51	            .ReadFrom.Configuration(context.Configuration)
52	            .ReadFrom.Services(services)
53	            .Enrich.FromLogContext()
54	            .Enrich.WithMachineName()
55	            .Enrich.WithThreadId()
56	            .Enrich.WithProperty("Application", "SoulPilates.API")
57	            .Enrich.WithProperty("Environment", context.HostingEnvironment.EnvironmentName);
58	    });
59	
60	    // Sentry SDK — points at our self-hosted GlitchTip when SentrySettings:Dsn is
61	    // populated; no-ops silently when empty (i.e. local dev with no DSN).
62	    // GlitchTip is Sentry-wire-compatible so the Sentry .NET SDK is the right client.
63	    builder.WebHost.UseSentry(o =>
64	    {
65	        o.Dsn = builder.Configuration["SentrySettings:Dsn"];
66	        o.Environment = builder.Environment.EnvironmentName;
67	        o.Release = typeof(Program).Assembly.GetName().Version?.ToString();
68	        o.MaxBreadcrumbs = builder.Configuration.GetValue<int?>("SentrySettings:MaxBreadcrumbs") ?? 50;
69	        o.SendDefaultPii = false;
70	        o.TracesSampleRate = builder.Configuration.GetValue<double?>("SentrySettings:TracesSampleRate") ?? 0;
71	        o.AttachStacktrace = true;
72	        o.SetBeforeSend(SentryScrubber.BeforeSend);
73	    });
