83	    builder.Services.Configure<MongoDbSettings>(
84	        builder.Configuration.GetSection("MongoDbSettings"));
85	
86	    builder.Services.AddSingleton<MongoDbContext>();
87	    builder.Services.AddScoped<IAuthService, AuthService>();
88	    builder.Services.AddScoped<IProductService, ProductService>();
89	    builder.Services.AddScoped<IClientService, ClientService>();
90	    builder.Services.AddScoped<IMerchandiseSkuService, MerchandiseSkuService>();
91	    builder.Services.AddScoped<IStockReceiptService, StockReceiptService>();
92	    builder.Services.AddScoped<IInvoiceService, InvoiceService>();
