99	    // StaffService — both take IStaffRateRevisionService in their constructor.
100	    builder.Services.AddScoped<IStaffRateRevisionService, StaffRateRevisionService>();
101	    builder.Services.AddScoped<IPayrollService, PayrollService>();
102	    builder.Services.AddScoped<IAccountingService, AccountingService>();
103	    builder.Services.AddScoped<IFundPoolService, FundPoolService>();
104	    builder.Services.AddScoped<IAnalyticsService, AnalyticsService>();
105	    builder.Services.AddScoped<IStaffService, StaffService>();
106	    builder.Services.AddScoped<IStudioRentalService, StudioRentalService>();
107	    builder.Services.AddScoped<IReceptionistKpiService, ReceptionistKpiService>();
108	    builder.Services.AddScoped<IPartnerService, PartnerService>();
109	    builder.Services.AddScoped<IVoucherService, VoucherService>();
110	    builder.Services.AddScoped<IPromotionService, PromotionService>();
111	    builder.Services.AddScoped<IEmailService, EmailService>();
112	    builder.Services.AddScoped<ICustomerAuthService, CustomerAuthService>();
113	    builder.Services.AddScoped<IPaymentService, PaymentService>();
114	    builder.Services.AddSingleton<IMediaStorage, MediaStorageService>();
115	    builder.Services.AddSingleton<IDocumentRenderer, QuestPdfDocumentRenderer>();
116	    builder.Services.AddScoped<ISettingsService, SettingsService>();
117	    builder.Services.AddScoped<IOwnerService, OwnerService>();
118	    builder.Services.AddScoped<IOwnerLoanService, OwnerLoanService>();
119	    builder.Services.AddScoped<IReminderService, ReminderService>();
120	    builder.Services.AddScoped<IRetentionReminderService, RetentionReminderService>();
121	    builder.Services.AddScoped<IInstructorService, InstructorService>();
122	    builder.Services.AddScoped<IEquipmentService, EquipmentService>();
123	    // P4-S04 — Audit log infrastructure. IHttpContextAccessor lets the logger
124	    // resolve the calling actor / IP from the ambient HTTP request.
125	    builder.Services.AddHttpContextAccessor();
126	    builder.Services.AddScoped<IAuditLogger, AuditLogger>();
127	    builder.Services.AddScoped<IAuditLogService, AuditLogService>();
128	    builder.Services.AddHostedService<PackageExpiryBackgroundService>();
129	    builder.Services.AddHostedService<BookingReminderBackgroundService>();
130	    builder.Services.AddHostedService<RetentionReminderBackgroundService>();
131	    builder.Services.AddHostedService<ScheduleMaterialiserBackgroundService>();
132	    builder.Services.AddHostedService<ReservationCleanupBackgroundService>();
133	    builder.Services.AddHostedService<SoulPilates.API.HostedServices.UserStaffLinker>();
134	    builder.Services.AddHostedService<SoulPilates.API.HostedServices.OwnerSeederHostedService>();
135	
136	    // ── PWA Web Push (P5-PWA) ────────────────────────────────────────
137	    //
138	    // The Channel decouples "a controller wants to send a push" from "the
139	    // HTTP call to FCM/APNs has happened". Singleton so producers + the
140	    // single-consumer PushDispatcherService share one queue.
141	    builder.Services.Configure<WebPushSettings>(
142	        builder.Configuration.GetSection("WebPush"));
143	    builder.Services.AddSingleton(_ => Channel.CreateUnbounded<PushJob>(
144	        new UnboundedChannelOptions { SingleReader = true, SingleWriter = false }));
145	    builder.Services.AddScoped<IPushService, PushService>();
146	    builder.Services.AddScoped<INotificationRuleService, NotificationRuleService>();
147	    builder.Services.AddScoped<INotificationPublisher, NotificationPublisher>();
148	    builder.Services.AddHostedService<PushDispatcherService>();
149	    builder.Services.AddHostedService<ClassReminderJob>();
150	    builder.Services.AddHostedService<SoulPilates.API.HostedServices.NotificationSeederHostedService>();
151	    builder.Services.AddHostedService<UpdateCheckerService>();
152	    builder.Services.AddHostedService<SessionCompletionBackgroundService>();
153	
154	    // ── Stripe configuration is now database-managed ──────────────────────
155	    // Stripe keys (publishable, secret, webhook secret) and the enabled
156	    // toggle are stored AES-256 encrypted in GlobalSettings and managed
157	    // via the admin dashboard (Settings → Payments → Stripe Configuration).
158	    // PaymentService reads them on-demand via ISettingsService. No
159	    // IOptions<StripeSettings> or appsettings binding is needed.
160	
161	    builder.Services.Configure<StorageSettings>(
162	        builder.Configuration.GetSection("StorageSettings"));
163	
164	    // Configure Admin Seed
165	    builder.Services.Configure<AdminSeedSettings>(
166	        builder.Configuration.GetSection("AdminSeed"));
167	    builder.Services.AddHostedService<AdminSeederHostedService>();
168	
169	    // ─────────────────────────────────────────────────────────────────────
170	    // JWT Authentication (P4-S12 — with optional key rotation).
171	    //
172	    // The token validator accepts EITHER the current `JwtSettings:Secret`
173	    // OR (when set) `JwtSettings:PreviousSecret`. New tokens issued by
174	    // AuthService / CustomerAuthService are still signed with the current
175	    // `Secret` only. Rotation procedure (deploy/RUNBOOK.md §15):
176	    //   1. Copy current `JWT_SECRET` to `JWT_PREVIOUS_SECRET` in prod.env.
177	    //   2. Generate a fresh `JWT_SECRET`.
178	    //   3. `docker compose restart backend` — the new container signs new
179	    //      JWTs with the fresh key; existing JWTs (signed with the old key)
180	    //      continue to validate via PreviousSecret until they expire (2h).
181	    //   4. After the 2h grace window, the operator may clear
182	    //      `JWT_PREVIOUS_SECRET` to fully retire the old key.
183	    // ─────────────────────────────────────────────────────────────────────
184	    var jwtSecret = builder.Configuration["JwtSettings:Secret"] ?? throw new InvalidOperationException("JwtSettings:Secret is not configured.");
185	    var jwtPreviousSecret = builder.Configuration["JwtSettings:PreviousSecret"];
186	    var jwtSigningKeys = new List<SecurityKey>
187	    {
188	        new SymmetricSecurityKey(Encoding.ASCII.GetBytes(jwtSecret))
189	    };
190	    if (!string.IsNullOrWhiteSpace(jwtPreviousSecret))
191	    {
192	        jwtSigningKeys.Add(new SymmetricSecurityKey(Encoding.ASCII.GetBytes(jwtPreviousSecret)));
193	    }
194	
195	    builder.Services.AddAuthentication(x =>
196	    {
197	        x.DefaultAuthenticateScheme = JwtBearerDefaults.AuthenticationScheme;
198	        x.DefaultChallengeScheme = JwtBearerDefaults.AuthenticationScheme;
199	    })
200	    .AddJwtBearer(x =>
201	    {
202	        x.RequireHttpsMetadata = false;
203	        x.SaveToken = true;
204	        x.TokenValidationParameters = new TokenValidationParameters
205	        {
206	            ValidateIssuerSigningKey = true,
207	            // IssuerSigningKeys (collection) lets the validator try multiple
208	            // keys — supports the rotation window without breaking existing
209	            // sessions. See remarks above.
210	            IssuerSigningKeys = jwtSigningKeys,
211	            ValidateIssuer = false,
212	            ValidateAudience = false
213	        };
214	    });
215	
216	    // ─────────────────────────────────────────────────────────────────────
217	    // Rate limiting (P4-S12 — protects auth-adjacent endpoints).
218	    //
219	    // Two named policies attached via [EnableRateLimiting("…")] on the auth
220	    // controllers:
221	    //
222	    //   • "auth-login"   — fixed-window per-IP, 10 req / 60s. Applied to
223	    //                       /api/auth/login, /api/customer/login,
224	    //                       /api/customer/verify-email.
225	    //   • "auth-register"— fixed-window per-IP, 5 req / 60s. Applied to
226	    //                       /api/customer/register.
227	    //
228	    // Partition key uses the resolved client IP — ForwardedHeaders middleware
229	    // (configured in a prior phase) ensures we see the real upstream IP.
230	    // OnRejected returns RFC-7807 ProblemDetails with retryAfter; status 429.
231	    // ─────────────────────────────────────────────────────────────────────
232	    builder.Services.AddRateLimiter(options =>
233	    {
234	        options.AddPolicy("auth-login", httpContext => RateLimitPartition.GetFixedWindowLimiter(
235	            partitionKey: ResolveClientIp(httpContext),
236	            factory: _ => new FixedWindowRateLimiterOptions
237	            {
238	                PermitLimit = 10,
239	                Window = TimeSpan.FromSeconds(60),
240	                QueueProcessingOrder = QueueProcessingOrder.OldestFirst,
241	                QueueLimit = 0,
242	                AutoReplenishment = true,
243	            }));
244	
245	        options.AddPolicy("auth-register", httpContext => RateLimitPartition.GetFixedWindowLimiter(
246	            partitionKey: ResolveClientIp(httpContext),
247	            factory: _ => new FixedWindowRateLimiterOptions
248	            {
249	                PermitLimit = 5,
250	                Window = TimeSpan.FromSeconds(60),
251	                QueueProcessingOrder = QueueProcessingOrder.OldestFirst,
252	                QueueLimit = 0,
253	                AutoReplenishment = true,
254	            }));
255	
256	        options.OnRejected = async (context, cancellationToken) =>
257	        {
258	            // 429 + ProblemDetails. Log at Warning so the event lands in
259	            // GlitchTip breadcrumbs but doesn't escalate to an Issue —
260	            // rate-limit hits are expected pushback, not anomalies.
261	            var retryAfter = context.Lease.TryGetMetadata(MetadataName.RetryAfter, out var retryAfterValue)
262	                ? (int)retryAfterValue.TotalSeconds
263	                : 60;
264	
265	            context.HttpContext.Response.StatusCode = StatusCodes.Status429TooManyRequests;
266	            context.HttpContext.Response.Headers.RetryAfter = retryAfter.ToString();
267	            context.HttpContext.Response.ContentType = "application/problem+json";
268	
269	            var problem = new
270	            {
271	                type = "https://soulpilates.com.vn/errors/rate-limited",
272	                title = "Too many requests.",
273	                status = StatusCodes.Status429TooManyRequests,
274	                detail = $"Too many requests. Try again in {retryAfter} second(s).",
275	                retryAfter,
276	                code = "RATE_LIMIT.EXCEEDED",
277	            };
278	
279	            Log.Warning("Rate-limit hit on {Path} from {ClientIp}; retryAfter={RetryAfter}s",
280	                context.HttpContext.Request.Path,
281	                ResolveClientIp(context.HttpContext),
282	                retryAfter);
283	
284	            await context.HttpContext.Response.WriteAsync(
285	                System.Text.Json.JsonSerializer.Serialize(problem),
286	                cancellationToken);
287	        };
288	    });
289	
290	    var app = builder.Build();
291	
292	    // Last-resort exception handler BEFORE authentication so even auth-stage
293	    // crashes are captured as RFC-7807 ProblemDetails responses rather than
294	    // raw 500s with stack traces. Pairs with the SentryScrubber on the way out.
295	    app.UseMiddleware<UnhandledExceptionMiddleware>();
296	
297	    // One structured log line per HTTP request — replaces the ASP.NET default
298	    // multi-line request log. Includes method, path, status, elapsed ms.
299	    app.UseSerilogRequestLogging(opts =>
300	    {
301	        opts.GetLevel = (httpContext, elapsed, ex) =>
302	            ex != null ? LogEventLevel.Error
303	            : httpContext.Response.StatusCode >= 500 ? LogEventLevel.Error
304	            : httpContext.Response.StatusCode >= 400 ? LogEventLevel.Warning
305	            : LogEventLevel.Information;
306	    });
307	
308	    if (app.Environment.IsDevelopment())
309	    {
310	        app.UseSwagger();
311	        app.UseSwaggerUI();
312	    }
313	
314	    app.UseCors(SoulPilatesCorsExtensions.PolicyName);
315	    app.UseAuthentication();
316	
317	    // Rate limiter sits AFTER auth so future per-user partitioning can read
318	    // the authenticated identity. For the anonymous auth-login / auth-register
319	    // policies it doesn't matter (they use client IP); but consistency wins.
320	    app.UseRateLimiter();
321	
322	    // Correlation enricher runs AFTER UseAuthentication so the authenticated
323	    // UserId is known by the time we push it onto LogContext.
324	    app.UseMiddleware<CorrelationEnricherMiddleware>();
325	
326	    app.UseAuthorization();
327	    app.MapControllers();
328	
329	    Log.Information("SoulPilates.API starting in {Environment} environment", app.Environment.EnvironmentName);
330	
331	    // Pre-flight infrastructure dependency validation.
332	    await UpdateCheckerService.ValidateEnvironmentAsync();
333	
334	    app.Run();
335	}
336	catch (Exception ex) when (ex is not HostAbortedException)
337	{
338	    Log.Fatal(ex, "SoulPilates.API terminated unexpectedly");
339	    throw;
340	}
341	finally
342	{
343	    Log.CloseAndFlush();
344	}
345	
346	/// <summary>
347	/// Resolve the upstream client IP for rate-limit partitioning. Reads from
348	/// <c>Connection.RemoteIpAddress</c>, which the ForwardedHeaders middleware
349	/// (configured upstream of <c>UseRateLimiter</c>) has already populated with
350	/// the real client IP from the reverse proxy. Falls back to a sentinel
351	/// <c>"unknown"</c> partition if neither is available, ensuring even oddly-
352	/// addressed callers share a single bucket (worst case: collective limit).
353	/// </summary>
354	static string ResolveClientIp(HttpContext context)
355	{
356	    var ip = context.Connection.RemoteIpAddress?.ToString();
357	    return string.IsNullOrWhiteSpace(ip) ? "unknown" : ip;
358	}
