using Microsoft.AspNetCore.Authentication.JwtBearer;
using SoulPilates.API.Extensions;
using Microsoft.IdentityModel.Tokens;
using System.Text;
using System.Threading.Channels;
using SoulPilates.Core.Configuration;
using SoulPilates.Core.Interfaces;
using SoulPilates.Infrastructure.Data;
using SoulPilates.Services;
using Serilog;
using Serilog.Events;
using Serilog.Sinks.SystemConsole.Themes;
using SoulPilates.API.Middleware;
using SoulPilates.API.Observability;
using Microsoft.AspNetCore.RateLimiting;
using System.Threading.RateLimiting;

// ────────────────────────────────────────────────────────────────────────────
// Serilog bootstrap (P4-S10 — observability stack).
//
// We build the logger BEFORE the host so we capture startup failures
// (e.g. mongo connection refused on boot, mis-configured JWT secret) in the
// same file/console sink as steady-state requests. Without this, those errors
// would only land in the default Microsoft.Extensions.Logging console writer
// and disappear on container restart.
//
// The full per-environment configuration is read from appsettings.json /
// appsettings.Production.json — this bootstrap config is just enough to keep
// us alive between Main() and UseSerilog().
// ────────────────────────────────────────────────────────────────────────────
Log.Logger = new LoggerConfiguration()
    .MinimumLevel.Information()
    .MinimumLevel.Override("Microsoft.AspNetCore", LogEventLevel.Warning)
    .Enrich.FromLogContext()
    .Enrich.WithMachineName()
    .Enrich.WithThreadId()
    .Enrich.WithProperty("Application", "SoulPilates.API")
    .WriteTo.Console(theme: AnsiConsoleTheme.Code)
    .CreateBootstrapLogger();

try
{
    var builder = WebApplication.CreateBuilder(args);

    // Replace the host logger with Serilog. The full pipeline (including the
    // production file sink + per-environment overrides) is read from
    // configuration — see appsettings.json :: "Serilog".
    builder.Host.UseSerilog((context, services, configuration) =>
    {
        configuration
            .ReadFrom.Configuration(context.Configuration)
            .ReadFrom.Services(services)
            .Enrich.FromLogContext()
            .Enrich.WithMachineName()
            .Enrich.WithThreadId()
            .Enrich.WithProperty("Application", "SoulPilates.API")
            .Enrich.WithProperty("Environment", context.HostingEnvironment.EnvironmentName);
    });

    // Sentry SDK — points at our self-hosted GlitchTip when SentrySettings:Dsn is
    // populated; no-ops silently when empty (i.e. local dev with no DSN).
    // GlitchTip is Sentry-wire-compatible so the Sentry .NET SDK is the right client.
    builder.WebHost.UseSentry(o =>
    {
        o.Dsn = builder.Configuration["SentrySettings:Dsn"];
        o.Environment = builder.Environment.EnvironmentName;
        o.Release = typeof(Program).Assembly.GetName().Version?.ToString();
        o.MaxBreadcrumbs = builder.Configuration.GetValue<int?>("SentrySettings:MaxBreadcrumbs") ?? 50;
        o.SendDefaultPii = false;
        o.TracesSampleRate = builder.Configuration.GetValue<double?>("SentrySettings:TracesSampleRate") ?? 0;
        o.AttachStacktrace = true;
        o.SetBeforeSend(SentryScrubber.BeforeSend);
    });

    // Add services to the container.
    builder.Services.AddControllers();
    builder.Services.AddEndpointsApiExplorer();
    builder.Services.AddSwaggerGen();

    builder.Services.AddSoulPilatesCors(builder.Configuration, builder.Environment);

    // Configure MongoDB Setup
    builder.Services.Configure<MongoDbSettings>(
        builder.Configuration.GetSection("MongoDbSettings"));

    builder.Services.AddSingleton<MongoDbContext>();
    builder.Services.AddScoped<IAuthService, AuthService>();
    builder.Services.AddScoped<IProductService, ProductService>();
    builder.Services.AddScoped<IClientService, ClientService>();
    builder.Services.AddScoped<IMerchandiseSkuService, MerchandiseSkuService>();
    builder.Services.AddScoped<IStockReceiptService, StockReceiptService>();
    builder.Services.AddScoped<IInvoiceService, InvoiceService>();
    builder.Services.AddScoped<IWalletService, WalletService>();
    // P4-S02 — Waitlist must be registered before SchedulingService and CustomerAuthService
    // (both depend on it for capacity-overflow handling and cancel auto-promotion).
    builder.Services.AddScoped<IWaitlistService, WaitlistService>();
    builder.Services.AddScoped<ISchedulingService, SchedulingService>();
    // Rate-revision ledger must be registered BEFORE PayrollService and
    // StaffService — both take IStaffRateRevisionService in their constructor.
    builder.Services.AddScoped<IStaffRateRevisionService, StaffRateRevisionService>();
    builder.Services.AddScoped<IPayrollService, PayrollService>();
    builder.Services.AddScoped<IAccountingService, AccountingService>();
    builder.Services.AddScoped<IFundPoolService, FundPoolService>();
    builder.Services.AddScoped<IAnalyticsService, AnalyticsService>();
    builder.Services.AddScoped<IStaffService, StaffService>();
    builder.Services.AddScoped<IStudioRentalService, StudioRentalService>();
    builder.Services.AddScoped<IReceptionistKpiService, ReceptionistKpiService>();
    builder.Services.AddScoped<IPartnerService, PartnerService>();
    builder.Services.AddScoped<IVoucherService, VoucherService>();
    builder.Services.AddScoped<IPromotionService, PromotionService>();
    builder.Services.AddScoped<IEmailService, EmailService>();
    builder.Services.AddScoped<ICustomerAuthService, CustomerAuthService>();
    builder.Services.AddScoped<IPaymentService, PaymentService>();
    builder.Services.AddSingleton<IMediaStorage, MediaStorageService>();
    builder.Services.AddSingleton<IDocumentRenderer, QuestPdfDocumentRenderer>();
    builder.Services.AddScoped<ISettingsService, SettingsService>();
    builder.Services.AddScoped<IOwnerService, OwnerService>();
    builder.Services.AddScoped<IOwnerLoanService, OwnerLoanService>();
    builder.Services.AddScoped<IReminderService, ReminderService>();
    builder.Services.AddScoped<IRetentionReminderService, RetentionReminderService>();
    builder.Services.AddScoped<IInstructorService, InstructorService>();
    builder.Services.AddScoped<IEquipmentService, EquipmentService>();
    // P4-S04 — Audit log infrastructure. IHttpContextAccessor lets the logger
    // resolve the calling actor / IP from the ambient HTTP request.
    builder.Services.AddHttpContextAccessor();
    builder.Services.AddScoped<IAuditLogger, AuditLogger>();
    builder.Services.AddScoped<IAuditLogService, AuditLogService>();
    builder.Services.AddHostedService<PackageExpiryBackgroundService>();
    builder.Services.AddHostedService<BookingReminderBackgroundService>();
    builder.Services.AddHostedService<RetentionReminderBackgroundService>();
    builder.Services.AddHostedService<ScheduleMaterialiserBackgroundService>();
    builder.Services.AddHostedService<ReservationCleanupBackgroundService>();
    builder.Services.AddHostedService<SoulPilates.API.HostedServices.UserStaffLinker>();
    builder.Services.AddHostedService<SoulPilates.API.HostedServices.OwnerSeederHostedService>();

    // ── PWA Web Push (P5-PWA) ────────────────────────────────────────
    //
    // The Channel decouples "a controller wants to send a push" from "the
    // HTTP call to FCM/APNs has happened". Singleton so producers + the
    // single-consumer PushDispatcherService share one queue.
    builder.Services.Configure<WebPushSettings>(
        builder.Configuration.GetSection("WebPush"));
    builder.Services.AddSingleton(_ => Channel.CreateUnbounded<PushJob>(
        new UnboundedChannelOptions { SingleReader = true, SingleWriter = false }));
    builder.Services.AddScoped<IPushService, PushService>();
    builder.Services.AddScoped<INotificationRuleService, NotificationRuleService>();
    builder.Services.AddScoped<INotificationPublisher, NotificationPublisher>();
    builder.Services.AddHostedService<PushDispatcherService>();
    builder.Services.AddHostedService<ClassReminderJob>();
    builder.Services.AddHostedService<SoulPilates.API.HostedServices.NotificationSeederHostedService>();
    builder.Services.AddHostedService<UpdateCheckerService>();
    builder.Services.AddHostedService<SessionCompletionBackgroundService>();

    // ── Stripe configuration is now database-managed ──────────────────────
    // Stripe keys (publishable, secret, webhook secret) and the enabled
    // toggle are stored AES-256 encrypted in GlobalSettings and managed
    // via the admin dashboard (Settings → Payments → Stripe Configuration).
    // PaymentService reads them on-demand via ISettingsService. No
    // IOptions<StripeSettings> or appsettings binding is needed.

    builder.Services.Configure<StorageSettings>(
        builder.Configuration.GetSection("StorageSettings"));

    // Configure Admin Seed
    builder.Services.Configure<AdminSeedSettings>(
        builder.Configuration.GetSection("AdminSeed"));
    builder.Services.AddHostedService<AdminSeederHostedService>();

    // ─────────────────────────────────────────────────────────────────────
    // JWT Authentication (P4-S12 — with optional key rotation).
    //
    // The token validator accepts EITHER the current `JwtSettings:Secret`
    // OR (when set) `JwtSettings:PreviousSecret`. New tokens issued by
    // AuthService / CustomerAuthService are still signed with the current
    // `Secret` only. Rotation procedure (deploy/RUNBOOK.md §15):
    //   1. Copy current `JWT_SECRET` to `JWT_PREVIOUS_SECRET` in prod.env.
    //   2. Generate a fresh `JWT_SECRET`.
    //   3. `docker compose restart backend` — the new container signs new
    //      JWTs with the fresh key; existing JWTs (signed with the old key)
    //      continue to validate via PreviousSecret until they expire (2h).
    //   4. After the 2h grace window, the operator may clear
    //      `JWT_PREVIOUS_SECRET` to fully retire the old key.
    // ─────────────────────────────────────────────────────────────────────
    var jwtSecret = builder.Configuration["JwtSettings:Secret"] ?? throw new InvalidOperationException("JwtSettings:Secret is not configured.");
    var jwtPreviousSecret = builder.Configuration["JwtSettings:PreviousSecret"];
    var jwtSigningKeys = new List<SecurityKey>
    {
        new SymmetricSecurityKey(Encoding.ASCII.GetBytes(jwtSecret))
    };
    if (!string.IsNullOrWhiteSpace(jwtPreviousSecret))
    {
        jwtSigningKeys.Add(new SymmetricSecurityKey(Encoding.ASCII.GetBytes(jwtPreviousSecret)));
    }

    builder.Services.AddAuthentication(x =>
    {
        x.DefaultAuthenticateScheme = JwtBearerDefaults.AuthenticationScheme;
        x.DefaultChallengeScheme = JwtBearerDefaults.AuthenticationScheme;
    })
    .AddJwtBearer(x =>
    {
        x.RequireHttpsMetadata = false;
        x.SaveToken = true;
        x.TokenValidationParameters = new TokenValidationParameters
        {
            ValidateIssuerSigningKey = true,
            // IssuerSigningKeys (collection) lets the validator try multiple
            // keys — supports the rotation window without breaking existing
            // sessions. See remarks above.
            IssuerSigningKeys = jwtSigningKeys,
            ValidateIssuer = false,
            ValidateAudience = false
        };
    });

    // ─────────────────────────────────────────────────────────────────────
    // Rate limiting (P4-S12 — protects auth-adjacent endpoints).
    //
    // Two named policies attached via [EnableRateLimiting("…")] on the auth
    // controllers:
    //
    //   • "auth-login"   — fixed-window per-IP, 10 req / 60s. Applied to
    //                       /api/auth/login, /api/customer/login,
    //                       /api/customer/verify-email.
    //   • "auth-register"— fixed-window per-IP, 5 req / 60s. Applied to
    //                       /api/customer/register.
    //
    // Partition key uses the resolved client IP — ForwardedHeaders middleware
    // (configured in a prior phase) ensures we see the real upstream IP.
    // OnRejected returns RFC-7807 ProblemDetails with retryAfter; status 429.
    // ─────────────────────────────────────────────────────────────────────
    builder.Services.AddRateLimiter(options =>
    {
        options.AddPolicy("auth-login", httpContext => RateLimitPartition.GetFixedWindowLimiter(
            partitionKey: ResolveClientIp(httpContext),
            factory: _ => new FixedWindowRateLimiterOptions
            {
                PermitLimit = 10,
                Window = TimeSpan.FromSeconds(60),
                QueueProcessingOrder = QueueProcessingOrder.OldestFirst,
                QueueLimit = 0,
                AutoReplenishment = true,
            }));

        options.AddPolicy("auth-register", httpContext => RateLimitPartition.GetFixedWindowLimiter(
            partitionKey: ResolveClientIp(httpContext),
            factory: _ => new FixedWindowRateLimiterOptions
            {
                PermitLimit = 5,
                Window = TimeSpan.FromSeconds(60),
                QueueProcessingOrder = QueueProcessingOrder.OldestFirst,
                QueueLimit = 0,
                AutoReplenishment = true,
            }));

        options.OnRejected = async (context, cancellationToken) =>
        {
            // 429 + ProblemDetails. Log at Warning so the event lands in
            // GlitchTip breadcrumbs but doesn't escalate to an Issue —
            // rate-limit hits are expected pushback, not anomalies.
            var retryAfter = context.Lease.TryGetMetadata(MetadataName.RetryAfter, out var retryAfterValue)
                ? (int)retryAfterValue.TotalSeconds
                : 60;

            context.HttpContext.Response.StatusCode = StatusCodes.Status429TooManyRequests;
            context.HttpContext.Response.Headers.RetryAfter = retryAfter.ToString();
            context.HttpContext.Response.ContentType = "application/problem+json";

            var problem = new
            {
                type = "https://soulpilates.com.vn/errors/rate-limited",
                title = "Too many requests.",
                status = StatusCodes.Status429TooManyRequests,
                detail = $"Too many requests. Try again in {retryAfter} second(s).",
                retryAfter,
                code = "RATE_LIMIT.EXCEEDED",
            };

            Log.Warning("Rate-limit hit on {Path} from {ClientIp}; retryAfter={RetryAfter}s",
                context.HttpContext.Request.Path,
                ResolveClientIp(context.HttpContext),
                retryAfter);

            await context.HttpContext.Response.WriteAsync(
                System.Text.Json.JsonSerializer.Serialize(problem),
                cancellationToken);
        };
    });

    var app = builder.Build();

    // Last-resort exception handler BEFORE authentication so even auth-stage
    // crashes are captured as RFC-7807 ProblemDetails responses rather than
    // raw 500s with stack traces. Pairs with the SentryScrubber on the way out.
    app.UseMiddleware<UnhandledExceptionMiddleware>();

    // One structured log line per HTTP request — replaces the ASP.NET default
    // multi-line request log. Includes method, path, status, elapsed ms.
    app.UseSerilogRequestLogging(opts =>
    {
        opts.GetLevel = (httpContext, elapsed, ex) =>
            ex != null ? LogEventLevel.Error
            : httpContext.Response.StatusCode >= 500 ? LogEventLevel.Error
            : httpContext.Response.StatusCode >= 400 ? LogEventLevel.Warning
            : LogEventLevel.Information;
    });

    if (app.Environment.IsDevelopment())
    {
        app.UseSwagger();
        app.UseSwaggerUI();
    }

    app.UseCors(SoulPilatesCorsExtensions.PolicyName);
    app.UseAuthentication();

    // Rate limiter sits AFTER auth so future per-user partitioning can read
    // the authenticated identity. For the anonymous auth-login / auth-register
    // policies it doesn't matter (they use client IP); but consistency wins.
    app.UseRateLimiter();

    // Correlation enricher runs AFTER UseAuthentication so the authenticated
    // UserId is known by the time we push it onto LogContext.
    app.UseMiddleware<CorrelationEnricherMiddleware>();

    app.UseAuthorization();
    app.MapControllers();

    Log.Information("SoulPilates.API starting in {Environment} environment", app.Environment.EnvironmentName);

    // Pre-flight infrastructure dependency validation.
    await UpdateCheckerService.ValidateEnvironmentAsync();

    app.Run();
}
catch (Exception ex) when (ex is not HostAbortedException)
{
    Log.Fatal(ex, "SoulPilates.API terminated unexpectedly");
    throw;
}
finally
{
    Log.CloseAndFlush();
}

/// <summary>
/// Resolve the upstream client IP for rate-limit partitioning. Reads from
/// <c>Connection.RemoteIpAddress</c>, which the ForwardedHeaders middleware
/// (configured upstream of <c>UseRateLimiter</c>) has already populated with
/// the real client IP from the reverse proxy. Falls back to a sentinel
/// <c>"unknown"</c> partition if neither is available, ensuring even oddly-
/// addressed callers share a single bucket (worst case: collective limit).
/// </summary>
static string ResolveClientIp(HttpContext context)
{
    var ip = context.Connection.RemoteIpAddress?.ToString();
    return string.IsNullOrWhiteSpace(ip) ? "unknown" : ip;
}

