using SoulPilates.Core.Entities;

namespace SoulPilates.Core.Entities;

/// <summary>
/// One row per <c>(Invoice, Partner)</c> when an invoice tagged with a
/// <c>RefereePartnerId</c> reaches PAID status and at least one eligible line
/// produced a non-zero commission. Persisted at payment time so the audit
/// trail links the source invoice → the partner who got paid.
///
/// <para>
/// The Year/Month is captured from the invoice's <c>IssueDate</c>, which is
/// the same key the monthly washout aggregates on. <c>(InvoiceId, PartnerId)</c>
/// is unique — re-firing payment on the same invoice replaces, never duplicates.
/// </para>
///
/// <para>
/// <b>Snapshot block.</b> <see cref="PartnerNameSnapshot"/> and
/// <see cref="TiersSnapshot"/> capture the partner's display name + commission
/// ladder at the moment the payout was emitted. Combined with
/// <see cref="LineBreakdown"/>, the partner-statement view can render a fully
/// auditable per-line breakdown without re-joining <c>Partners</c> or
/// <c>Products</c> — and without risking that a later edit to either silently
/// changes a paid statement.
/// </para>
/// </summary>
public class RefereePayout : BaseEntity
{
    public string PartnerId { get; set; } = null!;
    public string InvoiceId { get; set; } = null!;

    /// <summary>Denormalised so the partner-payout drill-down doesn't have to re-join Invoices.</summary>
    public string InvoiceNumber { get; set; } = null!;

    public decimal Amount { get; set; }

    public int Year { get; set; }
    public int Month { get; set; }

    /// <summary>"PENDING" | "PAID" — mirrors <see cref="StaffPayable.PaidStatus"/>.</summary>
    public string PaidStatus { get; set; } = "PENDING";
    public DateTime? PaidAt { get; set; }

    // ── Snapshot block ──────────────────────────────────────────────────

    /// <summary>
    /// Partner's display name at emission time. Denormalised so a later rename
    /// can't reshape historical partner-statement headers.
    /// </summary>
    public string PartnerNameSnapshot { get; set; } = string.Empty;

    /// <summary>
    /// Commission ladder that produced <see cref="Amount"/>. Copied from
    /// <see cref="Partner.CommissionTiers"/> at emission. A later edit to the
    /// partner's tiers does NOT change historical payouts because this list is
    /// detached from the live <c>Partner</c> document.
    /// </summary>
    public List<PartnerCommissionTier> TiersSnapshot { get; set; } = new();

    /// <summary>
    /// Per-line breakdown that sums to <see cref="Amount"/>. Each entry records
    /// the line total, the resolved rate, and the contribution for one eligible
    /// invoice line — making the partner statement fully reconstructable.
    /// </summary>
    public List<RefereePayoutLine> LineBreakdown { get; set; } = new();
}

/// <summary>
/// One commission contribution from a single <see cref="InvoiceLine"/> on the
/// payout's source <see cref="Invoice"/>. Stamped at emission so the partner
/// statement is self-describing even if the underlying invoice/product is
/// later edited (which currently it cannot be, but the snapshot makes the
/// invariant explicit rather than implicit).
/// </summary>
public class RefereePayoutLine
{
    public string? ProductId { get; set; }
    public string ProductDescriptionSnapshot { get; set; } = string.Empty;
    public string? ProductTypeSnapshot { get; set; }
    public int Quantity { get; set; }
    public decimal LineTotal { get; set; }
    public decimal RateApplied { get; set; }
    public decimal Commission { get; set; }
}

