using MongoDB.Bson;
using MongoDB.Bson.Serialization.Attributes;

namespace SoulPilates.Core.Entities;

/// <summary>
/// Sidecar profile attached 1:1 to a <see cref="Staff"/> row whose <c>Role == "OWNER"</c>.
/// Owner-specific fields live here rather than on <c>Staff</c> directly to avoid
/// cluttering the generic staff entity that 95%+ of rows are.
///
/// <para>
/// Keyed by <see cref="StaffId"/> (unique). The companion <c>OwnerService</c>
/// keeps profiles in sync with their parent <c>Staff</c> rows: deactivating
/// an owner's <c>Staff.IsActive=false</c> does NOT auto-deactivate the profile —
/// admin must explicitly toggle <see cref="IsActiveOwner"/> because the equity
/// invariant is pool-wide and demands an intentional act.
/// </para>
/// </summary>
public class OwnerProfile : BaseEntity
{
    /// <summary>Linked <see cref="Staff"/> row id. Unique across the collection.</summary>
    [BsonRepresentation(BsonType.ObjectId)]
    public string StaffId { get; set; } = null!;

    /// <summary>
    /// Owner's share of the Owners pool. Sum across all <see cref="IsActiveOwner"/>=true
    /// rows must equal 100 (within 0.01) — enforced in <c>OwnerService.UpsertAsync</c>.
    /// </summary>
    public decimal EquitySharePercentage { get; set; }

    /// <summary>
    /// True if Stripe payouts route to this owner's bank. Exactly one active owner
    /// may have this set to true at any time when <c>GlobalSettings.StripeRoutingMode</c>
    /// is <c>OWNER_ROUTED</c> (validated in P2-S08).
    /// </summary>
    public bool ReceivesStripePayouts { get; set; }

    /// <summary>
    /// Active owners participate in the equity-sum-to-100 invariant. Inactive
    /// owners are kept for historical record but excluded from washout splits.
    /// </summary>
    public bool IsActiveOwner { get; set; } = true;

    /// <summary>Free-text note (e.g. "co-founder, runs ops").</summary>
    public string Note { get; set; } = string.Empty;
}
