using MongoDB.Bson;
using MongoDB.Bson.Serialization.Attributes;
using System.Collections.Generic;

namespace SoulPilates.Core.Entities;

public class Staff : BaseEntity
{
    public string Name { get; set; } = null!;
    public string Role { get; set; } = "INSTRUCTOR"; // "INSTRUCTOR", "MANAGER", "RECEPTIONIST", "FREELANCE", "OWNER" (P2-S02)
    public string? Phone { get; set; }
    public string? Email { get; set; }

    // Commission structure
    public string CommissionModel { get; set; } = "PERCENTAGE_TIERED"; // "PERCENTAGE_TIERED", "FIXED_HEADCOUNT", "FIXED_SALARY", "REVENUE_SPLIT"

    /// <summary>
    /// Tier ladder used for <b>private-class commission</b> (per the studio's spreadsheet,
    /// only privates are tiered; group classes pay flat). The percentage of the rung
    /// matching the month's private-class count is applied to private revenue.
    /// Empty list → fall back to <see cref="FlatPrivateCommissionPct"/>.
    /// </summary>
    public List<CommissionTier> Tiers { get; set; } = new();

    /// <summary>
    /// Per-class flat fee paid for each group class taught. Mirrors the sheet's
    /// "Free group class rate" column — distinct from <see cref="FreeGroupClassRate"/>
    /// (used elsewhere as a benefit) by intent: this one is the payable rate.
    /// </summary>
    public decimal GroupFlatRatePerClass { get; set; } = 0;

    /// <summary>
    /// Additional VND-per-head paid on top of <see cref="GroupFlatRatePerClass"/>.
    /// Lets a popular class earn more than an empty one, matching the sheet.
    /// </summary>
    public decimal GroupRatePerHead { get; set; } = 0;

    /// <summary>
    /// True (default) → use <see cref="Tiers"/> for private-class commission.
    /// False → every private class earns <see cref="FlatPrivateCommissionPct"/>.
    /// Per-staff flag because the studio mixes models across instructors.
    /// </summary>
    public bool HasTieredPrivateCommission { get; set; } = true;

    /// <summary>
    /// Fallback private-class commission rate (e.g. <c>0.5m</c> for 50%) used when
    /// <see cref="HasTieredPrivateCommission"/> is false OR <see cref="Tiers"/> is empty.
    /// </summary>
    public decimal FlatPrivateCommissionPct { get; set; } = 0.5m;

    // Flat rate items
    public decimal FreeGroupClassRate { get; set; }   // e.g. 40,000 VND
    public decimal FreePrivateClassRate { get; set; } // e.g. 80,000 VND

    // Fixed per-head
    /// <summary>
    /// Legacy/shared single-rate per-student pay (VND). This is now treated as
    /// the group-class fallback and is also used for private classes when no
    /// private-specific fixed-headcount rates are configured.
    /// </summary>
    public decimal RatePerHead { get; set; }     // VND per student per class

    /// <summary>
    /// Per-student fixed-pay ladder for GROUP classes on the
    /// <c>FIXED_HEADCOUNT</c> commission model. Empty list → fall back to
    /// <see cref="RatePerHead"/> as a single open-ended tier.
    /// </summary>
    public List<HeadcountPayoutTier> HeadcountTiers { get; set; } = new();

    /// <summary>
    /// Optional private-class fixed per-student fallback. When zero and
    /// <see cref="PrivateHeadcountTiers"/> is empty, private classes fall back
    /// to the group/shared <see cref="RatePerHead"/> setting.
    /// </summary>
    public decimal PrivateRatePerHead { get; set; }

    /// <summary>
    /// Optional private-class fixed-pay ladder for the
    /// <c>FIXED_HEADCOUNT</c> commission model. Empty list → fall back to
    /// <see cref="PrivateRatePerHead"/>, then to the legacy/shared
    /// <see cref="HeadcountTiers"/> ladder.
    /// </summary>
    public List<HeadcountPayoutTier> PrivateHeadcountTiers { get; set; } = new();

    /// <summary>
    /// True (default) → walk the ladder marginally (income-tax-bracket style):
    /// each student paid at the rate of the rung their position falls into.
    /// False → the whole class pays one rate — whichever rung the total
    /// student count lands in.
    /// </summary>
    public bool UseMarginalHeadcountTiers { get; set; } = true;

    // Fixed salary / Revenue split
    public decimal BaseSalary { get; set; }      // Permanent monthly base
    public decimal BaseRate { get; set; }        // Flat amount or Revenue split %

    // Bank details for payroll
    public string? BankName { get; set; }
    public string? BankAccountNumber { get; set; }

    public bool IsActive { get; set; } = true;

    // ── Customer Booking Portal — Instructor Profile ──
    public string? Bio { get; set; }                             // Short biography (set by admin or instructor)
    public string? PhotoUrl { get; set; }                        // Profile photo (uploaded by admin or instructor user)
    public int YearsExperience { get; set; }                     // Experience years
    public List<string> Specialties { get; set; } = new();       // e.g. ["Posture", "Rehabilitation"]

    // Link to User for auth (optional — staff can exist without a login)
    [BsonRepresentation(BsonType.ObjectId)]
    public string? UserId { get; set; }

    [BsonRepresentation(BsonType.ObjectId)]
    public string? StudioRentalClientId { get; set; }
}
