namespace SoulPilates.Core.Entities;

/// <summary>
/// Per-user notification overrides, embedded as a sub-document on
/// <see cref="User"/>. Sparse by design — only categories the user has
/// explicitly toggled appear in <see cref="CategoryOverrides"/>; missing
/// keys defer to the admin matrix's <c>IsEnabled</c> default.
///
/// <para>Stored as a nullable property: <c>null</c> means "user has never
/// touched their notification settings" and the publisher treats that as
/// "all defaults from the matrix".</para>
/// </summary>
public class NotificationPreferences
{
    /// <summary>Master switch. False = no notifications at all, regardless
    /// of category, role rule, or per-category override. Maps to the big
    /// "Pause notifications" toggle at the top of the profile modal.</summary>
    public bool Enabled { get; set; } = true;

    /// <summary>Master email opt-in. False = push only; missed pushes drop
