using MongoDB.Bson;
using MongoDB.Bson.Serialization.Attributes;

namespace SoulPilates.Core.Entities;

public class GlobalSettings : BaseEntity
{
    /// <summary>
    /// Marketing fund's share of net revenue (P&L washout). Combined with
    /// <see cref="SavingsSplitPercentage"/> and <see cref="OwnersSplitPercentage"/>
    /// this triple MUST sum to exactly 100 (within 0.01); the service-layer
    /// validation in <c>SettingsService.UpdateAsync</c> rejects anything else.
    /// Default 5/10/85 mirrors the studio's historical sheet.
    /// </summary>
    public decimal MarketingSplitPercentage { get; set; } = 5;

    /// <summary>Savings reserve's share. See <see cref="MarketingSplitPercentage"/>.</summary>
    public decimal SavingsSplitPercentage { get; set; } = 10;

    /// <summary>
    /// Owners' pool share. Default 85; together with marketing (5) + savings (10)
    /// = 100. The pool is then split per owner via <c>OwnerProfile.EquitySharePercentage</c>
    /// (introduced in P2-S02).
    /// </summary>
    public decimal OwnersSplitPercentage { get; set; } = 85;

    /// <summary>
    /// Hours before a GROUP class start that a customer can still self-cancel
    /// for a free credit refund. Below this threshold the cancellation is
    /// recorded as <c>LATE_CANCEL</c> and the credit is forfeited.
    /// (P1-S13 — was previously hardcoded to 12; kept the per-format split
    /// because group vs private classes have different operational impact.)
    /// </summary>
    public int CancelWindowHoursGroup { get; set; } = 12;

    /// <summary>
    /// Hours before a PRIVATE class start that a customer can still self-cancel
    /// for a free credit refund. Default 24 (matches SOW §22 Q8 mitigation
    /// for private sessions, which are higher-cost to operate).
    /// </summary>
    public int CancelWindowHoursPrivate { get; set; } = 24;

    // ── Per-Payment-Method Cancel Windows ────────────────────────────────────────
    // Supersedes the legacy CancelWindowHoursGroup/Private pair with granular
    // per-payment-tier windows. Each tier determines how many hours before class
    // the customer can cancel without penalty for that payment method.
    // 0 = never refundable (always treated as late-cancel). Default 3h for all.

    /// <summary>Package credit — GROUP classes: hours before start for free cancel. Default 3.</summary>
    public int CancelWindowHoursCreditGroup { get; set; } = 3;
    /// <summary>Package credit — PRIVATE classes: hours before start for free cancel. Default 3.</summary>
    public int CancelWindowHoursCreditPrivate { get; set; } = 3;
    /// <summary>Online Stripe payment — GROUP classes: hours before start for refund eligibility. Default 3.</summary>
    public int CancelWindowHoursOnlineGroup { get; set; } = 3;
    /// <summary>Online Stripe payment — PRIVATE classes: hours before start for refund eligibility. Default 3.</summary>
    public int CancelWindowHoursOnlinePrivate { get; set; } = 3;
    /// <summary>Pay-at-studio — GROUP classes: hours before start for free cancel. Default 3.</summary>
    public int CancelWindowHoursStudioGroup { get; set; } = 3;
    /// <summary>Pay-at-studio — PRIVATE classes: hours before start for free cancel. Default 3.</summary>
    public int CancelWindowHoursStudioPrivate { get; set; } = 3;

    // ── Late Reschedule Grace ────────────────────────────────────────────────────
    // Allows a customer within the late-cancel window to move their booking to
    // another session instead of losing their credit/payment. Configurable limit,
    // tracking mode (per account or per booking), and eligible payment methods.

    /// <summary>Master switch — allow late reschedule instead of cancel. Default true.</summary>
    public bool EnableLateReschedule { get; set; } = true;

    /// <summary>Maximum number of late reschedules allowed within the tracking period. Default 1.</summary>
    public int LateRescheduleMaxPerMonth { get; set; } = 1;

    /// <summary>
    /// Tracking mode: <c>"ACCOUNT"</c> = limit is per-customer-account per month;
    /// <c>"BOOKING"</c> = each booking can be rescheduled once (lifetime, not monthly).
    /// Default "ACCOUNT".
    /// </summary>
    public string LateRescheduleMode { get; set; } = "ACCOUNT";

    /// <summary>
    /// Payment methods eligible for late reschedule. Default: credit + online.
    /// Values match <see cref="Attendance.PaymentMethod"/>: "PACKAGE_CREDIT", "STRIPE_DEPOSIT", "STRIPE_FULL", "PAY_AT_STUDIO".
    /// </summary>
    public List<string> LateRescheduleEligibleMethods { get; set; } = new() { "PACKAGE_CREDIT", "STRIPE_DEPOSIT", "STRIPE_FULL" };

    /// <summary>
    /// Editable list of expense categories shown in the expense form's dropdown.
    /// Seeded on first read with the studio's historical sheet labels (see
    /// <see cref="DefaultExpenseCategories"/>). Empty list means "uninitialised";
    /// the service backfills with the defaults rather than letting the dropdown be empty.
    /// </summary>
    public List<string> ExpenseCategories { get; set; } = new();

    /// <summary>
    /// How Stripe processing fees are absorbed at washout time. <c>COMPANY_ACCOUNT</c>
    /// (default) keeps fees inside <c>TotalFixedExpenses</c>, no <c>StripeDeduction</c>
    /// is routed. <c>OWNER_ROUTED</c> un-deducts the fees from FixedExpenses (so the
    /// owners' pool is computed against gross), then deducts the full sum from the
    /// chosen owner's distribution — matches the studio's spreadsheet semantics where
    /// one owner absorbs the fee out of their share. (P2-S08.)
    /// </summary>
    public string StripeRoutingMode { get; set; } = StripeRoutingModes.CompanyAccount;

    // ── Issue 2: Online Payment Surcharge ────────────────────────────────────────

    /// <summary>
    /// Percentage surcharge added on top of online (Stripe) payments to recover
    /// processing costs. Applied only to STRIPE_DEPOSIT and STRIPE_FULL.
    /// 0 = disabled (fees absorbed internally). Default 0.
    /// </summary>
    public decimal OnlinePaymentFeePercentage { get; set; } = 0m;

    public decimal StudioRentalGroupPerHeadFee { get; set; } = 0m;
    public decimal StudioRentalPrivatePerHeadFee { get; set; } = 0m;
    public decimal StudioRentalGroupPackagePrice { get; set; } = 0m;
    public int StudioRentalGroupPackageCredits { get; set; } = 0;
    public decimal StudioRentalPrivatePackagePrice { get; set; } = 0m;
    public int StudioRentalPrivatePackageCredits { get; set; } = 0;
    public bool EnableReceptionistKpiProgram { get; set; } = false;
    public decimal ReceptionistKpiBonusPoolAmount { get; set; } = 5_000_000m;
    public decimal ReceptionistDailyTaskCompletionPercent { get; set; } = 1m;
    public decimal ReceptionistAttendanceCommissionPerHead { get; set; } = 0m;
    public string ReceptionistAttendanceSplitMode { get; set; } = "EQUAL_ACTIVE";
    public List<ReceptionistDailyTaskDefinition> ReceptionistDailyTasks { get; set; } = new()
    {
        new() { Name = "Water plants" },
        new() { Name = "Post a story" },
        new() { Name = "Post a reel" },
        new() { Name = "Clean the machines" },
        new() { Name = "Sweep the floors" },
    };
    public List<ReceptionistKpiTier> ReceptionistRevenueTiers { get; set; } = new()
    {
        new() { Label = "Tier 1", Goal = 100_000_000m, RewardPercent = 10m },
        new() { Label = "Tier 2", Goal = 150_000_000m, RewardPercent = 10m },
        new() { Label = "Tier 3", Goal = 200_000_000m, RewardPercent = 10m },
    };
    public List<ReceptionistKpiTier> ReceptionistPackageSalesTiers { get; set; } = new()
    {
        new() { Label = "Tier 1", Goal = 10m, RewardPercent = 10m },
        new() { Label = "Tier 2", Goal = 15m, RewardPercent = 10m },
        new() { Label = "Tier 3", Goal = 20m, RewardPercent = 10m },
    };
    public List<ReceptionistKpiTier> ReceptionistGoogleReviewTiers { get; set; } = new()
    {
        new() { Label = "Tier 1", Goal = 20m, RewardPercent = 5m },
        new() { Label = "Tier 2", Goal = 30m, RewardPercent = 5m },
        new() { Label = "Tier 3", Goal = 40m, RewardPercent = 5m },
    };

    // ── Issue 3: Checkout Payment Method Controls ────────────────────────────────

    /// <summary>Whether Stripe online payments (full + deposit) are offered at checkout. Default true.</summary>
    public List<RoleAccessSetting> RoleAccessSettings { get; set; } = new();

    public bool AllowOnlinePayment { get; set; } = true;

    /// <summary>Whether the partial deposit option is shown (only relevant when AllowOnlinePayment=true). Default true.</summary>
    public bool AllowPartialPayment { get; set; } = true;

    /// <summary>Whether the Pay at Studio option is shown at checkout. Default true.</summary>
    public bool AllowPayAtStudio { get; set; } = true;

    /// <summary>
    /// Deposit percentage charged upfront for partial payments (0–100).
    /// This is the admin-UI source of truth; replaces the appsettings StripeSettings.DepositPercentage.
    /// Default 30.
    /// </summary>
    public int DepositPercentage { get; set; } = 30;

    /// <summary>
    /// Custom display label for the partial payment option shown to customers — English.
    /// Empty string = fall back to the built-in i18n key "Guarantee Your Spot".
    /// </summary>
    public string PartialPaymentLabelEn { get; set; } = "";

    /// <summary>
    /// Custom display label for the partial payment option shown to customers — Vietnamese.
    /// Empty string = fall back to the built-in i18n key "Đảm Bảo Chỗ".
    /// </summary>
    public string PartialPaymentLabelVi { get; set; } = "";

    // ── Issue 2: Checkout Package Upsell ─────────────────────────────────────────
    // Surfaces a "buy a package instead" card on the class-checkout page when a
    // matching package would save the customer money over the drop-in price. All
    // thresholds are admin-tunable so the studio can A/B without code changes.

    /// <summary>Master switch — show the upsell card on class checkout. Default true.</summary>
    public bool EnableCheckoutPackageUpsell { get; set; } = true;

    /// <summary>Minimum % saving per class vs. the drop-in price to surface a package as an upsell. 0 = always show. Default 0.</summary>
    public int UpsellMinSavingsPercentage { get; set; } = 0;

    /// <summary>Cap on how many upsell options the checkout card lists. Default 1 (single best deal).</summary>
    public int UpsellMaxOptionsShown { get; set; } = 1;

    /// <summary>
    /// Restrict the upsell to specific session formats. Empty list = all formats eligible.
    /// Values mirror <see cref="CalendarSession.Format"/> (e.g. "GROUP", "PRIVATE").
    /// </summary>
    public List<string> UpsellEligibleFormats { get; set; } = new();

    /// <summary>
    /// Hide the upsell when the customer already owns any active package (any format).
    /// Default true — the upsell is meant for new / lapsed customers, not active credit holders.
    /// </summary>
    public bool UpsellHideForActivePackageHolders { get; set; } = true;

    /// <summary>Custom headline copy shown in the upsell card. Empty string = use the i18n default. English.</summary>
    public string UpsellHeadlineEn { get; set; } = "";

    /// <summary>Custom headline copy shown in the upsell card. Empty string = use the i18n default. Vietnamese.</summary>
    public string UpsellHeadlineVi { get; set; } = "";

    // ── Per-format pinned upsell package IDs ──────────────────────────────────────
    // Admin explicitly selects which package to show per session format.
    // Empty string = upsell disabled for that format.

    /// <summary>Pinned product ID shown as the upsell suggestion for GROUP sessions. Empty = no upsell for GROUP.</summary>
    public string UpsellPackageIdGroup { get; set; } = "";

    /// <summary>Pinned product ID shown as the upsell suggestion for PRIVATE sessions. Empty = no upsell for PRIVATE.</summary>
    public string UpsellPackageIdPrivate { get; set; } = "";

    /// <summary>Pinned product ID shown as the upsell suggestion for MIXED/DUO sessions. Empty = no upsell for MIXED.</summary>
    public string UpsellPackageIdMixed { get; set; } = "";

    // ── Issue 5: Retention Check-In Reminders ────────────────────────────────────
    // Nudges customers with unused credits to come back. Background-driven via
    // RetentionReminderBackgroundService; idempotency lives on
    // ClientPackage.RetentionRemindersSent.

    /// <summary>Master switch — fire retention reminder emails on each tick. Default true.</summary>
    public bool EnableRetentionReminders { get; set; } = true;

    /// <summary>Days since a customer's last CHECKED_IN attendance before they're considered fading. Default 14.</summary>
    public int RetentionReminderInactivityDays { get; set; } = 14;

    /// <summary>
    /// Ordered list of window tags. Each tag fires at most once per <see cref="ClientPackage"/>
    /// via the same idempotent $push pattern as <see cref="Attendance.RemindersSent"/>.
    /// Defaults to two nudges: 14 days inactive, then again at 30.
    /// </summary>
    public List<string> RetentionReminderWindows { get; set; } = new() { "14d", "30d" };

    /// <summary>Background-job cadence in hours (1–48). Default 12 — matches PackageExpiryBackgroundService.</summary>
    public int RetentionReminderTickHours { get; set; } = 12;

    /// <summary>Only nudge packages with at least this many credits remaining. 0 = no floor. Default 1.</summary>
    public int RetentionReminderMinCreditsRemaining { get; set; } = 1;

    // ── P4-S02: Waitlist System Toggle ────────────────────────────────────────

    /// <summary>
    /// Master switch — enable or disable the class waitlist system globally.
    /// When false: JoinWaitlist rejects new entries, TryPromoteNextAsync is skipped,
    /// and the "Join Waitlist" CTA is hidden on the customer booking page.
    /// Default true (waitlist active from day 1).
    /// </summary>
    public bool EnableWaitlistSystem { get; set; } = true;

    // ── Customer Sign-Up Email Verification ───────────────────────────────────

    /// <summary>
    /// Whether new customer sign-ups require email verification before they can log in.
    /// <c>true</c> = accounts start unverified; a verification email is dispatched; login is blocked
    /// until the customer clicks the link.
    /// <c>false</c> = accounts are auto-verified at registration; immediate login allowed.
    /// Managed exclusively via the admin dashboard (Settings → Operations tab).
    /// Default false (immediate login allowed).
    /// </summary>
    public bool? EnableSignUpEmailVerification { get; set; } = false;

    // ── P5-S01: Reservation System Controls ──────────────────────────────
    // Governs the checkout-reservation flow. When a customer arrives at the
    // checkout page, the system creates a RESERVED attendance that temporarily
    // holds their spot. These settings control deduplication, expiry timing,
    // and whether the system is active at all.

    /// <summary>
    /// Master switch — enable or disable the checkout reservation (spot hold)
    /// system globally. When false, the checkout flow still creates an
    /// attendance but skips the reservation dedup and expiry logic; the
    /// attendance is created fresh each time (legacy behaviour).
    /// Default true (reservation hold active).
    /// </summary>
    public bool EnableReservationSystem { get; set; } = true;

    /// <summary>
    /// Minutes after which an uncompleted RESERVED attendance is automatically
    /// cancelled by the <c>ReservationCleanupBackgroundService</c> and the
    /// capacity slot is freed. Default 15 minutes.
    /// </summary>
    public int ReservationExpiryMinutes { get; set; } = 15;

    /// <summary>
    /// How often (in minutes) the cleanup background job checks for expired
    /// reservations. Default 2 minutes for snappy slot recovery.
    /// </summary>
    public int ReservationCleanupIntervalMinutes { get; set; } = 2;

    // ── Guest Checkout Toggle ──────────────────────────────────────────────────

    /// <summary>
    /// Allow unauthenticated (guest) customers to complete class bookings at
    /// checkout without registering or logging in. When <c>false</c> (default),
    /// the checkout page redirects any visitor who is not logged in to
    /// <c>/login</c> so that every booking, reservation, and package purchase
    /// is tied to a registered <see cref="CustomerAccount"/>. Enable only if
    /// the studio wants to accept walk-in-style anonymous bookings.
    /// Default false — account required from day one.
    /// </summary>
    public bool AllowGuestCheckout { get; set; } = false;

    // ── Google Analytics Integration ──────────────────────────────────────────
    // Configurable from the admin Settings page. The Measurement ID is injected
    // into the customer-facing layout's <head> so the gtag.js snippet fires on
    // every page view. Event tracking covers the full customer funnel:
    // Homepage → Booking → Checkout → Payment.

    /// <summary>
    /// Google Analytics 4 Measurement ID (e.g. "G-XXXXXXXXXX"). Empty/null
    /// disables the gtag.js snippet entirely — no scripts loaded, no events
    /// sent. Configurable from Admin → Settings → Integrations tab.
    /// </summary>
    public string GoogleAnalyticsMeasurementId { get; set; } = "";

    /// <summary>
    /// Master switch for customer-journey event tracking. When true AND
    /// <see cref="GoogleAnalyticsMeasurementId"/> is non-empty, the customer
    /// layout emits granular gtag events (page_view, view_class, begin_checkout,
    /// purchase, etc.). When false, only the basic page_view fires.
    /// Default true — studios want the full funnel out of the box.
    /// </summary>
    public bool EnableGoogleAnalyticsEventTracking { get; set; } = true;

    // ── Stripe Payment Gateway Configuration ───────────────────────────────────
    // Moved from appsettings.json to admin dashboard (database-backed) so keys
    // can be rotated at runtime without a server restart. All key fields are
    // stored AES-256-CBC encrypted via SettingsEncryptionHelper; the GET endpoint
    // returns only masked values (first 4 + last 4 chars). Currency is always VND.

    /// <summary>
    /// Master switch — enable or disable Stripe payment processing.
    /// When false: online payment options are hidden from checkout, webhook
    /// returns 503, and no Stripe API calls are made.
    /// Default false (payments disabled until keys are configured).
    /// </summary>
    public bool StripeEnabled { get; set; } = false;

    /// <summary>
    /// Stripe Publishable Key — stored AES-256 encrypted.
    /// Used client-side by Stripe.js Elements (safe to expose to browsers,
    /// but we encrypt at rest anyway for consistency). Display masked only.
    /// </summary>
    public string? StripePublishableKeyEncrypted { get; set; } = "";

    /// <summary>
    /// Stripe Secret Key — stored AES-256 encrypted.
    /// Used server-side for PaymentIntent creation. NEVER exposed via API.
    /// </summary>
    public string? StripeSecretKeyEncrypted { get; set; } = "";

    /// <summary>
    /// Stripe Webhook Signing Secret — stored AES-256 encrypted.
    /// Used server-side for webhook signature verification. NEVER exposed via API.
    /// </summary>
    public string? StripeWebhookSecretEncrypted { get; set; } = "";

    // ── V2 Schedule: Company Operating Hours, Holidays, Overrides ─────────────
    // Embedded sub-document that constrains every downstream calendar view,
    // materialiser tick, and blueprint slot validation.

    /// <summary>
    /// Studio operating hours, holidays, and date-specific overrides.
    /// All calendar grids only show rows within open hours. The materialiser
    /// skips holidays and validates slot times against the configured windows.
    /// Null-safe: defaults to an empty config (no hours defined) until admin sets it up.
    /// </summary>
    public CompanyScheduleConfig CompanySchedule { get; set; } = new();

    // ── V2: Materialisation Horizon ──────────────────────────────────────────
    // Controls how many days into the future the background materialiser and
    // the on-save materialisation project sessions. Replaces the previously
    // hardcoded 30-day constant in ScheduleMaterialiserBackgroundService and
    // ClassBlueprintController.

    /// <summary>
    /// Number of days into the future that class sessions are materialised
    /// from blueprints. The background service and the blueprint save/update
    /// pipelines both read this value. Default 30 days.
    /// Min 7, Max 365.
    /// </summary>
    public int MaterialisationHorizonDays { get; set; } = 30;

    // ── SPM-76: Editable Email Templates ──────────────────────────────────────
    // Admin-editable subject + body for each transactional email. When empty (a
    // fresh row, or a template the admin has never touched), EmailService falls
    // back to the hardcoded built-in default so emails can never break. Seeded /
    // backfilled by SettingsService from EmailTemplateDefaults.All().

    /// <summary>
    /// Per-template overrides for the studio's transactional emails. Each entry's
    /// <see cref="EmailTemplate.Id"/> matches a key in <see cref="EmailTemplateIds"/>.
    /// A blank Subject/BodyHtml on any entry means "use the built-in default" — the
    /// service resolves that fallback at send-time, so a half-edited or missing
    /// template is always safe. Backfilled with <see cref="EmailTemplateDefaults"/>
    /// on read when empty.
    /// </summary>
    public List<EmailTemplate> EmailTemplates { get; set; } = new();

    /// <summary>
    /// Default seed list. Mirrors the categories observed in the Google Sheets workbook
    /// per SOW §12.1 so existing receptionist mental model carries over unchanged.
    /// Order matters — this is the dropdown order on first launch.
    /// </summary>
    public static IReadOnlyList<string> DefaultExpenseCategories { get; } = new[]
    {
        "Software Subscriptions",
        "Domain & Hosting Renewals",
        "Branding & Signage",
        "Cleaning & Maintenance",
        "Marketing & Advertising",
        "Supplies",
        "Equipment Purchase",
        "Renovation & Interior Setup",
        "Payment Processing Fees",
        "Management Salary",
        "Staff Salaries",
        "Utilities",
        "Website & Booking System Development",
        "Rent",
        "Other",
    };
}

/// <summary>String constants for <see cref="GlobalSettings.StripeRoutingMode"/>.</summary>
public static class StripeRoutingModes
{
    /// <summary>Default mode — fees stay folded into FixedExpenses, no per-owner deduction.</summary>
    public const string CompanyAccount = "COMPANY_ACCOUNT";

    /// <summary>Routes Stripe fees to the active owner with <c>ReceivesStripePayouts=true</c>.</summary>
    public const string OwnerRouted = "OWNER_ROUTED";

    /// <summary>The expense category whose monthly sum is used as the Stripe-fee total when routing.</summary>
    public const string FeeExpenseCategory = "Payment Processing Fees";
}

