namespace SoulPilates.Core.Entities;

public class User : BaseEntity
{
    public string Name { get; set; } = null!;
    public string Email { get; set; } = null!;
    public string PasswordHash { get; set; } = null!;

    public string Role { get; set; } = null!; // e.g., "Admin", "Instructor"

    /// <summary>
    /// P3-S09 — link from the login identity to the operational
    /// <see cref="Staff"/> row this user represents. Null for Admin
    /// and Owner roles (no Staff entry), and for instructor users
    /// that <see cref="SoulPilates.API.HostedServices.UserStaffLinker"/>
    /// could not unambiguously resolve at startup. The
    /// <c>InstructorController</c> reads this from the JWT and
    /// gracefully degrades to a "profile setup pending" banner when
    /// unresolved.
    /// </summary>
    [BsonRepresentation(BsonType.ObjectId)]
    public string? StaffId { get; set; }

    public decimal? BaseSalary { get; set; }
    public decimal? FixedCommissionRate { get; set; }
    public bool TieredCommissionStatus { get; set; }

    /// <summary>
    /// P5-PWA — per-user notification overrides. Null for users who have
    /// never touched their notification settings; the publisher treats
    /// null as "all defaults from the matrix".
    /// </summary>
    public NotificationPreferences? NotificationPreferences { get; set; }
}
