using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.RateLimiting;
using SoulPilates.Core.DTOs;
using SoulPilates.Core.Interfaces;
using System.Threading.Tasks;

namespace SoulPilates.API.Controllers;

[ApiController]
[Route("api/[controller]")]
public class AuthController : ControllerBase
{
    private readonly IAuthService _authService;

    public AuthController(IAuthService authService)
    {
        _authService = authService;
    }

    [HttpPost("login")]
    [EnableRateLimiting("auth-login")] // P4-S12: 10 req / 60s per IP — protects against credential stuffing.
    public async Task<IActionResult> Login([FromBody] LoginRequest request)
    {
        var result = await _authService.AuthenticateAsync(request);
        if (result == null) return Unauthorized(new { message = "Invalid email or password" });

        return Ok(result);
    }
}
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Interfaces;
using System.Threading.Tasks;

namespace SoulPilates.API.Controllers;

[ApiController]
[Route("api/[controller]")]
[Authorize(Roles = "Admin")]
public class StaffController : ControllerBase
{
    private readonly IStaffService _staffService;
    private readonly IStaffRateRevisionService _revisions;

    public StaffController(IStaffService staffService, IStaffRateRevisionService revisions)
    {
        _staffService = staffService;
        _revisions = revisions;
    }

    [HttpGet]
    public async Task<IActionResult> GetAll()
    {
        var staff = await _staffService.GetAllStaffAsync();
        return Ok(staff);
    }

    [HttpGet("{id}")]
    public async Task<IActionResult> GetById(string id)
    {
        var staff = await _staffService.GetStaffByIdAsync(id);
        if (staff == null) return NotFound();
        return Ok(staff);
    }

    [HttpPost]
    public async Task<IActionResult> Create([FromBody] Staff staff)
    {
        var created = await _staffService.CreateStaffAsync(staff);
        return Ok(created);
    }

    [HttpPut("{id}")]
    public async Task<IActionResult> Update(string id, [FromBody] Staff staff)
    {
        await _staffService.UpdateStaffAsync(id, staff);
        return Ok();
    }

    [HttpPut("{id}/status")]
    public async Task<IActionResult> UpdateStatus(string id, [FromBody] UpdateStaffStatusRequest request)
    {
        await _staffService.UpdateActiveStatusAsync(id, request.IsActive);
        return Ok(new { isActive = request.IsActive });
    }

    // ─── P3-S09b — Login management ──────────────────────────────

    /// <summary>P3-S09b — read login status for the staff-form's "Login access" section.</summary>
    [HttpGet("{id}/login")]
    public async Task<IActionResult> GetLogin(string id)
    {
        var status = await _staffService.GetLoginStatusAsync(id);
        return Ok(status);
    }

    /// <summary>P3-S09b — create a new instructor user + link in one step.</summary>
    [HttpPost("{id}/login")]
    public async Task<IActionResult> CreateLogin(string id, [FromBody] SoulPilates.Core.DTOs.CreateStaffLoginRequest request)
    {
        var result = await _staffService.CreateLoginAsync(id, request);
        if (result is null)
        {
            // Ambiguous failure surface — staff doesn't exist, email
            // is taken, or input was blank. The frontend reads the
            // controller's preceding GET response and shows the
            // appropriate hint, so a generic 400 here is sufficient.
            return BadRequest(new
            {
                message = "Could not create login. The email may already be in use, or the staff member no longer exists.",
            });
        }
        return Ok(result);
    }

    /// <summary>P3-S09b — link an existing orphan instructor user to this staff.</summary>
    [HttpPut("{id}/login")]
    public async Task<IActionResult> LinkLogin(string id, [FromBody] SoulPilates.Core.DTOs.LinkStaffLoginRequest request)
    {
        var result = await _staffService.LinkExistingUserAsync(id, request);
        if (result is null)
        {
            return BadRequest(new
            {
                message = "No unlinked instructor user with that email was found. The user may already be linked to another staff member.",
            });
        }
        return Ok(result);
    }

    /// <summary>P3-S09b — unlink the user currently attached to this staff.</summary>
    [HttpDelete("{id}/login")]
    public async Task<IActionResult> UnlinkLogin(string id)
    {
        var removed = await _staffService.UnlinkLoginAsync(id);
        if (!removed)
            return NotFound(new { message = "No linked user found for this staff member." });
        return Ok(new { message = "Login unlinked successfully." });
    }

    // ── Rate revision history ────────────────────────────────────────────

    /// <summary>List the full rate-revision audit log for a staff member (oldest first).</summary>
    [HttpGet("{id}/rate-revisions")]
    public async Task<IActionResult> ListRateRevisions(string id)
    {
        var rows = await _revisions.ListAsync(id);
        return Ok(rows);
    }

    // ── Monthly commission overrides ─────────────────────────────────────

    /// <summary>List all commission overrides for a staff member.</summary>
    [HttpGet("{id}/commission-overrides")]
    public async Task<IActionResult> ListCommissionOverrides(string id, CancellationToken ct)
    {
        var rows = await _staffService.ListCommissionOverridesAsync(id, ct);
        return Ok(rows);
    }

    /// <summary>Create or replace the commission override for a given Year/Month.</summary>
    [HttpPost("{id}/commission-overrides")]
    public async Task<IActionResult> UpsertCommissionOverride(
        string id,
        [FromBody] SoulPilates.Core.Entities.MonthlyCommissionOverride payload,
        CancellationToken ct)
    {
        payload.StaffId = id; // always trust the route param, not the body
        try
        {
            var saved = await _staffService.UpsertCommissionOverrideAsync(payload, ct);
            return Ok(saved);
        }
        catch (InvalidOperationException ex)
        {
            return BadRequest(new { message = ex.Message });
        }
    }

    /// <summary>Delete a commission override by its document id.</summary>
    [HttpDelete("{id}/commission-overrides/{overrideId}")]
    public async Task<IActionResult> DeleteCommissionOverride(string id, string overrideId, CancellationToken ct)
    {
        await _staffService.DeleteCommissionOverrideAsync(overrideId, ct);
        return NoContent();
    }
}

public class UpdateStaffStatusRequest
{
    public bool IsActive { get; set; }
}

