                u => u.Id == linkedUserId,
                Builders<User>.Update
                    .Set(u => u.StaffId, id)
                    .Set(u => u.Role, MapStaffRoleToUserRole(staff.Role))
                    .Set(u => u.Name, staff.Name));
        }

        if (existing is not null && _revisions.RateFieldsDiffer(existing, staff))
        {
            await _revisions.AppendRevisionAsync(staff, effectiveFrom: DateTime.UtcNow);
