    {
        var update = Builders<Staff>.Update
            .Set(s => s.PhotoUrl, photoUrl)
            .Set(s => s.UpdatedAt, DateTime.UtcNow);
        await _staff.UpdateOneAsync(s => s.Id == id, update);
    }

