    public async Task<List<MonthlyCommissionOverride>> ListCommissionOverridesAsync(
        string staffId, CancellationToken ct = default)
    {
        return await _commissionOverrides
            .Find(o => o.StaffId == staffId)
            .SortByDescending(o => o.Year)
            .ThenByDescending(o => o.Month)
            .ToListAsync(ct);
    }

    public async Task<MonthlyCommissionOverride> UpsertCommissionOverrideAsync(
        MonthlyCommissionOverride payload, CancellationToken ct = default)
    {
        if (payload.Month < 1 || payload.Month > 12)
            throw new InvalidOperationException("Month must be between 1 and 12.");
        if (payload.Year < 2000 || payload.Year > 2100)
            throw new InvalidOperationException("Year is out of range.");

        var staff = await _staff.Find(s => s.Id == payload.StaffId).FirstOrDefaultAsync(ct);
        if (staff is not null)
            payload.StaffNameSnapshot = staff.Name ?? string.Empty;

        var existing = await _commissionOverrides
            .Find(o => o.StaffId == payload.StaffId
                    && o.Year == payload.Year
                    && o.Month == payload.Month)
            .FirstOrDefaultAsync(ct);

        if (existing is null)
        {
            payload.Id = null;
            payload.CreatedAt = DateTime.UtcNow;
            payload.UpdatedAt = DateTime.UtcNow;
            await _commissionOverrides.InsertOneAsync(payload, cancellationToken: ct);
        }
        else
        {
            payload.Id = existing.Id;
            payload.CreatedAt = existing.CreatedAt;
            payload.UpdatedAt = DateTime.UtcNow;
            await _commissionOverrides.ReplaceOneAsync(
                o => o.Id == existing.Id, payload, cancellationToken: ct);
        }

        return payload;
    }

    public async Task DeleteCommissionOverrideAsync(string id, CancellationToken ct = default)
    {
        await _commissionOverrides.DeleteOneAsync(o => o.Id == id, ct);
    }

    private async Task EnsureStudioRentalClientAsync(Staff staff)
    {
