<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Sign in — Soul Pilates</title>
    <meta name="theme-color" content="#1A1410" />
    <link rel="preconnect" href="https://fonts.googleapis.com" />
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
    <link
      href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap"
      rel="stylesheet"
    />
    <link rel="icon" type="image/svg+xml" href="/favicon.svg" />
    <style is:global>
      *,
      *::before,
      *::after {
        box-sizing: border-box;
        margin: 0;
        padding: 0;
      }
      :root {
        --copper: #c97b4b;
        --copper-hover: #b06835;
        --warm-dark: #1a1410;
        --warm-darker: #14100c;
        --warm-card: #ffffff;
        --warm-text: #1a1a1a;
        --warm-muted: #9b9b9b;
        --warm-secondary: #5c5c5c;
        --warm-border: #e8e5e0;
      }
      html,
      body {
        height: 100%;
      }
      body {
        font-family:
          "Inter",
          -apple-system,
          BlinkMacSystemFont,
          "Segoe UI",
          sans-serif;
        background: var(--warm-dark);
        color: #f5f0e8;
        min-height: 100vh;
        display: flex;
        align-items: center;
        justify-content: center;
        -webkit-font-smoothing: antialiased;
        -moz-osx-font-smoothing: grayscale;
        position: relative;
        overflow-x: hidden;
        padding: 24px;
      }

      /* Copper radial-gradient bloom — same recipe as customer hero */
      body::before,
      body::after {
        content: "";
        position: absolute;
        pointer-events: none;
        border-radius: 50%;
        filter: blur(80px);
        z-index: 0;
      }
      body::before {
        width: 480px;
        height: 480px;
        background: radial-gradient(
          circle,
          rgba(201, 123, 75, 0.3) 0%,
          transparent 70%
        );
        top: -120px;
        left: -120px;
      }
      body::after {
        width: 540px;
        height: 540px;
        background: radial-gradient(
          circle,
          rgba(201, 123, 75, 0.18) 0%,
          transparent 70%
        );
        bottom: -180px;
        right: -180px;
      }

      /* Subtle decorative ring on the dark backdrop */
      .ornament-ring {
        position: absolute;
        width: 700px;
        height: 700px;
        border: 1px solid rgba(201, 123, 75, 0.06);
        border-radius: 50%;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
        pointer-events: none;
        z-index: 0;
      }
      .ornament-ring.inner {
        width: 460px;
        height: 460px;
        border-color: rgba(201, 123, 75, 0.08);
      }

      /* Card */
      .login-card {
        position: relative;
        z-index: 1;
        background: var(--warm-card);
        border-radius: 18px;
        padding: 44px 40px 36px;
        width: 100%;
        max-width: 420px;
        box-shadow:
          0 30px 70px rgba(0, 0, 0, 0.45),
          0 0 0 1px rgba(255, 255, 255, 0.04);
        animation: card-in 0.5s cubic-bezier(0.4, 0, 0.2, 1);
      }
      @keyframes card-in {
        from {
          opacity: 0;
          transform: translateY(12px);
        }
        to {
          opacity: 1;
          transform: translateY(0);
        }
      }

      /* Logo lockup */
      .logo-wrap {
        display: flex;
        align-items: center;
        gap: 12px;
        margin-bottom: 36px;
      }
      .logo-icon {
        width: 44px;
        height: 44px;
        background: linear-gradient(135deg, var(--copper), var(--copper-hover));
        border-radius: 12px;
        display: flex;
        align-items: center;
        justify-content: center;
        box-shadow: 0 4px 14px rgba(201, 123, 75, 0.4);
      }
      .logo-icon svg {
        width: 24px;
        height: 24px;
        color: white;
      }
      .logo-text {
        font-family: "Inter", sans-serif;
        font-size: 16px;
        font-weight: 600;
        color: var(--warm-text);
        letter-spacing: 0.5px;
        line-height: 1.2;
      }
      .logo-sub {
        font-size: 10px;
        color: var(--warm-muted);
        letter-spacing: 1.5px;
        text-transform: uppercase;
        font-weight: 500;
        margin-top: 3px;
      }

      /* Heading */
      h1 {
        font-family: 'Inter', -apple-system, sans-serif;
        font-size: 32px;
        font-weight: 700;
        color: var(--warm-text);
        letter-spacing: -0.8px;
        margin-bottom: 6px;
        line-height: 1.1;
      }
      .subtitle {
        font-size: 13.5px;
        color: var(--warm-muted);
        margin-bottom: 32px;
        line-height: 1.5;
      }

      /* Form */
      .form-group {
        margin-bottom: 18px;
      }
      .form-label {
        display: block;
        font-size: 12.5px;
        font-weight: 600;
        color: var(--warm-secondary);
        margin-bottom: 7px;
        letter-spacing: 0.1px;
      }
      .form-control {
        width: 100%;
        padding: 12px 14px;
        font-size: 14px;
        font-family: "Inter", sans-serif;
        background: #ffffff;
        border: 1.5px solid var(--warm-border);
        border-radius: 10px;
        color: var(--warm-text);
        outline: none;
        transition:
          border-color 0.15s ease,
          box-shadow 0.15s ease;
        min-height: 44px;
      }
      .form-control:focus {
        border-color: var(--copper);
        box-shadow: 0 0 0 3px rgba(201, 123, 75, 0.18);
      }
      .form-control::placeholder {
        color: #c0bbb3;
      }

      /* Button */
      .btn {
        display: flex;
        align-items: center;
        justify-content: center;
        gap: 8px;
        width: 100%;
        padding: 13px;
        border-radius: 10px;
        border: none;
        cursor: pointer;
        font-size: 14px;
        font-weight: 600;
        font-family: "Inter", sans-serif;
        background: var(--copper);
        color: white;
        transition: all 0.15s ease;
        margin-top: 10px;
        box-shadow: 0 2px 10px rgba(201, 123, 75, 0.3);
        letter-spacing: 0.2px;
      }
      .btn:hover:not(:disabled) {
        background: var(--copper-hover);
        transform: translateY(-1px);
        box-shadow: 0 4px 16px rgba(201, 123, 75, 0.4);
      }
      .btn:active {
        transform: translateY(0);
      }
      .btn:disabled {
        opacity: 0.7;
        cursor: wait;
      }
      .btn svg {
        width: 16px;
        height: 16px;
      }

      .error {
        background: rgba(196, 75, 75, 0.1);
        border: 1px solid rgba(196, 75, 75, 0.3);
        color: #b33a3a;
        border-radius: 10px;
        padding: 11px 14px;
        font-size: 13px;
        margin-bottom: 18px;
        display: none;
      }

      /* Decorative footer ornament */
      .footer-mark {
        margin-top: 28px;
        padding-top: 22px;
        border-top: 1px solid var(--warm-border);
        text-align: center;
        font-size: 11px;
        color: var(--warm-muted);
        letter-spacing: 1.5px;
        text-transform: uppercase;
        font-weight: 500;
      }

      @media (max-width: 480px) {
        .login-card {
          padding: 32px 24px 28px;
          border-radius: 14px;
        }
        h1 {
          font-size: 30px;
        }
      }
    </style>
  </head>
  <body>
    <div class="ornament-ring"></div>
    <div class="ornament-ring inner"></div>

    <main class="login-card" role="main">
      <div class="logo-wrap">
        <div class="logo-icon" aria-hidden="true">
          <img src="/logo.png" alt="Soul Pilates" style="width:28px;height:28px;object-fit:contain;" />
        </div>
        <div>
          <div class="logo-text">Soul Pilates</div>
          <div class="logo-sub">Management</div>
        </div>
      </div>

      <h1>Welcome back</h1>
      <p class="subtitle">Sign in to continue to your dashboard.</p>

      <div class="error" id="errorMsg" role="alert" aria-live="polite"></div>

      <form id="loginForm" novalidate>
        <div class="form-group">
          <label class="form-label" for="email">Email</label>
          <input
            type="email"
            class="form-control"
            id="email"
            placeholder="admin@soulpilates.com.vn"
            autocomplete="email"
            required
          />
        </div>
        <div class="form-group">
          <label class="form-label" for="password">Password</label>
          <input
            type="password"
            class="form-control"
            id="password"
            placeholder="••••••••"
            autocomplete="current-password"
            required
          />
        </div>

        <button class="btn" id="loginBtn" type="submit">
          <span id="btnLabel">Sign in</span>
          <svg
            xmlns="http://www.w3.org/2000/svg"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="2.5"
            aria-hidden="true"
            ><line x1="5" y1="12" x2="19" y2="12"></line><polyline
              points="12 5 19 12 12 19"></polyline></svg
          >
        </button>
      </form>

      <div class="footer-mark">Soul Pilates · Studio Management</div>
    </main>

    <script>
      // Role-aware auto-redirect for already-authenticated users.
      // P3-S09: instructor tokens now route to /instructor; everything
      // else (admin, owner, fallback) routes to /admin.
      (function () {
        var token = localStorage.getItem("token");
        if (!token) return;
        try {
          var payload = JSON.parse(atob(token.split(".")[1]));
          var role = (
            payload[
              "http://schemas.microsoft.com/ws/2008/06/identity/claims/role"
            ] ||
            payload.role ||
            ""
          ).toLowerCase();
          window.location.href =
            role === "instructor" ? "/instructor" : "/admin";
        } catch (e) {
          // Malformed token — clear it and stay on the login page.
          localStorage.removeItem("token");
        }
      })();

      async function doLogin(ev) {
        if (ev) ev.preventDefault();
        const email = document.getElementById("email").value.trim();
        const password = document.getElementById("password").value;
        const errEl = document.getElementById("errorMsg");
        const btn = document.getElementById("loginBtn");
        const lbl = document.getElementById("btnLabel");
        errEl.style.display = "none";
        lbl.textContent = "Signing in…";
        btn.disabled = true;

        try {
          const res = await fetch(
            import.meta.env.PUBLIC_API_URL + "/api/auth/login",
            {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({ email, password }),
            },
          );
          if (!res.ok) throw new Error();
          const data = await res.json();
          localStorage.setItem("token", data.token);
          if (data.staffId) localStorage.setItem("staffId", data.staffId);
          // P3-S09: role-aware post-login redirect.
          // Instructor → instructor portal; Admin, Receptionist, Accountant → admin dashboard
          const role = (data.userRole || "").toLowerCase();
          window.location.href =
            role === "instructor" ? "/instructor" : "/admin";
        } catch {
          errEl.textContent = "Invalid email or password. Please try again.";
          errEl.style.display = "block";
          lbl.textContent = "Sign in";
          btn.disabled = false;
        }
      }

      // Wire submit handler — required because Astro bundles this <script> as
      // an ES module, so `doLogin` is module-scoped and not accessible from an
      // inline `onsubmit=` attribute on the form.
      document.getElementById("loginForm").addEventListener("submit", doLogin);
    </script>
  </body>
</html>

