    if (string.IsNullOrWhiteSpace(request.Email) ||
        string.IsNullOrWhiteSpace(request.Password))
    {
        return null;
    }

    var email = request.Email.Trim().ToLowerInvariant();
    var existing = await _users.Find(u => u.Email == email).FirstOrDefaultAsync();
    if (existing is not null) return null;

    var newUser = new User
    {
        Name = staff.Name,
        Email = email,
        PasswordHash = PasswordHasher.Hash(request.Password),
        Role = MapStaffRoleToUserRole(staff.Role),
        StaffId = staffId,
    };
    await _users.InsertOneAsync(newUser);

    var staffUpdate = Builders<Staff>.Update.Set(s => s.UserId, newUser.Id);
    await _staff.UpdateOneAsync(s => s.Id == staffId, staffUpdate);

    return new StaffLoginDto
