          <div class="logo-text">Soul Pilates</div>
          <div class="logo-sub">Management</div>
        </div>
      </div>

      <h1>Set your password</h1>
      <p class="subtitle">Choose a new password to secure your account.</p>

      <div class="notice">
        Your account was created with a temporary password. Please set a new password before continuing.
      </div>

      <div class="error" id="errorMsg" role="alert" aria-live="polite"></div>

      <form id="changeForm" novalidate>
        <div class="form-group">
          <label class="form-label" for="newPassword">New password</label>
          <input
            type="password"
            class="form-control"
            id="newPassword"
            placeholder="At least 8 characters"
            autocomplete="new-password"
            required
            minlength="8"
          />
        </div>
        <div class="form-group">
          <label class="form-label" for="confirmPassword">Confirm new password</label>
          <input
            type="password"
            class="form-control"
            id="confirmPassword"
            placeholder="Repeat your new password"
            autocomplete="new-password"
            required
          />
        </div>

        <button class="btn" id="submitBtn" type="submit">
          <span id="btnLabel">Set password &amp; continue</span>
          <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24"
            fill="none" stroke="currentColor" stroke-width="2.5" aria-hidden="true">
