        if (!localStorage.getItem("token")) {
          window.location.href = "/admin/login";
        }
      })();

      const API = import.meta.env.PUBLIC_API_URL;

      async function doChange(ev) {
        ev.preventDefault();
        const newPw  = document.getElementById("newPassword").value;
        const confPw = document.getElementById("confirmPassword").value;
        const errEl  = document.getElementById("errorMsg");
        const btn    = document.getElementById("submitBtn");
        const lbl    = document.getElementById("btnLabel");

        errEl.style.display = "none";

        if (newPw.length < 8) {
          errEl.textContent = "Password must be at least 8 characters.";
          errEl.style.display = "block";
          return;
        }
        if (newPw !== confPw) {
          errEl.textContent = "Passwords do not match.";
          errEl.style.display = "block";
          return;
        }

        lbl.textContent = "Saving…";
        btn.disabled = true;

        try {
          const res = await fetch(API + "/api/auth/change-password", {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              Authorization: "Bearer " + localStorage.getItem("token"),
            },
            body: JSON.stringify({ newPassword: newPw, confirmPassword: confPw }),
          });

          if (!res.ok) {
            const body = await res.json().catch(() => ({}));
            throw new Error(body.message || "Something went wrong.");
          }

          // Password changed — redirect to dashboard (role already in token).
          const token = localStorage.getItem("token");
          let role = "";
          try {
            const payload = JSON.parse(atob(token.split(".")[1]));
            role = (
              payload["http://schemas.microsoft.com/ws/2008/06/identity/claims/role"] ||
              payload.role ||
              ""
            ).toLowerCase();
          } catch (_) {}

          window.location.href = role === "instructor" ? "/instructor" : "/admin";
        } catch (err) {
          errEl.textContent = err.message || "Could not update password. Please try again.";
          errEl.style.display = "block";
          lbl.textContent = "Set password & continue";
          btn.disabled = false;
        }
      }

      document.getElementById("changeForm").addEventListener("submit", doChange);
    </script>
  </body>
