178	
179	  const canViewStaff = role === 'admin' || role === 'accountant';
180	  const canViewOwners = role === 'admin';
181	  let activeTab = new URLSearchParams(window.location.search).get('tab') || 'staff';
182	  let owners = [];
183	  let editing = null;
184	
185	  function escapeHtml(s) {
186	    return String(s ?? '').replace(/[&<>"']/g, c => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;', "'":'&#39;' }[c]));
187	  }
188	
189	  function syncActions() {
190	    document.getElementById('addStaffBtn').style.display = activeTab === 'staff' && canViewStaff ? 'inline-flex' : 'none';
191	    document.getElementById('addOwnerBtn').style.display = activeTab === 'owners' && canViewOwners ? 'inline-flex' : 'none';
192	  }
193	
194	  function setTab(tab) {
195	    if (tab === 'owners' && !canViewOwners) tab = 'staff';
196	    if (tab === 'staff' && !canViewStaff && canViewOwners) tab = 'owners';
197	    activeTab = tab;
198	
199	    document.querySelectorAll('.team-tab').forEach((button) => {
200	      const isVisible = (button.dataset.tab === 'staff' && canViewStaff) || (button.dataset.tab === 'owners' && canViewOwners);
201	      button.style.display = isVisible ? '' : 'none';
202	      button.classList.toggle('active', button.dataset.tab === activeTab);
203	    });
204	
205	    document.getElementById('staffPane').classList.toggle('active', activeTab === 'staff');
206	    document.getElementById('ownersPane').classList.toggle('active', activeTab === 'owners');
207	
208	    const next = new URL(window.location.href);
209	    next.searchParams.set('tab', activeTab);
210	    window.history.replaceState({}, '', next.toString());
211	    syncActions();
212	  }
213	
214	  function describeHeadcountRates(staff) {
215	    const group = Array.isArray(staff.headcountTiers) && staff.headcountTiers.length > 0
216	      ? `Group ${staff.headcountTiers.length} rung${staff.headcountTiers.length === 1 ? '' : 's'}${staff.useMarginalHeadcountTiers === false ? ', flat' : ''}`
217	      : `Group ${(staff.ratePerHead ?? 0).toLocaleString()} VND/head`;
218	    const hasPrivateSpecific = (Array.isArray(staff.privateHeadcountTiers) && staff.privateHeadcountTiers.length > 0)
219	      || (staff.privateRatePerHead ?? 0) > 0;
220	    if (!hasPrivateSpecific) return group;
221	
222	    const privateLabel = Array.isArray(staff.privateHeadcountTiers) && staff.privateHeadcountTiers.length > 0
223	      ? `Private ${staff.privateHeadcountTiers.length} rung${staff.privateHeadcountTiers.length === 1 ? '' : 's'}`
224	      : `Private ${(staff.privateRatePerHead ?? 0).toLocaleString()} VND/head`;
225	    return `${group} | ${privateLabel}`;
226	  }
227	
228	  function roleLabel(roleName) {
229	    return {
230	      INSTRUCTOR: 'Instructor',
231	      MANAGER: 'Studio Manager',
232	      RECEPTIONIST: 'Receptionist',
233	      FREELANCE: 'Freelance Instructor',
234	      OWNER: 'Owner',
235	    }[String(roleName || '').toUpperCase()] || (roleName || 'Instructor');
236	  }
237	
238	  function statusBadge(isActive) {
239	    return isActive
240	      ? '<span class="badge badge-success">Active</span>'
241	      : '<span class="badge" style="background:rgba(148,163,184,0.14);color:#cbd5e1;border:1px solid rgba(148,163,184,0.28);">Inactive</span>';
242	  }
243	
244	  async function toggleStaffStatus(id, nextIsActive) {
245	    const action = nextIsActive ? 'activate' : 'deactivate';
246	    if (!confirm(`Are you sure you want to ${action} this staff member?`)) return;
247	
248	    try {
249	      const res = await fetch(`${API}/api/staff/${id}/status`, {
250	        method: 'PUT',
251	        headers: {
252	          Authorization: 'Bearer ' + token,
253	          'Content-Type': 'application/json',
254	        },
255	        body: JSON.stringify({ isActive: nextIsActive }),
256	      });
257	      if (!res.ok) throw new Error();
258	      await loadStaff();
259	    } catch {
260	      alert(`Could not ${action} this staff member. Please try again.`);
261	    }
262	  }
263	
264	  async function loadStaff() {
265	    const table = document.getElementById('staffTable');
266	    if (!canViewStaff) {
267	      table.innerHTML = `<tr><td colspan="6" style="text-align:center;padding:40px;color:var(--color-text-muted);">Staff management is not available for this role.</td></tr>`;
268	      return;
269	    }
270	
271	    try {
272	      const r = await fetch(`${API}/api/staff`, { headers: { Authorization: 'Bearer ' + token } });
273	      if (!r.ok) throw new Error();
274	      const data = await r.json();
275	
276	      table.innerHTML = Array.isArray(data) && data.length
277	        ? data.map((s) => {
278	            const modelLabel = {
279	              PERCENTAGE_TIERED: 'Tiered %',
280	              FIXED_HEADCOUNT: 'Fixed per head',
281	              FIXED_SALARY: 'Fixed salary',
282	              REVENUE_SPLIT: 'Revenue split',
283	            };
284	            return `
285	              <tr>
286	                <td><span class="font-medium">${escapeHtml(s.name)}</span></td>
287	                <td class="text-muted text-sm">${escapeHtml(roleLabel(s.role))}</td>
288	                <td><span class="badge badge-default">${escapeHtml(modelLabel[s.commissionModel] ?? s.commissionModel)}</span></td>
289	                <td class="font-semibold text-sm">${
290	                  s.commissionModel === 'FIXED_HEADCOUNT'
291	                    ? escapeHtml(describeHeadcountRates(s))
292	                    : s.baseRate ? `${s.baseRate}%` : '-'
293	                }</td>
294	                <td>${statusBadge(s.isActive !== false)}</td>
295	                <td>
296	                  <button
297	                    class="btn btn-ghost btn-sm"
298	                    type="button"
299	                    onclick="toggleStaffStatus('${s.id}', ${s.isActive === false ? 'true' : 'false'})"
300	                    style="${s.isActive === false ? 'color:rgb(34,197,94);' : 'color:var(--color-danger);'}"
301	                  >
302	                    ${s.isActive === false ? 'Activate' : 'Deactivate'}
303	                  </button>
304	                  <button class="btn btn-ghost btn-sm btn-icon" title="Edit" onclick="window.location.href='/admin/staff-form?id='+encodeURIComponent('${s.id}')">
305	                    <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.12 2.12 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
306	                  </button>
307	                </td>
308	              </tr>`;
309	          }).join('')
310	        : `<tr><td colspan="6" style="text-align:center;padding:40px;color:var(--color-text-muted);">No staff members found</td></tr>`;
311	    } catch {
312	      table.innerHTML = `<tr><td colspan="6" style="text-align:center;padding:40px;color:var(--color-danger);">Error loading staff.</td></tr>`;
313	    }
314	  }
315	
316	  function renderOwnersTable() {
317	    const tbody = document.getElementById('ownersTable');
318	    if (!canViewOwners) {
319	      tbody.innerHTML = '<tr><td colspan="6" style="text-align:center;padding:40px;color:var(--color-text-muted);">Owner records are available to admin users.</td></tr>';
320	      document.getElementById('equitySumValue').textContent = '—';
321	      document.getElementById('equityBadge').textContent = 'Admin only';
322	      return;
323	    }
324	
325	    if (!owners.length) {
326	      tbody.innerHTML = '<tr><td colspan="6" style="text-align:center;padding:40px;color:var(--color-text-muted);">No owners yet. Click Add owner to get started.</td></tr>';
327	    } else {
328	      tbody.innerHTML = owners.map((o) => `
329	        <tr>
330	          <td>
331	            <div style="font-weight:600;">${escapeHtml(o.name)}</div>
332	            <div style="font-size:12px;color:var(--color-text-muted);">${escapeHtml(o.email || '')}</div>
333	          </td>
334	          <td class="hidden-mobile">
335	            <div style="font-size:13px;">${escapeHtml(o.bankName || '—')}</div>
336	            <div style="font-size:12px;color:var(--color-text-muted);">${escapeHtml(o.bankAccountNumber || '')}</div>
337	          </td>
338	          <td style="text-align:right;font-weight:600;font-family:'Inter', -apple-system, sans-serif;font-size:18px;">${o.equitySharePercentage}%</td>
339	          <td>${o.receivesStripePayouts ? '<span class="badge badge-success">Routed</span>' : '<span class="badge badge-default">—</span>'}</td>
340	          <td>${o.isActiveOwner ? '<span class="badge badge-success">Active</span>' : '<span class="badge badge-default">Inactive</span>'}</td>
341	          <td style="text-align:right;">
342	            <button class="btn btn-ghost btn-sm" data-edit="${o.profileId}">Edit</button>
343	            <button class="btn btn-ghost btn-sm" data-del="${o.profileId}" style="color:var(--color-danger);">Delete</button>
344	          </td>
345	        </tr>
346	      `).join('');
347	      tbody.querySelectorAll('[data-edit]').forEach((button) => button.addEventListener('click', () => openEdit(button.getAttribute('data-edit'))));
348	      tbody.querySelectorAll('[data-del]').forEach((button) => button.addEventListener('click', () => deleteOwner(button.getAttribute('data-del'))));
349	    }
350	
351	    const activeSum = owners
352	      .filter((o) => o.isActiveOwner)
353	      .reduce((sum, o) => sum + (parseFloat(o.equitySharePercentage) || 0), 0);
354	    document.getElementById('equitySumValue').textContent = `${activeSum.toFixed(2)}%`;
355	    const badge = document.getElementById('equityBadge');
356	    if (Math.abs(activeSum - 100) < 0.01) {
357	      badge.className = 'badge badge-success';
358	      badge.textContent = 'Balanced ✓';
359	    } else if (activeSum === 0) {
360	      badge.className = 'badge badge-default';
361	      badge.textContent = 'No active owners';
362	    } else {
363	      badge.className = 'badge badge-danger';
364	      badge.textContent = `Off by ${(100 - activeSum).toFixed(2)}%`;
365	    }
366	  }
367	
368	  async function loadOwners() {
369	    if (!canViewOwners) {
370	      renderOwnersTable();
371	      return;
372	    }
373	
374	    try {
375	      const r = await fetch(`${API}/api/owners`, { headers: { 'Authorization': 'Bearer ' + token } });
376	      if (!r.ok) throw new Error();
377	      owners = await r.json();
378	      renderOwnersTable();
379	    } catch {
380	      document.getElementById('ownersTable').innerHTML = '<tr><td colspan="6" style="text-align:center;padding:40px;color:var(--color-danger);">Error loading owners.</td></tr>';
381	      document.getElementById('equitySumValue').textContent = '—';
382	      document.getElementById('equityBadge').textContent = 'Load failed';
383	    }
384	  }
385	
386	  function openModal() {
387	    document.getElementById('ownerModal').style.display = 'flex';
388	    document.getElementById('modalError').style.display = 'none';
389	  }
390	
391	  function closeModal() {
392	    document.getElementById('ownerModal').style.display = 'none';
393	    editing = null;
394	  }
395	
396	  function clearForm() {
397	    ['fName', 'fEmail', 'fPhone', 'fBankName', 'fBankAcct', 'fEquity', 'fNote'].forEach((id) => {
398	      document.getElementById(id).value = '';
399	    });
400	    document.getElementById('fStripe').checked = false;
401	    document.getElementById('fActive').checked = true;
402	  }
403	
404	  function openEdit(profileId) {
405	    const owner = owners.find((x) => x.profileId === profileId);
406	    if (!owner) return;
407	    editing = owner;
408	    document.getElementById('modalTitle').textContent = 'Edit Owner';
409	    document.getElementById('fName').value = owner.name || '';
410	    document.getElementById('fEmail').value = owner.email || '';
411	    document.getElementById('fPhone').value = owner.phone || '';
412	    document.getElementById('fBankName').value = owner.bankName || '';
413	    document.getElementById('fBankAcct').value = owner.bankAccountNumber || '';
414	    document.getElementById('fEquity').value = owner.equitySharePercentage;
415	    document.getElementById('fStripe').checked = !!owner.receivesStripePayouts;
416	    document.getElementById('fActive').checked = !!owner.isActiveOwner;
417	    document.getElementById('fNote').value = owner.note || '';
418	    openModal();
419	  }
420	
421	  async function saveOwner() {
422	    const errEl = document.getElementById('modalError');
423	    errEl.style.display = 'none';
424	    const payload = {
425	      profileId: editing?.profileId || null,
426	      staffId: editing?.staffId || null,
