file.content:
        payload['http://schemas.microsoft.com/ws/2008/06/identity/claims/role'] ||
        payload.role ||
        'admin'
      ).toLowerCase();
    } catch {
      return 'admin';
    }
  })();

  const canViewStaff = role === 'admin' || role === 'accountant';
  const canViewOwners = role === 'admin';
  let activeTab = new URLSearchParams(window.location.search).get('tab') || 'staff';
  let owners = [];
  let editing = null;

  function escapeHtml(s) {
    return String(s ?? '').replace(/[&<>"']/g, c => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;', "'":'&#39;' }[c]));
  }

  function syncActions() {
    document.getElementById('addStaffBtn').style.display = activeTab === 'staff' && canViewStaff ? 'inline-flex' : 'none';
    document.getElementById('addOwnerBtn').style.display = activeTab === 'owners' && canViewOwners ? 'inline-flex' : 'none';
  }

  function setTab(tab) {
    if (tab === 'owners' && !canViewOwners) tab = 'staff';
    if (tab === 'staff' && !canViewStaff && canViewOwners) tab = 'owners';
    activeTab = tab;

    document.querySelectorAll('.team-tab').forEach((button) => {
      const isVisible = (button.dataset.tab === 'staff' && canViewStaff) || (button.dataset.tab === 'owners' && canViewOwners);
      button.style.display = isVisible ? '' : 'none';
      button.classList.toggle('active', button.dataset.tab === activeTab);
    });

    document.getElementById('staffPane').classList.toggle('active', activeTab === 'staff');
    document.getElementById('ownersPane').classList.toggle('active', activeTab === 'owners');

    const next = new URL(window.location.href);
    next.searchParams.set('tab', activeTab);
    window.history.replaceState({}, '', next.toString());
    syncActions();
  }

  function describeHeadcountRates(staff) {
    const group = Array.isArray(staff.headcountTiers) && staff.headcountTiers.length > 0
      ? `Group ${staff.headcountTiers.length} rung${staff.headcountTiers.length === 1 ? '' : 's'}${staff.useMarginalHeadcountTiers === false ? ', flat' : ''}`
      : `Group ${(staff.ratePerHead ?? 0).toLocaleString()} VND/head`;
    const hasPrivateSpecific = (Array.isArray(staff.privateHeadcountTiers) && staff.privateHeadcountTiers.length > 0)
      || (staff.privateRatePerHead ?? 0) > 0;
    if (!hasPrivateSpecific) return group;

    const privateLabel = Array.isArray(staff.privateHeadcountTiers) && staff.privateHeadcountTiers.length > 0
      ? `Private ${staff.privateHeadcountTiers.length} rung${staff.privateHeadcountTiers.length === 1 ? '' : 's'}`
      : `Private ${(staff.privateRatePerHead ?? 0).toLocaleString()} VND/head`;
    return `${group} | ${privateLabel}`;
  }

  function roleLabel(roleName) {
    return {
      INSTRUCTOR: 'Instructor',
      MANAGER: 'Studio Manager',
      RECEPTIONIST: 'Receptionist',
      FREELANCE: 'Freelance Instructor',
      OWNER: 'Owner',
    }[String(roleName || '').toUpperCase()] || (roleName || 'Instructor');
  }

  function statusBadge(isActive) {
    return isActive
      ? '<span class="badge badge-success">Active</span>'
      : '<span class="badge" style="background:rgba(148,163,184,0.14);color:#cbd5e1;border:1px solid rgba(148,163,184,0.28);">Inactive</span>';
  }

  async function toggleStaffStatus(id, nextIsActive) {
    const action = nextIsActive ? 'activate' : 'deactivate';
    if (!confirm(`Are you sure you want to ${action} this staff member?`)) return;

    try {
      const res = await fetch(`${API}/api/staff/${id}/status`, {
        method: 'PUT',
        headers: {
          Authorization: 'Bearer ' + token,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ isActive: nextIsActive }),
      });
      if (!res.ok) throw new Error();
      await loadStaff();
    } catch {
      alert(`Could not ${action} this staff member. Please try again.`);
    }
  }

  async function loadStaff() {
    const table = document.getElementById('staffTable');
    if (!canViewStaff) {
      table.innerHTML = `<tr><td colspan="6" style="text-align:center;padding:40px;color:var(--color-text-muted);">Staff management is not available for this role.</td></tr>`;
      return;
    }

    try {
      const r = await fetch(`${API}/api/staff`, { headers: { Authorization: 'Bearer ' + token } });
      if (!r.ok) throw new Error();
      const data = await r.json();

      table.innerHTML = Array.isArray(data) && data.length
        ? data.map((s) => {
            const modelLabel = {
              PERCENTAGE_TIERED: 'Tiered %',
              FIXED_HEADCOUNT: 'Fixed per head',
              FIXED_SALARY: 'Fixed salary',
              REVENUE_SPLIT: 'Revenue split',
            };
            return `
              <tr>
                <td><span class="font-medium">${escapeHtml(s.name)}</span></td>
                <td class="text-muted text-sm">${escapeHtml(roleLabel(s.role))}</td>
                <td><span class="badge badge-default">${escapeHtml(modelLabel[s.commissionModel] ?? s.commissionModel)}</span></td>
                <td class="font-semibold text-sm">${
                  s.commissionModel === 'FIXED_HEADCOUNT'
                    ? escapeHtml(describeHeadcountRates(s))
                    : s.baseRate ? `${s.baseRate}%` : '-'
                }</td>
                <td>${statusBadge(s.isActive !== false)}</td>
                <td>
                  <button
                    class="btn btn-ghost btn-sm"
                    type="button"
                    onclick="toggleStaffStatus('${s.id}', ${s.isActive === false ? 'true' : 'false'})"
                    style="${s.isActive === false ? 'color:rgb(34,197,94);' : 'color:var(--color-danger);'}"
                  >
                    ${s.isActive === false ? 'Activate' : 'Deactivate'}
                  </button>
                  <button class="btn btn-ghost btn-sm btn-icon" title="Edit" onclick="window.location.href='/admin/staff-form?id='+encodeURIComponent('${s.id}')">
                    <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.12 2.12 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
                  </button>
                </td>
              </tr>`;
          }).join('')
        : `<tr><td colspan="6" style="text-align:center;padding:40px;color:var(--color-text-muted);">No staff members found</td></tr>`;
    } catch {
      table.innerHTML = `<tr><td colspan="6" style="text-align:center;padding:40px;color:var(--color-danger);">Error loading staff.</td></tr>`;
    }
  }

  function renderOwnersTable() {
    const tbody = document.getElementById('ownersTable');
    if (!canViewOwners) {
      tbody.innerHTML = '<tr><td colspan="6" style="text-align:center;padding:40px;color:var(--color-text-muted);">Owner records are available to admin users.</td></tr>';
      document.getElementById('equitySumValue').textContent = '—';
      document.getElementById('equityBadge').textContent = 'Admin only';
      return;
    }

    if (!owners.length) {
      tbody.innerHTML = '<tr><td colspan="6" style="text-align:center;padding:40px;color:var(--color-text-muted);">No owners yet. Click Add owner to get started.</td></tr>';
    } else {
      tbody.innerHTML = owners.map((o) => `
        <tr>
          <td>
            <div style="font-weight:600;">${escapeHtml(o.name)}</div>
            <div style="font-size:12px;color:var(--color-text-muted);">${escapeHtml(o.email || '')}</div>
          </td>
          <td class="hidden-mobile">
            <div style="font-size:13px;">${escapeHtml(o.bankName || '—')}</div>
            <div style="font-size:12px;color:var(--color-text-muted);">${escapeHtml(o.bankAccountNumber || '')}</div>
          </td>
          <td style="text-align:right;font-weight:600;font-family:'Inter', -apple-system, sans-serif;font-size:18px;">${o.equitySharePercentage}%</td>
          <td>${o.receivesStripePayouts ? '<span class="badge badge-success">Routed</span>' : '<span class="badge badge-default">—</span>'}</td>
          <td>${o.isActiveOwner ? '<span class="badge badge-success">Active</span>' : '<span class="badge badge-default">Inactive</span>'}</td>
          <td style="text-align:right;">
            <button class="btn btn-ghost btn-sm" data-edit="${o.profileId}">Edit</button>
            <button class="btn btn-ghost btn-sm" data-del="${o.profileId}" style="color:var(--color-danger);">Delete</button>
          </td>
        </tr>
      `).join('');
      tbody.querySelectorAll('[data-edit]').forEach((button) => button.addEventListener('click', () => openEdit(button.getAttribute('data-edit'))));
      tbody.querySelectorAll('[data-del]').forEach((button) => button.addEventListener('click', () => deleteOwner(button.getAttribute('data-del'))));
    }

    const activeSum = owners
      .filter((o) => o.isActiveOwner)
      .reduce((sum, o) => sum + (parseFloat(o.equitySharePercentage) || 0), 0);
    document.getElementById('equitySumValue').textContent = `${activeSum.toFixed(2)}%`;
    const badge = document.getElementById('equityBadge');
    if (Math.abs(activeSum - 100) < 0.01) {
      badge.className = 'badge badge-success';
      badge.textContent = 'Balanced ✓';
    } else if (activeSum === 0) {
      badge.className = 'badge badge-default';
      badge.textContent = 'No active owners';
    } else {
      badge.className = 'badge badge-danger';
      badge.textContent = `Off by ${(100 - activeSum).toFixed(2)}%`;
    }
  }

  async function loadOwners() {
    if (!canViewOwners) {
      renderOwnersTable();
      return;
    }

    try {
      const r = await fetch(`${API}/api/owners`, { headers: { 'Authorization': 'Bearer ' + token } });
      if (!r.ok) throw new Error();
      owners = await r.json();
      renderOwnersTable();
    } catch {
      document.getElementById('ownersTable').innerHTML = '<tr><td colspan="6" style="text-align:center;padding:40px;color:var(--color-danger);">Error loading owners.</td></tr>';
      document.getElementById('equitySumValue').textContent = '—';
      document.getElementById('equityBadge').textContent = 'Load failed';
    }
  }

  function openModal() {
    document.getElementById('ownerModal').style.display = 'flex';
    document.getElementById('modalError').style.display = 'none';
  }

  function closeModal() {
    document.getElementById('ownerModal').style.display = 'none';
    editing = null;
  }

  function clearForm() {
    ['fName', 'fEmail', 'fPhone', 'fBankName', 'fBankAcct', 'fEquity', 'fNote'].forEach((id) => {
      document.getElementById(id).value = '';
    });
    document.getElementById('fStripe').checked = false;
    document.getElementById('fActive').checked = true;
  }

  function openEdit(profileId) {
    const owner = owners.find((x) => x.profileId === profileId);
    if (!owner) return;
    editing = owner;
    document.getElementById('modalTitle').textContent = 'Edit Owner';
    document.getElementById('fName').value = owner.name || '';
    document.getElementById('fEmail').value = owner.email || '';
    document.getElementById('fPhone').value = owner.phone || '';
    document.getElementById('fBankName').value = owner.bankName || '';
    document.getElementById('fBankAcct').value = owner.bankAccountNumber || '';
    document.getElementById('fEquity').value = owner.equitySharePercentage;
    document.getElementById('fStripe').checked = !!owner.receivesStripePayouts;
    document.getElementById('fActive').checked = !!owner.isActiveOwner;
    document.getElementById('fNote').value = owner.note || '';
    openModal();
  }

  async function saveOwner() {
    const errEl = document.getElementById('modalError');
    errEl.style.display = 'none';
    const payload = {
      profileId: editing?.profileId || null,
      staffId: editing?.staffId || null,
      name: document.getElementById('fName').value.trim(),
      email: document.getElementById('fEmail').value.trim() || null,
      phone: document.getElementById('fPhone').value.trim() || null,
      bankName: document.getElementById('fBankName').value.trim() || null,
      bankAccountNumber: document.getElementById('fBankAcct').value.trim() || null,
      equitySharePercentage: parseFloat(document.getElementById('fEquity').value) || 0,
      receivesStripePayouts: document.getElementById('fStripe').checked,
      isActiveOwner: document.getElementById('fActive').checked,
      note: document.getElementById('fNote').value.trim() || '',
    };
    const r = await fetch(`${API}/api/owners`, {
      method: 'POST',
      headers: { 'Authorization': 'Bearer ' + token, 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });
    if (!r.ok) {
      const body = await r.json().catch(() => ({ message: 'Save failed' }));
      errEl.textContent = body.message || 'Save failed';
      errEl.style.display = 'block';
      return;
    }
    closeModal();
    await loadOwners();
    window.showToast && window.showToast('Owner saved');
  }

  async function deleteOwner(profileId) {
    if (!confirm('Delete this owner profile? The underlying staff record will be preserved.')) return;
    await fetch(`${API}/api/owners/${profileId}`, {
      method: 'DELETE',
      headers: { 'Authorization': 'Bearer ' + token },
    });
    await loadOwners();
  }

  document.querySelectorAll('.team-tab').forEach((button) => {
    button.addEventListener('click', () => setTab(button.dataset.tab));
  });
  document.getElementById('addStaffBtn').addEventListener('click', () => {
    window.location.href = '/admin/staff-form';
  });
  document.getElementById('addOwnerBtn').addEventListener('click', () => {
    editing = null;
    document.getElementById('modalTitle').textContent = 'Add Owner';
    clearForm();
    openModal();
  });
  document.getElementById('cancelModalBtn').addEventListener('click', closeModal);
  document.getElementById('saveOwnerBtn').addEventListener('click', saveOwner);

  if (activeTab === 'owners' && !canViewOwners) activeTab = 'staff';
  setTab(activeTab);
  loadStaff();
  loadOwners();

  window.toggleStaffStatus = toggleStaffStatus;
</script>

