608	          if (!dto.payrollEstimatePeriodLabel) {
609	            payrollSubEl.textContent = 'No payroll run has been computed yet.';
610	          } else if (dto.payrollEstimateIsLatestComputed) {
611	            payrollSubEl.textContent = `Using ${dto.payrollEstimatePeriodLabel} while the current month is still open.`;
612	          } else {
613	            payrollSubEl.textContent = dto.payrollEstimatePeriodLabel;
614	          }
615	        }
616	      } catch (error) {
617	        console.warn('Dashboard KPI load failed:', error);
618	        if (revenueDeltaEl) revenueDeltaEl.textContent = 'Unable to load KPI data';
619	        if (clientsSubEl) clientsSubEl.textContent = 'Unable to load';
620	        if (payrollSubEl) payrollSubEl.textContent = 'Unable to load';
621	      }
622	    }
623	
624	    async function loadMonthSummary() {
625	      const { start, end } = currentMonthRange();
626	      try {
627	        const res = await fetch(`${API}/api/analytics/month-summary?startDate=${start}&endDate=${end}`, {
628	          headers: { Authorization: `Bearer ${token}` },
629	        });
630	        if (!res.ok) throw new Error(`HTTP ${res.status}`);
631	        latestMonthSummary = await res.json();
632	
633	        document.getElementById('pulse-totalRevenue').textContent = fmtVnd(latestMonthSummary.totalRevenueVnd ?? 0);
634	        document.getElementById('pulse-classRevenue').textContent = fmtVnd(latestMonthSummary.singleClassRevenueVnd ?? 0);
635	        document.getElementById('pulse-packageRevenue').textContent = fmtVnd(latestMonthSummary.packageRevenueVnd ?? 0);
636	        document.getElementById('pulse-occupancy').textContent = fmtPct(latestMonthSummary.averageOccupancyPct ?? 0);
637	        document.getElementById('pulse-packagesSold').textContent = fmtInt(latestMonthSummary.packagesSoldCount ?? 0);
638	        document.getElementById('pulse-newClients').textContent = fmtInt(latestMonthSummary.newClientsCount ?? 0);
639	        document.getElementById('pulse-dailyRevenue').textContent = fmtVnd(latestMonthSummary.dailyAverageRevenueVnd ?? 0);
640	        document.getElementById('pulse-creditsOwed').textContent = fmtInt(latestMonthSummary.outstandingPackageCredits ?? 0);
641	        document.getElementById('pulse-projection').textContent = fmtVnd(latestMonthSummary.monthlyProjectionVnd ?? 0);
642	        document.getElementById('pulse-totalClasses').textContent = fmtInt(latestMonthSummary.totalClassesHeld ?? 0);
643	        document.getElementById('pulse-dailyClasses').textContent = `${(Number(latestMonthSummary.dailyAverageClasses) || 0).toFixed(1)} / day`;
644	        document.getElementById('pulse-merchRevenue').textContent = fmtVnd(latestMonthSummary.merchandiseRevenueVnd ?? 0);
645	
646	        const packageRevenue = Number(latestMonthSummary.packageRevenueVnd || 0);
647	        const classRevenue = Number(latestMonthSummary.singleClassRevenueVnd || 0);
648	        const packageLead = packageRevenue >= classRevenue
649	          ? `Packages leading by ${fmtVnd(packageRevenue - classRevenue)}`
650	          : `Classes leading by ${fmtVnd(classRevenue - packageRevenue)}`;
651	        document.getElementById('dash-focus-value').textContent = fmtPct(latestMonthSummary.averageOccupancyPct ?? 0);
652	        document.getElementById('dash-focus-sub').textContent = `${packageLead} this month`;
653	        document.getElementById('dashboardHeroSubtitle').textContent =
654	          `Revenue, package momentum, occupancy, payroll pressure, and class delivery in one operating view.`;
655	
656	        renderInsights();
657	      } catch (error) {
658	        console.warn('Month summary load failed:', error);
659	      }
660	    }
661	
662	    async function loadRecentInvoices() {
663	      const tbody = document.getElementById('recent-invoices');
664	      try {
665	        const res = await fetch(`${API}/api/invoice/recent?limit=6`, {
666	          headers: { Authorization: `Bearer ${token}` },
667	        });
668	        if (!res.ok) throw new Error(`HTTP ${res.status}`);
669	        const invoices = await res.json();
670	
671	        if (!invoices || invoices.length === 0) {
672	          tbody.innerHTML = `<tr><td colspan="5" class="dashboard-table-empty">No invoices yet. Use POS to start creating transactions.</td></tr>`;
673	          return;
674	        }
675	
676	        tbody.innerHTML = invoices.map((invoice) => {
677	          const issueDate = new Date(invoice.issueDate).toLocaleDateString('en-US', {
678	            month: 'short',
679	            day: 'numeric',
680	            year: 'numeric',
681	          });
682	          const statusClass = invoice.status === 'PAID'
683	            ? 'badge-success'
684	            : invoice.status === 'PARTIAL'
685	              ? 'badge-warning'
686	              : 'badge-default';
687	          const statusLabel = invoice.status === 'PARTIAL' ? 'Partial' : (invoice.status || 'Unknown');
688	          return `
689	            <tr>
690	              <td>${escapeHtml(invoice.clientName)}</td>
691	              <td>${issueDate}</td>
692	              <td>${escapeHtml(invoice.itemsSummary)}</td>
693	              <td>${fmtVnd(invoice.totalNet)}</td>
694	              <td><span class="badge ${statusClass}">${escapeHtml(statusLabel)}</span></td>
695	            </tr>
696	          `;
697	        }).join('');
698	      } catch (error) {
699	        console.warn('Recent invoices load failed:', error);
700	        tbody.innerHTML = `<tr><td colspan="5" class="dashboard-table-empty">Unable to load recent invoices.</td></tr>`;
701	      }
702	    }
703	
704	    async function loadRevenueChart() {
705	      const ctx = document.getElementById('revenueChart').getContext('2d');
706	      try {
707	        const year = new Date().getFullYear();
708	        const res = await fetch(`${API}/api/analytics/yearly-revenue-expense?year=${year}`, {
709	          headers: { Authorization: `Bearer ${token}` },
710	        });
711	        if (!res.ok) throw new Error(`HTTP ${res.status}`);
712	        const rows = await res.json();
713	
714	        if (revenueChartInstance) revenueChartInstance.destroy();
715	        revenueChartInstance = new Chart(ctx, {
716	          type: 'bar',
717	          data: {
718	            labels: rows.map((row) => row.month),
719	            datasets: [
720	              {
721	                label: 'Revenue',
722	                data: rows.map((row) => row.revenueVnd),
723	                backgroundColor: 'rgba(219, 125, 60, 0.82)',
724	                borderRadius: 8,
725	                borderSkipped: false,
726	              },
727	              {
728	                label: 'Expenses',
729	                data: rows.map((row) => row.expensesVnd),
730	                backgroundColor: 'rgba(75, 104, 135, 0.42)',
731	                borderRadius: 8,
732	                borderSkipped: false,
733	              },
734	            ],
735	          },
736	          options: {
737	            responsive: true,
738	            maintainAspectRatio: false,
739	            plugins: {
740	              legend: {
741	                labels: {
742	                  color: css('--color-text-secondary'),
743	                  font: { family: 'Inter', size: 11 },
744	                  boxWidth: 10,
745	                },
746	              },
747	            },
748	            scales: {
749	              y: {
750	                ticks: {
751	                  color: css('--color-text-muted'),
752	                  font: { family: 'Inter', size: 10 },
753	                  callback: (value) => {
754	                    if (Math.abs(value) >= 1e9) return `${(value / 1e9).toFixed(1)}B`;
755	                    if (Math.abs(value) >= 1e6) return `${(value / 1e6).toFixed(0)}M`;
756	                    return value.toLocaleString('en-US');
757	                  },
758	                },
759	                grid: { color: css('--color-border-subtle') },
760	                border: { display: false },
761	              },
762	              x: {
763	                ticks: {
764	                  color: css('--color-text-secondary'),
765	                  font: { family: 'Inter', size: 11 },
766	                },
767	                grid: { display: false },
768	              },
769	            },
770	          },
771	        });
772	      } catch (error) {
773	        console.warn('Revenue chart load failed:', error);
774	      }
775	    }
776	
777	    async function loadBreakdownChart() {
778	      const ctx = document.getElementById('breakdownChart').getContext('2d');
779	      const { start, end } = currentMonthRange();
780	      try {
781	        const res = await fetch(`${API}/api/analytics/revenue-breakdown?startDate=${start}&endDate=${end}`, {
782	          headers: { Authorization: `Bearer ${token}` },
783	        });
784	        if (!res.ok) throw new Error(`HTTP ${res.status}`);
785	        latestBreakdown = await res.json();
786	
787	        const items = [
788	          { label: 'Classes', value: Number(latestBreakdown.singleClassRevenueVnd || 0), color: css('--color-brand-accent') },
789	          { label: 'Packages', value: Number(latestBreakdown.packageRevenueVnd || 0), color: '#4ea5d9' },
790	          { label: 'Merchandise', value: Number(latestBreakdown.merchandiseRevenueVnd || 0), color: '#45b68d' },
791	          { label: 'Studio Rental', value: Number(latestBreakdown.rentalRevenueVnd || 0), color: '#9b59b6' },
792	        ].filter((item) => item.value > 0);
793	
794	        if (breakdownChartInstance) breakdownChartInstance.destroy();
795	        breakdownChartInstance = new Chart(ctx, {
796	          type: 'doughnut',
797	          data: {
798	            labels: items.length ? items.map((item) => item.label) : ['No revenue'],
799	            datasets: [
800	              {
801	                data: items.length ? items.map((item) => item.value) : [1],
802	                backgroundColor: items.length ? items.map((item) => item.color) : [css('--color-border-strong')],
803	                borderWidth: 0,
804	              },
805	            ],
806	          },
807	          options: {
808	            responsive: true,
809	            maintainAspectRatio: false,
810	            cutout: '68%',
811	            plugins: {
812	              legend: {
813	                position: 'bottom',
814	                labels: {
815	                  color: css('--color-text-secondary'),
816	                  font: { family: 'Inter', size: 11 },
817	                  boxWidth: 10,
818	                },
819	              },
820	              tooltip: {
821	                callbacks: {
822	                  label: (ctx) => `${ctx.label}: ${fmtVnd(ctx.parsed)}`,
823	                },
824	              },
825	            },
826	          },
827	        });
828	
829	        renderInsights();
830	      } catch (error) {
831	        console.warn('Revenue breakdown load failed:', error);
832	      }
833	    }
834	
835	    function renderInsights() {
836	      if (!latestMonthSummary) return;
837	      const list = document.getElementById('dashboardInsightList');
838	      const totalRevenue = Number(latestMonthSummary.totalRevenueVnd || 0);
839	      const packageRevenue = latestBreakdown ? Number(latestBreakdown.packageRevenueVnd || 0) : Number(latestMonthSummary.packageRevenueVnd || 0);
840	      const classRevenue = latestBreakdown ? Number(latestBreakdown.singleClassRevenueVnd || 0) : Number(latestMonthSummary.singleClassRevenueVnd || 0);
841	      const occupancy = Number(latestMonthSummary.averageOccupancyPct || 0);
842	      const projection = Number(latestMonthSummary.monthlyProjectionVnd || 0);
843	      const packageShare = totalRevenue > 0 ? packageRevenue / totalRevenue : 0;
844	      const classShare = totalRevenue > 0 ? classRevenue / totalRevenue : 0;
845	
846	      const insights = [
847	        {
848	          title: 'Revenue mix',
849	          copy: packageShare >= classShare
850	            ? 'Packages are currently the biggest driver of top-line revenue.'
851	            : 'Single class sales are currently leading the month.',
852	          metric: totalRevenue > 0 ? `${Math.round(Math.max(packageShare, classShare) * 100)}% share` : '--',
853	        },
854	        {
855	          title: 'Occupancy health',
856	          copy: occupancy >= 0.75
857	            ? 'Classes are filling well. This is a strong signal for upsell and schedule expansion.'
858	            : 'There is still room to tighten utilization before adding more supply.',
859	          metric: fmtPct(occupancy),
860	        },
861	        {
862	          title: 'Projection pace',
863	          copy: 'Projected revenue helps you sense whether the month is ahead or behind pace.',
864	          metric: fmtVnd(projection),
865	        },
866	      ];
867	
868	      list.innerHTML = insights.map((insight) => `
869	        <li class="dashboard-insight-item">
870	          <div>
871	            <strong>${escapeHtml(insight.title)}</strong>
872	            <span>${escapeHtml(insight.copy)}</span>
873	          </div>
874	          <div class="dashboard-insight-metric">${escapeHtml(insight.metric)}</div>
875	        </li>
876	      `).join('');
877	    }
878	
879	    async function bootDashboard() {
880	      await Promise.all([
881	        loadDashboardKpis(),
882	        loadMonthSummary(),
883	        loadRecentInvoices(),
884	        loadRevenueChart(),
885	        loadBreakdownChart(),
886	      ]);
887	    }
888	
889	    bootDashboard();
890	  </script>
891	</AdminLayout>
