---
import AdminLayout from '../../layouts/AdminLayout.astro';
---
<AdminLayout title="Dashboard" activePage="dashboard">
  <style is:global>
    .dashboard-shell {
      display: grid;
      gap: 24px;
    }
    .dashboard-hero {
      display: grid;
      grid-template-columns: minmax(0, 1.45fr) minmax(320px, 0.95fr);
      gap: 20px;
      align-items: stretch;
    }
    .dashboard-hero-panel {
      position: relative;
      overflow: hidden;
      border-radius: 24px;
      border: 1px solid var(--color-border);
      background:
        radial-gradient(circle at top right, rgba(219, 125, 60, 0.22), transparent 28%),
        linear-gradient(180deg, rgba(219, 125, 60, 0.10), transparent 28%),
        var(--color-surface);
      box-shadow: var(--shadow-card);
      padding: 28px;
    }
    .dashboard-hero-panel::after {
      content: '';
      position: absolute;
      inset: auto 28px 0;
      height: 1px;
      background: linear-gradient(90deg, transparent, rgba(219, 125, 60, 0.35), transparent);
    }
    .dashboard-hero-title {
      max-width: 620px;
      margin-top: 8px;
      font-size: 32px;
      line-height: 1.08;
      letter-spacing: -0.05em;
      color: var(--color-text-primary);
    }
    .dashboard-hero-copy {
      margin-top: 12px;
      max-width: 620px;
      font-size: 14px;
      color: var(--color-text-secondary);
      line-height: 1.65;
    }
    .dashboard-hero-metric {
      display: flex;
      flex-wrap: wrap;
      align-items: baseline;
      gap: 12px;
      margin-top: 24px;
    }
    .dashboard-hero-value {
      font-size: clamp(34px, 5vw, 52px);
      font-weight: 800;
      line-height: 1;
      letter-spacing: -0.06em;
      color: var(--color-text-primary);
    }
    .dashboard-hero-delta {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 8px 12px;
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.6);
      border: 1px solid var(--color-border-subtle);
      color: var(--color-text-secondary);
      font-size: 12px;
      font-weight: 600;
    }
    [data-theme="dark"] .dashboard-hero-delta {
      background: rgba(255, 255, 255, 0.04);
    }
    .dashboard-progress {
      margin-top: 24px;
    }
    .dashboard-progress-bar {
      height: 10px;
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.5);
      border: 1px solid var(--color-border-subtle);
      overflow: hidden;
    }
    .dashboard-progress-fill {
      width: 0%;
      height: 100%;
      border-radius: inherit;
      background: linear-gradient(90deg, var(--color-brand-accent), #f0b278);
      transition: width 0.5s ease;
    }
    .dashboard-progress-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 14px;
      margin-top: 16px;
    }
    .dashboard-progress-stat {
      padding: 14px 16px;
      border-radius: 16px;
      background: var(--color-surface-raised);
      border: 1px solid var(--color-border-subtle);
    }
    .dashboard-progress-stat span {
      display: block;
      font-size: 11px;
      text-transform: uppercase;
      letter-spacing: 0.12em;
      color: var(--color-text-muted);
    }
    .dashboard-progress-stat strong {
      display: block;
      margin-top: 8px;
      font-size: 18px;
      line-height: 1.2;
      color: var(--color-text-primary);
    }
    .dashboard-summary-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 14px;
      height: 100%;
    }
    .dashboard-summary-card {
      padding: 18px;
      border-radius: 20px;
      border: 1px solid var(--color-border);
      background: var(--color-surface);
      box-shadow: var(--shadow-card);
      display: grid;
      gap: 12px;
      align-content: start;
    }
    .dashboard-summary-card .summary-label {
      font-size: 11px;
      text-transform: uppercase;
      letter-spacing: 0.12em;
      color: var(--color-text-muted);
    }
    .dashboard-summary-card .summary-value {
      font-size: 28px;
      font-weight: 800;
      letter-spacing: -0.05em;
      line-height: 1;
      color: var(--color-text-primary);
    }
    .dashboard-summary-card .summary-sub {
      font-size: 12px;
      color: var(--color-text-secondary);
      line-height: 1.5;
    }
    .dashboard-pulse-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 16px;
    }
    .dashboard-pulse-card {
      padding: 18px;
      border-radius: 18px;
      border: 1px solid var(--color-border);
      background: var(--color-surface);
      box-shadow: var(--shadow-card);
    }
    .dashboard-pulse-card .pulse-label {
      font-size: 11px;
      text-transform: uppercase;
      letter-spacing: 0.12em;
      color: var(--color-text-muted);
    }
    .dashboard-pulse-card .pulse-value {
      margin-top: 10px;
      font-size: 24px;
      line-height: 1;
      font-weight: 800;
      letter-spacing: -0.05em;
      color: var(--color-text-primary);
    }
    .dashboard-pulse-card .pulse-sub {
      margin-top: 8px;
      font-size: 12px;
      color: var(--color-text-secondary);
      line-height: 1.5;
    }
    .dashboard-grid {
      display: grid;
      grid-template-columns: minmax(0, 1.4fr) minmax(320px, 0.9fr);
      gap: 20px;
    }
    .dashboard-card {
      border-radius: 22px;
      overflow: hidden;
      border: 1px solid var(--color-border);
      background: var(--color-surface);
      box-shadow: var(--shadow-card);
    }
    .dashboard-card-header {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 16px;
      padding: 22px 24px 16px;
      border-bottom: 1px solid var(--color-border-subtle);
    }
    .dashboard-card-title {
      font-size: 17px;
      font-weight: 700;
      letter-spacing: -0.03em;
      color: var(--color-text-primary);
    }
    .dashboard-card-subtitle {
      margin-top: 6px;
      font-size: 12px;
      color: var(--color-text-muted);
    }
    .dashboard-card-body {
      padding: 24px;
    }
    .dashboard-chart-wrap {
      height: 320px;
    }
    .dashboard-insight-list {
      display: grid;
      gap: 14px;
      list-style: none;
      padding: 0;
      margin: 0;
    }
    .dashboard-insight-item {
      display: flex;
      justify-content: space-between;
      align-items: flex-start;
      gap: 14px;
      padding: 14px 16px;
      border-radius: 16px;
      background: var(--color-surface-raised);
      border: 1px solid var(--color-border-subtle);
    }
    .dashboard-insight-item strong {
      display: block;
      color: var(--color-text-primary);
      font-size: 13px;
    }
    .dashboard-insight-item span {
      display: block;
      margin-top: 4px;
      color: var(--color-text-secondary);
      font-size: 12px;
      line-height: 1.5;
    }
    .dashboard-insight-metric {
      white-space: nowrap;
      font-size: 12px;
      font-weight: 700;
      color: var(--color-brand-accent);
    }
    .dashboard-finance-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 14px;
    }
    .dashboard-finance-chip {
      padding: 16px;
      border-radius: 16px;
      background: var(--color-surface-raised);
      border: 1px solid var(--color-border-subtle);
    }
    .dashboard-finance-chip span {
      display: block;
      font-size: 11px;
      text-transform: uppercase;
      letter-spacing: 0.12em;
      color: var(--color-text-muted);
    }
    .dashboard-finance-chip strong {
      display: block;
      margin-top: 8px;
      font-size: 18px;
      line-height: 1.25;
      color: var(--color-text-primary);
    }
    .dashboard-finance-chip small {
      display: block;
      margin-top: 8px;
      color: var(--color-text-secondary);
      font-size: 12px;
      line-height: 1.5;
    }
    .dashboard-table-empty {
      text-align: center;
      padding: 32px !important;
      color: var(--color-text-muted);
    }
    @media (max-width: 1200px) {
      .dashboard-hero,
      .dashboard-grid {
        grid-template-columns: 1fr;
      }
      .dashboard-pulse-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }
    }
    @media (max-width: 720px) {
      .dashboard-summary-grid,
      .dashboard-pulse-grid,
      .dashboard-progress-grid,
      .dashboard-finance-grid {
        grid-template-columns: 1fr;
      }
      .dashboard-hero-panel,
      .dashboard-card-body {
        padding: 20px;
      }
      .dashboard-card-header {
        padding: 20px 20px 14px;
      }
      .dashboard-hero-title {
        font-size: 26px;
      }
      .dashboard-summary-card .summary-value,
      .dashboard-pulse-card .pulse-value {
        font-size: 24px;
      }
    }
  </style>

  <div class="dashboard-shell">
    <section class="dashboard-hero">
      <div class="dashboard-hero-panel" data-dash-role="admin,accountant">
        <div class="card-eyebrow">Business Snapshot</div>
        <div class="dashboard-hero-title">Studio performance, cash movement, and operating momentum at a glance.</div>
        <div class="dashboard-hero-copy" id="dashboardHeroSubtitle">
          Track the current month across revenue, package activity, occupancy, payroll pressure, and class delivery.
        </div>
        <div class="dashboard-hero-metric">
          <div class="dashboard-hero-value" id="kpi-revenue">--</div>
          <div class="dashboard-hero-delta" id="kpi-revenue-delta">Loading...</div>
        </div>
      </div>

      <div class="dashboard-summary-grid">
        <div class="dashboard-summary-card">
          <div class="summary-label">Active clients</div>
          <div class="summary-value" id="kpi-clients">--</div>
          <div class="summary-sub" id="kpi-clients-sub">Booked in the last 30 days</div>
        </div>
        <div class="dashboard-summary-card">
          <div class="summary-label">Classes this week</div>
          <div class="summary-value" id="kpi-classes">--</div>
          <div class="summary-sub">Scheduled sessions on the live calendar</div>
        </div>
        <div class="dashboard-summary-card" data-dash-role="admin,accountant">
          <div class="summary-label">Payroll estimate</div>
          <div class="summary-value" id="kpi-payroll">--</div>
          <div class="summary-sub" id="kpi-payroll-sub">Current washout reference</div>
        </div>
        <div class="dashboard-summary-card">
          <div class="summary-label">Studio focus</div>
          <div class="summary-value" id="dash-focus-value">--</div>
          <div class="summary-sub" id="dash-focus-sub">Loading operational mix</div>
        </div>
      </div>
    </section>

    <section class="dashboard-pulse-grid">
      <div class="dashboard-pulse-card" data-dash-role="admin,accountant">
        <div class="pulse-label">Month revenue</div>
        <div class="pulse-value" id="pulse-totalRevenue">--</div>
        <div class="pulse-sub">Total revenue recorded in the selected month snapshot</div>
      </div>
      <div class="dashboard-pulse-card">
        <div class="pulse-label">Class revenue</div>
        <div class="pulse-value" id="pulse-classRevenue">--</div>
        <div class="pulse-sub">Single-class checkouts and drop-in sales</div>
      </div>
      <div class="dashboard-pulse-card">
        <div class="pulse-label">Package revenue</div>
        <div class="pulse-value" id="pulse-packageRevenue">--</div>
        <div class="pulse-sub">Package sales captured this month</div>
      </div>
      <div class="dashboard-pulse-card">
        <div class="pulse-label">Average occupancy</div>
        <div class="pulse-value" id="pulse-occupancy">--</div>
        <div class="pulse-sub">How full your classes are running</div>
      </div>
      <div class="dashboard-pulse-card">
        <div class="pulse-label">Packages sold</div>
        <div class="pulse-value" id="pulse-packagesSold">--</div>
        <div class="pulse-sub">Completed package purchases this month</div>
      </div>
      <div class="dashboard-pulse-card">
        <div class="pulse-label">New clients</div>
        <div class="pulse-value" id="pulse-newClients">--</div>
        <div class="pulse-sub">Fresh customers added in the month window</div>
      </div>
      <div class="dashboard-pulse-card">
        <div class="pulse-label">Daily average revenue</div>
        <div class="pulse-value" id="pulse-dailyRevenue">--</div>
        <div class="pulse-sub">Typical revenue per active day</div>
      </div>
      <div class="dashboard-pulse-card">
        <div class="pulse-label">Credits owed</div>
        <div class="pulse-value" id="pulse-creditsOwed">--</div>
        <div class="pulse-sub">Remaining package credits still to be delivered</div>
      </div>
    </section>

    <section class="dashboard-grid">
      <div class="dashboard-card">
        <div class="dashboard-card-header">
          <div>
            <div class="card-eyebrow">Finance Trend</div>
            <div class="dashboard-card-title">Revenue vs expenses</div>
            <div class="dashboard-card-subtitle">Current year running totals for revenue and operating expenses.</div>
          </div>
        </div>
        <div class="dashboard-card-body">
          <div class="dashboard-chart-wrap">
            <canvas id="revenueChart"></canvas>
          </div>
        </div>
      </div>

      <div class="dashboard-card">
        <div class="dashboard-card-header">
          <div>
            <div class="card-eyebrow">Sales Mix</div>
            <div class="dashboard-card-title">What is driving revenue</div>
            <div class="dashboard-card-subtitle">Useful for seeing whether the month is being carried by classes, packages, products, or rentals.</div>
          </div>
        </div>
        <div class="dashboard-card-body">
          <div class="dashboard-chart-wrap" style="height:240px;">
            <canvas id="breakdownChart"></canvas>
          </div>
          <ul class="dashboard-insight-list" id="dashboardInsightList" style="margin-top:20px;">
            <li class="dashboard-insight-item">
              <div>
                <strong>Loading insights</strong>
                <span>Pulling together the most useful takeaways from your live data.</span>
              </div>
              <div class="dashboard-insight-metric">--</div>
            </li>
          </ul>
        </div>
      </div>
    </section>

    <section class="dashboard-grid">
      <div class="dashboard-card">
        <div class="dashboard-card-header">
          <div>
            <div class="card-eyebrow">Live Activity</div>
            <div class="dashboard-card-title">Recent invoices</div>
            <div class="dashboard-card-subtitle">The latest transactions coming out of point of sale.</div>
          </div>
          <a href="/admin/invoices" class="btn btn-secondary btn-sm">Open invoices</a>
        </div>
        <div class="dashboard-card-body" style="padding:0;">
          <div class="table-responsive">
            <table class="data-table">
              <thead>
                <tr>
                  <th>Client</th>
                  <th>Date</th>
                  <th>Items</th>
                  <th>Amount</th>
                  <th>Status</th>
                </tr>
              </thead>
              <tbody id="recent-invoices">
                <tr><td colspan="5" class="dashboard-table-empty">Loading transactions...</td></tr>
              </tbody>
            </table>
          </div>
        </div>
      </div>

      <div class="dashboard-card">
        <div class="dashboard-card-header">
          <div>
            <div class="card-eyebrow">Operating Notes</div>
            <div class="dashboard-card-title">Studio pulse</div>
            <div class="dashboard-card-subtitle">A tighter operational read on where the month is landing.</div>
          </div>
        </div>
        <div class="dashboard-card-body">
          <div class="dashboard-finance-grid">
            <div class="dashboard-finance-chip">
              <span>Monthly projection</span>
              <strong id="pulse-projection">--</strong>
              <small>Projected month-end revenue based on current pace.</small>
            </div>
            <div class="dashboard-finance-chip">
              <span>Total classes held</span>
              <strong id="pulse-totalClasses">--</strong>
              <small>Actual class delivery in the month window.</small>
            </div>
            <div class="dashboard-finance-chip">
              <span>Daily average classes</span>
              <strong id="pulse-dailyClasses">--</strong>
              <small>Useful for checking whether the weekly schedule is dense enough.</small>
            </div>
            <div class="dashboard-finance-chip">
              <span>Merchandise revenue</span>
              <strong id="pulse-merchRevenue">--</strong>
              <small>Accessory and product contribution to the month.</small>
            </div>
          </div>
        </div>
      </div>
    </section>
  </div>

  <script src="https://cdn.jsdelivr.net/npm/chart.js" is:inline></script>
  <script>
    const token = localStorage.getItem('token');
    const API = import.meta.env.PUBLIC_API_URL;

    const dashboardRole = (() => {
      try {
        const payload = JSON.parse(atob(token.split('.')[1]));
        return String(
          payload['http://schemas.microsoft.com/ws/2008/06/identity/claims/role'] ||
          payload.role ||
          'admin'
        ).toLowerCase();
      } catch {
        return 'admin';
      }
    })();

    document.querySelectorAll('[data-dash-role]').forEach((el) => {
      const allowed = el.getAttribute('data-dash-role').toLowerCase().split(',');
      if (allowed.indexOf(dashboardRole) === -1) {
        el.style.display = 'none';
      }
    });

    const fmtVnd = (n) => `${Math.round(Number(n) || 0).toLocaleString('en-US')} VND`;
    const fmtInt = (n) => `${Math.round(Number(n) || 0).toLocaleString('en-US')}`;
    const fmtPct = (n) => `${Math.round((Number(n) || 0) * 100)}%`;

    function escapeHtml(value) {
      return String(value || '').replace(/[<>&"']/g, (c) => ({
        '<': '&lt;',
        '>': '&gt;',
        '&': '&amp;',
        '"': '&quot;',
        "'": '&#39;',
      }[c]));
    }

    function css(name) {
      return getComputedStyle(document.documentElement).getPropertyValue(name).trim();
    }

    function currentMonthRange() {
      const now = new Date();
      const start = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-01`;
      const nextMonth = new Date(now.getFullYear(), now.getMonth() + 1, 1);
      const end = `${nextMonth.getFullYear()}-${String(nextMonth.getMonth() + 1).padStart(2, '0')}-01`;
      return { start, end };
    }

    let revenueChartInstance = null;
    let breakdownChartInstance = null;
    let latestMonthSummary = null;
    let latestBreakdown = null;

    async function loadDashboardKpis() {
      const revenueEl = document.getElementById('kpi-revenue');
      const revenueDeltaEl = document.getElementById('kpi-revenue-delta');
      const clientsEl = document.getElementById('kpi-clients');
      const clientsSubEl = document.getElementById('kpi-clients-sub');
      const classesEl = document.getElementById('kpi-classes');
      const payrollEl = document.getElementById('kpi-payroll');
      const payrollSubEl = document.getElementById('kpi-payroll-sub');

      try {
        const res = await fetch(`${API}/api/analytics/dashboard-kpis`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const dto = await res.json();

        if (revenueEl) revenueEl.textContent = fmtVnd(dto.monthlyRevenueVnd ?? 0);
        if (revenueDeltaEl) {
          const delta = dto.monthlyRevenueDeltaPct;
          if (delta === null || delta === undefined) {
            revenueDeltaEl.textContent = 'No prior month comparison yet';
          } else if (delta >= 0) {
            revenueDeltaEl.textContent = `Up ${delta.toFixed(1)}% vs last month`;
          } else {
            revenueDeltaEl.textContent = `Down ${Math.abs(delta).toFixed(1)}% vs last month`;
          }
        }

        if (clientsEl) clientsEl.textContent = fmtInt(dto.activeClients30d ?? 0);
        if (clientsSubEl) clientsSubEl.textContent = 'Booked in the last 30 days';
        if (classesEl) classesEl.textContent = fmtInt(dto.classesThisWeek ?? 0);

        if (payrollEl) payrollEl.textContent = fmtVnd(dto.payrollEstimateVnd ?? 0);
        if (payrollSubEl) {
          if (!dto.payrollEstimatePeriodLabel) {
            payrollSubEl.textContent = 'No payroll run has been computed yet.';
          } else if (dto.payrollEstimateIsLatestComputed) {
            payrollSubEl.textContent = `Using ${dto.payrollEstimatePeriodLabel} while the current month is still open.`;
          } else {
            payrollSubEl.textContent = dto.payrollEstimatePeriodLabel;
          }
        }
      } catch (error) {
        console.warn('Dashboard KPI load failed:', error);
        if (revenueDeltaEl) revenueDeltaEl.textContent = 'Unable to load KPI data';
        if (clientsSubEl) clientsSubEl.textContent = 'Unable to load';
        if (payrollSubEl) payrollSubEl.textContent = 'Unable to load';
      }
    }

    async function loadMonthSummary() {
      const { start, end } = currentMonthRange();
      try {
        const res = await fetch(`${API}/api/analytics/month-summary?startDate=${start}&endDate=${end}`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        latestMonthSummary = await res.json();

        document.getElementById('pulse-totalRevenue').textContent = fmtVnd(latestMonthSummary.totalRevenueVnd ?? 0);
        document.getElementById('pulse-classRevenue').textContent = fmtVnd(latestMonthSummary.singleClassRevenueVnd ?? 0);
        document.getElementById('pulse-packageRevenue').textContent = fmtVnd(latestMonthSummary.packageRevenueVnd ?? 0);
        document.getElementById('pulse-occupancy').textContent = fmtPct(latestMonthSummary.averageOccupancyPct ?? 0);
        document.getElementById('pulse-packagesSold').textContent = fmtInt(latestMonthSummary.packagesSoldCount ?? 0);
        document.getElementById('pulse-newClients').textContent = fmtInt(latestMonthSummary.newClientsCount ?? 0);
        document.getElementById('pulse-dailyRevenue').textContent = fmtVnd(latestMonthSummary.dailyAverageRevenueVnd ?? 0);
        document.getElementById('pulse-creditsOwed').textContent = fmtInt(latestMonthSummary.outstandingPackageCredits ?? 0);
        document.getElementById('pulse-projection').textContent = fmtVnd(latestMonthSummary.monthlyProjectionVnd ?? 0);
        document.getElementById('pulse-totalClasses').textContent = fmtInt(latestMonthSummary.totalClassesHeld ?? 0);
        document.getElementById('pulse-dailyClasses').textContent = `${(Number(latestMonthSummary.dailyAverageClasses) || 0).toFixed(1)} / day`;
        document.getElementById('pulse-merchRevenue').textContent = fmtVnd(latestMonthSummary.merchandiseRevenueVnd ?? 0);

        const packageRevenue = Number(latestMonthSummary.packageRevenueVnd || 0);
        const classRevenue = Number(latestMonthSummary.singleClassRevenueVnd || 0);
        const packageLead = packageRevenue >= classRevenue
          ? `Packages leading by ${fmtVnd(packageRevenue - classRevenue)}`
          : `Classes leading by ${fmtVnd(classRevenue - packageRevenue)}`;
        document.getElementById('dash-focus-value').textContent = fmtPct(latestMonthSummary.averageOccupancyPct ?? 0);
        document.getElementById('dash-focus-sub').textContent = `${packageLead} this month`;
        document.getElementById('dashboardHeroSubtitle').textContent =
          `Revenue, package momentum, occupancy, payroll pressure, and class delivery in one operating view.`;

        renderInsights();
      } catch (error) {
        console.warn('Month summary load failed:', error);
      }
    }

    async function loadRecentInvoices() {
      const tbody = document.getElementById('recent-invoices');
      try {
        const res = await fetch(`${API}/api/invoice/recent?limit=6`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const invoices = await res.json();

        if (!invoices || invoices.length === 0) {
          tbody.innerHTML = `<tr><td colspan="5" class="dashboard-table-empty">No invoices yet. Use POS to start creating transactions.</td></tr>`;
          return;
        }

        tbody.innerHTML = invoices.map((invoice) => {
          const issueDate = new Date(invoice.issueDate).toLocaleDateString('en-US', {
            month: 'short',
            day: 'numeric',
            year: 'numeric',
          });
          const statusClass = invoice.status === 'PAID'
            ? 'badge-success'
            : invoice.status === 'PARTIAL'
              ? 'badge-warning'
              : 'badge-default';
          const statusLabel = invoice.status === 'PARTIAL' ? 'Partial' : (invoice.status || 'Unknown');
          return `
            <tr>
              <td>${escapeHtml(invoice.clientName)}</td>
              <td>${issueDate}</td>
              <td>${escapeHtml(invoice.itemsSummary)}</td>
              <td>${fmtVnd(invoice.totalNet)}</td>
              <td><span class="badge ${statusClass}">${escapeHtml(statusLabel)}</span></td>
            </tr>
          `;
        }).join('');
      } catch (error) {
        console.warn('Recent invoices load failed:', error);
        tbody.innerHTML = `<tr><td colspan="5" class="dashboard-table-empty">Unable to load recent invoices.</td></tr>`;
      }
    }

    async function loadRevenueChart() {
      const ctx = document.getElementById('revenueChart').getContext('2d');
      try {
        const year = new Date().getFullYear();
        const res = await fetch(`${API}/api/analytics/yearly-revenue-expense?year=${year}`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const rows = await res.json();

        if (revenueChartInstance) revenueChartInstance.destroy();
        revenueChartInstance = new Chart(ctx, {
          type: 'bar',
          data: {
            labels: rows.map((row) => row.month),
            datasets: [
              {
                label: 'Revenue',
                data: rows.map((row) => row.revenueVnd),
                backgroundColor: 'rgba(219, 125, 60, 0.82)',
                borderRadius: 8,
                borderSkipped: false,
              },
              {
                label: 'Expenses',
                data: rows.map((row) => row.expensesVnd),
                backgroundColor: 'rgba(75, 104, 135, 0.42)',
                borderRadius: 8,
                borderSkipped: false,
              },
            ],
          },
          options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
              legend: {
                labels: {
                  color: css('--color-text-secondary'),
                  font: { family: 'Inter', size: 11 },
                  boxWidth: 10,
                },
              },
            },
            scales: {
              y: {
                ticks: {
                  color: css('--color-text-muted'),
                  font: { family: 'Inter', size: 10 },
                  callback: (value) => {
                    if (Math.abs(value) >= 1e9) return `${(value / 1e9).toFixed(1)}B`;
                    if (Math.abs(value) >= 1e6) return `${(value / 1e6).toFixed(0)}M`;
                    return value.toLocaleString('en-US');
                  },
                },
                grid: { color: css('--color-border-subtle') },
                border: { display: false },
              },
              x: {
                ticks: {
                  color: css('--color-text-secondary'),
                  font: { family: 'Inter', size: 11 },
                },
                grid: { display: false },
              },
            },
          },
        });
      } catch (error) {
        console.warn('Revenue chart load failed:', error);
      }
    }

    async function loadBreakdownChart() {
      const ctx = document.getElementById('breakdownChart').getContext('2d');
      const { start, end } = currentMonthRange();
      try {
        const res = await fetch(`${API}/api/analytics/revenue-breakdown?startDate=${start}&endDate=${end}`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        latestBreakdown = await res.json();

        const items = [
          { label: 'Classes', value: Number(latestBreakdown.singleClassRevenueVnd || 0), color: css('--color-brand-accent') },
          { label: 'Packages', value: Number(latestBreakdown.packageRevenueVnd || 0), color: '#4ea5d9' },
          { label: 'Merchandise', value: Number(latestBreakdown.merchandiseRevenueVnd || 0), color: '#45b68d' },
          { label: 'Studio Rental', value: Number(latestBreakdown.rentalRevenueVnd || 0), color: '#9b59b6' },
        ].filter((item) => item.value > 0);

        if (breakdownChartInstance) breakdownChartInstance.destroy();
        breakdownChartInstance = new Chart(ctx, {
          type: 'doughnut',
          data: {
            labels: items.length ? items.map((item) => item.label) : ['No revenue'],
            datasets: [
              {
                data: items.length ? items.map((item) => item.value) : [1],
                backgroundColor: items.length ? items.map((item) => item.color) : [css('--color-border-strong')],
                borderWidth: 0,
              },
            ],
          },
          options: {
            responsive: true,
            maintainAspectRatio: false,
            cutout: '68%',
            plugins: {
              legend: {
                position: 'bottom',
                labels: {
                  color: css('--color-text-secondary'),
                  font: { family: 'Inter', size: 11 },
                  boxWidth: 10,
                },
              },
              tooltip: {
                callbacks: {
                  label: (ctx) => `${ctx.label}: ${fmtVnd(ctx.parsed)}`,
                },
              },
            },
          },
        });

        renderInsights();
      } catch (error) {
        console.warn('Revenue breakdown load failed:', error);
      }
    }

    function renderInsights() {
      if (!latestMonthSummary) return;
      const list = document.getElementById('dashboardInsightList');
      const totalRevenue = Number(latestMonthSummary.totalRevenueVnd || 0);
      const packageRevenue = latestBreakdown ? Number(latestBreakdown.packageRevenueVnd || 0) : Number(latestMonthSummary.packageRevenueVnd || 0);
      const classRevenue = latestBreakdown ? Number(latestBreakdown.singleClassRevenueVnd || 0) : Number(latestMonthSummary.singleClassRevenueVnd || 0);
      const occupancy = Number(latestMonthSummary.averageOccupancyPct || 0);
      const projection = Number(latestMonthSummary.monthlyProjectionVnd || 0);
      const packageShare = totalRevenue > 0 ? packageRevenue / totalRevenue : 0;
      const classShare = totalRevenue > 0 ? classRevenue / totalRevenue : 0;

      const insights = [
        {
          title: 'Revenue mix',
          copy: packageShare >= classShare
            ? 'Packages are currently the biggest driver of top-line revenue.'
            : 'Single class sales are currently leading the month.',
          metric: totalRevenue > 0 ? `${Math.round(Math.max(packageShare, classShare) * 100)}% share` : '--',
        },
        {
          title: 'Occupancy health',
          copy: occupancy >= 0.75
            ? 'Classes are filling well. This is a strong signal for upsell and schedule expansion.'
            : 'There is still room to tighten utilization before adding more supply.',
          metric: fmtPct(occupancy),
        },
        {
          title: 'Projection pace',
          copy: 'Projected revenue helps you sense whether the month is ahead or behind pace.',
          metric: fmtVnd(projection),
        },
      ];

      list.innerHTML = insights.map((insight) => `
        <li class="dashboard-insight-item">
          <div>
            <strong>${escapeHtml(insight.title)}</strong>
            <span>${escapeHtml(insight.copy)}</span>
          </div>
          <div class="dashboard-insight-metric">${escapeHtml(insight.metric)}</div>
        </li>
      `).join('');
    }

    async function bootDashboard() {
      await Promise.all([
        loadDashboardKpis(),
        loadMonthSummary(),
        loadRecentInvoices(),
        loadRevenueChart(),
        loadBreakdownChart(),
      ]);
    }

    bootDashboard();
  </script>
</AdminLayout>

