  <script src="https://cdn.jsdelivr.net/npm/chart.js" is:inline></script>
  <script>
    const token = localStorage.getItem('token');
    const API = import.meta.env.PUBLIC_API_URL;

    // Role visibility
    const dashboardRole = (() => {
      try {
        const payload = JSON.parse(atob(token.split('.')[1]));
        return String(
          payload['http://schemas.microsoft.com/ws/2008/06/identity/claims/role'] ||
          payload.role || 'admin'
        ).toLowerCase();
      } catch { return 'admin'; }
    })();
    document.querySelectorAll('[data-dash-role]').forEach((el) => {
      const allowed = el.getAttribute('data-dash-role').toLowerCase().split(',');
      if (!allowed.includes(dashboardRole)) el.style.display = 'none';
    });

    const fmtVnd  = (n) => `${Math.round(Number(n) || 0).toLocaleString('en-US')} VND`;
    const fmtInt  = (n) => `${Math.round(Number(n) || 0).toLocaleString('en-US')}`;
    const fmtPct  = (n) => `${Math.round((Number(n) || 0) * 100)}%`;
    const fmtM    = (n) => {
      const v = Math.round(Number(n) || 0);
      if (Math.abs(v) >= 1e9) return `${(v/1e9).toFixed(1)}B`;
      if (Math.abs(v) >= 1e6) return `${(v/1e6).toFixed(0)}M`;
      return v.toLocaleString('en-US');
    };

    function escapeHtml(v) {
      return String(v || '').replace(/[<>&"']/g, c =>
        ({ '<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&#39;' }[c]));
    }

    function css(name) {
      return getComputedStyle(document.documentElement).getPropertyValue(name).trim();
    }

    function currentMonthRange() {
      const now = new Date();
      const start = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-01`;
      const next  = new Date(now.getFullYear(), now.getMonth()+1, 1);
      const end   = `${next.getFullYear()}-${String(next.getMonth()+1).padStart(2,'0')}-01`;
      return { start, end };
    }

    let revenueChartInstance  = null;
    let breakdownChartInstance = null;
    let latestMonthSummary    = null;
    let latestBreakdown       = null;

    // ── KPIs ──────────────────────────────────────────────────────────────────
    async function loadDashboardKpis() {
      try {
        const res = await fetch(`${API}/api/analytics/dashboard-kpis`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const dto = await res.json();

        setText('kpi-revenue', fmtVnd(dto.monthlyRevenueVnd ?? 0));

        const deltaEl = document.getElementById('kpi-revenue-delta');
        if (deltaEl) {
          const delta = dto.monthlyRevenueDeltaPct;
          if (delta == null) {
            deltaEl.textContent = 'No prior month comparison yet';
            deltaEl.className = 'db-delta flat';
          } else if (delta >= 0) {
            deltaEl.textContent = `▲ ${delta.toFixed(1)}% vs last month`;
            deltaEl.className = 'db-delta up';
          } else {
            deltaEl.textContent = `▼ ${Math.abs(delta).toFixed(1)}% vs last month`;
            deltaEl.className = 'db-delta down';
          }
        }

        setText('kpi-clients', fmtInt(dto.activeClients30d ?? 0));
        setText('kpi-classes', fmtInt(dto.classesThisWeek ?? 0));
        setText('kpi-payroll', fmtVnd(dto.payrollEstimateVnd ?? 0));

        const pSubEl = document.getElementById('kpi-payroll-sub-label');
        if (pSubEl && dto.payrollEstimatePeriodLabel) {
          pSubEl.textContent = dto.payrollEstimatePeriodLabel;
        }
      } catch (e) {
        console.warn('KPI load failed:', e);
      }
    }

    // ── Month summary ─────────────────────────────────────────────────────────
    async function loadMonthSummary() {
      const { start, end } = currentMonthRange();
      try {
        const res = await fetch(`${API}/api/analytics/month-summary?startDate=${start}&endDate=${end}`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        latestMonthSummary = await res.json();

        setText('pulse-totalRevenue',  fmtVnd(latestMonthSummary.totalRevenueVnd ?? 0));
        setText('pulse-classRevenue',  fmtVnd(latestMonthSummary.singleClassRevenueVnd ?? 0));
        setText('pulse-packageRevenue',fmtVnd(latestMonthSummary.packageRevenueVnd ?? 0));
        setText('pulse-occupancy',     fmtPct(latestMonthSummary.averageOccupancyPct ?? 0));
        setText('pulse-packagesSold',  fmtInt(latestMonthSummary.packagesSoldCount ?? 0));
        setText('pulse-newClients',    fmtInt(latestMonthSummary.newClientsCount ?? 0));
        setText('pulse-dailyRevenue',  fmtVnd(latestMonthSummary.dailyAverageRevenueVnd ?? 0));
        setText('pulse-creditsOwed',   fmtInt(latestMonthSummary.outstandingPackageCredits ?? 0));
        setText('pulse-projection',    fmtVnd(latestMonthSummary.monthlyProjectionVnd ?? 0));
        setText('pulse-totalClasses',  fmtInt(latestMonthSummary.totalClassesHeld ?? 0));
        setText('pulse-dailyClasses',  `${(Number(latestMonthSummary.dailyAverageClasses)||0).toFixed(1)} / day`);
        setText('pulse-merchRevenue',  fmtVnd(latestMonthSummary.merchandiseRevenueVnd ?? 0));

        // Update doughnut center
        const centerVal = document.getElementById('doughnut-center-val');
        if (centerVal) centerVal.textContent = fmtM(latestMonthSummary.totalRevenueVnd ?? 0);

        renderInsights();
      } catch (e) {
        console.warn('Month summary failed:', e);
      }
    }

    function setText(id, val) {
      const el = document.getElementById(id);
      if (el) el.textContent = val;
    }

    // ── Recent invoices ───────────────────────────────────────────────────────
    async function loadRecentInvoices() {
      const tbody = document.getElementById('recent-invoices');
      try {
        const res = await fetch(`${API}/api/invoice/recent?limit=6`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const invoices = await res.json();

        if (!invoices?.length) {
          tbody.innerHTML = `<tr><td colspan="5" class="db-table-empty">No invoices yet.</td></tr>`;
          return;
        }
        tbody.innerHTML = invoices.map((inv) => {
          const date = new Date(inv.issueDate).toLocaleDateString('en-US', { month:'short', day:'numeric', year:'numeric' });
          const cls  = inv.status === 'PAID' ? 'badge-success' : inv.status === 'PARTIAL' ? 'badge-warning' : 'badge-default';
          const lbl  = inv.status === 'PARTIAL' ? 'Partial' : (inv.status || 'Unknown');
          return `<tr>
            <td>${escapeHtml(inv.clientName)}</td>
            <td>${date}</td>
            <td>${escapeHtml(inv.itemsSummary)}</td>
            <td>${fmtVnd(inv.totalNet)}</td>
            <td><span class="badge ${cls}">${escapeHtml(lbl)}</span></td>
          </tr>`;
        }).join('');
      } catch (e) {
        console.warn('Invoices failed:', e);
        tbody.innerHTML = `<tr><td colspan="5" class="db-table-empty">Unable to load recent invoices.</td></tr>`;
      }
    }

    // ── Revenue chart (line + area) ───────────────────────────────────────────
    async function loadRevenueChart() {
      const ctx = document.getElementById('revenueChart').getContext('2d');
      try {
        const year = new Date().getFullYear();
        const res = await fetch(`${API}/api/analytics/yearly-revenue-expense?year=${year}`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const rows = await res.json();

        if (revenueChartInstance) revenueChartInstance.destroy();

        const copper = css('--color-brand-accent') || '#db7d3c';
        const blue   = '#4ea5d9';

        // Gradient fill for revenue
        const gradRev = ctx.createLinearGradient(0, 0, 0, 280);
        gradRev.addColorStop(0,   'rgba(219,125,60,0.30)');
        gradRev.addColorStop(1,   'rgba(219,125,60,0.00)');
        const gradExp = ctx.createLinearGradient(0, 0, 0, 280);
        gradExp.addColorStop(0,   'rgba(78,165,217,0.20)');
        gradExp.addColorStop(1,   'rgba(78,165,217,0.00)');

        revenueChartInstance = new Chart(ctx, {
          type: 'line',
          data: {
            labels: rows.map(r => r.month),
            datasets: [
              {
                label: 'Revenue',
                data: rows.map(r => r.revenueVnd),
                borderColor: copper,
                backgroundColor: gradRev,
                borderWidth: 2.5,
                pointRadius: 4,
                pointBackgroundColor: copper,
                pointBorderColor: '#fff',
                pointBorderWidth: 2,
                tension: 0.4,
                fill: true,
              },
              {
                label: 'Expenses',
                data: rows.map(r => r.expensesVnd),
                borderColor: blue,
                backgroundColor: gradExp,
                borderWidth: 2,
                pointRadius: 3,
                pointBackgroundColor: blue,
                pointBorderColor: '#fff',
                pointBorderWidth: 2,
                tension: 0.4,
                fill: true,
              },
            ],
          },
          options: {
            responsive: true,
            maintainAspectRatio: false,
            interaction: { mode: 'index', intersect: false },
            plugins: {
              legend: { display: false },
              tooltip: {
                backgroundColor: css('--color-surface') || '#1a1a1a',
                borderColor: css('--color-border') || '#333',
                borderWidth: 1,
                titleColor: css('--color-text-primary') || '#fff',
                bodyColor: css('--color-text-secondary') || '#aaa',
                padding: 12,
                callbacks: {
                  label: (ctx) => ` ${ctx.dataset.label}: ${fmtM(ctx.parsed.y)} VND`,
                },
              },
            },
            scales: {
              y: {
                ticks: {
                  color: css('--color-text-muted') || '#888',
                  font: { family: 'Inter', size: 10 },
                  callback: (v) => fmtM(v),
                },
                grid: { color: css('--color-border-subtle') || '#333' },
                border: { display: false },
              },
              x: {
                ticks: {
                  color: css('--color-text-secondary') || '#aaa',
                  font: { family: 'Inter', size: 11 },
                },
                grid: { display: false },
                border: { display: false },
              },
            },
          },
        });

        // Custom legend
        const legendWrap = document.getElementById('chart-legend-wrap');
        if (legendWrap) {
          legendWrap.innerHTML = [
            { color: copper, label: 'Revenue' },
            { color: blue,   label: 'Expenses' },
          ].map(item => `
            <div style="display:flex;align-items:center;gap:6px;font-size:12px;color:var(--color-text-secondary);">
              <span style="display:block;width:10px;height:10px;border-radius:50%;background:${item.color};flex-shrink:0;"></span>
              ${item.label}
            </div>
          `).join('');
        }
      } catch (e) {
        console.warn('Revenue chart failed:', e);
      }
    }

    // ── Breakdown doughnut ────────────────────────────────────────────────────
    async function loadBreakdownChart() {
      const ctx = document.getElementById('breakdownChart').getContext('2d');
      const { start, end } = currentMonthRange();
      try {
        const res = await fetch(`${API}/api/analytics/revenue-breakdown?startDate=${start}&endDate=${end}`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        latestBreakdown = await res.json();

        const palette = ['#db7d3c','#4ea5d9','#44be82','#9b59b6'];
        const items = [
          { label: 'Classes',       value: Number(latestBreakdown.singleClassRevenueVnd || 0) },
          { label: 'Packages',      value: Number(latestBreakdown.packageRevenueVnd || 0) },
          { label: 'Merchandise',   value: Number(latestBreakdown.merchandiseRevenueVnd || 0) },
          { label: 'Studio Rental', value: Number(latestBreakdown.rentalRevenueVnd || 0) },
        ].filter(i => i.value > 0).map((i, idx) => ({ ...i, color: palette[idx % palette.length] }));

        if (breakdownChartInstance) breakdownChartInstance.destroy();
        breakdownChartInstance = new Chart(ctx, {
          type: 'doughnut',
          data: {
            labels: items.length ? items.map(i => i.label) : ['No revenue'],
            datasets: [{
              data: items.length ? items.map(i => i.value) : [1],
              backgroundColor: items.length ? items.map(i => i.color) : [css('--color-border-strong') || '#444'],
              borderWidth: 3,
              borderColor: css('--color-surface') || '#111',
              hoverBorderColor: css('--color-surface') || '#111',
            }],
          },
          options: {
            responsive: true,
            maintainAspectRatio: false,
            cutout: '72%',
            plugins: {
              legend: {
                position: 'bottom',
                labels: {
                  color: css('--color-text-secondary') || '#aaa',
                  font: { family: 'Inter', size: 11 },
                  boxWidth: 8,
                  boxHeight: 8,
                  borderRadius: 4,
                  padding: 12,
                  usePointStyle: true,
                  pointStyle: 'circle',
                },
              },
              tooltip: {
                callbacks: {
                  label: (ctx) => ` ${ctx.label}: ${fmtVnd(ctx.parsed)}`,
                },
              },
            },
          },
        });

        renderInsights();
      } catch (e) {
        console.warn('Breakdown chart failed:', e);
      }
    }

    // ── Insights list ─────────────────────────────────────────────────────────
    function renderInsights() {
      if (!latestMonthSummary) return;
      const list = document.getElementById('dashboardInsightList');
      const total      = Number(latestMonthSummary.totalRevenueVnd || 0);
      const pkgRev     = latestBreakdown ? Number(latestBreakdown.packageRevenueVnd || 0) : Number(latestMonthSummary.packageRevenueVnd || 0);
      const clsRev     = latestBreakdown ? Number(latestBreakdown.singleClassRevenueVnd || 0) : Number(latestMonthSummary.singleClassRevenueVnd || 0);
      const occupancy  = Number(latestMonthSummary.averageOccupancyPct || 0);
      const projection = Number(latestMonthSummary.monthlyProjectionVnd || 0);
      const pkgShare   = total > 0 ? pkgRev / total : 0;
      const clsShare   = total > 0 ? clsRev / total : 0;

      const insights = [
        {
          color: '#db7d3c',
          title: 'Revenue mix',
          copy: pkgShare >= clsShare
            ? 'Packages are leading top-line revenue this month.'
            : 'Single class sales are leading the month.',
          metric: total > 0 ? `${Math.round(Math.max(pkgShare, clsShare) * 100)}%` : '--',
        },
        {
          color: '#44be82',
          title: 'Occupancy health',
          copy: occupancy >= 0.75
            ? 'Classes are filling well — strong signal for expansion.'
            : 'Room to tighten utilization before adding supply.',
          metric: fmtPct(occupancy),
        },
        {
          color: '#4ea5d9',
          title: 'Projection pace',
          copy: 'Projected month-end revenue based on current daily pace.',
          metric: fmtM(projection),
        },
      ];

      list.innerHTML = insights.map(ins => `
        <li class="db-insight-item">
          <div class="db-insight-item-left">
            <div class="db-insight-dot" style="background:${ins.color}"></div>
            <div>
              <div class="db-insight-title">${escapeHtml(ins.title)}</div>
              <div class="db-insight-copy">${escapeHtml(ins.copy)}</div>
            </div>
          </div>
          <div class="db-insight-metric">${escapeHtml(ins.metric)}</div>
        </li>
      `).join('');
    }

    // ── Boot ──────────────────────────────────────────────────────────────────
    Promise.all([
      loadDashboardKpis(),
      loadMonthSummary(),
      loadRecentInvoices(),
      loadRevenueChart(),
      loadBreakdownChart(),
    ]);
  </script>
</AdminLayout>

