---
import AdminLayout from '../../layouts/AdminLayout.astro';
---
<AdminLayout title="Dashboard" activePage="dashboard">
  <style is:global>
    /* ── Shell ───────────────────────────────────────────────────────────────── */
    .db { display: grid; gap: 24px; }

    /* ── Hero banner ─────────────────────────────────────────────────────────── */
    .db-hero {
      position: relative;
      overflow: hidden;
      border-radius: 24px;
      padding: 32px 36px;
      background:
        radial-gradient(ellipse at 80% 0%, rgba(219,125,60,0.35) 0%, transparent 55%),
        radial-gradient(ellipse at 0% 100%, rgba(219,125,60,0.12) 0%, transparent 40%),
        var(--color-surface);
      border: 1px solid var(--color-border);
      box-shadow: var(--shadow-card);
    }
    .db-hero::before {
      content: '';
      position: absolute;
      top: 0; left: 0; right: 0;
      height: 3px;
      background: linear-gradient(90deg, var(--color-brand-accent), #f0b278, transparent);
    }
    .db-hero-inner {
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      gap: 32px;
      flex-wrap: wrap;
    }
    .db-hero-left {}
    .db-hero-eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      font-size: 11px;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--color-brand-accent);
      margin-bottom: 10px;
    }
    .db-hero-eyebrow::before {
      content: '';
      display: block;
      width: 6px; height: 6px;
      border-radius: 50%;
      background: var(--color-brand-accent);
    }
    .db-hero-value {
      font-size: clamp(36px, 5vw, 56px);
      font-weight: 900;
      letter-spacing: -0.06em;
      line-height: 1;
      color: var(--color-text-primary);
    }
    .db-hero-label {
      margin-top: 8px;
      font-size: 14px;
      color: var(--color-text-secondary);
    }
    .db-hero-right {
      display: flex;
      gap: 20px;
      flex-wrap: wrap;
    }
    .db-hero-chip {
      text-align: right;
    }
    .db-hero-chip-value {
      font-size: 22px;
      font-weight: 800;
      letter-spacing: -0.04em;
      color: var(--color-text-primary);
    }
    .db-hero-chip-label {
      font-size: 11px;
      text-transform: uppercase;
      letter-spacing: 0.1em;
      color: var(--color-text-muted);
      margin-top: 2px;
    }
    .db-delta {
      display: inline-flex;
      align-items: center;
      gap: 5px;
      padding: 5px 10px;
      border-radius: 999px;
      font-size: 12px;
      font-weight: 700;
      margin-top: 10px;
    }
    .db-delta.up   { background: rgba(68,190,130,0.14); color: #44be82; }
    .db-delta.down { background: rgba(239,83,80,0.14);  color: #ef5350; }
    .db-delta.flat { background: var(--color-surface-raised); color: var(--color-text-muted); }

    /* ── KPI Strip ───────────────────────────────────────────────────────────── */
    .db-kpi-strip {
      display: grid;
      grid-template-columns: repeat(4, minmax(0,1fr));
      gap: 14px;
    }
    .db-kpi {
      padding: 20px 20px 18px;
      border-radius: 18px;
      border: 1px solid var(--color-border);
      background: var(--color-surface);
      box-shadow: var(--shadow-card);
      display: flex;
      flex-direction: column;
      gap: 0;
      position: relative;
      overflow: hidden;
    }
    .db-kpi::after {
      content: '';
      position: absolute;
      top: 0; left: 0;
      width: 3px; height: 100%;
      border-radius: 18px 0 0 18px;
      background: var(--kpi-color, var(--color-brand-accent));
    }
    .db-kpi-icon {
      width: 36px; height: 36px;
      border-radius: 10px;
      display: flex; align-items: center; justify-content: center;
      background: color-mix(in srgb, var(--kpi-color, var(--color-brand-accent)) 15%, transparent);
      color: var(--kpi-color, var(--color-brand-accent));
      font-size: 16px;
      margin-bottom: 14px;
      flex-shrink: 0;
    }
    .db-kpi-label {
      font-size: 11px;
      text-transform: uppercase;
      letter-spacing: 0.11em;
      color: var(--color-text-muted);
      font-weight: 600;
    }
    .db-kpi-value {
      margin-top: 6px;
      font-size: 26px;
      font-weight: 800;
      letter-spacing: -0.05em;
      line-height: 1;
      color: var(--color-text-primary);
    }
    .db-kpi-sub {
      margin-top: 8px;
      font-size: 12px;
      color: var(--color-text-secondary);
      line-height: 1.4;
    }

    /* ── Charts row ──────────────────────────────────────────────────────────── */
    .db-charts {
      display: grid;
      grid-template-columns: minmax(0, 1.6fr) minmax(300px, 1fr);
      gap: 20px;
    }
    .db-card {
      border-radius: 22px;
      border: 1px solid var(--color-border);
      background: var(--color-surface);
      box-shadow: var(--shadow-card);
      overflow: hidden;
    }
    .db-card-head {
      padding: 22px 24px 16px;
      border-bottom: 1px solid var(--color-border-subtle);
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 16px;
    }
    .db-card-eyebrow {
      font-size: 10px;
      font-weight: 700;
      letter-spacing: 0.14em;
      text-transform: uppercase;
      color: var(--color-brand-accent);
      margin-bottom: 4px;
    }
    .db-card-title {
      font-size: 16px;
      font-weight: 700;
      letter-spacing: -0.03em;
      color: var(--color-text-primary);
    }
    .db-card-sub {
      margin-top: 4px;
      font-size: 12px;
      color: var(--color-text-muted);
    }
    .db-card-body { padding: 24px; }
    .db-chart-wrap { height: 280px; }

    /* ── Doughnut card ───────────────────────────────────────────────────────── */
    .db-doughnut-wrap {
      position: relative;
      height: 200px;
      margin-bottom: 20px;
    }
    .db-doughnut-center {
      position: absolute;
      inset: 0;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      pointer-events: none;
    }
    .db-doughnut-center-value {
      font-size: 20px;
      font-weight: 800;
      letter-spacing: -0.04em;
      color: var(--color-text-primary);
    }
    .db-doughnut-center-label {
      font-size: 10px;
      text-transform: uppercase;
      letter-spacing: 0.1em;
      color: var(--color-text-muted);
      margin-top: 2px;
    }

    /* ── Insight rows ────────────────────────────────────────────────────────── */
    .db-insight-list { list-style: none; padding: 0; margin: 0; display: grid; gap: 10px; }
    .db-insight-item {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      padding: 12px 14px;
      border-radius: 12px;
      background: var(--color-surface-raised);
      border: 1px solid var(--color-border-subtle);
    }
    .db-insight-item-left { display: flex; align-items: center; gap: 10px; }
    .db-insight-dot {
      width: 8px; height: 8px;
      border-radius: 50%;
      flex-shrink: 0;
    }
    .db-insight-title { font-size: 13px; font-weight: 600; color: var(--color-text-primary); }
    .db-insight-copy { font-size: 11px; color: var(--color-text-secondary); margin-top: 1px; line-height: 1.4; }
    .db-insight-metric { font-size: 12px; font-weight: 700; color: var(--color-brand-accent); white-space: nowrap; }

    /* ── Pulse stats ─────────────────────────────────────────────────────────── */
    .db-pulse-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0,1fr));
      gap: 14px;
    }
    .db-pulse {
      padding: 20px;
      border-radius: 18px;
      border: 1px solid var(--color-border);
      background: var(--color-surface);
      box-shadow: var(--shadow-card);
    }
    .db-pulse-top {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 8px;
      margin-bottom: 12px;
    }
    .db-pulse-label {
      font-size: 11px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.11em;
      color: var(--color-text-muted);
    }
    .db-pulse-badge {
      width: 28px; height: 28px;
      border-radius: 8px;
      display: flex; align-items: center; justify-content: center;
      font-size: 13px;
      background: color-mix(in srgb, var(--pulse-color, var(--color-brand-accent)) 15%, transparent);
      color: var(--pulse-color, var(--color-brand-accent));
    }
    .db-pulse-value {
      font-size: 22px;
      font-weight: 800;
      letter-spacing: -0.05em;
      color: var(--color-text-primary);
      line-height: 1;
    }
    .db-pulse-sub {
      margin-top: 6px;
      font-size: 11px;
      color: var(--color-text-secondary);
      line-height: 1.4;
    }

    /* ── Bottom grid ─────────────────────────────────────────────────────────── */
    .db-bottom {
      display: grid;
      grid-template-columns: minmax(0, 1.55fr) minmax(280px, 0.85fr);
      gap: 20px;
    }
    .db-table-empty {
      text-align: center;
      padding: 32px !important;
      color: var(--color-text-muted);
    }

    /* ── Studio pulse chips ──────────────────────────────────────────────────── */
    .db-op-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 12px;
    }
    .db-op-chip {
      padding: 16px;
      border-radius: 14px;
      background: var(--color-surface-raised);
      border: 1px solid var(--color-border-subtle);
      display: flex;
      flex-direction: column;
      gap: 6px;
    }
    .db-op-chip-label {
      font-size: 10px;
      text-transform: uppercase;
      letter-spacing: 0.12em;
      color: var(--color-text-muted);
      font-weight: 600;
    }
    .db-op-chip-value {
      font-size: 18px;
      font-weight: 800;
      letter-spacing: -0.04em;
      color: var(--color-text-primary);
    }
    .db-op-chip-sub {
      font-size: 11px;
      color: var(--color-text-secondary);
      line-height: 1.4;
    }

    /* ── Responsive ──────────────────────────────────────────────────────────── */
    @media (max-width: 1280px) {
      .db-charts, .db-bottom { grid-template-columns: 1fr; }
    }
    @media (max-width: 900px) {
      .db-kpi-strip, .db-pulse-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }
    }
    @media (max-width: 560px) {
      .db-kpi-strip, .db-pulse-grid, .db-op-grid { grid-template-columns: 1fr; }
      .db-hero { padding: 24px 20px; }
      .db-hero-right { display: none; }
    }
  </style>

  <div class="db">

    <!-- ── Hero ─────────────────────────────────────────────────────────────── -->
    <div class="db-hero" data-dash-role="admin,accountant">
      <div class="db-hero-inner">
        <div class="db-hero-left">
          <div class="db-hero-eyebrow">Month Revenue</div>
          <div class="db-hero-value" id="kpi-revenue">--</div>
          <div class="db-hero-label">Total revenue recorded this month</div>
          <div class="db-delta flat" id="kpi-revenue-delta">Loading...</div>
        </div>
        <div class="db-hero-right">
          <div class="db-hero-chip">
            <div class="db-hero-chip-value" id="kpi-clients">--</div>
            <div class="db-hero-chip-label">Active Clients</div>
          </div>
          <div class="db-hero-chip">
            <div class="db-hero-chip-value" id="kpi-classes">--</div>
            <div class="db-hero-chip-label">Classes This Week</div>
          </div>
          <div class="db-hero-chip" data-dash-role="admin,accountant">
            <div class="db-hero-chip-value" id="kpi-payroll">--</div>
            <div class="db-hero-chip-label" id="kpi-payroll-sub-label">Payroll Estimate</div>
          </div>
        </div>
      </div>
    </div>

    <!-- ── KPI Strip ─────────────────────────────────────────────────────────── -->
    <div class="db-kpi-strip">
      <div class="db-kpi" style="--kpi-color:#db7d3c;">
        <div class="db-kpi-icon">📦</div>
        <div class="db-kpi-label">Package Revenue</div>
        <div class="db-kpi-value" id="pulse-packageRevenue">--</div>
        <div class="db-kpi-sub">Package sales captured this month</div>
      </div>
      <div class="db-kpi" style="--kpi-color:#4ea5d9;">
        <div class="db-kpi-icon">🎯</div>
        <div class="db-kpi-label">Class Revenue</div>
        <div class="db-kpi-value" id="pulse-classRevenue">--</div>
        <div class="db-kpi-sub">Drop-in and single-class checkouts</div>
      </div>
      <div class="db-kpi" style="--kpi-color:#44be82;">
        <div class="db-kpi-icon">📊</div>
        <div class="db-kpi-label">Avg Occupancy</div>
        <div class="db-kpi-value" id="pulse-occupancy">--</div>
        <div class="db-kpi-sub">How full your classes are running</div>
      </div>
      <div class="db-kpi" style="--kpi-color:#9b59b6;">
        <div class="db-kpi-icon">🎟️</div>
        <div class="db-kpi-label">Credits Owed</div>
        <div class="db-kpi-value" id="pulse-creditsOwed">--</div>
        <div class="db-kpi-sub">Remaining package credits to deliver</div>
      </div>
    </div>

    <!-- ── Charts row ───────────────────────────────────────────────────────── -->
    <div class="db-charts">
      <div class="db-card">
        <div class="db-card-head">
          <div>
            <div class="db-card-eyebrow">Finance Trend</div>
            <div class="db-card-title">Revenue vs Expenses</div>
            <div class="db-card-sub">Running totals across the current year</div>
          </div>
          <div id="chart-legend-wrap" style="display:flex;gap:14px;align-items:center;flex-shrink:0;"></div>
        </div>
        <div class="db-card-body">
          <div class="db-chart-wrap">
            <canvas id="revenueChart"></canvas>
          </div>
        </div>
      </div>

      <div class="db-card">
        <div class="db-card-head">
          <div>
            <div class="db-card-eyebrow">Sales Mix</div>
            <div class="db-card-title">What's Driving Revenue</div>
            <div class="db-card-sub">Classes vs packages vs other this month</div>
          </div>
        </div>
        <div class="db-card-body">
          <div class="db-doughnut-wrap">
            <canvas id="breakdownChart"></canvas>
            <div class="db-doughnut-center">
              <div class="db-doughnut-center-value" id="doughnut-center-val">--</div>
              <div class="db-doughnut-center-label">Total</div>
            </div>
          </div>
          <ul class="db-insight-list" id="dashboardInsightList">
            <li class="db-insight-item">
              <div class="db-insight-item-left">
                <div class="db-insight-dot" style="background:var(--color-border-strong)"></div>
                <div><div class="db-insight-title">Loading insights</div><div class="db-insight-copy">Pulling live data...</div></div>
              </div>
              <div class="db-insight-metric">--</div>
            </li>
          </ul>
        </div>
      </div>
    </div>

    <!-- ── Pulse stats ───────────────────────────────────────────────────────── -->
    <div class="db-pulse-grid">
      <div class="db-pulse" style="--pulse-color:#db7d3c;">
        <div class="db-pulse-top">
          <div class="db-pulse-label">Month Revenue</div>
          <div class="db-pulse-badge">💰</div>
        </div>
        <div class="db-pulse-value" id="pulse-totalRevenue">--</div>
        <div class="db-pulse-sub">Total revenue in the selected month</div>
      </div>
      <div class="db-pulse" style="--pulse-color:#4ea5d9;">
        <div class="db-pulse-top">
          <div class="db-pulse-label">Packages Sold</div>
          <div class="db-pulse-badge">📋</div>
        </div>
        <div class="db-pulse-value" id="pulse-packagesSold">--</div>
        <div class="db-pulse-sub">Completed package purchases this month</div>
      </div>
      <div class="db-pulse" style="--pulse-color:#44be82;">
        <div class="db-pulse-top">
          <div class="db-pulse-label">New Clients</div>
          <div class="db-pulse-badge">👤</div>
        </div>
        <div class="db-pulse-value" id="pulse-newClients">--</div>
        <div class="db-pulse-sub">Fresh customers in the month window</div>
      </div>
      <div class="db-pulse" style="--pulse-color:#f0b278;">
        <div class="db-pulse-top">
          <div class="db-pulse-label">Daily Avg Revenue</div>
          <div class="db-pulse-badge">📈</div>
        </div>
        <div class="db-pulse-value" id="pulse-dailyRevenue">--</div>
        <div class="db-pulse-sub">Typical revenue per active day</div>
      </div>
    </div>

    <!-- ── Bottom row ────────────────────────────────────────────────────────── -->
    <div class="db-bottom">
      <div class="db-card">
        <div class="db-card-head">
          <div>
            <div class="db-card-eyebrow">Live Activity</div>
            <div class="db-card-title">Recent Invoices</div>
            <div class="db-card-sub">Latest transactions from point of sale</div>
          </div>
          <a href="/admin/invoices" class="btn btn-secondary btn-sm">View all</a>
        </div>
        <div class="db-card-body" style="padding:0;">
          <div class="table-responsive">
            <table class="data-table">
              <thead>
                <tr>
                  <th>Client</th>
                  <th>Date</th>
                  <th>Items</th>
                  <th>Amount</th>
                  <th>Status</th>
                </tr>
              </thead>
              <tbody id="recent-invoices">
                <tr><td colspan="5" class="db-table-empty">Loading transactions...</td></tr>
              </tbody>
            </table>
          </div>
        </div>
      </div>

      <div class="db-card">
        <div class="db-card-head">
          <div>
            <div class="db-card-eyebrow">Operating Notes</div>
            <div class="db-card-title">Studio Pulse</div>
            <div class="db-card-sub">A tighter operational read on where the month is landing</div>
          </div>
        </div>
        <div class="db-card-body">
          <div class="db-op-grid">
            <div class="db-op-chip">
              <div class="db-op-chip-label">Monthly Projection</div>
              <div class="db-op-chip-value" id="pulse-projection">--</div>
              <div class="db-op-chip-sub">Projected month-end revenue at current pace</div>
            </div>
            <div class="db-op-chip">
              <div class="db-op-chip-label">Classes Held</div>
              <div class="db-op-chip-value" id="pulse-totalClasses">--</div>
              <div class="db-op-chip-sub">Actual delivery in the month window</div>
            </div>
            <div class="db-op-chip">
              <div class="db-op-chip-label">Daily Avg Classes</div>
              <div class="db-op-chip-value" id="pulse-dailyClasses">--</div>
              <div class="db-op-chip-sub">Schedule density check</div>
            </div>
            <div class="db-op-chip">
              <div class="db-op-chip-label">Merch Revenue</div>
              <div class="db-op-chip-value" id="pulse-merchRevenue">--</div>
              <div class="db-op-chip-sub">Accessory and product sales</div>
            </div>
          </div>
        </div>
      </div>
    </div>

  </div><!-- .db -->

  <script src="https://cdn.jsdelivr.net/npm/chart.js" is:inline></script>
  <script>
    const token = localStorage.getItem('token');
    const API = import.meta.env.PUBLIC_API_URL;

    // Role visibility
    const dashboardRole = (() => {
      try {
        const payload = JSON.parse(atob(token.split('.')[1]));
        return String(
          payload['http://schemas.microsoft.com/ws/2008/06/identity/claims/role'] ||
          payload.role || 'admin'
        ).toLowerCase();
      } catch { return 'admin'; }
    })();
    document.querySelectorAll('[data-dash-role]').forEach((el) => {
      const allowed = el.getAttribute('data-dash-role').toLowerCase().split(',');
      if (!allowed.includes(dashboardRole)) el.style.display = 'none';
    });

    const fmtVnd  = (n) => `${Math.round(Number(n) || 0).toLocaleString('en-US')} VND`;
    const fmtInt  = (n) => `${Math.round(Number(n) || 0).toLocaleString('en-US')}`;
    const fmtPct  = (n) => `${Math.round((Number(n) || 0) * 100)}%`;
    const fmtM    = (n) => {
      const v = Math.round(Number(n) || 0);
      if (Math.abs(v) >= 1e9) return `${(v/1e9).toFixed(1)}B`;
      if (Math.abs(v) >= 1e6) return `${(v/1e6).toFixed(0)}M`;
      return v.toLocaleString('en-US');
    };

    function escapeHtml(v) {
      return String(v || '').replace(/[<>&"']/g, c =>
        ({ '<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&#39;' }[c]));
    }

    function css(name) {
      return getComputedStyle(document.documentElement).getPropertyValue(name).trim();
    }

    function currentMonthRange() {
      const now = new Date();
      const start = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-01`;
      const next  = new Date(now.getFullYear(), now.getMonth()+1, 1);
      const end   = `${next.getFullYear()}-${String(next.getMonth()+1).padStart(2,'0')}-01`;
      return { start, end };
    }

    let revenueChartInstance  = null;
    let breakdownChartInstance = null;
    let latestMonthSummary    = null;
    let latestBreakdown       = null;

    // ── KPIs ──────────────────────────────────────────────────────────────────
    async function loadDashboardKpis() {
      try {
        const res = await fetch(`${API}/api/analytics/dashboard-kpis`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const dto = await res.json();

        setText('kpi-revenue', fmtVnd(dto.monthlyRevenueVnd ?? 0));

        const deltaEl = document.getElementById('kpi-revenue-delta');
        if (deltaEl) {
          const delta = dto.monthlyRevenueDeltaPct;
          if (delta == null) {
            deltaEl.textContent = 'No prior month comparison yet';
            deltaEl.className = 'db-delta flat';
          } else if (delta >= 0) {
            deltaEl.textContent = `▲ ${delta.toFixed(1)}% vs last month`;
            deltaEl.className = 'db-delta up';
          } else {
            deltaEl.textContent = `▼ ${Math.abs(delta).toFixed(1)}% vs last month`;
            deltaEl.className = 'db-delta down';
          }
        }

        setText('kpi-clients', fmtInt(dto.activeClients30d ?? 0));
        setText('kpi-classes', fmtInt(dto.classesThisWeek ?? 0));
        setText('kpi-payroll', fmtVnd(dto.payrollEstimateVnd ?? 0));

        const pSubEl = document.getElementById('kpi-payroll-sub-label');
        if (pSubEl && dto.payrollEstimatePeriodLabel) {
          pSubEl.textContent = dto.payrollEstimatePeriodLabel;
        }
      } catch (e) {
        console.warn('KPI load failed:', e);
      }
    }

    // ── Month summary ─────────────────────────────────────────────────────────
    async function loadMonthSummary() {
      const { start, end } = currentMonthRange();
      try {
        const res = await fetch(`${API}/api/analytics/month-summary?startDate=${start}&endDate=${end}`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        latestMonthSummary = await res.json();

        setText('pulse-totalRevenue',  fmtVnd(latestMonthSummary.totalRevenueVnd ?? 0));
        setText('pulse-classRevenue',  fmtVnd(latestMonthSummary.singleClassRevenueVnd ?? 0));
        setText('pulse-packageRevenue',fmtVnd(latestMonthSummary.packageRevenueVnd ?? 0));
        setText('pulse-occupancy',     fmtPct(latestMonthSummary.averageOccupancyPct ?? 0));
        setText('pulse-packagesSold',  fmtInt(latestMonthSummary.packagesSoldCount ?? 0));
        setText('pulse-newClients',    fmtInt(latestMonthSummary.newClientsCount ?? 0));
        setText('pulse-dailyRevenue',  fmtVnd(latestMonthSummary.dailyAverageRevenueVnd ?? 0));
        setText('pulse-creditsOwed',   fmtInt(latestMonthSummary.outstandingPackageCredits ?? 0));
        setText('pulse-projection',    fmtVnd(latestMonthSummary.monthlyProjectionVnd ?? 0));
        setText('pulse-totalClasses',  fmtInt(latestMonthSummary.totalClassesHeld ?? 0));
        setText('pulse-dailyClasses',  `${(Number(latestMonthSummary.dailyAverageClasses)||0).toFixed(1)} / day`);
        setText('pulse-merchRevenue',  fmtVnd(latestMonthSummary.merchandiseRevenueVnd ?? 0));

        // Update doughnut center
        const centerVal = document.getElementById('doughnut-center-val');
        if (centerVal) centerVal.textContent = fmtM(latestMonthSummary.totalRevenueVnd ?? 0);

        renderInsights();
      } catch (e) {
        console.warn('Month summary failed:', e);
      }
    }

    function setText(id, val) {
      const el = document.getElementById(id);
      if (el) el.textContent = val;
    }

    // ── Recent invoices ───────────────────────────────────────────────────────
    async function loadRecentInvoices() {
      const tbody = document.getElementById('recent-invoices');
      try {
        const res = await fetch(`${API}/api/invoice/recent?limit=6`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const invoices = await res.json();

        if (!invoices?.length) {
          tbody.innerHTML = `<tr><td colspan="5" class="db-table-empty">No invoices yet.</td></tr>`;
          return;
        }
        tbody.innerHTML = invoices.map((inv) => {
          const date = new Date(inv.issueDate).toLocaleDateString('en-US', { month:'short', day:'numeric', year:'numeric' });
          const cls  = inv.status === 'PAID' ? 'badge-success' : inv.status === 'PARTIAL' ? 'badge-warning' : 'badge-default';
          const lbl  = inv.status === 'PARTIAL' ? 'Partial' : (inv.status || 'Unknown');
          return `<tr>
            <td>${escapeHtml(inv.clientName)}</td>
            <td>${date}</td>
            <td>${escapeHtml(inv.itemsSummary)}</td>
            <td>${fmtVnd(inv.totalNet)}</td>
            <td><span class="badge ${cls}">${escapeHtml(lbl)}</span></td>
          </tr>`;
        }).join('');
      } catch (e) {
        console.warn('Invoices failed:', e);
        tbody.innerHTML = `<tr><td colspan="5" class="db-table-empty">Unable to load recent invoices.</td></tr>`;
      }
    }

    // ── Revenue chart (line + area) ───────────────────────────────────────────
    async function loadRevenueChart() {
      const ctx = document.getElementById('revenueChart').getContext('2d');
      try {
        const year = new Date().getFullYear();
        const res = await fetch(`${API}/api/analytics/yearly-revenue-expense?year=${year}`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const rows = await res.json();

        if (revenueChartInstance) revenueChartInstance.destroy();

        const copper = css('--color-brand-accent') || '#db7d3c';
        const blue   = '#4ea5d9';

        // Gradient fill for revenue
        const gradRev = ctx.createLinearGradient(0, 0, 0, 280);
        gradRev.addColorStop(0,   'rgba(219,125,60,0.30)');
        gradRev.addColorStop(1,   'rgba(219,125,60,0.00)');
        const gradExp = ctx.createLinearGradient(0, 0, 0, 280);
        gradExp.addColorStop(0,   'rgba(78,165,217,0.20)');
        gradExp.addColorStop(1,   'rgba(78,165,217,0.00)');

        revenueChartInstance = new Chart(ctx, {
          type: 'line',
          data: {
            labels: rows.map(r => r.month),
            datasets: [
              {
                label: 'Revenue',
                data: rows.map(r => r.revenueVnd),
                borderColor: copper,
                backgroundColor: gradRev,
                borderWidth: 2.5,
                pointRadius: 4,
                pointBackgroundColor: copper,
                pointBorderColor: '#fff',
                pointBorderWidth: 2,
                tension: 0.4,
                fill: true,
              },
              {
                label: 'Expenses',
                data: rows.map(r => r.expensesVnd),
                borderColor: blue,
                backgroundColor: gradExp,
                borderWidth: 2,
                pointRadius: 3,
                pointBackgroundColor: blue,
                pointBorderColor: '#fff',
                pointBorderWidth: 2,
                tension: 0.4,
                fill: true,
              },
            ],
          },
          options: {
            responsive: true,
            maintainAspectRatio: false,
            interaction: { mode: 'index', intersect: false },
            plugins: {
              legend: { display: false },
              tooltip: {
                backgroundColor: css('--color-surface') || '#1a1a1a',
                borderColor: css('--color-border') || '#333',
                borderWidth: 1,
                titleColor: css('--color-text-primary') || '#fff',
                bodyColor: css('--color-text-secondary') || '#aaa',
                padding: 12,
                callbacks: {
                  label: (ctx) => ` ${ctx.dataset.label}: ${fmtM(ctx.parsed.y)} VND`,
                },
              },
            },
            scales: {
              y: {
                ticks: {
                  color: css('--color-text-muted') || '#888',
                  font: { family: 'Inter', size: 10 },
                  callback: (v) => fmtM(v),
                },
                grid: { color: css('--color-border-subtle') || '#333' },
                border: { display: false },
              },
              x: {
                ticks: {
                  color: css('--color-text-secondary') || '#aaa',
                  font: { family: 'Inter', size: 11 },
                },
                grid: { display: false },
                border: { display: false },
              },
            },
          },
        });

        // Custom legend
        const legendWrap = document.getElementById('chart-legend-wrap');
        if (legendWrap) {
          legendWrap.innerHTML = [
            { color: copper, label: 'Revenue' },
            { color: blue,   label: 'Expenses' },
          ].map(item => `
            <div style="display:flex;align-items:center;gap:6px;font-size:12px;color:var(--color-text-secondary);">
              <span style="display:block;width:10px;height:10px;border-radius:50%;background:${item.color};flex-shrink:0;"></span>
              ${item.label}
            </div>
          `).join('');
        }
      } catch (e) {
        console.warn('Revenue chart failed:', e);
      }
    }

    // ── Breakdown doughnut ────────────────────────────────────────────────────
    async function loadBreakdownChart() {
      const ctx = document.getElementById('breakdownChart').getContext('2d');
      const { start, end } = currentMonthRange();
      try {
        const res = await fetch(`${API}/api/analytics/revenue-breakdown?startDate=${start}&endDate=${end}`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        latestBreakdown = await res.json();

        const palette = ['#db7d3c','#4ea5d9','#44be82','#9b59b6'];
        const items = [
          { label: 'Classes',       value: Number(latestBreakdown.singleClassRevenueVnd || 0) },
          { label: 'Packages',      value: Number(latestBreakdown.packageRevenueVnd || 0) },
          { label: 'Merchandise',   value: Number(latestBreakdown.merchandiseRevenueVnd || 0) },
          { label: 'Studio Rental', value: Number(latestBreakdown.rentalRevenueVnd || 0) },
        ].filter(i => i.value > 0).map((i, idx) => ({ ...i, color: palette[idx % palette.length] }));

        if (breakdownChartInstance) breakdownChartInstance.destroy();
        breakdownChartInstance = new Chart(ctx, {
          type: 'doughnut',
          data: {
            labels: items.length ? items.map(i => i.label) : ['No revenue'],
            datasets: [{
              data: items.length ? items.map(i => i.value) : [1],
              backgroundColor: items.length ? items.map(i => i.color) : [css('--color-border-strong') || '#444'],
              borderWidth: 3,
              borderColor: css('--color-surface') || '#111',
              hoverBorderColor: css('--color-surface') || '#111',
            }],
          },
          options: {
            responsive: true,
            maintainAspectRatio: false,
            cutout: '72%',
            plugins: {
              legend: {
                position: 'bottom',
                labels: {
                  color: css('--color-text-secondary') || '#aaa',
                  font: { family: 'Inter', size: 11 },
                  boxWidth: 8,
                  boxHeight: 8,
                  borderRadius: 4,
                  padding: 12,
                  usePointStyle: true,
                  pointStyle: 'circle',
                },
              },
              tooltip: {
                callbacks: {
                  label: (ctx) => ` ${ctx.label}: ${fmtVnd(ctx.parsed)}`,
                },
              },
            },
          },
        });

        renderInsights();
      } catch (e) {
        console.warn('Breakdown chart failed:', e);
      }
    }

    // ── Insights list ─────────────────────────────────────────────────────────
    function renderInsights() {
      if (!latestMonthSummary) return;
      const list = document.getElementById('dashboardInsightList');
      const total      = Number(latestMonthSummary.totalRevenueVnd || 0);
      const pkgRev     = latestBreakdown ? Number(latestBreakdown.packageRevenueVnd || 0) : Number(latestMonthSummary.packageRevenueVnd || 0);
      const clsRev     = latestBreakdown ? Number(latestBreakdown.singleClassRevenueVnd || 0) : Number(latestMonthSummary.singleClassRevenueVnd || 0);
      const occupancy  = Number(latestMonthSummary.averageOccupancyPct || 0);
      const projection = Number(latestMonthSummary.monthlyProjectionVnd || 0);
      const pkgShare   = total > 0 ? pkgRev / total : 0;
      const clsShare   = total > 0 ? clsRev / total : 0;

      const insights = [
        {
          color: '#db7d3c',
          title: 'Revenue mix',
          copy: pkgShare >= clsShare
            ? 'Packages are leading top-line revenue this month.'
            : 'Single class sales are leading the month.',
          metric: total > 0 ? `${Math.round(Math.max(pkgShare, clsShare) * 100)}%` : '--',
        },
        {
          color: '#44be82',
          title: 'Occupancy health',
          copy: occupancy >= 0.75
            ? 'Classes are filling well — strong signal for expansion.'
            : 'Room to tighten utilization before adding supply.',
          metric: fmtPct(occupancy),
        },
        {
          color: '#4ea5d9',
          title: 'Projection pace',
          copy: 'Projected month-end revenue based on current daily pace.',
          metric: fmtM(projection),
        },
      ];

      list.innerHTML = insights.map(ins => `
        <li class="db-insight-item">
          <div class="db-insight-item-left">
            <div class="db-insight-dot" style="background:${ins.color}"></div>
            <div>
              <div class="db-insight-title">${escapeHtml(ins.title)}</div>
              <div class="db-insight-copy">${escapeHtml(ins.copy)}</div>
            </div>
          </div>
          <div class="db-insight-metric">${escapeHtml(ins.metric)}</div>
        </li>
      `).join('');
    }

    // ── Boot ──────────────────────────────────────────────────────────────────
    Promise.all([
      loadDashboardKpis(),
      loadMonthSummary(),
      loadRecentInvoices(),
      loadRevenueChart(),
      loadBreakdownChart(),
    ]);
  </script>
</AdminLayout>

