---
import AdminLayout from "../../layouts/AdminLayout.astro";
---

<AdminLayout title="KPI Bonus" activePage="kpi-bonus">
  <div class="kpi-page-shell">
    <div class="kpi-page-header">
      <div>
        <div class="page-title">Performance Bonus</div>
        <div class="page-subtitle">
          Complete tasks, hit targets and unlock your monthly bonus.
        </div>
      </div>
      <div class="kpi-page-actions">
        <label class="kpi-action-control kpi-action-control-month">
          <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <rect x="3" y="4" width="18" height="18" rx="2"></rect>
            <line x1="16" y1="2" x2="16" y2="6"></line>
            <line x1="8" y1="2" x2="8" y2="6"></line>
            <line x1="3" y1="10" x2="21" y2="10"></line>
          </svg>
          <span id="monthRangeText">Loading month</span>
          <input type="month" id="monthPicker" class="kpi-hidden-month-input" />
        </label>

        <label id="staffPickerWrap" class="kpi-action-control" style="display:none;">
          <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <path d="M16 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"></path>
            <circle cx="8.5" cy="7" r="4"></circle>
            <path d="M20 8v6"></path>
            <path d="M23 11h-6"></path>
          </svg>
          <select id="staffPicker" class="kpi-inline-select"></select>
        </label>

        <button class="kpi-help-btn" id="openHowItWorksBtn" type="button">
          <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <circle cx="12" cy="12" r="10"></circle>
            <path d="M9.09 9a3 3 0 1 1 5.82 1c0 2-3 3-3 3"></path>
            <line x1="12" y1="17" x2="12.01" y2="17"></line>
          </svg>
          <span>How it works</span>
        </button>
      </div>
    </div>

    <div
      id="kpiBanner"
      class="card kpi-banner-card"
      style="display:none;"
    >
      <div class="card-body" id="kpiBannerText"></div>
    </div>

    <div class="kpi-dashboard-grid">
      <section class="card kpi-progress-card">
        <div class="card-header">
          <div>
            <div class="card-title">Monthly Bonus Progress</div>
            <div class="card-subtitle" id="monthLabel">Loading</div>
          </div>
        </div>
        <div class="card-body">
          <div class="kpi-progress-layout">
            <div class="kpi-ring-wrap">
              <div class="kpi-ring" id="progressRing">
                <div class="kpi-ring-core">
                  <div class="kpi-ring-percent" id="progressPercent">0%</div>
                  <div class="kpi-ring-amount" id="progressMoney">
                    <span class="kpi-ring-amount-value">0</span>
                    <span class="kpi-ring-amount-currency">VND</span>
                  </div>
                  <div class="kpi-ring-sub" id="progressPoolHint">of 0 VND</div>
                </div>
              </div>
            </div>

            <div class="kpi-progress-summary">
              <div class="kpi-summary-block">
                <span>Base Salary</span>
                <strong id="baseSalaryValue">0 VND</strong>
