<script>
  const API = import.meta.env.PUBLIC_API_URL;
  const token = localStorage.getItem("token");
  if (!token) window.location.href = "/login";

  let isAdmin = false;
  let currentDashboard = null;
  let currentGoalKey = "";

  const monthPicker = document.getElementById("monthPicker");
  const dayPicker = document.getElementById("dayPicker");
  const staffPicker = document.getElementById("staffPicker");

  const CATEGORY_META = {
    "Daily Tasks": {
      key: "daily-tasks",
      color: "#ff8d2f",
      tint: "rgba(255,141,47,0.14)",
      icon: "calendar",
    },
    "Revenue Targets": {
      key: "revenue-targets",
      color: "#4fd36d",
      tint: "rgba(79,211,109,0.14)",
      icon: "trend",
    },
    "Google Reviews": {
      key: "google-reviews",
      color: "#f3bf35",
      tint: "rgba(243,191,53,0.14)",
      icon: "star",
    },
    "Package Sales": {
      key: "package-sales",
      color: "#9b6cff",
      tint: "rgba(155,108,255,0.14)",
      icon: "briefcase",
    },
    "Attendance & Punctuality": {
      key: "attendance-punctuality",
      color: "#59a8ff",
      tint: "rgba(89,168,255,0.14)",
      icon: "clock",
    },
  };

  function money(value) {
    return `${Math.round(Number(value || 0)).toLocaleString()} VND`;
  }

  function moneyParts(value) {
    return {
      amount: Math.round(Number(value || 0)).toLocaleString(),
      currency: "VND",
    };
  }

  function setMonthDefaults() {
    const now = new Date();
    const monthValue = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}`;
    const dayValue = `${monthValue}-${String(now.getDate()).padStart(2, "0")}`;
    monthPicker.value = monthValue;
    dayPicker.value = dayValue;
  }

  function selectedYearMonth() {
    const [year, month] = (monthPicker.value || "").split("-").map(Number);
    return { year, month };
  }

  function parseJwtPayload(rawToken) {
    try {
      const segment = rawToken?.split(".")?.[1];
      if (!segment) return {};
      const normalized = segment
        .replaceAll("-", "+")
        .replaceAll("_", "/")
        .padEnd(Math.ceil(segment.length / 4) * 4, "=");
      return JSON.parse(atob(normalized));
    } catch {
      return {};
    }
  }

  function escapeHtml(value) {
    return String(value ?? "")
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll('"', "&quot;")
      .replaceAll("'", "&#39;");
  }

  function slugifyLabel(value) {
    return String(value || "")
      .toLowerCase()
      .replaceAll("&", "and")
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "");
  }

  function getCategoryMeta(category) {
    const label = category?.label || "";
    return CATEGORY_META[label] || {
      key: slugifyLabel(label) || "category",
      color: "#ff8d2f",
      tint: "rgba(255,141,47,0.14)",
      icon: "spark",
    };
  }

  function formatMonthRange(year, month) {
    if (!year || !month) return "Select month";
    const start = new Date(year, month - 1, 1);
    const end = new Date(year, month, 0);
    const monthName = start.toLocaleDateString(undefined, { month: "short" });
    return `${monthName} 1 - ${monthName} ${end.getDate()}, ${year}`;
  }

  function formatSelectedDate(dateKey) {
    if (!dateKey) return "Selected day";
    const parsed = new Date(`${dateKey}T00:00:00`);
    if (Number.isNaN(parsed.getTime())) return dateKey;
    return parsed.toLocaleDateString(undefined, {
      month: "short",
      day: "numeric",
      year: "numeric",
    });
  }

  function getDaysInSelectedMonth() {
    const { year, month } = selectedYearMonth();
    if (!year || !month) return 30;
    return new Date(year, month, 0).getDate();
  }

  function getElapsedDayCount() {
    const [year, month, day] = (dayPicker.value || "").split("-").map(Number);
    if (!year || !month || !day) return 1;
    return Math.max(1, day);
  }

  function buildProjection(currentPercent) {
    const current = Math.max(0, Math.min(100, Number(currentPercent || 0)));
    const elapsed = getElapsedDayCount();
    const totalDays = getDaysInSelectedMonth();
    const forecast = elapsed > 0
      ? Math.max(current, Math.min(100, Math.round((current / elapsed) * totalDays)))
      : current;
    return { current, forecast };
  }

  function rewardColorClass(percent) {
    if (percent >= 75) return "Amazing progress — you’re closing in on the full pool.";
    if (percent >= 50) return "Strong momentum this month. Keep the tiers moving.";
    if (percent >= 25) return "Great start. Daily consistency will move this faster.";
    if (percent > 0) return "You’ve unlocked the first part of the bonus. Keep stacking wins.";
    return "Start with daily tasks and the first goal tier to build momentum.";
  }

  function iconSvg(icon) {
    const map = {
      calendar: `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="4" width="18" height="18" rx="2"></rect><line x1="16" y1="2" x2="16" y2="6"></line><line x1="8" y1="2" x2="8" y2="6"></line><line x1="3" y1="10" x2="21" y2="10"></line></svg>`,
      trend: `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 17l6-6 4 4 7-8"></path><path d="M14 7h6v6"></path></svg>`,
      star: `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polygon points="12 2 15.1 8.3 22 9.3 17 14.2 18.2 21 12 17.7 5.8 21 7 14.2 2 9.3 8.9 8.3 12 2"></polygon></svg>`,
      briefcase: `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="2" y="7" width="20" height="14" rx="2"></rect><path d="M16 7V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v2"></path><path d="M2 12h20"></path></svg>`,
      clock: `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg>`,
      spark: `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 3l1.9 5.7L20 10.5l-4.8 3.6L17 20l-5-3.2L7 20l1.8-5.9L4 10.5l6.1-1.8L12 3z"></path></svg>`,
      trophy: `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M8 21h8"></path><path d="M12 17v4"></path><path d="M7 4h10v6a5 5 0 0 1-10 0V4z"></path><path d="M17 6h3a2 2 0 0 1-2 2h-1"></path><path d="M7 6H4a2 2 0 0 0 2 2h1"></path></svg>`,
    };
    return map[icon] || map.spark;
  }

  function parseRewardPercent(label) {
    const match = String(label || "").match(/([+-]?\d+(?:\.\d+)?)\s*%/);
    return match ? Number(match[1]) : 0;
  }

  function buildAchievements(categories) {
    const items = [];
    categories.forEach((category) => {
      const meta = getCategoryMeta(category);
      (category.tiers || []).forEach((tier) => {
        if (!tier.isUnlocked) return;
        items.push({
          title: `${category.label} ${tier.label}`.trim(),
          subtitle: tier.goalLabel || "Unlocked this month",
          reward: tier.rewardLabel || `+${Math.round(category.unlockedPercent || 0)}%`,
          color: meta.color,
          tint: meta.tint,
          icon: meta.icon,
        });
      });
    });

    if (!items.length) {
      const partial = categories.find((category) => Number(category.unlockedPercent || 0) > 0);
      if (partial) {
        const meta = getCategoryMeta(partial);
        items.push({
          title: partial.label,
          subtitle: partial.progressLabel || "Progress started",
          reward: `+${Math.round(partial.unlockedPercent || 0)}%`,
          color: meta.color,
          tint: meta.tint,
          icon: meta.icon,
        });
      }
    }

    return items.slice(0, 4);
  }

  function buildBadges(categories) {
    return categories
      .filter((category) => Number(category.unlockedPercent || 0) > 0 || (category.tiers || []).some((tier) => tier.isUnlocked))
      .slice(0, 4)
      .map((category) => {
        const meta = getCategoryMeta(category);
        return {
          label: category.label,
          color: meta.color,
          icon: meta.icon,
        };
      });
  }

  function deriveGoalTabs(categories) {
    return categories.filter((category) => (category.tiers || []).length > 0);
  }

  function deriveGoalRowState(category, tier, index) {
    if (tier.isUnlocked) return "unlocked";
    const unlockedCount = (category.tiers || []).filter((entry) => entry.isUnlocked).length;
    if (index === unlockedCount) return "active";
    return "locked";
  }

  function deriveGoalProgressWidth(category, tier, index) {
    if (tier.isUnlocked) return 100;
    const unlockedCount = (category.tiers || []).filter((entry) => entry.isUnlocked).length;
    if (index < unlockedCount) return 100;
    if (index === unlockedCount && Number(category.unlockedPercent || 0) > 0) {
      return Math.max(18, Math.min(72, Math.round(Number(category.unlockedPercent || 0))));
    }
    return 0;
  }

