  function renderProjectionChart(currentPercent, forecastPercent) {
    const current = Math.max(0, Math.min(100, Number(currentPercent || 0)));
    const forecast = Math.max(current, Math.min(100, Number(forecastPercent || 0)));
    const values = [
      Math.max(4, current * 0.22),
      Math.max(8, current * 0.4),
      Math.max(12, current * 0.46),
      Math.max(16, current * 0.58),
      Math.max(22, current * 0.68),
      Math.max(28, current * 0.8),
      current,
      Math.max(current, (current + forecast) / 2),
      forecast,
    ].map((value) => Math.max(0, Math.min(100, value)));

    const width = 320;
    const height = 120;
    const step = width / (values.length - 1);
    const points = values.map((value, index) => {
      const x = index * step;
      const y = 110 - (value / 100) * 94;
      return [x, y];
    });

    const linePath = points.map(([x, y], index) => `${index === 0 ? "M" : "L"} ${x.toFixed(2)} ${y.toFixed(2)}`).join(" ");
    const areaPath = `${linePath} L ${width} 112 L 0 112 Z`;
    const guidePoint = points[points.length - 2];
    const dotPoint = points[points.length - 1];

    document.getElementById("projectionLine").setAttribute("d", linePath);
    document.getElementById("projectionArea").setAttribute("d", areaPath);
    document.getElementById("projectionGuideLine").setAttribute("x1", guidePoint[0].toFixed(2));
    document.getElementById("projectionGuideLine").setAttribute("x2", guidePoint[0].toFixed(2));
    document.getElementById("projectionGuideDot").setAttribute("cx", dotPoint[0].toFixed(2));
    document.getElementById("projectionGuideDot").setAttribute("cy", dotPoint[1].toFixed(2));
  }

