      return `<button type="button" class="kpi-goal-tab ${isActive ? "active" : ""}" data-goal-key="${meta.key}">${escapeHtml(category.label)}</button>`;
    }).join("");

    tabsRoot.querySelectorAll("[data-goal-key]").forEach((button) => {
      button.addEventListener("click", () => {
