    color: var(--color-text-primary);
    font: inherit;
  }

  .kpi-inline-select {
    min-width: 190px;
    padding-right: 16px;
  }

  .kpi-help-btn {
    cursor: pointer;
    font: inherit;
    font-weight: 600;
  }

  .kpi-banner-card {
    border: 1px solid rgba(201, 145, 72, 0.35);
    background: linear-gradient(180deg, rgba(201, 145, 72, 0.16), rgba(201, 145, 72, 0.06));
  }

  .kpi-dashboard-grid {
    display: grid;
    grid-template-columns: minmax(0, 1.08fr) minmax(0, 1.12fr) minmax(300px, 0.72fr);
    gap: 16px;
    align-items: start;
  }

  .kpi-support-column {
    display: grid;
    gap: 16px;
    align-content: start;
  }

  .kpi-detail-grid {
    display: grid;
    grid-template-columns: minmax(320px, 0.78fr) minmax(0, 1.22fr);
    gap: 16px;
    align-items: start;
  }

  .kpi-support-grid {
    display: grid;
    grid-template-columns: minmax(320px, 0.9fr) minmax(0, 1.1fr);
    gap: 16px;
    align-items: start;
  }

  .kpi-progress-card .card-body,
  .kpi-breakdown-card .card-body,
  .kpi-projection-card .card-body,
  .kpi-achievements-card .card-body,
  .kpi-badges-card .card-body,
  .kpi-tasks-card .card-body,
  .kpi-goals-card .card-body,
  .kpi-profile-card .card-body,
  .kpi-admin-card .card-body {
    padding-top: 18px;
  }

  .kpi-progress-layout {
    display: grid;
    grid-template-columns: minmax(236px, 0.82fr) minmax(0, 1fr);
    gap: 18px;
    align-items: center;
  }

  .kpi-ring-wrap {
    display: flex;
    justify-content: center;
  }

  .kpi-ring {
    --ring-percent: 0;
    width: min(100%, 280px);
    aspect-ratio: 1;
    border-radius: 50%;
    position: relative;
    display: grid;
    place-items: center;
    background:
      radial-gradient(circle at 50% 50%, rgba(7, 10, 15, 0.96) 0 58%, transparent 59%),
      conic-gradient(from -90deg, #f26a1b calc(var(--ring-percent) * 1%), rgba(255,255,255,0.08) 0);
    box-shadow:
      inset 0 0 0 16px rgba(255,255,255,0.03),
      0 30px 60px rgba(0, 0, 0, 0.28);
  }

  .kpi-ring::before {
    content: "";
    position: absolute;
    inset: 18px;
    border-radius: 50%;
    background:
      radial-gradient(circle at 50% 30%, rgba(255,255,255,0.03), transparent 62%),
      linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));
    border: 1px solid rgba(255,255,255,0.06);
  }

  .kpi-ring-core {
    position: relative;
    z-index: 1;
    width: calc(100% - 88px);
    aspect-ratio: 1;
    border-radius: 50%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
    padding: 16px;
    background: radial-gradient(circle at 50% 25%, rgba(255,255,255,0.03), rgba(5,7,11,0.96) 70%);
  }

  .kpi-ring-percent {
    font-size: clamp(40px, 4vw, 60px);
    font-weight: 800;
    line-height: 1;
    color: var(--color-text-primary);
  }

  .kpi-ring-amount {
    margin-top: 12px;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 4px;
    color: #ff8d2f;
    max-width: 150px;
  }

  .kpi-ring-amount-value {
    font-size: clamp(18px, 1.7vw, 24px);
    font-weight: 800;
    line-height: 1.05;
    letter-spacing: 0;
  }

  .kpi-ring-amount-currency {
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.12em;
    text-transform: uppercase;
  }

  .kpi-ring-sub {
    margin-top: 8px;
    font-size: 12px;
    color: var(--color-text-secondary);
    line-height: 1.35;
    max-width: 100%;
    text-align: center;
  }

  .kpi-progress-summary {
    display: flex;
    flex-direction: column;
    gap: 10px;
  }

  .kpi-summary-block {
    display: flex;
    flex-direction: column;
    gap: 3px;
    padding-bottom: 12px;
    border-bottom: 1px solid var(--color-border-subtle);
  }

  .kpi-summary-block span,
  .kpi-progress-meta span {
    color: var(--color-text-muted);
    font-size: 13px;
  }

  .kpi-summary-block strong {
    font-size: clamp(18px, 1.85vw, 28px);
    line-height: 1.1;
    color: var(--color-text-primary);
    overflow-wrap: anywhere;
  }

  .kpi-summary-block-success strong {
    color: #46d26d;
  }

  .kpi-progress-meta {
    display: flex;
    flex-direction: column;
    gap: 4px;
    padding-top: 4px;
  }

  .kpi-progress-meta strong {
    font-size: 15px;
    color: var(--color-text-secondary);
    font-weight: 600;
  }

  .kpi-progress-encouragement {
    margin-top: 14px;
    min-height: 40px;
    display: inline-flex;
    align-items: center;
    padding: 0 14px;
    border-radius: 10px;
    background: rgba(255,255,255,0.025);
    border: 1px solid var(--color-border-subtle);
    color: var(--color-text-secondary);
    font-size: 14px;
    font-weight: 600;
    max-width: 100%;
    overflow-wrap: anywhere;
  }

  .kpi-breakdown-list {
    display: flex;
    flex-direction: column;
    gap: 14px;
  }

  .kpi-breakdown-item {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 14px;
    align-items: center;
  }

  .kpi-breakdown-item-main {
    display: flex;
    align-items: center;
    gap: 14px;
    min-width: 0;
  }

  .kpi-breakdown-icon {
    width: 48px;
    height: 48px;
    border-radius: 14px;
    display: grid;
    place-items: center;
    flex: 0 0 auto;
    border: 1px solid rgba(255,255,255,0.05);
  }

  .kpi-breakdown-icon svg {
    width: 20px;
    height: 20px;
  }

  .kpi-breakdown-copy {
    min-width: 0;
  }

  .kpi-breakdown-title {
    font-size: 16px;
    font-weight: 700;
    color: var(--color-text-primary);
  }

  .kpi-breakdown-desc,
  .kpi-breakdown-progress-text,
  .kpi-achievement-subtitle,
  .kpi-goal-subtext,
  .kpi-goal-meta,
  .kpi-task-label small {
    color: var(--color-text-muted);
    font-size: 13px;
    line-height: 1.35;
  }

  .kpi-breakdown-progress {
    margin-top: 8px;
  }

  .kpi-progress-bar {
    height: 8px;
    border-radius: 999px;
    background: rgba(255,255,255,0.07);
    overflow: hidden;
  }

  .kpi-progress-bar > span {
    display: block;
    height: 100%;
    border-radius: inherit;
    background: var(--bar-color, #f26a1b);
    width: var(--bar-width, 0%);
  }

  .kpi-breakdown-side {
    text-align: right;
    min-width: 112px;
  }

  .kpi-breakdown-side strong {
    display: block;
    font-size: 26px;
    line-height: 1;
    color: var(--side-color, #ff8d2f);
  }

  .kpi-breakdown-side span {
    display: block;
    margin-top: 8px;
    color: var(--color-text-secondary);
    font-size: 14px;
    font-weight: 600;
  }

  .kpi-breakdown-total {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 12px;
    margin-top: 14px;
    padding-top: 16px;
    border-top: 1px solid var(--color-border-subtle);
  }

  .kpi-breakdown-total span {
    color: var(--color-text-secondary);
    font-size: 15px;
  }

  .kpi-breakdown-total strong {
    font-size: 36px;
    color: #ffb347;
    line-height: 1;
  }

  .kpi-breakdown-total div {
    text-align: right;
  }

  .kpi-breakdown-total div span {
    display: block;
    margin-top: 4px;
    color: #ff8d2f;
    font-weight: 700;
  }

  .kpi-projection-grid {
    display: flex;
    flex-direction: column;
    gap: 10px;
  }

  .kpi-projection-row {
    display: flex;
    justify-content: space-between;
    gap: 16px;
    align-items: flex-start;
    padding: 12px 14px;
    border-radius: 12px;
    background: rgba(255,255,255,0.02);
    border: 1px solid var(--color-border-subtle);
  }

  .kpi-projection-row span {
    color: var(--color-text-muted);
    font-size: 13px;
  }

  .kpi-projection-row div {
    text-align: right;
  }

  .kpi-projection-row strong {
    display: block;
    font-size: 18px;
    line-height: 1;
    color: var(--color-text-primary);
  }

  .kpi-projection-row small {
    display: block;
    margin-top: 6px;
    color: #ff8d2f;
    font-size: 13px;
    font-weight: 700;
  }

  .kpi-mini-chart {
    margin-top: 14px;
    padding-top: 4px;
  }

  .kpi-mini-chart svg {
    width: 100%;
    height: 130px;
    display: block;
  }

  .kpi-mini-line {
    fill: none;
    stroke: url(#kpiChartStroke);
    stroke-width: 3;
    stroke-linecap: round;
    stroke-linejoin: round;
  }

  .kpi-mini-area {
    fill: url(#kpiChartFill);
  }

  .kpi-mini-guide {
    stroke: rgba(255,255,255,0.22);
    stroke-width: 1.2;
    stroke-dasharray: 4 4;
  }

  .kpi-mini-dot {
    fill: #f26a1b;
    stroke: rgba(255,255,255,0.9);
    stroke-width: 2;
  }

  .kpi-mini-axis {
    display: flex;
    justify-content: space-between;
    gap: 12px;
    margin-top: 6px;
    color: var(--color-text-muted);
    font-size: 12px;
  }

  .kpi-achievement-list {
    display: flex;
    flex-direction: column;
    gap: 10px;
  }

  .kpi-achievement-item {
    display: grid;
    grid-template-columns: 52px minmax(0, 1fr) auto;
    gap: 12px;
    align-items: center;
    padding: 12px;
    border-radius: 12px;
    background: rgba(255,255,255,0.02);
    border: 1px solid var(--color-border-subtle);
  }

  .kpi-achievement-icon {
    width: 52px;
    height: 52px;
    border-radius: 14px;
    display: grid;
    place-items: center;
    border: 1px solid rgba(255,255,255,0.05);
  }

  .kpi-achievement-icon svg {
    width: 22px;
    height: 22px;
  }

  .kpi-achievement-title {
    font-size: 15px;
    font-weight: 700;
    color: var(--color-text-primary);
    line-height: 1.25;
  }

  .kpi-achievement-reward {
    font-size: 18px;
    font-weight: 800;
    color: #49d46f;
    white-space: nowrap;
  }

  .kpi-badge-list {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 10px;
  }

  .kpi-badge-item {
    aspect-ratio: 1;
    min-height: 78px;
    border-radius: 16px;
    border: 1px solid rgba(255,255,255,0.06);
    background: linear-gradient(180deg, rgba(255,255,255,0.025), rgba(255,255,255,0.01));
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: 10px 8px;
    text-align: center;
  }

  .kpi-badge-glyph {
    width: 38px;
    height: 38px;
    border-radius: 50%;
    display: grid;
    place-items: center;
    border: 1px solid currentColor;
  }

  .kpi-badge-glyph svg {
    width: 16px;
    height: 16px;
  }

  .kpi-badge-item span {
    font-size: 11px;
    font-weight: 700;
    line-height: 1.25;
    color: var(--color-text-secondary);
    overflow-wrap: anywhere;
  }

  .kpi-task-header-tools {
    display: flex;
    align-items: center;
    gap: 10px;
    flex-wrap: wrap;
    justify-content: flex-end;
  }

  .kpi-day-control {
    min-height: 42px;
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding: 0 12px;
    border-radius: 10px;
    border: 1px solid var(--color-border);
    background: rgba(255,255,255,0.02);
    min-width: 188px;
  }

  .kpi-completion-pill {
    min-height: 38px;
    display: inline-flex;
    align-items: center;
    padding: 0 14px;
    border-radius: 999px;
    background: rgba(72, 199, 116, 0.12);
    border: 1px solid rgba(72, 199, 116, 0.25);
    color: #6dd88c;
    font-size: 13px;
    font-weight: 700;
    white-space: nowrap;
  }

  .kpi-task-meta {
    display: flex;
    justify-content: space-between;
    gap: 12px;
    align-items: center;
    flex-wrap: wrap;
    margin-bottom: 16px;
  }

  .kpi-task-meta span {
    color: var(--color-text-muted);
    font-size: 13px;
  }

  .kpi-task-meta strong {
    font-size: 14px;
    color: #ff9f43;
  }

  .kpi-task-list {
    display: flex;
    flex-direction: column;
    gap: 10px;
  }

  .kpi-task-item {
    display: grid;
    grid-template-columns: 20px minmax(0, 1fr) auto;
    gap: 12px;
    align-items: center;
    padding: 12px 14px;
    border-radius: 12px;
    background: rgba(255,255,255,0.02);
    border: 1px solid var(--color-border-subtle);
  }

  .kpi-task-item input {
    width: 16px;
    height: 16px;
  }

  .kpi-task-label {
    min-width: 0;
  }

  .kpi-task-label strong {
    display: block;
    font-size: 15px;
    color: var(--color-text-primary);
  }

  .kpi-task-status-chip {
    min-height: 28px;
    display: inline-flex;
    align-items: center;
    padding: 0 10px;
    border-radius: 999px;
    font-size: 11px;
    font-weight: 700;
    white-space: nowrap;
    border: 1px solid transparent;
  }

  .kpi-task-status-chip.done {
    color: #66d887;
    background: rgba(72, 199, 116, 0.12);
    border-color: rgba(72, 199, 116, 0.22);
  }

  .kpi-task-status-chip.pending {
    color: var(--color-text-muted);
    background: rgba(255,255,255,0.04);
    border-color: rgba(255,255,255,0.08);
  }

  .kpi-task-footer {
    display: flex;
    justify-content: space-between;
    gap: 16px;
    align-items: center;
    flex-wrap: wrap;
    margin-top: 18px;
    padding-top: 18px;
    border-top: 1px solid var(--color-border-subtle);
  }

  .kpi-task-footer-summary span {
    display: block;
    font-size: 13px;
    color: var(--color-text-muted);
  }

  .kpi-task-footer-summary strong {
    display: block;
    margin-top: 4px;
    font-size: 28px;
    color: #ff9f43;
  }

  .kpi-goal-tabs {
    display: flex;
    gap: 8px;
    flex-wrap: wrap;
    margin-bottom: 18px;
  }

  .kpi-goal-tab {
    min-height: 38px;
    padding: 0 14px;
    border: 0;
    border-radius: 10px;
    background: transparent;
    color: var(--color-text-secondary);
    font: inherit;
    font-size: 14px;
    font-weight: 700;
    cursor: pointer;
    border-bottom: 2px solid transparent;
  }

  .kpi-goal-tab.active {
    color: #ff8d2f;
    border-bottom-color: #ff8d2f;
  }

  .kpi-goal-summary {
    margin-bottom: 16px;
    color: var(--color-text-secondary);
    font-size: 14px;
    line-height: 1.45;
  }

  .kpi-goal-rows {
    display: flex;
    flex-direction: column;
    gap: 10px;
  }

  .kpi-goal-row {
    display: grid;
    grid-template-columns: 42px minmax(0, 1fr) auto;
    gap: 14px;
    align-items: center;
    padding: 14px 16px;
    border-radius: 12px;
    background: rgba(255,255,255,0.02);
    border: 1px solid var(--color-border-subtle);
  }

  .kpi-goal-marker {
    width: 42px;
    height: 42px;
    border-radius: 50%;
    border: 2px solid rgba(255,255,255,0.18);
    display: grid;
    place-items: center;
    color: rgba(255,255,255,0.35);
    flex: 0 0 auto;
  }

  .kpi-goal-row.unlocked .kpi-goal-marker {
    border-color: var(--goal-color, #4fd36d);
    color: var(--goal-color, #4fd36d);
    box-shadow: 0 0 0 4px rgba(79, 211, 109, 0.09);
  }

  .kpi-goal-row.active .kpi-goal-marker {
    border-color: #ff8d2f;
    color: #ff8d2f;
  }

  .kpi-goal-title-line {
    display: flex;
    align-items: center;
    gap: 10px;
    flex-wrap: wrap;
  }

  .kpi-goal-title-line strong {
    font-size: 18px;
    color: var(--color-text-primary);
  }

  .kpi-goal-reward-pill {
    min-height: 30px;
    display: inline-flex;
    align-items: center;
    padding: 0 10px;
    border-radius: 999px;
    font-size: 12px;
    font-weight: 800;
    color: var(--goal-color, #ff8d2f);
    background: rgba(255,255,255,0.05);
    border: 1px solid rgba(255,255,255,0.08);
  }

  .kpi-goal-progress {
    margin-top: 10px;
  }

  .kpi-goal-side {
    min-width: 88px;
    text-align: right;
  }

  .kpi-goal-side strong {
    display: block;
    font-size: 18px;
    color: var(--goal-color, #ff8d2f);
  }

  .kpi-goal-side span {
    display: block;
    margin-top: 6px;
    color: var(--color-text-muted);
    font-size: 12px;
  }

  .kpi-goal-footer {
    margin-top: 18px;
    min-height: 42px;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    padding: 0 16px;
    border-radius: 12px;
    background: rgba(255, 141, 47, 0.08);
    border: 1px solid rgba(255, 141, 47, 0.18);
    color: #ff9f43;
    font-size: 14px;
    font-weight: 700;
  }

  .staff-card {
    display: flex;
    align-items: center;
    gap: 14px;
  }

  .staff-avatar {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    background: rgba(255,255,255,0.03);
    border: 1px solid var(--color-border-subtle);
    overflow: hidden;
    display: grid;
    place-items: center;
    font-weight: 800;
    font-size: 18px;
  }

  .staff-avatar img {
    width: 100%;
    height: 100%;
    object-fit: cover;
  }

  .kpi-profile-stats {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 12px;
    margin-top: 18px;
  }

  .kpi-profile-stat {
    padding: 14px;
    border-radius: 12px;
    background: rgba(255,255,255,0.02);
    border: 1px solid var(--color-border-subtle);
  }

  .kpi-profile-stat span {
    display: block;
    font-size: 12px;
    color: var(--color-text-muted);
  }

  .kpi-profile-stat strong {
    display: block;
    margin-top: 8px;
    font-size: 22px;
    line-height: 1.1;
    color: var(--color-text-primary);
    overflow-wrap: anywhere;
  }

  .kpi-toggle-row {
    display: flex;
    align-items: center;
    gap: 10px;
    cursor: pointer;
    font-size: 14px;
  }

  .kpi-admin-footer {
    display: flex;
    gap: 10px;
    align-items: center;
    flex-wrap: wrap;
    margin-top: 16px;
  }

  .kpi-inline-msg {
    font-size: 13px;
    font-weight: 700;
  }

  .kpi-inline-msg.success {
    color: var(--color-success);
  }

  .kpi-inline-msg.error {
    color: var(--color-danger);
  }

  .kpi-modal-backdrop {
    position: fixed;
    inset: 0;
    z-index: 1000;
    display: grid;
    place-items: center;
    padding: 20px;
    background: rgba(2, 5, 9, 0.72);
    backdrop-filter: blur(10px);
  }

  .kpi-modal {
    width: min(100%, 720px);
    border-radius: 16px;
    border: 1px solid var(--color-border);
    background: var(--color-surface);
    box-shadow: 0 26px 64px rgba(0, 0, 0, 0.38);
    overflow: hidden;
  }

  .kpi-modal-header {
    display: flex;
    justify-content: space-between;
    gap: 16px;
    align-items: flex-start;
    padding: 20px 22px 16px;
    border-bottom: 1px solid var(--color-border-subtle);
  }

  .kpi-modal-body {
    padding: 18px 22px 22px;
  }

  .kpi-help-steps {
    display: flex;
    flex-direction: column;
    gap: 16px;
  }

  .kpi-help-step {
    display: grid;
    grid-template-columns: 34px minmax(0, 1fr);
    gap: 14px;
    align-items: start;
  }

  .kpi-help-step-number {
    width: 34px;
    height: 34px;
    border-radius: 50%;
    display: grid;
    place-items: center;
    background: rgba(255, 141, 47, 0.12);
    color: #ff8d2f;
    font-size: 14px;
    font-weight: 800;
  }

  .kpi-help-step p {
    margin: 6px 0 0;
    color: var(--color-text-secondary);
    font-size: 14px;
    line-height: 1.5;
  }

  @media (max-width: 1360px) {
    .kpi-dashboard-grid {
      grid-template-columns: 1fr 1fr;
    }

    .kpi-projection-card {
      grid-column: 1 / -1;
    }
  }

  @media (max-width: 1180px) {
    .kpi-detail-grid,
    .kpi-support-grid,
    .kpi-progress-layout {
      grid-template-columns: 1fr;
    }

    .kpi-profile-stats {
      grid-template-columns: 1fr 1fr;
    }
  }

  @media (max-width: 960px) {
    .kpi-dashboard-grid,
    .kpi-detail-grid,
    .kpi-support-grid,
    .kpi-support-column {
      grid-template-columns: 1fr;
    }

    .kpi-page-actions {
      width: 100%;
      justify-content: stretch;
    }

    .kpi-action-control,
    .kpi-help-btn {
      width: 100%;
    }

    .kpi-breakdown-item,
    .kpi-achievement-item,
    .kpi-goal-row {
      grid-template-columns: 1fr;
    }

    .kpi-breakdown-item-main {
      align-items: flex-start;
    }

    .kpi-breakdown-side,
    .kpi-goal-side {
      text-align: left;
    }
  }

  @media (max-width: 720px) {
    .kpi-page-header {
      gap: 14px;
    }

    .kpi-progress-card .card-body,
    .kpi-breakdown-card .card-body,
    .kpi-projection-card .card-body,
    .kpi-achievements-card .card-body,
    .kpi-badges-card .card-body,
    .kpi-tasks-card .card-body,
    .kpi-goals-card .card-body,
    .kpi-profile-card .card-body,
    .kpi-admin-card .card-body {
      padding-top: 14px;
    }

    .kpi-badge-list,
    .kpi-profile-stats {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .kpi-breakdown-total strong {
      font-size: 30px;
    }

    .kpi-task-header-tools {
      width: 100%;
      justify-content: flex-start;
    }

    .kpi-task-footer {
      align-items: flex-start;
    }
  }

  @media (max-width: 520px) {
    .kpi-badge-list,
    .kpi-profile-stats {
      grid-template-columns: 1fr;
    }

    .kpi-ring {
      width: min(100%, 242px);
    }

    .kpi-goal-title-line strong,
    .kpi-breakdown-title,
    .kpi-achievement-title {
      font-size: 16px;
    }

    .kpi-breakdown-side strong,
    .kpi-breakdown-total strong {
      font-size: 26px;
    }

    .kpi-summary-block strong,
    .kpi-profile-stat strong,
    .kpi-task-footer-summary strong,
    .kpi-projection-row strong {
      font-size: 20px;
    }
  }
</style>

