with open('/opt/soulpilates/SoulPilates.Astro/src/pages/admin/kpi-bonus.astro', 'r') as f:
    content = f.read()

# Find the style block boundaries
style_start = content.index('<style is:global>')
style_end   = content.index('</style>') + len('</style>')

new_style = '''<style is:global>
  /* ── Shell ───────────────────────────────────────────────────────────────── */
  .kpi-page-shell {
    display: flex;
    flex-direction: column;
    gap: 12px;
  }

  .kpi-page-header {
    display: flex;
    justify-content: space-between;
    gap: 12px;
    align-items: center;
    flex-wrap: wrap;
  }

  .kpi-page-actions {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 8px;
    flex-wrap: wrap;
    margin-left: auto;
  }

  .kpi-action-control,
  .kpi-help-btn {
    min-height: 36px;
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 0 12px;
    border-radius: 8px;
    border: 1px solid var(--color-border);
    background: var(--color-surface);
    color: var(--color-text-secondary);
    box-shadow: var(--shadow-card);
    font-size: 13px;
  }

  .kpi-action-control {
    position: relative;
    min-width: 200px;
  }

  .kpi-action-control svg,
  .kpi-help-btn svg,
  .kpi-day-control svg {
    flex: 0 0 auto;
    color: var(--color-text-muted);
    width: 14px; height: 14px;
  }

  .kpi-action-control-month { cursor: pointer; }

  .kpi-hidden-month-input {
    position: absolute;
    inset: 0;
    opacity: 0;
    cursor: pointer;
  }

  .kpi-inline-select,
  .kpi-inline-date {
    width: 100%;
    border: 0;
    outline: 0;
    background: transparent;
    color: var(--color-text-primary);
    font: inherit;
    font-size: 13px;
  }

  .kpi-inline-select { min-width: 160px; padding-right: 8px; }

  .kpi-help-btn {
    cursor: pointer;
    font: inherit;
    font-size: 13px;
    font-weight: 600;
  }

  /* ── Banner ───────────────────────────────────────────────────────────────── */
  .kpi-banner-card {
    border: 1px solid rgba(201,145,72,0.35);
    background: linear-gradient(180deg, rgba(201,145,72,0.14), rgba(201,145,72,0.05));
  }

  /* ── Main layout: 3-column grid ───────────────────────────────────────────── */
  .kpi-dashboard-grid {
    display: grid;
    grid-template-columns: minmax(0,1.05fr) minmax(0,1.15fr) minmax(260px,0.7fr);
    gap: 12px;
    align-items: start;
  }

  .kpi-detail-grid {
    display: grid;
    grid-template-columns: minmax(0,0.72fr) minmax(0,1.28fr);
    gap: 12px;
    align-items: start;
  }

  .kpi-support-grid {
    display: grid;
    grid-template-columns: minmax(0,1fr) minmax(0,1fr);
    gap: 12px;
    align-items: start;
  }

  .kpi-support-column {
    display: grid;
    gap: 12px;
    align-content: start;
  }

  /* ── Card body padding override for KPI cards ─────────────────────────────── */
  .kpi-progress-card .card-body,
  .kpi-breakdown-card .card-body,
  .kpi-projection-card .card-body,
  .kpi-achievements-card .card-body,
  .kpi-badges-card .card-body,
  .kpi-tasks-card .card-body,
  .kpi-goals-card .card-body,
  .kpi-profile-card .card-body,
  .kpi-admin-card .card-body {
    padding: 14px 16px 16px;
  }

  .kpi-progress-card .card-header,
  .kpi-breakdown-card .card-header,
  .kpi-projection-card .card-header,
  .kpi-achievements-card .card-header,
  .kpi-badges-card .card-header,
  .kpi-tasks-card .card-header,
  .kpi-goals-card .card-header,
  .kpi-profile-card .card-header,
  .kpi-admin-card .card-header {
    padding: 12px 16px 10px;
  }

  /* ── Progress ring ────────────────────────────────────────────────────────── */
  .kpi-progress-layout {
    display: grid;
    grid-template-columns: 160px minmax(0,1fr);
    gap: 14px;
    align-items: center;
  }

  .kpi-ring-wrap {
    display: flex;
    justify-content: center;
  }

  .kpi-ring {
    --ring-percent: 0;
    width: 160px;
    aspect-ratio: 1;
    border-radius: 50%;
    position: relative;
    display: grid;
    place-items: center;
    background:
      radial-gradient(circle at 50% 50%, rgba(7,10,15,0.96) 0 58%, transparent 59%),
      conic-gradient(from -90deg, #f26a1b calc(var(--ring-percent) * 1%), rgba(255,255,255,0.08) 0);
    box-shadow: inset 0 0 0 10px rgba(255,255,255,0.03), 0 12px 32px rgba(0,0,0,0.24);
  }

  .kpi-ring::before {
    content: "";
    position: absolute;
    inset: 12px;
    border-radius: 50%;
    background:
      radial-gradient(circle at 50% 30%, rgba(255,255,255,0.03), transparent 62%),
      linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));
    border: 1px solid rgba(255,255,255,0.06);
  }

  .kpi-ring-core {
    position: relative;
    z-index: 1;
    width: calc(100% - 52px);
    aspect-ratio: 1;
    border-radius: 50%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
    padding: 8px;
    background: radial-gradient(circle at 50% 25%, rgba(255,255,255,0.03), rgba(5,7,11,0.96) 70%);
  }

  .kpi-ring-percent {
    font-size: 30px;
    font-weight: 800;
    line-height: 1;
    color: var(--color-text-primary);
  }

  .kpi-ring-amount {
    margin-top: 6px;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 2px;
    color: #ff8d2f;
    max-width: 100%;
  }

  .kpi-ring-amount-value {
    font-size: 13px;
    font-weight: 800;
    line-height: 1.1;
    overflow-wrap: anywhere;
  }

  .kpi-ring-amount-currency {
    font-size: 9px;
    font-weight: 800;
    letter-spacing: 0.1em;
    text-transform: uppercase;
  }

  .kpi-ring-sub {
    margin-top: 4px;
    font-size: 10px;
    color: var(--color-text-secondary);
    line-height: 1.3;
    text-align: center;
  }

  /* ── Progress summary ─────────────────────────────────────────────────────── */
  .kpi-progress-summary {
    display: flex;
    flex-direction: column;
    gap: 6px;
  }

  .kpi-summary-block {
    display: flex;
    flex-direction: column;
    gap: 1px;
    padding-bottom: 7px;
    border-bottom: 1px solid var(--color-border-subtle);
  }

  .kpi-summary-block span,
  .kpi-progress-meta span {
    color: var(--color-text-muted);
    font-size: 11px;
  }

  .kpi-summary-block strong {
    font-size: 16px;
    line-height: 1.2;
    color: var(--color-text-primary);
    overflow-wrap: anywhere;
  }

  .kpi-summary-block-success strong { color: #46d26d; }

  .kpi-progress-meta {
    display: flex;
    flex-direction: column;
    gap: 2px;
    padding-top: 2px;
  }

  .kpi-progress-meta strong {
    font-size: 12px;
    color: var(--color-text-secondary);
    font-weight: 600;
  }

  .kpi-progress-encouragement {
    margin-top: 10px;
    padding: 8px 12px;
    border-radius: 8px;
    background: rgba(255,255,255,0.025);
    border: 1px solid var(--color-border-subtle);
    color: var(--color-text-secondary);
    font-size: 12px;
    font-weight: 600;
    overflow-wrap: anywhere;
  }

  /* ── Breakdown ────────────────────────────────────────────────────────────── */
  .kpi-breakdown-list {
    display: flex;
    flex-direction: column;
    gap: 10px;
  }

  .kpi-breakdown-item {
    display: grid;
    grid-template-columns: minmax(0,1fr) auto;
    gap: 10px;
    align-items: center;
  }

  .kpi-breakdown-item-main {
    display: flex;
    align-items: center;
    gap: 10px;
    min-width: 0;
  }

  .kpi-breakdown-icon {
    width: 36px;
    height: 36px;
    border-radius: 10px;
    display: grid;
    place-items: center;
    flex: 0 0 auto;
    border: 1px solid rgba(255,255,255,0.05);
  }

  .kpi-breakdown-icon svg { width: 16px; height: 16px; }

  .kpi-breakdown-copy { min-width: 0; }

  .kpi-breakdown-title {
    font-size: 13px;
    font-weight: 700;
    color: var(--color-text-primary);
  }

  .kpi-breakdown-desc,
  .kpi-breakdown-progress-text,
  .kpi-achievement-subtitle,
  .kpi-goal-subtext,
  .kpi-goal-meta,
  .kpi-task-label small {
    color: var(--color-text-muted);
    font-size: 11px;
    line-height: 1.3;
  }

  .kpi-breakdown-progress { margin-top: 5px; }

  .kpi-progress-bar {
    height: 5px;
    border-radius: 999px;
    background: rgba(255,255,255,0.07);
    overflow: hidden;
  }

  .kpi-progress-bar > span {
    display: block;
    height: 100%;
    border-radius: inherit;
    background: var(--bar-color, #f26a1b);
    width: var(--bar-width, 0%);
  }

  .kpi-breakdown-side {
    text-align: right;
    min-width: 80px;
  }

  .kpi-breakdown-side strong {
    display: block;
    font-size: 18px;
    line-height: 1;
    color: var(--side-color, #ff8d2f);
  }

  .kpi-breakdown-side span {
    display: block;
    margin-top: 4px;
    color: var(--color-text-secondary);
    font-size: 11px;
    font-weight: 600;
  }

  .kpi-breakdown-total {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 10px;
    margin-top: 10px;
    padding-top: 10px;
    border-top: 1px solid var(--color-border-subtle);
  }

  .kpi-breakdown-total span {
    color: var(--color-text-secondary);
    font-size: 13px;
  }

  .kpi-breakdown-total strong {
    font-size: 22px;
    color: #ffb347;
    line-height: 1;
  }

  .kpi-breakdown-total div { text-align: right; }

  .kpi-breakdown-total div span {
    display: block;
    margin-top: 2px;
    color: #ff8d2f;
    font-weight: 700;
    font-size: 12px;
  }

  /* ── Projection ───────────────────────────────────────────────────────────── */
  .kpi-projection-grid {
    display: flex;
    flex-direction: column;
    gap: 7px;
  }

  .kpi-projection-row {
    display: flex;
    justify-content: space-between;
    gap: 10px;
    align-items: flex-start;
    padding: 9px 12px;
    border-radius: 9px;
    background: rgba(255,255,255,0.02);
    border: 1px solid var(--color-border-subtle);
  }

  .kpi-projection-row span {
    color: var(--color-text-muted);
    font-size: 12px;
  }

  .kpi-projection-row div { text-align: right; }

  .kpi-projection-row strong {
    display: block;
    font-size: 15px;
    line-height: 1;
    color: var(--color-text-primary);
  }

  .kpi-projection-row small {
    display: block;
    margin-top: 3px;
    color: #ff8d2f;
    font-size: 11px;
    font-weight: 700;
  }

  .kpi-mini-chart { margin-top: 10px; }

  .kpi-mini-chart svg {
    width: 100%;
    height: 90px;
    display: block;
  }

  .kpi-mini-line {
    fill: none;
    stroke: url(#kpiChartStroke);
    stroke-width: 2.5;
    stroke-linecap: round;
    stroke-linejoin: round;
  }

  .kpi-mini-area { fill: url(#kpiChartFill); }

  .kpi-mini-guide {
    stroke: rgba(255,255,255,0.22);
    stroke-width: 1;
    stroke-dasharray: 3 3;
  }

  .kpi-mini-dot {
    fill: #f26a1b;
    stroke: rgba(255,255,255,0.9);
    stroke-width: 2;
  }

  .kpi-mini-axis {
    display: flex;
    justify-content: space-between;
    gap: 8px;
    margin-top: 4px;
    color: var(--color-text-muted);
    font-size: 10px;
  }

  /* ── Achievements ─────────────────────────────────────────────────────────── */
  .kpi-achievement-list {
    display: flex;
    flex-direction: column;
    gap: 7px;
  }

  .kpi-achievement-item {
    display: grid;
    grid-template-columns: 38px minmax(0,1fr) auto;
    gap: 10px;
    align-items: center;
    padding: 9px 10px;
    border-radius: 10px;
    background: rgba(255,255,255,0.02);
    border: 1px solid var(--color-border-subtle);
  }

  .kpi-achievement-icon {
    width: 38px;
    height: 38px;
    border-radius: 10px;
    display: grid;
    place-items: center;
    border: 1px solid rgba(255,255,255,0.05);
  }

  .kpi-achievement-icon svg { width: 16px; height: 16px; }

  .kpi-achievement-title {
    font-size: 13px;
    font-weight: 700;
    color: var(--color-text-primary);
    line-height: 1.2;
  }

  .kpi-achievement-reward {
    font-size: 15px;
    font-weight: 800;
    color: #49d46f;
    white-space: nowrap;
  }

  /* ── Badges ───────────────────────────────────────────────────────────────── */
  .kpi-badge-list {
    display: grid;
    grid-template-columns: repeat(4,minmax(0,1fr));
    gap: 8px;
  }

  .kpi-badge-item {
    aspect-ratio: 1;
    min-height: 64px;
    border-radius: 12px;
    border: 1px solid rgba(255,255,255,0.06);
    background: rgba(255,255,255,0.02);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 6px;
    padding: 8px 6px;
    text-align: center;
  }

  .kpi-badge-glyph {
    width: 28px;
    height: 28px;
    border-radius: 50%;
    display: grid;
    place-items: center;
    border: 1px solid currentColor;
  }

  .kpi-badge-glyph svg { width: 13px; height: 13px; }

  .kpi-badge-item span {
    font-size: 10px;
    font-weight: 700;
    line-height: 1.2;
    color: var(--color-text-secondary);
    overflow-wrap: anywhere;
  }

  /* ── Tasks ────────────────────────────────────────────────────────────────── */
  .kpi-task-header-tools {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    justify-content: flex-end;
  }

  .kpi-day-control {
    min-height: 34px;
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 0 10px;
    border-radius: 8px;
    border: 1px solid var(--color-border);
    background: rgba(255,255,255,0.02);
    min-width: 160px;
    font-size: 13px;
  }

  .kpi-completion-pill {
    min-height: 30px;
    display: inline-flex;
    align-items: center;
    padding: 0 10px;
    border-radius: 999px;
    background: rgba(72,199,116,0.12);
    border: 1px solid rgba(72,199,116,0.25);
    color: #6dd88c;
    font-size: 12px;
    font-weight: 700;
    white-space: nowrap;
  }

  .kpi-task-meta {
    display: flex;
    justify-content: space-between;
    gap: 8px;
    align-items: center;
    flex-wrap: wrap;
    margin-bottom: 10px;
  }

  .kpi-task-meta span { color: var(--color-text-muted); font-size: 12px; }
  .kpi-task-meta strong { font-size: 12px; color: #ff9f43; }

  .kpi-task-list {
    display: flex;
    flex-direction: column;
    gap: 6px;
  }

  .kpi-task-item {
    display: grid;
    grid-template-columns: 16px minmax(0,1fr) auto;
    gap: 10px;
    align-items: center;
    padding: 9px 12px;
    border-radius: 9px;
    background: rgba(255,255,255,0.02);
    border: 1px solid var(--color-border-subtle);
  }

  .kpi-task-item input { width: 14px; height: 14px; }

  .kpi-task-label { min-width: 0; }

  .kpi-task-label strong {
    display: block;
    font-size: 13px;
    color: var(--color-text-primary);
  }

  .kpi-task-status-chip {
    min-height: 24px;
    display: inline-flex;
    align-items: center;
    padding: 0 8px;
    border-radius: 999px;
    font-size: 10px;
    font-weight: 700;
    white-space: nowrap;
    border: 1px solid transparent;
  }

  .kpi-task-status-chip.done {
    color: #66d887;
    background: rgba(72,199,116,0.12);
    border-color: rgba(72,199,116,0.22);
  }

  .kpi-task-status-chip.pending {
    color: var(--color-text-muted);
    background: rgba(255,255,255,0.04);
    border-color: rgba(255,255,255,0.08);
  }

  .kpi-task-footer {
    display: flex;
    justify-content: space-between;
    gap: 12px;
    align-items: center;
    flex-wrap: wrap;
    margin-top: 12px;
    padding-top: 12px;
    border-top: 1px solid var(--color-border-subtle);
  }

  .kpi-task-footer-summary span {
    display: block;
    font-size: 11px;
    color: var(--color-text-muted);
  }

  .kpi-task-footer-summary strong {
    display: block;
    margin-top: 2px;
    font-size: 20px;
    color: #ff9f43;
  }

  /* ── Goals ────────────────────────────────────────────────────────────────── */
  .kpi-goal-tabs {
    display: flex;
    gap: 4px;
    flex-wrap: wrap;
    margin-bottom: 12px;
  }

  .kpi-goal-tab {
    min-height: 32px;
    padding: 0 12px;
    border: 0;
    border-radius: 8px;
    background: transparent;
    color: var(--color-text-secondary);
    font: inherit;
    font-size: 13px;
    font-weight: 700;
    cursor: pointer;
    border-bottom: 2px solid transparent;
  }

  .kpi-goal-tab.active {
    color: #ff8d2f;
    border-bottom-color: #ff8d2f;
  }

  .kpi-goal-summary {
    margin-bottom: 10px;
    color: var(--color-text-secondary);
    font-size: 13px;
    line-height: 1.4;
  }

  .kpi-goal-rows {
    display: flex;
    flex-direction: column;
    gap: 7px;
  }

  .kpi-goal-row {
    display: grid;
    grid-template-columns: 34px minmax(0,1fr) auto;
    gap: 10px;
    align-items: center;
    padding: 10px 12px;
    border-radius: 10px;
    background: rgba(255,255,255,0.02);
    border: 1px solid var(--color-border-subtle);
  }

  .kpi-goal-marker {
    width: 34px;
    height: 34px;
    border-radius: 50%;
    border: 2px solid rgba(255,255,255,0.18);
    display: grid;
    place-items: center;
    color: rgba(255,255,255,0.35);
    flex: 0 0 auto;
  }

  .kpi-goal-row.unlocked .kpi-goal-marker {
    border-color: var(--goal-color, #4fd36d);
    color: var(--goal-color, #4fd36d);
    box-shadow: 0 0 0 3px rgba(79,211,109,0.09);
  }

  .kpi-goal-row.active .kpi-goal-marker {
    border-color: #ff8d2f;
    color: #ff8d2f;
  }

  .kpi-goal-title-line {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
  }

  .kpi-goal-title-line strong {
    font-size: 14px;
    color: var(--color-text-primary);
  }

  .kpi-goal-reward-pill {
    min-height: 24px;
    display: inline-flex;
    align-items: center;
    padding: 0 8px;
    border-radius: 999px;
    font-size: 11px;
    font-weight: 800;
    color: var(--goal-color, #ff8d2f);
    background: rgba(255,255,255,0.05);
    border: 1px solid rgba(255,255,255,0.08);
  }

  .kpi-goal-progress { margin-top: 6px; }

  .kpi-goal-side {
    min-width: 76px;
    text-align: right;
  }

  .kpi-goal-side strong {
    display: block;
    font-size: 13px;
    color: var(--goal-color, #ff8d2f);
  }

  .kpi-goal-side span {
    display: block;
    margin-top: 3px;
    color: var(--color-text-muted);
    font-size: 11px;
  }

  .kpi-goal-footer {
    margin-top: 12px;
    padding: 8px 14px;
    border-radius: 9px;
    background: rgba(255,141,47,0.08);
    border: 1px solid rgba(255,141,47,0.18);
    color: #ff9f43;
    font-size: 12px;
    font-weight: 700;
    text-align: center;
  }

  /* ── Profile ──────────────────────────────────────────────────────────────── */
  .staff-card {
    display: flex;
    align-items: center;
    gap: 10px;
  }

  .staff-avatar {
    width: 48px;
    height: 48px;
    border-radius: 50%;
    background: rgba(255,255,255,0.03);
    border: 1px solid var(--color-border-subtle);
    overflow: hidden;
    display: grid;
    place-items: center;
    font-weight: 800;
    font-size: 14px;
    flex-shrink: 0;
  }

  .staff-avatar img { width: 100%; height: 100%; object-fit: cover; }

  .kpi-profile-stats {
    display: grid;
    grid-template-columns: repeat(2,minmax(0,1fr));
    gap: 8px;
    margin-top: 12px;
  }

  .kpi-profile-stat {
    padding: 10px 12px;
    border-radius: 10px;
    background: rgba(255,255,255,0.02);
    border: 1px solid var(--color-border-subtle);
  }

  .kpi-profile-stat span {
    display: block;
    font-size: 11px;
    color: var(--color-text-muted);
  }

  .kpi-profile-stat strong {
    display: block;
    margin-top: 4px;
    font-size: 16px;
    line-height: 1.2;
    color: var(--color-text-primary);
    overflow-wrap: anywhere;
  }

  /* ── Admin ────────────────────────────────────────────────────────────────── */
  .kpi-toggle-row {
    display: flex;
    align-items: center;
    gap: 8px;
    cursor: pointer;
    font-size: 13px;
  }

  .kpi-admin-footer {
    display: flex;
    gap: 8px;
    align-items: center;
    flex-wrap: wrap;
    margin-top: 12px;
  }

  .kpi-inline-msg { font-size: 12px; font-weight: 700; }
  .kpi-inline-msg.success { color: var(--color-success); }
  .kpi-inline-msg.error   { color: var(--color-danger); }

  /* ── Modal ────────────────────────────────────────────────────────────────── */
  .kpi-modal-backdrop {
    position: fixed;
    inset: 0;
    z-index: 1000;
    display: grid;
    place-items: center;
    padding: 20px;
    background: rgba(2,5,9,0.72);
    backdrop-filter: blur(10px);
  }

  .kpi-modal {
    width: min(100%, 640px);
    border-radius: 14px;
    border: 1px solid var(--color-border);
    background: var(--color-surface);
    box-shadow: 0 24px 56px rgba(0,0,0,0.38);
    overflow: hidden;
  }

  .kpi-modal-header {
    display: flex;
    justify-content: space-between;
    gap: 14px;
    align-items: flex-start;
    padding: 16px 18px 12px;
    border-bottom: 1px solid var(--color-border-subtle);
  }

  .kpi-modal-body { padding: 14px 18px 18px; }

  .kpi-help-steps { display: flex; flex-direction: column; gap: 12px; }

  .kpi-help-step {
    display: grid;
    grid-template-columns: 28px minmax(0,1fr);
