public async Task<bool> CancelSessionAsync(string sessionId)
{
    var session = await _sessions.Find(s => s.Id == sessionId).FirstOrDefaultAsync();
    if (session == null) return false;

    // Set session to cancelled
    var sessionUpdate = Builders<CalendarSession>.Update.Set(s => s.Status, "CANCELLED");
    await _sessions.UpdateOneAsync(s => s.Id == sessionId, sessionUpdate);

    // Get all active bookings for this session
    var bookings = await _attendances.Find(a =>
        a.CalendarSessionId == sessionId &&
        a.Status != "CANCELLED"
    ).ToListAsync();

    // Cancel each booking and refund credits if applicable
    foreach (var booking in bookings)
    {
        var attendanceUpdate = Builders<Attendance>.Update.Set(a => a.Status, "CANCELLED");
        await _attendances.UpdateOneAsync(a => a.Id == booking.Id, attendanceUpdate);

        // Refund credit if a package was linked. Ledger-driven so multi-wallet
        // deductions are fully reversed; the PackageInstanceId fallback covers
        // legacy migrated rows that have no ledger trail.
        // SPM-108: only run the blind PackageInstanceId fallback when there is NO
        // ledger trail for this attendance. Otherwise a re-processed row (e.g. a
        // LATE_CANCEL/RESCHEDULED booking that already settled its ledger) would be
        // phantom-refunded a second credit (the observed 1 -> 2 bug).
        var (refunded, hasLedgerTrail) = await _walletService.RefundCreditByAttendanceWithTrailAsync(booking.Id!);
        if (!refunded && !hasLedgerTrail && !string.IsNullOrEmpty(booking.PackageInstanceId))
        {
            // Attach to the attendance the credit was DEDUCTED under (the original for
            // a carried reschedule), so the deduction nets to zero and can't be
            // re-refunded later (SPM-108).
            await _walletService.RefundCreditAsync(
                booking.PackageInstanceId, booking.RescheduledFromAttendanceId ?? booking.Id!);
        }
    }

    // P4-S02 — Mass-cancel any waitlist entries for the (now-cancelled) session.
    // There's nothing left to promote into, so the entries are inert noise on
    // the customer's my-bookings view. Cancel them silently.
    await _waitlistService.CancelAllForSessionAsync(sessionId);

    // SPM-101 — Notify each affected customer (email) + studio Admin/Manager
    // staff (push w/ email fallback) that this whole session was cancelled.
    // Fire-and-forget: a notification hiccup must never fail the cancel.
    NotifySessionCancelled(session, bookings);

    return true;
}

/// <summary>
/// SPM-101 — fire-and-forget fan-out for an admin whole-session cancel:
///   (i) every affected customer via email (the customer-facing surface
///       has no push channel, so we email — same channel the booking
///       confirmation path uses), and
///   (ii) studio Admin/Manager staff via the notification publisher
///        (push with email fallback, gated by the per-role matrix).
/// Each leg is wrapped so notification failures can't fail the cancel.
/// </summary>
private void NotifySessionCancelled(CalendarSession session, List<Attendance> bookings)
{
    _ = Task.Run(async () =>
    {
        foreach (var booking in bookings)
        {
            if (string.IsNullOrWhiteSpace(booking.ClientEmail)) continue;
            try
            {
                await _emailService.SendClassCancelledAsync(
                    booking.ClientEmail,
                    booking.ClientName ?? "Customer",
                    session.ClassName,
                    session.StartTime);
            }
            catch { /* email service already no-ops when SMTP is disabled */ }
        }

        try
        {
            var payload = new PushPayload
            {
                Title = "Class cancelled",
                Body  = $"{session.ClassName} · {session.StartTime:ddd HH:mm} was cancelled · {bookings.Count} booking(s) affected",
                Icon  = "/icons/icon-192.png",
                Badge = "/icons/icon-192.png",
                Url   = $"/admin/calendar?session={session.Id}",
                Tag   = $"session-cancelled-{session.Id}",
            };
            await _notifications.PublishToRolesAsync(
                new[] { "Admin", "Manager" },
                NotificationCategory.BookingCancelled,
                payload);
        }
        catch { /* publisher already logs */ }
    });
}

