/* ── cancelSession ───────────────────────────────────────── */
async cancelSession() {
  if (!this._sessionDetail) return;
  if (!confirm(`Cancel class "${this._sessionDetail.className}"? This cannot be undone.`)) return;
  try {
    const r = await fetch(`${_CDP_API}/api/scheduling/session/${this._sessionDetail.id}`, {
      method: 'DELETE',
      headers: { Authorization: 'Bearer ' + this._getToken() },
    });
    if (!r.ok) throw new Error('Failed');
    window.showToast?.('Class cancelled', 'success');
    this.close();
    if (this._afterSessionCancel) await this._afterSessionCancel();
  } catch {
    window.showToast?.('Failed to cancel class', 'error');
  }
},

/* ── Add student search ──────────────────────────────────── */
searchStudentDebounced(q) {
  if (this._sessionDetail?.isFreelance) return;
  if (this._searchTimeout) clearTimeout(this._searchTimeout);
  this._searchTimeout = window.setTimeout(() => this._searchStudent(q), 300);
},

async _searchStudent(q) {
  const el = document.getElementById('cdpAddResults');
  if (!el) return;
  if (!q || q.length < 2) { el.innerHTML = ''; return; }
  try {
    const clients = await fetch(`${_CDP_API}/api/client?search=${encodeURIComponent(q)}`,
      { headers: { Authorization: 'Bearer ' + this._getToken() } }).then(r => r.json());
    this._renderStudentResults(clients.slice(0, 5));
  } catch { el.innerHTML = ''; }
},

