/// <summary>
/// Returns bookings joined with CalendarSession for rich UI rendering
/// (date/time, instructor, format, class name).
/// </summary>
public async Task<IEnumerable<object>> GetMyBookingsEnrichedAsync(string clientId)
{
    var bookings = await _attendances
        .Find(a => a.ClientId == clientId)
        .SortByDescending(a => a.BookedAt)
        .ToListAsync();

    if (bookings.Count == 0) return Array.Empty<object>();

    // Migrated historical attendances may not have a session attached;
    // we only project session details when one is present.
    var sessionIds = bookings
        .Where(b => !string.IsNullOrEmpty(b.CalendarSessionId))
        .Select(b => b.CalendarSessionId!)
        .Distinct()
        .ToList();
    var sessions = await _sessions.Find(s => sessionIds.Contains(s.Id!)).ToListAsync();
    var sessionMap = sessions.ToDictionary(s => s.Id!, s => s);

    return bookings.Select(b =>
    {
        CalendarSession? session = null;
        if (!string.IsNullOrEmpty(b.CalendarSessionId))
        {
            sessionMap.TryGetValue(b.CalendarSessionId, out session);
        }
        return new
        {
            id = b.Id,
            bookingReference = b.BookingReference,
            calendarSessionId = b.CalendarSessionId,
            // Which ClientPackage was charged — exposed so the My-Packages page
            // can attribute credit deductions to a specific package instance.
            packageInstanceId = b.PackageInstanceId,
            status = b.Status,
            bookingSource = b.BookingSource,
            bookedAt = b.BookedAt,
            isFreeClass = b.IsFreeClass,
            paymentMethod = b.PaymentMethod,
            amountPaid = b.AmountPaid,
            amountDueAtStudio = b.AmountDueAtStudio,
            // Multi-seat group bookings: surface so the My-Packages credit
            // history can render “-N credits” rather than the legacy “-1”.
            quantity = b.Quantity <= 0 ? 1 : b.Quantity,
            goals = b.Goals,
            // Session details
            className = session?.ClassName,
            instructorName = session?.InstructorName,
            instructorPhotoUrl = session?.InstructorPhotoUrl,
            format = session?.Format ?? "GROUP",
            level = session?.DifficultyLevel,
            focusArea = session?.FocusArea,
            imageUrl = session?.ImageUrl,
            equipmentType = session?.EquipmentType ?? b.EquipmentType,
            startTime = session?.StartTime,
            endTime = session?.EndTime,
            durationMinutes = session != null ? (int)(session.EndTime - session.StartTime).TotalMinutes : 60
        };
    });
}

