/* ── Edit Session Modal ──────────────────────────────────── */
openEditModal() {
  if (!this._sessionDetail) { window.showToast?.('No session selected', 'error'); return; }
  const c = this._sessionDetail;
  const modal = document.getElementById('cdpEditModal');
  if (!modal) return;
  (document.getElementById('cdpEsClassName')).value = c.className || '';
  (document.getElementById('cdpEsStartTime')).value = this._isoLocal(new Date(c.startTime));
  const dur = Math.round((new Date(c.endTime) - new Date(c.startTime)) / 60000);
  (document.getElementById('cdpEsDuration')).value = String(dur || 60);
  (document.getElementById('cdpEsCapacity')).value = String(c.capacity || 10);
  (document.getElementById('cdpEsDifficulty')).value = c.difficultyLevel || 'ALL_LEVELS';
  (document.getElementById('cdpEsFocusArea')).value = c.focusArea || '';
  (document.getElementById('cdpEsNote')).value = '';
  const sel = document.getElementById('cdpEsInstructorId');
  const staffList = this._getStaffList();
  sel.innerHTML = '<option value="">Select instructor...</option>' +
    staffList.filter(s => s.isActive !== false).map(s =>
      `<option value="${s.id}" ${s.id === c.instructorId ? 'selected' : ''}>${this._esc(s.name)}${s.role ? ` (${s.role})` : ''}</option>`
    ).join('');
  const statusSel = document.getElementById('cdpEsStatus');
  if (statusSel) statusSel.value = c.status || '';
  const pubChk = document.getElementById('cdpEsIsPublic');
  // Default to public (checked) when the field is missing on legacy sessions.
  if (pubChk) pubChk.checked = c.isPublic !== false;
  modal.classList.add('open');
},

closeEditModal() {
  document.getElementById('cdpEditModal')?.classList.remove('open');
},

async saveEdit() {
  if (!this._sessionDetail) return;
  const sid = this._sessionDetail.id;
  const start = new Date((document.getElementById('cdpEsStartTime')).value);
  const end = new Date(start);
  end.setMinutes(end.getMinutes() + parseInt((document.getElementById('cdpEsDuration')).value));
  const instSel = document.getElementById('cdpEsInstructorId');
  const instName = instSel.options[instSel.selectedIndex]?.text?.split(' (')[0] || '';
  const body = {
    className: (document.getElementById('cdpEsClassName')).value.trim(),
    instructorId: instSel.value || null, // SPM-122 — send null, not '', for "no instructor"
    instructorName: instName,
    startTime: start.toISOString(),
    endTime: end.toISOString(),
    capacity: parseInt((document.getElementById('cdpEsCapacity')).value),
    difficultyLevel: (document.getElementById('cdpEsDifficulty')).value,
    focusArea: (document.getElementById('cdpEsFocusArea')).value.trim(),
    note: (document.getElementById('cdpEsNote')).value.trim() || null,
    status: (document.getElementById('cdpEsStatus'))?.value || null,
    isPublic: (document.getElementById('cdpEsIsPublic'))?.checked ?? true,
  };
  try {
    const r = await fetch(`${_CDP_API}/api/scheduling/session/${sid}/override`, {
      method: 'PATCH',
      headers: { Authorization: 'Bearer ' + this._getToken(), 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
    if (!r.ok) { const err = await r.text(); throw new Error(err); }
    window.showToast?.('Session updated', 'success');
    this.closeEditModal();
    if (this._afterSessionEdit) await this._afterSessionEdit(sid);
    else this.refresh();
  } catch (err) {
    window.showToast?.(`Failed to update session: ${err.message}`, 'error');
  }
},

/* ── Collect Payment — redirect to POS ───────────────────── */
showCollectPayment(attendanceId, amountDue, clientId, clientName) {
  // Build POS redirect URL with pre-populated query params
  const session = this._sessionDetail;
  const sessionId = session?.id || '';
  const className = encodeURIComponent(session?.className || 'Class Session');
  const instructorName = encodeURIComponent(session?.instructorName || '');
  const st = session?.startTime ? new Date(session.startTime) : null;
  const sessionLabel = st
    ? encodeURIComponent(st.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' }) +
      ' ' + st.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' }))

/// Override a materialised session: reschedule, swap instructor, change capacity.
/// The original session is mutated in-place with IsOverride = true.
/// </summary>
[HttpPatch("session/{id}/override")]
[Authorize(Roles = "Admin,Manager,Instructor")]
public async Task<IActionResult> OverrideSession(string id, [FromBody] OverrideSessionRequest request)
{
    // SPM-91 — resolve the public-visibility intent. When the request omits
    // IsPublic (legacy clients), preserve the session's current value rather
    // than defaulting it on or off.
    var current = await _schedulingService.GetSessionByIdAsync(id);
    if (current is null) return NotFound(new { message = "Session not found." });

    var updated = new CalendarSession
    {
        InstructorId = request.InstructorId,
        InstructorName = request.InstructorName,
        ClassName = request.ClassName,
        FocusArea = request.FocusArea,
        DifficultyLevel = request.DifficultyLevel,
        Capacity = request.Capacity,
        StartTime = request.StartTime,
        EndTime = request.EndTime,
        Status = request.Status,
        IsPublic = request.IsPublic ?? current.IsPublic,
    };
    var success = await _schedulingService.OverrideSessionAsync(id, updated, request.Note);
    if (!success) return NotFound(new { message = "Session not found." });
    return Ok(new { message = "Session overridden." });
}

/// <summary>
/// Returns all sessions for a specific studio-local date. Used by the
/// admin day-view calendar.
/// </summary>
[HttpGet("day/{date}")]
[Authorize(Roles = "Admin,Manager,Receptionist,Instructor")]
public async Task<IActionResult> GetDayView(DateTime date)
{
    var sessions = await _schedulingService.GetSessionsByDateAsync(date);
    return Ok(sessions);
}

// ── V2: Freelance Operations ─────────────────────────────────────────

/// <summary>
/// Create a freelance rental session. Admin only.
/// </summary>
[HttpPost("session/freelance")]
[Authorize(Roles = "Admin,Manager")]

public async Task<bool> OverrideSessionAsync(string sessionId, CalendarSession updated, string? note)
{
    // SPM-87 — load the existing session FIRST so we can detect an
    // instructor re-assignment (old vs new InstructorId) after the save.
    var existing = await _sessions.Find(s => s.Id == sessionId).FirstOrDefaultAsync();

    // SPM-122 — InstructorId is [BsonRepresentation(ObjectId)]; an empty string can't
    // serialize as an ObjectId (this path is reused by SPM-106 instructor transfer).
    // Normalize blank -> null before the Set().
    updated.InstructorId = string.IsNullOrWhiteSpace(updated.InstructorId) ? null : updated.InstructorId;

    var updateDef = Builders<CalendarSession>.Update
        .Set(s => s.InstructorId, updated.InstructorId)
        .Set(s => s.InstructorName, updated.InstructorName)
        .Set(s => s.ClassName, updated.ClassName)
        .Set(s => s.FocusArea, updated.FocusArea)
        .Set(s => s.DifficultyLevel, updated.DifficultyLevel)
        .Set(s => s.Capacity, updated.Capacity)
        .Set(s => s.StartTime, updated.StartTime)
        .Set(s => s.EndTime, updated.EndTime)
        .Set(s => s.Origin, "OVERRIDE")
        .Set(s => s.IsOverride, true)
        .Set(s => s.OverrideNote, note)
        // SPM-91 — persist the per-session public-visibility override. The
        // controller resolves the value (request value, else the session's
        // current value) before calling, so this is always the intended state.
        .Set(s => s.IsPublic, updated.IsPublic)
        .Set(s => s.UpdatedAt, DateTime.UtcNow);

    // Apply status override only when explicitly provided.
    if (!string.IsNullOrWhiteSpace(updated.Status))
        updateDef = updateDef.Set(s => s.Status, updated.Status);

    var result = await _sessions.UpdateOneAsync(s => s.Id == sessionId, updateDef);

    // SPM-87 — notify the newly-assigned instructor (push + email-fallback)
    // only when the instructor actually changed, so no-op saves stay quiet.
    NotifyInstructorReassignedIfChanged(existing, updated);

    return result.ModifiedCount > 0;
}

