// ── Load equipment filter pills from API ──────────────────────────────
async function loadEquipmentFilters() {
  const group = document.getElementById('equipmentGroup');
  try {
    const res = await fetch(`${API}/api/equipment/public`);
    if (!res.ok) throw new Error('Bad response');
    const items = await res.json();

    // Build NAME -> ImageUrl lookup so class cards can render the equipment
    // image as their thumbnail. Key is normalized for flexible matching
    // against the session's free-text equipmentType.
    equipmentImageByName = {};
    items.forEach((eq) => {
      if (eq && eq.name && eq.imageUrl) {
        const key = normalizeEquipType(eq.name);
        if (key) equipmentImageByName[key] = eq.imageUrl;
      }
    });

    // Clear skeletons
    group.innerHTML = '';

    if (!items.length) {
      // No equipment configured yet — hide the separator and group
      group.style.display = 'none';
      return;
    }

    items.forEach((eq) => {
      const btn = document.createElement('button');
      btn.className = 'sp-filter-pill';
      btn.dataset.equipment = eq.name;  // Use name as the filter key
      btn.textContent = eq.name;
      btn.addEventListener('click', () => {
        const wasActive = btn.classList.contains('active');
        group.querySelectorAll('[data-equipment]').forEach((b) => b.classList.remove('active'));
        if (!wasActive) {
          btn.classList.add('active');
          activeEquipment = eq.name;
        } else {
          activeEquipment = null;
        }
        renderClasses();
      });
      group.appendChild(btn);
    });
  } catch {
    // Silently clear skeletons on failure — booking still works without filter
    group.innerHTML = '';
    group.style.display = 'none';
  }
}

function buildInstructorFilter(sessions) {
  const names = [
    ...new Set(sessions.map((s) => s.instructorName).filter(Boolean)),
  ].sort();
  const group = document.getElementById("instructorGroup");

  if (names.length <= 1) {
    group.style.display = "none";
    return;
  }
  group.style.display = "flex";

  // Remove previous dynamic pills (keep static "All Instructors")
  group
    .querySelectorAll("[data-instructor]:not([data-instructor='all'])")
    .forEach((el) => el.remove());

  // Reset All-Instructors button
  const allBtn = group.querySelector("[data-instructor='all']");
  const freshAll = allBtn.cloneNode(true);
  allBtn.replaceWith(freshAll);
  freshAll.classList.add("active");
  freshAll.addEventListener("click", () => {
    group
      .querySelectorAll("[data-instructor]")
      .forEach((b) => b.classList.remove("active"));
    freshAll.classList.add("active");

