// ─── Service worker registration ──────────────────────────────────────────
//
// Imported once by AdminLayout.astro. Responsibilities:
//   1. Register /sw.js at the broadest scope ("/") so the same worker
//      controls both /admin/* and the public booking portal.
//   2. Listen for an updated worker landing in `waiting` state and surface a
//      "Refresh to update" toast that, when clicked, posts SKIP_WAITING to
//      activate the new SW immediately.
//   3. Gracefully no-op in browsers without SW support (very rare in 2026
//      but worth doing — the page still works as a plain SPA).
//
// We register on the `load` event so it never delays the first paint.

(function () {
  if (!("serviceWorker" in navigator)) return;

  // Only register from a secure context. Localhost is allowed by spec; in
  // production this is gated by HTTPS, which the reverse proxy provides.
  if (!window.isSecureContext && location.hostname !== "localhost") return;

  window.addEventListener("load", async () => {
    try {
      const registration = await navigator.serviceWorker.register("/sw.js", {
        scope: "/",
      });

      // Surface updates as a "Refresh" toast. We only show this once an
      // installed-but-waiting worker actually exists, so first-time visitors
      // don't see anything unusual.
      registration.addEventListener("updatefound", () => {
        const installing = registration.installing;
        if (!installing) return;
        installing.addEventListener("statechange", () => {
          if (
            installing.state === "installed" &&
            navigator.serviceWorker.controller // there's an old SW controlling the page → this is an update
          ) {
            showUpdateToast(registration);
          }
        });
      });

      // Periodic update check — re-fetches /sw.js and the manifest every
      // hour while the app is open. Cheap; no-ops when nothing changes.
      setInterval(() => registration.update().catch(() => {}), 60 * 60 * 1000);
    } catch (err) {
      console.warn("[sw] registration failed:", err);
    }
  });

  // When the new SW takes control, reload once so the page is served by it.
  // We track whether we initiated the reload to avoid an infinite refresh
  // loop in edge cases (e.g. user has multiple tabs open).
  let reloading = false;
  navigator.serviceWorker.addEventListener("controllerchange", () => {
    if (reloading) return;
    reloading = true;
    window.location.reload();
  });

  function showUpdateToast(registration) {
    // Use the global showToast helper from AdminLayout when available;
    // fall back to a plain confirm() for surfaces that don't ship it.
    if (typeof window.showToast === "function") {
      window.showToast("A new version is available — refresh to update", "warning");
      // Auto-apply after a short delay so the user sees the toast first.
      setTimeout(() => {
        registration.waiting?.postMessage({ type: "SKIP_WAITING" });
      }, 2500);
    } else if (window.confirm("New version available. Refresh now?")) {
      registration.waiting?.postMessage({ type: "SKIP_WAITING" });
    }
  }
})();

