939	    function renderClassCard(s) {
940	      const start = new Date(s.startTime);
941	      const end = new Date(s.endTime);
942	      const duration = Math.round((end - start) / 60000);
943	
944	      // Split time into hour and AM/PM (always en-US for visual consistency)
945	      const timeStr = start.toLocaleTimeString("en-US", {
946	        hour: "numeric",
