function renderClassCard(s) {
  const start = new Date(s.startTime);
  const end = new Date(s.endTime);
  const duration = Math.round((end - start) / 60000);

  // Split time into hour and AM/PM (always en-US for visual consistency)
  const timeStr = start.toLocaleTimeString("en-US", {
    hour: "numeric",
    minute: "2-digit",
    hour12: true,
  });
  const lastSpace = timeStr.lastIndexOf(" ");
  const hourPart =
    lastSpace > 0 ? timeStr.substring(0, lastSpace) : timeStr;
  const ampmPart = lastSpace > 0 ? timeStr.substring(lastSpace + 1) : "";

  // Level CSS + label
  const lvl = s.difficultyLevel || "ALL_LEVELS";
  const levelCssMap = {
    BEGINNER: "beginner",
    INTERMEDIATE: "intermediate",
    ADVANCED: "advanced",
    ALL_LEVELS: "all-levels",
  };
  const levelCss = levelCssMap[lvl] || "all-levels";
  const levelLabelMap = {
    BEGINNER: t("booking.beginner"),
    INTERMEDIATE: t("booking.intermediate"),
    ADVANCED: t("booking.advanced"),
    ALL_LEVELS: t("booking.allLevels") || "All Levels",
  };
  const levelLabel = levelLabelMap[lvl] || lvl;

  // Spots
  const total = s.capacity || 10;
  const booked = s.currentBookings || 0;
  const spotsLeft = Math.max(0, s.spotsLeft ?? total - booked);
  const ratio = booked / total;
  const isFull = spotsLeft <= 0;

  // Availability dots (cap at 10)
  const dotCount = Math.min(total, 10);
  const bookedDots = Math.round(ratio * dotCount);
  let dotClass = "booked";
  if (ratio >= 0.9) dotClass = "booked danger";
  else if (ratio >= 0.7) dotClass = "booked warning";
  let dots = "";
  for (let i = 0; i < dotCount; i++) {
    dots += `<span class="sp-dot ${i < bookedDots ? dotClass : ""}"></span>`;
  }

  const spotsColorClass = isFull
    ? "sp-spots-danger"
    : spotsLeft <= 2
      ? "sp-spots-warning"
      : "";
  const spotsText = isFull
    ? t("booking.full") || "Full"
    : `${spotsLeft} / ${total} spots left`;

  // Tags
  const tagsHtml = (s.tags || [])
    .slice(0, 3)
    .map((tag) => `<span class="sp-tag">${escapeHtml(tag)}</span>`)
    .join("");

  // SPM-71 — Equipment label: join all equipment used by the class.
  const equipNames = sessionEquipmentList(s);
  const equipLabel = equipNames.length
    ? equipNames.map((n) => equipmentDisplayName(n)).join(", ")
    : "";

  const equipIcon = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="2" y="9" width="20" height="6" rx="2"/><line x1="7" y1="9" x2="7" y2="15"/></svg>`;
  const personIcon = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="7" r="4"/><path d="M5.5 21a6.5 6.5 0 0 1 13 0"/></svg>`;

  // Thumbnail — SPM-77: collect EVERY equipment image the class has. With
  // multiple images the thumb becomes an auto-playing cross-fade gallery
  // (started in renderClasses); with one image it's a single static thumb;
  // with none we fall back to the blueprint hero image, then the
  // no-thumbnail state.
  const equipImageUrls = [];
  for (const name of equipNames) {
    const key = normalizeEquipType(name);
    const url = key ? equipmentImageByName[key] : null;
    if (url && !equipImageUrls.includes(url)) equipImageUrls.push(url);
  }

  let thumbHtml = null;
  if (equipImageUrls.length > 1) {
    // Auto-playing gallery — first image active, the rest cross-fade in.
    const slides = equipImageUrls
      .map(
        (url, i) =>
          `<img class="sp-class-image${i === 0 ? " is-active" : ""}" src="${escapeHtml(url)}" alt="${escapeHtml(s.className)}" loading="lazy"/>`,
      )
      .join("");
    thumbHtml = `<div class="sp-card-thumb sp-thumb-gallery">${slides}</div>`;
  } else {
    const thumbUrl = equipImageUrls[0] || s.imageUrl;
    if (thumbUrl) {

