function equipmentDisplayName(type) {
  // Normalize first to handle any casing stored in DB
  const norm = normalizeEquipType(type);
  const map = {
    REFORMER: t("booking.reformer") || "Reformer",
    WUNDA_CHAIR: t("booking.wundaChair") || "Wunda Chair",
    LADDER_BARREL: t("booking.ladderBarrel") || "Ladder Barrel",
  };
  return map[norm] || type;
}

function escapeHtml(s) {
  return String(s || "").replace(
    /[&<>"']/g,
    (c) =>
      ({
        "&": "&amp;",
        "<": "&lt;",
        ">": "&gt;",
        '"': "&quot;",
        "'": "&#39;",
      })[c],
  );
}

