.sp-class-time {
  min-width: 70px;
  display: flex;
  flex-direction: column;
  padding-right: var(--sp-space-xl);
}

.sp-class-time-value {
  font-size: 15px;
  font-weight: 600;
  color: var(--sp-text-primary);
  line-height: 1.2;
}

.sp-class-time-period {
  font-size: 13px;
  font-weight: 600;
  color: var(--sp-text-primary);
}

.sp-class-time-duration {
  font-size: 12px;
  color: var(--sp-text-muted);
  margin-top: var(--sp-space-xs);
}

/* Center content */
.sp-class-info {
  flex: 1;
  min-width: 0;
}

.sp-class-title-row {
  display: flex;
  align-items: center;
  gap: var(--sp-space-sm);
  margin-bottom: var(--sp-space-sm);
  flex-wrap: wrap;
}

.sp-class-name {
  font-size: 16px;
  font-weight: 600;
  color: var(--sp-text-primary);
  letter-spacing: -0.1px;
}

.sp-class-meta {
  display: flex;
  align-items: center;
  gap: var(--sp-space-lg);
  margin-bottom: var(--sp-space-md);
  color: var(--sp-text-muted);
  font-size: 13px;
}

.sp-class-meta-item {
  display: flex;
  align-items: center;
  gap: var(--sp-space-xs);
}

.sp-class-meta-item svg {
  width: 14px;
  height: 14px;
}

.sp-class-tags {
  display: flex;
  flex-wrap: wrap;
  gap: var(--sp-space-xs);
}

/* Right section */
.sp-class-right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  justify-content: space-between;
  min-width: 160px;
  padding-left: var(--sp-space-xl);
}

.sp-class-image {
  width: 140px;
  height: 100px;
  border-radius: var(--sp-radius-md);
  object-fit: cover;
  background: var(--sp-surface-raised);
}

.sp-class-image-placeholder {
  width: 140px;
  height: 100px;
  border-radius: var(--sp-radius-md);
  background: linear-gradient(135deg, var(--sp-surface-raised), var(--sp-border));
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--sp-text-muted);
}

.sp-class-image-placeholder svg {
  width: 32px;
  height: 32px;
  opacity: 0.3;
}

.sp-class-spots {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: var(--sp-space-xs);
  margin-top: var(--sp-space-sm);
}

.sp-class-spots-text {
  font-size: 13px;
  font-weight: 500;
  color: var(--sp-text-secondary);
}

/* Availability dots */
.sp-dots {
  display: flex;
  gap: 3px;
  align-items: center;
}

.sp-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--sp-border);
  transition: background var(--sp-transition-fast);
}

.sp-dot.booked {
  background: var(--sp-success);
}

.sp-dot.booked.warning {
  background: var(--sp-warning);
}

.sp-dot.booked.danger {
  background: var(--sp-danger);
}

.sp-class-cta {
  margin-top: var(--sp-space-sm);
}

/* ─── Level Badge ────────────────────────────────────────────────── */
.sp-badge-level {
  display: inline-flex;
  align-items: center;
  padding: 3px 10px;
  border-radius: var(--sp-radius-full);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.3px;
}

