@media (max-width: 1024px) {
  .sp-content {
    padding: var(--sp-space-xl) var(--sp-space-xl);
  }

  .sp-class-right {
    min-width: 120px;
  }

  .sp-class-image,
  .sp-class-image-placeholder {
    width: 110px;
    height: 80px;
  }

  :root {
    --sp-offcanvas-width: 600px;
  }
}

/* ── Mobile (≤768px) ─────────────────────────────────────────────── */
@media (max-width: 768px) {
  .sp-topnav {
    display: none !important;
  }

  .sp-bottomnav {
    display: block !important;
  }

  .sp-day-strip {
    display: flex !important;
  }

  .sp-main {
    padding-top: 0;
  }

  .sp-content {
    padding: var(--sp-space-lg) var(--sp-space-lg);
    padding-bottom: calc(var(--sp-bottomnav-height) + var(--sp-space-lg));
  }

  /* Mobile top bar (simplified) */
  .sp-mobile-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    height: 48px;
    padding: 0 var(--sp-space-lg);
    width: 100%;
    background: var(--sp-white);
    border-bottom: 1px solid var(--sp-border);
    position: sticky;
    top: 0;
    z-index: 100;
  }

  .sp-mobile-header .sp-logo-text {
    font-size: 14px;
    letter-spacing: 3px;
  }

  /* Class card — mobile layout */
  .sp-class-card {
    flex-direction: column;
    padding: var(--sp-space-lg);
  }

  .sp-class-time {
    flex-direction: row;
    align-items: baseline;
    gap: var(--sp-space-xs);
    padding-right: 0;
    padding-bottom: var(--sp-space-sm);
    min-width: unset;
  }

  .sp-class-right {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
    min-width: unset;
    padding-left: 0;
    padding-top: var(--sp-space-md);
  }

  .sp-class-image,
  .sp-class-image-placeholder {
    width: 80px;
    height: 80px;
    position: absolute;
    top: var(--sp-space-lg);
    right: var(--sp-space-lg);
  }

  .sp-credits-badge {
    display: none;
  }

  /* Offcanvas → Full screen on mobile */
  .sp-offcanvas {
    width: 100%;
    max-width: 100%;
    top: 0;
    right: 0;
    bottom: 0;
    transform: translateY(100%);
  }

  .sp-offcanvas-overlay.open .sp-offcanvas {
    transform: translateY(0);
  }

  .sp-offcanvas-hero {
    height: 260px;
  }

  /* Filters — scrollable */
  .sp-filters {
    flex-wrap: nowrap;
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
    scrollbar-width: none;
    padding-bottom: var(--sp-space-xs);
  }

  .sp-filters::-webkit-scrollbar {
    display: none;
  }

  /* Day header hidden (day strip handles it) */
  .sp-day-header {
    display: none;
  }

  .sp-hidden-mobile {
    display: none !important;
  }

  .sp-hidden-desktop {
    display: flex;
  }

  .sp-form-input {
    min-height: 44px;
    font-size: 16px;
  }

  .sp-btn {
    min-height: 44px;
  }

  .sp-form-row {
    grid-template-columns: 1fr;
  }

  .sp-heading-page {
    font-size: 20px;
  }

  .sp-topnav-links {
    display: none;
  }
}

