function renderPage(page) {
  currentPage = page;
  const start = (page - 1) * PAGE_SIZE;
  const slice = filtered.slice(start, start + PAGE_SIZE);
  document.getElementById('productCount').textContent = `${filtered.length} products`;
  document.getElementById('productCountTop').textContent = `${filtered.length} shown`;
  const tbody = document.getElementById('productTable');
  if (!slice.length) {
    tbody.innerHTML = `<tr><td colspan="7" style="text-align:center;padding:40px;color:var(--color-text-muted);">No products found</td></tr>`;
  } else {
    const typeLabel = {
      PACKAGE: 'Package',
      MERCHANDISE: 'Merch',
      FREELANCE_PACKAGE: 'Rental Package',
      FREELANCE_SINGLE: 'Rental Class',
    };
    const formatLabel = {
      GROUP: 'Group',
      MAT: 'Mat Group Classes',
      PRIVATE: 'Private',
      DUO: 'Duo',
      NONE: 'Any',
    };
    tbody.innerHTML = slice.map(p => {
      const lowCount = lowStockByProduct[p.id] ?? 0;
      const pill = lowCount > 0
        ? `<span class="badge" style="background:var(--color-warning-soft, #fef3c7);color:var(--color-warning, #b45309);font-size:11px;margin-left:8px;font-weight:600;" title="${lowCount} variant(s) at or below reorder threshold">Restock ${lowCount}</span>`
        : '';
      const iconKey = p.iconKey || defaultIconForType(p.type);
      // Encode the id during template rendering so the resulting onclick
      // attribute is a fully-resolved URL. The previous version had no
      // interpolation and emitted a literal "p.id" reference, which fails
      // at click time with ReferenceError because the `p` parameter is
      // scoped to this .map() callback and is not a global.
      const editHref = `/admin/product-form?id=${encodeURIComponent(p.id)}`;
      return `
      <tr>
        <td>
          <div class="product-name-cell">
            <span class="product-icon-badge">${productIconSvg(iconKey)}</span>
            <div class="product-name-copy">
              <div class="product-name-title"><span class="font-medium">${p.name}</span>${pill}</div>
            </div>
          </div>
        </td>
        <td><span class="badge badge-default">${typeLabel[p.type] || p.type || '-'}</span></td>
        <td class="hidden-mobile">${p.type === 'MERCHANDISE' ? '<span class="text-muted text-sm">—</span>' : `<span class="badge badge-default">${formatLabel[p.formatRestriction] || p.formatRestriction || '—'}</span>`}</td>
        <td class="font-semibold">${(p.basePrice ?? 0).toLocaleString()} VND</td>
        <td class="text-muted text-sm">${p.credits ?? '-'}</td>
        <td><span class="badge badge-success">Active</span></td>

