using SoulPilates.Core.Entities;
using System.Collections.Generic;

namespace SoulPilates.Core.Entities;

public class Product : BaseEntity
{
    public string Name { get; set; } = null!;

    /// <summary>
    /// The product discriminator. Active types: <c>PACKAGE</c>,
    /// <c>MERCHANDISE</c>, <c>FREELANCE_PACKAGE</c>, and
    /// <c>FREELANCE_SINGLE</c>.
    /// </summary>
    public string Type { get; set; } = null!;
    public string FormatRestriction { get; set; } = "NONE"; // "GROUP", "PRIVATE", "MIXED", "NONE"
    public string? Description { get; set; }
    public string? IconKey { get; set; }

    public decimal BasePrice { get; set; }
    public decimal TaxRate { get; set; }
    public bool IsActive { get; set; } = true;

    /// <summary>
    /// Surfaces this product in the home page's "Featured Packages" strip. Only
    /// honoured for <see cref="Type"/> = <c>PACKAGE</c>; ignored for everything else.
    /// Defaults to <c>false</c> so existing products don't auto-promote into the new strip.
    /// </summary>
    public bool IsFeatured { get; set; } = false;

    /// <summary>
    /// Hides this product from the customer-facing online shop (package catalog /
    /// featured strip). Independent of <see cref="HiddenFromPos"/>. Defaults to
    /// <c>false</c> so existing documents stay visible after deserialization.
    /// </summary>
    public bool HiddenFromOnline { get; set; } = false;

    /// <summary>
    /// Hides this product from the in-store POS product grid. Independent of
    /// <see cref="HiddenFromOnline"/>. Defaults to <c>false</c> so existing
    /// documents stay visible after deserialization.
    /// </summary>
    public bool HiddenFromPos { get; set; } = false;

    // Package-specific fields.
    public int Credits { get; set; }

    /// <summary>
    /// Number of days a provisioned <see cref="ClientPackage"/> is valid for after
    /// activation. Set to <c>0</c> to create open-ended packages that never expire
    /// (<see cref="ClientPackage.ExpiryDate"/> will be <c>null</c>).
    /// </summary>
    public int ValidityDays { get; set; }
    public int MaxFreezeDays { get; set; }

    // Merchandise-specific (flattened from MerchandiseSku).
    // Post-P3-S14 these three fields are LEGACY: the authoritative inventory
    // unit is now <see cref="MerchandiseSku"/> (one row per Colour/Size variant
    // with its own StockQuantity + ReorderThreshold). These flat fields are kept
    // populated by the importer + admin form for backward compatibility with the
    // P&L grid and any analytics surface that still reads them, but POS sales no
    // longer mutate Product.StockQuantity — they mutate the matching SKU.
    public int StockQuantity { get; set; }
    public string? Sku { get; set; }
    public List<string> Variants { get; set; } = new();
}

