using MongoDB.Driver;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Interfaces;
using SoulPilates.Infrastructure.Data;
using System;
using System.Collections.Generic;
using System.Threading.Tasks;

namespace SoulPilates.Services;

public class ProductService : IProductService
{
    /// <summary>
    /// Closed list of accepted <see cref="Product.Type"/> discriminators. Anything outside this set is
    /// rejected at create/update time as a defence-in-depth guard against typo'd or fabricated values
    /// (the admin dropdown is the only happy-path entry, but the API surface is public-Authenticated).
    /// </summary>
    private static readonly HashSet<string> AllowedProductTypes = new(StringComparer.Ordinal)
    {
        "PACKAGE",
        "MERCHANDISE",
        "FREELANCE_PACKAGE",
        "FREELANCE_SINGLE",
    };

    private readonly IMongoCollection<Product> _products;

    public ProductService(MongoDbContext dbContext)
    {
        _products = dbContext.GetCollection<Product>("Products");
    }

    public async Task<IEnumerable<Product>> GetAllProductsAsync()
    {
        return await _products.Find(_ => true).ToListAsync();
    }

    public async Task<Product?> GetProductByIdAsync(string id)
    {
        return await _products.Find(p => p.Id == id).FirstOrDefaultAsync();
    }

    public async Task<Product> CreateProductAsync(Product product)
    {
        ValidateProductType(product);
        await _products.InsertOneAsync(product);
        return product;
    }

    public async Task UpdateProductAsync(string id, Product product)
    {
        ValidateProductType(product);
        product.Id = id;
        await _products.ReplaceOneAsync(p => p.Id == id, product);
    }

    public async Task DeleteProductAsync(string id)
    {
        var update = Builders<Product>.Update.Set(p => p.IsActive, false);
        await _products.UpdateOneAsync(p => p.Id == id, update);
    }

    private static void ValidateProductType(Product product)
    {
        if (product == null) throw new ArgumentNullException(nameof(product));
        if (string.IsNullOrWhiteSpace(product.Type))
        {
            throw new ArgumentException("Product.Type is required.", nameof(product));
        }
        if (!AllowedProductTypes.Contains(product.Type))
        {
            var allowed = string.Join(", ", AllowedProductTypes);
            throw new ArgumentException(
                $"Product.Type '{product.Type}' is not in the allowed set: {allowed}.",
                nameof(product));
        }
    }
}

