 */
function onTypeChange() {
  const type = document.getElementById("pType").value;
  const isMerch = type === "MERCHANDISE";
  const isPackage = type === "PACKAGE" || type === "FREELANCE_PACKAGE";
  const isStudioRental = type === "FREELANCE_PACKAGE" || type === "FREELANCE_SINGLE";
  const formatSelect = document.getElementById("pFormat");
  const duoOption = document.getElementById("pFormatDuo");

  document.getElementById("packageFields").style.display = isPackage
    ? ""
    : "none";
  document.getElementById("merchandiseFields").style.display = isMerch
    ? ""
    : "none";
  document.getElementById("formatGroup").style.display = isMerch
    ? "none"
    : "";

  // "Feature on storefront" only makes sense for sellable PACKAGE products.
  const featuredGroup = document.getElementById("featuredGroup");
  if (featuredGroup) {
    featuredGroup.style.display = type === "PACKAGE" ? "" : "none";
  }

  document.getElementById("pPriceHint").style.display = isStudioRental ? "block" : "none";
  if (duoOption) {
    duoOption.disabled = isStudioRental;
    duoOption.hidden = isStudioRental;
  }
  if (isStudioRental && formatSelect.value === "DUO") {
    formatSelect.value = "GROUP";
  }

  if (!iconTouched) {
    selectProductIcon(defaultIconForType(type), false);
  }

  if (!editId && rentalDefaults && isStudioRental) {
    const format = formatSelect.value;
    if (type === "FREELANCE_SINGLE") {
      document.getElementById("pPrice").value = format === "PRIVATE"
        ? (rentalDefaults.studioRentalPrivatePerHeadFee ?? 0)
        : (rentalDefaults.studioRentalGroupPerHeadFee ?? 0);
