      document.getElementById("pPrice").value = format === "PRIVATE"
        ? (rentalDefaults.studioRentalPrivatePackagePrice ?? 0)
        : (rentalDefaults.studioRentalGroupPackagePrice ?? 0);
      document.getElementById("pCredits").value = format === "PRIVATE"
        ? (rentalDefaults.studioRentalPrivatePackageCredits ?? 0)
        : (rentalDefaults.studioRentalGroupPackageCredits ?? 0);
    }
  }
}

