using MongoDB.Bson.Serialization.Attributes;

namespace SoulPilates.Core.Entities;

/// <summary>
/// An editable transactional email template (SPM-76). Stored as an embedded
/// sub-document inside <see cref="GlobalSettings.EmailTemplates"/> so the studio
/// owner can re-word any email from the admin Settings → Email Templates tab
/// without a code change.
///
/// <para>
/// Substitution convention: <c>{VariableName}</c> tokens (PascalCase) inside
/// <see cref="Subject"/> and <see cref="BodyHtml"/> are replaced at send-time by
/// <c>EmailService</c> with the live, HTML-encoded values for that send. The set
/// of tokens a template supports is fixed in code (the built-in defaults) — the
/// admin can move/remove/duplicate them but cannot invent new ones, because the
/// service only supplies the known dictionary keys.
/// </para>
///
/// <para>
/// SAFE-FALLBACK CONTRACT: when a stored template's <see cref="Subject"/> or
/// <see cref="BodyHtml"/> is blank (or the whole record is missing), the service
/// falls back to the hardcoded built-in default for that <see cref="Id"/>, so a
/// half-configured or never-touched template can never break a live email.
/// </para>
/// </summary>
public class EmailTemplate
{
    /// <summary>
    /// Stable template key — matches the constants in <c>EmailTemplateIds</c>
    /// (e.g. "booking-confirmation"). Used to look the template up at send-time
    /// and to backfill built-in defaults on read.
    /// </summary>
    public string Id { get; set; } = "";

    /// <summary>
    /// Human-readable label shown in the admin list (e.g. "Booking Confirmation").
    /// Informational only — not used for substitution.
    /// </summary>
    public string Name { get; set; } = "";

    /// <summary>
    /// The email subject line. May contain <c>{Token}</c> placeholders. Blank →
    /// service uses the built-in default subject for this <see cref="Id"/>.
    /// </summary>
    public string Subject { get; set; } = "";

    /// <summary>
    /// The inner body HTML fragment (the per-template content — NOT the shared
    /// chrome, which <c>EmailTemplateHelper.Layout</c> still wraps around it).
    /// May contain <c>{Token}</c> placeholders. Blank → service uses the built-in
    /// default body for this <see cref="Id"/>.
    /// </summary>
    public string BodyHtml { get; set; } = "";

    /// <summary>
    /// Tokens (without braces, e.g. "ClientName") that MUST appear — referenced as
    /// <c>{ClientName}</c> — somewhere in <see cref="Subject"/> + <see cref="BodyHtml"/>
    /// combined for the template to be considered valid. The update path rejects a
    /// save that drops any of these so an admin can't accidentally strip a critical
    /// field (e.g. a reset link) out of the email.
    /// </summary>
    public List<string> RequiredVariables { get; set; } = new();

    /// <summary>
    /// All tokens the service can substitute for this template (superset of
    /// <see cref="RequiredVariables"/>) — surfaced in the admin UI as the
    /// "available variables" reference list. Informational; not persisted-critical.
    /// </summary>
    public List<string> AvailableVariables { get; set; } = new();

    // ── SPM-76 follow-up — transient fields for the admin editor (API response only) ──
    // [BsonIgnore] keeps these OUT of the stored document, so the "blank stored field =
    // use built-in default at send-time" contract (and future-default tracking) is preserved;
    // GetEmailTemplatesAsync fills them so the editor can show the default, support
    // "Reset to default", and render the Customised badge.

    /// <summary>Built-in default subject — lets the editor's "Reset to default" restore it.</summary>
    [BsonIgnore] public string DefaultSubject { get; set; } = "";

    /// <summary>Built-in default body HTML — for "Reset to default".</summary>
    [BsonIgnore] public string DefaultBodyHtml { get; set; } = "";

    /// <summary>True when a stored non-blank override exists (drives the "Customised" badge).</summary>
    [BsonIgnore] public bool IsCustomised { get; set; }
}

