[HttpGet("stripe-keys")]
public async Task<IActionResult> GetStripeKeys(CancellationToken ct)
{
    var settings = await _settingsService.GetAsync(ct);
    var decrypted = await _settingsService.GetDecryptedStripeConfigAsync(ct);

    return Ok(new
    {
        enabled = settings.StripeEnabled,
        publishableKeyMasked = SettingsEncryptionHelper.Mask(decrypted.PublishableKey),
        secretKeyMasked = SettingsEncryptionHelper.Mask(decrypted.SecretKey),
        webhookSecretMasked = SettingsEncryptionHelper.Mask(decrypted.WebhookSecret),
        hasPublishableKey = !string.IsNullOrEmpty(decrypted.PublishableKey),
        hasSecretKey = !string.IsNullOrEmpty(decrypted.SecretKey),
        hasWebhookSecret = !string.IsNullOrEmpty(decrypted.WebhookSecret),
    });
}

