}

function renderTemplateList() {
  const list = document.getElementById('emailTplList');
  if (!templatesCache.length) {
    list.innerHTML = '<div style="color:var(--color-text-muted);font-size:13px;">No templates found.</div>';
    return;
  }
  list.innerHTML = templatesCache.map((t) => {
    const customised = !!t.isCustomised;
    const badge = customised
      ? '<span style="margin-left:8px;font-size:10px;padding:2px 8px;background:var(--color-brand-subtle,#eef0ff);border:1px solid var(--color-border-subtle);border-radius:999px;color:var(--color-brand,#635bff);">Customised</span>'
      : '<span style="margin-left:8px;font-size:10px;padding:2px 8px;background:var(--color-surface);border:1px solid var(--color-border-subtle);border-radius:999px;color:var(--color-text-muted);">Using default</span>';
    return `
      <div style="display:flex;align-items:center;gap:12px;padding:12px;border:1px solid var(--color-border-subtle);border-radius:var(--radius-sm);background:var(--color-surface-raised);">
        <div style="flex:1;min-width:0;">
          <div style="font-size:13px;font-weight:600;">${escapeHtml(t.name || t.id)}${badge}</div>
          <div style="font-size:11px;color:var(--color-text-muted);font-family:monospace;">${escapeHtml(t.id)}</div>
        </div>
        <button class="btn btn-secondary btn-sm" data-tpl-edit="${escapeHtml(t.id)}" type="button">Edit</button>
      </div>`;
  }).join('');

  list.querySelectorAll('[data-tpl-edit]').forEach((btn) => {
    btn.addEventListener('click', () => openEditor(btn.getAttribute('data-tpl-edit')));
  });
}

function openEditor(id) {
  const t = templatesCache.find((x) => x.id === id);
  if (!t) return;
  currentId = id;
  currentTpl = t;
  document.getElementById('emailTplEditId').value = id;
  document.getElementById('emailTplEditorTitle').textContent = `Edit: ${t.name || t.id}`;
  document.getElementById('emailTplEditorSubtitle').textContent =
    'Showing the built-in default — edit and Save to customise, or Reset to default to restore it. Highlighted chips are variables present in your text.';
  // Show the RESOLVED content (defaults filled in) so the editor is never blank.
  document.getElementById('emailTplSubject').value = t.subject || '';
  document.getElementById('emailTplBody').value = t.bodyHtml || '';
  document.getElementById('emailTplError').style.display = 'none';
  document.getElementById('emailTplSuccess').style.display = 'none';

  // Variable chips — colour is set dynamically by updateVarChips() based on whether
  // each {Token} currently appears in the subject/body.
  const varsWrap = document.getElementById('emailTplVars');
  const avail = Array.isArray(t.availableVariables) ? t.availableVariables : [];
  const required = Array.isArray(t.requiredVariables) ? t.requiredVariables : [];
  varsWrap.innerHTML = avail.map((v) => {
    const isReq = required.indexOf(v) !== -1;
    return `<button type="button" class="email-tpl-var-chip" data-var="${escapeHtml(v)}" data-required="${isReq ? '1' : '0'}"
