{
    var filters = new List<FilterDefinition<CalendarSession>>
    {
        Builders<CalendarSession>.Filter.Gte(s => s.StartTime, start),
        Builders<CalendarSession>.Filter.Lte(s => s.StartTime, end),
        Builders<CalendarSession>.Filter.Eq(s => s.Status, "SCHEDULED"),
        Builders<CalendarSession>.Filter.Eq(s => s.BlockedReason, (string?)null),
        // SPM-91 — only public sessions appear on the public booking page.
        // Use Ne(false) (not Eq(true)) so existing documents that predate the
        // IsPublic field — where the field is ABSENT, not stored true — still
        // match and stay public. A strict Eq(true) would wrongly hide them.
        Builders<CalendarSession>.Filter.Ne(s => s.IsPublic, false)
    };

    if (!string.IsNullOrWhiteSpace(format))
    {
        // MAT is a sub-type of group class. When the public schedule requests
        // GROUP, include MAT sessions too so "The Mat" blueprints appear on the
        // Group Classes tab without needing a separate tab.
        var upper = format.ToUpperInvariant();
        if (upper == "GROUP")
        {
            filters.Add(Builders<CalendarSession>.Filter.In(s => s.Format, new[] { "GROUP", "MAT" }));
        }
        else
        {
            filters.Add(Builders<CalendarSession>.Filter.Eq(s => s.Format, upper));
        }
    }

    if (!string.IsNullOrWhiteSpace(instructorId))
    {
        filters.Add(Builders<CalendarSession>.Filter.Eq(s => s.InstructorId, instructorId));
    }

    return await _sessions.Find(Builders<CalendarSession>.Filter.And(filters))
        .SortBy(s => s.StartTime)
        .ToListAsync();
}

