using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Interfaces;
using SoulPilates.Services;

namespace SoulPilates.API.Controllers;

[ApiController]
[Route("api/[controller]")]
[Authorize(Roles = "Admin")]
public class SettingsController : ControllerBase
{
    private readonly ISettingsService _settingsService;

    // Refactored in P1-S04: was directly injecting MongoDbContext, which violated
    // the controller-uses-service layer rule. The seed/backfill semantics now live
    // in SettingsService where domain rules belong.
    public SettingsController(ISettingsService settingsService)
    {
        _settingsService = settingsService;
    }

    [HttpGet]
    public async Task<IActionResult> GetSettings(CancellationToken ct)
    {
        var settings = await _settingsService.GetAsync(ct);

        // Sanitise — encrypted Stripe key fields must NEVER reach the frontend.
        // Null them out so they aren't serialised, then inject masked placeholders
        // as separate ad-hoc properties.
        var stripeConfig = await _settingsService.GetDecryptedStripeConfigAsync(ct);

        // Wipe encrypted blobs from the outbound entity — these are binary noise
        // to the frontend and must never leave the server.
        settings.StripePublishableKeyEncrypted = null;
        settings.StripeSecretKeyEncrypted = null;
        settings.StripeWebhookSecretEncrypted = null;

        // Return the full settings entity + masked display helpers.
        // Using an anonymous wrapper keeps the JSON shape flat (properties merge)
        // while the encrypted blobs are safely null/omitted.
        return Ok(new
        {
            // Spread all settings properties via serialisation
            settings.Id,
            settings.MarketingSplitPercentage,
            settings.SavingsSplitPercentage,
            settings.OwnersSplitPercentage,
            settings.CancelWindowHoursGroup,
            settings.CancelWindowHoursPrivate,
            settings.CancelWindowHoursCreditGroup,
            settings.CancelWindowHoursCreditPrivate,
            settings.CancelWindowHoursOnlineGroup,
            settings.CancelWindowHoursOnlinePrivate,
            settings.CancelWindowHoursStudioGroup,
            settings.CancelWindowHoursStudioPrivate,
            settings.EnableLateReschedule,
            settings.LateRescheduleMaxPerMonth,
            settings.LateRescheduleMode,
            settings.LateRescheduleEligibleMethods,
            settings.ExpenseCategories,
            settings.StripeRoutingMode,
            settings.OnlinePaymentFeePercentage,
            settings.StudioRentalGroupPerHeadFee,
            settings.StudioRentalPrivatePerHeadFee,
            settings.StudioRentalGroupPackagePrice,
            settings.StudioRentalGroupPackageCredits,
            settings.StudioRentalPrivatePackagePrice,
            settings.StudioRentalPrivatePackageCredits,
            settings.EnableReceptionistKpiProgram,
            settings.ReceptionistKpiBonusPoolAmount,
            settings.ReceptionistDailyTaskCompletionPercent,
            settings.ReceptionistAttendanceCommissionPerHead,
            settings.ReceptionistAttendanceSplitMode,
            settings.ReceptionistDailyTasks,
            settings.ReceptionistRevenueTiers,
            settings.ReceptionistPackageSalesTiers,
            settings.ReceptionistGoogleReviewTiers,
            settings.RoleAccessSettings,
            settings.AllowOnlinePayment,
            settings.AllowPartialPayment,
            settings.AllowPayAtStudio,
            settings.DepositPercentage,
            settings.PartialPaymentLabelEn,
            settings.PartialPaymentLabelVi,
            settings.EnableCheckoutPackageUpsell,
            settings.UpsellHideForActivePackageHolders,
            settings.UpsellHeadlineEn,
            settings.UpsellHeadlineVi,
            settings.UpsellPackageIdGroup,
            settings.UpsellPackageIdPrivate,
            settings.UpsellPackageIdMixed,
            settings.EnableWaitlistSystem,
            settings.EnableSignUpEmailVerification,
            settings.EnableReservationSystem,
            settings.ReservationExpiryMinutes,
            settings.ReservationCleanupIntervalMinutes,
            settings.AllowGuestCheckout,
            settings.EnableGoogleAnalyticsEventTracking,
            settings.GoogleAnalyticsMeasurementId,
            settings.EnableRetentionReminders,
            settings.RetentionReminderInactivityDays,
            settings.RetentionReminderTickHours,
            settings.RetentionReminderMinCreditsRemaining,
            settings.RetentionReminderWindows,
            settings.MaterialisationHorizonDays,

            // Stripe — masked display values only (never raw)
            StripeEnabled = settings.StripeEnabled,
            StripePublishableKeyMasked = SettingsEncryptionHelper.Mask(stripeConfig.PublishableKey),
            StripeSecretKeyMasked = SettingsEncryptionHelper.Mask(stripeConfig.SecretKey),
            StripeWebhookSecretMasked = SettingsEncryptionHelper.Mask(stripeConfig.WebhookSecret),
        });
    }

    [HttpPost]
    public async Task<IActionResult> UpdateSettings([FromBody] GlobalSettings update, CancellationToken ct)
    {
        try
        {
            var saved = await _settingsService.UpdateAsync(update, ct);
            return Ok(saved);
        }
        catch (InvalidOperationException ex)
        {
            // Service-layer validation (allocation sum, negatives) → 400 with the
            // validation message verbatim so the admin UI can render it inline.
            return BadRequest(new { message = ex.Message });
        }
    }

    /// <summary>
    /// Partial-update for the retention-reminder fields only. Avoids the
    /// full-document <see cref="UpdateAsync"/> path that requires the
    /// allocation triple to sum to 100 — admins editing only the retention
    /// card shouldn't need to re-supply unrelated financial fields.
    /// </summary>
    [HttpPatch("retention")]
    public async Task<IActionResult> UpdateRetentionSettings(
        [FromBody] RetentionSettingsPatch patch,
        CancellationToken ct)
    {
        var saved = await _settingsService.UpdateRetentionAsync(patch, ct);
        return Ok(saved);
    }

    // ── P2-S01: per-month allocation overrides ─────────────────────────────

    [HttpGet("allocation-overrides")]
    public async Task<IActionResult> ListAllocationOverrides(CancellationToken ct)
    {
        var rows = await _settingsService.ListAllocationOverridesAsync(ct);
        return Ok(rows);
    }

    [HttpGet("allocation-overrides/effective/{year:int}/{month:int}")]
    public async Task<IActionResult> GetEffectiveAllocation(int year, int month, CancellationToken ct)
    {
        var (marketing, savings, owners) = await _settingsService.GetEffectiveAllocationAsync(year, month, ct);
        return Ok(new { year, month, marketing, savings, owners });
    }

    [HttpPost("allocation-overrides")]
    public async Task<IActionResult> UpsertAllocationOverride([FromBody] MonthlyAllocationOverride payload, CancellationToken ct)
    {
        try
        {
            var saved = await _settingsService.UpsertAllocationOverrideAsync(payload, ct);
            return Ok(saved);
        }
        catch (InvalidOperationException ex)
        {
            return BadRequest(new { message = ex.Message });
        }
    }

    [HttpDelete("allocation-overrides/{id}")]
    public async Task<IActionResult> DeleteAllocationOverride(string id, CancellationToken ct)
    {
        await _settingsService.DeleteAllocationOverrideAsync(id, ct);
        return NoContent();
    }

    // ── V2 Schedule: Company Operating Hours ────────────────────────────

    /// <summary>
    /// Returns the studio's operating hours, holidays, and date-specific overrides.
    /// </summary>
    [HttpGet("schedule")]
    public async Task<IActionResult> GetScheduleConfig(CancellationToken ct)
    {
        var config = await _settingsService.GetScheduleConfigAsync(ct);
        return Ok(config);
    }

    /// <summary>
    /// Replaces the studio's operating hours, holidays, and date-specific overrides.
    /// Validates time ordering and date formats before saving.
    /// </summary>
    [HttpPost("schedule")]
    public async Task<IActionResult> UpdateScheduleConfig(
        [FromBody] CompanyScheduleConfig config,
        CancellationToken ct)
    {
        try
        {
            var saved = await _settingsService.UpdateScheduleConfigAsync(config, ct);
            return Ok(saved);
        }
        catch (InvalidOperationException ex)
        {
            return BadRequest(new { message = ex.Message });
        }
    }

    // ── V2: Materialisation Horizon ────────────────────────────────────────

    /// <summary>
    /// Partial update — sets <c>MaterialisationHorizonDays</c> only, without
    /// touching any other settings field. Avoids the risky GET→full-POST
    /// round-trip that could race-overwrite other concurrently-saved settings.
    /// Clamps the value to the allowed range [7, 365] server-side.
    /// </summary>
    [HttpPatch("horizon")]
    public async Task<IActionResult> UpdateMaterialisationHorizon(
        [FromBody] HorizonPatchRequest request,
        CancellationToken ct)
    {
        var saved = await _settingsService.UpdateMaterialisationHorizonAsync(request.Days, ct);
        return Ok(new { days = saved });
    }

    // ── SPM-76: Editable Email Templates ───────────────────────────────────

    /// <summary>
    /// Returns the editable transactional email templates (Admin only). Each
    /// template carries its current stored Subject/BodyHtml (blank = using the
    /// built-in default) plus its required + available variable lists for the
    /// admin editor. Missing templates are backfilled server-side.
    /// </summary>
    [HttpGet("email-templates")]
    public async Task<IActionResult> GetEmailTemplates(CancellationToken ct)
    {
        var templates = await _settingsService.GetEmailTemplatesAsync(ct);
        return Ok(templates);
    }

    /// <summary>
    /// Updates one email template's Subject + BodyHtml (Admin only). The service
    /// validates that every required variable for the template is still present;
    /// a failed validation returns 400 with the missing-variable message so the
    /// admin UI can show which token is missing. A blank field resets that field
    /// to the built-in default.
    /// </summary>
    [HttpPut("email-templates/{id}")]
    public async Task<IActionResult> UpdateEmailTemplate(
        string id,
        [FromBody] UpdateEmailTemplateRequest request,
        CancellationToken ct)
    {
        try
        {
            var saved = await _settingsService.UpdateEmailTemplateAsync(
                id, request.Subject ?? "", request.BodyHtml ?? "", ct);
            return Ok(saved);
        }
        catch (InvalidOperationException ex)
        {
            // Required-variable / unknown-id validation → 400 with the message
            // verbatim so the admin UI can render it inline.
            return BadRequest(new { message = ex.Message });
        }
    }

    [HttpPatch("email-templates/{id}/enabled")]
    public async Task<IActionResult> SetEmailTemplateEnabled(
        string id,
        [FromBody] SetEmailTemplateEnabledRequest request,
        CancellationToken ct)
    {
        try
        {
            var saved = await _settingsService.SetEmailTemplateEnabledAsync(id, request.IsEnabled, ct);
            return Ok(saved);
        }
        catch (InvalidOperationException ex)
        {
            return BadRequest(new { message = ex.Message });
        }
    }

    // ── Stripe Key Management ──────────────────────────────────────────────

    /// <summary>
    /// Returns the current Stripe configuration status with masked keys.
    /// Raw keys are NEVER returned — only first 4 + last 4 characters are visible.
    /// </summary>
    [HttpGet("stripe-keys")]
    public async Task<IActionResult> GetStripeKeys(CancellationToken ct)
    {
        var settings = await _settingsService.GetAsync(ct);
        var decrypted = await _settingsService.GetDecryptedStripeConfigAsync(ct);

        return Ok(new
        {
            enabled = settings.StripeEnabled,
            publishableKeyMasked = SettingsEncryptionHelper.Mask(decrypted.PublishableKey),
            secretKeyMasked = SettingsEncryptionHelper.Mask(decrypted.SecretKey),
            webhookSecretMasked = SettingsEncryptionHelper.Mask(decrypted.WebhookSecret),
            hasPublishableKey = !string.IsNullOrEmpty(decrypted.PublishableKey),
            hasSecretKey = !string.IsNullOrEmpty(decrypted.SecretKey),
            hasWebhookSecret = !string.IsNullOrEmpty(decrypted.WebhookSecret),
        });
    }

    /// <summary>
    /// Updates Stripe credentials. Each key field is optional — pass null to
    /// leave the existing value unchanged, or an empty string to clear it.
    /// Keys are AES-256-CBC encrypted before persisting to the database.
    /// </summary>
    [HttpPost("stripe-keys")]
    public async Task<IActionResult> UpdateStripeKeys(
        [FromBody] UpdateStripeKeysRequest request,
        CancellationToken ct)
    {
        await _settingsService.UpdateStripeKeysAsync(
            request.Enabled,
            request.PublishableKey,
            request.SecretKey,
            request.WebhookSecret,
            ct);

        // Return the masked state after update so the UI can refresh.
        return await GetStripeKeys(ct);
    }
}

