/* ── View switching ── */
function setView(v) {
  currentView = v;
  document.querySelectorAll('.cal-seg-btn').forEach(b => b.classList.toggle('active', b.dataset.view === v));
  document.getElementById('groupBySelect').style.display = v === 'day' ? '' : 'none';
  if (v === 'day') selectedDayDate = new Date(weekStart);
  ClassDetailPanel.close();
  renderCalendar();
}
document.getElementById('groupBySelect').addEventListener('change', e => {
  currentGroupBy = e.target.value;
  renderGrid();
});

/* ── Staff loading ── */
async function loadStaff() {
  try {
    staffList = await fetch(`${API}/api/staff`, { headers: { Authorization: 'Bearer ' + token } }).then(r => r.json());
    staffList.sort((a,b) => {
      if (a.id === myStaffId) return -1;
      if (b.id === myStaffId) return 1;
      return (a.name||'').localeCompare(b.name||'');
    });
    const sel = document.getElementById('filterInstructor');
    sel.innerHTML = '<option value="">All Instructors</option>' +
      staffList.filter(s => s.isActive !== false && (s.role === 'INSTRUCTOR' || s.role === 'OWNER' || s.role === 'FREELANCE'))
      .map(s => `<option value="${s.id}">${esc(s.name)}</option>`).join('');
  } catch {}
}

function filterByInstructor() {
  selectedInstructorId = document.getElementById('filterInstructor').value;
  renderGrid();
}

function filterByHasAttendees() {
  filterHasAttendees = document.getElementById('filterHasAttendees').checked;
  renderGrid();
}

/* ── Schedule config (holidays, operating hours) ── */
async function loadScheduleConfig() {
  try {
    const r = await fetch(`${API}/api/settings/schedule`, { headers: { Authorization: 'Bearer ' + token } });
    if (r.ok) {
      scheduleConfig = await r.json();
      holidayDates = new Set((scheduleConfig.holidays||[]).map(h => h.date));
    }
  } catch {}
}

