/* ═══════════════════════════════════════════════════
   RENDER CALENDAR
   ═══════════════════════════════════════════════════ */
async function renderCalendar() {
  const end = new Date(weekStart);
  end.setDate(end.getDate() + 7);

  // Update label
  if (currentView === 'week') {
    const s = weekStart.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
    const e = new Date(end.getTime()-1).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
    document.getElementById('weekLabel').textContent = `${s} – ${e}`;
  } else {
    document.getElementById('weekLabel').textContent = selectedDayDate.toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric', year: 'numeric' });
  }

  allSessions = [];
  try {
    const fStart = currentView === 'week' ? weekStart : new Date(selectedDayDate.getFullYear(), selectedDayDate.getMonth(), selectedDayDate.getDate());
    const fEnd = currentView === 'week' ? end : new Date(fStart.getTime() + 86400000);
    allSessions = await fetch(
      `${API}/api/scheduling?start=${fStart.toISOString()}&end=${fEnd.toISOString()}`,
      { headers: { Authorization: 'Bearer ' + token } }
    ).then(r => r.json());
  } catch {}

  renderGrid();
  document.getElementById('calScroll').scrollTop = 0;
  batchFetchAttendees();
}

/* ── Visible sessions after filter ── */
function getVisibleSessions() {
  return allSessions.filter(s => {
    if (s.status === 'BLOCKED') return true;
    if (selectedInstructorId && s.instructorId !== selectedInstructorId) return false;
    if (filterHasAttendees && (s.currentBookings || 0) === 0) return false;
    return true;
  });
}

