import '../styles/global.css';
import InstallPrompt from '../components/admin/InstallPrompt.astro';

export interface Props {
  title: string;
  activePage?: string;
  accessModules?: string;
}
const { title, activePage = '', accessModules = '' } = Astro.props;
const pageGroups: Record<string, string> = {
  dashboard: 'Studio overview',
  calendar: 'Scheduling',
  classes: 'Class operations',
  clients: 'Client management',
  products: 'Product catalog',
  'studio-rentals': 'Freelance rentals',
  'class-blueprints': 'Class templates',
  pos: 'Point of sale',
  invoices: 'Billing',
  bookings: 'Bookings',
  expenses: 'Finance',
  washout: 'Payroll and washout',
  analytics: 'Analytics',
  'kpi-bonus': 'Reception team',
  staff: 'Team management',
  partners: 'Referrals',
  promotions: 'Promotions',
  owners: 'Ownership',
  'audit-log': 'Audit history',
  settings: 'System settings',
};
const pageGroup = pageGroups[activePage] ?? 'Workspace';
---

<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover" />
  <title>{title} — Soul Pilates CRM</title>
  <meta name="theme-color" content="#1A1410" />

  {/* PWA — installable shell + native push notifications */}
  <link rel="manifest" href="/manifest.webmanifest" />
  <link rel="icon" type="image/png" sizes="192x192" href="/icons/icon-192.png" />
  <link rel="apple-touch-icon" href="/icons/icon-192.png" />
  <meta name="apple-mobile-web-app-capable" content="yes" />
  <meta name="apple-mobile-web-app-status-bar-style" content="black-translucent" />
  <meta name="apple-mobile-web-app-title" content="Soul Pilates" />
  <meta name="mobile-web-app-capable" content="yes" />

  {/* Pre-paint theme switch — runs before CSS evaluates to prevent flash */}
  <script is:inline>
    (function() {
      try {
        var saved = localStorage.getItem('admin-theme');
        var prefersDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
        var theme = saved || (prefersDark ? 'dark' : 'light');
        document.documentElement.dataset.theme = theme;
      } catch (e) {
        document.documentElement.dataset.theme = 'light';
      }
    })();
  </script>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap" rel="stylesheet">
  <link rel="icon" type="image/svg+xml" href="/favicon.svg" />

</head>
<body>
<div
  class="app-shell"
  data-active-page={activePage}
  data-access-modules={accessModules || activePage}
  data-api-base={import.meta.env.PUBLIC_API_URL}
>

  <!-- ── Sidebar ── -->

