import '../styles/global.css';
/*
 * P3-S09 — Instructor Portal layout.
 *
 * Sibling of AdminLayout. Same shell chrome (sidebar + topbar +
 * theme toggle + auth guard) for consistency — Q3-S09-6 default
 * (A) deliberately mirrors the admin design system so an instructor
 * doesn't experience a brand whiplash when the studio owner is
 * showing them around the platform.
 *
 * Sidebar pre-seeds disabled "Coming soon" items per Q3-S09-5 (A)
 * so P3-S10 lands by flipping the disabled flag rather than
 * inserting new nav entries.
 *
 * Auth guard: redirect to /login if no token; redirect to /admin
 * if the token is for a non-Instructor role (defence-in-depth —
 * the role-aware login redirect should prevent this case from ever
 * being hit, but a copy-pasted admin token shouldn't get an empty
 * instructor portal).
 */
export interface Props {
  title: string;
  activePage?: string;
}
const { title, activePage = '' } = Astro.props;
