function _getCreditsUsedInCart() {
  const used = { GROUP: 0, MAT: 0, PRIVATE: 0 };
  for (const item of cart) {
    // SPM-124: collect-payment items can also consume a credit, so count any
    // class-linked line (walk-in OR collect) that has _useCredit checked.
    if (item._useCredit && item._classSessionId) {
      const fmt = (item._classFormat || 'GROUP').toUpperCase();
      used[fmt] = (used[fmt] || 0) + 1;
    }
  }
  return used;
}

function _getCreditPoolForFormat(format) {
  const fmt = (format || 'GROUP').toUpperCase();
  if (fmt === 'PRIVATE') return _clientPrivateCredits;
  if (fmt === 'MAT') return _clientMatCredits;
  return _clientGroupCredits;
}

/**
 * Toggle "use credit" for a cart item. Prevents going negative.
 */
function toggleCartCredit(idx) {
  const item = cart[idx];
  if (!item) return;
  const newVal = !item._useCredit;
  if (newVal) {
    // Verify credits available
    const fmt = (item._classFormat || 'GROUP').toUpperCase();
    const pool = _getCreditPoolForFormat(fmt);
    const used = _getCreditsUsedInCart();
    if ((used[fmt] || 0) >= pool) {
      window.showToast && window.showToast(`No ${fmt.toLowerCase()} credits remaining.`, 'warning');
      return;
    }
  }
  item._useCredit = newVal;
  renderCart();
}

