async function checkout() {
  if (saleMode === "CLIENT" && !selectedClient) {
    window.showToast &&
      window.showToast("Please select a client first", "warning");
    return;
  }
  if (saleMode === "STUDIO_RENTAL" && !selectedFreelance) {
    window.showToast &&
      window.showToast("Please select a freelance instructor first", "warning");
    return;
  }
  if (saleMode === "STUDIO_RENTAL" && !selectedFreelance?.linkedClientId) {
    window.showToast &&
      window.showToast("This freelance instructor is missing a linked rental billing profile.", "error");
    return;
  }
  if (!cart.length) {
    window.showToast && window.showToast("Cart is empty", "warning");
    return;
  }

  const subtotal = cart.reduce(
    (s, c) => s + (c._useCredit ? 0 : (c.unitPrice ?? c.basePrice ?? 0) * c.qty),
    0,
  );
  const discVal =
    parseFloat(document.getElementById("discountAmt").value) || 0;
  const discType = document.getElementById("discountType").value;
  const baseDiscount =
    discType === "PCT" ? (subtotal * discVal) / 100 : discVal;

  // P1-S12: voucher contribution on top of the manual discount.
  const voucherId = document.getElementById("voucherSelect").value;
  const voucher = voucherId
    ? activeVoucherBatches.find((b) => b.id === voucherId)
    : null;
