/// <inheritdoc />
public async Task<RevenueBreakdownDto> GetRevenueBreakdownAsync(AnalyticsRangeQuery range)
{
    if (range == null) throw new ArgumentNullException(nameof(range));

    var paidInvoices = await _invoices
        .Find(Builders<Invoice>.Filter.And(
            Builders<Invoice>.Filter.Eq(i => i.Status, "PAID"),
            Builders<Invoice>.Filter.Gte(i => i.IssueDate, range.StartDate),
            Builders<Invoice>.Filter.Lt(i => i.IssueDate, range.EndDate)))
        .ToListAsync();

    var distinctProductIds = paidInvoices
        .SelectMany(i => i.Lines.Select(l => l.ProductId))
        .Where(pid => !string.IsNullOrEmpty(pid))
        .Distinct()
        .ToList();

    var productsById = distinctProductIds.Count == 0
        ? new Dictionary<string, Product>()
        : (await _products
            .Find(Builders<Product>.Filter.In(p => p.Id, distinctProductIds))
            .ToListAsync())
            .Where(p => p.Id != null)
            .ToDictionary(p => p.Id!, p => p);

