    {
        var yearStart = new DateTime(year, 1, 1, 0, 0, 0, DateTimeKind.Utc);
        var yearEnd = new DateTime(year + 1, 1, 1, 0, 0, 0, DateTimeKind.Utc);

        var invoicesTask = _payments
            .Find(Builders<Payment>.Filter.And(
                Builders<Payment>.Filter.Gte(p => p.PaymentDate, yearStart),
                Builders<Payment>.Filter.Lt(p => p.PaymentDate, yearEnd)))
            .Project(p => new { p.PaymentDate, p.AmountPaid })
            .ToListAsync();

        var expensesTask = _expenses
            .Find(Builders<Expense>.Filter.And(
                Builders<Expense>.Filter.Gte(e => e.DateIncurred, yearStart),
                Builders<Expense>.Filter.Lt(e => e.DateIncurred, yearEnd),
                Builders<Expense>.Filter.Ne(e => e.Type, "CAPEX")))
            .Project(e => new { e.DateIncurred, e.Amount })
            .ToListAsync();

        await Task.WhenAll(invoicesTask, expensesTask);

        var revenueByMonth = invoicesTask.Result
            .GroupBy(i => i.PaymentDate.Month)
            .ToDictionary(g => g.Key, g => g.Sum(i => i.AmountPaid));

        var expenseByMonth = expensesTask.Result
            .GroupBy(e => e.DateIncurred.Month)
            .ToDictionary(g => g.Key, g => g.Sum(e => e.Amount));

        var monthNames = new[] { "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec" };
        var result = new List<MonthlyRevenueExpenseDto>(12);
        for (var m = 1; m <= 12; m++)
        {
            result.Add(new MonthlyRevenueExpenseDto
            {
                Month = monthNames[m - 1],
                Year = year,
                RevenueVnd = revenueByMonth.TryGetValue(m, out var r) ? r : 0m,
                ExpensesVnd = expenseByMonth.TryGetValue(m, out var e) ? e : 0m,
            });
        }
        return result;
    }
}

