using System.ComponentModel.DataAnnotations;

namespace SoulPilates.Core.DTOs;

/// <summary>
/// Shared date-range parameter for analytics endpoints. All analytics surfaces
/// (P3-S03 Top Clients / Top Class Times, P3-S04 Recurring vs One-Time, etc.)
/// accept the same shape so the controller layer can validate ranges in one
/// place and the frontend can keep a single date-picker component.
///
/// <para>
/// <strong>Window semantics:</strong> <see cref="StartDate"/> is inclusive,
/// <see cref="EndDate"/> is exclusive. Pass <c>2026-04-01</c>/<c>2026-05-01</c>
/// to query "all of April 2026". This matches the half-open convention used by
/// every other date-window in the codebase (P2-S11 P&amp;L grid, P3-S02 KPI
/// month boundaries, P2-S03 washouts).
/// </para>
/// </summary>
public class AnalyticsRangeQuery
{
    [Required]
    public DateTime StartDate { get; set; }

    [Required]
    public DateTime EndDate { get; set; }

    /// <summary>
    /// Returns <c>(true, null)</c> when the range is well-formed,
    /// <c>(false, reason)</c> otherwise. The controller surfaces the reason as
    /// a <c>400 Bad Request</c> body so the frontend can show it inline.
    /// 366-day cap is a deliberate guard against accidental "all-time" scans
    /// on a fresh analytics page; if the operator legitimately needs a longer
    /// window, raise it in a future slice with a covering index review.
    /// </summary>
    public (bool ok, string? reason) Validate()
    {
        if (EndDate <= StartDate)
            return (false, "endDate must be strictly after startDate.");

        var span = EndDate - StartDate;
        if (span.TotalDays > 366)
            return (false, "Window cannot exceed 366 days. Narrow your range.");

        return (true, null);
    }
}

