/// Sums <c>Invoice.TotalNet</c> for paid invoices in the current month and
/// the previous month, then computes the delta-vs-previous as a percentage.
/// Returns <c>null</c> for the delta when the previous month had zero
/// revenue &mdash; an &infin;% jump is meaningless on a fresh DB and would
/// be more misleading than a dash on the dashboard.
/// </summary>
private async Task<(decimal current, decimal previous, decimal? deltaPct)> ComputeRevenueAsync(
    DateTime monthStart, DateTime nextMonthStart, DateTime prevMonthStart)
{
    var paid = "PAID";

    var currentTask = _invoices.Find(
            Builders<Invoice>.Filter.And(
                Builders<Invoice>.Filter.Eq(i => i.Status, paid),
                Builders<Invoice>.Filter.Gte(i => i.IssueDate, monthStart),
                Builders<Invoice>.Filter.Lt(i => i.IssueDate, nextMonthStart)))
        .ToListAsync();
    var prevTask = _invoices.Find(
            Builders<Invoice>.Filter.And(
                Builders<Invoice>.Filter.Eq(i => i.Status, paid),
                Builders<Invoice>.Filter.Gte(i => i.IssueDate, prevMonthStart),
                Builders<Invoice>.Filter.Lt(i => i.IssueDate, monthStart)))
        .ToListAsync();

    await Task.WhenAll(currentTask, prevTask);

    var current = currentTask.Result.Sum(i => i.TotalNet);
    var previous = prevTask.Result.Sum(i => i.TotalNet);

    // Divide-by-zero guard. Previous == 0 means the dashboard's first-ever
    // month — we can't express "infinite growth" honestly, so return null
    // and let the frontend render a muted "— vs last month" pill.
    decimal? deltaPct = previous == 0
        ? (decimal?)null
        : Math.Round((current - previous) / previous * 100m, 1, MidpointRounding.AwayFromZero);

    return (current, previous, deltaPct);
}

