// ── Add collect-payment item to cart ──────────────────────────────────
function addCollectPaymentToCart(attendanceId, sessionId, amount, className, sessionLabel, instructorName, format) {
  if ((amount ?? 0) <= 0) {
    window.showToast && window.showToast(`"${className || 'Class Session'}" does not have any payment due.`, 'warning');
    return;
  }
  const lineKey = `collect::${attendanceId}`;
  if (cart.find(c => c.lineKey === lineKey)) {
    window.showToast && window.showToast('This booking is already in the cart.', 'warning');
    return;
  }
  cart.push({
    id: attendanceId,
    lineKey,
    name: className || 'Class Session',
    type: 'CLASS',
    _isCollectPayment: true,
    _attendanceId: attendanceId,
    _classSessionId: sessionId,
    _classSessionLabel: `${sessionLabel} · ${instructorName}`,
    // SPM-124: carry the class format so the cart can offer a pay-with-credit
    // option for this collect item (mirrors walk-in items).
    _classFormat: (format || 'GROUP').toUpperCase(),
    unitPrice: amount || 0,
    qty: 1,
  });
  hidePosSessionPopup();
  renderCart();
  window.showToast && window.showToast(`Added collect-payment for ${className}`, 'success');
}

// ── Add collect-invoice item to cart (partial invoice remaining balance) ──
function addCollectInvoiceToCart(invoiceId, invoiceNumber, balanceDue, clientId, clientName) {
  const lineKey = `invoice::${invoiceId}`;
  if (cart.find(c => c.lineKey === lineKey)) {
    window.showToast && window.showToast('This invoice is already in the cart.', 'warning');
    return;
  }
  cart.push({
    id: invoiceId,
    lineKey,
    name: `Balance — ${invoiceNumber}`,
    type: 'INVOICE_BALANCE',
    _isCollectInvoice: true,
    _invoiceId: invoiceId,
    _invoiceNumber: invoiceNumber,
    unitPrice: balanceDue || 0,
    qty: 1,
  });
  renderCart();
  window.showToast && window.showToast(`Invoice balance added: ${Math.round(balanceDue).toLocaleString()} ₫`, 'success');
}

