function saveExpense() {
  const paidStatus = document.getElementById("exPaidStatus").value;
  const outstanding = parseFloat(document.getElementById("exOutstanding").value) || 0;
  const staffName = payBy === "STAFF"
    ? (document.getElementById("exStaffName").value || "").trim()
    : null;

  if (payBy === "STAFF" && !staffName) {
    window.showToast
      ? window.showToast("Please select a staff member.", "warning")
      : alert("Please select a staff member.");
    return;
  }

  fetch(`${API}/api/accounting/expense`, {
    method: "POST",
    headers: {
      Authorization: "Bearer " + token,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      category: document.getElementById("exCat").value,
      description: document.getElementById("exDesc").value,
      amount: parseFloat(document.getElementById("exAmt").value),
      expenseType,
      paidBy: payBy,
      staffName,
      enteredByUserId: "admin",
      fundSource,
      frequency: document.getElementById("exFreq").value,
      paymentMethod: document.getElementById("exMethod").value,
      paidStatus,
      outstandingAmount: paidStatus === "PAID" ? 0 : outstanding,
      vendorName: document.getElementById("exVendor").value || null,
    }),
  }).then(() => {
    closeModal();
    resetModal();
    loadExpenses();
    loadPoolBalances();
  });
}

async function markExpensePaid(id) {
  if (!id) return;
  const res = await fetch(`${API}/api/accounting/expense/${id}/mark-paid`, {
    method: "POST",
    headers: { Authorization: "Bearer " + token },
  });
  if (!res.ok) {
    const body = await res.json().catch(() => ({ message: "Could not mark paid" }));
    window.showToast
      ? window.showToast(body.message || "Could not mark paid", "error")
      : alert(body.message || "Could not mark paid");
    return;
  }
  window.showToast && window.showToast("Marked as paid.", "success");
  loadExpenses();
}

