public async Task<Expense> LogExpenseAsync(Expense expense)
{
    // Refuse to attach an expense to a closed month — the washout numbers
    // have already been signed off.
    await AssertMonthNotLockedAsync(expense.DateIncurred.Year, expense.DateIncurred.Month);

    await _expenses.InsertOneAsync(expense);
    await _audit.LogAsync(
        action: "CREATE",
        entityType: "Expense",
        entityId: expense.Id!,
        entityLabel: expense.Category,
        after: new
        {
            expense.Category,
            expense.Amount,
            expense.PaidBy,
            expense.StaffName,
            expense.DateIncurred,
            expense.Description,
            expense.FundSource,
        });
    return expense;
}

public async Task<IEnumerable<Expense>> GetExpensesAsync(int month, int year)
{
    var start = new DateTime(year, month, 1, 0, 0, 0, DateTimeKind.Utc);
    var end = start.AddMonths(1).AddTicks(-1);
    return await _expenses.Find(e => e.DateIncurred >= start && e.DateIncurred <= end).ToListAsync();
}

public async Task<Expense> MarkExpensePaidAsync(string expenseId)
{
    // Look up the existing row up-front so we can: (a) 404 properly when
    // the id is bogus, (b) emit a before/after audit pair, and (c) keep
    // the operation idempotent — if it's already paid we skip the write
    // entirely (no audit churn, no jittery UpdatedAt bumps).
    var existing = await _expenses.Find(e => e.Id == expenseId).FirstOrDefaultAsync()
        ?? throw new InvalidOperationException($"Expense {expenseId} not found.");

    // Flipping an expense to PAID changes downstream cash-flow analytics for
    // the month the expense lives in — reject if that month is locked.
    await AssertMonthNotLockedAsync(existing.DateIncurred.Year, existing.DateIncurred.Month);

    if (existing.PaidStatus == "PAID" && existing.OutstandingAmount == 0m)
        return existing;

