function renderDashboard(data) {
  const { year, month } = selectedYearMonth();
  const totalPercent = Math.round(Number(data.totalUnlockedPercent || 0));
  const projection = buildProjection(totalPercent);
  const totalBonusPool = Number(data.bonusPoolAmount || 0);
  const projectedBonusAmount = Math.round(totalBonusPool * (projection.forecast / 100));
  const completedTasks = (data.dailyTasks || []).filter((task) => task.isCompleted).length;
  const allTasksCount = (data.dailyTasks || []).length;
  const taskCategory = (data.categories || []).find((category) => String(category.label).toLowerCase() === "daily tasks");
  const goalTabs = deriveGoalTabs(data.categories || []);

  document.getElementById("monthLabel").textContent = data.monthLabel || "Month";
  document.getElementById("monthRangeText").textContent = formatMonthRange(year, month);
  document.getElementById("progressPercent").textContent = `${totalPercent}%`;
  const ringMoney = moneyParts(data.totalUnlockedAmount);
  document.getElementById("progressMoney").innerHTML = `
    <span class="kpi-ring-amount-value">${ringMoney.amount}</span>
    <span class="kpi-ring-amount-currency">${ringMoney.currency}</span>
  `;
  document.getElementById("progressPoolHint").textContent = `of ${money(totalBonusPool)}`;
  document.getElementById("baseSalaryValue").textContent = money(data.baseSalaryAmount);
  document.getElementById("bonusPoolValue").textContent = money(totalBonusPool);
  document.getElementById("bonusUnlockedValue").textContent = money(data.totalUnlockedAmount);
  document.getElementById("attendanceCommissionValue").textContent = money(data.attendanceCommissionAmount);
  document.getElementById("projectedTotalValue").textContent = money(data.totalProjectedPay);
  document.getElementById("attendanceCountValue").textContent = Number(data.teamAttendanceCount || 0).toLocaleString();
  document.getElementById("attendancePoolValue").textContent = money(data.teamAttendanceCommissionPool);
  document.getElementById("monthStatusValue").textContent = data.kpiEnabled ? "Active" : "Disabled";
  document.getElementById("taskMeta").textContent = formatSelectedDate(data.selectedDateKey);
  document.getElementById("taskCompletionPill").textContent = `${completedTasks} / ${allTasksCount} completed`;
  document.getElementById("dailyTaskBonusValue").textContent = `+${Math.round(Number(taskCategory?.unlockedPercent || 0))}%`;
  document.getElementById("taskRewardHint").textContent = taskCategory
    ? `${money(taskCategory.unlockedAmount)} unlocked from daily tasks`
    : "Daily task reward pending";
  document.getElementById("progressUpdatedAt").textContent = formatSelectedDate(data.selectedDateKey);
  document.getElementById("progressEncouragement").textContent = rewardColorClass(totalPercent);

  document.getElementById("breakdownTotalPercent").textContent = `${totalPercent}%`;
  document.getElementById("breakdownTotalAmount").textContent = money(data.totalUnlockedAmount);

  document.getElementById("projectionCurrentPercent").textContent = `${projection.current}%`;
  document.getElementById("projectionCurrentAmount").textContent = money(data.totalUnlockedAmount);
  document.getElementById("projectionForecastPercent").textContent = `${projection.forecast}%`;
  document.getElementById("projectionForecastAmount").textContent = money(projectedBonusAmount);
  document.getElementById("projectionMaxPercent").textContent = "100%";
  document.getElementById("projectionMaxAmount").textContent = money(totalBonusPool);
  document.getElementById("projectionAxisStart").textContent = `${new Date(year, month - 1, 1).toLocaleDateString(undefined, { month: "short", day: "numeric" })}`;
  document.getElementById("projectionAxisMid").textContent = `${new Date(year, month - 1, Math.ceil(getDaysInSelectedMonth() / 2)).toLocaleDateString(undefined, { month: "short", day: "numeric" })}`;
  document.getElementById("projectionAxisEnd").textContent = `${new Date(year, month - 1, getDaysInSelectedMonth()).toLocaleDateString(undefined, { month: "short", day: "numeric" })}`;

  renderRing(totalPercent);
  renderProjectionChart(projection.current, projection.forecast);
  renderStaffCard(data.staff);
  renderCategories(data.categories || []);
  renderTasks(data.dailyTasks || []);
  renderGoalTabsAndRows(goalTabs);
  renderAchievements(data.categories || []);
  renderBadges(data.categories || []);
  renderAdminFields(data);
  renderBanner(data);

  if (isAdmin) {
    renderStaffOptions(data.receptionists || [], data.staff?.id || "");
  }
}

