}

async function saveTasks() {
  if (!currentDashboard) return;
  const button = document.getElementById("saveTasksBtn");
  const ok = document.getElementById("saveTasksMsg");
  const err = document.getElementById("saveTasksErr");
  button.disabled = true;
  ok.style.display = "none";
  err.style.display = "none";

  try {
    const completedTaskIds = Array.from(document.querySelectorAll("[data-task-id]:checked")).map((checkbox) => checkbox.dataset.taskId);
    const payload = {
      dateKey: dayPicker.value,
      completedTaskIds,
    };
    if (isAdmin) payload.staffId = staffPicker.value || currentDashboard.staff.id;

    const res = await fetch(`${API}/api/receptionist-kpi/daily-tasks`, {
      method: "PUT",
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify(payload),
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(data.message || "Failed to save tasks.");
    ok.style.display = "";
    setTimeout(() => { ok.style.display = "none"; }, 2000);
    await loadDashboard();
  } catch (error) {
    err.textContent = error.message || "Failed to save tasks.";
    err.style.display = "";
  } finally {
    button.disabled = false;
  }
}

