function renderCategories(categories) {
  document.getElementById("categoryList").innerHTML = categories.map((category) => {
    const meta = getCategoryMeta(category);
    const width = Math.max(0, Math.min(100, Math.round(Number(category.unlockedPercent || 0))));
    const adminDetail = isAdmin ? category.adminDetail : "";
    return `
      <div class="kpi-breakdown-item">
        <div class="kpi-breakdown-item-main">
          <div class="kpi-breakdown-icon" style="background:${meta.tint};color:${meta.color};">
            ${iconSvg(meta.icon)}
          </div>
          <div class="kpi-breakdown-copy">
            <div class="kpi-breakdown-title">${escapeHtml(category.label)}</div>
            <div class="kpi-breakdown-desc">${escapeHtml(category.description || "")}</div>
            <div class="kpi-breakdown-progress">
              <div class="kpi-progress-bar" style="--bar-width:${width}%;--bar-color:${meta.color};">
                <span></span>
              </div>
              <div class="kpi-breakdown-progress-text" style="margin-top:8px;">${escapeHtml(category.progressLabel || "")}</div>
              ${adminDetail ? `<div class="kpi-breakdown-progress-text">${escapeHtml(adminDetail)}</div>` : ""}
            </div>
          </div>
        </div>
        <div class="kpi-breakdown-side" style="--side-color:${meta.color};">
          <strong>${Math.round(Number(category.unlockedPercent || 0))}%</strong>
          <span>${money(category.unlockedAmount)}</span>
        </div>
      </div>
    `;
  }).join("");

