    const pkgs = await fetch(`${API}/api/wallet/client/${clientId}`, {
      headers: { Authorization: 'Bearer ' + token },
    }).then(r => r.ok ? r.json() : []);
    // SPM-123: LOW_BALANCE wallets (last 1-2 credits) are still usable — include
    // them alongside ACTIVE so the client's remaining credit shows up in POS.
    _clientPackages = (pkgs || []).filter(p =>
      (p.status === 'ACTIVE' || p.status === 'LOW_BALANCE') && (p.creditsRemaining ?? 0) > 0
    );
    _clientGroupCredits = _clientPackages.filter(p => (p.format||'').toUpperCase() === 'GROUP')
      .reduce((s, p) => s + (p.creditsRemaining ?? 0), 0);
    _clientMatCredits = _clientPackages.filter(p => (p.format||'').toUpperCase() === 'MAT')
      .reduce((s, p) => s + (p.creditsRemaining ?? 0), 0);
    _clientPrivateCredits = _clientPackages.filter(p => (p.format||'').toUpperCase() === 'PRIVATE')
      .reduce((s, p) => s + (p.creditsRemaining ?? 0), 0);
  } catch { /* swallow */ }

  const bar = document.getElementById('clientCreditBar');
  const total = _clientGroupCredits + _clientMatCredits + _clientPrivateCredits;
  if (total > 0) {
    document.getElementById('creditGroupCount').textContent =
      _clientGroupCredits > 0 ? `Group: ${_clientGroupCredits}` : '';
    document.getElementById('creditMatCount').textContent =
      _clientMatCredits > 0 ? `Mat: ${_clientMatCredits}` : '';
    document.getElementById('creditPrivateCount').textContent =
      _clientPrivateCredits > 0 ? `Private: ${_clientPrivateCredits}` : '';
    bar.style.display = 'flex';
  } else {
    bar.style.display = 'none';
  }
  // Re-render cart to show/hide credit checkboxes
  renderCart();
}

