namespace SoulPilates.API.Controllers;

/// <summary>
/// Admin-facing wallet surface. Powers the client-profile page's
/// &quot;Active Packages &amp; Wallet&quot; card, the freeze modal, and
/// the manual credit-adjustment modal.
///
/// <para>
/// Note: <see cref="IWalletService"/> has existed since P1 but was never
/// HTTP-exposed; the admin SPA wired calls against
/// <c>/api/wallet/client/{id}</c> assuming this controller existed. This is
/// the missing surface.
/// </para>
/// </summary>
[ApiController]
[Route("api/wallet")]
[Authorize(Roles = "Admin,Receptionist")]
public class WalletController : ControllerBase
{
    private readonly IWalletService _walletService;
    private readonly IClientService _clientService;
    private readonly IEmailService _emailService;

    public WalletController(
        IWalletService walletService,
        IClientService clientService,
        IEmailService emailService)
    {
        _walletService = walletService;
        _clientService = clientService;
        _emailService = emailService;
    }

    /// <summary>
    /// All packages for a single client (active + historical), newest first.
    /// Returns a flat camelCase projection consumed by the admin
    /// client-profile wallet card.
    /// </summary>
    [HttpGet("client/{clientId}")]
    public async Task<IActionResult> GetForClient(string clientId)
    {
        if (string.IsNullOrWhiteSpace(clientId))
            return BadRequest(new { message = "clientId is required." });

        var packages = await _walletService.GetAllPackagesForClientAsync(clientId);

        // Derive frozen state from the entity status + expiry; the legacy
        // wallet card UI consumes `isFrozen` + `frozenUntil` as scalar fields.
        // We treat status == "FROZEN" as authoritative and surface the
        // current ExpiryDate as `frozenUntil` (since FreezePackageAsync
        // extends the expiry by the freeze duration when a freeze is applied).
        return Ok(packages.Select(p => new
