    {
        id = p.Id,
        clientId = p.ClientId,
        format = p.Format,
        totalCredits = p.TotalCredits,
        creditsUsed = p.CreditsUsed,
        creditsRemaining = p.CreditsRemaining,
        activationDate = p.ActivationDate,
        expiryDate = p.ExpiryDate,
        status = p.Status,
        isFrozen = string.Equals(p.Status, "FROZEN", StringComparison.OrdinalIgnoreCase),
        frozenUntil = string.Equals(p.Status, "FROZEN", StringComparison.OrdinalIgnoreCase)
            ? (DateTime?)p.ExpiryDate
