346	            : c.billingMode === "FIXED_FEE" && c.invoiceId && c.linkedClientId && Number(c.balanceDue || 0) > 0
347	              ? `<a class="btn btn-primary btn-sm" href="${collectInvoiceUrl(c)}" style="text-decoration:none;">Collect ${money(c.balanceDue)} →</a>`
348	              : `<span class="text-sm text-muted">${c.billingMode === "FIXED_FEE" ? "Paid" : "Done"}</span>`}</td>
