.sr-how-title { font-size: 13px; font-weight: 700; margin-bottom: 4px; }
.sr-how-desc { font-size: 11px; color: var(--color-text-muted); line-height: 1.5; }
.sr-how-arrow {
  font-size: 20px;
  color: var(--color-border-subtle);
  flex-shrink: 0;
  padding: 0 4px;
  padding-bottom: 36px;
}

/* ── Overview mini-list items ── */
.sr-mini-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 16px;
  border-bottom: 1px solid var(--color-border-subtle);
  transition: background .12s;
}
.sr-mini-row:last-child { border-bottom: none; }
.sr-mini-row:hover { background: var(--color-surface-raised); }

/* ── Modals ── */
.rental-modal {
  position: fixed;
  inset: 0;
  display: none;
  align-items: center;
  justify-content: center;
  background: rgba(0,0,0,.5);
  z-index: 1200;
  padding: 20px;
  backdrop-filter: blur(2px);
}
.rental-modal.open { display: flex; }
.rental-modal-card {
  width: min(680px, 100%);
  background: var(--color-surface);
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-md);
  padding: 24px;
  box-shadow: 0 32px 80px rgba(0,0,0,.4);
}
.rental-instructor-row { cursor: pointer; transition: background .1s; }
.rental-instructor-row.active { background: var(--color-brand-accent-soft) !important; }

@media (max-width: 1100px) {
  .sr-overview-grid { grid-template-columns: 1fr 1fr; }
  .sr-overview-grid > div:last-child { grid-column: 1 / -1; flex-direction: row; }
  .sr-instructor-layout { grid-template-columns: 1fr; }
  .sr-detail-panel { min-height: auto; }
}
@media (max-width: 800px) {
  .sr-stats-grid { grid-template-columns: repeat(2, 1fr); }
  .sr-overview-grid { grid-template-columns: 1fr; }
  .sr-how-grid { flex-direction: column; }
  .sr-how-arrow { transform: rotate(90deg); padding: 0; }
}

