// ── Load ──
async function loadStudioRentals(search = "") {
  const [dashRes, bpRes, cfgRes] = await Promise.all([
    fetch(`${API}/api/studio-rentals/dashboard?classLimit=100&search=${encodeURIComponent(search)}`, { headers: { Authorization: "Bearer " + token } }),
    fetch(`${API}/api/studio-rentals/blueprints`, { headers: { Authorization: "Bearer " + token } }),
    fetch(`${API}/api/studio-rentals/config`, { headers: { Authorization: "Bearer " + token } }),
  ]);
  state.dashboard = dashRes.ok ? await dashRes.json() : { instructors: [], classes: [], totalCreditsRemaining: 0 };
  state.blueprints = bpRes.ok ? (await bpRes.json()).filter(b => !!b.isFreelance) : [];
  state.settings = cfgRes.ok ? await cfgRes.json() : {};

  if (!state.selectedStaffId && state.dashboard.instructors.length) state.selectedStaffId = state.dashboard.instructors[0].staffId;
  if (state.selectedStaffId && !state.dashboard.instructors.find(i => i.staffId === state.selectedStaffId))
    state.selectedStaffId = state.dashboard.instructors[0]?.staffId || null;

  renderAll();
}

function renderAll() {
  renderStats();
  renderOverview();
  renderInstructorTable();
  renderInstructorDetail();
  renderClassesTable();
  syncRentalBlueprintMeta();
  syncRentalPackageOptions();
}

// ── Stats ──
function renderStats() {
  const { dashboard } = state;
  document.getElementById("ovInstructors").textContent = dashboard.totalInstructors ?? dashboard.instructors.length;
  document.getElementById("ovClasses").textContent = dashboard.totalClasses ?? dashboard.classes.length;
  document.getElementById("ovCredits").textContent = (dashboard.totalCreditsRemaining ?? 0).toLocaleString();

  const revenue = dashboard.classes
    .filter(c => c.status === 'COMPLETED' && c.billingMode === 'FIXED_FEE' && c.chargeAmount)
    .reduce((s, c) => s + Number(c.chargeAmount || 0), 0);
  document.getElementById("ovRevenue").textContent = revenue > 0 ? money(revenue) : '₫ 0';

  const feeBits = [];
  if ((state.settings.studioRentalGroupPerHeadFee ?? 0) > 0) feeBits.push(`Group: ${money(state.settings.studioRentalGroupPerHeadFee)}/head`);
  if ((state.settings.studioRentalPrivatePerHeadFee ?? 0) > 0) feeBits.push(`Private: ${money(state.settings.studioRentalPrivatePerHeadFee)}/head`);
  document.getElementById("studioRentalSubtitle").textContent = feeBits.length
    ? `Manage freelance instructors, their classes and rental credits. ${feeBits.join(' | ')}.`
    : "Manage freelance instructors, their classes and rental credits.";
}

