        <div style="font-size:11px;color:var(--color-text-muted);">${esc(c.instructorName)}</div>
      </div>
      <div style="text-align:right;flex-shrink:0;display:flex;flex-direction:column;align-items:flex-end;gap:3px;">
        <div style="font-size:11px;color:var(--color-text-muted);">${fmtDate(c.startTime)} · ${fmtTime(c.startTime)}</div>
        <div style="display:flex;align-items:center;gap:4px;">
          <span style="font-size:11px;color:var(--color-text-muted);">${c.headcount??c.currentBookings??0} attendees</span>
          ${formatBadge(c.format)}
        </div>
      </div>
    </div>`;
