using MongoDB.Driver;
using SoulPilates.Infrastructure.Data;
using SoulPilates.Migration.Abstractions;
using SoulPilates.Migration.Reporting;

namespace SoulPilates.Migration.Commands;

/// <summary>
/// Drops ALL user-created collections from the configured database.
/// Used before a full re-import to guarantee a clean-slate state.
/// Safety: requires <c>--commit</c>; dry-run prints what WOULD be dropped.
/// </summary>
internal sealed class WipeCommand : IMigrationCommand
{
    private readonly MongoDbContext _db;

    public WipeCommand(MongoDbContext db) => _db = db;

    public string Name => "wipe";

    public string Description => "Drop all collections for a full re-import (requires --commit).";

    public async Task<MigrationReport> RunAsync(string? csvPath, bool commit, CancellationToken ct)
    {
        var report = new MigrationReport { CommandName = Name, Committed = commit };

        var database = _db.Database;
        var collectionNames = new List<string>();

        using var cursor = await database.ListCollectionNamesAsync(new MongoDB.Driver.ListCollectionNamesOptions(), ct);
        await cursor.ForEachAsync(name => collectionNames.Add(name), ct);

        // Sort for deterministic output.
        collectionNames.Sort(StringComparer.OrdinalIgnoreCase);

        Console.WriteLine();
        Console.WriteLine($"  Found {collectionNames.Count} collections to drop:");
        foreach (var name in collectionNames)
        {
            Console.WriteLine($"    - {name}");
        }
        Console.WriteLine();

        if (!commit)
        {
            Console.WriteLine("  DRY-RUN: No collections were dropped. Pass --commit to execute.");
            report.Skipped = collectionNames.Count;
            report.FinishedAt = DateTime.UtcNow;
            return report;
        }

        foreach (var name in collectionNames)
        {
            ct.ThrowIfCancellationRequested();
            await database.DropCollectionAsync(name, ct);
            Console.WriteLine($"  ✓ Dropped: {name}");
            report.Created++; // repurpose Created as "dropped" counter for reporting
        }

        Console.WriteLine();
        Console.WriteLine($"  Wiped {collectionNames.Count} collections. Database is now empty.");
        report.FinishedAt = DateTime.UtcNow;
        return report;
    }
}

