using MongoDB.Driver;
using SoulPilates.Core.Entities;
using SoulPilates.Infrastructure.Data;
using SoulPilates.Migration.Abstractions;
using SoulPilates.Migration.Reporting;

namespace SoulPilates.Migration.Commands;

/// <summary>
/// Phase 5 step 2: Computes simplified payroll records and monthly washouts
/// for the entire Nov 2025–May 2026 cutover window, then locks each month.
///
/// NOTE: This is a simplified payroll computation that works directly against
/// the synthesized CalendarSessions (from session-synth), rather than going
/// through the full PayrollService → AccountingService pipeline, because the
/// migration harness doesn't have the full DI graph available.
///
/// The washout numbers can be reviewed and adjusted in the dashboard before
/// the user signs off on them.
/// </summary>
internal sealed class WashoutAllCommand : IMigrationCommand
{
    private readonly IMongoCollection<CalendarSession> _sessions;
    private readonly IMongoCollection<Attendance> _attendances;
    private readonly IMongoCollection<Staff> _staff;
    private readonly IMongoCollection<ClientPackage> _packages;
    private readonly IMongoCollection<Invoice> _invoices;
    private readonly IMongoCollection<Payment> _payments;
    private readonly IMongoCollection<Expense> _expenses;
    private readonly IMongoCollection<PayrollRun> _payrolls;
    private readonly IMongoCollection<MonthlyWashout> _washouts;
    private readonly IMongoCollection<OwnerProfile> _ownerProfiles;
    private readonly IMongoCollection<OwnerDistribution> _ownerDists;
    private readonly IMongoCollection<GlobalSettings> _settings;
    private readonly IMongoCollection<MonthlyAllocationOverride> _overrides;

    public WashoutAllCommand(MongoDbContext db)
    {
        _sessions = db.GetCollection<CalendarSession>("CalendarSessions");
        _attendances = db.GetCollection<Attendance>("Attendances");
        _staff = db.GetCollection<Staff>("Staff");
        _packages = db.GetCollection<ClientPackage>("ClientPackages");
        _invoices = db.GetCollection<Invoice>("Invoices");
        _payments = db.GetCollection<Payment>("Payments");
        _expenses = db.GetCollection<Expense>("Expenses");
        _payrolls = db.GetCollection<PayrollRun>("PayrollRuns");
        _washouts = db.GetCollection<MonthlyWashout>("MonthlyWashouts");
        _ownerProfiles = db.GetCollection<OwnerProfile>("OwnerProfiles");
        _ownerDists = db.GetCollection<OwnerDistribution>("OwnerDistributions");
        _settings = db.GetCollection<GlobalSettings>("Settings");
        _overrides = db.GetCollection<MonthlyAllocationOverride>("MonthlyAllocationOverrides");
    }

    public string Name => "washout-all";

    public string Description =>
        "Phase 5: Compute payroll + washouts for Nov 2025–May 2026, then lock each month.";

    public async Task<MigrationReport> RunAsync(string? csvPath, bool commit, CancellationToken ct)
    {
        var report = new MigrationReport { CommandName = Name, Committed = commit };

        // Month range: Nov 2025 through May 2026
        var months = new (int Year, int Month)[]
        {
            (2025, 11), (2025, 12),
            (2026, 1), (2026, 2), (2026, 3), (2026, 4), (2026, 5),
        };

        // Pre-load owner profiles for distribution splits
        var owners = await _ownerProfiles.Find(o => o.IsActiveOwner).ToListAsync(ct);
        var allStaff = await _staff.Find(_ => true).ToListAsync(ct);
        var staffById = allStaff.ToDictionary(s => s.Id!, s => s);

        // Load global settings for allocation defaults
        var globalSettings = await _settings.Find(_ => true).FirstOrDefaultAsync(ct);

        foreach (var (year, month) in months)
        {
            ct.ThrowIfCancellationRequested();

            var start = new DateTime(year, month, 1, 0, 0, 0, DateTimeKind.Utc);
            var end = start.AddMonths(1).AddTicks(-1);

            Console.WriteLine($"\n  ── Processing {year}-{month:D2} ──");

            // ── 1) Payroll Computation ─────────────────────────────────
            var completedSessions = await _sessions
                .Find(s => s.StartTime >= start && s.StartTime <= end && s.Status == "COMPLETED")
                .ToListAsync(ct);

            Console.WriteLine($"    Sessions: {completedSessions.Count}");

            var payrollResults = new List<InstructorPayrollResult>();
            decimal totalPayroll = 0m;

            foreach (var instrGroup in completedSessions.GroupBy(s => s.InstructorId))
            {
                var instrId = instrGroup.Key;
                if (string.IsNullOrEmpty(instrId) || !staffById.TryGetValue(instrId, out var staffRow))
                    continue;

                // Only compute payroll for instructors (not owners/receptionists acting as pseudo-staff)
                if (staffRow.Role != "INSTRUCTOR") continue;

                var groupSessions = instrGroup.Where(s => s.Format == "GROUP" || s.Capacity > 1).ToList();
                var privateSessions = instrGroup.Where(s => s.Format == "PRIVATE" || s.Capacity == 1).ToList();

                decimal groupEarnings = 0m;
                decimal privateEarnings = 0m;

                // Group session earnings
                foreach (var gs in groupSessions)
                {
                    if (staffRow.CommissionModel == "FIXED_HEADCOUNT" && staffRow.HeadcountTiers.Count > 0)
                    {
                        var students = gs.CurrentBookings;
                        var rung = staffRow.HeadcountTiers
                            .OrderBy(t => t.MinStudents)
                            .FirstOrDefault(t =>
                                students >= t.MinStudents &&
                                (!t.MaxStudents.HasValue || students <= t.MaxStudents.Value))
                            ?? staffRow.HeadcountTiers.Last();
                        groupEarnings += rung.RatePerStudent * students;
                    }
                    else
                    {
                        groupEarnings += staffRow.GroupFlatRatePerClass;
                        groupEarnings += staffRow.GroupRatePerHead * gs.CurrentBookings;
                    }
                }

                // Private session earnings (fraction of package value × commission %)
                decimal privateRevenue = 0m;
                foreach (var ps in privateSessions)
                {
                    var atts = await _attendances
                        .Find(a => a.CalendarSessionId == ps.Id && a.Status == "CHECKED_IN")
                        .ToListAsync(ct);
                    foreach (var att in atts)
                    {
                        if (!string.IsNullOrEmpty(att.PackageInstanceId))
                        {
                            var pkg = await _packages
                                .Find(p => p.Id == att.PackageInstanceId)
                                .FirstOrDefaultAsync(ct);
                            if (pkg != null) privateRevenue += pkg.FractionalValuePerClass;
                        }
                    }
                }
                var commRate = staffRow.HasTieredPrivateCommission && staffRow.Tiers.Count > 0
                    ? (staffRow.Tiers
                        .Where(t => privateSessions.Count >= t.MinClasses &&
                                   (!t.MaxClasses.HasValue || privateSessions.Count <= t.MaxClasses.Value))
                        .OrderByDescending(t => t.CommissionPercentage)
                        .FirstOrDefault()?.CommissionPercentage ?? staffRow.FlatPrivateCommissionPct)
                    : staffRow.FlatPrivateCommissionPct;
                privateEarnings = privateRevenue * commRate;

                var total = staffRow.BaseSalary + groupEarnings + privateEarnings;

                payrollResults.Add(new InstructorPayrollResult
                {
                    InstructorId = instrId,
                    InstructorNameSnapshot = staffRow.Name,
                    CommissionModelSnapshot = staffRow.CommissionModel,
                    BaseSalarySnapshot = staffRow.BaseSalary,
                    BaseSalaryAmount = staffRow.BaseSalary,
                    GroupClassEarnings = groupEarnings,
                    PrivateClassEarnings = privateEarnings,
                    TotalGroupClasses = groupSessions.Count,
                    TotalPrivateClasses = privateSessions.Count,
                    TotalPay = total,
                });

                totalPayroll += total;
                Console.WriteLine($"    Payroll {staffRow.Name}: {total:N0} VND " +
                                  $"(base:{staffRow.BaseSalary:N0} grp:{groupEarnings:N0} pvt:{privateEarnings:N0})");
            }

            // Add Santino's salary + gross commission
            if (santinoPaysThisMonth(year, month) && staffById.ContainsKey(allStaff.FirstOrDefault(s => s.Name == "Santino")?.Id ?? ""))
            {
                var sant = allStaff.First(s => s.Name == "Santino");
                totalPayroll += sant.BaseSalary;

                payrollResults.Add(new InstructorPayrollResult
                {
                    InstructorId = sant.Id!,
                    InstructorNameSnapshot = sant.Name,
                    CommissionModelSnapshot = "FIXED_SALARY",
                    BaseSalarySnapshot = sant.BaseSalary,
                    BaseSalaryAmount = sant.BaseSalary,
                    TotalPay = sant.BaseSalary,
                });
                Console.WriteLine($"    Payroll Santino (salary): {sant.BaseSalary:N0} VND");
            }

            // Add Phong's salary for Dec 2025 & Jan 2026
            if ((year == 2025 && month == 12) || (year == 2026 && month == 1))
            {
                var phong = allStaff.FirstOrDefault(s => s.Name == "Phong");
                if (phong != null)
                {
                    totalPayroll += phong.BaseSalary;
                    payrollResults.Add(new InstructorPayrollResult
                    {
                        InstructorId = phong.Id!,
                        InstructorNameSnapshot = phong.Name,
                        CommissionModelSnapshot = "FIXED_SALARY",
                        BaseSalarySnapshot = phong.BaseSalary,
                        BaseSalaryAmount = phong.BaseSalary,
                        TotalPay = phong.BaseSalary,
                    });
                    Console.WriteLine($"    Payroll Phong (salary): {phong.BaseSalary:N0} VND");
                }
            }

            if (!commit) { report.Created++; continue; }

            // Upsert PayrollRun
            var existingPayroll = await _payrolls
                .Find(p => p.PeriodStart == start && p.PeriodEnd <= end)
                .FirstOrDefaultAsync(ct);

            var payrollRun = new PayrollRun
            {
                Id = existingPayroll?.Id,
                PeriodStart = start,
                PeriodEnd = end,
                RunDate = DateTime.UtcNow,
                Results = payrollResults,
                TotalPayroll = totalPayroll,
                CreatedAt = existingPayroll?.CreatedAt ?? DateTime.UtcNow,
                UpdatedAt = DateTime.UtcNow,
            };

            if (existingPayroll is null)
                await _payrolls.InsertOneAsync(payrollRun, cancellationToken: ct);
            else
                await _payrolls.ReplaceOneAsync(p => p.Id == existingPayroll.Id, payrollRun, cancellationToken: ct);

            Console.WriteLine($"    ✓ PayrollRun: {totalPayroll:N0} VND total");

            // ── 2) Washout Computation ─────────────────────────────────
            var monthInvoices = await _invoices
                .Find(i => i.IssueDate >= start && i.IssueDate <= end)
                .ToListAsync(ct);
            var totalSales = monthInvoices.Sum(i => i.TotalNet);

            var monthExpenses = await _expenses
                .Find(e => e.DateIncurred >= start && e.DateIncurred <= end)
                .ToListAsync(ct);
            var totalFixed = monthExpenses
                .Where(e => string.IsNullOrEmpty(e.FundSource) || e.FundSource == "OPERATIONS")
                .Sum(e => e.Amount);

            // Santino's gross revenue commission (on top of salary)
            decimal santinoCommission = 0m;
            if (santinoPaysThisMonth(year, month))
            {
                var commPct = totalSales >= 100_000_000m ? 0.05m : 0.04m;
                santinoCommission = totalSales * commPct;
                totalPayroll += santinoCommission; // Add to total payroll for washout math
                Console.WriteLine($"    Santino gross commission ({commPct * 100}%): {santinoCommission:N0} VND");
            }

            var totalNetBefore = totalSales - totalPayroll - totalFixed;

            // Resolve allocation percentages (override → global)
            var monthOverride = await _overrides
                .Find(o => o.Year == year && o.Month == month)
                .FirstOrDefaultAsync(ct);
            decimal mktPct, savPct, ownPct;
            if (monthOverride != null)
            {
                mktPct = monthOverride.MarketingPercentage;
                savPct = monthOverride.SavingsPercentage;
                ownPct = monthOverride.OwnersPercentage;
            }
            else
            {
                mktPct = globalSettings?.MarketingSplitPercentage ?? 5m;
                savPct = globalSettings?.SavingsSplitPercentage ?? 10m;
                ownPct = globalSettings?.OwnersSplitPercentage ?? 85m;
            }

            var mktAlloc = totalNetBefore * mktPct / 100m;
            var savAlloc = totalNetBefore * savPct / 100m;
            var ownAlloc = totalNetBefore * ownPct / 100m;

            // Upsert washout
            var existingWashout = await _washouts
                .Find(w => w.Year == year && w.Month == month)
                .FirstOrDefaultAsync(ct);

            var washout = new MonthlyWashout
            {
                Id = existingWashout?.Id,
                Month = month,
                Year = year,
                TotalSalesRevenue = totalSales,
                TotalEarnedRevenue = totalSales,
                TotalPayroll = totalPayroll,
                TotalFixedExpenses = totalFixed,
                TotalCapitalDepreciation = 0m,
                TotalNetBeforeAllocations = totalNetBefore,
                MarketingAllocation = mktAlloc,
                SavingsAllocation = savAlloc,
                OwnersPool = ownAlloc,
                MarketingPercentageApplied = mktPct,
                SavingsPercentageApplied = savPct,
                OwnersPercentageApplied = ownPct,
                NetIncome = totalNetBefore,
                Locked = true, // Lock historical months immediately
                CalculatedAt = DateTime.UtcNow,
                CreatedAt = existingWashout?.CreatedAt ?? DateTime.UtcNow,
                UpdatedAt = DateTime.UtcNow,
            };

            if (existingWashout is null)
                await _washouts.InsertOneAsync(washout, cancellationToken: ct);
            else
                await _washouts.ReplaceOneAsync(w => w.Id == existingWashout.Id, washout, cancellationToken: ct);

            Console.WriteLine($"    ✓ Washout: revenue={totalSales:N0} expenses={totalFixed:N0} " +
                              $"payroll={totalPayroll:N0} net={totalNetBefore:N0}");
            Console.WriteLine($"      Allocation ({mktPct}/{savPct}/{ownPct}): " +
                              $"mkt={mktAlloc:N0} sav={savAlloc:N0} own={ownAlloc:N0}");

            // ── 3) Owner Distributions ─────────────────────────────────
            foreach (var owner in owners)
            {
                if (!staffById.TryGetValue(owner.StaffId, out var ownerStaff)) continue;

                var equityShare = ownAlloc * owner.EquitySharePercentage / 100m;

                var existingDist = await _ownerDists
                    .Find(d => d.OwnerStaffId == owner.StaffId && d.Year == year && d.Month == month)
                    .FirstOrDefaultAsync(ct);

                var dist = new OwnerDistribution
                {
                    Id = existingDist?.Id,
                    OwnerStaffId = owner.StaffId,
                    Year = year,
                    Month = month,
                    OwnersPoolAmount = ownAlloc,
                    EquityShareAtTime = owner.EquitySharePercentage,
                    AllocationShare = equityShare,
                    TotalPayable = equityShare,
                    PaidStatus = "PAID", // Historical — already settled
                    PaidAt = end,
                    CreatedAt = existingDist?.CreatedAt ?? DateTime.UtcNow,
                    UpdatedAt = DateTime.UtcNow,
                };

                if (existingDist is null)
                    await _ownerDists.InsertOneAsync(dist, cancellationToken: ct);
                else
                    await _ownerDists.ReplaceOneAsync(d => d.Id == existingDist.Id, dist, cancellationToken: ct);

                Console.WriteLine($"      → {ownerStaff.Name} ({owner.EquitySharePercentage}%): {equityShare:N0} VND");
            }

            Console.WriteLine($"    ✓ Month {year}-{month:D2} LOCKED");
            report.Created++;
        }

        report.FinishedAt = DateTime.UtcNow;
        return report;
    }

    /// <summary>Santino gets salary every month from Nov 2025 onwards.</summary>
    private static bool santinoPaysThisMonth(int year, int month) => true;
}

