using SoulPilates.Core.Entities;
using System;

namespace SoulPilates.Core.Entities;

public class ClientPackage : BaseEntity
{
    [BsonRepresentation(BsonType.ObjectId)]
    public string ClientId { get; set; } = null!;

    public string? InvoiceLineId { get; set; }

    public string Format { get; set; } = "GROUP"; // "GROUP", "PRIVATE", "FREELANCE" (P3-S13 — freelance package slots)
    public int TotalCredits { get; set; }
    public int CreditsUsed { get; set; }
    public int CreditsRemaining { get; set; }

    public DateTime ActivationDate { get; set; }

    /// <summary>
    /// When <c>null</c> the package never expires (open-ended validity).
    /// A non-null value is enforced by the background expiry sweep and the active-
    /// package filter in <see cref="WalletService"/>. Admin can set / clear this
    /// via <c>PATCH /api/wallet/{packageId}/expiry</c>.
    /// </summary>
    public DateTime? ExpiryDate { get; set; }

    public string Status { get; set; } = "ACTIVE"; // "ACTIVE", "LOW_BALANCE", "COMPLETED", "EXPIRED", "FROZEN"
    public decimal FractionalValuePerClass { get; set; }

    /// <summary>
    /// Idempotency tags for the retention reminder job (Issue #5). Mirrors the
    /// same pattern as <see cref="Attendance.RemindersSent"/>: the background
    /// loop checks for the next-due window tag before sending, then appends it
    /// via an atomic <c>$push</c> after the email succeeds. Missing-field BSON
    /// deserialisation reads as an empty list, so legacy rows need no migration.
    /// </summary>
    public List<string> RetentionRemindersSent { get; set; } = new();
}
