// Credit tracking: pkgIdx -> remaining credits to assign
const creditsLeft = {};
pkgDefs.forEach((p, i) => { creditsLeft[i] = p.used; });

function hasCreditLeft(pkgIdx) { return creditsLeft[pkgIdx] > 0; }
function useCredit(pkgIdx) { creditsLeft[pkgIdx]--; }

// Pull active package index for a client+format
function getActivePkgIdx(ci, fmt) {
  const m = activePkgFor[ci];
  if (!m) return -1;
  return m[fmt] !== undefined ? m[fmt] : -1;
}

function addAttendance(sessionDoc, ci, pkgIdx) {
  const sessId = sessionDoc._id;
  if (!sessionBookingCount[sessId]) sessionBookingCount[sessId] = 0;
  sessionBookingCount[sessId]++;
  const pkg = pkgIdx >= 0 ? pkgDocs[pkgIdx] : null;
  attendanceDocs.push({
    _id: new ObjectId(),
    CreatedAt: new Date(sessionDoc.StartTime.getTime() - 2 * 86400000),
    UpdatedAt: sessionDoc.StartTime,
    CalendarSessionId: sessId,
    ClientId: cid(ci),
    PackageInstanceId: pkg ? pkg._id : null,
    Status: "CHECKED_IN",
    IsFreeClass: false,
    CountsTowardsCommission: true,
    BookedAt: new Date(sessionDoc.StartTime.getTime() - 2 * 86400000),
    BookingReference: ref(),
    ClientName: cname(ci),
    ClientPhone: clientData[ci].cc + " " + clientData[ci].phone,
    ClientEmail: clientData[ci].email,
    BookingSource: "ADMIN",
    PaymentMethod: pkg ? "PACKAGE_CREDIT" : "PAY_AT_STUDIO",
    AmountPaid: pkg ? 0 : null,
    AmountDueAtStudio: null,
    Seats: 1,
  });
}

