  { ci:14, avail:utc(2026,4,2)  }, // Laura
  { ci:15, avail:utc(2026,5,1)  }, // David - joined May 1
];

let gPoolIdx = 0;

function pickGroupClients(sessionDate, count) {
  const eligible = groupPool.filter(g => {
    const pkgIdx = getActivePkgIdx(g.ci, "GROUP");
    return pkgIdx >= 0 && sessionDate >= g.avail && hasCreditLeft(pkgIdx);
  });
  if (eligible.length === 0) return [];
  const picked = [];
  let attempts = 0;
  while (picked.length < count && attempts < eligible.length * 2) {
    const candidate = eligible[gPoolIdx % eligible.length];
    gPoolIdx++;
    attempts++;
    const pkgIdx = getActivePkgIdx(candidate.ci, "GROUP");
    if (hasCreditLeft(pkgIdx) && !picked.find(p => p.ci === candidate.ci)) {
      picked.push(candidate);
    }
  }
  return picked;
}

// Reformer: aim for 2-3 attendees per session
reformerPastSessions.forEach((sess, idx) => {
  const count = (idx % 3 === 0) ? 3 : 2;
  const attendees = pickGroupClients(sess.StartTime, count);
  attendees.forEach(a => {
    const pkgIdx = getActivePkgIdx(a.ci, "GROUP");
    if (hasCreditLeft(pkgIdx)) {
      useCredit(pkgIdx);
      addAttendance(sess, a.ci, pkgIdx);
    }
  });
});

