  for (let i = 0; i < 9; i++) s += chars[Math.floor(Math.random() * chars.length)];
  return s;
}

// Generate all dates in [start,end] matching weekdays array (0=Sun)
function genDates(start, end, weekdays) {
  const out = [];
  const d = new Date(start);
  while (d <= end) {
    if (weekdays.includes(d.getUTCDay())) out.push(new Date(d));
    d.setUTCDate(d.getUTCDate() + 1);
