print('Current session fields: ' + Object.keys(sess).join(', '));

// Known-good fields from the C# entity
const validFields = new Set([
  '_id','CreatedAt','UpdatedAt',
  'ClassBlueprintId','InstructorId','StartTime','EndTime',
  'Capacity','CurrentBookings','IsPublic',
  'ClassName','FocusArea','DifficultyLevel','Format',
  'InstructorName','EquipmentType','EquipmentTypes',
  'ImageUrl','Tags','InstructorPhotoUrl',
  'BlockedReason','BlockScope','BlockScopeValue',
  'RecurringScheduleRuleId','InstructorReminderSent',
  'Origin','IsOverride','OverrideNote','Status',
  'IsFreelance','FreelanceStaffId','FreelancePackageId',
  'FreelanceHeadcount','FreelanceFormat','FreelanceBillingMode',
  'FreelanceInvoiceId','FreelanceChargeAmount','DropInPrice'
]);

// Build \$unset for any field not in validFields
const unset = {};
Object.keys(sess).forEach(k => { if (!validFields.has(k)) unset[k] = ''; });
print('Fields to remove: ' + JSON.stringify(unset));

if (Object.keys(unset).length > 0) {
  const r = D.CalendarSessions.updateMany({}, {'\$unset': unset});
  print('Updated: ' + r.modifiedCount + ' sessions');
} else {
  print('No extra fields found');
}
