---
// ─── Install-to-home-screen prompt ────────────────────────────────────────
//
// Rendered once into AdminLayout. Listens for the `beforeinstallprompt`
// event on Chromium-family browsers and offers a non-blocking banner so
// the user can install with one tap. For iOS Safari (which never fires
// `beforeinstallprompt`) we show a one-time coach card with the explicit
// Share → Add to Home Screen instructions, since that's the *only* way
// to get the PWA installed there.
//
// Dismissal is sticky: clicking ✕ stores a flag in localStorage so the
// banner doesn't reappear every page-load. The flag has a 30-day TTL so
// users who later change their mind don't have to clear storage.
//
// Why a banner and not a modal? The studio's primary surfaces (POS,
// Schedule) are time-sensitive; a hard interrupt at 7am would be hostile.
// The banner sits politely at the bottom and can be ignored.
---

<div class="pwa-install-banner" id="pwaInstallBanner" hidden>
  <div class="pwa-install-icon" aria-hidden="true">
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      stroke-width="2"
      stroke-linecap="round"
      stroke-linejoin="round"
    >
      <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path>
      <polyline points="7 10 12 15 17 10"></polyline>
      <line x1="12" y1="15" x2="12" y2="3"></line>
    </svg>
  </div>
  <div class="pwa-install-body">
    <div class="pwa-install-title">Install Soul Pilates</div>
    <div class="pwa-install-sub" id="pwaInstallSub">
      Add it to your home screen for instant access and class reminders.
    </div>
  </div>
  <button class="pwa-install-cta" id="pwaInstallCta" type="button"
    >Install</button
  >
  <button
    class="pwa-install-close"
    id="pwaInstallClose"
    type="button"
    aria-label="Dismiss"
  >
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 24 24"
      width="14"
      height="14"
      fill="none"
      stroke="currentColor"
      stroke-width="2.5"
      stroke-linecap="round"
      stroke-linejoin="round"
    >
      <line x1="18" y1="6" x2="6" y2="18"></line>
      <line x1="6" y1="6" x2="18" y2="18"></line>
    </svg>
  </button>
</div>

<!-- iOS coach card. Hidden by default; the script below shows it for iOS Safari users who haven't installed yet. -->
<div class="pwa-ios-coach" id="pwaIosCoach" hidden>
  <div class="pwa-ios-coach-inner">
    <button
      class="pwa-ios-coach-close"
      id="pwaIosCoachClose"
      type="button"
      aria-label="Dismiss"
    >
      <svg
        xmlns="http://www.w3.org/2000/svg"
        viewBox="0 0 24 24"
        width="14"
        height="14"
        fill="none"
        stroke="currentColor"
        stroke-width="2.5"
        stroke-linecap="round"
        stroke-linejoin="round"
      >
        <line x1="18" y1="6" x2="6" y2="18"></line>
        <line x1="6" y1="6" x2="18" y2="18"></line>
      </svg>
    </button>
    <div class="pwa-ios-coach-title">Add to Home Screen</div>
    <div class="pwa-ios-coach-step">
      <span class="pwa-ios-coach-num">1</span>
      Tap the Share button
      <svg
        xmlns="http://www.w3.org/2000/svg"
        viewBox="0 0 24 24"
        width="16"
        height="16"
        fill="none"
        stroke="currentColor"
        stroke-width="2"
        stroke-linecap="round"
        stroke-linejoin="round"
        style="vertical-align:middle;margin-left:4px;"
      >
        <path d="M4 12v8a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-8"></path>
        <polyline points="16 6 12 2 8 6"></polyline>
        <line x1="12" y1="2" x2="12" y2="15"></line>
      </svg>
      below.
    </div>
    <div class="pwa-ios-coach-step">
      <span class="pwa-ios-coach-num">2</span>
      Scroll &amp; tap <strong>Add to Home Screen</strong>.
    </div>
    <div class="pwa-ios-coach-step">
      <span class="pwa-ios-coach-num">3</span>
      Tap <strong>Add</strong>. You'll get the icon and notifications.
    </div>
  </div>
</div>

<style is:global>
  /* ── Chromium install banner ───────────────────────────────────────── */
  .pwa-install-banner {
    position: fixed;
    bottom: 20px;
    left: 50%;
    transform: translateX(-50%);
    z-index: 10000;
    display: flex;
    align-items: center;
    gap: 14px;
    background: var(--color-surface-raised, #1f1814);
    color: var(--color-text-primary, #f5efe7);
    border: 1px solid var(--color-border, #2a221c);
    border-radius: 12px;
    padding: 12px 14px 12px 16px;
    box-shadow:
      0 10px 40px rgba(0, 0, 0, 0.35),
      0 0 0 1px rgba(180, 140, 80, 0.1);
    backdrop-filter: blur(20px) saturate(140%);
    max-width: calc(100vw - 32px);
    width: 380px;
    animation: pwa-slide-up 0.35s cubic-bezier(0.16, 1, 0.3, 1);
  }
  .pwa-install-icon {
    flex-shrink: 0;
    width: 36px;
    height: 36px;
    border-radius: 8px;
    background: linear-gradient(
      135deg,
      rgba(180, 140, 80, 0.22),
      rgba(180, 140, 80, 0.08)
    );
    color: rgb(212, 170, 100);
    display: grid;
    place-items: center;
  }
  .pwa-install-icon svg {
    width: 18px;
    height: 18px;
  }
  .pwa-install-body {
    flex: 1;
    min-width: 0;
  }
  .pwa-install-title {
    font-family: 'Inter', -apple-system, sans-serif;
    font-size: 16px;
    font-weight: 600;
    letter-spacing: 0.01em;
  }
  .pwa-install-sub {
    font-size: 12px;
    color: var(--color-text-muted, #b3a89a);
    line-height: 1.4;
    margin-top: 2px;
  }
  .pwa-install-cta {
    flex-shrink: 0;
    background: linear-gradient(135deg, rgb(180, 140, 80), rgb(150, 110, 60));
    color: #fff;
    border: 0;
    border-radius: 8px;
    padding: 8px 14px;
    font-weight: 600;
    font-size: 13px;
    cursor: pointer;
    transition:
      transform 0.15s ease,
      box-shadow 0.15s ease;
  }
  .pwa-install-cta:hover {
    transform: translateY(-1px);
    box-shadow: 0 6px 16px rgba(180, 140, 80, 0.35);
  }
  .pwa-install-close {
    flex-shrink: 0;
    background: transparent;
    border: 0;
    color: var(--color-text-muted, #b3a89a);
    cursor: pointer;
    padding: 4px;
    border-radius: 6px;
    display: grid;
    place-items: center;
    transition:
      background 0.15s ease,
      color 0.15s ease;
  }
  .pwa-install-close:hover {
    background: rgba(255, 255, 255, 0.06);
    color: var(--color-text-primary, #f5efe7);
  }

  /* ── iOS coach card ──────────────────────────────────────────────── */
  .pwa-ios-coach {
    position: fixed;
    bottom: 90px; /* clears the mobile bottom nav */
    left: 50%;
    transform: translateX(-50%);
    z-index: 10000;
    max-width: calc(100vw - 32px);
    width: 340px;
    animation: pwa-slide-up 0.35s cubic-bezier(0.16, 1, 0.3, 1);
  }
  .pwa-ios-coach-inner {
    position: relative;
    background: var(--color-surface-raised, #1f1814);
    color: var(--color-text-primary, #f5efe7);
    border: 1px solid var(--color-border, #2a221c);
    border-radius: 14px;
    padding: 18px 20px 16px;
    box-shadow:
      0 12px 40px rgba(0, 0, 0, 0.4),
      0 0 0 1px rgba(180, 140, 80, 0.1);
    backdrop-filter: blur(20px) saturate(140%);
  }
  .pwa-ios-coach-close {
    position: absolute;
    top: 10px;
    right: 10px;
    background: transparent;
    border: 0;
    color: var(--color-text-muted);
    cursor: pointer;
    padding: 4px;
    border-radius: 6px;
  }
  .pwa-ios-coach-title {
    font-family: 'Inter', -apple-system, sans-serif;
    font-size: 18px;
    font-weight: 600;
    margin-bottom: 10px;
  }
  .pwa-ios-coach-step {
    font-size: 13px;
    line-height: 1.6;
    color: var(--color-text-muted);
    display: flex;
    align-items: baseline;
    gap: 8px;
    padding: 4px 0;
  }
  .pwa-ios-coach-step strong {
    color: var(--color-text-primary);
    font-weight: 600;
  }
  .pwa-ios-coach-num {
    flex-shrink: 0;
    width: 20px;
    height: 20px;
    border-radius: 50%;
    background: rgba(180, 140, 80, 0.22);
    color: rgb(212, 170, 100);
    font-size: 11px;
    font-weight: 700;
    display: inline-grid;
    place-items: center;
    align-self: center;
  }

  @keyframes pwa-slide-up {
    from {
      opacity: 0;
      transform: translate(-50%, 12px);
    }
    to {
      opacity: 1;
      transform: translate(-50%, 0);
    }
  }
</style>

<script is:inline>
  // ─── Install prompt — Chromium ────────────────────────────────────
  // The browser fires `beforeinstallprompt` exactly once when its install
  // heuristics decide our app qualifies. We stash the event, show our
  // banner, and call .prompt() on click. Once accepted, the browser
  // never fires the event again — but we listen for `appinstalled` to
  // hide any lingering UI.
  //
  // Dismissal TTL: 30 days. Stored as the dismissal timestamp so the
  // banner reappears later for users who initially declined.
  //
  // NOTE: We use style.display instead of the `hidden` attribute because
  // the banner's CSS sets `display:flex` which overrides `[hidden]` in
  // some rendering contexts, causing the banner to remain visible.
  (function () {
    var STORAGE_KEY = "pwa-install-dismissed-at";
    var TTL_DAYS = 30;
    var banner = document.getElementById("pwaInstallBanner");
    var cta = document.getElementById("pwaInstallCta");
    var closeBtn = document.getElementById("pwaInstallClose");
    var subText = document.getElementById("pwaInstallSub");
    if (!banner || !cta || !closeBtn) return;

    // Ensure the banner starts hidden (belt-and-suspenders with `hidden` attr)
    banner.style.display = "none";

    function isDismissed() {
      var v = localStorage.getItem(STORAGE_KEY);
      if (!v) return false;
      var age = (Date.now() - Number(v)) / (1000 * 60 * 60 * 24);
      return age < TTL_DAYS;
    }
    function rememberDismissal() {
      localStorage.setItem(STORAGE_KEY, String(Date.now()));
    }
    function showBanner() {
      if (!isDismissed()) {
        banner.removeAttribute("hidden");
        banner.style.display = "flex";
      }
    }
    function hideBanner() {
      banner.setAttribute("hidden", "");
      banner.style.display = "none";
    }

    // Detect if already running as installed PWA
    var isStandalone =
      window.matchMedia("(display-mode: standalone)").matches ||
      window.matchMedia("(display-mode: window-controls-overlay)").matches ||
      navigator.standalone === true;
    if (isStandalone) return; // Already installed — never show the banner.

    var deferredPrompt = null;

    window.addEventListener("beforeinstallprompt", function (e) {
      e.preventDefault();
      deferredPrompt = e;
      showBanner();
    });

    cta.addEventListener("click", async function () {
      if (!deferredPrompt) {
        // Prompt was consumed or never arrived. Give the user guidance.
        if (subText) {
          subText.textContent =
            "Use your browser's install option (address bar icon or menu → Install app).";
          subText.style.color = "rgb(212, 170, 100)";
        }
        return;
      }
      hideBanner();
      try {
        deferredPrompt.prompt();
        var choice = await deferredPrompt.userChoice;
        if (choice.outcome === "dismissed") rememberDismissal();
      } catch (err) {
        // Prompt was already consumed (e.g. browser showed its own UI)
        console.warn("[PWA] Install prompt error:", err);
      }
      deferredPrompt = null;
    });

    closeBtn.addEventListener("click", function () {
      hideBanner();
      rememberDismissal();
    });

    window.addEventListener("appinstalled", function () {
      hideBanner();
      deferredPrompt = null;
    });
  })();

  // ─── iOS coach card ───────────────────────────────────────────────
  // Show on iOS Safari (not Chrome-on-iOS, which uses WebKit but still
  // doesn't support the prompt) when not already installed.
  (function () {
    var COACH_KEY = "pwa-ios-coach-dismissed-at";
    var TTL_DAYS = 14;
    var coach = document.getElementById("pwaIosCoach");
    var closeBtn = document.getElementById("pwaIosCoachClose");
    if (!coach || !closeBtn) return;

    // Ensure starts hidden
    coach.style.display = "none";

    var ua = navigator.userAgent;
    var isIOS = /iPhone|iPad|iPod/.test(ua);
    // Safari on iOS contains "Version/" + "Safari/" and lacks "CriOS"/"FxiOS".
    var isIOSSafari =
      isIOS &&
      /Version\/[\d.]+ Safari/.test(ua) &&
      !/CriOS|FxiOS|EdgiOS/.test(ua);
    // navigator.standalone is iOS-specific and only true once the user has
    // added the PWA to their home screen.
    var isStandalone =
      ("standalone" in navigator && navigator.standalone) ||
      window.matchMedia("(display-mode: standalone)").matches;

    function isDismissed() {
      var v = localStorage.getItem(COACH_KEY);
      if (!v) return false;
      var age = (Date.now() - Number(v)) / (1000 * 60 * 60 * 24);
      return age < TTL_DAYS;
    }

    if (isIOSSafari && !isStandalone && !isDismissed()) {
      // Delay slightly so it doesn't compete with first-paint or login.
      setTimeout(function () {
        coach.removeAttribute("hidden");
        coach.style.display = "block";
      }, 2500);
    }

    closeBtn.addEventListener("click", function () {
      coach.setAttribute("hidden", "");
      coach.style.display = "none";
      localStorage.setItem(COACH_KEY, String(Date.now()));
    });
  })();
</script>

