// ── Install App button ────────────────────────────────────────────
(function() {
  const btn      = document.getElementById('profileInstallBtn');
  const label    = document.getElementById('profileInstallLabel');
  const sub      = document.getElementById('profileInstallSub');
  const chevron  = document.getElementById('profileInstallChevron');
  const iosSteps = document.getElementById('profileIosSteps');
  if (!btn) return;

  const isStandalone =
    window.matchMedia('(display-mode: standalone)').matches ||
    window.matchMedia('(display-mode: window-controls-overlay)').matches ||
    navigator.standalone === true;

  if (isStandalone) {
    label.textContent = 'App Installed';
    sub.textContent = 'You\'re running Soul Pilates as an app.';
    chevron.style.display = 'none';
    btn.style.cursor = 'default';
    btn.style.opacity = '0.7';
    return;
  }

  const ua = navigator.userAgent;
  const isIOS = /iPhone|iPad|iPod/.test(ua);
  const isIOSSafari = isIOS && /Version\/[\d.]+ Safari/.test(ua) && !/CriOS|FxiOS|EdgiOS/.test(ua);

  // Android/Chrome: use deferred prompt captured by InstallPrompt component
  btn.addEventListener('click', function() {
    if (window.__pwaInstallPrompt) {
      window.__pwaInstallPrompt.prompt();
      window.__pwaInstallPrompt.userChoice.then(function() {
        window.__pwaInstallPrompt = null;
      });
    } else if (isIOSSafari) {
      // Toggle inline iOS instructions
      const open = iosSteps.style.display !== 'none';
      iosSteps.style.display = open ? 'none' : 'block';
      chevron.style.transform = open ? '' : 'rotate(90deg)';
    } else {
      // Chrome/Android but prompt not ready yet — guide via browser UI
      sub.textContent = 'Tap the browser menu (⋮) and choose "Add to Home Screen".';
      sub.style.color = 'rgb(212,170,100)';
      chevron.style.display = 'none';
    }
  });
})();

