            required
          />
        </div>

        <button class="btn" id="loginBtn" type="submit">
          <span id="btnLabel">Sign in</span>
          <svg
            xmlns="http://www.w3.org/2000/svg"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="2.5"
            aria-hidden="true"
            ><line x1="5" y1="12" x2="19" y2="12"></line><polyline
              points="12 5 19 12 12 19"></polyline></svg
          >
        </button>
      </form>

      <div class="footer-mark">Soul Pilates · Studio Management</div>
    </main>

    <script>
      // Role-aware auto-redirect for already-authenticated users.
      // P3-S09: instructor tokens now route to /instructor; everything
      // else (admin, owner, fallback) routes to /admin.
      (function () {
        var token = localStorage.getItem("token");
        if (!token) return;
        try {
          var payload = JSON.parse(atob(token.split(".")[1]));
          var role = (
            payload[
              "http://schemas.microsoft.com/ws/2008/06/identity/claims/role"
            ] ||
            payload.role ||
            ""
          ).toLowerCase();
          window.location.href =
            role === "instructor" ? "/instructor" : "/admin";
        } catch (e) {
          // Malformed token — clear it and stay on the login page.
          localStorage.removeItem("token");
        }
      })();

      async function doLogin(ev) {
        if (ev) ev.preventDefault();
        const email = document.getElementById("email").value.trim();
        const password = document.getElementById("password").value;
        const errEl = document.getElementById("errorMsg");
        const btn = document.getElementById("loginBtn");
        const lbl = document.getElementById("btnLabel");
        errEl.style.display = "none";
        lbl.textContent = "Signing in…";
        btn.disabled = true;

        try {
          const res = await fetch(
            import.meta.env.PUBLIC_API_URL + "/api/auth/login",
            {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({ email, password }),
            },
          );
          if (!res.ok) throw new Error();
          const data = await res.json();
          localStorage.setItem("token", data.token);
          if (data.staffId) localStorage.setItem("staffId", data.staffId);
          // Force password change before reaching the dashboard.
          if (data.mustChangePassword) {
            window.location.href = "/admin/change-password";
            return;
          }
          // P3-S09: role-aware post-login redirect.
          // Instructor → instructor portal; Admin, Receptionist, Accountant → admin dashboard
          const role = (data.userRole || "").toLowerCase();
          window.location.href =
            role === "instructor" ? "/instructor" : "/admin";
        } catch {
          errEl.textContent = "Invalid email or password. Please try again.";
          errEl.style.display = "block";
          lbl.textContent = "Sign in";
          btn.disabled = false;
        }
      }

      // Wire submit handler — required because Astro bundles this <script> as
      // an ES module, so `doLogin` is module-scoped and not accessible from an
      // inline `onsubmit=` attribute on the form.
      document.getElementById("loginForm").addEventListener("submit", doLogin);
    </script>
  </body>
</html>

using MongoDB.Bson;
using MongoDB.Bson.Serialization.Attributes;
using SoulPilates.Core.Entities;

namespace SoulPilates.Core.Entities;

public class InvoiceLine : BaseEntity
{
    [BsonRepresentation(BsonType.ObjectId)]
    public string InvoiceId { get; set; } = null!;

    [BsonRepresentation(BsonType.ObjectId)]
    public string ProductId { get; set; } = null!;

    [BsonRepresentation(BsonType.ObjectId)]
    public string? VariantId { get; set; }

    public int Quantity { get; set; }
    public decimal UnitPrice { get; set; }
    public decimal LineDiscount { get; set; }
    public decimal LineTotal { get; set; }

    /// <summary>
    /// Links this invoice line to a specific booking (Attendance) when the
    /// line represents a class drop-in purchased at POS or a studio-collected
    /// balance. Null for merchandise, packages, and non-class lines.
    /// </summary>
    [BsonRepresentation(BsonType.ObjectId)]
    public string? AttendanceId { get; set; }

    /// <summary>
    /// Links this invoice line to a specific calendar session when the
    /// line represents a class drop-in. Null for non-class lines.
    /// </summary>
    [BsonRepresentation(BsonType.ObjectId)]
    public string? CalendarSessionId { get; set; }

    /// <summary>
    /// Optional human-readable description for the line (e.g. "Group Class Session").
    /// When set, InvoiceService uses this instead of looking up the product name.
    /// Used for credit-based class bookings where ProductId is a blueprint ID.
    /// </summary>
    public string? Description { get; set; }

    /// Snapshot of <see cref="Product.Type"/> at the moment the invoice was created. Used by the
    /// washout pipeline to attribute revenue to the correct category ("PACKAGE", "MERCHANDISE",
    /// etc.) <em>as it was at sale time</em> — so a later reclassification of the product
    /// (e.g. switching it from PACKAGE to MERCHANDISE) cannot retroactively reshuffle historical
    /// <c>MonthlyWashout.RevenueByCategory</c> totals. Null on lines that pre-date this field;
    /// the washout reader falls back to the live <c>Product.Type</c> in that case.
    /// </summary>
    public string? ProductTypeSnapshot { get; set; }
}

