---
import '../styles/global.css';
import InstallPrompt from '../components/admin/InstallPrompt.astro';
/*
 * P3-S09 — Instructor Portal layout.
 *
 * Sibling of AdminLayout. Same shell chrome (sidebar + topbar +
 * theme toggle + auth guard) for consistency — Q3-S09-6 default
 * (A) deliberately mirrors the admin design system so an instructor
 * doesn't experience a brand whiplash when the studio owner is
 * showing them around the platform.
 *
 * Sidebar pre-seeds disabled "Coming soon" items per Q3-S09-5 (A)
 * so P3-S10 lands by flipping the disabled flag rather than
 * inserting new nav entries.
 *
 * Auth guard: redirect to /login if no token; redirect to /admin
 * if the token is for a non-Instructor role (defence-in-depth —
 * the role-aware login redirect should prevent this case from ever
 * being hit, but a copy-pasted admin token shouldn't get an empty
 * instructor portal).
 */
export interface Props {
  title: string;
  activePage?: string;
}
const { title, activePage = '' } = Astro.props;
---
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover" />
  <title>{title} — Soul Pilates Instructor Portal</title>
  <meta name="description" content="Soul Pilates instructor self-service portal." />
  <meta name="theme-color" content="#1A1410" />

  {/* PWA — installable shell */}
  <link rel="manifest" href="/manifest.webmanifest" />
  <link rel="icon" type="image/png" sizes="192x192" href="/icons/icon-192.png" />
  <link rel="apple-touch-icon" href="/icons/icon-192.png" />
  <meta name="apple-mobile-web-app-capable" content="yes" />
  <meta name="apple-mobile-web-app-status-bar-style" content="black-translucent" />
  <meta name="apple-mobile-web-app-title" content="Soul Pilates" />
  <meta name="mobile-web-app-capable" content="yes" />

  <script is:inline>
    (function() {
      try {
        var saved = localStorage.getItem('admin-theme');
        var prefersDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
        var theme = saved || (prefersDark ? 'dark' : 'light');
        document.documentElement.dataset.theme = theme;
      } catch (e) {
        document.documentElement.dataset.theme = 'light';
      }
    })();
  </script>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap" rel="stylesheet">
  <link rel="icon" type="image/svg+xml" href="/favicon.svg" />
  <meta name="api-url" content={import.meta.env.PUBLIC_API_URL || ''} />

</head>
<body>
<div class="app-shell">

  <!-- ── Sidebar ── -->
  <aside class="sidebar" id="sidebar">
    <div class="sidebar-header">
      <a href="/instructor/schedule" class="sidebar-logo">
        <div class="sidebar-logo-icon" aria-label="Soul Pilates">
          <img src="/logo.png" alt="Soul Pilates" class="sidebar-logo-img" />
        </div>
        <div>
          <div class="sidebar-logo-text">Soul Pilates</div>
          <div class="sidebar-logo-sub">Instructor</div>
        </div>
      </a>
      <button class="collapse-toggle" id="collapseToggle" onclick="toggleSidebar()" title="Collapse sidebar" aria-label="Collapse sidebar">
        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><polyline points="15 18 9 12 15 6"/></svg>
      </button>
    </div>

    <nav class="sidebar-nav">
      <div class="nav-section-label">My space</div>
      {/*
        P3-S10 — schedule + earnings now active; Client notes still
        deferred to a future slice.
      */}
      <a href="/instructor/schedule" class={`nav-item ${activePage === 'schedule' ? 'active' : ''}`}>
        <svg class="nav-icon" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>
        <span class="nav-item-label">My schedule</span>
      </a>
      <a href="/instructor/earnings" class={`nav-item ${activePage === 'earnings' ? 'active' : ''}`}>
        <svg class="nav-icon" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><line x1="12" y1="1" x2="12" y2="23"/><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/></svg>
        <span class="nav-item-label">My earnings</span>
      </a>
      <a class="nav-item disabled" aria-disabled="true" title="Coming soon">
        <svg class="nav-icon" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>
        <span class="nav-item-label">Client notes</span>
        <span class="nav-badge">Soon</span>
      </a>
    </nav>

    <div class="sidebar-footer">
      <button class="theme-toggle" id="themeToggle" onclick="toggleTheme()" aria-label="Toggle theme">
        <svg class="icon-moon" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/></svg>
        <svg class="icon-sun" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.93 4.93l1.41 1.41M17.66 17.66l1.41 1.41M2 12h2M20 12h2M4.93 19.07l1.41-1.41M17.66 6.34l1.41-1.41"/></svg>
        <span class="nav-item-label" id="themeToggleLabel">Dark mode</span>
      </button>
      <button onclick="logout()" class="theme-toggle" aria-label="Sign out">
        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/><polyline points="16 17 21 12 16 7"/><line x1="21" y1="12" x2="9" y2="12"/></svg>
        <span class="nav-item-label">Sign out</span>
      </button>
    </div>
  </aside>

  <!-- ── Main Area ── -->
  <div class="main-area">
    <header class="topbar">
      <div class="topbar-left">
        <button class="hamburger-btn" id="hamburgerBtn" onclick="toggleMobileSidebar()" aria-label="Open menu" aria-expanded="false" aria-controls="sidebar">
          <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><line x1="3" y1="6" x2="21" y2="6"/><line x1="3" y1="12" x2="21" y2="12"/><line x1="3" y1="18" x2="21" y2="18"/></svg>
        </button>
        <span class="topbar-breadcrumb">{title}</span>
      </div>
      <div class="topbar-right">
        <!-- Admin impersonation dropdown -->
        <div class="va-wrap" id="viewAsWrap" style="display:none;">
          <label class="va-label" for="viewAsSelect">
            <svg xmlns="http://www.w3.org/2000/svg" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
            View as
          </label>
          <select class="va-select" id="viewAsSelect">
            <option value="">— Select instructor —</option>
          </select>
        </div>
        <span class="text-sm text-muted hidden-mobile" id="topbar-date"></span>
        <button class="topbar-avatar" id="topbar-avatar" title="My Profile" type="button" style="cursor:pointer;border:none;font-family:inherit;">
          <span id="topbarAvatarInner">I</span>
        </button>
      </div>
    </header>
    <main class="content-area">
      <slot />
    </main>
  </div>

</div>

<!-- ── Mobile sidebar backdrop (drawer dim layer) ── -->
<div class="sidebar-backdrop" id="sidebarBackdrop" onclick="closeMobileSidebar()" aria-hidden="true"></div>

<!-- ── Profile Offcanvas (slide-out) ── -->
