<div class="toast-host" id="toastHost" aria-live="polite" aria-atomic="true"></div>

<script is:inline>
  // ─── Auth guard ──────────────────────────────────────────────
  // Two-layer guard:
  //   1. No token → bounce to /admin/login (shared login surface).
  //   2. Token present but role is a customer (non-staff) → bounce to /.
  //      Admin and SuperAdmin users are explicitly allowed so they can
  //      view the instructor portal on behalf of an instructor or for
  //      auditing purposes. Instructor is the primary audience.
  (function() {
    var token = localStorage.getItem('token');
    if (!token) { window.location.href = '/admin/login'; return; }
    try {
      var payload = JSON.parse(atob(token.split('.')[1]));
      var role = (payload['http://schemas.microsoft.com/ws/2008/06/identity/claims/role'] || payload.role || '').toLowerCase();
      var allowed = ['instructor', 'admin', 'superadmin'];
      if (role && allowed.indexOf(role) === -1) { window.location.href = '/admin'; return; }
    } catch (e) { /* malformed token → let the API 401 handle it */ }
  })();

  // ─── Date in topbar ──────────────────────────────────────────
  const _topbarDate = document.getElementById('topbar-date');
  if (_topbarDate) {
    _topbarDate.textContent = new Date().toLocaleDateString('en-US', {
      weekday: 'short', month: 'short', day: 'numeric'
    });
  }

  function logout() { localStorage.removeItem('token'); window.location.href = '/admin/login'; }

  function toggleSidebar() {
    const sb = document.getElementById('sidebar');
    sb.classList.toggle('collapsed');
    localStorage.setItem('sidebarCollapsed', sb.classList.contains('collapsed'));
  }
  if (localStorage.getItem('sidebarCollapsed') === 'true') {
    document.getElementById('sidebar').classList.add('collapsed');
  }

  // ─── Mobile sidebar drawer (SPM-112) ────────────────────────
  // On phones the sidebar is hidden (display:none via the global
  // ≤768px media query). The hamburger slides it in as a fixed
  // overlay drawer; tapping the backdrop or any nav item closes it.
  function openMobileSidebar() {
    document.getElementById('sidebar')?.classList.add('mobile-open');
    document.getElementById('sidebarBackdrop')?.classList.add('open');
    document.getElementById('hamburgerBtn')?.setAttribute('aria-expanded', 'true');
    document.body.style.overflow = 'hidden';
  }
  function closeMobileSidebar() {
    document.getElementById('sidebar')?.classList.remove('mobile-open');
    document.getElementById('sidebarBackdrop')?.classList.remove('open');
    document.getElementById('hamburgerBtn')?.setAttribute('aria-expanded', 'false');
    document.body.style.overflow = '';
  }
  function toggleMobileSidebar() {
    const sb = document.getElementById('sidebar');
    if (sb && sb.classList.contains('mobile-open')) closeMobileSidebar();
    else openMobileSidebar();
  }
  // Close the drawer when a nav item is tapped (navigation within the SPA shell).
  document.querySelectorAll('#sidebar .sidebar-nav .nav-item, #sidebar .sidebar-logo').forEach(function(el) {
    el.addEventListener('click', closeMobileSidebar);
  });
  // Close on Escape for keyboard users.
  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape') closeMobileSidebar();
  });

  function toggleTheme() {
    const next = document.documentElement.dataset.theme === 'dark' ? 'light' : 'dark';
    document.documentElement.dataset.theme = next;
    localStorage.setItem('admin-theme', next);
    updateThemeLabels();
  }
  function updateThemeLabels() {
    const isDark = document.documentElement.dataset.theme === 'dark';
    const label = isDark ? 'Light mode' : 'Dark mode';
    const a = document.getElementById('themeToggleLabel');
    if (a) a.textContent = label;
  }
  updateThemeLabels();
  // ─── Global toast helper ────────────────────────────────────
  window.showToast = function(message, type) {
    const host = document.getElementById('toastHost');
    if (!host) return;
    const el = document.createElement('div');
    el.className = 'toast' + (type ? ' ' + type : '');
    const iconMap = {
      success: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg>',
      error:   '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><circle cx="12" cy="12" r="10"/><line x1="15" y1="9" x2="9" y2="15"/><line x1="9" y1="9" x2="15" y2="15"/></svg>',
      warning: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>',
    };
    el.innerHTML = (iconMap[type] || '') + '<span>' + String(message).replace(/[<>&]/g, c => ({'<':'&lt;','>':'&gt;','&':'&amp;'}[c])) + '</span>';
    host.appendChild(el);
    setTimeout(() => {
      el.classList.add('exiting');
      setTimeout(() => el.remove(), 250);
    }, 3000);
  };
</script>

