<script is:inline>
  // ─── Admin / Owner "View As" impersonation ──────────────────────
  // Active for Admin / SuperAdmin and (SPM-103) Owner users. Loads the
  // staff list and renders a dropdown to switch between instructors.
  // Selected staffId is stored in sessionStorage as 'viewAsStaffId'.
  // All instructor pages read this value and pass ?viewAs= on API calls.
  // SPM-103: an "All instructors" option (value 'all') asks the API for
  // the whole-studio aggregate schedule/roster.
  (function initViewAs() {
    var token = localStorage.getItem('token');
    if (!token) return;

    var role = '';
    try {
      var payload = JSON.parse(atob(token.split('.')[1]));
      role = (payload['http://schemas.microsoft.com/ws/2008/06/identity/claims/role'] || payload.role || '').toLowerCase();
    } catch (e) { return; }

    if (role !== 'admin' && role !== 'superadmin' && role !== 'owner') return;

    var wrap = document.getElementById('viewAsWrap');
    var sel = document.getElementById('viewAsSelect');
    if (!wrap || !sel) return;

    wrap.style.display = '';

    // Resolve API URL from the meta tag injected in <head>
    var apiUrl = '';
    try {
      var metaApi = document.querySelector('meta[name="api-url"]');
      apiUrl = metaApi ? metaApi.getAttribute('content') : '';
    } catch (e) {}
    if (!apiUrl) {
      apiUrl = localStorage.getItem('sp_api_url') || '';
    }

    // SPM-103 — render the static options up front so the switcher is
    // usable even if /api/staff is unavailable for this role (e.g. an
    // Owner token that /api/staff doesn't authorise). "All instructors"
    // (whole-studio schedule/roster) never depends on the staff list.
    var meLabel = role === 'owner' ? '— Me (Owner) —' : '— Me (Admin) —';
    sel.innerHTML = '<option value="">' + meLabel + '</option>'
      + '<option value="all">★ All instructors</option>';

    // Helper: reflect the restored selection in the topbar avatar.
    function applyRestoredSelection(instructors) {
      var saved = sessionStorage.getItem('viewAsStaffId');
      if (!saved) return;
      sel.value = saved;
      var av = document.getElementById('topbar-avatar');
      if (!av) return;
      if (saved === 'all') {
        // SPM-103 — aggregate view: show a studio-wide marker.
        av.textContent = '∗';
        av.title = 'Viewing: All instructors';
        return;
      }
      var staff = (instructors || []).find(function(s) { return s.id === saved; });
      if (staff) {
        var initials = staff.name.split(' ').map(function(w) { return w[0]; }).join('').substring(0,2).toUpperCase();
        av.textContent = initials;
        av.title = 'Viewing as: ' + staff.name;
      }
    }

    // Restore immediately so 'all' / cached selections survive even if
    // the staff fetch fails; re-applied after the list loads for the
    // single-instructor avatar initials.
    applyRestoredSelection([]);

    fetch(apiUrl + '/api/staff', {
      headers: { 'Authorization': 'Bearer ' + token }
    })
    .then(function(r) { return r.ok ? r.json() : []; })
    .then(function(staffList) {
      // Filter to active staff only.
      var instructors = (staffList || []).filter(function(s) {
        return s.isActive !== false;
      });

      instructors.forEach(function(s) {
        var opt = document.createElement('option');
        opt.value = s.id;
        opt.textContent = s.name + (s.role ? ' (' + s.role + ')' : '');
        sel.appendChild(opt);
      });

      applyRestoredSelection(instructors);
    })
    .catch(function() {
      // Staff API failed — keep the switcher with Me + All instructors.
    });

    // On change — store selection and reload
    sel.addEventListener('change', function() {
      var val = sel.value;
      if (val) {
        sessionStorage.setItem('viewAsStaffId', val);
      } else {
        sessionStorage.removeItem('viewAsStaffId');
      }
      // Reload page to apply new impersonation context
      window.location.reload();
    });
  })();

  // ─── Helper: get viewAs query param suffix ──────────────────────
  // Pages should call getViewAsParam() to get the query suffix.
  // Returns '&viewAs=xxx' or '' if no impersonation is active.
  window.getViewAsParam = function() {
    var id = sessionStorage.getItem('viewAsStaffId');
    return id ? '&viewAs=' + encodeURIComponent(id) : '';
  };
  // Returns just the staffId or null
  window.getViewAsStaffId = function() {
    return sessionStorage.getItem('viewAsStaffId') || null;
  };
</script>

<!-- ── Profile Offcanvas Logic ── -->
<script>
  import { isSupported, getPermission, isSubscribedHere, enable, disable, listMyDevices, sendTest } from '/src/scripts/push-client.js';

  const API = import.meta.env.PUBLIC_API_URL;
  const token = localStorage.getItem('token');

  const modal       = document.getElementById('profileModal');
  const overlay     = document.getElementById('profileOverlay');
  const avatarBtn   = document.getElementById('topbar-avatar');
  const closeBtn    = document.getElementById('profileClose');

  // ── Open / Close ──────────────────────────────────────────────
  function openProfile() {
    modal.classList.add('open');
    overlay.classList.add('open');
    document.body.style.overflow = 'hidden';
    loadProfile();
    loadPushStatus();
    loadPreferences();
  }
  function closeProfile() {
    modal.classList.remove('open');
    overlay.classList.remove('open');
    document.body.style.overflow = '';
  }

  avatarBtn?.addEventListener('click', openProfile);
  closeBtn?.addEventListener('click', closeProfile);
  overlay?.addEventListener('click', closeProfile);
  document.addEventListener('keydown', e => { if (e.key === 'Escape' && modal.classList.contains('open')) closeProfile(); });

  // ── Profile tab switching ───────────────────────────────────────
  const ptabBtns   = document.querySelectorAll('.profile-tab');
  const ptabPanels = {
    profile:       document.getElementById('ptabProfile'),
    notifications: document.getElementById('ptabNotifications'),
  };
  ptabBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      ptabBtns.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      Object.entries(ptabPanels).forEach(([key, panel]) => {
        panel.style.display = key === btn.dataset.ptab ? '' : 'none';
        if (key === btn.dataset.ptab) panel.classList.add('active');
        else panel.classList.remove('active');
      });
    });
  });

  // ── Load Profile (GET /api/me) ──────────────────────────────────
  let _profileData = null;

  async function loadProfile() {
    try {
      const res = await fetch(`${API}/api/me`, {
        headers: { 'Authorization': 'Bearer ' + token },
      });
      if (!res.ok) return;
      const u = await res.json();
      _profileData = u;

      // Name
      document.getElementById('profileNameDisplay').textContent = u.name || 'User';
      document.getElementById('profileNameInput').value = u.name || '';

      // Email
      document.getElementById('profileEmailDisplay').textContent = u.email || '';
      document.getElementById('profileEmailInput').value = u.email || '';

      // Role badge
      document.getElementById('profileRoleBadge').textContent = u.role || 'Instructor';

      // Avatar — offcanvas
      const circle = document.getElementById('profileAvatarCircle');
      if (u.photoUrl) {
        circle.innerHTML = `<img src="${u.photoUrl}" alt="${u.name}" />`;
      } else {
        circle.textContent = (u.name || 'I').charAt(0).toUpperCase();
      }

      // Avatar — topbar
      const topInner = document.getElementById('topbarAvatarInner');
      if (u.photoUrl) {
        topInner.innerHTML = `<img src="${u.photoUrl}" alt="${u.name}" style="width:100%;height:100%;object-fit:cover;border-radius:50%;" />`;
      } else {
        topInner.textContent = (u.name || 'I').charAt(0).toUpperCase();
      }

      // Photo upload button — only show if user has a staffId
      const photoEditBtn = document.getElementById('profileAvatarEditBtn');
      if (u.staffId) {
        photoEditBtn.style.display = '';
      }
    } catch (err) {
      console.error('Failed to load profile:', err);
    }
  }

  // ── Save Name ─────────────────────────────────────────────
  document.getElementById('profileNameSaveBtn')?.addEventListener('click', async () => {
    const nameInput = document.getElementById('profileNameInput');
    const msg = document.getElementById('profileNameMsg');
    const name = nameInput.value.trim();
    if (!name) { msg.className = 'profile-msg error'; msg.textContent = 'Name is required.'; return; }

    msg.className = 'profile-msg'; msg.textContent = 'Saving…';
    try {
      const r = await fetch(`${API}/api/me/name`, {
        method: 'PUT',
        headers: { 'Authorization': 'Bearer ' + token, 'Content-Type': 'application/json' },
        body: JSON.stringify({ name }),
      });
      if (!r.ok) { const e = await r.json().catch(() => ({})); throw new Error(e.error || 'Failed'); }
      msg.className = 'profile-msg success'; msg.textContent = '✓ Name updated';
      document.getElementById('profileNameDisplay').textContent = name;
      document.getElementById('topbarAvatarInner').textContent = name.charAt(0).toUpperCase();
      setTimeout(() => { msg.textContent = ''; }, 2000);
    } catch (err) {
      msg.className = 'profile-msg error'; msg.textContent = '✗ ' + err.message;
    }
  });

  // ── Change Password ───────────────────────────────────────
  document.getElementById('pwdChangeBtn')?.addEventListener('click', async () => {
    const current = document.getElementById('pwdCurrent').value;
    const newPwd  = document.getElementById('pwdNew').value;
    const confirm = document.getElementById('pwdConfirm').value;
    const msg     = document.getElementById('pwdMsg');

    if (!current) { msg.className = 'profile-msg error'; msg.textContent = 'Enter current password.'; return; }
    if (newPwd.length < 8) { msg.className = 'profile-msg error'; msg.textContent = 'New password must be at least 8 characters.'; return; }
    if (newPwd !== confirm) { msg.className = 'profile-msg error'; msg.textContent = 'Passwords do not match.'; return; }

    msg.className = 'profile-msg'; msg.textContent = 'Changing…';
    try {
      const r = await fetch(`${API}/api/me/password`, {
        method: 'PUT',
        headers: { 'Authorization': 'Bearer ' + token, 'Content-Type': 'application/json' },
        body: JSON.stringify({ currentPassword: current, newPassword: newPwd }),
      });
      if (!r.ok) { const e = await r.json().catch(() => ({})); throw new Error(e.error || 'Failed'); }
      msg.className = 'profile-msg success'; msg.textContent = '✓ Password changed successfully';
      document.getElementById('pwdCurrent').value = '';
      document.getElementById('pwdNew').value = '';
      document.getElementById('pwdConfirm').value = '';
      setTimeout(() => { msg.textContent = ''; }, 3000);
    } catch (err) {
      msg.className = 'profile-msg error'; msg.textContent = '✗ ' + err.message;
    }
  });

  // ── Photo Upload ──────────────────────────────────────────
  document.getElementById('profilePhotoInput')?.addEventListener('change', async (e) => {
    const file = e.target.files?.[0];
    if (!file || !_profileData?.staffId) return;

    const form = new FormData();
    form.append('file', file);

    try {
      const r = await fetch(`${API}/api/media/instructor-photo/${_profileData.staffId}`, {
        method: 'POST',
        headers: { 'Authorization': 'Bearer ' + token },
        body: form,
      });
      if (!r.ok) { const err = await r.json().catch(() => ({})); throw new Error(err.error || 'Upload failed'); }
      const data = await r.json();
      // Update both avatars
      const circle = document.getElementById('profileAvatarCircle');
      circle.innerHTML = `<img src="${data.url}" alt="Photo" />`;
      const topInner = document.getElementById('topbarAvatarInner');
      topInner.innerHTML = `<img src="${data.url}" alt="Photo" style="width:100%;height:100%;object-fit:cover;border-radius:50%;" />`;
      if (window.showToast) window.showToast('Photo updated', 'success');
    } catch (err) {
      if (window.showToast) window.showToast(err.message, 'error');
    }
  });

  // ══════════════════════════════════════════════════════════════════
  // NOTIFICATIONS TAB — push device management + preferences
  // ══════════════════════════════════════════════════════════════════

  const CATEGORY_LABELS = {
    NewBooking:     'New Booking',
    Cancellation:   'Cancellation',
    Payment:        'Payment Received',
    Reminder:       'Class Reminder',
    SystemAlert:    'System Alert',
    Test:           'Test Notification',
  };

  // ── Push status & device management ───────────────────────────
  async function loadPushStatus() {
    const badge   = document.getElementById('pm_notifStatusBadge');
    const enableB = document.getElementById('pm_notifEnableBtn');
    const disableB= document.getElementById('pm_notifDisableBtn');
    const testB   = document.getElementById('pm_notifTestBtn');
    const msg     = document.getElementById('pm_notifMsg');
    const devList = document.getElementById('pm_notifDeviceList');

    if (!isSupported()) {
      badge.textContent = 'Not supported';
      badge.style.color = 'var(--color-danger)';
      msg.textContent = 'Push notifications are not supported in this browser.';
      return;
    }

    const perm = getPermission();
    const subscribed = await isSubscribedHere();

    if (subscribed) {
      badge.textContent = 'Active';
      badge.style.background = 'var(--color-success)'; badge.style.color = '#fff'; badge.style.borderColor = 'var(--color-success)';
      disableB.style.display = '';
      testB.style.display = '';
    } else if (perm === 'denied') {
      badge.textContent = 'Blocked';
      badge.style.color = 'var(--color-danger)';
      msg.textContent = 'Push is blocked in your browser settings. Please reset permissions.';
    } else {
      badge.textContent = 'Off';
      enableB.style.display = '';
    }

    enableB.addEventListener('click', async () => {
      enableB.disabled = true; msg.textContent = 'Requesting permission…';
      try {
        await enable(API, token);
        msg.textContent = ''; loadPushStatus();
      } catch (err) { msg.textContent = err.message; }
      enableB.disabled = false;
    });

    disableB.addEventListener('click', async () => {
      disableB.disabled = true;
      try {
        await disable(API, token);
        loadPushStatus();
      } catch (err) { msg.textContent = err.message; }
      disableB.disabled = false;
    });

    testB.addEventListener('click', async () => {
      testB.disabled = true;
      try { await sendTest(API, token); msg.textContent = '✓ Test sent'; setTimeout(() => msg.textContent = '', 2000); }
      catch (err) { msg.textContent = err.message; }
      testB.disabled = false;
    });

    try {
      const devices = await listMyDevices(API, token);
      if (!devices || devices.length === 0) {
        devList.innerHTML = '<li style="color:var(--color-text-muted);font-size:12px;">No devices registered yet.</li>';
      } else {
        devList.innerHTML = devices.map(d => `
          <li style="font-size:12px;padding:4px 8px;background:var(--color-surface-raised);border-radius:var(--radius-sm);border:1px solid var(--color-border-subtle);display:flex;justify-content:space-between;align-items:center;">
            <span>${d.userAgent ? d.userAgent.substring(0, 40) + '…' : 'Unknown device'}</span>
            <span style="font-size:10px;color:var(--color-text-muted);">${d.createdAt ? new Date(d.createdAt).toLocaleDateString() : ''}</span>
          </li>
        `).join('');
      }
    } catch { devList.innerHTML = '<li style="color:var(--color-text-muted);font-size:12px;">Could not load devices.</li>'; }
  }

  // ── Notification preferences ──────────────────────────────────
  async function loadPreferences() {
    const prefCatList = document.getElementById('pm_prefCategoryList');
    try {
      const res = await fetch(`${API}/api/push/preferences`, {
        headers: { 'Authorization': 'Bearer ' + token },
      });
      if (!res.ok) { prefCatList.innerHTML = '<div style="color:var(--color-danger);font-size:12px;">Failed to load.</div>'; return; }
      const prefs = await res.json();

      document.getElementById('pm_prefMasterToggle').checked = prefs.enabled;
      document.getElementById('pm_prefEmailFallback').checked = prefs.emailFallbackEnabled;

      const overrides = prefs.categoryOverrides || {};
      let html = '';
      for (const [cat, label] of Object.entries(CATEGORY_LABELS)) {
        if (cat === 'Test') continue;
        const isOn = cat in overrides ? overrides[cat] : true;
        html += `
          <label style="display:flex;align-items:center;gap:8px;cursor:pointer;padding:5px 8px;border:1px solid var(--color-border-subtle);border-radius:var(--radius-sm);background:var(--color-surface-raised);font-size:12px;">
            <input type="checkbox" ${isOn ? 'checked' : ''} data-pm-pref-cat="${cat}" class="pm-pref-cat-toggle" />
            <span>${label}</span>
          </label>
        `;
      }
      prefCatList.innerHTML = html;
    } catch (err) {
      prefCatList.innerHTML = `<div style="color:var(--color-danger);font-size:12px;">${err.message}</div>`;
    }
  }

  document.getElementById('pm_prefSaveBtn')?.addEventListener('click', async () => {
    const btn = document.getElementById('pm_prefSaveBtn');
    const msg = document.getElementById('pm_prefSaveMsg');
    btn.disabled = true; msg.textContent = 'Saving…'; msg.style.color = 'var(--color-text-muted)';

    try {
      const categoryOverrides = {};
      document.querySelectorAll('.pm-pref-cat-toggle').forEach(cb => {
        categoryOverrides[cb.dataset.pmPrefCat] = cb.checked;
      });

      const r = await fetch(`${API}/api/push/preferences`, {
        method: 'PUT',
        headers: { 'Authorization': 'Bearer ' + token, 'Content-Type': 'application/json' },
        body: JSON.stringify({
          enabled: document.getElementById('pm_prefMasterToggle').checked,
          emailFallbackEnabled: document.getElementById('pm_prefEmailFallback').checked,
          categoryOverrides,
        }),
      });
      if (!r.ok) throw new Error('Save failed');
      msg.textContent = '✓ Saved'; msg.style.color = 'var(--color-success)';
      setTimeout(() => { msg.textContent = ''; }, 2000);
    } catch {
      msg.textContent = '✗ Failed'; msg.style.color = 'var(--color-danger)';
    } finally {
      btn.disabled = false;
    }
  });
</script>

