file.content:
function startOfDay(date) {
  const d = new Date(date);
  d.setHours(0, 0, 0, 0);
  return d;
}

function addDays(date, days) {
  const d = new Date(date);
  d.setDate(d.getDate() + days);
  return d;
}

function isSameDay(a, b) {
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

function toInputDate(date) {
  // "YYYY-MM-DD"
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, "0");
  const d = String(date.getDate()).padStart(2, "0");
  return `${y}-${m}-${d}`;
}

function friendlyDate(date) {
  const loc = getLocale() === "vi" ? "vi-VN" : "en-US";
  const today = startOfDay(new Date());
  if (isSameDay(date, today)) return "Today";
  if (isSameDay(date, addDays(today, 1))) return "Tomorrow";
  return date.toLocaleDateString(loc, {
    weekday: "short",
    month: "short",
    day: "numeric",
  });
}

// ── Date Scroller ──
function initDateScroller() {
  renderDateChips();
  selectDateChip(selectedDate);
}

function renderDateChips() {
  const track = document.getElementById('dateScrollerTrack');
  const today = startOfDay(new Date());
  const loc = getLocale() === 'vi' ? 'vi-VN' : 'en-US';
  let html = '';

  for (let i = 0; i < dateChipCount; i++) {
    const d = addDays(today, i);
    const isToday = i === 0;
    const isSelected = isSameDay(d, selectedDate);
    const weekday = isToday
      ? (getLocale() === 'vi' ? 'HÔM NAY' : 'TODAY')
      : d.toLocaleDateString(loc, { weekday: 'short' }).toUpperCase();
    const dayNum = d.getDate();
    const month = d.toLocaleDateString(loc, { month: 'short' });
    const dateKey = toInputDate(d);

    html += `
      <button class="sp-date-chip${isSelected ? ' selected' : ''}${isToday ? ' today' : ''}"
              data-date="${dateKey}" type="button"
              aria-label="${d.toLocaleDateString(loc, { weekday: 'long', month: 'long', day: 'numeric' })}">
        <span class="sp-date-chip-weekday">${escapeHtml(weekday)}</span>
        <span class="sp-date-chip-day">${dayNum}</span>
        <span class="sp-date-chip-month">${escapeHtml(month)}</span>
        ${isToday ? '<span class="sp-date-chip-dot"></span>' : ''}
      </button>`;
  }

  // "Load more" chip (if not at max)
  if (dateChipCount < DATE_CHIP_MAX) {
    html += `
      <button class="sp-date-chip sp-date-chip-more" type="button" id="loadMoreDatesBtn"
              aria-label="Load more dates">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:20px;height:20px;">

