function renderClasses() {
  const list = document.getElementById("classList");
  document.getElementById("classSkeleton").style.display = "none";

  // SPM-77: stop any auto-play timers from the previous render before the
  // old card DOM is replaced, so setInterval handles never leak.
  _cardGalleryTimers.forEach((id) => clearInterval(id));
  _cardGalleryTimers = [];

  const now = new Date();
  const isToday = isSameDay(selectedDate, now);

  const filtered = allSessions.filter((s) => {
    // Hide classes that have already started when browsing today's schedule
    if (isToday && new Date(s.startTime) < now) return false;

    if (activeLevel !== "all" && s.difficultyLevel !== activeLevel)
      return false;
    if (activeEquipment) {
      // SPM-71 — a class matches if ANY of its equipment matches the pill.
      // Flexible match: compare by name (case-insensitive). Old sessions only
      // have the singular equipmentType, which sessionEquipmentList() treats
      // as a single-element list.
      const filterEquip = activeEquipment.toLowerCase();
      const matches = sessionEquipmentList(s).some(
        (name) => (name || '').toLowerCase() === filterEquip,
      );
      if (!matches) return false;
    }
    if (activeInstructor !== "all" && s.instructorName !== activeInstructor)
      return false;
    return true;
  });

  if (filtered.length === 0) {
    list.innerHTML = "";
    document.getElementById("emptyState").style.display = "block";
    return;
  }
  document.getElementById("emptyState").style.display = "none";

  // Group by calendar day
  const grouped = {};
  filtered.forEach((s) => {
    const d = new Date(s.startTime);
    const key = `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;
    if (!grouped[key]) grouped[key] = { date: d, sessions: [] };
    grouped[key].sessions.push(s);
  });

  const loc = getLocale() === "vi" ? "vi-VN" : "en-US";
  const today = startOfDay(new Date());

  let html = "";
  Object.values(grouped)
    .sort((a, b) => a.date - b.date)
    .forEach((group) => {
      const isToday = isSameDay(group.date, today);
      const isTomorrow = isSameDay(group.date, addDays(today, 1));
      const longLabel = group.date.toLocaleDateString(loc, {

