// ─── Push client helper ───────────────────────────────────────────────────
//
// Shared module for any admin page that wants to enable / manage push.
// Used today by `settings.astro`'s Notifications tab; designed so future
// surfaces (e.g. an in-app "enable notifications" nudge) can import it.
//
// API surface:
//   isSupported()           — feature-detect SW + PushManager + Notification
//   getPermission()         — current value of Notification.permission
//   isSubscribedHere()      — does THIS browser have an active subscription?
//   enable(API, token)      — request permission + subscribe; returns the sub
//   disable(API, token)     — unsubscribe + delete server-side
//   listMyDevices(API, t)   — fetch all devices linked to this user
//   sendTest(API, token)    — backend ping to all of my devices
//
// All network calls expect (API, token) so the helper works for both admin
// and instructor surfaces — neither owns its own auth context.

/**
 * Base64url string → Uint8Array. The Push API's applicationServerKey
 * parameter wants the raw bytes, but VAPID public keys travel as base64url
 * (URL-safe + no padding) so we have to decode in the browser.
 */
function urlBase64ToUint8Array(base64String) {
  const padding = "=".repeat((4 - (base64String.length % 4)) % 4);
  const base64 = (base64String + padding).replace(/-/g, "+").replace(/_/g, "/");
  const raw = atob(base64);
  const out = new Uint8Array(raw.length);
  for (let i = 0; i < raw.length; ++i) out[i] = raw.charCodeAt(i);
  return out;
}

export function isSupported() {
  return (
    typeof window !== "undefined" &&
    "serviceWorker" in navigator &&
    "PushManager" in window &&
    "Notification" in window
  );
}

export function getPermission() {
  return typeof Notification !== "undefined" ? Notification.permission : "default";
}

/**
 * Returns the PushSubscription registered with THIS browser, or null.
 * Note this only reflects the local browser state — there could be other
 * devices subscribed under the same user (see listMyDevices for that).
 */

