if (!isSupported()) {
  const ua = navigator.userAgent;
  const isIOS = /iPhone|iPad|iPod/.test(ua);
  const isStandalone = window.matchMedia('(display-mode: standalone)').matches || navigator.standalone === true;
  badge.textContent = 'Not available';
  badge.style.color = 'var(--color-text-muted)';
  if (isIOS && !isStandalone) {
    msg.innerHTML = 'Push notifications require the app to be installed.<br>Tap <strong>Install App</strong> above, add it to your home screen, then open the installed app to enable notifications.';
  } else if (isIOS) {
    msg.textContent = 'Push notifications require iOS 16.4 or later. Please update your iPhone and try again.';
  } else {
    msg.textContent = 'Push notifications are not supported in this browser.';
  }
  return;
}

