// ─── Push client helper ───────────────────────────────────────────────────
//
// Shared module for any admin page that wants to enable / manage push.
// Used today by `settings.astro`'s Notifications tab; designed so future
// surfaces (e.g. an in-app "enable notifications" nudge) can import it.
//
// API surface:
//   isSupported()           — feature-detect SW + PushManager + Notification
//   getPermission()         — current value of Notification.permission
//   isSubscribedHere()      — does THIS browser have an active subscription?
//   enable(API, token)      — request permission + subscribe; returns the sub
//   disable(API, token)     — unsubscribe + delete server-side
//   listMyDevices(API, t)   — fetch all devices linked to this user
//   sendTest(API, token)    — backend ping to all of my devices
//
// All network calls expect (API, token) so the helper works for both admin
// and instructor surfaces — neither owns its own auth context.

/**
 * Base64url string → Uint8Array. The Push API's applicationServerKey
 * parameter wants the raw bytes, but VAPID public keys travel as base64url
 * (URL-safe + no padding) so we have to decode in the browser.
 */
function urlBase64ToUint8Array(base64String) {
  const padding = "=".repeat((4 - (base64String.length % 4)) % 4);
  const base64 = (base64String + padding).replace(/-/g, "+").replace(/_/g, "/");
  const raw = atob(base64);
  const out = new Uint8Array(raw.length);
  for (let i = 0; i < raw.length; ++i) out[i] = raw.charCodeAt(i);
  return out;
}

export function isSupported() {
  return (
    typeof window !== "undefined" &&
    "serviceWorker" in navigator &&
    "PushManager" in window &&
    "Notification" in window
  );
}

export function getPermission() {
  return typeof Notification !== "undefined" ? Notification.permission : "default";
}

/**
 * Returns the PushSubscription registered with THIS browser, or null.
 * Note this only reflects the local browser state — there could be other
 * devices subscribed under the same user (see listMyDevices for that).
 */
export async function getLocalSubscription() {
  if (!isSupported()) return null;
  const reg = await navigator.serviceWorker.ready;
  return reg.pushManager.getSubscription();
}

export async function isSubscribedHere() {
  return (await getLocalSubscription()) !== null;
}

export async function enable(API, token) {
  if (!isSupported()) throw new Error("Push notifications aren't supported in this browser.");

  // 1. Ask the OS for permission. If it was already 'denied', the browser
  //    won't re-prompt — surface a useful error so the UI can guide the user
  //    to their browser settings.
  let perm = Notification.permission;
  if (perm === "default") perm = await Notification.requestPermission();
  if (perm !== "granted") {
    throw new Error("Permission denied. Enable notifications in your browser settings to continue.");
  }

  // 2. Pull the VAPID public key. The SW + PushManager need it to register
  //    the subscription with the upstream push service (FCM/Mozilla/etc).
  const keyRes = await fetch(`${API}/api/push/vapid-public-key`);
  if (!keyRes.ok) throw new Error("Failed to fetch VAPID public key.");
  const { publicKey } = await keyRes.json();
  if (!publicKey) throw new Error("Push is not configured on the server (missing VAPID key).");

  // 3. Register with the upstream service via the SW's PushManager.
  const reg = await navigator.serviceWorker.ready;
  // If a subscription already exists for an old key, drop it and re-subscribe;
  // mixing applicationServerKeys throws InvalidStateError on Chromium.
  const existing = await reg.pushManager.getSubscription();
  if (existing) {
    try { await existing.unsubscribe(); } catch { /* best-effort */ }
  }
  const sub = await reg.pushManager.subscribe({
    userVisibleOnly: true,
    applicationServerKey: urlBase64ToUint8Array(publicKey),
  });

  // 4. Hand the subscription to the backend so it can be used for fan-out.
  const body = sub.toJSON();
  const r = await fetch(`${API}/api/push/subscribe`, {
    method: "POST",
    headers: { "Content-Type": "application/json", Authorization: "Bearer " + token },
    body: JSON.stringify({ endpoint: body.endpoint, keys: body.keys }),
  });
  if (!r.ok) {
    // Clean up the orphan browser subscription on failure so the user can retry.
    try { await sub.unsubscribe(); } catch { /* best-effort */ }
    throw new Error("Failed to register subscription with the server.");
  }
  return sub;
}

export async function disable(API, token) {
  const sub = await getLocalSubscription();
  if (!sub) return; // nothing to do
  // Tell the backend first so a failed unsubscribe at the browser doesn't
  // leave a dead record on the server (the dispatcher would eventually
  // prune it via 410 anyway, but explicit is better).
  await fetch(`${API}/api/push/subscribe`, {
    method: "DELETE",
    headers: { "Content-Type": "application/json", Authorization: "Bearer " + token },
    body: JSON.stringify({ endpoint: sub.endpoint }),
  }).catch(() => {});
  try { await sub.unsubscribe(); } catch { /* best-effort */ }
}

export async function listMyDevices(API, token) {
  const r = await fetch(`${API}/api/push/devices`, {
    headers: { Authorization: "Bearer " + token },
  });
  if (!r.ok) return [];
  return r.json();
}

export async function sendTest(API, token) {
  const r = await fetch(`${API}/api/push/test`, {
    method: "POST",
    headers: { Authorization: "Bearer " + token },
  });
  if (!r.ok) throw new Error("Failed to queue test notification.");
  return r.json();
}

