# ═══════════════════════════════════════════════════════════════════════════
#  Soul Pilates — VestaCP Nginx Reverse Proxy Template
#  Domain: soulpilates.com.vn
#
#  Paste this into VestaCP's nginx template for the soulpilates.com.vn domain.
#  VestaCP handles TLS termination (Let's Encrypt) — this block runs
#  inside the `server { }` context that VestaCP generates.
#
#  Port mapping (docker-compose.prod.yml):
#    Frontend (Astro/nginx): host :3719  → container :80
#    Backend  (.NET API):    host :8391  → container :8080
#    RustFS   (S3 storage):  host :9000  → container :9000
# ═══════════════════════════════════════════════════════════════════════════

# ── API: /api/* → backend container ──
location /api/ {
    proxy_pass          http://127.0.0.1:8391;
    proxy_http_version  1.1;
    proxy_set_header    Host $host;
    proxy_set_header    X-Real-IP $remote_addr;
    proxy_set_header    X-Forwarded-For $proxy_add_x_forwarded_for;
    proxy_set_header    X-Forwarded-Proto $scheme;

    # WebSocket support for SignalR
    proxy_set_header    Upgrade $http_upgrade;
    proxy_set_header    Connection "upgrade";

    # Large file uploads (images, etc.)
    client_max_body_size 15M;

    # Timeouts — SignalR long-poll can hold connections
    proxy_read_timeout  120s;
    proxy_send_timeout  120s;
}

# ── SignalR hub — explicit block to ensure WebSocket upgrade ──
location /hubs/ {
    proxy_pass          http://127.0.0.1:8391;
    proxy_http_version  1.1;
    proxy_set_header    Host $host;
    proxy_set_header    X-Real-IP $remote_addr;
    proxy_set_header    X-Forwarded-For $proxy_add_x_forwarded_for;
    proxy_set_header    X-Forwarded-Proto $scheme;
    proxy_set_header    Upgrade $http_upgrade;
    proxy_set_header    Connection "upgrade";
    proxy_read_timeout  3600s;
    proxy_send_timeout  3600s;
}

# ── Public media: /soulpilates-public/* → RustFS S3 (read-only) ──
location /soulpilates-public/ {
    proxy_pass          http://127.0.0.1:9000;
    proxy_http_version  1.1;
    proxy_set_header    Host $host;
    proxy_set_header    X-Real-IP $remote_addr;
    proxy_set_header    X-Forwarded-For $proxy_add_x_forwarded_for;
    proxy_set_header    X-Forwarded-Proto $scheme;

    # Long cache for immutable media assets
    expires             7d;
    add_header          Cache-Control "public, immutable";
}

# ── Stripe webhook (needs raw body — no buffering) ──
location = /api/webhooks/stripe {
    proxy_pass          http://127.0.0.1:8391;
    proxy_http_version  1.1;
    proxy_set_header    Host $host;
    proxy_set_header    X-Real-IP $remote_addr;
    proxy_set_header    X-Forwarded-For $proxy_add_x_forwarded_for;
    proxy_set_header    X-Forwarded-Proto $scheme;
    proxy_buffering     off;
    client_max_body_size 1M;
}

# ── Frontend: everything else → Astro static SPA ──
location / {
    proxy_pass          http://127.0.0.1:3719;
    proxy_http_version  1.1;
    proxy_set_header    Host $host;
    proxy_set_header    X-Real-IP $remote_addr;
    proxy_set_header    X-Forwarded-For $proxy_add_x_forwarded_for;
    proxy_set_header    X-Forwarded-Proto $scheme;
}

# ── Security headers (VestaCP may add its own — merge as needed) ──
add_header X-Content-Type-Options  nosniff always;
add_header X-Frame-Options         SAMEORIGIN always;
add_header Referrer-Policy         strict-origin-when-cross-origin always;
add_header X-XSS-Protection        "1; mode=block" always;

