async function doLogin(ev) {
  if (ev) ev.preventDefault();
  const email = document.getElementById("email").value.trim();
  const password = document.getElementById("password").value;
  const errEl = document.getElementById("errorMsg");
  const btn = document.getElementById("loginBtn");
  const lbl = document.getElementById("btnLabel");
  errEl.style.display = "none";
  lbl.textContent = "Signing in…";
  btn.disabled = true;

  try {
    const res = await fetch(
      import.meta.env.PUBLIC_API_URL + "/api/auth/login",
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password }),
      },
    );
    if (!res.ok) throw new Error();
    const data = await res.json();
    localStorage.setItem("token", data.token);
    if (data.staffId) localStorage.setItem("staffId", data.staffId);
    // Force password change before reaching the dashboard.
    if (data.mustChangePassword) {
      window.location.href = "/admin/change-password";
      return;
    }
    // P3-S09: role-aware post-login redirect.
    // Instructor → instructor portal; Admin, Receptionist, Accountant → admin dashboard
    const role = (data.userRole || "").toLowerCase();
    window.location.href =
      role === "instructor" ? "/instructor" : "/admin";
  } catch {
    errEl.textContent = "Invalid email or password. Please try again.";
    errEl.style.display = "block";
    lbl.textContent = "Sign in";
    btn.disabled = false;
  }
}

