// ─── Soul Pilates service worker ───────────────────────────────────────────
//
// Responsibilities:
//   1. **App shell caching** so the dashboard opens instantly on subsequent
//      visits and survives flaky connectivity at the studio.
//   2. **Network-first for /api/**** with a *short* timeout fallback to cache,
//      so the operator sees the freshest data when online but still gets a
//      useful page when the API is unreachable.
//   3. **Push notifications** (Slice B will populate these handlers). For now
//      a no-op stub is registered so the SW upgrade path doesn't need a hard
//      reload once we wire push.
//   4. **Versioned cache cleanup** on activate.
//
// IMPORTANT: bump SW_VERSION any time the precache list or any of the
// hand-listed assets change. Clients on the old SW will spot the new file,
// install it, then receive a "Refresh to update" toast from the registration
// script.
//
// Note: in dev mode (`astro dev`), this file is served from `/sw.js` like any
// other static asset; Astro doesn't bundle/transform service workers. We keep
// the code dependency-free so the global `caches`, `fetch`, `clients` APIs
// can be reasoned about directly.

const SW_VERSION = "v1.0.2";
const SHELL_CACHE = `soulpilates-shell-${SW_VERSION}`;
const RUNTIME_CACHE = `soulpilates-runtime-${SW_VERSION}`;

// Precache list: only assets that are universally needed for the shell to
// paint. Pages themselves are runtime-cached on first visit (stale-while-
// revalidate strategy) — keeps this list maintainable as the app grows.
const SHELL_ASSETS = [
  "/manifest.webmanifest",
  "/icons/icon-192.png",
  "/icons/icon-512.png",
  "/favicon.svg",
  "/favicon.ico",
];

// ── Install ──────────────────────────────────────────────────────────────
self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(SHELL_CACHE);
      // `addAll` is atomic — if any asset 404s the whole install fails and
      // the new SW won't take over. That's the behaviour we want; partial
      // shells are worse than the old one.
      await cache.addAll(SHELL_ASSETS);
      // Activate immediately on first install so the user gets the new SW
      // without needing to close every tab.
      await self.skipWaiting();
    })()
  );
});

// ── Activate ─────────────────────────────────────────────────────────────
self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      // Drop caches from older SW_VERSIONs.
      const keys = await caches.keys();
      await Promise.all(
        keys
          .filter((k) => k.startsWith("soulpilates-") && !k.endsWith(SW_VERSION))
          .map((k) => caches.delete(k))
      );
      await self.clients.claim();
    })()
  );
});

// ── Fetch ────────────────────────────────────────────────────────────────
//
// Strategy decision tree:
//
//   /api/**  ─── network-first, 3s timeout, cache fallback (read-only GETs only)
//   navigations (mode === 'navigate') ─── network-first, cache fallback
//   everything else (static asset, /src/, /node_modules/, image, font) ─── SWR
//
// Non-GET requests are NEVER intercepted — there's no point caching a POST,
// and we don't want to risk replaying a write from a stale offline state.
self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;

  const url = new URL(req.url);

  // Only handle same-origin requests; cross-origin (Google Fonts, S3 images
  // etc.) get their own browser-default cache behaviour.
  if (url.origin !== self.location.origin) return;

  // Skip dev-mode HMR, Vite internals, and source files.
  if (
    url.pathname.startsWith("/@vite/") ||
    url.pathname.startsWith("/@id/") ||
    url.pathname.startsWith("/@fs/") ||
    url.pathname.startsWith("/src/") ||
    url.pathname.startsWith("/node_modules/")
  ) {
    return;
  }

  // ── API: network-first with 3s timeout ──────────────────────────────
  if (url.pathname.startsWith("/api/")) {
    event.respondWith(networkFirstWithTimeout(req, 3000));
    return;
  }

  // ── Navigations (HTML documents): network-first with cache fallback ──
  if (req.mode === "navigate") {
    event.respondWith(navigationHandler(req));
    return;
  }

  // ── Everything else: stale-while-revalidate ──────────────────────────
  event.respondWith(staleWhileRevalidate(req));
});

async function networkFirstWithTimeout(req, timeoutMs) {
  const cache = await caches.open(RUNTIME_CACHE);
  try {
    const response = await Promise.race([
      fetch(req),
      new Promise((_, reject) =>
        setTimeout(() => reject(new Error("timeout")), timeoutMs)
      ),
    ]);
    // Only cache successful, opaque-safe responses to avoid poisoning the
    // cache with auth-rejected 401s or empty 5xxs.
    if (response.ok) cache.put(req, response.clone());
    return response;
  } catch {
    const cached = await cache.match(req);
    if (cached) return cached;
    // Final fallback: return a synthetic offline JSON so the SPA can show a
    // friendly "you're offline" toast instead of a hard fetch error.
    return new Response(
      JSON.stringify({
        error: "offline",
        message: "You're offline. Please reconnect and try again.",
      }),
      { status: 503, headers: { "Content-Type": "application/json" } }
    );
  }
}

async function navigationHandler(req) {
  const cache = await caches.open(RUNTIME_CACHE);
  try {
    const response = await fetch(req);
    if (response.ok) cache.put(req, response.clone());
    return response;
  } catch {
    const cached = await cache.match(req);
    if (cached) return cached;
    // Last resort: app-shell index page so the SPA can render its own
    // offline state. We prefer /admin/ over / since admin is the primary
    // surface and unauthenticated /login redirects from there anyway.
    return (
      (await cache.match("/admin/")) ||
      new Response("<h1>Offline</h1>", {
        status: 503,
        headers: { "Content-Type": "text/html" },
      })
    );
  }
}

async function staleWhileRevalidate(req) {
  const cache = await caches.open(RUNTIME_CACHE);
  const cached = await cache.match(req);
  const fetchPromise = fetch(req)
    .then((response) => {
      if (response.ok) cache.put(req, response.clone());
      return response;
    })
    .catch(() => cached);
  return cached || fetchPromise;
}

// ── Push (Slice B will populate; stub now to avoid an SW reload later) ──
self.addEventListener("push", (event) => {
  if (!event.data) return;
  let payload;
  try {
    payload = event.data.json();
  } catch {
    payload = { title: "Soul Pilates", body: event.data.text() };
  }
  const {
    title = "Soul Pilates",
    body = "",
    icon = "/icons/icon-192.png",
    badge = "/icons/icon-192.png",
    url = "/admin/",
    tag,
  } = payload;
  event.waitUntil(
    self.registration.showNotification(title, {
      body,
      icon,
      badge,
      tag, // collapses duplicate pings for the same entity (e.g. same booking)
      data: { url },
      requireInteraction: false,
    })
  );
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const targetUrl = (event.notification.data && event.notification.data.url) || "/admin/";
  event.waitUntil(
    (async () => {
      const all = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
      // If a tab is already open at the right origin, focus + navigate it.
      for (const client of all) {
        if (client.url.includes(self.location.origin)) {
          await client.focus();
          if ("navigate" in client) await client.navigate(targetUrl);
          return;
        }
      }
      // Otherwise open a fresh window.
      await self.clients.openWindow(targetUrl);
    })()
  );
});

// ── Allow the page to ask the SW to skip waiting (for "Refresh to update") ─
self.addEventListener("message", (event) => {
  if (event.data && event.data.type === "SKIP_WAITING") {
    self.skipWaiting();
  }
});

