self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      // Drop caches from older SW_VERSIONs.
      const keys = await caches.keys();
      await Promise.all(
        keys
          .filter((k) => k.startsWith("soulpilates-") && !k.endsWith(SW_VERSION))
          .map((k) => caches.delete(k))
      );
