[HttpPost("subscribe")]
public async Task<IActionResult> Subscribe([FromBody] SubscribePushRequest request)
{
    var userId = CurrentUserId();
    if (userId is null) return Unauthorized();
    var userAgent = Request.Headers.UserAgent.ToString();
    var sub = await _push.SubscribeAsync(userId, request, string.IsNullOrWhiteSpace(userAgent) ? null : userAgent);
    return Ok(new { id = sub.Id });
}

/// <summary>Drop a subscription (called by "remove device" in settings).</summary>
[HttpDelete("subscribe")]
public async Task<IActionResult> Unsubscribe([FromBody] UnsubscribeRequest request)
{
    var userId = CurrentUserId();
    if (userId is null) return Unauthorized();
    if (string.IsNullOrWhiteSpace(request.Endpoint))
        return BadRequest(new { message = "Endpoint is required." });
    await _push.UnsubscribeAsync(userId, request.Endpoint);
    return NoContent();
}

