        <span>${_posEsc(s.instructorName || '—')}</span>
        <span>${s.currentBookings ?? 0}/${s.capacity ?? '?'}</span>
      </div>
    `;

    ev.addEventListener('click', e => {
      e.stopPropagation();
      _showPosSessionPopup(e, s);
    });
