  let voucherPartners = {}; // id -> businessName
  // P3-S12: applied promo code (validated by /api/promotions/preview).
  let appliedPromo = null; // { promotionId, code, discount, label }
  // ── Package credit state ──
  let _clientPackages = [];  // full package objects from /api/wallet/client/{id}
  let _clientGroupCredits = 0;
  let _clientMatCredits = 0;
  let _clientPrivateCredits = 0;

  // Load B2B partners for referee dropdown
  fetch(`${API}/api/partner`, {
    headers: { Authorization: "Bearer " + token },
  })
    .then((r) => r.json())
    .then((data) => {
      const sel = document.getElementById("refereeSelect");
      (data || []).filter(p => p.status === 'ACTIVE').forEach(
        (p) => (sel.innerHTML += `<option value="${p.id}">${escapeOpt(p.businessName)}</option>`),
      );
    })
    .catch(() => {});

  // P1-S12: Load active voucher batches + partner names so we can label each option.
  Promise.all([
    fetch(`${API}/api/voucher-batches/active`, {
      headers: { Authorization: "Bearer " + token },
    }).then((r) => (r.ok ? r.json() : [])),
    fetch(`${API}/api/partner`, {
      headers: { Authorization: "Bearer " + token },
    }).then((r) => (r.ok ? r.json() : [])),
  ])
    .then(([batches, partners]) => {
      activeVoucherBatches = batches || [];
      voucherPartners = Object.fromEntries(
        (partners || []).map((p) => [p.id, p.businessName]),
      );
      const sel = document.getElementById("voucherSelect");
      activeVoucherBatches.forEach((b) => {
        const remaining = b.quantity - b.redeemedCount;
        const partnerName = voucherPartners[b.partnerId] || "(partner)";
        const valueLabel = formatVoucherValue(b);
        sel.innerHTML += `<option value="${b.id}">${escapeOpt(partnerName)} · ${b.voucherType}${valueLabel} · ${remaining} left</option>`;
      });
    })
    .catch(() => {});

  function escapeOpt(s) {
    return String(s ?? "").replace(
      /[<>&"]/g,
      (c) => ({ "<": "&lt;", ">": "&gt;", "&": "&amp;", '"': "&quot;" })[c],
    );
  }
  function formatVoucherValue(b) {
    if (b.voucherType === "PERCENT_OFF") return ` ${b.value}%`;
    if (b.voucherType === "FIXED_OFF") return ` -${b.value.toLocaleString()}₫`;
    return "";
  }

  function filterPOS(type) {
    filterType = type;
    document.querySelectorAll("#posTabs .pos-tab").forEach((b) => {
      const isMatch = b.dataset.type === type;
      b.classList.toggle("btn-secondary", isMatch);
      b.classList.toggle("btn-ghost", !isMatch);
    });
    // Toggle between product grid and calendar view
    const calView = document.getElementById('posCalendarView');
    const prodGrid = document.getElementById('productGrid');
    if (type === 'CLASS') {
      prodGrid.style.display = 'none';
      calView.classList.add('active');
      if (!_posCalLoaded) { _posCalLoaded = true; initPosCalendar(); }
      else renderPosCalendar();
    } else {
      calView.classList.remove('active');
      prodGrid.style.display = '';
      renderProductGrid();
    }
  }

