  function renderProductGrid() {
    const list = allProducts.filter(matchesFilter);
    document.getElementById("productGrid").innerHTML = list
      .map((p) => {
        const badge = p.credits
          ? `<div style="font-size:11px;color:var(--color-text-muted);margin-top:3px;">${p.credits} credits</div>`
          : "";
        const icon = productIconSvg(p.iconKey || defaultProductIcon(p.type));
        return `
      <div class="product-tile" onclick='addToCart(${JSON.stringify(p)})'>
        <div class="product-tile-icon">${icon}</div>
        <div class="product-tile-name">${p.name}</div>
        <div class="product-tile-price">${(p.basePrice ?? 0).toLocaleString()} ₫</div>
        ${badge}
      </div>`;
      })
      .join("");
  }

  /**
   * Add a product to the cart, keeping studio-rental items inside the
   * dedicated sale mode so they bill against the linked freelance profile.
   * CLASS products open the session picker modal instead of adding directly.
   */
  function addToCart(p) {
    const isStudioRentalProduct = p.type === "FREELANCE_PACKAGE" || p.type === "FREELANCE_SINGLE";
    if (isStudioRentalProduct && saleMode !== "STUDIO_RENTAL") {
      window.showToast && window.showToast("Switch to Studio Rental Sale to sell rental products.", "warning");
      return;
    }
    if (!isStudioRentalProduct && saleMode === "STUDIO_RENTAL") {
      window.showToast && window.showToast("Studio rental checkout only supports studio rental products.", "warning");
      return;
    }
    if (p.type === "MERCHANDISE") {
      // P3-S14: defer the add to the variant picker. Tile click only opens the
      // modal; the actual cart push happens in addVariantToCart() below.
      openVariantPicker(p);
      return;
    }
    const ex = cart.find((c) => (c.lineKey ?? c.id) === p.id);
    if (ex) ex.qty++;
    else
      cart.push({ ...p, lineKey: p.id, unitPrice: p.basePrice ?? 0, qty: 1 });
    renderCart();
  }

