content.content:
  .pos-cal-ev.client-match {
    box-shadow: 0 0 0 1.5px var(--color-brand-accent), 0 0 8px rgba(201,123,75,0.4);
    z-index: 2;
  }
  .pos-cal-ev.client-match.unpaid {
    box-shadow: 0 0 0 1.5px var(--color-warning), 0 0 12px rgba(245,158,11,0.5);
    animation: pos-unpaid-pulse 2s ease-in-out infinite;
  }
  @keyframes pos-unpaid-pulse {
    0%, 100% { box-shadow: 0 0 0 1.5px var(--color-warning), 0 0 12px rgba(245,158,11,0.5); }
    50% { box-shadow: 0 0 0 2px var(--color-warning), 0 0 18px rgba(245,158,11,0.7); }
  }
  .pos-cal-ev.full-session { opacity: 0.5; }

  /* Multi pill */
  .pos-cal-multi {
    position: absolute; top: 2px; left: 2px; right: 2px;
    background: var(--color-surface-raised);
    border: 1px solid var(--color-border); border-radius: 4px;
    padding: 3px 6px; font-size: 9px; font-weight: 600;
    color: var(--color-text-primary); cursor: pointer;
    z-index: 2; text-align: center; transition: all 0.12s;
  }
  .pos-cal-multi:hover {
    background: var(--color-brand-accent-soft);
    color: var(--color-brand-accent);
  }

  /* Popup items */
  .pos-popup-session-card {
    padding: 10px 12px; border-radius: 6px;
    border: 1px solid var(--color-border-subtle);
    margin-bottom: 6px; background: var(--color-surface);
  }
  .pos-popup-action-btn {
    display: flex; align-items: center; gap: 8px; width: 100%;
    padding: 8px 10px; border: none; background: none;
    border-radius: 6px; font-size: 12px; font-weight: 500;
    color: var(--color-text-secondary); cursor: pointer;
    font-family: 'Inter', sans-serif; text-align: left;
    transition: all 0.12s;
  }
  .pos-popup-action-btn:hover { background: var(--color-brand-accent-soft); color: var(--color-brand-accent); }
  .pos-popup-action-btn.primary {
    background: var(--color-brand-accent); color: white; font-weight: 600;
  }
  .pos-popup-action-btn.primary:hover { filter: brightness(1.1); }

  /* Unpaid badge on Classes tab */
  .pos-tab-badge {
    display: inline-flex; align-items: center; justify-content: center;
    background: var(--color-warning); color: #000;
    font-size: 9px; font-weight: 700;
    min-width: 16px; height: 16px; border-radius: 8px;
    padding: 0 4px; margin-left: 4px;
  }

  /* ── Floating session popup (cal-floating from calendar.astro) ── */
  .cal-floating {
    position: fixed; z-index: 1050;
    background: var(--color-surface-raised);
    border: 1px solid var(--color-border);
    border-radius: 10px; padding: 6px;
    display: none; min-width: 200px;
    box-shadow: 0 8px 30px rgba(0,0,0,.3), 0 0 0 1px rgba(255,255,255,.04);
    backdrop-filter: blur(12px);
  }
  .cal-floating.open { display: block; animation: posPopIn .15s ease; }
  @keyframes posPopIn {
    from { opacity: 0; transform: translateY(-6px) scale(.96); }
    to   { opacity: 1; transform: translateY(0) scale(1); }
  }
</style>

<script>
  const API = import.meta.env.PUBLIC_API_URL;

