function _drawPosCalGrid() {
  const headers = document.getElementById('posCalHeaders');
  const grid = document.getElementById('posCalGrid');
  const filterInst = document.getElementById('posCalFilter')?.value || '';
  const cols = 7;
  const gtc = `42px repeat(${cols}, 1fr)`;
  headers.style.gridTemplateColumns = gtc;
  grid.style.gridTemplateColumns = gtc;

  // Build set of client-matched session IDs for highlight
  const clientSessionSet = new Set();
  const unpaidSessionSet = new Set();
  _posCalClientBookings.forEach(b => {
    if (b.calendarSessionId) clientSessionSet.add(b.calendarSessionId);
    // A booking is unpaid only when:
    //  • payment method is PAY_AT_STUDIO (or not yet set) — PACKAGE_CREDIT is settled
    //  • no monetary amount has been paid yet
    //  • it is not a free class
    //  • the attendance is in an active state
    if (b.calendarSessionId &&
        b.paymentMethod !== 'PACKAGE_CREDIT' &&
        (b.paymentMethod === 'PAY_AT_STUDIO' || !b.paymentMethod) &&
        (b.amountDueAtStudio ?? 0) > 0 &&
        (!b.amountPaid || b.amountPaid === 0) && !b.isFreeClass &&
        b.status !== 'CANCELLED' && b.status !== 'NO_SHOW' && b.status !== 'LATE_CANCEL') {
      unpaidSessionSet.add(b.calendarSessionId);
    }
  });

  const todayStr = new Date().toDateString();
  headers.innerHTML = '<div></div>' +
    Array.from({ length: cols }, (_, i) => {
      const d = new Date(_posCalWeekStart); d.setDate(d.getDate() + i);
      const isToday = d.toDateString() === todayStr;
      return `<div class="pos-cal-hdr">
        <div class="pos-cal-hdr-wday">${d.toLocaleDateString('en-US', { weekday: 'short' })}</div>
        <div class="pos-cal-hdr-num ${isToday ? 'today' : ''}">${d.getDate()}</div>
      </div>`;
    }).join('');

  // Filter sessions
  const vis = _posCalSessions.filter(s => {
    if (s.status === 'BLOCKED' || s.status === 'CANCELLED') return false;
    if (filterInst && s.instructorId !== filterInst) return false;
    return true;
  });

  grid.innerHTML = '';
  POS_HOURS.forEach(h => {
    const tl = document.createElement('div');
    tl.className = 'pos-cal-time';
    tl.textContent = _posFmtHour(h);
    grid.appendChild(tl);

    for (let d = 0; d < cols; d++) {
      const cell = document.createElement('div');
      cell.className = 'pos-cal-cell';
      const cellDate = new Date(_posCalWeekStart);
      cellDate.setDate(cellDate.getDate() + d);
      cellDate.setHours(h, 0, 0, 0);

      const cellSessions = vis.filter(s => {
        const st = new Date(s.startTime);
        return st.getDate() === cellDate.getDate() &&
          st.getMonth() === cellDate.getMonth() &&
          st.getFullYear() === cellDate.getFullYear() &&
          st.getHours() === h;
      });

      if (cellSessions.length === 1) {
        cell.appendChild(_buildPosEventCard(cellSessions[0], clientSessionSet, unpaidSessionSet));
      } else if (cellSessions.length > 1) {
        // Multi pill
        const pill = document.createElement('div');
        pill.className = 'pos-cal-multi';
        const hasUnpaid = cellSessions.some(s => unpaidSessionSet.has(s.id));
        if (hasUnpaid) pill.style.borderColor = 'var(--color-warning)';
        pill.textContent = `${cellSessions.length} classes`;
        pill.addEventListener('click', e => {
          e.stopPropagation();
          _showPosMultiPopup(e, cellSessions, clientSessionSet, unpaidSessionSet);
        });
        cell.appendChild(pill);

