// Soul Pilates — service worker v2.0.0
//
// Intentionally minimal: push notifications only.
// All caching is delegated to the browser's native HTTP cache via
// Cache-Control headers set by nginx — no SW cache interception.
// This avoids the fetch-interception overhead that caused freezes on iOS.

const SW_VERSION = "v2.0.0";

// ── Install: take over immediately, no precache ──────────────────────────
self.addEventListener("install", (event) => {
  event.waitUntil(self.skipWaiting());
});

// ── Activate: clean up any old caches from v1.x, claim all clients ───────
self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.map((k) => caches.delete(k)));
      await self.clients.claim();
    })()
  );
});

// ── Push: show a notification ─────────────────────────────────────────────
self.addEventListener("push", (event) => {
  if (!event.data) return;

  let payload;
  try {
    payload = event.data.json();
  } catch {
    payload = { title: "Soul Pilates", body: event.data.text() };
  }

  const {
    title = "Soul Pilates",
    body = "",
    icon = "/icons/icon-192.png",
    badge = "/icons/icon-192.png",
    url = "/admin/",
    tag,
  } = payload;

  event.waitUntil(
    self.registration.showNotification(title, {
      body,
      icon,
      badge,
      tag,
      data: { url },
      requireInteraction: false,
    })
  );
});

// ── Notification click: focus existing window or open a new one ───────────
self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const targetUrl =
    (event.notification.data && event.notification.data.url) || "/admin/";

  event.waitUntil(
    (async () => {
      const all = await self.clients.matchAll({
        type: "window",
        includeUncontrolled: true,
      });
      for (const client of all) {
        if (client.url.includes(self.location.origin)) {
          await client.focus();
          if ("navigate" in client) await client.navigate(targetUrl);
          return;
        }
      }
      await self.clients.openWindow(targetUrl);
    })()
  );
});

// ── Message: allow pages to trigger skipWaiting ───────────────────────────
self.addEventListener("message", (event) => {
  if (event.data && event.data.type === "SKIP_WAITING") {
    self.skipWaiting();
  }
});

# Soul Pilates — nginx config for the static Astro bundle
server {
    listen      80 default_server;
    listen      [::]:80 default_server;
    server_name _;

    root  /usr/share/nginx/html;
    index index.html;

    # Emit relative Location headers so the outer reverse-proxy's scheme is preserved
    absolute_redirect off;

    # Long-cache the immutable build assets
    location /_astro/ {
        access_log    off;
        expires       1y;
        add_header    Cache-Control "public, immutable";
        try_files     $uri =404;
    }

    # Astro generates directory-style routes (/booking/index.html). Try as-is
    # first; if the file doesn't exist, try the directory; fall back to 404.
    location / {
        try_files $uri $uri/ $uri.html /404.html;
    }

    # Don't cache HTML — must always pick up new deployments
    location ~* \.html$ {
        add_header Cache-Control "no-store, must-revalidate";
        add_header Pragma "no-cache";
    }

    # Reasonable security defaults
    add_header X-Content-Type-Options nosniff;
    add_header X-Frame-Options SAMEORIGIN;
    add_header Referrer-Policy strict-origin-when-cross-origin;
}

server {
    listen 80;
    listen [::]:80;
    server_name new.soulpilates.com.vn;

    # Let's Encrypt ACME challenge
    location /.well-known/acme-challenge/ {
        root /var/www/html;
        allow all;
    }

    # Redirect all HTTP to HTTPS
    location / {
        return 301 https://$host$request_uri;
    }
}

server {
    listen 443 ssl;
    listen [::]:443 ssl;
    server_name new.soulpilates.com.vn;

    ssl_certificate     /etc/letsencrypt/live/new.soulpilates.com.vn/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/new.soulpilates.com.vn/privkey.pem;
    ssl_protocols       TLSv1.2 TLSv1.3;
    ssl_ciphers         HIGH:!aNULL:!MD5;

    client_max_body_size 15M;

    location /api/ {
        proxy_pass http://127.0.0.1:8391;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_read_timeout 120s;
        proxy_send_timeout 120s;
    }

    location /hubs/ {
        proxy_pass http://127.0.0.1:8391;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_read_timeout 3600s;
        proxy_send_timeout 3600s;
    }

    location /soulpilates-public/ {
        proxy_pass http://127.0.0.1:6324;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        expires 7d;
        add_header Cache-Control "public, immutable";
    }

    location / {
        proxy_pass http://127.0.0.1:3719;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        # Rewrite any http:// Location redirects from the inner nginx to https://
        proxy_redirect http://new.soulpilates.com.vn https://new.soulpilates.com.vn;
        proxy_redirect http://72.62.240.50 https://new.soulpilates.com.vn;
    }

    add_header X-Content-Type-Options nosniff always;
    add_header X-Frame-Options SAMEORIGIN always;
    add_header Referrer-Policy strict-origin-when-cross-origin always;
}

