  .getElementById("continueBtn")
  .addEventListener("click", async () => {
    if (!selectedMethod) return;
    const btn = document.getElementById("continueBtn");
    btn.disabled = true;
    btn.querySelector("span").textContent = t("common.loading");

    try {
      // 1. Reserve the spot (creates Attendance) if not already reserved
      if (!attendance) {
        // Resolve contact details from the most-trusted source first:
        //   - already-hydrated `intent` (from /booking handoff or
        //     client-context),
        //   - then the guest contact form once revealed.
        const guestVisible =
          document.getElementById("guestContactSection").style.display ===
          "block";
        let name = intent.clientName;
        let phone = intent.clientPhone;
        let email = intent.clientEmail;

        if (guestVisible) {
          name = (document.getElementById("guestName").value || "").trim();
          const cc = document.getElementById("guestPhoneCc").value;
          const num = (
            document.getElementById("guestPhone").value || ""
          ).trim();
          phone = num ? `${cc}${num.replace(/^0+/, "")}` : "";
          email =
            (document.getElementById("guestEmail").value || "").trim() ||
            null;
        }

        // No contact details? Reveal the inline guest form instead of
        // bouncing the user off-page. The login link is still available
        // inside the form for known customers.
        if (!name || !phone) {
          revealGuestContactForm();
          if (guestVisible) {
            // The form is already visible AND missing fields — surface
            // an inline error rather than silently failing.
            showGuestError(
              t("checkout.contactRequired") ||
                "Please enter your full name and phone number.",
            );
          }
          btn.disabled = false;
          btn.querySelector("span").textContent = getContinueBtnLabel();
          return;
        }

        const resBody = {
          sessionId,
          name,
          phone,
          email,
          goals: intent.goals || null,
          equipmentType: intent.equipmentType || null,
          quantity,
        };

        const rr = await fetch(`${API}/api/booking/reserve`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(resBody),
        });
        if (!rr.ok) throw new Error((await rr.json()).message);
        const r = await rr.json();
        attendance = {
          id: r.attendanceId,
          bookingReference: r.bookingReference,
          ...r,
        };
        sessionStorage.setItem(
          "sp_attendance_id",
          r.attendanceId || r.id || "",
        );
      }

      // 2. Create payment intent
      const ir = await fetch(`${API}/api/payment/create-intent`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          attendanceId:
            attendance.id || sessionStorage.getItem("sp_attendance_id"),
          paymentMethod: selectedMethod,
        }),
      });
      const intentRes = await ir.json();

      // 3. If no charge needed → straight to confirmation
      if (intentRes.amount === 0 || !intentRes.clientSecret) {
        showConfirmation(attendance.bookingReference);
        return;
      }

      // 4. Otherwise, mount Stripe Elements
      await showCardView(intentRes);
    } catch (e) {
      alert(e.message || "Something went wrong.");
      btn.disabled = false;
      btn.querySelector("span").textContent = getContinueBtnLabel();
    }
  });

