const params = new URLSearchParams(window.location.search);
const sessionId = params.get("session");
const intent = JSON.parse(
  sessionStorage.getItem("sp_booking_intent") || "{}",
);

let session = null; // CalendarSession from /class/{id}
let attendance = null; // Attendance returned by /reserve
let stripe = null;
let elements = null;
let paymentElement = null;
let activePackages = [];
let selectedMethod = null; // 'PACKAGE_CREDIT' | 'STRIPE_DEPOSIT' | 'STRIPE_FULL' | 'PAY_AT_STUDIO'
let quote = null; // Price quote from /payment/quote
let quantity = 1; // Group multi-seat. 1 for solo PRIVATE; 2 for a PRIVATE duo (SPM-98).
let upsellsByMethod = {}; // method -> upsells[] from each /quote call.
let upsellDismissed = false; // sticky once the user clicks "no thanks".
let resolvedClientId = null; // Set after client-context resolves; forwarded to /quote for upsell eligibility.
let bookingCompleted = false; // Set to true after successful payment — prevents unload beacon from releasing the reservation.
let checkoutSettings = {
  // Admin-configured defaults (overridden by API response)
  allowOnlinePayment: true,
  allowPartialPayment: true,
  allowPayAtStudio: true,
  depositPercentage: 30,
  onlinePaymentFeePercentage: 0,
  partialPaymentLabelEn: "",
  partialPaymentLabelVi: "",
  enableReservationSystem: true,
  reservationExpiryMinutes: 15,
  // Default true so the page works gracefully before the API responds;
  // the actual flag is loaded from /api/payment/checkout-settings.
  allowGuestCheckout: true,
};

// ── P5-S01: Immediate reservation release on page exit ──
// Uses sendBeacon so the request fires reliably even when the tab
// is closing. pagehide is the recommended event on modern browsers
// (Safari ignores beforeunload in many cases).
function releaseReservationBeacon() {
  if (bookingCompleted || !attendance) return;
  const payload = JSON.stringify({
    attendanceId: attendance.id || attendance.attendanceId,
    clientId: resolvedClientId || null,
  });
  navigator.sendBeacon(
    `${API}/api/booking/release-reservation`,
    new Blob([payload], { type: "application/json" }),
  );
}
window.addEventListener("pagehide", releaseReservationBeacon);
window.addEventListener("beforeunload", releaseReservationBeacon);

// ── Init ──
translatePage();
if (!sessionId) {
  alert("Missing session. Returning to booking.");
  window.location.href = "/booking";
} else {
  init();
}

async function init() {
  try {
    // Fetch checkout settings (no auth needed) in parallel with the session
    const [sessionRes, settingsRes] = await Promise.all([
      fetch(`${API}/api/booking/class/${sessionId}`),
      fetch(`${API}/api/payment/checkout-settings`).catch(() => null),
    ]);
    if (!sessionRes.ok) throw new Error("Session not found");
    // The /class/{id} endpoint returns a wrapped envelope:
    //   { session: {...}, blueprint: {...}, instructor: {...} }
    // We flatten it onto a single object the rest of this script can read with
    // the historical `session.capacity` / `session.format` / etc. property names.
    // Before this flatten, every consumer read `undefined` and:
    //   • the qty stepper got max=0 (spotsRemaining), disabling "+";
    //   • PACKAGE_CREDIT was filtered out because activePackages couldn't match format;
    //   • the booking summary's "CLASS" row rendered "—".
    const envelope = await sessionRes.json();
    const sessionPayload = envelope.session || envelope;
    session = {
      ...sessionPayload,
      className: sessionPayload.className,
      instructorName:
        envelope.instructor?.name ?? sessionPayload.instructorName,
      equipmentType:
        sessionPayload.equipmentType ?? envelope.blueprint?.equipmentType,
    };
    if (settingsRes && settingsRes.ok) {
      checkoutSettings = {
        ...checkoutSettings,
        ...(await settingsRes.json()),
      };
    }
    renderSummary();

    // ── Policy disclaimer banner ──
    fetch(`${API}/api/customer/cancel-policy`)
      .then((r) => (r.ok ? r.json() : null))
      .then((p) => {
        if (!p) return;
        const isPrivate = session?.format === "PRIVATE";
        // Build a human-readable summary of cancel windows
        const creditHrs = isPrivate
          ? (p.cancelWindowHoursCreditPrivate ?? 3)
          : (p.cancelWindowHoursCreditGroup ?? 3);
        const onlineHrs = isPrivate
          ? (p.cancelWindowHoursOnlinePrivate ?? 3)
          : (p.cancelWindowHoursOnlineGroup ?? 3);
        const studioHrs = isPrivate
          ? (p.cancelWindowHoursStudioPrivate ?? 3)
          : (p.cancelWindowHoursStudioGroup ?? 3);
        let text = `Cancellation policy: Credit bookings can be cancelled up to ${creditHrs}h before class.`;
        if (onlineHrs > 0)
          text += ` Online payments within ${onlineHrs}h are non-refundable.`;
        else text += ` Online payments are non-refundable.`;
        text += ` Studio bookings within ${studioHrs}h count as completed.`;
        const banner = document.getElementById("policyBanner");
        const bannerText = document.getElementById("policyBannerText");
        if (banner && bannerText) {
          bannerText.textContent = text;
          banner.style.display = "";
        }
      })
      .catch(() => {});

    // ── Guest-checkout gate ──────────────────────────────────────────────
    // If the admin has disabled guest checkout AND the visitor has no JWT,
    // send them to /login with a redirect back here so they can return
    // seamlessly after authenticating. We check AFTER settings load so
    // the flag is always current (not the default-true placeholder).
    const token = localStorage.getItem("customer_token");
    if (!token && checkoutSettings.allowGuestCheckout === false) {
      const here = window.location.pathname + window.location.search;
      window.location.href = "/login?redirect=" + encodeURIComponent(here);
      return; // Stop further init — the redirect will navigate away
    }

    // Try to get logged-in client + their packages.
    if (token) {

