    // Try to get logged-in client + their packages.
    if (token) {
      try {
        const cr = await fetch(`${API}/api/booking/client-context`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (cr.ok) {
          const ctx = await cr.json();
          if (ctx.clientName && !intent.clientName)
            intent.clientName = ctx.clientName;
          if (ctx.clientPhone && !intent.clientPhone)
            intent.clientPhone = ctx.clientPhone;
          if (ctx.clientEmail && !intent.clientEmail)
            intent.clientEmail = ctx.clientEmail;
          // Capture clientId so /quote can run the "hide for active holders" check server-side.
          if (ctx.clientId) resolvedClientId = ctx.clientId;
          activePackages = (ctx.packages || []).filter(
            (p) =>
              p.creditsRemaining > 0 &&
              (p.format === session.format || p.format === "MIXED"),
          );
        }
      } catch {}
    }

    // Fetch quotes for each method we will display
    await loadPaymentOptions();
  } catch (e) {
    document.getElementById("paymentOptions").innerHTML =
      `<div class="sp-error-msg visible">Could not load checkout. Please try again.</div>`;
  }
}

function renderSummary() {
  const start = new Date(session.startTime || intent.startTime);
  const end = new Date(session.endTime || intent.endTime);
  const dateStr = start.toLocaleDateString(
    getLocale() === "vi" ? "vi-VN" : "en-US",
    { weekday: "long", month: "long", day: "numeric" },
  );
  const timeStr = `${start.toLocaleTimeString(
    getLocale() === "vi" ? "vi-VN" : "en-US",
    { hour: "numeric", minute: "2-digit" },
  )} – ${end.toLocaleTimeString(getLocale() === "vi" ? "vi-VN" : "en-US", {
    hour: "numeric",
    minute: "2-digit",
  })}`;

  document.getElementById("sumClass").textContent =
    session.format === "PRIVATE"
      ? intent.equipmentName
        ? `Private — ${intent.equipmentName}`
        : "Private Class"
      : session.className || "—";
  document.getElementById("sumInstructor").textContent =
    session.instructorName || intent.instructorName || "—";
  document.getElementById("sumDateTime").innerHTML =
    `${dateStr}<br><span style="color:var(--sp-text-muted);font-weight:400;">${timeStr}</span>`;

  if (intent.equipmentName && session.format === "PRIVATE") {
    document.getElementById("sumEquipmentRow").style.display = "flex";
    document.getElementById("sumEquipment").textContent =
      intent.equipmentName;
  }

  if (session.format !== "PRIVATE") {
    // GROUP — the multi-seat quantity stepper drives quantity.
    const block = document.getElementById("qtyBlock");
    block.style.display = "flex";
    wireQuantityStepper();
  } else if (isDuoBooking()) {
    // SPM-98 — PRIVATE "Make it a Duo Class": book the SAME session for 2
    // seats. The single booker covers both, so there's no interactive
    // stepper — we lock quantity to 2 and surface a read-only Duo indicator.
    // This reuses the GROUP multi-seat path: 2 credits / 2× the drop-in are
    // charged via the standard /reserve + /quote flow.
    quantity = 2;
    const duoRow = document.getElementById("sumDuoRow");
    if (duoRow) duoRow.style.display = "flex";
    const duoNote = document.getElementById("duoPriceNote");

