function revealGuestContactForm() {
  // If guest checkout is disabled by admin, redirect to login rather than
  // showing the inline form. This is a secondary safeguard — the gate in
  // init() should already have redirected before we get here, but a late
  // settings load race could still surface the form momentarily.
  if (checkoutSettings.allowGuestCheckout === false) {
    const here = window.location.pathname + window.location.search;
    window.location.href = "/login?redirect=" + encodeURIComponent(here);
    return;
  }

  const section = document.getElementById("guestContactSection");
  if (section.style.display === "block") return;
  section.style.display = "block";
  // Friendly scroll — the section is now the most relevant unresolved
  // field on the page.
  setTimeout(() => {
    section.scrollIntoView({ behavior: "smooth", block: "center" });
    document.getElementById("guestName").focus();
  }, 50);

  const link = document.getElementById("linkToLogin");
  if (link && !link.dataset.bound) {
    link.dataset.bound = "true";
    link.addEventListener("click", (ev) => {
      ev.preventDefault();
      window.location.href =
        "/login?redirect=/checkout?session=" +
        encodeURIComponent(sessionId);
    });

