using System.Security.Claims;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using MongoDB.Driver;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Interfaces;
using SoulPilates.Infrastructure.Data;

namespace SoulPilates.API.Controllers;

/// <summary>
/// PWA push subscription management. The frontend's <c>push-client.js</c>
/// talks to these endpoints to wire <c>navigator.serviceWorker</c>'s
/// PushManager to our backend.
/// </summary>
[ApiController]
[Route("api/push")]
[Authorize]
public class PushController : ControllerBase
{
    private readonly IPushService _push;
    private readonly MongoDbContext _db;
    private readonly ILogger<PushController> _logger;

    public PushController(IPushService push, MongoDbContext db, ILogger<PushController> logger)
    {
        _push = push;
        _db = db;
        _logger = logger;
    }

    /// <summary>
    /// Public VAPID identity. The browser's <c>pushManager.subscribe()</c>
    /// needs this to sign its registration with the upstream push service.
    /// Anonymous so the page can fetch it before the user is logged in
    /// (though today we only call it from authenticated settings).
    /// </summary>
    [HttpGet("vapid-public-key")]
    [AllowAnonymous]
    public IActionResult GetVapidPublicKey()
    {
        var key = _push.GetVapidPublicKey();
        return Ok(new { publicKey = key });
    }

    /// <summary>Register / refresh this browser's subscription.</summary>
    [HttpPost("subscribe")]
    public async Task<IActionResult> Subscribe([FromBody] SubscribePushRequest request)
    {
        var userId = CurrentUserId();
        if (userId is null) return Unauthorized();
        var userAgent = Request.Headers.UserAgent.ToString();
        var sub = await _push.SubscribeAsync(userId, request, string.IsNullOrWhiteSpace(userAgent) ? null : userAgent);
        return Ok(new { id = sub.Id });
    }

    /// <summary>Drop a subscription (called by "remove device" in settings).</summary>
    [HttpDelete("subscribe")]
    public async Task<IActionResult> Unsubscribe([FromBody] UnsubscribeRequest request)
    {
        var userId = CurrentUserId();
        if (userId is null) return Unauthorized();
        if (string.IsNullOrWhiteSpace(request.Endpoint))
            return BadRequest(new { message = "Endpoint is required." });
        await _push.UnsubscribeAsync(userId, request.Endpoint);
        return NoContent();
    }

    /// <summary>List my registered devices for the settings UI.</summary>
    [HttpGet("devices")]
    public async Task<IActionResult> ListDevices()
    {
        var userId = CurrentUserId();
        if (userId is null) return Unauthorized();
        var devices = await _push.ListMyDevicesAsync(userId);
        return Ok(devices.Select(d => new
        {
            id = d.Id,
            endpoint = d.Endpoint,
            userAgent = d.UserAgent,
            lastDeliveredAt = d.LastDeliveredAt,
            createdAt = d.CreatedAt,
        }));
    }

    /// <summary>
    /// Send a test ping to all of my own devices. Useful for verifying the
    /// permission grant + subscription round-trip without waiting for a real
    /// trigger to fire.
    /// </summary>
    [HttpPost("test")]
    public async Task<IActionResult> SendTest()
    {
        var userId = CurrentUserId();
        if (userId is null) return Unauthorized();
        var actorName = User.FindFirst(ClaimTypes.Name)?.Value ?? "there";
        var count = await _push.EnqueueAsync(userId, new PushPayload
        {
            Title = "🌙 Test notification",
            Body = $"Hi {actorName} — if you see this, push is working!",
            Icon = "/icons/icon-192.png",
            Badge = "/icons/icon-192.png",
            Url = "/admin/settings",
            Tag = "test-ping",
        });
        return Ok(new { devicesQueued = count });
    }

    // ── Per-user preferences ──────────────────────────────────────────
    // Drives the Notifications tab inside the user's profile modal. Each
    // user owns exactly one preferences sub-document; the publisher reads
    // it on every PublishAsync. Saved as an embedded doc on User to
    // avoid a second round-trip per notification.

    /// <summary>
    /// Fetch the caller's preferences. Synthesises defaults
    /// (<c>Enabled = true</c>, no overrides) when the sub-doc is missing
    /// so the UI can always render a coherent state.
    /// </summary>
    [HttpGet("preferences")]
    public async Task<IActionResult> GetPreferences()
    {
        var userId = CurrentUserId();
        if (userId is null) return Unauthorized();

        var users = _db.GetCollection<User>("Users");
        var user = await users.Find(u => u.Id == userId).FirstOrDefaultAsync();
        if (user is null) return NotFound();

        var prefs = user.NotificationPreferences ?? new NotificationPreferences();
        return Ok(new
        {
            enabled = prefs.Enabled,
            emailFallbackEnabled = prefs.EmailFallbackEnabled,
            categoryOverrides = prefs.CategoryOverrides,
        });
    }

    public record UpdatePreferencesRequest(
        bool Enabled,
        bool EmailFallbackEnabled,
        Dictionary<string, bool>? CategoryOverrides);

    /// <summary>Replace the caller's preferences in one shot.</summary>
    [HttpPut("preferences")]
    public async Task<IActionResult> UpdatePreferences([FromBody] UpdatePreferencesRequest body)
    {
        var userId = CurrentUserId();
        if (userId is null) return Unauthorized();

        var prefs = new NotificationPreferences
        {
            Enabled = body.Enabled,
            EmailFallbackEnabled = body.EmailFallbackEnabled,
            CategoryOverrides = body.CategoryOverrides ?? new Dictionary<string, bool>(),
        };

        var users = _db.GetCollection<User>("Users");
        var update = Builders<User>.Update.Set(u => u.NotificationPreferences, prefs);
        var result = await users.UpdateOneAsync(u => u.Id == userId, update);
        if (result.MatchedCount == 0) return NotFound();
        return NoContent();
    }

    // ── Helpers ────────────────────────────────────────────────────────

    private string? CurrentUserId()
    {
        // The JWT issued by AuthService puts the user id in NameIdentifier.
        // Matches the pattern InstructorController / MeController already use.
        var sub = User.FindFirst(ClaimTypes.NameIdentifier)?.Value
                  ?? User.FindFirst("sub")?.Value;
        return string.IsNullOrWhiteSpace(sub) ? null : sub;
    }
}

public class UnsubscribeRequest
{
    public string Endpoint { get; set; } = null!;
}

