1	using Microsoft.Extensions.Configuration;
2	using Microsoft.Extensions.Logging;
3	using MongoDB.Driver;
4	using SoulPilates.Core.Entities;
5	using SoulPilates.Core.Interfaces;
6	using SoulPilates.Core.Notifications;
7	using SoulPilates.Infrastructure.Data;
8	
9	namespace SoulPilates.Services;
10	
11	/// <summary>
12	/// Default <see cref="INotificationPublisher"/>. Implements the
13	/// "push-first, email-fallback" policy with these decision rules:
14	///
15	/// <list type="number">
16	///   <item><description>Look up the target user. If no row → no-op (logs).</description></item>
17	///   <item><description>Honour the user's master switch
18	///   (<see cref="NotificationPreferences.Enabled"/>). If off → skip.</description></item>
19	///   <item><description>Consult the admin matrix
20	///   (<see cref="NotificationRule"/>) for <c>(category, user.Role)</c>.
21	///   When locked, the rule's <c>IsEnabled</c> is final. Otherwise the
22	///   user's <see cref="NotificationPreferences.CategoryOverrides"/> wins
23	///   if present, falling back to the rule default. Missing/unseeded rule
24	///   defaults OFF (SPM-127) unless the user explicitly overrode it; the
25	///   manual <see cref="NotificationCategory.Test"/> ping bypasses the matrix
26	///   and sends whenever the master switch is on.</description></item>
27	///   <item><description>Call <see cref="IPushService.EnqueueAsync"/>. If
28	///   it returns 0 (no devices) → fall back to email when
29	///   (a) the rule allows it, (b) the user opted in, (c) we have an
30	///   email address.</description></item>
31	/// </list>
32	///
33	/// All failures are swallowed and logged — notifications must never
34	/// destabilise the originating request.
35	/// </summary>
36	public class NotificationPublisher : INotificationPublisher
37	{
38	    private readonly IPushService _push;
39	    private readonly IEmailService _email;
40	    private readonly INotificationRuleService _rules;
41	    private readonly IMongoCollection<User> _users;
42	    private readonly ILogger<NotificationPublisher> _logger;
43	
44	    /// <summary>
45	    /// Public-facing site origin (e.g. <c>https://app.soulpilates.com.vn</c>)
46	    /// read from <c>PublicSite:BaseUrl</c> — the same key EmailService uses.
47	    /// Trailing slashes are trimmed at construction so app-relative push URLs
48	    /// can be promoted to absolute links for the email fallback without "//".
49	    /// </summary>
50	    private readonly string _publicBaseUrl;
51	
52	    public NotificationPublisher(
53	        IPushService push,
54	        IEmailService email,
55	        INotificationRuleService rules,
56	        MongoDbContext dbContext,
57	        IConfiguration configuration,
58	        ILogger<NotificationPublisher> logger)
59	    {
60	        _push = push;
61	        _email = email;
62	        _rules = rules;
63	        _users = dbContext.GetCollection<User>("Users");
64	        _logger = logger;
65	
66	        var rawBase = configuration["PublicSite:BaseUrl"];
67	        _publicBaseUrl = string.IsNullOrWhiteSpace(rawBase)
68	            ? "http://localhost:4321"
69	            : rawBase.TrimEnd('/');
70	    }
71	
72	    public async Task PublishAsync(string userId, NotificationCategory category, PushPayload payload)
73	    {
74	        try
75	        {
76	            var user = await _users.Find(u => u.Id == userId).FirstOrDefaultAsync();
77	            if (user is null)
78	            {
79	                _logger.LogDebug("NotificationPublisher: user {UserId} not found; skipping {Category}", userId, category);
80	                return;
81	            }
82	
83	            // 1. Master switch.
84	            var prefs = user.NotificationPreferences;
85	            if (prefs is { Enabled: false })
86	            {
87	                _logger.LogDebug("NotificationPublisher: master switch off for {UserId}; skipping {Category}",
88	                    userId, category);
89	                return;
90	            }
91	
92	            // 2. Resolve rule + decide.
93	            var rule = await _rules.GetRuleAsync(category, user.Role);
94	            var shouldSend = ResolveShouldSend(rule, prefs, category);
95	            if (!shouldSend)
96	            {
97	                _logger.LogDebug("NotificationPublisher: matrix/prefs disabled {Category} for {UserId}", category, userId);
98	                return;
99	            }
100	
101	            // 3. Try push first.
102	            var queued = await _push.EnqueueAsync(userId, payload);
103	            if (queued > 0)
104	            {
105	                _logger.LogDebug("NotificationPublisher: queued {Category} for {UserId} to {Count} device(s)",
106	                    category, userId, queued);
107	                return;
108	            }
109	
110	            // 4. Email fallback. Both the rule AND the user must allow it,
111	            //    and we need an address to send to.
112	            var ruleAllowsEmail = rule?.EmailFallbackEnabled ?? true;
113	            var userAllowsEmail = prefs?.EmailFallbackEnabled ?? true;
114	            if (ruleAllowsEmail && userAllowsEmail && !string.IsNullOrWhiteSpace(user.Email))
115	            {
116	                _logger.LogDebug("NotificationPublisher: 0 devices for {UserId}; falling back to email for {Category}",
117	                    userId, category);
118	                await _email.SendGenericAsync(
119	                    toEmail: user.Email,
120	                    subject: payload.Title,
121	                    heading: payload.Title,
122	                    bodyText: payload.Body,
123	                    ctaUrl: BuildAbsoluteUrl(payload.Url),
124	                    ctaLabel: "Open in Soul Pilates");
125	            }
126	            else
127	            {
128	                _logger.LogInformation(
129	                    "NotificationPublisher: no push and email-fallback disabled for {UserId}; dropping {Category}",
130	                    userId, category);
131	            }
132	        }
133	        catch (Exception ex)
134	        {
135	            // Notifications must NEVER kill the originating request. Swallow
136	            // here and log; ops can see misses in Serilog/GlitchTip.
137	            _logger.LogError(ex, "NotificationPublisher: failed to publish {Category} to {UserId}", category, userId);
138	        }
139	    }
140	
141	    public async Task PublishToRolesAsync(IEnumerable<string> roles, NotificationCategory category, PushPayload payload)
142	    {
143	        try
144	        {
145	            var roleList = roles.ToList();
146	            if (roleList.Count == 0) return;
147	            var users = await _users.Find(u => roleList.Contains(u.Role)).ToListAsync();
148	            foreach (var u in users)
149	            {
150	                if (string.IsNullOrWhiteSpace(u.Id)) continue;
151	                await PublishAsync(u.Id, category, payload);
152	            }
153	        }
154	        catch (Exception ex)
155	        {
156	            _logger.LogError(ex, "NotificationPublisher: failed PublishToRolesAsync for {Category}", category);
157	        }
158	    }
159	
160	    // ── Decision logic ───────────────────────────────────────────────────
161	
162	    /// <summary>
163	    /// The single source of truth for "should this notification be
164	    /// delivered to this user?". Split out so the publisher can unit-test
165	    /// the matrix without spinning Mongo.
166	    /// </summary>
167	    internal static bool ResolveShouldSend(
168	        NotificationRule? rule,
169	        NotificationPreferences? prefs,
170	        NotificationCategory category)
171	    {
172	        // Test (value 99) is a user-initiated self-test that intentionally has
173	        // no matrix cell (NotificationRuleService.SeedDefaultsAsync skips it).
174	        // It bypasses the rule matrix entirely and sends whenever the user's
175	        // master switch is on — the master switch is re-checked here so the
176	        // function stays self-consistent even though PublishAsync also gates on
177	        // it. (prefs null = master switch on, matching PublishAsync.)
178	        if (category == NotificationCategory.Test)
179	            return prefs is not { Enabled: false };
180	
181	        // Missing/unseeded rule = default-OFF (SPM-127). This stops the
182	        // boot-time flood before NotificationSeederHostedService runs and
183	        // ensures only explicitly-seeded categories fire. A user's explicit
184	        // override is still honoured if they set one.
185	        if (rule is null)
186	        {
187	            if (prefs?.CategoryOverrides is { } o &&
188	                o.TryGetValue(category.ToString(), out var explicitOverride))
189	                return explicitOverride;
190	            return false;
191	        }
192	
193	        // Locked: the rule's IsEnabled is final, user prefs ignored.
194	        if (rule.IsLocked) return rule.IsEnabled;
195	
196	        // Not locked: user override wins if present, else rule default.
197	        if (prefs?.CategoryOverrides is { } overrides &&
198	            overrides.TryGetValue(category.ToString(), out var userVal))
199	            return userVal;
200	
201	        return rule.IsEnabled;
202	    }
203	
204	    /// <summary>
205	    /// Push payloads carry app-relative URLs (e.g. <c>/admin/calendar</c>)
206	    /// because the service worker resolves them against
207	    /// <c>self.location.origin</c>. Email recipients aren't on the SW, so the
208	    /// email fallback needs an absolute link. We prepend the configured
209	    /// <c>PublicSite:BaseUrl</c> (SPM-127) to app-relative paths and leave
210	    /// already-absolute http(s) URLs untouched. Null/empty input passes
211	    /// through unchanged.
212	    /// </summary>
213	    private string? BuildAbsoluteUrl(string? path)
214	    {
215	        if (string.IsNullOrWhiteSpace(path)) return path;
216	
217	        // Already absolute (http:// or https://) — don't touch it.
218	        if (path.StartsWith("http://", StringComparison.OrdinalIgnoreCase) ||
219	            path.StartsWith("https://", StringComparison.OrdinalIgnoreCase))
220	            return path;
221	
222	        // App-relative path: join to the trimmed base with exactly one slash.
223	        return path.StartsWith('/')
224	            ? $"{_publicBaseUrl}{path}"
225	            : $"{_publicBaseUrl}/{path}";
226	    }
227	}
