///
/// <list type="number">
///   <item><description>Look up the target user. If no row → no-op (logs).</description></item>
///   <item><description>Honour the user's master switch
///   (<see cref="NotificationPreferences.Enabled"/>). If off → skip.</description></item>
///   <item><description>Consult the admin matrix
///   (<see cref="NotificationRule"/>) for <c>(category, user.Role)</c>.
///   When locked, the rule's <c>IsEnabled</c> is final. Otherwise the
///   user's <see cref="NotificationPreferences.CategoryOverrides"/> wins
///   if present, falling back to the rule default. Missing/unseeded rule
///   defaults OFF (SPM-127) unless the user explicitly overrode it; the
///   manual <see cref="NotificationCategory.Test"/> ping bypasses the matrix
///   and sends whenever the master switch is on.</description></item>
///   <item><description>Call <see cref="IPushService.EnqueueAsync"/>. If
///   it returns 0 (no devices) → fall back to email when
///   (a) the rule allows it, (b) the user opted in, (c) we have an
///   email address.</description></item>
/// </list>
///
/// All failures are swallowed and logged — notifications must never
/// destabilise the originating request.
/// </summary>
public class NotificationPublisher : INotificationPublisher
{
    private readonly IPushService _push;
    private readonly IEmailService _email;
    private readonly INotificationRuleService _rules;
    private readonly IMongoCollection<User> _users;
    private readonly ILogger<NotificationPublisher> _logger;

    /// <summary>
    /// Public-facing site origin (e.g. <c>https://app.soulpilates.com.vn</c>)
    /// read from <c>PublicSite:BaseUrl</c> — the same key EmailService uses.
    /// Trailing slashes are trimmed at construction so app-relative push URLs
    /// can be promoted to absolute links for the email fallback without "//".
    /// </summary>
    private readonly string _publicBaseUrl;

    public NotificationPublisher(
        IPushService push,
        IEmailService email,
        INotificationRuleService rules,
        MongoDbContext dbContext,
        IConfiguration configuration,
        ILogger<NotificationPublisher> logger)
    {
        _push = push;
        _email = email;
        _rules = rules;
        _users = dbContext.GetCollection<User>("Users");
        _logger = logger;

        var rawBase = configuration["PublicSite:BaseUrl"];
        _publicBaseUrl = string.IsNullOrWhiteSpace(rawBase)
            ? "http://localhost:4321"
            : rawBase.TrimEnd('/');
    }

    public async Task PublishAsync(string userId, NotificationCategory category, PushPayload payload)
    {
        try
        {
            var user = await _users.Find(u => u.Id == userId).FirstOrDefaultAsync();
            if (user is null)
            {
                _logger.LogDebug("NotificationPublisher: user {UserId} not found; skipping {Category}", userId, category);
                return;
            }

            // 1. Master switch.
            var prefs = user.NotificationPreferences;
            if (prefs is { Enabled: false })
            {
                _logger.LogDebug("NotificationPublisher: master switch off for {UserId}; skipping {Category}",
                    userId, category);
                return;
            }

            // 2. Resolve rule + decide.
            var rule = await _rules.GetRuleAsync(category, user.Role);
            var shouldSend = ResolveShouldSend(rule, prefs, category);
            if (!shouldSend)
            {
                _logger.LogDebug("NotificationPublisher: matrix/prefs disabled {Category} for {UserId}", category, userId);
                return;
            }

            // 3. Try push first.
            var queued = await _push.EnqueueAsync(userId, payload);
            if (queued > 0)
            {
                _logger.LogDebug("NotificationPublisher: queued {Category} for {UserId} to {Count} device(s)",
                    category, userId, queued);
                return;
            }

            // 4. Email fallback. Both the rule AND the user must allow it,
            //    and we need an address to send to.
            var ruleAllowsEmail = rule?.EmailFallbackEnabled ?? true;
            var userAllowsEmail = prefs?.EmailFallbackEnabled ?? true;
            if (ruleAllowsEmail && userAllowsEmail && !string.IsNullOrWhiteSpace(user.Email))
            {
                _logger.LogDebug("NotificationPublisher: 0 devices for {UserId}; falling back to email for {Category}",
                    userId, category);
                await _email.SendGenericAsync(
                    toEmail: user.Email,
                    subject: payload.Title,
                    heading: payload.Title,
                    bodyText: payload.Body,
                    ctaUrl: BuildAbsoluteUrl(payload.Url),
                    ctaLabel: "Open in Soul Pilates");
            }
            else
            {
                _logger.LogInformation(
                    "NotificationPublisher: no push and email-fallback disabled for {UserId}; dropping {Category}",
                    userId, category);
            }
        }
        catch (Exception ex)
        {
            // Notifications must NEVER kill the originating request. Swallow
            // here and log; ops can see misses in Serilog/GlitchTip.
            _logger.LogError(ex, "NotificationPublisher: failed to publish {Category} to {UserId}", category, userId);
        }
    }

    public async Task PublishToRolesAsync(IEnumerable<string> roles, NotificationCategory category, PushPayload payload)
    {
        try
        {
            var roleList = roles.ToList();
            if (roleList.Count == 0) return;
            var users = await _users.Find(u => roleList.Contains(u.Role)).ToListAsync();
            foreach (var u in users)
            {
                if (string.IsNullOrWhiteSpace(u.Id)) continue;
                await PublishAsync(u.Id, category, payload);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "NotificationPublisher: failed PublishToRolesAsync for {Category}", category);
        }
    }

    // ── Decision logic ───────────────────────────────────────────────────

    /// <summary>
    /// The single source of truth for "should this notification be
    /// delivered to this user?". Split out so the publisher can unit-test
    /// the matrix without spinning Mongo.
    /// </summary>
    internal static bool ResolveShouldSend(
        NotificationRule? rule,
        NotificationPreferences? prefs,
        NotificationCategory category)
    {
        // Test (value 99) is a user-initiated self-test that intentionally has
        // no matrix cell (NotificationRuleService.SeedDefaultsAsync skips it).
        // It bypasses the rule matrix entirely and sends whenever the user's
        // master switch is on — the master switch is re-checked here so the
        // function stays self-consistent even though PublishAsync also gates on
        // it. (prefs null = master switch on, matching PublishAsync.)
        if (category == NotificationCategory.Test)
            return prefs is not { Enabled: false };

        // Missing/unseeded rule = default-OFF (SPM-127). This stops the
        // boot-time flood before NotificationSeederHostedService runs and
        // ensures only explicitly-seeded categories fire. A user's explicit
        // override is still honoured if they set one.
        if (rule is null)
        {
            if (prefs?.CategoryOverrides is { } o &&
                o.TryGetValue(category.ToString(), out var explicitOverride))
                return explicitOverride;
            return false;
        }

        // Locked: the rule's IsEnabled is final, user prefs ignored.
        if (rule.IsLocked) return rule.IsEnabled;

        // Not locked: user override wins if present, else rule default.
        if (prefs?.CategoryOverrides is { } overrides &&
            overrides.TryGetValue(category.ToString(), out var userVal))
            return userVal;

        return rule.IsEnabled;
    }

    /// <summary>
    /// Push payloads carry app-relative URLs (e.g. <c>/admin/calendar</c>)
    /// because the service worker resolves them against
    /// <c>self.location.origin</c>. Email recipients aren't on the SW, so the
    /// email fallback needs an absolute link. We prepend the configured
    /// <c>PublicSite:BaseUrl</c> (SPM-127) to app-relative paths and leave
    /// already-absolute http(s) URLs untouched. Null/empty input passes
    /// through unchanged.
    /// </summary>
    private string? BuildAbsoluteUrl(string? path)
    {
        if (string.IsNullOrWhiteSpace(path)) return path;

        // Already absolute (http:// or https://) — don't touch it.
        if (path.StartsWith("http://", StringComparison.OrdinalIgnoreCase) ||
            path.StartsWith("https://", StringComparison.OrdinalIgnoreCase))
            return path;

        // App-relative path: join to the trimmed base with exactly one slash.
        return path.StartsWith('/')
            ? $"{_publicBaseUrl}{path}"
            : $"{_publicBaseUrl}/{path}";
    }
}

