using Microsoft.Extensions.Logging;
using MongoDB.Driver;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Interfaces;
using SoulPilates.Core.Notifications;
using SoulPilates.Infrastructure.Data;

namespace SoulPilates.Services;

/// <summary>
/// Default <see cref="INotificationRuleService"/> backed by the
/// <c>NotificationRules</c> Mongo collection. A unique index on
/// <c>(Category, Role)</c> guarantees the matrix has at most one cell per
/// pair — concurrent <c>SeedDefaultsAsync</c> calls from horizontal scale
/// can't double-insert.
/// </summary>
public class NotificationRuleService : INotificationRuleService
{
    /// <summary>
    /// Roles that participate in the matrix. Customer-facing accounts are
    /// intentionally excluded; this grid is for management/staff roles only.
    /// </summary>
    private static readonly string[] StaffRoles =
    {
        "Admin",
        "SuperAdmin",
        "Owner",
        "Manager",
        "Receptionist",
        "Accountant",
        "Instructor",
    };

    /// <summary>
    /// Combinations that are hard-locked OFF by product decision (SPM-102):
    /// they can never resolve to "send" and the admin matrix must never be
    /// able to re-enable them, regardless of any stored/toggled rule. The
    /// service is the single source of truth for these — see
    /// <see cref="ApplyHardLock"/>.
    /// </summary>
    private static bool IsHardLockedOff(NotificationCategory category, string? role)
        => category == NotificationCategory.PaymentReceived
           && string.Equals(role, "Instructor", StringComparison.OrdinalIgnoreCase);

    private readonly IMongoCollection<NotificationRule> _rules;
    private readonly ILogger<NotificationRuleService> _logger;

    public NotificationRuleService(MongoDbContext dbContext, ILogger<NotificationRuleService> logger)
    {
        _rules = dbContext.GetCollection<NotificationRule>("NotificationRules");
        _logger = logger;

        // Best-effort unique index. Tolerant of "already exists" failures
        // for hot-reload scenarios.
        try
        {
            _rules.Indexes.CreateOne(new CreateIndexModel<NotificationRule>(
                Builders<NotificationRule>.IndexKeys
                    .Ascending(r => r.Category)
                    .Ascending(r => r.Role),
                new CreateIndexOptions { Unique = true, Name = "uq_category_role" }));
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex, "Could not ensure NotificationRules indexes");
        }
    }

    public async Task<IReadOnlyList<NotificationRule>> GetAllAsync()
    {
        var all = await _rules.Find(Builders<NotificationRule>.Filter.Empty).ToListAsync();
        // Enforce hard-locks on read so the admin matrix always reflects the true
        // (locked-off) state even if a stale document slipped through, and flag them
        // (SPM-127) so the UI can render a non-editable lock affordance.
        foreach (var r in all)
        {
            ApplyHardLock(r);
            r.IsHardLocked = IsHardLockedOff(r.Category, r.Role);
        }
        return all;
    }

    public async Task<NotificationRule?> GetRuleAsync(NotificationCategory category, string role)
    {
        // Hard-locked combinations resolve OFF regardless of what (if anything)
        // is stored. Returning a synthetic locked+disabled rule guarantees the
        // publisher's ResolveShouldSend short-circuits to "don't send".
        if (IsHardLockedOff(category, role))
            return HardLockedRule(category, role);

        var rule = await _rules.Find(r => r.Category == category && r.Role == role).FirstOrDefaultAsync();
        if (rule is not null) ApplyHardLock(rule);
        return rule;
    }

    public async Task<NotificationRule> UpsertAsync(NotificationCategory category, string role,
        bool isEnabled, bool isLocked, bool emailFallbackEnabled)
    {
        if (string.IsNullOrWhiteSpace(role)) throw new ArgumentException("Role is required.", nameof(role));

        // Hard-locked combinations (SPM-102) can never be enabled by an admin.
        // Force the stored state to disabled+locked no matter what was sent.
        if (IsHardLockedOff(category, role))
        {
            isEnabled = false;
            isLocked = true;
        }

        var filter = Builders<NotificationRule>.Filter.And(
            Builders<NotificationRule>.Filter.Eq(r => r.Category, category),
            Builders<NotificationRule>.Filter.Eq(r => r.Role, role));

        var update = Builders<NotificationRule>.Update
            .Set(r => r.Category, category)
            .Set(r => r.Role, role)
            .Set(r => r.IsEnabled, isEnabled)
            .Set(r => r.IsLocked, isLocked)
            .Set(r => r.EmailFallbackEnabled, emailFallbackEnabled)
            .Set(r => r.UpdatedAt, DateTime.UtcNow)
            .SetOnInsert(r => r.CreatedAt, DateTime.UtcNow);

        var updated = await _rules.FindOneAndUpdateAsync(filter, update,
            new FindOneAndUpdateOptions<NotificationRule>
            {
                IsUpsert = true,
                ReturnDocument = ReturnDocument.After,
            });
        return updated;
    }

    public async Task<int> SeedDefaultsAsync()
    {
        var existing = await _rules.Find(Builders<NotificationRule>.Filter.Empty).ToListAsync();
        var seen = new HashSet<(NotificationCategory, string)>(
            existing.Select(r => (r.Category, r.Role)));

        var inserts = new List<NotificationRule>();
        foreach (NotificationCategory cat in Enum.GetValues(typeof(NotificationCategory)))
        {
            // Test is a manual-only category; no matrix cell needed.
            if (cat == NotificationCategory.Test) continue;

            foreach (var role in StaffRoles)
            {
                if (seen.Contains((cat, role))) continue;
                var hardLocked = IsHardLockedOff(cat, role);
                inserts.Add(new NotificationRule
                {
                    Category = cat,
                    Role = role,
                    // Hard-locked pairs (SPM-102) are seeded off + locked so
                    // they can never resolve to send.
                    IsEnabled = !hardLocked && DefaultEnabledFor(cat, role),
                    IsLocked = hardLocked,
                    EmailFallbackEnabled = true,
                });
            }
        }

        if (inserts.Count == 0) return 0;

        try
        {
            await _rules.InsertManyAsync(inserts, new InsertManyOptions { IsOrdered = false });
        }
        catch (MongoBulkWriteException ex)
        {
            // Race: another node inserted some of these between our read
            // and write. Duplicate-key errors are expected and benign.
            _logger.LogDebug(ex, "Tolerating duplicate-key on rule seed (concurrent boot)");
        }

        _logger.LogInformation("Seeded {Count} NotificationRule rows", inserts.Count);
        return inserts.Count;
    }

    /// <summary>
    /// Per-(category, role) opinion on whether the default should be on.
    /// Most things are on by default; a few combinations are off because
    /// they'd be noise (e.g. Instructor doesn't care about a new client
    /// being added by an admin).
    /// </summary>
    private static bool DefaultEnabledFor(NotificationCategory cat, string role) => (cat, role) switch
    {
        // Instructors only care about events that involve their classes/clients.
        (NotificationCategory.NewClient, "Instructor")            => false,
        (NotificationCategory.ReimbursementSettled, "Instructor") => false,
        (NotificationCategory.LowStock, "Instructor")             => false,
        (NotificationCategory.PaymentReceived, "Instructor")      => false,
        // Booking cancel/reschedule events (SPM-101) are studio-ops concerns:
        // on for Admin/Manager (default via the catch-all), off for Instructor.
        (NotificationCategory.BookingCancelled, "Instructor")     => false,
        (NotificationCategory.BookingRescheduled, "Instructor")   => false,
        // Class reminder is only meaningful to instructors.
        (NotificationCategory.ClassReminder, "Admin")             => false,
        (NotificationCategory.ClassReminder, "SuperAdmin")        => false,
        (NotificationCategory.ClassReminder, "Owner")             => false,
        (NotificationCategory.ClassReminder, "Manager")           => false,
        (NotificationCategory.ClassReminder, "Receptionist")      => false,
        (NotificationCategory.ClassReminder, "Accountant")        => false,
        // Class re-assignment (SPM-87) targets the newly-assigned instructor.
        // On for Instructor; off for non-instructors — they typically perform the
        // reassignment themselves, so a back-to-self ping would be noise.
        (NotificationCategory.ClassReassigned, "Admin")           => false,
        (NotificationCategory.ClassReassigned, "SuperAdmin")      => false,
        (NotificationCategory.ClassReassigned, "Owner")           => false,
        (NotificationCategory.ClassReassigned, "Manager")         => false,
        (NotificationCategory.ClassReassigned, "Receptionist")    => false,
        (NotificationCategory.ClassReassigned, "Accountant")      => false,
        _ => true,
    };

    /// <summary>
    /// Coerce a rule for a hard-locked combination (SPM-102) into its only
    /// permitted state: disabled and locked. Mutating in place keeps the
    /// returned grid/rule consistent with what the publisher resolves.
    /// </summary>
    private static void ApplyHardLock(NotificationRule rule)
    {
        if (!IsHardLockedOff(rule.Category, rule.Role)) return;
        rule.IsEnabled = false;
        rule.IsLocked = true;
    }

    /// <summary>
    /// Synthetic disabled+locked rule for a hard-locked combination, used
    /// when the publisher asks for a rule that may not be stored. Because
    /// <c>IsLocked</c> is true and <c>IsEnabled</c> is false, the publisher's
    /// ResolveShouldSend always returns false for these pairs.
    /// </summary>
    private static NotificationRule HardLockedRule(NotificationCategory category, string role)
        => new()
        {
            Category = category,
            Role = role,
            IsEnabled = false,
            IsLocked = true,
            EmailFallbackEnabled = false,
        };
}

namespace SoulPilates.Core.Notifications;

/// <summary>
/// Cross-feature catalogue of notification kinds the publisher knows how to
/// emit. Categories are the granularity at which:
///   1. Admins toggle defaults on/off in <c>NotificationRule</c> (per-role).
///   2. Individual users override the defaults in their profile.
///   3. The publisher decides whether to fall back to email.
///
/// Add new entries here whenever a new trigger is wired; the per-role matrix
/// + per-user preferences will surface the new toggle automatically.
/// </summary>
public enum NotificationCategory
{
    /// <summary>A customer reserved a spot in an instructor's class.</summary>
    NewBooking = 1,

    /// <summary>15-minute pre-class ping for the instructor.</summary>
    ClassReminder = 2,

    /// <summary>Customer didn't check in and was marked NO_SHOW.</summary>
    NoShow = 3,

    /// <summary>Payment recorded at the till / Stripe webhook fired.</summary>
    PaymentReceived = 4,

    /// <summary>New customer record was created.</summary>
    NewClient = 5,

    /// <summary>A reimbursement to the recipient was marked settled.</summary>
    ReimbursementSettled = 6,

    /// <summary>Stock dropped below the low-water mark.</summary>
    LowStock = 7,

    /// <summary>A booking was cancelled (customer self-service or admin whole-session cancel).</summary>
    BookingCancelled = 8,

    /// <summary>A booking was moved to a different session (customer self-service reschedule).</summary>
    BookingRescheduled = 9,

    /// <summary>A class was re-assigned to a different instructor; the newly-assigned instructor is notified.</summary>
    ClassReassigned = 10,

    /// <summary>Operator-fired test ping (used by the Settings page button).</summary>
    Test = 99,
}

