file.content:
.pos-products-card {
  flex: 1;
  min-height: 320px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}
.pos-product-grid {
  padding: 16px;
  overflow-y: auto;
  flex: 1;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(190px, 1fr));
  gap: 10px;
}
.pos-cart-card {
  flex: 1;
  display: flex;
  flex-direction: column;
  /* Always allow the right-column card to scroll so the totals block
     and Complete Sale button are never clipped on any viewport height. */
  overflow-y: auto;
  max-height: calc(100vh - var(--topbar-height) - 72px);
  min-height: 0;
}
.pos-cart-header { flex-shrink: 0; }
.pos-cart-items {
  flex: none;
  overflow: visible;
  padding: 12px 16px;
  min-height: 200px;
}
.pos-client-row {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

/* Tablet / narrow desktops — stack columns vertically so the page can
   scroll naturally. The viewport is no longer pinned to 100vh. */
@media (max-width: 920px) {
  .pos-layout {
    grid-template-columns: 1fr;
    min-height: 0;
  }
  .pos-col-right { max-height: none; }
  .pos-products-card { min-height: 360px; }
}

