  const cols = 7;
  const gtc = `52px repeat(${cols}, 1fr)`;
  headers.style.gridTemplateColumns = gtc;
  grid.style.gridTemplateColumns = gtc;

  headers.innerHTML = '<div class="cal-col-gutter"></div>' +
    Array.from({ length: cols }, (_, i) => {
      const d = new Date(weekStart); d.setDate(d.getDate() + i);
      const isToday = d.toDateString() === new Date().toDateString();
      const isHoliday = holidayDates.has(d.toISOString().slice(0,10));
      return `<div class="cal-col-header">
        <div class="ch-wday">${d.toLocaleDateString('en-US', { weekday: 'short' })}</div>
        <div class="ch-num ${isToday ? 'today' : ''}">${d.getDate()}</div>
        ${isHoliday ? '<div style="font-size:9px;color:var(--color-warning);margin-top:2px;">Holiday</div>' : ''}
      </div>`;
    }).join('');

  const vis = getVisibleSessions();
  grid.innerHTML = '';
  HOURS.forEach(h => {
    const tl = document.createElement('div');
    tl.className = 'cal-time-label';
    tl.textContent = fmtHour(h);
    grid.appendChild(tl);

    for (let d = 0; d < cols; d++) {
      const cell = document.createElement('div');
      cell.className = 'cal-cell';
      const cellDate = new Date(weekStart); cellDate.setDate(cellDate.getDate() + d); cellDate.setHours(h,0,0,0);

      if (!isHourOpen(h, cellDate.getDay())) cell.classList.add('closed-hour');

      const dateStr = cellDate.toISOString().slice(0,10);
      if (h === HOURS[0] && holidayDates.has(dateStr)) {
        const hol = scheduleConfig.holidays?.find(x => x.date === dateStr);
        const overlay = document.createElement('div');
        overlay.className = 'cal-holiday-overlay';
        overlay.innerHTML = `<div class="hol-icon">📅</div><div class="hol-label">${esc(hol?.label || 'Studio Holiday')}</div><div class="hol-sub">No Classes</div>`;
        cell.appendChild(overlay);
      }

      const cellSessions = vis.filter(s => {
        const st = new Date(s.startTime);
        return st.getDate() === cellDate.getDate() && st.getMonth() === cellDate.getMonth() &&
          st.getFullYear() === cellDate.getFullYear() && st.getHours() === h;
      });

      if (cellSessions.length === 1) {
        cell.appendChild(buildEventCard(cellSessions[0]));
      } else if (cellSessions.length > 1) {
        cell.appendChild(buildMultiPill(cellSessions, cellDate));
      }

      cell.addEventListener('click', e => {
        if (e.target.closest('.ev') || e.target.closest('.ev-multi-pill')) return;
        showSlotPopover(e, cellDate);
      });

      grid.appendChild(cell);
    }
  });
}

/* ══ DAY VIEW ══ */
function renderDayGrid() {
