/* ══ DAY VIEW ══ */
function renderDayGrid() {
  const headers = document.getElementById('calHeaders');
  const grid = document.getElementById('calGrid');
  const vis = getVisibleSessions();

  let columns = [];
  if (currentGroupBy === 'instructor') {
    const ids = new Set(vis.map(s => s.instructorId).filter(Boolean));
    staffList.forEach(s => { if (s.isActive !== false) ids.add(s.id); });
    columns = [...ids].map(id => {
      const st = staffList.find(s => s.id === id);
      return { key: id, label: st?.name || '—' };
    });
    if (!columns.length) columns = [{ key: '__all', label: 'All' }];
  } else if (currentGroupBy === 'difficulty') {
    columns = ['ALL_LEVELS','BEGINNER','INTERMEDIATE','ADVANCED'].map(k => ({ key: k, label: k.replace('_',' ') }));
  } else if (currentGroupBy === 'format') {
    columns = ['GROUP','MAT','PRIVATE','DUO'].map(k => ({ key: k, label: k === 'MAT' ? 'Mat Group Classes' : k }));
  } else {
    columns = [{ key: '__all', label: selectedDayDate.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' }) }];
  }

  const gtc = `52px repeat(${columns.length}, 1fr)`;
  headers.style.gridTemplateColumns = gtc;
  grid.style.gridTemplateColumns = gtc;

  headers.innerHTML = '<div class="cal-col-gutter"></div>' +
    columns.map(c => `<div class="cal-col-header"><div class="ch-wday">${esc(c.label)}</div></div>`).join('');

  grid.innerHTML = '';
  HOURS.forEach(h => {
    const tl = document.createElement('div');
    tl.className = 'cal-time-label';
    tl.textContent = fmtHour(h);
    grid.appendChild(tl);

    columns.forEach(col => {
      const cell = document.createElement('div');
      cell.className = 'cal-cell';
      if (!isHourOpen(h, selectedDayDate.getDay())) cell.classList.add('closed-hour');

      const cellSessions = vis.filter(s => {
        const st = new Date(s.startTime);
        if (st.getDate() !== selectedDayDate.getDate() || st.getMonth() !== selectedDayDate.getMonth() || st.getHours() !== h) return false;
        if (col.key === '__all') return true;
        if (currentGroupBy === 'instructor') return s.instructorId === col.key;
        if (currentGroupBy === 'difficulty') return (s.difficultyLevel || 'ALL_LEVELS') === col.key;
        if (currentGroupBy === 'format') return (s.format || 'GROUP') === col.key;
        return true;
      });

      if (cellSessions.length === 1) cell.appendChild(buildEventCard(cellSessions[0]));
      else if (cellSessions.length > 1) {
        const sd = new Date(selectedDayDate); sd.setHours(h,0,0,0);
        cell.appendChild(buildMultiPill(cellSessions, sd));
      }

      const sd2 = new Date(selectedDayDate); sd2.setHours(h,0,0,0);
      cell.addEventListener('click', e => {
        if (e.target.closest('.ev') || e.target.closest('.ev-multi-pill')) return;
        showSlotPopover(e, sd2);
      });

      grid.appendChild(cell);
    });
  });
}

function renderGrid() {
  if (currentView === 'day') renderDayGrid();
  else if (currentView === 'month') renderMonthGrid();
  else renderWeekGrid();
  renderLegend();

