const cols = 7;
const dayNames = ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];

headers.style.gridTemplateColumns = `repeat(${cols}, 1fr)`;
headers.innerHTML = dayNames.map(d => `<div class="cal-col-header"><div class="ch-wday">${d}</div></div>`).join('');

grid.style.gridTemplateColumns = `repeat(${cols}, 1fr)`;
grid.style.gridAutoRows = 'minmax(90px, auto)';

// Build grid from Mon before month start to Sun after month end
const firstDay = new Date(monthStart);
const startCell = new Date(firstDay);
startCell.setDate(startCell.getDate() - ((firstDay.getDay() + 6) % 7));
const lastDay = new Date(monthStart.getFullYear(), monthStart.getMonth() + 1, 0);
const endCell = new Date(lastDay);
const extra = (7 - ((lastDay.getDay() + 6) % 7 + 1)) % 7;
endCell.setDate(endCell.getDate() + extra);

grid.innerHTML = '';
const cur = new Date(startCell);
const vis = getVisibleSessions();
while (cur <= endCell) {
  const cellDate = new Date(cur); cellDate.setHours(0,0,0,0);
  const isThisMonth = cellDate.getMonth() === monthStart.getMonth();
  const isToday = cellDate.toDateString() === today.toDateString();
  const isHoliday = holidayDates.has(cellDate.toISOString().slice(0,10));
  const dateStr = cellDate.toISOString().slice(0,10);

  const daySessions = vis.filter(s => {
    const st = new Date(s.startTime); st.setHours(0,0,0,0);
    return st.toDateString() === cellDate.toDateString();
  }).sort((a,b) => new Date(a.startTime) - new Date(b.startTime));

  const cell = document.createElement('div');
  cell.className = 'cal-month-cell' + (isThisMonth ? '' : ' other-month') + (isToday ? ' today-cell' : '') + (isHoliday ? ' holiday-cell' : '');
  cell.setAttribute('data-date', dateStr);

  const num = document.createElement('div');
  num.className = 'cal-month-num' + (isToday ? ' today' : '');
  num.textContent = cellDate.getDate();
  cell.appendChild(num);

  const evList = document.createElement('div');
  evList.className = 'cal-month-ev-list';
  const MAX_SHOW = 3;
  daySessions.slice(0, MAX_SHOW).forEach(s => {
    const ev = document.createElement('div');
    ev.className = 'cal-month-ev ' + (s.status === 'BLOCKED' ? 'blocked' : (s.format || 'GROUP').toLowerCase());
    const st = new Date(s.startTime);
    ev.textContent = `${st.getHours().toString().padStart(2,'0')}:${st.getMinutes().toString().padStart(2,'0')} ${s.blueprintName || s.format || ''}`;
    ev.title = `${s.blueprintName || ''} — ${fmtHour(st.getHours())}`;
    ev.addEventListener('click', (e) => { e.stopPropagation(); openEventDetail(s, ev); });
    evList.appendChild(ev);
  });
  if (daySessions.length > MAX_SHOW) {
    const more = document.createElement('div');
    more.className = 'cal-month-more';
    more.textContent = `+${daySessions.length - MAX_SHOW} more`;
    evList.appendChild(more);
  }

