1	using System.Security.Cryptography;
2	using System.Text;
3	using System.Threading.Channels;
4	using Microsoft.Extensions.Logging;
5	using MongoDB.Driver;
6	using SoulPilates.Core.Configuration;
7	using SoulPilates.Core.Entities;
8	using SoulPilates.Core.Interfaces;
9	using SoulPilates.Infrastructure.Data;
10	using Microsoft.Extensions.Options;
11	
12	namespace SoulPilates.Services;
13	
14	/// <summary>
15	/// Manages the <c>PushSubscriptions</c> Mongo collection and hands payloads
16	/// off to <see cref="PushDispatcherService"/> via an in-process channel.
17	///
18	/// <para>Why a channel and not "just await SendAsync inline"?</para>
19	/// Sending a push payload is a network call to FCM/APNs/Mozilla. We don't
20	/// want the booking POST to block on that — the user sees nothing useful
21	/// from a "delivery confirmed" round-trip and a transient hiccup against
22	/// FCM shouldn't fail the booking. The channel decouples the two and gives
23	/// us natural retry headroom.
24	/// </summary>
25	public class PushService : IPushService
26	{
27	    private readonly IMongoCollection<PushSubscription> _subs;
28	    private readonly WebPushSettings _settings;
29	    private readonly Channel<PushJob> _outbox;
30	    private readonly ILogger<PushService> _logger;
31	
32	    public PushService(
33	        MongoDbContext dbContext,
34	        IOptions<WebPushSettings> settings,
35	        Channel<PushJob> outbox,
36	        ILogger<PushService> logger)
37	    {
38	        _subs = dbContext.GetCollection<PushSubscription>("PushSubscriptions");
39	        _settings = settings.Value;
40	        _outbox = outbox;
41	        _logger = logger;
42	
43	        // Best-effort index ensure. The Mongo driver caches the result so
44	        // this is effectively a no-op after the first call. Failures (e.g.
45	        // index already exists with different opts) log but don't crash —
46	        // the collection still works fine without these.
47	        try
48	        {
49	            _subs.Indexes.CreateOne(new CreateIndexModel<PushSubscription>(
50	                Builders<PushSubscription>.IndexKeys.Ascending(s => s.UserId)));
51	            _subs.Indexes.CreateOne(new CreateIndexModel<PushSubscription>(
52	                Builders<PushSubscription>.IndexKeys.Ascending(s => s.EndpointHash),
53	                new CreateIndexOptions { Unique = true }));
54	        }
55	        catch (Exception ex)
56	        {
57	            _logger.LogWarning(ex, "Could not ensure PushSubscriptions indexes");
58	        }
59	    }
60	
61	    public string GetVapidPublicKey() => _settings.PublicKey;
62	
63	    public async Task<PushSubscription> SubscribeAsync(string userId, SubscribePushRequest request, string? userAgent)
64	    {
65	        if (string.IsNullOrWhiteSpace(request.Endpoint))
66	            throw new ArgumentException("Endpoint is required.", nameof(request));
67	        if (request.Keys is null || string.IsNullOrWhiteSpace(request.Keys.P256dh) || string.IsNullOrWhiteSpace(request.Keys.Auth))
68	            throw new ArgumentException("Keys.p256dh and keys.auth are required.", nameof(request));
69	
70	        var hash = HashEndpoint(request.Endpoint);
71	
72	        // Atomic upsert keyed by EndpointHash. Same browser × same user
73	        // re-subscribing (e.g. after a permission reset) refreshes the
74	        // Keys + UserAgent rather than spawning duplicate rows.
75	        // Using ReplaceOneAsync with IsUpsert avoids the race condition
76	        // where a Find-then-Insert can hit a DuplicateKey error when two
77	        // concurrent requests both pass the Find check.
78	        var sub = new PushSubscription
79	        {
80	            // Pre-generate an ObjectId so MongoDB never inserts _id:null.
81	            // On upsert-update this is ignored (existing doc keeps its _id).
82	            Id = MongoDB.Bson.ObjectId.GenerateNewId().ToString(),
83	            UserId = userId,
84	            Endpoint = request.Endpoint,
85	            EndpointHash = hash,
86	            P256dh = request.Keys.P256dh,
87	            Auth = request.Keys.Auth,
88	            UserAgent = userAgent,
89	            ConsecutiveFailures = 0,
90	        };
91	
92	        var result = await _subs.ReplaceOneAsync(
93	            s => s.EndpointHash == hash,
94	            sub,
95	            new ReplaceOptions { IsUpsert = true });
96	
97	        // If we updated an existing doc, preserve its original Id
98	        if (result.UpsertedId is not null)
99	            sub.Id = result.UpsertedId.ToString()!;
100	
101	        return sub;
102	    }
103	
104	    public async Task UnsubscribeAsync(string userId, string endpoint)
105	    {
106	        var hash = HashEndpoint(endpoint);
107	        await _subs.DeleteOneAsync(s => s.UserId == userId && s.EndpointHash == hash);
108	    }
109	
110	    public async Task<IReadOnlyList<PushSubscription>> ListMyDevicesAsync(string userId)
111	    {
112	        return await _subs.Find(s => s.UserId == userId).ToListAsync();
113	    }
114	
115	    public async Task<int> EnqueueAsync(string userId, PushPayload payload)
116	    {
117	        // If the operator hasn't configured VAPID, silently skip — the email
118	        // fallback path in NotificationPublisher will pick up the slack.
119	        if (!_settings.Enabled || string.IsNullOrWhiteSpace(_settings.PublicKey))
120	            return 0;
121	
122	        var subs = await _subs.Find(s => s.UserId == userId).ToListAsync();
123	        if (subs.Count == 0) return 0;
124	
125	        foreach (var sub in subs)
126	        {
127	            // Channel.Writer.WriteAsync would await if the channel is bounded
128	            // and full. We use an unbounded channel (see Program.cs) because
129	            // the volume is small and we'd rather use a touch of memory than
130	            // block a booking POST waiting on FCM.
131	            await _outbox.Writer.WriteAsync(new PushJob(sub, payload));
132	        }
133	        return subs.Count;
134	    }
135	
136	    // ── Helpers ─────────────────────────────────────────────────────────
137	
138	    private static string HashEndpoint(string endpoint)
139	    {
140	        var bytes = SHA256.HashData(Encoding.UTF8.GetBytes(endpoint));
141	        return Convert.ToHexString(bytes);
142	    }
143	}
144	
145	/// <summary>One queued delivery: which subscription + what to send.</summary>
146	public record PushJob(PushSubscription Subscription, PushPayload Payload);
147

