using System.Net;
using System.Text.Json;
using System.Threading.Channels;
using Lib.Net.Http.WebPush;
using Lib.Net.Http.WebPush.Authentication;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using MongoDB.Driver;
using SoulPilates.Core.Configuration;
using SoulPilates.Core.Entities;
using SoulPilates.Infrastructure.Data;
using SpEntities = SoulPilates.Core.Entities;
using LibWebPush = Lib.Net.Http.WebPush;

namespace SoulPilates.Services;

/// <summary>
/// Background worker that drains <see cref="Channel{PushJob}"/> and pushes
/// each payload through <see cref="LibWebPush.PushServiceClient"/>.
///
/// <para>Failure handling:</para>
/// <list type="bullet">
///   <item><description>HTTP 410 Gone / 404 Not Found → endpoint is dead;
///   delete the subscription so it never fires again.</description></item>
///   <item><description>Any other failure → bump ConsecutiveFailures.
///   At 5+ we delete the subscription (covers misconfigured proxies, network
///   blackholes, etc. without retrying forever).</description></item>
///   <item><description>Successful delivery → reset ConsecutiveFailures and
///   stamp LastDeliveredAt.</description></item>
/// </list>
/// </summary>
public class PushDispatcherService : BackgroundService
{
    private readonly Channel<PushJob> _outbox;
    private readonly WebPushSettings _settings;
    private readonly IMongoCollection<SpEntities.PushSubscription> _subs;
    private readonly ILogger<PushDispatcherService> _logger;

    private readonly LibWebPush.PushServiceClient _client = new();
    private readonly VapidAuthentication? _vapid;

    public PushDispatcherService(
        Channel<PushJob> outbox,
        IOptions<WebPushSettings> settings,
        MongoDbContext dbContext,
        ILogger<PushDispatcherService> logger)
    {
        _outbox = outbox;
        _settings = settings.Value;
        _subs = dbContext.GetCollection<SpEntities.PushSubscription>("PushSubscriptions");
        _logger = logger;

        if (_settings.Enabled
            && !string.IsNullOrWhiteSpace(_settings.PublicKey)
            && !string.IsNullOrWhiteSpace(_settings.PrivateKey))
        {
            _vapid = new VapidAuthentication(_settings.PublicKey, _settings.PrivateKey)
            {
                Subject = _settings.Subject,
            };
        }
        else
        {
            _logger.LogWarning("WebPush is disabled or VAPID keys missing — push deliveries will be no-ops.");
        }
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        await foreach (var job in _outbox.Reader.ReadAllAsync(stoppingToken))
        {
            // Fire-and-await per job. The channel is single-consumer here so
            // we don't accidentally parallel-blow FCM; if throughput becomes
            // an issue we can spin up N readers.
            try
            {
                await DispatchAsync(job, stoppingToken);
            }
            catch (Exception ex) when (ex is not OperationCanceledException)
            {
                _logger.LogError(ex, "Unhandled error in push dispatcher");
            }
        }
    }

    private async Task DispatchAsync(PushJob job, CancellationToken ct)
    {
        if (_vapid is null) return;

        var (sub, payload) = (job.Subscription, job.Payload);

        // Map our entity → Lib.Net.Http.WebPush's expected wire format.
        var libSub = new LibWebPush.PushSubscription
        {
            Endpoint = sub.Endpoint,
        };
        libSub.SetKey(PushEncryptionKeyName.P256DH, sub.P256dh);
        libSub.SetKey(PushEncryptionKeyName.Auth, sub.Auth);

        var json = JsonSerializer.Serialize(payload, new JsonSerializerOptions
        {
            PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
            DefaultIgnoreCondition = System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull,
        });

        var message = new PushMessage(json)
        {
            // Tell the push service to keep this message for 24h if the
            // device is offline. The default is shorter and we'd rather
            // the instructor see a missed booking when they come back online.
            TimeToLive = (int)TimeSpan.FromHours(24).TotalSeconds,
            Topic = payload.Tag, // FCM uses this to collapse pings of the same kind
        };

        try
        {
            await _client.RequestPushMessageDeliveryAsync(libSub, message, _vapid, ct);
            // Success → reset failure counter + stamp delivery time.
            var update = Builders<SpEntities.PushSubscription>.Update
                .Set(s => s.LastDeliveredAt, DateTime.UtcNow)
                .Set(s => s.ConsecutiveFailures, 0);
            await _subs.UpdateOneAsync(s => s.Id == sub.Id, update, cancellationToken: ct);
        }
        catch (PushServiceClientException ex) when (
            ex.StatusCode == HttpStatusCode.Gone || ex.StatusCode == HttpStatusCode.NotFound)
        {
            // Endpoint is dead — user uninstalled, cleared data, or revoked
            // permission. Permanently remove so we never try again.
            await _subs.DeleteOneAsync(s => s.Id == sub.Id, ct);
            _logger.LogInformation("Pruned dead push subscription {Id} ({Status}) for user {UserId}",
                sub.Id, ex.StatusCode, sub.UserId);
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex, "Push delivery failed for subscription {Id}", sub.Id);

            // Soft-failure path: bump the counter; prune at 5.
            var update = Builders<SpEntities.PushSubscription>.Update
                .Inc(s => s.ConsecutiveFailures, 1);
            await _subs.UpdateOneAsync(s => s.Id == sub.Id, update, cancellationToken: ct);

            var refreshed = await _subs.Find(s => s.Id == sub.Id).FirstOrDefaultAsync(ct);
            if (refreshed is not null && refreshed.ConsecutiveFailures >= 5)
            {
                await _subs.DeleteOneAsync(s => s.Id == sub.Id, ct);
                _logger.LogWarning("Pruned push subscription {Id} after 5 consecutive failures", sub.Id);
            }
        }
    }
}

