            Endpoint = sub.Endpoint,
        };
        libSub.SetKey(PushEncryptionKeyName.P256DH, sub.P256dh);
        libSub.SetKey(PushEncryptionKeyName.Auth, sub.Auth);

        var json = JsonSerializer.Serialize(payload, new JsonSerializerOptions
        {
            PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
            DefaultIgnoreCondition = System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull,
        });

        var message = new PushMessage(json)
        {
            // Tell the push service to keep this message for 24h if the
            // device is offline. The default is shorter and we'd rather
            // the instructor see a missed booking when they come back online.
            TimeToLive = (int)TimeSpan.FromHours(24).TotalSeconds,
            Topic = payload.Tag, // FCM uses this to collapse pings of the same kind
        };

        try
        {
            await _client.RequestPushMessageDeliveryAsync(libSub, message, _vapid, ct);
            // Success → reset failure counter + stamp delivery time.
            var update = Builders<SpEntities.PushSubscription>.Update
                .Set(s => s.LastDeliveredAt, DateTime.UtcNow)
                .Set(s => s.ConsecutiveFailures, 0);
            await _subs.UpdateOneAsync(s => s.Id == sub.Id, update, cancellationToken: ct);
        }
        catch (PushServiceClientException ex) when (
            ex.StatusCode == HttpStatusCode.Gone || ex.StatusCode == HttpStatusCode.NotFound)
        {
            // Endpoint is dead — user uninstalled, cleared data, or revoked
            // permission. Permanently remove so we never try again.
            await _subs.DeleteOneAsync(s => s.Id == sub.Id, ct);
            _logger.LogInformation("Pruned dead push subscription {Id} ({Status}) for user {UserId}",
                sub.Id, ex.StatusCode, sub.UserId);
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex, "Push delivery failed for subscription {Id}", sub.Id);

            // Soft-failure path: bump the counter; prune at 5.
            var update = Builders<SpEntities.PushSubscription>.Update
                .Inc(s => s.ConsecutiveFailures, 1);
            await _subs.UpdateOneAsync(s => s.Id == sub.Id, update, cancellationToken: ct);

            var refreshed = await _subs.Find(s => s.Id == sub.Id).FirstOrDefaultAsync(ct);
            if (refreshed is not null && refreshed.ConsecutiveFailures >= 5)
            {
                await _subs.DeleteOneAsync(s => s.Id == sub.Id, ct);
                _logger.LogWarning("Pruned push subscription {Id} after 5 consecutive failures", sub.Id);
            }
        }
    }
}

