426	      // ── PWA Service Worker + Install Prompt ──
427	      (function() {
428	        var DISMISSED_KEY = 'sp_pwa_banner_dismissed';
429	
430	        // Register service worker
431	        if ('serviceWorker' in navigator && window.isSecureContext) {
432	          window.addEventListener('load', function() {
433	            navigator.serviceWorker.register('/sw.js', { scope: '/' }).catch(function() {});
434	          });
435	        }
436	
437	        // Don't show banner if already installed (standalone mode) or dismissed recently
438	        if (window.matchMedia('(display-mode: standalone)').matches) return;
439	        if (window.navigator.standalone === true) return; // iOS standalone
440	        var dismissed = localStorage.getItem(DISMISSED_KEY);
441	        if (dismissed && (Date.now() - parseInt(dismissed)) < 7 * 24 * 60 * 60 * 1000) return;
442	
443	        var isIOS = /iphone|ipad|ipod/i.test(navigator.userAgent) && !window.MSStream;
444	        var isSafari = /^((?!chrome|android).)*safari/i.test(navigator.userAgent);
445	
446	        // iOS: show instruction banner in Safari only
447	        if (isIOS && isSafari) {
448	          var iosBanner = document.getElementById('iosInstallBanner');
449	          if (iosBanner) {
450	            iosBanner.style.display = 'block';
451	            document.getElementById('iosInstallDismiss').addEventListener('click', function() {
452	              iosBanner.style.display = 'none';
453	              localStorage.setItem(DISMISSED_KEY, Date.now().toString());
454	            });
455	          }
456	          return;
457	        }
458	
459	        // Android/Chrome: capture and show install prompt
460	        var deferredPrompt = null;
461	        window.addEventListener('beforeinstallprompt', function(e) {
462	          e.preventDefault();
463	          deferredPrompt = e;
464	          var banner = document.getElementById('pwaInstallBanner');
465	          if (banner) banner.style.display = 'flex';
466	        });
467	
468	        document.getElementById('pwaInstallBtn')?.addEventListener('click', function() {
469	          if (!deferredPrompt) return;
470	          deferredPrompt.prompt();
471	          deferredPrompt.userChoice.then(function() {
472	            deferredPrompt = null;
473	            var banner = document.getElementById('pwaInstallBanner');
474	            if (banner) banner.style.display = 'none';
475	          });
476	        });
477	
