/* ── Format row: toggle left, credits right ── */
.sp-format-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: var(--sp-space-xl);
}

/* ── Credits badge ── */
.sp-credits-badge {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  align-items: center;
}
.sp-credits-badge-count {
  display: inline-flex;
  align-items: center;
  padding: 8px 14px;
  border-radius: 10px;
  border: 1.5px solid var(--sp-accent);
  background: rgba(167, 110, 76, 0.08);
  color: var(--sp-accent);
  font-size: 13px;
  font-weight: 600;
  white-space: nowrap;
}

/* ── Format Toggle (Group / Private) ── */
.sp-format-toggle {
  display: flex;
  gap: 0;
  background: var(--sp-surface-raised);
  border-radius: var(--sp-radius-lg);
  padding: 4px;
  border: 1.5px solid var(--sp-border);
  width: fit-content;
}

.sp-format-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 24px;
  border: none;

