/* ── Credits card ── */
.sp-credits-card {
  background: var(--sp-surface);
  border: 1.5px solid var(--sp-border);
  border-radius: 16px;
  padding: 14px 18px;
  min-width: 220px;
}
.sp-credits-card-header {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 12px;
  color: var(--sp-accent);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.sp-credits-card-header svg {
  width: 15px;
  height: 15px;
  flex-shrink: 0;
}
.sp-credits-items {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}
.sp-credits-item {
  display: flex;
  align-items: center;
  gap: 10px;
}
.sp-credits-item + .sp-credits-item {
  padding-left: 16px;
  border-left: 1px solid var(--sp-border);
}
.sp-credits-item-icon {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(167, 110, 76, 0.1);
  color: var(--sp-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.sp-credits-item-icon svg {
  width: 18px;
  height: 18px;
}
.sp-credits-item-body {
  display: flex;
  flex-direction: column;
  line-height: 1.2;
}
.sp-credits-item-count {
  font-size: 22px;
  font-weight: 800;
  color: var(--sp-text-primary);
  letter-spacing: -0.5px;
}
.sp-credits-item-label {
  font-size: 11px;
  color: var(--sp-text-muted);
  font-weight: 500;
  white-space: nowrap;
}

@media (max-width: 600px) {
  .sp-format-row {
    flex-direction: column;
    align-items: stretch;
  }
  .sp-credits-card {
    min-width: 0;
    width: 100%;
  }
  .sp-credits-items {
    justify-content: space-between;
  }
  .sp-credits-item + .sp-credits-item {
    border-left: 1px solid var(--sp-border);
  }
}

