---
import "../styles/customer.css";

export interface Props {
  title: string;
  activePage?: string;
  description?: string;
}
const {
  title,
  activePage = "",
  description = "Book your Pilates class at Soul Pilates Da Nang",
} = Astro.props;

// Resolved at build time — safe to use in is:inline via meta tag injection
const publicApiUrl = import.meta.env.PUBLIC_API_URL || '';
---

<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta
      name="viewport"
      content="width=device-width, initial-scale=1.0, viewport-fit=cover"
    />
    <title>{title} — Soul Pilates Da Nang</title>
    <meta name="description" content={description} />
    <!-- API base URL injected at build time for use by is:inline scripts -->
    <meta name="api-url" content={publicApiUrl} />
    <link rel="preconnect" href="https://fonts.googleapis.com" />
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
    <link
      href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap"
      rel="stylesheet"
    />
    <link rel="icon" type="image/svg+xml" href="/favicon.svg" />
    <link rel="apple-touch-icon" href="/icons/icon-192.png" />
    <link rel="manifest" href="/customer-manifest.webmanifest" />
    <meta name="theme-color" content="#C97B4B" />
    <meta name="apple-mobile-web-app-capable" content="yes" />
    <meta name="apple-mobile-web-app-status-bar-style" content="default" />
    <meta name="apple-mobile-web-app-title" content="Soul Pilates" />
    <meta name="mobile-web-app-capable" content="yes" />
  </head>
  <body class="sp-customer">
    <a class="sp-skip-link" href="#mainContent" data-i18n="common.skipToContent"
      >Skip to main content</a
    >

    <!-- ── Desktop Top Navigation ── -->
    <nav class="sp-topnav" id="spTopnav">
      <a href="/" class="sp-topnav-logo">
        <img src="/logo.png" alt="Soul Pilates" class="sp-logo-img" />
      </a>

      <ul class="sp-topnav-links">
        <li>
          <a
            href="/booking"
            class={activePage === "booking" ? "active" : ""}
            data-i18n="nav.bookClass">Book a Class</a>
        </li>
        <li>
          <a
            href="/packages"
            class={activePage === "store" ? "active" : ""}
            data-i18n="nav.buyPackages">Buy Packages</a>
        </li>
        <li>
          <a
            href="/my-bookings"
            class={activePage === "bookings" ? "active" : ""}
            data-i18n="nav.myBookings">My Bookings</a>
        </li>
        <li>
          <a
            href="/my-package"
            class={activePage === "packages" ? "active" : ""}
            data-i18n="nav.myPackages">My Packages</a>
        </li>
      </ul>

      <div class="sp-topnav-right">
        <!-- Language Toggle -->
        <button
          class="sp-btn-ghost sp-btn-sm"
          id="langToggle"
          onclick="toggleLang()"
          style="font-size:12px;letter-spacing:0.5px;"
        >
          EN / VI
        </button>
        <!-- User Avatar (shown when logged in) -->
        <a
          href="/account"
          class="sp-avatar"
          id="userAvatar"
          style="display:none;"
          title="My Account"
        >
          <span id="userInitials"></span>
        </a>
        <!-- Auth links (shown when not logged in) -->
        <div id="loginBtn" style="display:flex;align-items:center;gap:6px;">
          <a
            href="/register"
            class="sp-btn sp-btn-ghost sp-btn-sm"
            style="font-size:12px;"
            data-i18n="auth.signUp">Sign Up</a
          >
          <a
            href="/login"
            class="sp-btn sp-btn-primary sp-btn-sm"
            style="font-size:12px;"
            data-i18n="auth.logIn">Log In</a
          >
        </div>
      </div>
    </nav>

    <!-- ── Mobile Header ── -->
    <header class="sp-mobile-header sp-hidden-desktop" id="spMobileHeader">
      <a href="/booking" class="sp-topnav-logo">
        <img
          src="/logo.png"
          alt="Soul Pilates"
          class="sp-logo-img"
          style="height:28px;"
        />
      </a>
      <div style="display:flex;align-items:center;gap:8px;">
        <button
          class="sp-btn-ghost sp-btn-sm"
          id="langToggleMobile"
          onclick="toggleLang()"
          style="font-size:11px;padding:4px 8px;"
        >
          EN / VI
        </button>
        <a
          href="/account"
          class="sp-avatar"
          id="userAvatarMobile"
          style="display:none;width:28px;height:28px;font-size:10px;"
          title="My Account"
        >
          <span id="userInitialsMobile"></span>
        </a>
        <a
          href="/login"
          class="sp-btn sp-btn-primary sp-btn-sm"
          id="loginBtnMobile"
          style="font-size:11px;padding:4px 10px;"
          data-i18n="auth.logIn">Log In</a
        >
      </div>
    </header>

    <!-- ── Main Content ── -->
    <main class="sp-main" id="mainContent" tabindex="-1">
      <slot />
    </main>

    <!-- ── Mobile Bottom Tab Bar ── -->
    <nav class="sp-bottomnav" id="spBottomnav">
      <div class="sp-bottomnav-inner">
        <a
          href="/booking"
          class={`sp-bottomnav-item ${activePage === "booking" ? "active" : ""}`}
        >
          <svg
            xmlns="http://www.w3.org/2000/svg"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="1.5"
            stroke-linecap="round"
            stroke-linejoin="round"
          >
            <rect x="3" y="4" width="18" height="18" rx="2"></rect><line
              x1="16"
              y1="2"
              x2="16"
              y2="6"></line><line x1="8" y1="2" x2="8" y2="6"></line><line
              x1="3"
              y1="10"
              x2="21"
              y2="10"></line>
          </svg>
          <span data-i18n="nav.bookClass">Book</span>
        </a>
        <a
          href="/packages"
          class={`sp-bottomnav-item ${activePage === "store" ? "active" : ""}`}
        >
          <svg
            xmlns="http://www.w3.org/2000/svg"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="1.5"
            stroke-linecap="round"
            stroke-linejoin="round"
          >
            <path d="M6 2L3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4z"
            ></path><line x1="3" y1="6" x2="21" y2="6"></line><path
              d="M16 10a4 4 0 0 1-8 0"></path>
          </svg>
          <span data-i18n="nav.buyShort">Buy</span>
        </a>
        <a
          href="/my-bookings"
          class={`sp-bottomnav-item ${activePage === "bookings" ? "active" : ""}`}
        >
          <svg
            xmlns="http://www.w3.org/2000/svg"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="1.5"
            stroke-linecap="round"
            stroke-linejoin="round"
          >
            <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"
            ></path><polyline points="14 2 14 8 20 8"></polyline><line
              x1="16"
              y1="13"
              x2="8"
              y2="13"></line><line x1="16" y1="17" x2="8" y2="17"></line>
          </svg>
          <span data-i18n="nav.myBookings">Bookings</span>
        </a>
        <a
          href="/my-package"
          class={`sp-bottomnav-item ${activePage === "packages" ? "active" : ""}`}
        >
          <svg
            xmlns="http://www.w3.org/2000/svg"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="1.5"
            stroke-linecap="round"
            stroke-linejoin="round"
          >
            <path
              d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"
            ></path>
          </svg>
          <span data-i18n="nav.mineShort">Mine</span>
        </a>
        <a
          href="/account"
          class={`sp-bottomnav-item ${activePage === "account" ? "active" : ""}`}
        >
          <svg
            xmlns="http://www.w3.org/2000/svg"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="1.5"
            stroke-linecap="round"
            stroke-linejoin="round"
          >
            <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"></path><circle
              cx="12"
              cy="7"
              r="4"></circle>
          </svg>
          <span data-i18n="nav.account">Account</span>
        </a>
      </div>
    </nav>

    <script is:inline>
      // ── i18n Inline Bootstrap ──
      // (Full module loaded per-page; this handles nav text on first paint)
      const SP_LANG_KEY = "sp_lang";

      function getSPLang() {
        return localStorage.getItem(SP_LANG_KEY) || "en";
      }

      function toggleLang() {
        const current = getSPLang();
        const next = current === "en" ? "vi" : "en";
        localStorage.setItem(SP_LANG_KEY, next);
        document.documentElement.setAttribute("lang", next);
        // Reload to apply translations (pages using the i18n module will handle reactively)
        window.location.reload();
      }

      // ── Auth State ──
      function checkAuth() {
        const token = localStorage.getItem("customer_token");
        const name = localStorage.getItem("customer_name") || "";
        const initials =
          name
            .split(" ")
            .map((n) => n[0])
            .join("")
            .substring(0, 2)
            .toUpperCase() || "?";

        if (token) {
          // Show avatar, hide login buttons
          const avatarEls = document.querySelectorAll(
            "#userAvatar, #userAvatarMobile",
          );
          avatarEls.forEach((el) => {
            el.style.display = "flex";
          });

          const initialEls = document.querySelectorAll(
            "#userInitials, #userInitialsMobile",
          );
          initialEls.forEach((el) => {
            el.textContent = initials;
          });

          const loginBtn = document.getElementById("loginBtn");
          if (loginBtn) loginBtn.style.display = "none";

          const loginBtnMobile = document.getElementById("loginBtnMobile");
          if (loginBtnMobile) loginBtnMobile.style.display = "none";
        }
      }

      // ── Init ──
      document.documentElement.setAttribute("lang", getSPLang());
      checkAuth();

      // Expose globally
      window.toggleLang = toggleLang;
      window.getSPLang = getSPLang;
    </script>

    <!-- ── Google Analytics 4 — Dynamic Loader & Funnel Tracker ── -->
    <script is:inline>
      // Loads GA4 gtag.js dynamically based on the admin-configured
      // Measurement ID. Fetched from public API so no secrets leak.
      // Full funnel tracking: page_view → view_class → begin_checkout → purchase
      (function initGA4() {
        // PUBLIC_API_URL is injected at build time into a <meta name="api-url"> tag.
        // We read it here because is:inline scripts are not processed by Vite
        // and cannot use import.meta.env (which caused a Firefox SyntaxError).
        var metaApi = document.querySelector('meta[name="api-url"]');
        var API_URL = metaApi ? metaApi.content : '';

        fetch(API_URL + '/api/analytics/ga-config')
          .then(function(res) { return res.ok ? res.json() : null; })
          .then(function(cfg) {
            if (!cfg || !cfg.measurementId) return;
            var gaId = cfg.measurementId;
            var enableEvents = cfg.enableEventTracking !== false;

            // 1. Inject gtag.js script
            var s = document.createElement('script');
            s.async = true;
            s.src = 'https://www.googletagmanager.com/gtag/js?id=' + gaId;
            document.head.appendChild(s);

            // 2. Initialize dataLayer + gtag
            window.dataLayer = window.dataLayer || [];
            function gtag() { window.dataLayer.push(arguments); }
            window.gtag = gtag;
            gtag('js', new Date());
            gtag('config', gaId, {
              page_path: window.location.pathname,
              send_page_view: true,
            });

            // 3. Expose event helper for pages to use
            window.spTrackEvent = function(eventName, params) {
              if (!enableEvents || typeof gtag !== 'function') return;
              gtag('event', eventName, params || {});
            };

            // 4. Track SPA-style navigations (if any)
            window.addEventListener('popstate', function() {
              gtag('config', gaId, { page_path: window.location.pathname });
            });
          })
          .catch(function(err) {
            // Silently fail — GA is non-critical
            console.debug('[GA4] Config fetch failed, analytics disabled:', err);
          });

        // Fallback no-op so pages can call spTrackEvent even if GA didn't load
        if (!window.spTrackEvent) {
          window.spTrackEvent = function() {};
        }
      })();
    </script>


    <script is:inline>
      // Suppress the PWA install prompt on the customer-facing site.
      // The installable PWA is the admin/staff app only.
      window.addEventListener('beforeinstallprompt', function(e) { e.preventDefault(); });
    </script>
  </body>
</html>

// Soul Pilates — service worker v2.0.0
//
// Intentionally minimal: push notifications only.
// All caching is delegated to the browser's native HTTP cache via
// Cache-Control headers set by nginx — no SW cache interception.
// This avoids the fetch-interception overhead that caused freezes on iOS.

const SW_VERSION = "v2.1.0";

// ── Install: take over immediately, no precache ──────────────────────────
self.addEventListener("install", (event) => {
  event.waitUntil(self.skipWaiting());
});

// ── Activate: clean up any old caches from v1.x, claim all clients ───────
self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.map((k) => caches.delete(k)));
      await self.clients.claim();
    })()
  );
});

// ── Push: show a notification ─────────────────────────────────────────────
self.addEventListener("push", (event) => {
  if (!event.data) return;

  let payload;
  try {
    payload = event.data.json();
  } catch {
    payload = { title: "Soul Pilates", body: event.data.text() };
  }

  const {
    title = "Soul Pilates",
    body = "",
    icon = "/icons/icon-192.png",
    badge = "/icons/icon-192.png",
    url = "/admin/",
    tag,
  } = payload;

  event.waitUntil(
    self.registration.showNotification(title, {
      body,
      icon,
      badge,
      tag,
      data: { url },
      requireInteraction: true,  // keep banner visible until user taps it
      vibrate: [200, 100, 200],  // short-pause-short pulse for visibility
    })
  );
});

// ── Notification click: focus existing window or open a new one ───────────
self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const targetUrl =
    (event.notification.data && event.notification.data.url) || "/admin/";

  event.waitUntil(
    (async () => {
      const all = await self.clients.matchAll({
        type: "window",
        includeUncontrolled: true,
      });
      for (const client of all) {
        if (client.url.includes(self.location.origin)) {
          await client.focus();
          if ("navigate" in client) await client.navigate(targetUrl);
          return;
        }
      }
      await self.clients.openWindow(targetUrl);
    })()
  );
});

// ── Message: allow pages to trigger skipWaiting ───────────────────────────
self.addEventListener("message", (event) => {
  if (event.data && event.data.type === "SKIP_WAITING") {
    self.skipWaiting();
  }
});

using System.Net;
using System.Text.Json;
using System.Threading.Channels;
using Lib.Net.Http.WebPush;
using Lib.Net.Http.WebPush.Authentication;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using MongoDB.Driver;
using SoulPilates.Core.Configuration;
using SoulPilates.Core.Entities;
using SoulPilates.Infrastructure.Data;
using SpEntities = SoulPilates.Core.Entities;
using LibWebPush = Lib.Net.Http.WebPush;

namespace SoulPilates.Services;

/// <summary>
/// Background worker that drains <see cref="Channel{PushJob}"/> and pushes
/// each payload through <see cref="LibWebPush.PushServiceClient"/>.
///
/// <para>Failure handling:</para>
/// <list type="bullet">
///   <item><description>HTTP 410 Gone / 404 Not Found → endpoint is dead;
///   delete the subscription so it never fires again.</description></item>
///   <item><description>Any other failure → bump ConsecutiveFailures.
///   At 5+ we delete the subscription (covers misconfigured proxies, network
///   blackholes, etc. without retrying forever).</description></item>
///   <item><description>Successful delivery → reset ConsecutiveFailures and
///   stamp LastDeliveredAt.</description></item>
/// </list>
/// </summary>
public class PushDispatcherService : BackgroundService
{
    private readonly Channel<PushJob> _outbox;
    private readonly WebPushSettings _settings;
    private readonly IMongoCollection<SpEntities.PushSubscription> _subs;
    private readonly ILogger<PushDispatcherService> _logger;

    private readonly LibWebPush.PushServiceClient _client = new();
    private readonly VapidAuthentication? _vapid;

    public PushDispatcherService(
        Channel<PushJob> outbox,
        IOptions<WebPushSettings> settings,
        MongoDbContext dbContext,
        ILogger<PushDispatcherService> logger)
    {
        _outbox = outbox;
        _settings = settings.Value;
        _subs = dbContext.GetCollection<SpEntities.PushSubscription>("PushSubscriptions");
        _logger = logger;

        if (_settings.Enabled
            && !string.IsNullOrWhiteSpace(_settings.PublicKey)
            && !string.IsNullOrWhiteSpace(_settings.PrivateKey))
        {
            _vapid = new VapidAuthentication(_settings.PublicKey, _settings.PrivateKey)
            {
                Subject = _settings.Subject,
            };
        }
        else
        {
            _logger.LogWarning("WebPush is disabled or VAPID keys missing — push deliveries will be no-ops.");
        }
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        await foreach (var job in _outbox.Reader.ReadAllAsync(stoppingToken))
        {
            // Fire-and-await per job. The channel is single-consumer here so
            // we don't accidentally parallel-blow FCM; if throughput becomes
            // an issue we can spin up N readers.
            try
            {
                await DispatchAsync(job, stoppingToken);
            }
            catch (Exception ex) when (ex is not OperationCanceledException)
            {
                _logger.LogError(ex, "Unhandled error in push dispatcher");
            }
        }
    }

    private async Task DispatchAsync(PushJob job, CancellationToken ct)
    {
        if (_vapid is null) return;

        var (sub, payload) = (job.Subscription, job.Payload);

        // Map our entity → Lib.Net.Http.WebPush's expected wire format.
        var libSub = new LibWebPush.PushSubscription
        {
            Endpoint = sub.Endpoint,
        };
        libSub.SetKey(PushEncryptionKeyName.P256DH, sub.P256dh);
        libSub.SetKey(PushEncryptionKeyName.Auth, sub.Auth);

        var json = JsonSerializer.Serialize(payload, new JsonSerializerOptions
        {
            PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
            DefaultIgnoreCondition = System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull,
        });

        var message = new PushMessage(json)
        {
            // Tell the push service to keep this message for 24h if the
            // device is offline. The default is shorter and we'd rather
            // the instructor see a missed booking when they come back online.
            TimeToLive = (int)TimeSpan.FromHours(24).TotalSeconds,
            Topic = payload.Tag, // FCM uses this to collapse pings of the same kind
            // High urgency → FCM/APNs delivers immediately and shows a banner
            // (vs Normal which lets the OS defer to battery-saving state and
            // may silently drop the notification into the notification shade).
            Urgency = PushMessageUrgency.High,
        };

        try
        {
            await _client.RequestPushMessageDeliveryAsync(libSub, message, _vapid, ct);
            // Success → reset failure counter + stamp delivery time.
            var update = Builders<SpEntities.PushSubscription>.Update
                .Set(s => s.LastDeliveredAt, DateTime.UtcNow)
                .Set(s => s.ConsecutiveFailures, 0);
            await _subs.UpdateOneAsync(s => s.Id == sub.Id, update, cancellationToken: ct);
        }
        catch (PushServiceClientException ex) when (
            ex.StatusCode == HttpStatusCode.Gone || ex.StatusCode == HttpStatusCode.NotFound)
        {
            // Endpoint is dead — user uninstalled, cleared data, or revoked
            // permission. Permanently remove so we never try again.
            await _subs.DeleteOneAsync(s => s.Id == sub.Id, ct);
            _logger.LogInformation("Pruned dead push subscription {Id} ({Status}) for user {UserId}",
                sub.Id, ex.StatusCode, sub.UserId);
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex, "Push delivery failed for subscription {Id}", sub.Id);

            // Soft-failure path: bump the counter; prune at 5.
            var update = Builders<SpEntities.PushSubscription>.Update
                .Inc(s => s.ConsecutiveFailures, 1);
            await _subs.UpdateOneAsync(s => s.Id == sub.Id, update, cancellationToken: ct);

            var refreshed = await _subs.Find(s => s.Id == sub.Id).FirstOrDefaultAsync(ct);
            if (refreshed is not null && refreshed.ConsecutiveFailures >= 5)
            {
                await _subs.DeleteOneAsync(s => s.Id == sub.Id, ct);
                _logger.LogWarning("Pruned push subscription {Id} after 5 consecutive failures", sub.Id);
            }
        }
    }
}

using System.Security.Cryptography;
using System.Text;
using System.Threading.Channels;
using Microsoft.Extensions.Logging;
using MongoDB.Driver;
using SoulPilates.Core.Configuration;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Interfaces;
using SoulPilates.Infrastructure.Data;
using Microsoft.Extensions.Options;

namespace SoulPilates.Services;

/// <summary>
/// Manages the <c>PushSubscriptions</c> Mongo collection and hands payloads
/// off to <see cref="PushDispatcherService"/> via an in-process channel.
///
/// <para>Why a channel and not "just await SendAsync inline"?</para>
/// Sending a push payload is a network call to FCM/APNs/Mozilla. We don't
/// want the booking POST to block on that — the user sees nothing useful
/// from a "delivery confirmed" round-trip and a transient hiccup against
/// FCM shouldn't fail the booking. The channel decouples the two and gives
/// us natural retry headroom.
/// </summary>
public class PushService : IPushService
{
    private readonly IMongoCollection<PushSubscription> _subs;
    private readonly WebPushSettings _settings;
    private readonly Channel<PushJob> _outbox;
    private readonly ILogger<PushService> _logger;

    public PushService(
        MongoDbContext dbContext,
        IOptions<WebPushSettings> settings,
        Channel<PushJob> outbox,
        ILogger<PushService> logger)
    {
        _subs = dbContext.GetCollection<PushSubscription>("PushSubscriptions");
        _settings = settings.Value;
        _outbox = outbox;
        _logger = logger;

        // Best-effort index ensure. The Mongo driver caches the result so
        // this is effectively a no-op after the first call. Failures (e.g.
        // index already exists with different opts) log but don't crash —
        // the collection still works fine without these.
        try
        {
            _subs.Indexes.CreateOne(new CreateIndexModel<PushSubscription>(
                Builders<PushSubscription>.IndexKeys.Ascending(s => s.UserId)));
            _subs.Indexes.CreateOne(new CreateIndexModel<PushSubscription>(
                Builders<PushSubscription>.IndexKeys.Ascending(s => s.EndpointHash),
                new CreateIndexOptions { Unique = true }));
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex, "Could not ensure PushSubscriptions indexes");
        }
    }

    public string GetVapidPublicKey() => _settings.PublicKey;

    public async Task<PushSubscription> SubscribeAsync(string userId, SubscribePushRequest request, string? userAgent)
    {
        if (string.IsNullOrWhiteSpace(request.Endpoint))
            throw new ArgumentException("Endpoint is required.", nameof(request));
        if (request.Keys is null || string.IsNullOrWhiteSpace(request.Keys.P256dh) || string.IsNullOrWhiteSpace(request.Keys.Auth))
            throw new ArgumentException("Keys.p256dh and keys.auth are required.", nameof(request));

        var hash = HashEndpoint(request.Endpoint);

        // Atomic upsert keyed by EndpointHash. Same browser × same user
        // re-subscribing (e.g. after a permission reset) refreshes the
        // Keys + UserAgent rather than spawning duplicate rows.
        // Using ReplaceOneAsync with IsUpsert avoids the race condition
        // where a Find-then-Insert can hit a DuplicateKey error when two
        // concurrent requests both pass the Find check.
        var sub = new PushSubscription
        {
            // Pre-generate an ObjectId so MongoDB never inserts _id:null.
            // On upsert-update this is ignored (existing doc keeps its _id).
            Id = MongoDB.Bson.ObjectId.GenerateNewId().ToString(),
            UserId = userId,
            Endpoint = request.Endpoint,
            EndpointHash = hash,
            P256dh = request.Keys.P256dh,
            Auth = request.Keys.Auth,
            UserAgent = userAgent,
            ConsecutiveFailures = 0,
        };

        var result = await _subs.ReplaceOneAsync(
            s => s.EndpointHash == hash,
            sub,
            new ReplaceOptions { IsUpsert = true });

        // If we updated an existing doc, preserve its original Id
        if (result.UpsertedId is not null)
            sub.Id = result.UpsertedId.ToString()!;

        return sub;
    }

    public async Task UnsubscribeAsync(string userId, string endpoint)
    {
        var hash = HashEndpoint(endpoint);
        await _subs.DeleteOneAsync(s => s.UserId == userId && s.EndpointHash == hash);
    }

    public async Task<IReadOnlyList<PushSubscription>> ListMyDevicesAsync(string userId)
    {
        return await _subs.Find(s => s.UserId == userId).ToListAsync();
    }

    public async Task<int> EnqueueAsync(string userId, PushPayload payload)
    {
        // If the operator hasn't configured VAPID, silently skip — the email
        // fallback path in NotificationPublisher will pick up the slack.
        if (!_settings.Enabled || string.IsNullOrWhiteSpace(_settings.PublicKey))
            return 0;

        var subs = await _subs.Find(s => s.UserId == userId).ToListAsync();
        if (subs.Count == 0) return 0;

        foreach (var sub in subs)
        {
            // Channel.Writer.WriteAsync would await if the channel is bounded
            // and full. We use an unbounded channel (see Program.cs) because
            // the volume is small and we'd rather use a touch of memory than
            // block a booking POST waiting on FCM.
            await _outbox.Writer.WriteAsync(new PushJob(sub, payload));
        }
        return subs.Count;
    }

    // ── Helpers ─────────────────────────────────────────────────────────

    private static string HashEndpoint(string endpoint)
    {
        var bytes = SHA256.HashData(Encoding.UTF8.GetBytes(endpoint));
        return Convert.ToHexString(bytes);
    }
}

/// <summary>One queued delivery: which subscription + what to send.</summary>
public record PushJob(PushSubscription Subscription, PushPayload Payload);

