    ]);
    if (!sessionRes.ok) throw new Error("Session not found");
    // The /class/{id} endpoint returns a wrapped envelope:
    //   { session: {...}, blueprint: {...}, instructor: {...} }
    // We flatten it onto a single object the rest of this script can read with
    // the historical `session.capacity` / `session.format` / etc. property names.
    // Before this flatten, every consumer read `undefined` and:
    //   • the qty stepper got max=0 (spotsRemaining), disabling "+";
    //   • PACKAGE_CREDIT was filtered out because activePackages couldn't match format;
    //   • the booking summary's "CLASS" row rendered "—".
    const envelope = await sessionRes.json();
    const sessionPayload = envelope.session || envelope;
    session = {
      ...sessionPayload,
      className: sessionPayload.className,
      instructorName:
        envelope.instructor?.name ?? sessionPayload.instructorName,
      equipmentType:
        sessionPayload.equipmentType ?? envelope.blueprint?.equipmentType,
    };
    if (settingsRes && settingsRes.ok) {
      checkoutSettings = {
        ...checkoutSettings,
        ...(await settingsRes.json()),
      };
    }
    renderSummary();

    // ── Policy disclaimer banner ──
    fetch(`${API}/api/customer/cancel-policy`)
      .then((r) => (r.ok ? r.json() : null))
      .then((p) => {
        if (!p) return;
        const isPrivate = session?.format === "PRIVATE";
        // Build a human-readable summary of cancel windows
        const creditHrs = isPrivate
          ? (p.cancelWindowHoursCreditPrivate ?? 3)
          : (p.cancelWindowHoursCreditGroup ?? 3);
        const onlineHrs = isPrivate
          ? (p.cancelWindowHoursOnlinePrivate ?? 3)
          : (p.cancelWindowHoursOnlineGroup ?? 3);
        const studioHrs = isPrivate
          ? (p.cancelWindowHoursStudioPrivate ?? 3)
          : (p.cancelWindowHoursStudioGroup ?? 3);
        let text = `Cancellation policy: Credit bookings can be cancelled up to ${creditHrs}h before class.`;
        if (onlineHrs > 0)
          text += ` Online payments within ${onlineHrs}h are non-refundable.`;
        else text += ` Online payments are non-refundable.`;
        text += ` Studio bookings within ${studioHrs}h count as completed.`;
        const banner = document.getElementById("policyBanner");
        const bannerText = document.getElementById("policyBannerText");
        if (banner && bannerText) {
          bannerText.textContent = text;
          banner.style.display = "";
        }
      })
      .catch(() => {});

    // ── Guest-checkout gate ──────────────────────────────────────────────
    // If the admin has disabled guest checkout AND the visitor has no JWT,
    // send them to /login with a redirect back here so they can return
    // seamlessly after authenticating. We check AFTER settings load so
    // the flag is always current (not the default-true placeholder).
    const token = localStorage.getItem("customer_token");
    if (!token && checkoutSettings.allowGuestCheckout === false) {
      const here = window.location.pathname + window.location.search;
      window.location.href = "/login?redirect=" + encodeURIComponent(here);
      return; // Stop further init — the redirect will navigate away
    }

    // Try to get logged-in client + their packages.
    if (token) {
      try {
        const cr = await fetch(`${API}/api/booking/client-context`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (cr.ok) {
          const ctx = await cr.json();
          if (ctx.clientName && !intent.clientName)
            intent.clientName = ctx.clientName;
          if (ctx.clientPhone && !intent.clientPhone)
            intent.clientPhone = ctx.clientPhone;
          if (ctx.clientEmail && !intent.clientEmail)
            intent.clientEmail = ctx.clientEmail;
          // Capture clientId so /quote can run the "hide for active holders" check server-side.
