1	using Microsoft.AspNetCore.Authorization;
2	using Microsoft.AspNetCore.Mvc;
3	using Microsoft.Extensions.Logging;
4	using SoulPilates.Core.DTOs;
5	using SoulPilates.Core.Entities;
6	using SoulPilates.Core.Interfaces;
7	using System;
8	using System.Threading.Tasks;
9	
10	namespace SoulPilates.API.Controllers;
11	
12	[ApiController]
13	[Route("api/classblueprint")]
14	public class ClassBlueprintController : ControllerBase
15	{
16	    private readonly ISchedulingService _scheduling;
17	    private readonly ISettingsService _settingsService;
18	    private readonly ILogger<ClassBlueprintController> _logger;
19	
20	    /// <summary>Fallback horizon when settings haven't been configured yet.</summary>
21	    private const int DefaultHorizonDays = 30;
22	
23	    public ClassBlueprintController(
24	        ISchedulingService scheduling,
25	        ISettingsService settingsService,
26	        ILogger<ClassBlueprintController> logger)
27	    {
28	        _scheduling = scheduling;
29	        _settingsService = settingsService;
30	        _logger = logger;
31	    }
32	
33	    [Authorize(Roles = "Admin,Receptionist,Instructor,Accountant")]
34	    [HttpGet]
35	    public async Task<IActionResult> GetAll()
36	    {
37	        var items = await _scheduling.GetAllBlueprintsAsync();
38	        return Ok(items);
39	    }
40	
41	    [Authorize(Roles = "Admin,Receptionist,Instructor,Accountant")]
42	    [HttpGet("{id}")]
43	    public async Task<IActionResult> GetById(string id)
44	    {
45	        var item = await _scheduling.GetBlueprintByIdAsync(id);
46	        if (item is null) return NotFound();
47	        return Ok(item);
48	    }
49	
50	    [Authorize(Roles = "Admin")]
51	    [HttpPost]
52	    public async Task<IActionResult> Create([FromBody] ClassBlueprint blueprint)
53	    {
54	        var created = await _scheduling.CreateBlueprintAsync(blueprint);
55	
56	        // D10: Save = Published — materialise sessions immediately so the
57	        // admin sees them on the calendar without waiting for the background tick.
58	        if (created.IsActive && created.WeeklySlots?.Count > 0)
59	        {
60	            // Read admin-configured horizon
61	            var horizonDays = await GetHorizonDaysAsync();
62	
63	            _ = Task.Run(async () =>
64	            {
65	                try { await _scheduling.MaterialiseFromBlueprintAsync(created.Id!, horizonDays, DateTime.UtcNow); }
66	                catch (Exception ex) { _logger.LogError(ex, "Blueprint {Id} create: immediate materialise failed (the next 6h materialiser tick will retry). Most common cause: MongoDB unreachable.", created.Id); }
67	            });
68	        }
69	
70	        return Ok(created);
71	    }
72	
73	    /// <summary>
74	    /// PUT /api/classblueprint/{id}
75	    ///
76	    /// Accepts a <see cref="BlueprintUpdateRequest"/> that wraps the updated blueprint
77	    /// together with the admin's sync preferences (chosen in the save dialog).
78	    ///
79	    /// The update pipeline runs sequentially in a background task:
80	    ///   1. SyncBlueprintSessionsAsync  — updates existing future sessions in-place
81	    ///   2. MaterialiseFromBlueprintAsync — idempotently creates any genuinely new slots
82	    ///
83	    /// Running sync before materialise prevents the race where the materialiser
84	    /// would recreate an old-time session before sync had a chance to move it.
85	    /// </summary>
86	    [Authorize(Roles = "Admin")]
87	    [HttpPut("{id}")]
88	    public async Task<IActionResult> Update(string id, [FromBody] BlueprintUpdateRequest req)
89	    {
90	        var blueprint = req.Blueprint;
91	        var syncOpts  = req.Sync ?? new BlueprintSyncOptions();
92	
93	        // Default the "from" time to now if not supplied
94	        syncOpts.FromUtc ??= DateTime.UtcNow;
95	
96	        var ok = await _scheduling.UpdateBlueprintAsync(id, blueprint);
97	        if (!ok) return NotFound();
98	
99	        // Read admin-configured horizon
100	        var horizonDays = await GetHorizonDaysAsync();
101	
102	        if (blueprint.IsActive && blueprint.WeeklySlots?.Count > 0)
103	        {
104	            _ = Task.Run(async () =>
105	            {
106	                try
107	                {
108	                    // Step 1: Sync existing sessions (respects admin options)
109	                    if (syncOpts.UpdateExisting)
110	                        await _scheduling.SyncBlueprintSessionsAsync(id, blueprint, syncOpts);
111	
112	                    // Step 2: Materialise any genuinely new slots (idempotent)
113	                    await _scheduling.MaterialiseFromBlueprintAsync(id, horizonDays, DateTime.UtcNow);
114	                }
115	                catch (Exception ex) { _logger.LogError(ex, "Blueprint {Id} update: background sync/materialise failed (the next 6h materialiser tick will retry). Most common cause: MongoDB unreachable.", id); }
116	            });
117	        }
118	        else if (blueprint.IsActive)
119	        {
120	            // No weekly slots but active — nothing to materialise; still run sync
121	            // in case pricing changed and there are existing sessions.
122	            _ = Task.Run(async () =>
123	            {
124	                try
125	                {
126	                    if (syncOpts.UpdateExisting)
127	                        await _scheduling.SyncBlueprintSessionsAsync(id, blueprint, syncOpts);
128	                }
129	                catch (Exception ex) { _logger.LogError(ex, "Blueprint {Id} update: background sync failed.", id); }
130	            });
131	        }
132	
133	        return Ok();
134	    }
135	
136	    [Authorize(Roles = "Admin")]
137	    [HttpDelete("{id}")]
138	    public async Task<IActionResult> Delete(string id)
139	    {
140	        var ok = await _scheduling.DeleteBlueprintAsync(id);
141	        if (!ok) return NotFound();
142	        return NoContent();
143	    }
144	
145	    /// <summary>Public endpoint for the homepage "Our Classes" section.</summary>
146	    [AllowAnonymous]
147	    [HttpGet("featured")]
148	    public async Task<IActionResult> GetFeatured()
149	    {
150	        var items = await _scheduling.GetFeaturedBlueprintsAsync();
151	        return Ok(items);
152	    }
153	
154	    /// <summary>Admin toggle: mark a blueprint as featured (or not).</summary>
155	    [Authorize(Roles = "Admin")]
156	    [HttpPatch("{id}/featured")]
157	    public async Task<IActionResult> ToggleFeatured(string id, [FromBody] ToggleFeaturedRequest req)
158	    {
159	        var ok = await _scheduling.SetBlueprintFeaturedAsync(id, req.IsFeatured);
160	        if (!ok) return NotFound();
161	        return Ok();
162	    }
163	
164	    /// <summary>
165	    /// Reads the admin-configured materialisation horizon from GlobalSettings.
166	    /// Falls back to <see cref="DefaultHorizonDays"/> if not yet configured.
