using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using SoulPilates.Core.DTOs;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Interfaces;
using System;
using System.Threading.Tasks;

namespace SoulPilates.API.Controllers;

[ApiController]
[Route("api/classblueprint")]
public class ClassBlueprintController : ControllerBase
{
    private readonly ISchedulingService _scheduling;
    private readonly ISettingsService _settingsService;
    private readonly ILogger<ClassBlueprintController> _logger;

    /// <summary>Fallback horizon when settings haven't been configured yet.</summary>
    private const int DefaultHorizonDays = 30;

    public ClassBlueprintController(
        ISchedulingService scheduling,
        ISettingsService settingsService,
        ILogger<ClassBlueprintController> logger)
    {
        _scheduling = scheduling;
        _settingsService = settingsService;
        _logger = logger;
    }

    [Authorize(Roles = "Admin,Receptionist,Instructor,Accountant")]
    [HttpGet]
    public async Task<IActionResult> GetAll()
    {
        var items = await _scheduling.GetAllBlueprintsAsync();
        return Ok(items);
    }

    [Authorize(Roles = "Admin,Receptionist,Instructor,Accountant")]
    [HttpGet("{id}")]
    public async Task<IActionResult> GetById(string id)
    {
        var item = await _scheduling.GetBlueprintByIdAsync(id);
        if (item is null) return NotFound();
        return Ok(item);
    }

    [Authorize(Roles = "Admin")]
    [HttpPost]
    public async Task<IActionResult> Create([FromBody] ClassBlueprint blueprint)
    {
        var created = await _scheduling.CreateBlueprintAsync(blueprint);

        // D10: Save = Published — materialise sessions immediately so the
        // admin sees them on the calendar without waiting for the background tick.
        if (created.IsActive && created.WeeklySlots?.Count > 0)
        {
            // Read admin-configured horizon
            var horizonDays = await GetHorizonDaysAsync();

            _ = Task.Run(async () =>
            {
                try { await _scheduling.MaterialiseFromBlueprintAsync(created.Id!, horizonDays, DateTime.UtcNow); }
                catch (Exception ex) { _logger.LogError(ex, "Blueprint {Id} create: immediate materialise failed (the next 6h materialiser tick will retry). Most common cause: MongoDB unreachable.", created.Id); }
            });
        }

        return Ok(created);
    }

    /// <summary>
    /// PUT /api/classblueprint/{id}
    ///
    /// Accepts a <see cref="BlueprintUpdateRequest"/> that wraps the updated blueprint
    /// together with the admin's sync preferences (chosen in the save dialog).
    ///
    /// The update pipeline runs sequentially in a background task:
    ///   1. SyncBlueprintSessionsAsync  — updates existing future sessions in-place
    ///   2. MaterialiseFromBlueprintAsync — idempotently creates any genuinely new slots
    ///
    /// Running sync before materialise prevents the race where the materialiser
    /// would recreate an old-time session before sync had a chance to move it.
    /// </summary>
    [Authorize(Roles = "Admin")]
    [HttpPut("{id}")]
    public async Task<IActionResult> Update(string id, [FromBody] BlueprintUpdateRequest req)
    {
        var blueprint = req.Blueprint;
        var syncOpts  = req.Sync ?? new BlueprintSyncOptions();

        // Default the "from" time to now if not supplied
        syncOpts.FromUtc ??= DateTime.UtcNow;

        var ok = await _scheduling.UpdateBlueprintAsync(id, blueprint);
        if (!ok) return NotFound();

        // Read admin-configured horizon
        var horizonDays = await GetHorizonDaysAsync();

        if (blueprint.IsActive && blueprint.WeeklySlots?.Count > 0)
        {
            _ = Task.Run(async () =>
            {
                try
                {
                    // Step 1: Sync existing sessions (respects admin options)
                    if (syncOpts.UpdateExisting)
                        await _scheduling.SyncBlueprintSessionsAsync(id, blueprint, syncOpts);

                    // Step 2: Materialise any genuinely new slots (idempotent)
                    await _scheduling.MaterialiseFromBlueprintAsync(id, horizonDays, DateTime.UtcNow);
                }
                catch (Exception ex) { _logger.LogError(ex, "Blueprint {Id} update: background sync/materialise failed (the next 6h materialiser tick will retry). Most common cause: MongoDB unreachable.", id); }
            });
        }
        else if (blueprint.IsActive)
        {
            // No weekly slots but active — nothing to materialise; still run sync
            // in case pricing changed and there are existing sessions.
            _ = Task.Run(async () =>
            {
                try
                {
                    if (syncOpts.UpdateExisting)
                        await _scheduling.SyncBlueprintSessionsAsync(id, blueprint, syncOpts);
                }
                catch (Exception ex) { _logger.LogError(ex, "Blueprint {Id} update: background sync failed.", id); }
            });
        }

        return Ok();
    }

    [Authorize(Roles = "Admin")]
    [HttpDelete("{id}")]
    public async Task<IActionResult> Delete(string id)
    {
        var ok = await _scheduling.DeleteBlueprintAsync(id);
        if (!ok) return NotFound();
        return NoContent();
    }

    /// <summary>Public endpoint for the homepage "Our Classes" section.</summary>
    [AllowAnonymous]
    [HttpGet("featured")]
    public async Task<IActionResult> GetFeatured()
    {
        var items = await _scheduling.GetFeaturedBlueprintsAsync();
        return Ok(items);
    }

    /// <summary>Admin toggle: mark a blueprint as featured (or not).</summary>
    [Authorize(Roles = "Admin")]
    [HttpPatch("{id}/featured")]
    public async Task<IActionResult> ToggleFeatured(string id, [FromBody] ToggleFeaturedRequest req)
    {
        var ok = await _scheduling.SetBlueprintFeaturedAsync(id, req.IsFeatured);
        if (!ok) return NotFound();
        return Ok();
    }

    /// <summary>
    /// Reads the admin-configured materialisation horizon from GlobalSettings.
    /// Falls back to <see cref="DefaultHorizonDays"/> if not yet configured.
    /// </summary>
    private async Task<int> GetHorizonDaysAsync()
    {
        try
        {
            var settings = await _settingsService.GetAsync();
            return settings.MaterialisationHorizonDays > 0
                ? settings.MaterialisationHorizonDays
                : DefaultHorizonDays;
        }
        catch
        {
            return DefaultHorizonDays;
        }
    }
}

public record ToggleFeaturedRequest(bool IsFeatured);

