async function showCardView(intentRes) {
  document.getElementById("viewMethod").style.display = "none";
  document.getElementById("viewCard").style.display = "block";
  document.getElementById("cardAmount").textContent = fmt(
    intentRes.amount,
    intentRes.currency,
  );

