/// <summary>
/// Create a Stripe PaymentIntent for an attendance booking.
/// Returns the client_secret needed by Stripe Elements.
/// </summary>
[HttpPost("create-intent")]
public async Task<IActionResult> CreateIntent([FromBody] CreateIntentRequest request)
{
    if (string.IsNullOrWhiteSpace(request.AttendanceId))
        return BadRequest(new { message = "attendanceId is required." });
    if (string.IsNullOrWhiteSpace(request.PaymentMethod))
        return BadRequest(new { message = "paymentMethod is required." });

    try
    {
        var result = await _paymentService.CreateIntentAsync(request.AttendanceId, request.PaymentMethod);
        return Ok(new
        {
            paymentIntentId = result.PaymentIntentId,
            clientSecret = result.ClientSecret,
            amount = result.Amount,
            currency = result.Currency,
            publishableKey = result.PublishableKey,
            sessionFee = result.SessionFee,
            feeAmount = result.FeeAmount,
            feePercentage = result.FeePercentage,
            amountDueAtStudio = result.AmountDueAtStudio
        });
    }
    catch (System.Exception ex)
    {
        return BadRequest(new { message = ex.Message });
    }
}

/// <summary>
/// Client-side confirmation hook — frontend calls this after Stripe.confirmCardPayment succeeds.
/// Marks payment as SUCCEEDED. Webhook will idempotently confirm again later.
/// </summary>
[HttpPost("confirm")]
public async Task<IActionResult> Confirm([FromBody] ConfirmRequest request)
{
    if (string.IsNullOrWhiteSpace(request.PaymentIntentId))
        return BadRequest(new { message = "paymentIntentId is required." });
    var ok = await _paymentService.MarkSucceededAsync(request.PaymentIntentId);
    return Ok(new { success = ok });
}

/// <summary>
/// Stripe webhook receiver. Verifies signature, deduplicates by Stripe event id, and applies side effects exactly once.
/// Returns:
///   200 — processed, replayed (already-seen event), or unsupported event type acknowledged.
///   400 — invalid Stripe signature.
///   503 — Stripe payments are disabled on this server.
/// </summary>
[HttpPost("webhook")]
public async Task<IActionResult> Webhook()

public async Task<PaymentIntentResult> CreateIntentAsync(string attendanceId, string paymentMethod)
{
    var attendance = await _attendances.Find(a => a.Id == attendanceId).FirstOrDefaultAsync()
        ?? throw new Exception("Booking not found.");
    var session = await _sessions.Find(s => s.Id == attendance.CalendarSessionId).FirstOrDefaultAsync()
        ?? throw new Exception("Session not found.");

    // Pass the session's snapshotted drop-in price (sourced from ClassBlueprint).
    var quote = await QuotePriceAsync(
        session.Format,
        paymentMethod,
        customSessionFee: session.DropInPrice,
        quantity: Math.Max(1, attendance.Quantity),
        clientId: attendance.ClientId);

    // Issue #3 / Hotfix 2026-05-17 — PACKAGE_CREDIT deducts at confirmation.
    // Previously this block did a read-only pre-flight and left the
    // actual deduction to check-in, which (a) never happened in code,
    // and (b) contradicted the studio's policy of "use credits up
    // while confirming/checking out". We now:
    //   1. Read all eligible wallets ordered by expiry (FIFO).
    //   2. Fail fast if the customer doesn't have `quantity` credits.
    //   3. Stamp the oldest-contributing wallet on the attendance so
    //      cancellation can find a refund target (refund itself walks
    //      the ledger for the full multi-wallet case).
    //   4. Delegate the actual atomic decrement to WalletService so
    //      the PackageLedgerLog entries are written in lock-step with
    //      the wallet state — the same code path admins use.
    if (paymentMethod == "PACKAGE_CREDIT")
    {
        var quantityNeeded = Math.Max(1, attendance.Quantity);

        // SPM-108: the pre-flight wallet read MUST match the wallet set
        // DeductCreditAsync actually decrements, otherwise the two can
        // disagree on the boundary case. A wallet with its LAST credit(s)
        // has Status == "LOW_BALANCE" (set by DeductCreditAsync once
        // CreditsRemaining <= 2), NOT "ACTIVE". The previous inline filter
        // here only accepted "ACTIVE", so a customer's final credit was
        // invisible to this pre-flight: totalCredits came back 0, this
        // method threw INSUFFICIENT_CREDITS, and the attendance was left
        // stranded in RESERVED (never promoted to BOOKED, no credit spent).
        // Delegate to the canonical active-wallet query (ACTIVE +
        // LOW_BALANCE, expiry-aware, FIFO-sorted) — the exact same query
        // DeductCreditAsync walks — so the two stay in lock-step.
        var activeWallets = (await _walletService
            .GetActivePackagesForClientAsync(attendance.ClientId, session.Format))
            .ToList();
        var totalCredits = activeWallets.Sum(p => p.CreditsRemaining);
        if (totalCredits < quantityNeeded)
            throw new InvalidOperationException(
                $"BOOKING.INSUFFICIENT_CREDITS — {quantityNeeded} credit(s) required but only {totalCredits} available.");

        // Pick the oldest-expiring wallet as the "primary" refund target.
        // WalletService.RefundCreditByAttendanceAsync walks the ledger
        // so a deduction that spans more than one wallet is still fully
        // reversed on cancel; this field is just a fast-path hint and a
        // legacy compatibility shim for existing single-wallet refund code.
        // Order by soonest-expiring first; never-expiring (null) wallets sort
        // last so an open-ended package isn't burned before a dated one.
        var primaryWallet = activeWallets
            .OrderBy(p => p.ExpiryDate ?? DateTime.MaxValue)
            .First();

        var deducted = await _walletService.DeductCreditAsync(
            attendance.ClientId,
            session.Format,
            attendanceId,
            quantityNeeded);
        if (!deducted)
            throw new InvalidOperationException(
                "BOOKING.CREDIT_DEDUCTION_FAILED — wallet state changed during checkout, please retry.");

        // Persist payment method + amounts + the wallet hint in a single
        // round-trip so we don't leave an attendance with a missing
        // PackageInstanceId if the next write fails.
        var creditUpdate = Builders<Attendance>.Update
            .Set(a => a.PaymentMethod, paymentMethod)
            .Set(a => a.AmountPaid, 0m)
            .Set(a => a.AmountDueAtStudio, quote.AmountDueAtStudio)
            .Set(a => a.PackageInstanceId, primaryWallet.Id);

