private const string Currency = "VND";

private readonly IMongoCollection<PaymentRecord> _payments;
private readonly IMongoCollection<Attendance> _attendances;
private readonly IMongoCollection<CalendarSession> _sessions;
private readonly IMongoCollection<StripeProcessedEvent> _processedEvents;
// P5-PWA — Look up the instructor's UserId when firing the "New booking" push.
private readonly IMongoCollection<Staff> _staff;
// Issue #2 / #4 — needed to compute upsell suggestions and read Invoice rows
// for the package-purchase intent flow.
private readonly IMongoCollection<SoulPilates.Core.Entities.Product> _products;
private readonly IMongoCollection<ClientPackage> _clientPackages;
private readonly IMongoCollection<SoulPilates.Core.Entities.Invoice> _invoices;
private readonly ISettingsService _settingsService;
private readonly ILogger<PaymentService> _logger;
private readonly IAuditLogger _audit;
private readonly INotificationPublisher _notifications;
private readonly IInvoiceService _invoiceService;
private readonly IWalletService _walletService;
private readonly IEmailService _emailService;

public PaymentService(
    MongoDbContext db,
    ISettingsService settingsService,
    ILogger<PaymentService> logger,
    IAuditLogger audit,
    INotificationPublisher notifications,
    IInvoiceService invoiceService,
    IWalletService walletService,
    IEmailService emailService)
{
    _payments = db.GetCollection<PaymentRecord>("PaymentRecords");
    _attendances = db.GetCollection<Attendance>("Attendances");
    _sessions = db.GetCollection<CalendarSession>("CalendarSessions");
    _processedEvents = db.GetCollection<StripeProcessedEvent>("StripeProcessedEvents");
    _staff = db.GetCollection<Staff>("Staff");
    _products = db.GetCollection<SoulPilates.Core.Entities.Product>("Products");
    _clientPackages = db.GetCollection<ClientPackage>("ClientPackages");
    _invoices = db.GetCollection<SoulPilates.Core.Entities.Invoice>("Invoices");

