file.content:
---
/*
 * Instructor Schedule — Redesigned card-based list view.
 *
 * Two tabs:
 *   1. My Classes — upcoming sessions with ≥0 attendees, card layout
 *      inspired by the customer booking page, showing commission estimates.
 *   2. Recent Bookings — recent customer bookings to this instructor's classes.
 *
 * Clicking a class card opens a detail drawer (instructor-scoped variant of
 * the admin ClassDetailPanel) showing attendees with status-change controls,
 * waitlist, and commission financials. POS/admin-only features removed.
 */
import InstructorLayout from "../../layouts/InstructorLayout.astro";
---

<InstructorLayout title="My schedule" activePage="schedule">

<style is:global>
  /* ═══════════════════════════════════════════════════════════
     INSTRUCTOR SCHEDULE — REDESIGNED
     ═══════════════════════════════════════════════════════════ */

  .ins-page { max-width: 1100px; margin: 0 auto; }

  /* ── Page Header ── */
  .ins-header {
    display: flex; align-items: flex-end; justify-content: space-between;
    margin-bottom: 24px; flex-wrap: wrap; gap: 12px;
  }
  .ins-header-left {}
  .ins-header-title {
    font-family: 'Inter', -apple-system, sans-serif;
    font-size: 1.75rem; font-weight: 700; margin: 0;
    letter-spacing: -0.02em;
  }
  .ins-header-subtitle {
    margin: 4px 0 0; font-size: 0.875rem;
    color: var(--color-text-muted, rgba(255,255,255,.6));
  }
  .ins-header-right { display: flex; gap: 8px; align-items: center; }

  /* ── Tabs ── */
  .ins-tabs {
    display: flex; gap: 0;
    border-bottom: 2px solid var(--color-border-subtle, rgba(255,255,255,.08));
    margin-bottom: 20px;
  }
  .ins-tab {
    padding: 12px 20px; font-size: 13px; font-weight: 600;
    color: var(--color-text-muted, rgba(255,255,255,.5));
    border: none; background: none; cursor: pointer;
    border-bottom: 2px solid transparent;
    margin-bottom: -2px;
    font-family: 'Inter', sans-serif;
    transition: all 0.15s;
  }
  .ins-tab:hover { color: var(--color-text-primary, #fff); }
  .ins-tab.active {
    color: var(--color-brand-accent, #c8a45d);
    border-bottom-color: var(--color-brand-accent, #c8a45d);
  }
  .ins-tab-badge {
    display: inline-flex; align-items: center; justify-content: center;
    min-width: 20px; height: 20px; padding: 0 6px;
    border-radius: 999px; font-size: 11px; font-weight: 700;
    background: var(--color-surface-raised, rgba(255,255,255,.06));
    color: var(--color-text-muted); margin-left: 6px;
  }
  .ins-tab.active .ins-tab-badge {
    background: rgba(200,164,93,.15);
    color: var(--color-brand-accent, #c8a45d);
  }
  .ins-tab-panel { display: none; }
  .ins-tab-panel.active { display: block; }

  /* ── Filters ── */
  .ins-filters {
    display: flex; gap: 8px; align-items: center;
    flex-wrap: wrap; margin-bottom: 16px;
  }
  .ins-filter-control {
    padding: 7px 12px; border: 1px solid var(--color-border, rgba(255,255,255,.1));
    border-radius: 8px; background: var(--color-surface, rgba(255,255,255,.03));
    color: var(--color-text-primary, #fff); font-size: 12.5px;
    font-family: 'Inter', sans-serif; cursor: pointer; outline: none;
  }
  .ins-filter-control:focus { border-color: var(--color-brand-accent, #c8a45d); }

  /* ── Day Group Header ── */
  .ins-day-header {
    font-size: 13px; font-weight: 700;
    color: var(--color-text-muted, rgba(255,255,255,.5));
    text-transform: uppercase; letter-spacing: 0.06em;
    padding: 12px 0 8px; margin-top: 8px;
    border-bottom: 1px solid var(--color-border-subtle, rgba(255,255,255,.06));
  }
  .ins-day-header:first-child { margin-top: 0; }

  /* ═══ Class Card ═══ */

