/* ═══ Class Card ═══ */
.ins-class-card {
  display: flex; align-items: stretch; gap: 0;
  padding: 16px 20px;
  background: var(--color-surface, rgba(255,255,255,.02));
  border: 1px solid var(--color-border-subtle, rgba(255,255,255,.06));
  border-radius: 12px;
  margin-bottom: 8px;
  cursor: pointer;
  transition: all 0.15s;
  position: relative;
}
.ins-class-card:hover {
  border-color: rgba(200,164,93,.3);
  background: rgba(200,164,93,.04);
  transform: translateY(-1px);
  box-shadow: 0 4px 16px rgba(0,0,0,.12);
}

/* Card col 1: Time */
.ins-card-time {
  display: flex; flex-direction: column; align-items: center;
  justify-content: center; flex-shrink: 0; width: 64px;
  text-align: center; gap: 1px;
}
.ins-card-time-main {
  font-size: 18px; font-weight: 700;
  color: var(--color-text-primary, #fff);
  letter-spacing: -0.5px; line-height: 1.1;
}
.ins-card-time-ampm {
  font-size: 9px; font-weight: 600;
  color: var(--color-text-muted, rgba(255,255,255,.5));
  text-transform: uppercase; letter-spacing: 0.5px;
}
.ins-card-time-dur {
  font-size: 10px; font-weight: 500;
  color: var(--color-text-muted, rgba(255,255,255,.4));
  margin-top: 3px; white-space: nowrap;
}

/* Card col 2: Vertical divider */
.ins-card-divider {
  flex-shrink: 0; width: 1px;
  background: var(--color-border-subtle, rgba(255,255,255,.08));
  margin: 2px 14px; align-self: stretch;
}

/* Card col 3: Info (grows) */
.ins-card-info {
  flex: 1; min-width: 0; display: flex;
  flex-direction: column; justify-content: center; gap: 4px;
}
.ins-card-name-row {
  display: flex; align-items: center; gap: 8px; flex-wrap: wrap;
}
.ins-card-name {
  font-size: 14px; font-weight: 600;
  color: var(--color-text-primary, #fff); line-height: 1.2;
}
.ins-card-badge {
  font-size: 9px; font-weight: 700; padding: 2px 7px;
  border-radius: 4px; text-transform: uppercase; letter-spacing: 0.04em;
}
.ins-card-badge.group { background: rgba(43,183,163,.15); color: #2bb7a3; }
.ins-card-badge.private { background: rgba(244,146,60,.15); color: #f4923c; }
.ins-card-badge.duo { background: rgba(139,92,246,.15); color: #8b5cf6; }
.ins-card-badge.scheduled { background: var(--color-surface-raised, rgba(255,255,255,.06)); color: var(--color-text-muted); }
.ins-card-badge.completed { background: rgba(74,222,128,.12); color: #4ade80; }
.ins-card-badge.no_show { background: rgba(239,68,68,.12); color: #ef4444; }
.ins-card-badge.cancelled { background: rgba(239,68,68,.12); color: #ef4444; }
.ins-card-meta {
  display: flex; align-items: center; gap: 10px; flex-wrap: wrap;
}
.ins-card-meta-item {
  display: inline-flex; align-items: center; gap: 4px;
  font-size: 11px; color: var(--color-text-muted, rgba(255,255,255,.5));
}
.ins-card-meta-item svg { width: 12px; height: 12px; flex-shrink: 0; }

/* Card col 4: Capacity + Commission */
.ins-card-stats {
  display: flex; flex-direction: column; align-items: flex-end;
  justify-content: center; gap: 6px; flex-shrink: 0;
  margin-left: 12px; min-width: 100px;
}
.ins-card-capacity {
  display: flex; align-items: center; gap: 6px;
  font-size: 12px; font-weight: 600;
  color: var(--color-text-primary, #fff);
}
.ins-card-fill-bar {
  width: 40px; height: 5px; border-radius: 3px;
  background: var(--color-border-subtle, rgba(255,255,255,.1));
  overflow: hidden;
}
.ins-card-fill-inner {
  height: 100%; border-radius: 3px;
  transition: width 0.3s ease;
}
.ins-card-fill-inner.low { background: var(--color-success, #4ade80); }
.ins-card-fill-inner.mid { background: var(--color-brand-accent, #c8a45d); }
.ins-card-fill-inner.high { background: var(--color-warning, #facc15); }
.ins-card-fill-inner.full { background: var(--color-danger, #ef4444); }
.ins-card-commission {
  font-size: 11px; font-weight: 600;
  color: var(--color-brand-accent, #c8a45d);
  white-space: nowrap;
}
.ins-card-commission.estimate {
  opacity: 0.7; font-style: italic;
}

/* ── Empty / Loading States ── */
.ins-empty {
  text-align: center; padding: 64px 24px;
  color: var(--color-text-muted, rgba(255,255,255,.45));
}
.ins-empty-icon {
  width: 56px; height: 56px; margin: 0 auto 16px;
  border-radius: 50%;
  background: rgba(200,164,93,.1);
  display: flex; align-items: center; justify-content: center;
  color: var(--color-brand-accent, #c8a45d);
}
.ins-empty-icon svg { width: 24px; height: 24px; }
.ins-empty h3 {
  font-family: 'Inter', sans-serif; font-size: 1.15rem;
  font-weight: 600; margin: 0 0 6px;
  color: var(--color-text-primary, #fff);
}
.ins-empty p { margin: 0; font-size: 13px; }
.ins-skeleton-row {
  height: 72px; border-radius: 12px; margin-bottom: 8px;
  background: linear-gradient(90deg,
    rgba(255,255,255,.03) 25%, rgba(255,255,255,.08) 50%, rgba(255,255,255,.03) 75%);
  background-size: 200% 100%;
  animation: ins-pulse 1.4s ease infinite;
}
@keyframes ins-pulse {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}

/* ═══ Bookings Tab — Table-like rows ═══ */
.ins-bkg-row {
  display: grid;
  grid-template-columns: 1fr 1.4fr 1fr 0.7fr 100px 100px;
  gap: 8px; align-items: center;
  padding: 12px 16px;
  border-bottom: 1px solid var(--color-border-subtle, rgba(255,255,255,.06));
  font-size: 12.5px;
  transition: background 0.1s;
  cursor: pointer;
}
.ins-bkg-row:hover { background: var(--color-surface-raised, rgba(255,255,255,.03)); }
.ins-bkg-header {
  font-size: 10px; font-weight: 700;
  text-transform: uppercase; letter-spacing: 0.06em;
  color: var(--color-text-muted, rgba(255,255,255,.4));
  border-bottom: 1px solid var(--color-border-subtle, rgba(255,255,255,.1));
  padding: 8px 16px;
  cursor: default;
}
.ins-bkg-header:hover { background: none; }
.ins-bkg-client {
  font-weight: 600; color: var(--color-text-primary, #fff);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.ins-bkg-class {
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  color: var(--color-text-secondary, rgba(255,255,255,.7));
}
.ins-bkg-date {
  color: var(--color-text-muted, rgba(255,255,255,.5));
  font-size: 11px;
}

/* ── Payment Status Pills ── */
.ins-pay-pill {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 3px 8px; border-radius: 4px;
  font-size: 10px; font-weight: 700; text-transform: uppercase;
  letter-spacing: 0.03em; white-space: nowrap;
  line-height: 1.3;
}
.ins-pay-pill.pay-paid      { background: rgba(74,222,128,.12);  color: #4ade80; }
.ins-pay-pill.pay-partial   { background: rgba(250,204,21,.12);  color: #facc15; }
.ins-pay-pill.pay-free      { background: rgba(56,189,248,.12);  color: #38bdf8; }
.ins-pay-pill.pay-unpaid    { background: rgba(239,68,68,.10);   color: #ef4444; }
.ins-pay-pill.pay-refund    { background: rgba(244,114,182,.12); color: #f472b6; }
.ins-pay-pill.pay-void      { background: rgba(148,163,184,.12); color: #94a3b8; }
.ins-pay-method {
  display: inline-flex; align-items: center;
  padding: 2px 5px; border-radius: 3px;
  font-size: 8.5px; font-weight: 700; text-transform: uppercase;
  letter-spacing: 0.03em; white-space: nowrap;
  margin-left: 3px; opacity: 0.75;
  background: var(--color-surface-raised, rgba(255,255,255,.06));
  color: var(--color-text-muted, rgba(255,255,255,.5));

