---
import AdminLayout from "../../layouts/AdminLayout.astro";
import ClassDetailPanel from "../../components/admin/ClassDetailPanel.astro";
---

<AdminLayout title="Schedule" activePage="calendar">

<style is:global>
  /* ═══ Override content-area for full-bleed calendar ═══ */
  .content-area:has(.cal-page) {
    padding: 0 !important;
    overflow: hidden !important;
    display: flex;
    flex-direction: column;
  }

  /* ═══════════════════════════════════════════════════════════
     CALENDAR PAGE SHELL
     ═══════════════════════════════════════════════════════════ */
  .cal-page {
    display: flex;
    flex-direction: column;
    flex: 1;
    min-height: 0;
    overflow: hidden;
  }

  /* ── Top Bar ── */
  .cal-topbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 16px 24px 12px;
    border-bottom: 1px solid var(--color-border);
    flex-shrink: 0;
    gap: 12px;
    flex-wrap: wrap;
  }
  .cal-topbar-left { display: flex; flex-direction: column; gap: 2px; }
  .cal-topbar-title {
    font-size: 22px; font-weight: 700;
    color: var(--color-text-primary);
    letter-spacing: -0.3px;
    line-height: 1.2;
  }
  .cal-topbar-subtitle {
    font-size: 12.5px;
    color: var(--color-text-muted);
  }
  .cal-topbar-right {
    display: flex; align-items: center; gap: 8px; flex-wrap: wrap;
  }

  /* Navigation cluster */
  .cal-nav-cluster { display: flex; align-items: center; gap: 4px; }
  .cal-nav-btn {
    width: 32px; height: 32px; border: 1px solid var(--color-border);
    background: var(--color-surface); border-radius: var(--radius-sm);
    color: var(--color-text-muted); cursor: pointer;
    display: flex; align-items: center; justify-content: center;

