/* Notes */
.ins-notes-card {
  margin: 12px 20px; padding: 12px;
  background: var(--color-surface-raised, rgba(255,255,255,.04));
  border: 1px solid var(--color-border-subtle, rgba(255,255,255,.06));
  border-radius: 8px;
}
.ins-notes-title {
  font-size: 11px; font-weight: 600; text-transform: uppercase;
  letter-spacing: 0.05em; color: var(--color-text-muted);
  margin-bottom: 6px;
}
.ins-notes-body { font-size: 12.5px; line-height: 1.6; color: var(--color-text-secondary, rgba(255,255,255,.6)); }

/* Pagination */
.ins-pagination {
  display: flex; gap: 4px; align-items: center;
  justify-content: center; padding: 16px 0;
}
.ins-pagination button {
  border: 1px solid var(--color-border, rgba(255,255,255,.1));
  background: var(--color-surface, rgba(255,255,255,.03));
  color: var(--color-text-primary, #fff);
  padding: 4px 10px; font-size: 12px;
  border-radius: 6px; cursor: pointer;
  font-family: 'Inter', sans-serif;
}
.ins-pagination button.active {
  background: var(--color-brand-accent, #c8a45d);
  color: #1a1410; border-color: var(--color-brand-accent);
}
.ins-pagination button:disabled { opacity: 0.4; cursor: default; }

/* ── Admin browsing banner ── */
.ins-admin-banner {
  text-align: center; padding: 48px 24px;
  background: linear-gradient(135deg, rgba(99,179,237,.06), rgba(99,179,237,.01));
  border: 1px solid rgba(99,179,237,.2);
  border-radius: 14px;
}
.ins-admin-banner h2 {
  font-family: 'Inter', sans-serif; font-size: 1.4rem;
  margin: 0 0 8px; color: #63b3ed;
}
.ins-admin-banner p {
  color: var(--color-text-muted, rgba(255,255,255,.5));
  margin: 0 0 16px; font-size: 13px;
}

/* ── Responsive ── */
@media (max-width: 768px) {
  .ins-class-card { padding: 12px 14px; }
  .ins-card-time { width: 52px; }
  .ins-card-time-main { font-size: 15px; }
  .ins-card-stats { min-width: 80px; }
  .ins-drawer { width: 100vw; }
  .ins-bkg-row { grid-template-columns: 1fr 1fr 80px 80px; }
  .ins-bkg-row > :nth-child(3),
  .ins-bkg-row > :nth-child(4) { display: none; }
  .ins-bkg-header > :nth-child(3),
  .ins-bkg-header > :nth-child(4) { display: none; }
}

/* ═══════════════════════════════════════════════════════════
   INSTRUCTOR CALENDAR (TAB 3) — ic- prefix
