---
import AdminLayout from "../../layouts/AdminLayout.astro";
import ClassDetailPanel from "../../components/admin/ClassDetailPanel.astro";
---

<AdminLayout title="Schedule" activePage="calendar">

<style is:global>
  /* ═══ Admin Schedule List View ═══ */
  .cal-page { max-width: 1100px; margin: 0 auto; padding: 0 0 40px; }

  .cal-topbar {
    display: flex; align-items: center; justify-content: space-between;
    padding: 20px 0 16px; flex-wrap: wrap; gap: 12px;
  }
  .cal-topbar-left { display: flex; flex-direction: column; gap: 2px; }
  .cal-topbar-title { font-size: 22px; font-weight: 700; color: var(--color-text-primary); letter-spacing: -0.3px; }
  .cal-topbar-subtitle { font-size: 12.5px; color: var(--color-text-muted); }
  .cal-topbar-right { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }

  /* Nav cluster */
  .cal-nav-cluster { display: flex; align-items: center; gap: 4px; }
  .cal-nav-btn {
    width: 32px; height: 32px; border: 1px solid var(--color-border);
    background: var(--color-surface); border-radius: var(--radius-sm);
    color: var(--color-text-muted); cursor: pointer;
    display: flex; align-items: center; justify-content: center; transition: all 0.12s;
  }
  .cal-nav-btn:hover { border-color: var(--color-brand-accent); color: var(--color-brand-accent); }
  .cal-nav-btn svg { width: 14px; height: 14px; }
  .cal-period-label {
    font-size: 14px; font-weight: 600; color: var(--color-text-primary);
    padding: 6px 14px; border: 1px solid var(--color-border);
    border-radius: var(--radius-sm); background: var(--color-surface); white-space: nowrap;
  }
  .cal-today-btn {
    padding: 6px 14px; font-size: 12px; font-weight: 600;
    border: 1px solid var(--color-border); border-radius: var(--radius-sm);
    background: var(--color-surface); cursor: pointer;
    color: var(--color-text-muted); transition: all 0.12s;
  }
  .cal-today-btn:hover { border-color: var(--color-brand-accent); color: var(--color-brand-accent); }

  /* View toggle */
  .cal-view-seg {
    display: inline-flex; border: 1px solid var(--color-border);
    border-radius: var(--radius-sm); overflow: hidden;
  }
  .cal-view-btn {
    padding: 6px 14px; border: none; background: none; font-size: 12px; font-weight: 600;
    cursor: pointer; color: var(--color-text-muted); font-family: 'Inter', sans-serif; transition: all 0.12s;
  }
  .cal-view-btn:not(:last-child) { border-right: 1px solid var(--color-border); }
  .cal-view-btn.active { background: var(--color-brand-accent); color: #fff; }
  .cal-view-btn:hover:not(.active) { background: var(--color-surface-raised); color: var(--color-text-primary); }

  /* Filters bar */
  .cal-filters {
    display: flex; gap: 8px; align-items: center; flex-wrap: wrap; margin-bottom: 16px;
  }
  .cal-filter-select {
    padding: 7px 12px; border: 1px solid var(--color-border);
    border-radius: var(--radius-sm); background: var(--color-surface);
    color: var(--color-text-primary); font-size: 12.5px;
    font-family: 'Inter', sans-serif; cursor: pointer; outline: none;
  }
  .cal-filter-select:focus { border-color: var(--color-brand-accent); }
  .cal-filter-label {
    display: flex; align-items: center; gap: 6px;
    font-size: 12px; color: var(--color-text-muted); cursor: pointer;
  }
  .cal-filter-label input { accent-color: var(--color-brand-accent); cursor: pointer; }

  /* Day header */
  .cal-day-header {
    font-size: 12px; font-weight: 700;
    color: var(--color-text-muted);
    text-transform: uppercase; letter-spacing: 0.06em;
