   INSTRUCTOR CALENDAR (TAB 3) — ic- prefix
   ═══════════════════════════════════════════════════════════ */
.ic-wrap {
  display: flex; flex-direction: column;
  border: 1px solid var(--color-border-subtle, rgba(255,255,255,.08));
  border-radius: 12px; overflow: hidden;
  background: var(--color-surface, rgba(255,255,255,.02));
  min-height: 500px;
}
/* Top bar */
.ic-topbar {
  display: flex; align-items: center; justify-content: space-between;
  padding: 12px 16px; border-bottom: 1px solid var(--color-border-subtle, rgba(255,255,255,.08));
  flex-shrink: 0; gap: 10px; flex-wrap: wrap;
}
.ic-topbar-left { display: flex; align-items: center; gap: 6px; }
.ic-topbar-right { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.ic-nav-btn {
  width: 30px; height: 30px; border: 1px solid var(--color-border-subtle, rgba(255,255,255,.1));
  background: none; border-radius: 6px; color: var(--color-text-muted, rgba(255,255,255,.5));
  cursor: pointer; display: flex; align-items: center; justify-content: center; transition: all 0.12s;
}
.ic-nav-btn:hover { background: rgba(255,255,255,.05); color: var(--color-text-primary, #fff); }
.ic-nav-btn svg { width: 13px; height: 13px; }
.ic-date-label {
  font-size: 13px; font-weight: 600; color: var(--color-text-primary, #fff);
  padding: 4px 10px; border: 1px solid var(--color-border-subtle, rgba(255,255,255,.1));
  border-radius: 6px; background: rgba(255,255,255,.03); white-space: nowrap;
}
.ic-today-btn {
  padding: 4px 12px; font-size: 11px; font-weight: 600;
  border: 1px solid var(--color-border-subtle, rgba(255,255,255,.1));
  border-radius: 6px; background: none; cursor: pointer;
  color: var(--color-text-muted, rgba(255,255,255,.5)); transition: all 0.12s;
}
.ic-today-btn:hover { background: rgba(200,164,93,.1); color: var(--color-brand-accent, #c8a45d); }
.ic-seg {
  display: inline-flex; border: 1px solid var(--color-border-subtle, rgba(255,255,255,.1));
  border-radius: 6px; overflow: hidden;
}
.ic-seg-btn {
  padding: 4px 14px; border: none; background: none; font-size: 11px; font-weight: 600;
  cursor: pointer; color: var(--color-text-muted, rgba(255,255,255,.5));
  font-family: 'Inter', sans-serif; transition: all 0.12s;
}
.ic-seg-btn:not(:last-child) { border-right: 1px solid var(--color-border-subtle, rgba(255,255,255,.1)); }
.ic-seg-btn.active { background: var(--color-brand-accent, #c8a45d); color: white; }
.ic-seg-btn:hover:not(.active) { background: rgba(255,255,255,.04); color: var(--color-text-primary, #fff); }

/* Column headers */
.ic-col-headers {
  display: grid; flex-shrink: 0;
  border-bottom: 1px solid var(--color-border-subtle, rgba(255,255,255,.08));
}
.ic-col-header { padding: 8px 4px; text-align: center; }
.ic-col-header .ch-wday {
  font-size: 10px; font-weight: 600; text-transform: uppercase;
  letter-spacing: 0.5px; color: var(--color-text-muted, rgba(255,255,255,.5));
}
.ic-col-header .ch-num {
  font-size: 18px; font-weight: 700; font-family: 'Inter', sans-serif;
  letter-spacing: -0.3px; line-height: 1; color: var(--color-text-primary, #fff); margin-top: 2px;
}
.ic-col-header .ch-num.today {
  display: inline-flex; align-items: center; justify-content: center;
  background: var(--color-brand-accent, #c8a45d); color: white;
  width: 30px; height: 30px; border-radius: 50%;
  box-shadow: 0 2px 8px rgba(200,164,93,0.3);
}

/* Grid / cells */
.ic-scroll { flex: 1; overflow-y: auto; overflow-x: hidden; max-height: 600px; }
.ic-grid { display: grid; position: relative; }
.ic-time-label {
  font-size: 10px; font-weight: 500; color: var(--color-text-muted, rgba(255,255,255,.4));
  text-align: right; padding: 0 6px; line-height: 1; padding-top: 2px;
  height: var(--ic-row-h, 80px);
  border-bottom: 1px solid var(--color-border-subtle, rgba(255,255,255,.05));
  display: flex; align-items: flex-start; justify-content: flex-end;
}
.ic-cell {
  height: var(--ic-row-h, 80px);
  border-bottom: 1px solid var(--color-border-subtle, rgba(255,255,255,.05));
  border-left: 1px solid var(--color-border-subtle, rgba(255,255,255,.05));
  position: relative;
}

/* Event card */
.ic-ev {
  position: absolute; top: 2px; bottom: 2px; left: 3px; right: 3px;
  border-radius: 5px; padding: 3px 6px; font-size: 10px;
  cursor: pointer; overflow: hidden; z-index: 1;
  border-left: 3px solid var(--ic-accent, var(--color-brand-accent, #c8a45d));
  background: var(--ic-bg, rgba(200,164,93,0.12));
  color: var(--ic-text, #e0c070); transition: all 0.12s;
  display: flex; flex-direction: column;
}
.ic-ev:hover {
  filter: brightness(1.12); transform: scale(1.01);
  z-index: 5; box-shadow: 0 4px 16px rgba(0,0,0,0.25);
}
.ic-ev .ic-ev-time { font-size: 8px; opacity: 0.6; line-height: 1; margin-bottom: 1px; white-space: nowrap; }
.ic-ev .ic-ev-name { font-size: 10px; font-weight: 700; line-height: 1.2; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ic-ev .ic-ev-cap { font-size: 8px; opacity: 0.65; margin-top: 1px; }
.ic-ev .ic-ev-clients { font-size: 8px; opacity: 0.75; line-height: 1.2; flex: 1; overflow: hidden; }
.ic-ev .ic-ev-client-line { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ic-ev .ic-ev-more { opacity: 0.5; font-style: italic; }

/* Multi pill */
.ic-multi-pill {
  position: absolute; top: 3px; left: 3px; right: 3px;
  display: flex; align-items: center; gap: 4px;
  background: var(--color-surface-raised, rgba(255,255,255,.06));
  border: 1px solid var(--color-border-subtle, rgba(255,255,255,.1));
  border-radius: 5px; padding: 4px 6px; font-size: 10px; font-weight: 600;
  color: var(--color-text-primary, #fff); cursor: pointer; z-index: 2; overflow: hidden;
  transition: all 0.12s;
}
.ic-multi-pill:hover { background: rgba(200,164,93,.12); border-color: var(--color-brand-accent, #c8a45d); }
.ic-multi-pill .ic-pill-dots { display: flex; gap: 2px; align-items: center; }
.ic-multi-pill .ic-pill-dot { width: 5px; height: 5px; border-radius: 50%; }
.ic-multi-pill .ic-pill-label { flex: 1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

/* Multi dropdown (floating) */
.ic-floating {
  position: fixed; z-index: 1050; background: var(--color-surface-raised, #2a2520);
  border: 1px solid var(--color-border-subtle, rgba(255,255,255,.1));
  border-radius: 10px; padding: 6px; display: none; min-width: 200px;
  box-shadow: 0 8px 30px rgba(0,0,0,.3); backdrop-filter: blur(12px);
}
.ic-floating.open { display: block; animation: icPopIn .15s ease; }
@keyframes icPopIn { from { opacity: 0; transform: translateY(-6px) scale(.96); } to { opacity: 1; transform: translateY(0) scale(1); } }
.ic-floating-header {
  padding: 6px 10px 8px; font-size: 11px; font-weight: 600;
  color: var(--color-text-muted, rgba(255,255,255,.5));
  border-bottom: 1px solid var(--color-border-subtle, rgba(255,255,255,.08)); margin-bottom: 4px;
}
.ic-float-item {
  display: block; width: 100%; text-align: left; border: none; background: none;
  border-radius: 6px; padding: 7px 10px; cursor: pointer; transition: background 0.1s;
  font-family: 'Inter', sans-serif; border-left: 3px solid transparent; margin-bottom: 2px;
}
.ic-float-item:hover { background: rgba(200,164,93,.08); }
.ic-float-item .fi-name { font-size: 11px; font-weight: 600; color: var(--color-text-primary, #fff); }
.ic-float-item .fi-time { font-size: 10px; color: var(--color-text-muted, rgba(255,255,255,.5)); }
.ic-float-item .fi-cap { font-size: 9px; color: var(--color-text-muted, rgba(255,255,255,.4)); margin-top: 1px; }

/* Legend */
.ic-legend {
  display: flex; align-items: center; gap: 12px; padding: 8px 16px;
  border-top: 1px solid var(--color-border-subtle, rgba(255,255,255,.08));
  font-size: 10px; color: var(--color-text-muted, rgba(255,255,255,.4));
  flex-shrink: 0; flex-wrap: wrap;
}
.ic-legend-item { display: flex; align-items: center; gap: 5px; white-space: nowrap; }
.ic-legend-dot { width: 8px; height: 8px; border-radius: 3px; flex-shrink: 0; }

@media (max-width: 768px) {
  .ic-topbar { padding: 10px 12px; }
  .ic-date-label { font-size: 11px; padding: 3px 8px; }
  .ic-scroll { max-height: 450px; }
  /* Disable GPU-heavy effects on mobile */
  .ic-floating { backdrop-filter: none !important; -webkit-backdrop-filter: none !important; }
  .ins-skeleton-row { animation: none !important; }
}

