// Pull the instructor's own upcoming sessions (calendar endpoint is already
// scoped to the resolved instructor and respects viewAs) and keep only valid
// reschedule targets: future, SCHEDULED, same format, with an open spot, and
// not the session the booking is already on.
async function insLoadReschedCandidates() {
  const list = document.getElementById('insReschedList');
  if (!list) return;
  const from = _insResched.from;
  const to = _insResched.to;
  if (from && to && from > to) {
    list.innerHTML = '<div style="text-align:center;padding:24px;color:var(--color-text-muted);font-size:12px;">"From" date must be on or before "To" date.</div>';
    return;
  }
  list.innerHTML = '<div style="text-align:center;padding:24px;color:var(--color-text-muted);font-size:12px;">Loading available sessions…</div>';
  try {
    const now = new Date();
    const startBound = from ? new Date(from + 'T00:00:00') : now;
    const rangeStart = startBound > now ? startBound : now;
    const rangeEnd = to ? new Date(to + 'T23:59:59.999') : new Date(now.getTime() + 30 * 86400000);
    const url = vaUrl(`${API}/api/instructor/calendar?start=${encodeURIComponent(rangeStart.toISOString())}&end=${encodeURIComponent(rangeEnd.toISOString())}`);
    const res = await fetch(url, { headers: { Authorization: 'Bearer ' + token } });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const sessions = await res.json();
    _insResched.candidates = (sessions || []).filter(s => {
      const start = new Date(s.startTime);
      return s.id !== _insResched.currentSessionId &&
        (s.status === 'SCHEDULED' || !s.status) &&
        (!_insResched.format || s.format === _insResched.format) &&
        start > now &&
        start >= rangeStart && start <= rangeEnd &&
        (Number(s.currentBookings) || 0) < (Number(s.capacity) || 0);
    }).sort((a, b) => new Date(a.startTime) - new Date(b.startTime));
    insRenderReschedList();
  } catch {
    list.innerHTML = '<div style="text-align:center;padding:24px;color:var(--color-text-muted);font-size:12px;">Failed to load sessions.</div>';
  }
}

function insRenderReschedList() {
  const list = document.getElementById('insReschedList');
  if (!list) return;
  const q = _insResched.filter.trim().toLowerCase();
  const rows = _insResched.candidates.filter(s =>
    !q || (s.className || '').toLowerCase().includes(q)
  );
  if (!rows.length) {
    list.innerHTML = '<div style="text-align:center;padding:24px;color:var(--color-text-muted);font-size:12px;">No matching future sessions with open spots.</div>';
    return;
  }
  list.innerHTML = rows.slice(0, 50).map(s => {
    const when = new Date(s.startTime).toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
    const spots = Math.max(0, (Number(s.capacity) || 0) - (Number(s.currentBookings) || 0));
    return `<div class="ins-resched-item" onclick="insConfirmResched('${esc(s.id)}')">
      <div>
        <div class="ins-resched-item-main">${esc(s.className || 'Class')} <span class="badge badge-default" style="font-size:9px;">${esc(s.format || '')}</span></div>
        <div class="ins-resched-item-sub">${esc(when)}</div>
      </div>
      <div class="ins-resched-item-sub" style="white-space:nowrap;">${spots} spot${spots === 1 ? '' : 's'} left</div>
    </div>`;
  }).join('');
}

document.getElementById('insReschedSearch')?.addEventListener('input', e => {
  _insResched.filter = e.target.value; insRenderReschedList();
});
document.getElementById('insReschedFrom')?.addEventListener('change', e => {
  _insResched.from = e.target.value; insLoadReschedCandidates();
});
document.getElementById('insReschedTo')?.addEventListener('change', e => {
  _insResched.to = e.target.value; insLoadReschedCandidates();
});

async function insConfirmResched(newSessionId) {
  if (!_insResched.attendanceId || !_insResched.currentSessionId) return;
  try {
    const res = await fetch(vaUrl(`${API}/api/instructor/booking/${_insResched.attendanceId}/reschedule`), {
      method: 'POST',
      headers: { Authorization: 'Bearer ' + token, 'Content-Type': 'application/json' },
      body: JSON.stringify({ currentSessionId: _insResched.currentSessionId, newSessionId }),
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(data.message || `HTTP ${res.status}`);
    window.showToast?.(data.message || 'Booking rescheduled', 'success');
    insCloseResched();
    insCloseDrawer();
    loadClasses();
  } catch (err) {
    window.showToast?.(err.message || 'Failed to reschedule booking', 'error');
  }
}
window.insConfirmResched = insConfirmResched;

// ── Status change handler ──
async function insOnStatusChange(selectEl, attendanceId) {
  const newStatus = selectEl.value;
  selectEl.dataset.status = newStatus;
  try {
    const r = await fetch(`${API}/api/scheduling/booking/${attendanceId}/status`, {
      method: 'PATCH',
      headers: { Authorization: 'Bearer ' + token, 'Content-Type': 'application/json' },
      body: JSON.stringify({ status: newStatus }),
    });
    if (!r.ok) throw new Error('Failed');
    window.showToast?.(`Status → ${newStatus.replace(/_/g, ' ')}`, 'success');
    // Refresh roster and class list
    if (_currentDrawerSession) insRefreshRoster(_currentDrawerSession.id);
    loadClasses();
  } catch {
    window.showToast?.('Failed to update status', 'error');
  }
}
window.insOnStatusChange = insOnStatusChange;

// ── Waitlist ──
async function insRefreshWaitlist(sessionId) {
  const el = document.getElementById('insWaitlist');
  if (!el) return;
  try {
    const entries = await fetch(vaUrl(`${API}/api/instructor/session/${sessionId}/waitlist`),
      { headers: { Authorization: 'Bearer ' + token } }).then(r => r.json());
    if (!entries.length) {
      el.innerHTML = '<div style="text-align:center;padding:32px 20px;color:var(--color-text-muted);font-size:12px;">No one on the waitlist.</div>';
      return;
    }
    const avatarColors = ['#2BB7A3','#8B5CF6','#F4923C','#3B82F6','#EC4899','#F59E0B','#10B981','#6366F1'];
    el.innerHTML = entries.map((w, idx) => {
      const initials = (w.clientName || 'U').split(' ').map(x => x[0]).join('').substring(0, 2).toUpperCase();
      const ac = avatarColors[idx % avatarColors.length];
      return `<div class="ins-att-row">
        <div class="ins-att-avatar" style="background:${ac};">${esc(initials)}</div>
        <div class="ins-att-info">
          <div class="ins-att-name">${esc(w.clientName || 'Unknown')}</div>
          <div class="ins-att-sub">${esc(w.clientPhone || w.clientEmail || '')}</div>
        </div>
        <span style="font-size:10px;font-weight:600;padding:2px 8px;border-radius:999px;background:var(--color-surface-raised,rgba(255,255,255,.06));color:var(--color-text-muted);">#${w.position}</span>
      </div>`;
    }).join('');
    const wTab = document.querySelector('.ins-dp-tab[data-tab="waitlist"]');
    if (wTab) wTab.innerHTML = `Waitlist <span style="opacity:0.6;">(${entries.length})</span>`;
  } catch {
    el.innerHTML = '<div style="text-align:center;padding:32px 20px;color:var(--color-text-muted);font-size:12px;">Failed to load waitlist.</div>';
  }
}

