      method: 'POST',
      headers: { Authorization: 'Bearer ' + token, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        classBlueprintId: bpSel.value || null,
        className,
        startTime: start.toISOString(),
        endTime: end.toISOString(),
