const IC_HOURS = Array.from({ length: 16 }, (_, i) => i + 6); // 6am–9pm

// Colors are driven by the session's REAL structured Format field
// (GROUP / PRIVATE / DUO), mirroring the admin calendar's Format palette
// for consistency — not by fuzzy class-name matching.
const IC_FORMAT_COLORS = {
  GROUP:   { bg: 'rgba(43,183,163,0.15)', accent: '#2BB7A3', text: '#5dd8c4' },
  PRIVATE: { bg: 'rgba(244,146,60,0.15)', accent: '#F4923C', text: '#f6a962' },
  DUO:     { bg: 'rgba(139,92,246,0.15)', accent: '#8B5CF6', text: '#a78bfa' },
};
const IC_DEFAULT = { bg: 'rgba(200,164,93,0.15)', accent: '#c8a45d', text: '#e0c070' };

function icGetColor(s) {
  return IC_FORMAT_COLORS[s.format || 'GROUP'] || IC_DEFAULT;
}

function icFmtTime(d) { return d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }); }
function icFmtHour(h) { return h === 0 ? '12 AM' : h < 12 ? h + ' AM' : h === 12 ? '12 PM' : (h - 12) + ' PM'; }

let icWeekStart = icGetMonday(new Date());
let icAllSessions = [];
let icView = 'week';
let icDayDate = new Date();
const icAttCache = new Map();

function icGetMonday(d) {
  const dd = new Date(d); dd.setHours(0,0,0,0);
  const day = dd.getDay();
  dd.setDate(dd.getDate() - (day === 0 ? 6 : day - 1));
  return dd;
}

// Navigation
function icChangeWeek(n) {
  if (icView === 'day') {
    icDayDate.setDate(icDayDate.getDate() + n);
    icWeekStart = icGetMonday(icDayDate);
  } else {
    icWeekStart.setDate(icWeekStart.getDate() + n * 7);
  }
  icRenderCalendar();
}
function icJumpToday() {
  icWeekStart = icGetMonday(new Date());
  icDayDate = new Date();
  icRenderCalendar();
}
function icSetView(v) {
  icView = v;
  document.querySelectorAll('.ic-seg-btn').forEach(b => b.classList.toggle('active', b.dataset.icview === v));
  if (v === 'day') icDayDate = new Date(icWeekStart);
  icRenderCalendar();
}

// Fetch & render
async function icRenderCalendar() {
  const end = new Date(icWeekStart); end.setDate(end.getDate() + 7);
  const label = document.getElementById('icWeekLabel');
  if (icView === 'week') {
    const s = icWeekStart.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
    const e = new Date(end.getTime()-1).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
    label.textContent = `${s} – ${e}`;
  } else {
    label.textContent = icDayDate.toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric', year: 'numeric' });
  }

  icAllSessions = [];
  try {
    const fStart = icView === 'week' ? icWeekStart : new Date(icDayDate.getFullYear(), icDayDate.getMonth(), icDayDate.getDate());
    const fEnd = icView === 'week' ? end : new Date(fStart.getTime() + 86400000);
    icAllSessions = await fetch(
      vaUrl(`${API}/api/instructor/calendar?start=${fStart.toISOString()}&end=${fEnd.toISOString()}`),
      { headers: { Authorization: 'Bearer ' + token } }
    ).then(r => r.json());
  } catch {}

  icRenderGrid();
  document.getElementById('icScroll').scrollTop = 0;
  icBatchFetchAtt();
}

function icRenderGrid() {
  if (icView === 'day') icRenderDayGrid();
  else icRenderWeekGrid();
