2199	  function icRenderWeekGrid() {
2200	    const headers = document.getElementById('icHeaders');
2201	    const grid = document.getElementById('icGrid');
2202	    const cols = 7;
2203	    const gtc = `48px repeat(${cols}, 1fr)`;
2204	    headers.style.gridTemplateColumns = gtc;
2205	    grid.style.gridTemplateColumns = gtc;
2206	
2207	    headers.innerHTML = '<div></div>' + Array.from({ length: cols }, (_, i) => {
2208	      const d = new Date(icWeekStart); d.setDate(d.getDate() + i);
2209	      const isToday = d.toDateString() === new Date().toDateString();
2210	      return `<div class="ic-col-header">
2211	        <div class="ch-wday">${d.toLocaleDateString('en-US', { weekday: 'short' })}</div>
2212	        <div class="ch-num ${isToday ? 'today' : ''}">${d.getDate()}</div>
2213	      </div>`;
2214	    }).join('');
2215	
2216	    // Pre-bucket sessions by "dayOffset_hour" — O(n) instead of O(n × hours × cols)
2217	    const icWeekBucket = new Map();
2218	    icAllSessions.forEach(s => {
2219	      if (s.status === 'BLOCKED' || s.status === 'CANCELLED') return;
2220	      if (classState.hasAttendees && (s.currentBookings || 0) === 0) return;
2221	      const st = new Date(s.startTime);
2222	      const dayOffset = Math.round((new Date(st.getFullYear(), st.getMonth(), st.getDate()) - new Date(icWeekStart.getFullYear(), icWeekStart.getMonth(), icWeekStart.getDate())) / 86400000);
2223	      if (dayOffset < 0 || dayOffset >= cols) return;
2224	      const key = `${dayOffset}_${st.getHours()}`;
2225	      if (!icWeekBucket.has(key)) icWeekBucket.set(key, []);
2226	      icWeekBucket.get(key).push(s);
2227	    });
2228	
2229	    grid.innerHTML = '';
2230	    IC_HOURS.forEach(h => {
2231	      const tl = document.createElement('div');
2232	      tl.className = 'ic-time-label';
2233	      tl.textContent = icFmtHour(h);
2234	      grid.appendChild(tl);
2235	
2236	      for (let d = 0; d < cols; d++) {
2237	        const cell = document.createElement('div');
2238	        cell.className = 'ic-cell';
2239	        const cellDate = new Date(icWeekStart); cellDate.setDate(cellDate.getDate() + d); cellDate.setHours(h,0,0,0);
2240	
2241	        const cellSessions = icWeekBucket.get(`${d}_${h}`) || [];
2242	
2243	        if (cellSessions.length === 1) cell.appendChild(icBuildCard(cellSessions[0]));
2244	        else if (cellSessions.length > 1) cell.appendChild(icBuildMultiPill(cellSessions, cellDate));
2245	
2246	        grid.appendChild(cell);
2247	      }
2248	    });
2249	  }
2250	
2251	  function icRenderDayGrid() {
2252	    const headers = document.getElementById('icHeaders');
2253	    const grid = document.getElementById('icGrid');
2254	    const gtc = '48px 1fr';
2255	    headers.style.gridTemplateColumns = gtc;
2256	    grid.style.gridTemplateColumns = gtc;
2257	
2258	    headers.innerHTML = '<div></div>' + `<div class="ic-col-header">
2259	      <div class="ch-wday">${icDayDate.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' })}</div>
2260	    </div>`;
2261	
2262	    // Pre-bucket sessions for this day by hour — O(n) instead of O(n × hours)
2263	    const icDayBucket = new Map();
