  function icRenderWeekGrid() {
    const headers = document.getElementById('icHeaders');
    const grid = document.getElementById('icGrid');
    const cols = 7;
    const gtc = `48px repeat(${cols}, 1fr)`;
    headers.style.gridTemplateColumns = gtc;
    grid.style.gridTemplateColumns = gtc;

    headers.innerHTML = '<div></div>' + Array.from({ length: cols }, (_, i) => {
      const d = new Date(icWeekStart); d.setDate(d.getDate() + i);
      const isToday = d.toDateString() === new Date().toDateString();
      return `<div class="ic-col-header">
        <div class="ch-wday">${d.toLocaleDateString('en-US', { weekday: 'short' })}</div>
        <div class="ch-num ${isToday ? 'today' : ''}">${d.getDate()}</div>
      </div>`;
    }).join('');

    // Pre-bucket sessions by "dayOffset_hour" — O(n) instead of O(n × hours × cols)
    const icWeekBucket = new Map();
    icAllSessions.forEach(s => {
      if (s.status === 'BLOCKED' || s.status === 'CANCELLED') return;
      if (classState.hasAttendees && (s.currentBookings || 0) === 0) return;
      const st = new Date(s.startTime);
      const dayOffset = Math.round((new Date(st.getFullYear(), st.getMonth(), st.getDate()) - new Date(icWeekStart.getFullYear(), icWeekStart.getMonth(), icWeekStart.getDate())) / 86400000);
      if (dayOffset < 0 || dayOffset >= cols) return;
      const key = `${dayOffset}_${st.getHours()}`;
      if (!icWeekBucket.has(key)) icWeekBucket.set(key, []);
      icWeekBucket.get(key).push(s);
    });

    grid.innerHTML = '';
    IC_HOURS.forEach(h => {
      const tl = document.createElement('div');
      tl.className = 'ic-time-label';
      tl.textContent = icFmtHour(h);
      grid.appendChild(tl);

      for (let d = 0; d < cols; d++) {
        const cell = document.createElement('div');
        cell.className = 'ic-cell';
        const cellDate = new Date(icWeekStart); cellDate.setDate(cellDate.getDate() + d); cellDate.setHours(h,0,0,0);

        const cellSessions = icWeekBucket.get(`${d}_${h}`) || [];

        if (cellSessions.length === 1) cell.appendChild(icBuildCard(cellSessions[0]));
        else if (cellSessions.length > 1) cell.appendChild(icBuildMultiPill(cellSessions, cellDate));

        grid.appendChild(cell);
      }
    });
  }

  function icRenderDayGrid() {
    const headers = document.getElementById('icHeaders');
    const grid = document.getElementById('icGrid');
    const gtc = '48px 1fr';
    headers.style.gridTemplateColumns = gtc;
    grid.style.gridTemplateColumns = gtc;

    headers.innerHTML = '<div></div>' + `<div class="ic-col-header">
      <div class="ch-wday">${icDayDate.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' })}</div>
    </div>`;

    // Pre-bucket sessions for this day by hour — O(n) instead of O(n × hours)
    const icDayBucket = new Map();
    icAllSessions.forEach(s => {
      if (s.status === 'BLOCKED' || s.status === 'CANCELLED') return;
      if (classState.hasAttendees && (s.currentBookings || 0) === 0) return;
      const st = new Date(s.startTime);
      if (st.getDate() !== icDayDate.getDate() || st.getMonth() !== icDayDate.getMonth() || st.getFullYear() !== icDayDate.getFullYear()) return;
      const h = st.getHours();
      if (!icDayBucket.has(h)) icDayBucket.set(h, []);
      icDayBucket.get(h).push(s);
    });

    grid.innerHTML = '';
    IC_HOURS.forEach(h => {
      const tl = document.createElement('div');
      tl.className = 'ic-time-label';
      tl.textContent = icFmtHour(h);
      grid.appendChild(tl);

      const cell = document.createElement('div');
      cell.className = 'ic-cell';
      const cellSessions = icDayBucket.get(h) || [];
      if (cellSessions.length === 1) cell.appendChild(icBuildCard(cellSessions[0]));
      else if (cellSessions.length > 1) {
        const sd = new Date(icDayDate); sd.setHours(h,0,0,0);
        cell.appendChild(icBuildMultiPill(cellSessions, sd));
      }
      grid.appendChild(cell);
    });
  }

  // Event card
  function icBuildCard(s) {
    const ev = document.createElement('div');
    ev.className = 'ic-ev';
    const color = icGetColor(s);
    const st = new Date(s.startTime), et = new Date(s.endTime);
    ev.style.setProperty('--ic-bg', color.bg);
    ev.style.setProperty('--ic-accent', color.accent);
    ev.style.setProperty('--ic-text', color.text);
    // SPM-103 — in the "All instructors" aggregate, surface whose class
    // this is (the single-instructor view omits it as redundant).
    const instructorLine = _isAllInstructors && s.instructorName
      ? `<div class="ic-ev-cap">🧑‍🏫 ${esc(s.instructorName)}</div>`
      : '';
    ev.innerHTML = `
      <div class="ic-ev-time">${esc(icFmtTime(st))} – ${esc(icFmtTime(et))}</div>
      <div class="ic-ev-name">${esc(s.className || 'Class')}</div>
      ${instructorLine}
      <div class="ic-ev-cap">👥 ${s.currentBookings ?? 0} / ${s.capacity ?? '?'}</div>
      <div class="ic-ev-clients" data-icsid="${s.id}"></div>`;
    ev.addEventListener('click', e => { e.stopPropagation(); insOpenDrawer(s.id); });
    return ev;
  }

  // Multi pill
  function icBuildMultiPill(sessions, date) {
    const pill = document.createElement('div');
    pill.className = 'ic-multi-pill';
    const dots = sessions.slice(0,3).map(s => {
      const c = icGetColor(s);
      return `<span class="ic-pill-dot" style="background:${c.accent};"></span>`;
    }).join('');
    pill.innerHTML = `<span class="ic-pill-dots">${dots}</span>
      <span class="ic-pill-label">${sessions.length} class${sessions.length !== 1 ? 'es' : ''}</span>`;
    pill.addEventListener('click', e => { e.stopPropagation(); icShowMultiDD(e, sessions, date); });
    return pill;
  }

  // Multi-event dropdown
  let _icMultiSessions = [];
  function icShowMultiDD(e, sessions, date) {
    _icMultiSessions = sessions;
    const dd = document.getElementById('icMultiDropdown');
    document.getElementById('icMultiHeader').textContent =
      `${date.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' })} · ${sessions.length} sessions`;
    document.getElementById('icMultiList').innerHTML = sessions.map((s, i) => {
      const st = new Date(s.startTime), et = new Date(s.endTime);
      const color = icGetColor(s);
      const spots = Math.max(0, (s.capacity || 0) - (s.currentBookings || 0));
      return `<button class="ic-float-item" data-icidx="${i}" style="border-left-color:${color.accent};">
        <div class="fi-name">${esc(s.className || 'Class')}</div>
        <div class="fi-time">${esc(icFmtTime(st))} – ${esc(icFmtTime(et))}</div>
        <div class="fi-cap">👥 ${s.currentBookings ?? 0}/${s.capacity ?? '?'} · ${spots} left</div>
      </button>`;
    }).join('');
    let top = e.clientY + 6, left = e.clientX + 6;
    dd.classList.add('open');
    requestAnimationFrame(() => {
      if (left + dd.offsetWidth > window.innerWidth - 12) left = window.innerWidth - dd.offsetWidth - 12;
      if (top + dd.offsetHeight > window.innerHeight - 12) top = top - dd.offsetHeight - 8;
      if (left < 8) left = 8; if (top < 8) top = 8;
      dd.style.top = top + 'px'; dd.style.left = left + 'px';
    });
  }
  function icHideMultiDD() { document.getElementById('icMultiDropdown').classList.remove('open'); _icMultiSessions = []; }

  document.getElementById('icMultiList').addEventListener('click', e => {
    const btn = e.target.closest('[data-icidx]'); if (!btn) return;
    e.stopPropagation();
    const s = _icMultiSessions[parseInt(btn.dataset.icidx)];
    icHideMultiDD();
    if (s) insOpenDrawer(s.id);
  });

  // Close floating on outside click
  document.addEventListener('click', e => {
    const dd = document.getElementById('icMultiDropdown');
    if (dd.classList.contains('open') && !dd.contains(e.target)) icHideMultiDD();
  });

  // Batch attendee fetch
  async function icBatchFetchAtt() {
    const ids = icAllSessions.filter(s => s.status !== 'BLOCKED' && s.status !== 'CANCELLED').map(s => s.id);
    const batch = 8;
    for (let i = 0; i < ids.length; i += batch) {
      await Promise.all(ids.slice(i, i + batch).map(async sid => {
        try {
          const bookings = await fetch(vaUrl(`${API}/api/scheduling/session/${sid}/bookings`),
            { headers: { Authorization: 'Bearer ' + token } }).then(r => r.json());
          icAttCache.set(sid, bookings);
          icPatchNames(sid, bookings);
        } catch {}
      }));
    }
  }
  function icPatchNames(sid, bookings) {
    const el = document.querySelector(`.ic-ev-clients[data-icsid="${sid}"]`);
    if (!el || !bookings.length) return;
    const max = 3;
    const lines = bookings.slice(0, max).map(b => {
      const parts = (b.clientName || 'Unknown').split(' ');
      const abbr = parts.length > 1 ? `${parts[0]} ${parts[parts.length-1][0]}.` : parts[0];
      return `<div class="ic-ev-client-line">⬤ ${esc(abbr)}</div>`;
    });
    if (bookings.length > max) lines.push(`<div class="ic-ev-more">+${bookings.length - max} more</div>`);
    el.innerHTML = lines.join('');
  }

  // Wire calendar controls
  document.getElementById('icPrevBtn').addEventListener('click', () => icChangeWeek(-1));
  document.getElementById('icNextBtn').addEventListener('click', () => icChangeWeek(1));
  document.getElementById('icTodayBtn').addEventListener('click', icJumpToday);
  document.getElementById('icViewWeek').addEventListener('click', () => icSetView('week'));
  document.getElementById('icViewDay').addEventListener('click', () => icSetView('day'));
  document.getElementById('icHasAttendees').addEventListener('change', (e) => {
    classState.hasAttendees = e.target.checked;
    const myCb = document.getElementById('insHasAttendees');
    if (myCb) myCb.checked = classState.hasAttendees;
    icRenderGrid();
  });

  // ── Init on load ──
  insInit();
</script>

