323	<script>
324	  const API   = import.meta.env.PUBLIC_API_URL || '';
325	  const token = localStorage.getItem('token');
326	  const esc   = (s) => String(s ?? '').replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
327	
328	  // ── State ──
329	  let currentView   = 'day';   // 'day' | 'week' | 'month'
330	  let anchorDate    = new Date(); // the "current" day/week/month pivot
331	  let allSessions   = [];
332	  let staffList     = [];
333	
334	  // ── Init ──
335	  async function calInit() {
336	    anchorDate = new Date();
337	    anchorDate.setHours(0,0,0,0);
338	    await Promise.all([loadStaff(), loadBlueprints()]);
339	    await calLoad();
