342	  // ── Navigation ──
343	  function calNav(dir) {
344	    if (currentView === 'day') {
345	      anchorDate.setDate(anchorDate.getDate() + dir);
346	    } else if (currentView === 'week') {
347	      anchorDate.setDate(anchorDate.getDate() + dir * 7);
348	    } else {
349	      anchorDate.setMonth(anchorDate.getMonth() + dir);
350	    }
351	    calLoad();
352	  }
353	
354	  function calGoToday() {
355	    anchorDate = new Date(); anchorDate.setHours(0,0,0,0);
356	    calLoad();
357	  }
358	
359	  function calSetView(v) {
360	    currentView = v;
361	    ['day','week','month'].forEach(k => {
362	      document.getElementById('calView' + k.charAt(0).toUpperCase() + k.slice(1))
363	        .classList.toggle('active', k === v);
364	    });
365	    calLoad();
366	  }
367	
368	  // ── Date range for current view ──
369	  function getRange() {
370	    const d = new Date(anchorDate);
371	    if (currentView === 'day') {
372	      const start = new Date(d); start.setHours(0,0,0,0);
373	      const end   = new Date(d); end.setHours(23,59,59,999);
374	      return { start, end };
375	    } else if (currentView === 'week') {
376	      // Mon-Sun week
377	      const dow   = d.getDay();
378	      const diff  = (dow === 0 ? -6 : 1 - dow);
379	      const start = new Date(d); start.setDate(d.getDate() + diff); start.setHours(0,0,0,0);
380	      const end   = new Date(start); end.setDate(start.getDate() + 6); end.setHours(23,59,59,999);
381	      return { start, end };
382	    } else {
383	      const start = new Date(d.getFullYear(), d.getMonth(), 1);
384	      const end   = new Date(d.getFullYear(), d.getMonth() + 1, 0, 23, 59, 59, 999);
385	      return { start, end };
386	    }
387	  }
388	
389	  function updatePeriodLabel() {
390	    const { start, end } = getRange();
391	    const lbl = document.getElementById('calPeriodLabel');
392	    if (currentView === 'day') {
393	      lbl.textContent = start.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });
394	    } else if (currentView === 'week') {
395	      const opts = { month: 'short', day: 'numeric' };
396	      lbl.textContent = `${start.toLocaleDateString('en-US', opts)} – ${end.toLocaleDateString('en-US', opts)}`;
397	    } else {
398	      lbl.textContent = start.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
399	    }
400	  }
401	
402	  // ── Load sessions ──
403	  async function calLoad() {
404	    updatePeriodLabel();
405	    document.getElementById('calSkeleton').style.display = '';
406	    document.getElementById('calList').innerHTML = '';
407	    document.getElementById('calEmpty').style.display = 'none';
408	
409	    const { start, end } = getRange();
410	    try {
411	      allSessions = await fetch(
412	        `${API}/api/scheduling?start=${start.toISOString()}&end=${end.toISOString()}`,
413	        { headers: { Authorization: 'Bearer ' + token } }
414	      ).then(r => r.json());
415	    } catch { allSessions = []; }
416	
417	    document.getElementById('calSkeleton').style.display = 'none';
418	    calRender();
419	  }
420	
421	  // ── Apply filters + render ──
422	  function calApplyFilters() { calRender(); }
423	
424	  function getFiltered() {
425	    const instrFilter   = document.getElementById('calInstructorFilter').value;
426	    const formatFilter  = document.getElementById('calFormatFilter').value;
427	    const hasAttendees  = document.getElementById('calHasAttendees').checked;
428	    const hideCompleted = document.getElementById('calHideCompleted').checked;
429	
430	    return allSessions.filter(s => {
431	      if (s.status === 'BLOCKED') return false; // skip block events
432	      if (instrFilter  && s.instructorId !== instrFilter) return false;
433	      if (formatFilter && s.format !== formatFilter) return false;
434	      if (hasAttendees && (s.currentBookings || 0) === 0) return false;
435	      if (hideCompleted && (s.status === 'COMPLETED' || s.status === 'NO_SHOW')) return false;
436	      return true;
437	    }).sort((a, b) => new Date(a.startTime) - new Date(b.startTime));
438	  }
439	
440	  function calRender() {
441	    const sessions = getFiltered();
442	    const list     = document.getElementById('calList');
443	    list.innerHTML = '';
444	
445	    // Update subtitle
446	    const { start } = getRange();
447	    const subtitle = currentView === 'day'
448	      ? `${sessions.length} session${sessions.length !== 1 ? 's' : ''} today`
449	      : currentView === 'week'
450	        ? `${sessions.length} session${sessions.length !== 1 ? 's' : ''} this week`
451	        : `${sessions.length} session${sessions.length !== 1 ? 's' : ''} in ${start.toLocaleDateString('en-US', { month: 'long' })}`;
452	    document.getElementById('calSubtitle').textContent = subtitle;
453	
454	    if (sessions.length === 0) {
455	      document.getElementById('calEmpty').style.display = '';
456	      return;
457	    }
458	    document.getElementById('calEmpty').style.display = 'none';
459	
460	    // Group by day
461	    const dayMap = new Map();
462	    sessions.forEach(s => {
463	      const key = new Date(s.startTime).toISOString().slice(0,10);
464	      if (!dayMap.has(key)) dayMap.set(key, []);
465	      dayMap.get(key).push(s);
466	    });
467	
468	    const today = new Date(); today.setHours(0,0,0,0);
469	
470	    dayMap.forEach((daySessions, dateKey) => {
471	      const d       = new Date(dateKey);
472	      const isToday = d.toDateString() === today.toDateString();
473	
474	      const hdr = document.createElement('div');
475	      hdr.className = 'cal-day-header' + (isToday ? ' today-header' : '');
476	      hdr.textContent = d.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' })
477	        + (isToday ? '  —  Today' : '');
478	      list.appendChild(hdr);
479	
480	      daySessions.forEach(s => list.appendChild(buildCard(s)));
481	    });
482	  }
483	
484	  function buildCard(s) {
485	    const start   = new Date(s.startTime);
486	    const end     = new Date(s.endTime);
487	    const durMin  = Math.round((end - start) / 60000);
488	    const h       = start.getHours();
489	    const m       = start.getMinutes();
490	    const ampm    = h >= 12 ? 'PM' : 'AM';
491	    const h12     = h % 12 || 12;
492	    const timeStr = `${h12}${m ? ':' + String(m).padStart(2,'0') : ''}`;
493	    const fmt     = (s.format || 'GROUP').toLowerCase();
494	    const cap     = s.capacity || 0;
495	    const booked  = s.currentBookings || 0;
496	    const pct     = cap > 0 ? booked / cap : 0;
497	    const fillCls = pct >= 1 ? 'full' : pct >= 0.75 ? 'high' : pct >= 0.4 ? 'mid' : 'low';
498	    const status  = (s.status || 'SCHEDULED').toLowerCase();
499	
500	    const card = document.createElement('div');
501	    card.className = 'cal-card';
502	    card.innerHTML = `
503	      <div class="cal-card-time">
504	        <div class="cal-card-time-main">${esc(timeStr)}</div>
505	        <div class="cal-card-time-ampm">${ampm}</div>
506	        <div class="cal-card-time-dur">${durMin}min</div>
507	      </div>
508	      <div class="cal-card-divider"></div>
509	      <div class="cal-card-info">
510	        <div class="cal-card-name-row">
511	          <span class="cal-card-name">${esc(s.className || '—')}</span>
512	          <span class="cal-card-badge ${fmt}">${fmt === 'mat' ? 'Mat' : fmt.charAt(0).toUpperCase() + fmt.slice(1)}</span>
513	        </div>
514	        <div class="cal-card-meta">
515	          ${s.instructorName ? `<span class="cal-card-meta-item"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="7" r="4"/><path d="M5.5 21a6.5 6.5 0 0 1 13 0"/></svg>${esc(s.instructorName)}</span>` : ''}
516	          ${s.equipmentType ? `<span class="cal-card-meta-item"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="2" y="9" width="20" height="6" rx="2"/><line x1="7" y1="9" x2="7" y2="15"/></svg>${esc(s.equipmentType)}</span>` : ''}
517	        </div>
518	      </div>
519	      <div class="cal-card-stats">
520	        <div class="cal-card-capacity">
521	          <div class="cal-fill-bar"><div class="cal-fill-inner ${fillCls}" style="width:${Math.round(pct*100)}%"></div></div>
522	          ${booked}/${cap}
523	        </div>
524	        <span class="cal-card-status ${status}">${status === 'no_show' ? 'No Show' : status.charAt(0).toUpperCase() + status.slice(1)}</span>
525	      </div>`;
526	
527	    card.addEventListener('click', () => {
528	      if (typeof window.openClassDetail === 'function') window.openClassDetail(s.id);
529	    });
530	    return card;
531	  }
