533	  // ── Staff list for filter ──
534	  async function loadStaff() {
535	    try {
536	      const r = await fetch(`${API}/api/staff`, { headers: { Authorization: 'Bearer ' + token } });
537	      if (!r.ok) return;
538	      staffList = await r.json();
539	      const sel = document.getElementById('calInstructorFilter');
540	      staffList
541	        .filter(s => s.isActive !== false)
