567	  .ic-wrap {
568	    display: flex; flex-direction: column;
569	    border: 1px solid var(--color-border-subtle, rgba(255,255,255,.08));
570	    border-radius: 12px; overflow: hidden;
571	    background: var(--color-surface, rgba(255,255,255,.02));
572	    min-height: 500px;
573	  }
574	  /* Top bar */
575	  .ic-topbar {
576	    display: flex; align-items: center; justify-content: space-between;
577	    padding: 12px 16px; border-bottom: 1px solid var(--color-border-subtle, rgba(255,255,255,.08));
578	    flex-shrink: 0; gap: 10px; flex-wrap: wrap;
579	  }
580	  .ic-topbar-left { display: flex; align-items: center; gap: 6px; }
581	  .ic-topbar-right { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
582	  .ic-nav-btn {
583	    width: 30px; height: 30px; border: 1px solid var(--color-border-subtle, rgba(255,255,255,.1));
584	    background: none; border-radius: 6px; color: var(--color-text-muted, rgba(255,255,255,.5));
585	    cursor: pointer; display: flex; align-items: center; justify-content: center; transition: all 0.12s;
586	  }
587	  .ic-nav-btn:hover { background: rgba(255,255,255,.05); color: var(--color-text-primary, #fff); }
588	  .ic-nav-btn svg { width: 13px; height: 13px; }
589	  .ic-date-label {
590	    font-size: 13px; font-weight: 600; color: var(--color-text-primary, #fff);
591	    padding: 4px 10px; border: 1px solid var(--color-border-subtle, rgba(255,255,255,.1));
592	    border-radius: 6px; background: rgba(255,255,255,.03); white-space: nowrap;
593	  }
594	  .ic-today-btn {
595	    padding: 4px 12px; font-size: 11px; font-weight: 600;
596	    border: 1px solid var(--color-border-subtle, rgba(255,255,255,.1));
597	    border-radius: 6px; background: none; cursor: pointer;
598	    color: var(--color-text-muted, rgba(255,255,255,.5)); transition: all 0.12s;
599	  }
600	  .ic-today-btn:hover { background: rgba(200,164,93,.1); color: var(--color-brand-accent, #c8a45d); }
601	  .ic-seg {
602	    display: inline-flex; border: 1px solid var(--color-border-subtle, rgba(255,255,255,.1));
603	    border-radius: 6px; overflow: hidden;
604	  }
605	  .ic-seg-btn {
606	    padding: 4px 14px; border: none; background: none; font-size: 11px; font-weight: 600;
607	    cursor: pointer; color: var(--color-text-muted, rgba(255,255,255,.5));
608	    font-family: 'Inter', sans-serif; transition: all 0.12s;
609	  }
610	  .ic-seg-btn:not(:last-child) { border-right: 1px solid var(--color-border-subtle, rgba(255,255,255,.1)); }
611	  .ic-seg-btn.active { background: var(--color-brand-accent, #c8a45d); color: white; }
612	  .ic-seg-btn:hover:not(.active) { background: rgba(255,255,255,.04); color: var(--color-text-primary, #fff); }
613	
614	  /* Column headers */
615	  .ic-col-headers {
616	    display: grid; flex-shrink: 0;
617	    border-bottom: 1px solid var(--color-border-subtle, rgba(255,255,255,.08));
618	  }
619	  .ic-col-header { padding: 8px 4px; text-align: center; }
620	  .ic-col-header .ch-wday {
621	    font-size: 10px; font-weight: 600; text-transform: uppercase;
622	    letter-spacing: 0.5px; color: var(--color-text-muted, rgba(255,255,255,.5));
623	  }
624	  .ic-col-header .ch-num {
625	    font-size: 18px; font-weight: 700; font-family: 'Inter', sans-serif;
