639	    font-size: 10px; font-weight: 500; color: var(--color-text-muted, rgba(255,255,255,.4));
640	    text-align: right; padding: 0 6px; line-height: 1; padding-top: 2px;
641	    height: var(--ic-row-h, 80px);
642	    border-bottom: 1px solid var(--color-border-subtle, rgba(255,255,255,.05));
643	    display: flex; align-items: flex-start; justify-content: flex-end;
644	  }
