667	  .ic-ev .ic-ev-name { font-size: 10px; font-weight: 700; line-height: 1.2; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
668	  .ic-ev .ic-ev-cap { font-size: 8px; opacity: 0.65; margin-top: 1px; }
669	  .ic-ev .ic-ev-clients { font-size: 8px; opacity: 0.75; line-height: 1.2; flex: 1; overflow: hidden; }
670	  .ic-ev .ic-ev-client-line { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
671	  .ic-ev .ic-ev-more { opacity: 0.5; font-style: italic; }
