680	    color: var(--color-text-primary, #fff); cursor: pointer; z-index: 2; overflow: hidden;
681	    transition: all 0.12s;
682	  }
683	  .ic-multi-pill:hover { background: rgba(200,164,93,.12); border-color: var(--color-brand-accent, #c8a45d); }
684	  .ic-multi-pill .ic-pill-dots { display: flex; gap: 2px; align-items: center; }
685	  .ic-multi-pill .ic-pill-dot { width: 5px; height: 5px; border-radius: 50%; }
686	  .ic-multi-pill .ic-pill-label { flex: 1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
687	
688	  /* Multi dropdown (floating) */
689	  .ic-floating {
690	    position: fixed; z-index: 1050; background: var(--color-surface-raised, #2a2520);
691	    border: 1px solid var(--color-border-subtle, rgba(255,255,255,.1));
692	    border-radius: 10px; padding: 6px; display: none; min-width: 200px;
693	    box-shadow: 0 8px 30px rgba(0,0,0,.3); backdrop-filter: blur(12px);
694	  }
