696	  @keyframes icPopIn { from { opacity: 0; transform: translateY(-6px) scale(.96); } to { opacity: 1; transform: translateY(0) scale(1); } }
697	  .ic-floating-header {
698	    padding: 6px 10px 8px; font-size: 11px; font-weight: 600;
699	    color: var(--color-text-muted, rgba(255,255,255,.5));
700	    border-bottom: 1px solid var(--color-border-subtle, rgba(255,255,255,.08)); margin-bottom: 4px;
701	  }
