      <label class="cg-filter-label">
        <input type="checkbox" id="cgHasAttendees" onchange="cgApplyFilters()" /> Has Attendees
      </label>
      <label class="cg-filter-label">
        <input type="checkbox" id="cgHideCompleted" onchange="cgApplyFilters()" /> Hide Completed
      </label>
    </div>

    <div class="cg-wrap">
      <div class="cg-inner-topbar">
        <div class="cg-inner-left">
          <button class="cg-today-btn" id="cgTodayBtn">Today</button>
          <button class="cg-nav-btn" id="cgPrevBtn" title="Previous">
            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="15 18 9 12 15 6"/></svg>
          </button>
          <button class="cg-nav-btn" id="cgNextBtn" title="Next">
            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="9 18 15 12 9 6"/></svg>
          </button>
          <span class="cg-date-label" id="cgWeekLabel"></span>
        </div>
        <div class="cg-inner-right">
          <div class="cg-seg">
            <button class="cg-seg-btn active" data-cgview="week" id="cgViewWeek" onclick="cgSetView('week')">Week</button>
            <button class="cg-seg-btn" data-cgview="day" id="cgViewDay" onclick="cgSetView('day')">Day</button>
          </div>
        </div>
      </div>
      <div class="cg-col-headers" id="cgHeaders"></div>
      <div class="cg-scroll" id="cgScroll">
        <div class="cg-grid" id="cgGrid"></div>
      </div>
      <div class="cg-legend">
        <div class="cg-legend-item"><span class="cg-legend-dot" style="background:#2BB7A3;"></span> Group / Mat</div>
        <div class="cg-legend-item"><span class="cg-legend-dot" style="background:#F4923C;"></span> Private</div>
        <div class="cg-legend-item"><span class="cg-legend-dot" style="background:#8B5CF6;"></span> Duo</div>
      </div>
    </div>
  </div>
</div>

<!-- Multi-event dropdown (grid view) -->
<div class="cg-floating" id="cgMultiDropdown" style="min-width:240px;max-width:300px;max-height:340px;overflow-y:auto;padding:8px;">
  <div class="cg-floating-header" id="cgMultiHeader"></div>
  <div id="cgMultiList"></div>
</div>

<!-- ═══ Class Detail Panel ═══ -->
<ClassDetailPanel />

<!-- ═══ New Session Modal ═══ -->
<div class="modal-overlay" id="calNewSessionModal">
  <div class="modal" style="max-width:420px;">
    <div class="modal-header">
      <span class="modal-title">Add manual session</span>
      <button class="modal-close" onclick="calCloseNewSession()">
        <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
      </button>
    </div>
    <div class="modal-body">
      <div class="form-group">
        <label class="form-label">Date & Start time</label>
        <input type="datetime-local" class="form-control" id="calNsStart" />
      </div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;">
        <div class="form-group">
          <label class="form-label">Duration (min)</label>
          <input type="number" class="form-control" id="calNsDuration" value="60" />
        </div>
        <div class="form-group">
          <label class="form-label">Capacity</label>
          <input type="number" class="form-control" id="calNsCapacity" value="10" />
        </div>
      </div>
      <div class="form-group">
        <label class="form-label">Class Blueprint</label>
        <select class="form-control" id="calNsBlueprint"><option value="">Select a class…</option></select>
      </div>
      <div class="form-group">
        <label class="form-label">Instructor</label>
        <select class="form-control" id="calNsInstructor"><option value="">Select instructor…</option></select>
      </div>
    </div>
    <div class="modal-footer">
      <button class="btn btn-secondary" onclick="calCloseNewSession()">Cancel</button>
      <button class="btn btn-primary" onclick="calSaveNewSession()">Create</button>
    </div>
  </div>
</div>

</AdminLayout>

<script>
  const API   = import.meta.env.PUBLIC_API_URL || '';
  const token = localStorage.getItem('token');
  const esc   = (s) => String(s ?? '').replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));

  // ── PWA detection ──
  const isPWA = window.matchMedia('(display-mode: standalone)').matches
    || window.navigator.standalone === true;

  document.getElementById(isPWA ? 'calListView' : 'calGridView').style.display = '';

  // ══════════════════════════════════════════════
  //  SHARED: staff list, blueprints, new session
  // ══════════════════════════════════════════════
  let staffList = [];

  async function loadStaff() {
    try {
      const r = await fetch(`${API}/api/staff`, { headers: { Authorization: 'Bearer ' + token } });
      if (!r.ok) return;
      staffList = await r.json();
      const active = staffList.filter(s => s.isActive !== false).sort((a,b) => (a.name||'').localeCompare(b.name||''));

      // Populate both filter dropdowns
      for (const selId of ['calInstructorFilter', 'cgInstructorFilter']) {
        const sel = document.getElementById(selId);
        if (!sel) continue;
        active.forEach(s => {
          const o = document.createElement('option'); o.value = s.id; o.textContent = s.name;
          sel.appendChild(o);
        });
      }
    } catch {}
  }

  async function loadBlueprints() {
    try {
      const r = await fetch(`${API}/api/classblueprint`, { headers: { Authorization: 'Bearer ' + token } });
      if (!r.ok) return;
      const bps = await r.json();
      const sel = document.getElementById('calNsBlueprint');
      bps.filter(b => b.isActive !== false)
        .sort((a,b) => (a.className||'').localeCompare(b.className||''))
        .forEach(b => {
          const o = document.createElement('option'); o.value = b.id; o.textContent = b.className;
          sel.appendChild(o);
        });
    } catch {}
  }

  function calOpenNewSession() {
    const anchor = isPWA ? calAnchorDate : new Date(cgWeekStart);
    anchor.setHours(9,0,0,0);
    const local = new Date(anchor.getTime() - anchor.getTimezoneOffset()*60000).toISOString().slice(0,16);
    document.getElementById('calNsStart').value = local;

    const instrSel = document.getElementById('calNsInstructor');
    if (instrSel.options.length <= 1 && staffList.length > 0) {
      staffList.filter(s => s.isActive !== false).sort((a,b) => (a.name||'').localeCompare(b.name||'')).forEach(s => {
        const o = document.createElement('option'); o.value = s.id; o.textContent = s.name;
        instrSel.appendChild(o);
      });
    }
    document.getElementById('calNewSessionModal').classList.add('open');
  }

  function calCloseNewSession() {
    document.getElementById('calNewSessionModal').classList.remove('open');
  }

  async function calSaveNewSession() {
    const startVal  = document.getElementById('calNsStart').value;
    const duration  = parseInt(document.getElementById('calNsDuration').value) || 60;
    const capacity  = parseInt(document.getElementById('calNsCapacity').value) || 10;
    const blueprint = document.getElementById('calNsBlueprint').value;
    const instrId   = document.getElementById('calNsInstructor').value;
    if (!startVal || !blueprint) { alert('Please fill in all required fields.'); return; }
    const start = new Date(startVal);
    const end   = new Date(start.getTime() + duration * 60000);
    try {
      const r = await fetch(`${API}/api/scheduling/session/manual`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + token },
        body: JSON.stringify({ classBlueprintId: blueprint, startTime: start.toISOString(), endTime: end.toISOString(), capacity, instructorId: instrId || null }),
      });
      if (!r.ok) { const e = await r.json(); alert(e.message || 'Failed to create session.'); return; }
      calCloseNewSession();
      if (isPWA) calLoad(); else cgRenderCalendar();
    } catch { alert('Network error.'); }
  }

  // ══════════════════════════════════════════════
  //  LIST VIEW (PWA)
  // ══════════════════════════════════════════════
  let calView      = 'day';
  let calAnchorDate = new Date();
  let calSessions  = [];

  function calNav(dir) {
    if (calView === 'day') calAnchorDate.setDate(calAnchorDate.getDate() + dir);
    else if (calView === 'week') calAnchorDate.setDate(calAnchorDate.getDate() + dir * 7);
    else calAnchorDate.setMonth(calAnchorDate.getMonth() + dir);
    calLoad();
  }
  function calGoToday() {
    calAnchorDate = new Date(); calAnchorDate.setHours(0,0,0,0); calLoad();
  }
  function calSetView(v) {
    calView = v;
    ['day','week','month'].forEach(k => {
      document.getElementById('calView' + k.charAt(0).toUpperCase() + k.slice(1))?.classList.toggle('active', k === v);
    });
    calLoad();
  }

  function calGetRange() {
    const d = new Date(calAnchorDate);
    if (calView === 'day') {
      const start = new Date(d); start.setHours(0,0,0,0);
      const end   = new Date(d); end.setHours(23,59,59,999);
      return { start, end };
    } else if (calView === 'week') {
      const dow  = d.getDay();
      const diff = (dow === 0 ? -6 : 1 - dow);
      const start = new Date(d); start.setDate(d.getDate() + diff); start.setHours(0,0,0,0);
      const end   = new Date(start); end.setDate(start.getDate() + 6); end.setHours(23,59,59,999);
      return { start, end };
    } else {
      const start = new Date(d.getFullYear(), d.getMonth(), 1);
      const end   = new Date(d.getFullYear(), d.getMonth() + 1, 0, 23, 59, 59, 999);
      return { start, end };
    }
  }

  function calUpdatePeriodLabel() {
    const { start, end } = calGetRange();
    const lbl = document.getElementById('calPeriodLabel');
    if (!lbl) return;
    if (calView === 'day') lbl.textContent = start.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });
    else if (calView === 'week') lbl.textContent = `${start.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })} – ${end.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}`;
    else lbl.textContent = start.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
  }

  async function calLoad() {
    calUpdatePeriodLabel();
    const skel = document.getElementById('calSkeleton');
    const list = document.getElementById('calList');
    const emp  = document.getElementById('calEmpty');
    if (skel) skel.style.display = '';
    if (list) list.innerHTML = '';
    if (emp)  emp.style.display = 'none';

    const { start, end } = calGetRange();
    try {
      calSessions = await fetch(
        `${API}/api/scheduling?start=${start.toISOString()}&end=${end.toISOString()}`,
        { headers: { Authorization: 'Bearer ' + token } }
      ).then(r => r.json());
    } catch { calSessions = []; }
    if (skel) skel.style.display = 'none';
    calRender();
  }

  function calApplyFilters() { calRender(); }

  function calGetFiltered() {
    const instrFilter   = document.getElementById('calInstructorFilter')?.value || '';
    const formatFilter  = document.getElementById('calFormatFilter')?.value || '';
    const hasAttendees  = document.getElementById('calHasAttendees')?.checked || false;
    const hideCompleted = document.getElementById('calHideCompleted')?.checked || false;
    return calSessions.filter(s => {
      if (s.status === 'BLOCKED') return false;
      if (instrFilter  && s.instructorId !== instrFilter) return false;
      if (formatFilter && s.format !== formatFilter) return false;
      if (hasAttendees && (s.currentBookings || 0) === 0) return false;
      if (hideCompleted && (s.status === 'COMPLETED' || s.status === 'NO_SHOW')) return false;
      return true;
    }).sort((a, b) => new Date(a.startTime) - new Date(b.startTime));
  }

  function calRender() {
    const sessions = calGetFiltered();
    const list = document.getElementById('calList');
    const emp  = document.getElementById('calEmpty');
    const sub  = document.getElementById('calSubtitle');
    if (!list) return;
    list.innerHTML = '';

    const { start } = calGetRange();
    const label = calView === 'day' ? `${sessions.length} session${sessions.length !== 1?'s':''} today`
      : calView === 'week' ? `${sessions.length} session${sessions.length !== 1?'s':''} this week`
      : `${sessions.length} session${sessions.length !== 1?'s':''} in ${start.toLocaleDateString('en-US', { month: 'long' })}`;
    if (sub) sub.textContent = label;

    if (sessions.length === 0) { if (emp) emp.style.display = ''; return; }
    if (emp) emp.style.display = 'none';

    const dayMap = new Map();
    sessions.forEach(s => {
      const key = new Date(s.startTime).toISOString().slice(0,10);
      if (!dayMap.has(key)) dayMap.set(key, []);
      dayMap.get(key).push(s);
    });
    const today = new Date(); today.setHours(0,0,0,0);
    dayMap.forEach((daySessions, dateKey) => {
      const d = new Date(dateKey);
      const isToday = d.toDateString() === today.toDateString();
      const hdr = document.createElement('div');
      hdr.className = 'cal-day-header' + (isToday ? ' today-header' : '');
      hdr.textContent = d.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' }) + (isToday ? '  —  Today' : '');
      list.appendChild(hdr);
      daySessions.forEach(s => list.appendChild(calBuildCard(s)));
    });
  }

  function calBuildCard(s) {
    const start  = new Date(s.startTime), end = new Date(s.endTime);
    const durMin = Math.round((end - start) / 60000);
    const h = start.getHours(), m = start.getMinutes();
    const ampm = h >= 12 ? 'PM' : 'AM', h12 = h % 12 || 12;
    const timeStr = `${h12}${m ? ':' + String(m).padStart(2,'0') : ''}`;
    const fmt  = (s.format || 'GROUP').toLowerCase();
    const cap  = s.capacity || 0, booked = s.currentBookings || 0;
    const pct  = cap > 0 ? booked / cap : 0;
    const fillCls = pct >= 1 ? 'full' : pct >= 0.75 ? 'high' : pct >= 0.4 ? 'mid' : 'low';
    const status = (s.status || 'SCHEDULED').toLowerCase();
    const card = document.createElement('div');
    card.className = 'cal-card';
    card.innerHTML = `
      <div class="cal-card-time">
        <div class="cal-card-time-main">${esc(timeStr)}</div>
        <div class="cal-card-time-ampm">${ampm}</div>
        <div class="cal-card-time-dur">${durMin}min</div>
      </div>
      <div class="cal-card-divider"></div>
      <div class="cal-card-info">
        <div class="cal-card-name-row">
          <span class="cal-card-name">${esc(s.className || '—')}</span>
          <span class="cal-card-badge ${fmt}">${fmt === 'mat' ? 'Mat' : fmt.charAt(0).toUpperCase() + fmt.slice(1)}</span>
        </div>
        <div class="cal-card-meta">
          ${s.instructorName ? `<span class="cal-card-meta-item"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="7" r="4"/><path d="M5.5 21a6.5 6.5 0 0 1 13 0"/></svg>${esc(s.instructorName)}</span>` : ''}
        </div>
      </div>
      <div class="cal-card-stats">
        <div class="cal-card-capacity">
          <div class="cal-fill-bar"><div class="cal-fill-inner ${fillCls}" style="width:${Math.round(pct*100)}%"></div></div>
          ${booked}/${cap}
        </div>
        <span class="cal-card-status ${status}">${status === 'no_show' ? 'No Show' : status.charAt(0).toUpperCase() + status.slice(1)}</span>
      </div>`;
    card.addEventListener('click', () => { if (typeof window.openClassDetail === 'function') window.openClassDetail(s.id); });
    return card;
  }

  // ══════════════════════════════════════════════
  //  GRID VIEW (Desktop)
  // ══════════════════════════════════════════════
  const CG_HOURS = Array.from({ length: 16 }, (_, i) => i + 6); // 6am–9pm
  const CG_FORMAT_COLORS = {
    GROUP:   { bg: 'rgba(43,183,163,0.15)', accent: '#2BB7A3', text: '#5dd8c4' },
    MAT:     { bg: 'rgba(43,183,163,0.12)', accent: '#2BB7A3', text: '#5dd8c4' },
    PRIVATE: { bg: 'rgba(244,146,60,0.15)', accent: '#F4923C', text: '#f6a962' },
    DUO:     { bg: 'rgba(139,92,246,0.15)', accent: '#8B5CF6', text: '#a78bfa' },
  };
  const CG_DEFAULT = { bg: 'rgba(200,164,93,0.15)', accent: '#c8a45d', text: '#e0c070' };

  let cgWeekStart  = cgGetMonday(new Date());
  let cgAllSessions = [];
  let cgView = 'week';
  let cgDayDate = new Date();

  function cgGetColor(s) { return CG_FORMAT_COLORS[s.format || 'GROUP'] || CG_DEFAULT; }
  function cgFmtTime(d) { return d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }); }
  function cgFmtHour(h) { return h === 0 ? '12 AM' : h < 12 ? h + ' AM' : h === 12 ? '12 PM' : (h-12) + ' PM'; }

  function cgGetMonday(d) {
    const dd = new Date(d); dd.setHours(0,0,0,0);
    const day = dd.getDay();
    dd.setDate(dd.getDate() - (day === 0 ? 6 : day - 1));
    return dd;
  }

  function cgSetView(v) {
    cgView = v;
    document.querySelectorAll('.cg-seg-btn').forEach(b => b.classList.toggle('active', b.dataset.cgview === v));
    if (v === 'day') cgDayDate = new Date(cgWeekStart);
    cgRenderCalendar();
  }

  function cgChangeWeek(n) {
    if (cgView === 'day') {
      cgDayDate.setDate(cgDayDate.getDate() + n);
      cgWeekStart = cgGetMonday(cgDayDate);
    } else {
      cgWeekStart.setDate(cgWeekStart.getDate() + n * 7);
    }
    cgRenderCalendar();
  }

  function cgJumpToday() {
    cgWeekStart = cgGetMonday(new Date());
    cgDayDate = new Date();
    cgRenderCalendar();
  }

  function cgGetFiltered() {
    const instrFilter   = document.getElementById('cgInstructorFilter')?.value || '';
    const formatFilter  = document.getElementById('cgFormatFilter')?.value || '';
    const hasAttendees  = document.getElementById('cgHasAttendees')?.checked || false;
    const hideCompleted = document.getElementById('cgHideCompleted')?.checked || false;
    return cgAllSessions.filter(s => {
      if (s.status === 'BLOCKED') return false;
      if (instrFilter  && s.instructorId !== instrFilter) return false;
      if (formatFilter && s.format !== formatFilter) return false;
      if (hasAttendees && (s.currentBookings || 0) === 0) return false;
      if (hideCompleted && (s.status === 'COMPLETED' || s.status === 'NO_SHOW')) return false;
      return true;
    });
  }

  function cgApplyFilters() { cgRenderGrid(); }

  async function cgRenderCalendar() {
    const end = new Date(cgWeekStart); end.setDate(end.getDate() + 7);
    const label = document.getElementById('cgWeekLabel');
    if (cgView === 'week') {
      const s = cgWeekStart.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
      const e = new Date(end.getTime()-1).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
      if (label) label.textContent = `${s} – ${e}`;
    } else {
      if (label) label.textContent = cgDayDate.toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric', year: 'numeric' });
    }

    const fStart = cgView === 'week' ? cgWeekStart : new Date(cgDayDate.getFullYear(), cgDayDate.getMonth(), cgDayDate.getDate());
    const fEnd   = cgView === 'week' ? end : new Date(fStart.getTime() + 86400000);
    try {
      cgAllSessions = await fetch(
        `${API}/api/scheduling?start=${fStart.toISOString()}&end=${fEnd.toISOString()}`,
        { headers: { Authorization: 'Bearer ' + token } }
      ).then(r => r.json());
    } catch { cgAllSessions = []; }

    const sub = document.getElementById('cgSubtitle');
    if (sub) sub.textContent = `${cgAllSessions.length} session${cgAllSessions.length !== 1 ? 's' : ''} ${cgView === 'week' ? 'this week' : 'today'}`;

    cgRenderGrid();
    const scroller = document.getElementById('cgScroll');
    if (scroller) scroller.scrollTop = 0;
  }

  function cgRenderGrid() {
    if (cgView === 'day') cgRenderDayGrid();
    else cgRenderWeekGrid();
  }

  function cgRenderWeekGrid() {
    const headers = document.getElementById('cgHeaders');
    const grid    = document.getElementById('cgGrid');
    if (!headers || !grid) return;
    const cols = 7;
    const gtc  = `48px repeat(${cols}, 1fr)`;
    headers.style.gridTemplateColumns = gtc;
    grid.style.gridTemplateColumns    = gtc;

    headers.innerHTML = '<div></div>' + Array.from({ length: cols }, (_, i) => {
      const d = new Date(cgWeekStart); d.setDate(d.getDate() + i);
      const isToday = d.toDateString() === new Date().toDateString();
      return `<div class="cg-col-header">
        <div class="ch-wday">${d.toLocaleDateString('en-US', { weekday: 'short' })}</div>
        <div class="ch-num ${isToday ? 'today' : ''}">${d.getDate()}</div>
      </div>`;
    }).join('');

    const filtered = cgGetFiltered();
    const bucket   = new Map();
    filtered.forEach(s => {
      const st = new Date(s.startTime);
      const dayOffset = Math.round((new Date(st.getFullYear(), st.getMonth(), st.getDate()) - new Date(cgWeekStart.getFullYear(), cgWeekStart.getMonth(), cgWeekStart.getDate())) / 86400000);
      if (dayOffset < 0 || dayOffset >= cols) return;
      const key = `${dayOffset}_${st.getHours()}`;
      if (!bucket.has(key)) bucket.set(key, []);
      bucket.get(key).push(s);
    });

    grid.innerHTML = '';
    CG_HOURS.forEach(h => {
      const tl = document.createElement('div');
      tl.className = 'cg-time-label';
      tl.textContent = cgFmtHour(h);
      grid.appendChild(tl);
      for (let d = 0; d < cols; d++) {
        const cell = document.createElement('div');
        cell.className = 'cg-cell';
        const cellSessions = bucket.get(`${d}_${h}`) || [];
        const cellDate = new Date(cgWeekStart); cellDate.setDate(cellDate.getDate() + d); cellDate.setHours(h,0,0,0);
        if (cellSessions.length === 1) cell.appendChild(cgBuildCard(cellSessions[0]));
        else if (cellSessions.length > 1) cell.appendChild(cgBuildMultiPill(cellSessions, cellDate));
        grid.appendChild(cell);
      }
    });
  }

  function cgRenderDayGrid() {
    const headers = document.getElementById('cgHeaders');
    const grid    = document.getElementById('cgGrid');
    if (!headers || !grid) return;
    headers.style.gridTemplateColumns = '48px 1fr';
    grid.style.gridTemplateColumns    = '48px 1fr';
    headers.innerHTML = '<div></div>' + `<div class="cg-col-header">
      <div class="ch-wday">${cgDayDate.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' })}</div>
    </div>`;

    const filtered = cgGetFiltered();
    const bucket = new Map();
    filtered.forEach(s => {
      const st = new Date(s.startTime);
      if (st.getDate() !== cgDayDate.getDate() || st.getMonth() !== cgDayDate.getMonth() || st.getFullYear() !== cgDayDate.getFullYear()) return;
      const h = st.getHours();
      if (!bucket.has(h)) bucket.set(h, []);
      bucket.get(h).push(s);
    });

    grid.innerHTML = '';
    CG_HOURS.forEach(h => {
      const tl = document.createElement('div');
      tl.className = 'cg-time-label';
      tl.textContent = cgFmtHour(h);
      grid.appendChild(tl);
      const cell = document.createElement('div');
      cell.className = 'cg-cell';
      const cellSessions = bucket.get(h) || [];
      if (cellSessions.length === 1) cell.appendChild(cgBuildCard(cellSessions[0]));
      else if (cellSessions.length > 1) {
        const sd = new Date(cgDayDate); sd.setHours(h,0,0,0);
        cell.appendChild(cgBuildMultiPill(cellSessions, sd));
      }
      grid.appendChild(cell);
    });
  }

  function cgBuildCard(s) {
    const ev  = document.createElement('div');
    ev.className = 'cg-ev';
    const color = cgGetColor(s);
    const st = new Date(s.startTime), et = new Date(s.endTime);
    ev.style.setProperty('--cg-bg', color.bg);
    ev.style.setProperty('--cg-accent', color.accent);
    ev.style.setProperty('--cg-text', color.text);
    ev.innerHTML = `
      <div class="cg-ev-time">${esc(cgFmtTime(st))} – ${esc(cgFmtTime(et))}</div>
      <div class="cg-ev-name">${esc(s.className || 'Class')}</div>
      <div class="cg-ev-cap">👥 ${s.currentBookings ?? 0} / ${s.capacity ?? '?'}</div>
      ${s.instructorName ? `<div class="cg-ev-instr">🧑‍🏫 ${esc(s.instructorName)}</div>` : ''}`;
    ev.addEventListener('click', e => { e.stopPropagation(); if (typeof window.openClassDetail === 'function') window.openClassDetail(s.id); });
    return ev;
  }

  function cgBuildMultiPill(sessions, date) {
    const pill = document.createElement('div');
    pill.className = 'cg-multi-pill';
    const dots = sessions.slice(0,3).map(s => {
      const c = cgGetColor(s);
      return `<span class="cg-pill-dot" style="background:${c.accent};"></span>`;
    }).join('');
    pill.innerHTML = `<span class="cg-pill-dots">${dots}</span>
      <span class="cg-pill-label">${sessions.length} class${sessions.length !== 1 ? 'es' : ''}</span>`;
    pill.addEventListener('click', e => { e.stopPropagation(); cgShowMultiDD(e, sessions, date); });
    return pill;
  }

  let _cgMultiSessions = [];
  function cgShowMultiDD(e, sessions, date) {
    _cgMultiSessions = sessions;
    const dd = document.getElementById('cgMultiDropdown');
    document.getElementById('cgMultiHeader').textContent =
      `${date.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' })} · ${sessions.length} sessions`;
    document.getElementById('cgMultiList').innerHTML = sessions.map((s, i) => {
      const st = new Date(s.startTime), et = new Date(s.endTime);
      const color = cgGetColor(s);
      const spots = Math.max(0, (s.capacity || 0) - (s.currentBookings || 0));
      return `<button class="cg-float-item" data-cgidx="${i}" style="border-left-color:${color.accent};">
        <div class="fi-name">${esc(s.className || 'Class')}</div>
        <div class="fi-time">${esc(cgFmtTime(st))} – ${esc(cgFmtTime(et))}</div>
        <div class="fi-cap">👥 ${s.currentBookings ?? 0}/${s.capacity ?? '?'} · ${spots} left</div>
      </button>`;
    }).join('');
    let top = e.clientY + 6, left = e.clientX + 6;
    dd.classList.add('open');
    requestAnimationFrame(() => {
      if (left + dd.offsetWidth > window.innerWidth - 12) left = window.innerWidth - dd.offsetWidth - 12;
      if (top + dd.offsetHeight > window.innerHeight - 12) top = top - dd.offsetHeight - 8;
      if (left < 8) left = 8; if (top < 8) top = 8;
      dd.style.top = top + 'px'; dd.style.left = left + 'px';
    });
  }
  function cgHideMultiDD() { document.getElementById('cgMultiDropdown').classList.remove('open'); _cgMultiSessions = []; }

  document.getElementById('cgMultiList').addEventListener('click', e => {
    const btn = e.target.closest('[data-cgidx]'); if (!btn) return;
    e.stopPropagation();
    const s = _cgMultiSessions[parseInt(btn.dataset.cgidx)];
    cgHideMultiDD();
    if (s && typeof window.openClassDetail === 'function') window.openClassDetail(s.id);
  });
  document.addEventListener('click', e => {
    const dd = document.getElementById('cgMultiDropdown');
    if (dd.classList.contains('open') && !dd.contains(e.target)) cgHideMultiDD();
  });

  // Wire grid controls
  document.getElementById('cgPrevBtn')?.addEventListener('click', () => cgChangeWeek(-1));
  document.getElementById('cgNextBtn')?.addEventListener('click', () => cgChangeWeek(1));
  document.getElementById('cgTodayBtn')?.addEventListener('click', cgJumpToday);

  // ── Init ──
  async function init() {
    calAnchorDate = new Date(); calAnchorDate.setHours(0,0,0,0);
    await Promise.all([loadStaff(), loadBlueprints()]);
    if (isPWA) {
      calLoad();
    } else {
      cgRenderCalendar();
    }
  }

  init();
</script>

