    transform: translateY(-1px);
    box-shadow: 0 4px 16px rgba(0,0,0,.12);
  }

  .cal-card-time {
    display: flex; flex-direction: column; align-items: center;
    justify-content: center; flex-shrink: 0; width: 60px; text-align: center; gap: 1px;
  }
  .cal-card-time-main { font-size: 17px; font-weight: 700; color: var(--color-text-primary); letter-spacing: -0.5px; line-height: 1.1; }
  .cal-card-time-ampm { font-size: 9px; font-weight: 600; color: var(--color-text-muted); text-transform: uppercase; letter-spacing: 0.5px; }
  .cal-card-time-dur { font-size: 10px; font-weight: 500; color: var(--color-text-muted); margin-top: 3px; white-space: nowrap; }

  .cal-card-divider {
    flex-shrink: 0; width: 1px;
    background: var(--color-border-subtle);
    margin: 2px 14px; align-self: stretch;
  }

  .cal-card-info {
    flex: 1; min-width: 0; display: flex;
    flex-direction: column; justify-content: center; gap: 4px;
  }
  .cal-card-name-row { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
  .cal-card-name { font-size: 14px; font-weight: 600; color: var(--color-text-primary); line-height: 1.2; }
  .cal-card-badge {
    font-size: 9px; font-weight: 700; padding: 2px 7px;
    border-radius: 4px; text-transform: uppercase; letter-spacing: 0.04em;
  }
  .cal-card-badge.group  { background: rgba(43,183,163,.15);  color: #2bb7a3; }
  .cal-card-badge.mat    { background: rgba(99,179,237,.15);   color: #63b3ed; }
  .cal-card-badge.private { background: rgba(244,146,60,.15); color: #f4923c; }
  .cal-card-badge.duo    { background: rgba(139,92,246,.15);   color: #8b5cf6; }
  .cal-card-badge.blocked { background: rgba(239,68,68,.12);  color: #ef4444; }
  .cal-card-meta { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
  .cal-card-meta-item {
    display: inline-flex; align-items: center; gap: 4px;
    font-size: 11px; color: var(--color-text-muted);
  }
  .cal-card-meta-item svg { width: 12px; height: 12px; flex-shrink: 0; }

  .cal-card-stats {
    display: flex; flex-direction: column; align-items: flex-end;
    justify-content: center; gap: 6px; flex-shrink: 0; margin-left: 12px; min-width: 90px;
  }
  .cal-card-capacity { display: flex; align-items: center; gap: 6px; font-size: 12px; font-weight: 600; color: var(--color-text-primary); }
  .cal-fill-bar {
    width: 36px; height: 5px; border-radius: 3px;
    background: var(--color-border-subtle); overflow: hidden;
  }
  .cal-fill-inner { height: 100%; border-radius: 3px; transition: width 0.3s; }
  .cal-fill-inner.low  { background: #4ade80; }
  .cal-fill-inner.mid  { background: var(--color-brand-accent); }
  .cal-fill-inner.high { background: #facc15; }
  .cal-fill-inner.full { background: #ef4444; }
  .cal-card-status {
    font-size: 10px; font-weight: 700; padding: 2px 7px;
    border-radius: 4px; text-transform: uppercase; letter-spacing: 0.04em; white-space: nowrap;
  }
  .cal-card-status.scheduled { background: rgba(255,255,255,.06); color: var(--color-text-muted); }
  .cal-card-status.completed { background: rgba(74,222,128,.12);  color: #4ade80; }
  .cal-card-status.cancelled { background: rgba(239,68,68,.12);  color: #ef4444; }
  .cal-card-status.no_show   { background: rgba(239,68,68,.12);  color: #ef4444; }

  .cal-skeleton-row {
    height: 70px; border-radius: 12px; margin-bottom: 8px;
    background: linear-gradient(90deg, rgba(255,255,255,.03) 25%, rgba(255,255,255,.07) 50%, rgba(255,255,255,.03) 75%);
    background-size: 200% 100%;
    animation: cal-pulse 1.4s ease infinite;
  }
  @keyframes cal-pulse { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }
  .cal-empty {
    text-align: center; padding: 64px 24px;
    color: var(--color-text-muted);
  }
  .cal-empty-icon {
    width: 56px; height: 56px; margin: 0 auto 16px; border-radius: 50%;
    background: rgba(200,164,93,.1);
    display: flex; align-items: center; justify-content: center;
    color: var(--color-brand-accent);
  }
  .cal-empty-icon svg { width: 24px; height: 24px; }
  .cal-empty h3 { font-size: 1.1rem; font-weight: 600; margin: 0 0 6px; color: var(--color-text-primary); }
  .cal-empty p  { margin: 0; font-size: 13px; }

  @media (max-width: 768px) {
    .cal-card { padding: 10px 12px; }
    .cal-card-time { width: 48px; }
    .cal-card-time-main { font-size: 14px; }
    .cal-card-stats { min-width: 72px; }
  }

  /* ═══ Admin Calendar Grid View (Desktop) ═══ */
  .cg-page { max-width: 1400px; margin: 0 auto; padding: 0 0 40px; }
  .cg-topbar {
    display: flex; align-items: center; justify-content: space-between;
    padding: 20px 0 16px; flex-wrap: wrap; gap: 12px;
  }
  .cg-topbar-left { display: flex; flex-direction: column; gap: 2px; }
  .cg-topbar-title { font-size: 22px; font-weight: 700; color: var(--color-text-primary); letter-spacing: -0.3px; }
  .cg-topbar-subtitle { font-size: 12.5px; color: var(--color-text-muted); }
  .cg-topbar-right { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }

  .cg-filters {
    display: flex; gap: 8px; align-items: center; flex-wrap: wrap; margin-bottom: 16px;
  }
  .cg-filter-select {
    padding: 7px 12px; border: 1px solid var(--color-border);
    border-radius: var(--radius-sm); background: var(--color-surface);
    color: var(--color-text-primary); font-size: 12.5px;
    font-family: 'Inter', sans-serif; cursor: pointer; outline: none;
  }
  .cg-filter-select:focus { border-color: var(--color-brand-accent); }
  .cg-filter-label {
    display: flex; align-items: center; gap: 6px;
    font-size: 12px; color: var(--color-text-muted); cursor: pointer;
  }
  .cg-filter-label input { accent-color: var(--color-brand-accent); cursor: pointer; }

  /* Grid wrap */
  .cg-wrap {
    display: flex; flex-direction: column;
    border: 1px solid var(--color-border-subtle, rgba(255,255,255,.08));
    border-radius: 12px; overflow: hidden;
    background: var(--color-surface, rgba(255,255,255,.02));
    min-height: 500px;
  }
  .cg-inner-topbar {
    display: flex; align-items: center; justify-content: space-between;
    padding: 12px 16px; border-bottom: 1px solid var(--color-border-subtle, rgba(255,255,255,.08));
    flex-shrink: 0; gap: 10px; flex-wrap: wrap;
  }
  .cg-inner-left { display: flex; align-items: center; gap: 6px; }
  .cg-inner-right { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
  .cg-nav-btn {
    width: 30px; height: 30px; border: 1px solid var(--color-border-subtle, rgba(255,255,255,.1));
    background: none; border-radius: 6px; color: var(--color-text-muted, rgba(255,255,255,.5));
    cursor: pointer; display: flex; align-items: center; justify-content: center; transition: all 0.12s;
  }
  .cg-nav-btn:hover { background: rgba(255,255,255,.05); color: var(--color-text-primary, #fff); }
  .cg-nav-btn svg { width: 13px; height: 13px; }
  .cg-date-label {
    font-size: 13px; font-weight: 600; color: var(--color-text-primary, #fff);
    padding: 4px 10px; border: 1px solid var(--color-border-subtle, rgba(255,255,255,.1));
    border-radius: 6px; background: rgba(255,255,255,.03); white-space: nowrap;
  }
  .cg-today-btn {
    padding: 4px 12px; font-size: 11px; font-weight: 600;
    border: 1px solid var(--color-border-subtle, rgba(255,255,255,.1));
    border-radius: 6px; background: none; cursor: pointer;
    color: var(--color-text-muted, rgba(255,255,255,.5)); transition: all 0.12s;
  }
  .cg-today-btn:hover { background: rgba(200,164,93,.1); color: var(--color-brand-accent, #c8a45d); }
  .cg-seg {
    display: inline-flex; border: 1px solid var(--color-border-subtle, rgba(255,255,255,.1));
    border-radius: 6px; overflow: hidden;
  }
  .cg-seg-btn {
    padding: 4px 14px; border: none; background: none; font-size: 11px; font-weight: 600;
    cursor: pointer; color: var(--color-text-muted, rgba(255,255,255,.5));
    font-family: 'Inter', sans-serif; transition: all 0.12s;
  }
  .cg-seg-btn:not(:last-child) { border-right: 1px solid var(--color-border-subtle, rgba(255,255,255,.1)); }
  .cg-seg-btn.active { background: var(--color-brand-accent, #c8a45d); color: white; }
  .cg-seg-btn:hover:not(.active) { background: rgba(255,255,255,.04); color: var(--color-text-primary, #fff); }

  .cg-col-headers {
    display: grid; flex-shrink: 0;
    border-bottom: 1px solid var(--color-border-subtle, rgba(255,255,255,.08));
  }
  .cg-col-header { padding: 8px 4px; text-align: center; }
  .cg-col-header .ch-wday {
    font-size: 10px; font-weight: 600; text-transform: uppercase;
    letter-spacing: 0.5px; color: var(--color-text-muted, rgba(255,255,255,.5));
  }
  .cg-col-header .ch-num {
    font-size: 18px; font-weight: 700; font-family: 'Inter', sans-serif;
    letter-spacing: -0.3px; line-height: 1; color: var(--color-text-primary, #fff); margin-top: 2px;
  }
  .cg-col-header .ch-num.today {
    display: inline-flex; align-items: center; justify-content: center;
    background: var(--color-brand-accent, #c8a45d); color: white;
    width: 30px; height: 30px; border-radius: 50%;
    box-shadow: 0 2px 8px rgba(200,164,93,0.3);
  }

  .cg-scroll { flex: 1; overflow-y: auto; overflow-x: hidden; max-height: 680px; }
  .cg-grid { display: grid; position: relative; }
  .cg-time-label {
    font-size: 10px; font-weight: 500; color: var(--color-text-muted, rgba(255,255,255,.4));
    text-align: right; padding: 0 6px; line-height: 1; padding-top: 2px;
    height: var(--cg-row-h, 80px);
    border-bottom: 1px solid var(--color-border-subtle, rgba(255,255,255,.05));
    display: flex; align-items: flex-start; justify-content: flex-end;
  }
  .cg-cell {
    height: var(--cg-row-h, 80px);
    border-bottom: 1px solid var(--color-border-subtle, rgba(255,255,255,.05));
    border-left: 1px solid var(--color-border-subtle, rgba(255,255,255,.05));
    position: relative;
  }

  .cg-ev {
    position: absolute; top: 2px; bottom: 2px; left: 3px; right: 3px;
    border-radius: 5px; padding: 3px 6px; font-size: 10px;
    cursor: pointer; overflow: hidden; z-index: 1;
    border-left: 3px solid var(--cg-accent, var(--color-brand-accent, #c8a45d));
    background: var(--cg-bg, rgba(200,164,93,0.12));
    color: var(--cg-text, #e0c070); transition: all 0.12s;
    display: flex; flex-direction: column;
  }
  .cg-ev:hover {
    filter: brightness(1.12); transform: scale(1.01);
    z-index: 5; box-shadow: 0 4px 16px rgba(0,0,0,0.25);
  }
  .cg-ev .cg-ev-time { font-size: 8px; opacity: 0.6; line-height: 1; margin-bottom: 1px; white-space: nowrap; }
  .cg-ev .cg-ev-name { font-size: 10px; font-weight: 700; line-height: 1.2; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .cg-ev .cg-ev-cap { font-size: 8px; opacity: 0.65; margin-top: 1px; }
  .cg-ev .cg-ev-instr { font-size: 8px; opacity: 0.65; margin-top: 1px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

  .cg-multi-pill {
    position: absolute; top: 3px; left: 3px; right: 3px;
    display: flex; align-items: center; gap: 4px;
    background: var(--color-surface-raised, rgba(255,255,255,.06));
    border: 1px solid var(--color-border-subtle, rgba(255,255,255,.1));
    border-radius: 5px; padding: 4px 6px; font-size: 10px; font-weight: 600;
    color: var(--color-text-primary, #fff); cursor: pointer; z-index: 2; overflow: hidden;
    transition: all 0.12s;
  }
  .cg-multi-pill:hover { background: rgba(200,164,93,.12); border-color: var(--color-brand-accent, #c8a45d); }
  .cg-multi-pill .cg-pill-dots { display: flex; gap: 2px; align-items: center; }
  .cg-multi-pill .cg-pill-dot { width: 5px; height: 5px; border-radius: 50%; }
  .cg-multi-pill .cg-pill-label { flex: 1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

  .cg-floating {
    position: fixed; z-index: 1050; background: var(--color-surface-raised, #2a2520);
    border: 1px solid var(--color-border-subtle, rgba(255,255,255,.1));
    border-radius: 10px; padding: 6px; display: none; min-width: 200px;
    box-shadow: 0 8px 30px rgba(0,0,0,.3); backdrop-filter: blur(12px);
  }
  .cg-floating.open { display: block; animation: cgPopIn .15s ease; }
  @keyframes cgPopIn { from { opacity: 0; transform: translateY(-6px) scale(.96); } to { opacity: 1; transform: translateY(0) scale(1); } }
  .cg-floating-header {
