    if (!isPWA) return;

    const calPage = document.getElementById('calPage');
    const pwaView = document.getElementById('pwaListView');
    if (calPage) calPage.style.display = 'none';
    if (pwaView) pwaView.style.display = 'flex';

    const esc = (s) => String(s ?? '').replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));

    let pwaView_ = 'day';
    let pwaAnchor = new Date(); pwaAnchor.setHours(0,0,0,0);
    let pwaSessions = [];

    function pwaGetRange() {
      const d = new Date(pwaAnchor);
      if (pwaView_ === 'day') {
        return { start: new Date(new Date(pwaAnchor).setHours(0,0,0,0)), end: new Date(new Date(pwaAnchor).setHours(23,59,59,999)) };
      } else if (pwaView_ === 'week') {
        const dow = d.getDay(), diff = dow === 0 ? -6 : 1 - dow;
        const start = new Date(d); start.setDate(d.getDate() + diff); start.setHours(0,0,0,0);
        const end = new Date(start); end.setDate(start.getDate() + 6); end.setHours(23,59,59,999);
        return { start, end };
      } else {
        return {
          start: new Date(d.getFullYear(), d.getMonth(), 1),
          end: new Date(d.getFullYear(), d.getMonth() + 1, 0, 23, 59, 59, 999),
        };
      }
    }

    function pwaUpdateLabel() {
      const { start, end } = pwaGetRange();
      const lbl = document.getElementById('pwaPeriodLabel');
      if (!lbl) return;
      if (pwaView_ === 'day') lbl.textContent = start.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });
      else if (pwaView_ === 'week') lbl.textContent = `${start.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })} – ${end.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}`;
      else lbl.textContent = start.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
    }

    async function pwaLoad() {
      pwaUpdateLabel();
      document.getElementById('pwaSkeleton').style.display = '';
      document.getElementById('pwaList').innerHTML = '';
      document.getElementById('pwaEmpty').style.display = 'none';
      const { start, end } = pwaGetRange();
      try {
        pwaSessions = await fetch(
          `${API}/api/scheduling?start=${start.toISOString()}&end=${end.toISOString()}`,
          { headers: { Authorization: 'Bearer ' + token } }
        ).then(r => r.json());
      } catch { pwaSessions = []; }
      document.getElementById('pwaSkeleton').style.display = 'none';
      pwaRender();
    }

    function pwaRender() {
      const sessions = pwaSessions
        .filter(s => s.status !== 'BLOCKED')
        .sort((a, b) => new Date(a.startTime) - new Date(b.startTime));
      const list = document.getElementById('pwaList');
      const emp  = document.getElementById('pwaEmpty');
      const sub  = document.getElementById('pwaSubtitle');
      list.innerHTML = '';
      if (sub) sub.textContent = `${sessions.length} session${sessions.length !== 1 ? 's' : ''}`;
      if (!sessions.length) { emp.style.display = ''; return; }
      emp.style.display = 'none';

      const FORMAT_COLOR = { GROUP:'#2BB7A3', MAT:'#63b3ed', PRIVATE:'#F4923C', DUO:'#8B5CF6' };
      const today = new Date(); today.setHours(0,0,0,0);
      const dayMap = new Map();
      sessions.forEach(s => {
        const key = new Date(s.startTime).toISOString().slice(0,10);
        if (!dayMap.has(key)) dayMap.set(key, []);
        dayMap.get(key).push(s);
      });

      dayMap.forEach((daySessions, dateKey) => {
        const d = new Date(dateKey);
        const isToday = d.toDateString() === today.toDateString();
        const hdr = document.createElement('div');
        hdr.style.cssText = `font-size:11px;font-weight:700;color:${isToday ? 'var(--color-brand-accent)' : 'var(--color-text-muted)'};text-transform:uppercase;letter-spacing:.06em;padding:12px 0 7px;margin-top:6px;border-bottom:1px solid var(--color-border-subtle);`;
        hdr.textContent = d.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' }) + (isToday ? '  —  Today' : '');
        list.appendChild(hdr);

        daySessions.forEach(s => {
          const st = new Date(s.startTime), et = new Date(s.endTime);
          const durMin = Math.round((et - st) / 60000);
          const h = st.getHours(), m = st.getMinutes();
          const ampm = h >= 12 ? 'PM' : 'AM', h12 = h % 12 || 12;
          const timeStr = `${h12}${m ? ':' + String(m).padStart(2,'0') : ''}`;
          const fmt = (s.format || 'GROUP');
          const accent = FORMAT_COLOR[fmt] || 'var(--color-brand-accent)';
          const cap = s.capacity || 0, booked = s.currentBookings || 0;
          const pct = cap > 0 ? booked / cap : 0;
          const fillColor = pct >= 1 ? '#ef4444' : pct >= 0.75 ? '#facc15' : pct >= 0.4 ? 'var(--color-brand-accent)' : '#4ade80';
          const status = (s.status || 'SCHEDULED').toLowerCase();

          const card = document.createElement('div');
          card.style.cssText = 'display:flex;align-items:stretch;gap:0;padding:12px 14px;background:var(--color-surface);border:1px solid var(--color-border-subtle);border-radius:10px;margin-top:8px;cursor:pointer;transition:all .15s;';
          card.innerHTML = `
            <div style="display:flex;flex-direction:column;align-items:center;justify-content:center;flex-shrink:0;width:52px;text-align:center;gap:1px;">
              <div style="font-size:16px;font-weight:700;color:var(--color-text-primary);letter-spacing:-.5px;line-height:1.1;">${esc(timeStr)}</div>
              <div style="font-size:9px;font-weight:600;color:var(--color-text-muted);text-transform:uppercase;">${ampm}</div>
              <div style="font-size:10px;color:var(--color-text-muted);margin-top:2px;">${durMin}m</div>
            </div>
            <div style="flex-shrink:0;width:1px;background:var(--color-border-subtle);margin:2px 12px;align-self:stretch;"></div>
            <div style="flex:1;min-width:0;display:flex;flex-direction:column;justify-content:center;gap:3px;">
              <div style="display:flex;align-items:center;gap:7px;flex-wrap:wrap;">
                <span style="font-size:13px;font-weight:600;color:var(--color-text-primary);line-height:1.2;">${esc(s.className || '—')}</span>
                <span style="font-size:9px;font-weight:700;padding:2px 6px;border-radius:4px;text-transform:uppercase;background:${accent}22;color:${accent};">${esc(fmt)}</span>
              </div>
              ${s.instructorName ? `<div style="font-size:11px;color:var(--color-text-muted);">${esc(s.instructorName)}</div>` : ''}
            </div>
            <div style="display:flex;flex-direction:column;align-items:flex-end;justify-content:center;gap:5px;flex-shrink:0;margin-left:10px;">
              <div style="display:flex;align-items:center;gap:5px;font-size:12px;font-weight:600;color:var(--color-text-primary);">
                <div style="width:32px;height:4px;border-radius:3px;background:var(--color-border-subtle);overflow:hidden;">
                  <div style="height:100%;border-radius:3px;background:${fillColor};width:${Math.round(pct*100)}%;"></div>
                </div>
                ${booked}/${cap}
              </div>
              <span style="font-size:10px;font-weight:700;padding:2px 6px;border-radius:4px;text-transform:uppercase;${status==='completed'?'background:rgba(74,222,128,.12);color:#4ade80;':status==='cancelled'?'background:rgba(239,68,68,.12);color:#ef4444;':'background:rgba(255,255,255,.06);color:var(--color-text-muted);'}">${status==='no_show'?'No Show':status.charAt(0).toUpperCase()+status.slice(1)}</span>
            </div>`;
          card.addEventListener('mouseenter', () => { card.style.borderColor='rgba(200,164,93,.35)'; card.style.transform='translateY(-1px)'; });
          card.addEventListener('mouseleave', () => { card.style.borderColor=''; card.style.transform=''; });
          card.addEventListener('click', () => { if (typeof window.openDetailPanel === 'function') window.openDetailPanel(s.id); });
          list.appendChild(card);
        });
      });
    }

    window.pwaNav = function(dir) {
      if (pwaView_ === 'day') pwaAnchor.setDate(pwaAnchor.getDate() + dir);
      else if (pwaView_ === 'week') pwaAnchor.setDate(pwaAnchor.getDate() + dir * 7);
      else pwaAnchor.setMonth(pwaAnchor.getMonth() + dir);
      pwaLoad();
    };
    window.pwaGoToday = function() { pwaAnchor = new Date(); pwaAnchor.setHours(0,0,0,0); pwaLoad(); };
    window.pwaSetView = function(v) {
      pwaView_ = v;
      ['day','week','month'].forEach(k => {
        const btn = document.getElementById('pwaView' + k.charAt(0).toUpperCase() + k.slice(1));
        if (btn) {
          btn.style.background = k === v ? 'var(--color-brand-accent)' : 'none';
          btn.style.color = k === v ? '#fff' : 'var(--color-text-muted)';
        }
      });
      pwaLoad();
    };

    pwaLoad();
  })();
</script>

