/* ═══ Init ═══ */
ClassDetailPanel.init({
  mode: 'panel',
  getToken: () => localStorage.getItem('token') || '',
  getStaffList: () => staffList,
  getRole: () => myRole,
  onClose: () => {
    selectedSessionId = null;
    document.querySelectorAll('.ev.selected').forEach(el => el.classList.remove('selected'));
  },
  afterAttendanceUpdate: async (sid) => {
    await renderCalendar();
  },
  afterSessionEdit: async (sid) => {
    await renderCalendar();
    // Re-open the updated session after calendar refresh
    setTimeout(() => {
      const updated = allSessions.find(s => s.id === sid);
      if (updated) openDetailPanel(updated);
      else ClassDetailPanel.open(sid);
    }, 500);
  },
  afterSessionCancel: async () => {
    await renderCalendar();
  },
  // SPM-70 — after blocking/unblocking from the panel, refresh the calendar
  // so the blocked styling (or restored class) reflects immediately.
  afterBlockToggle: async () => {
    await renderCalendar();
  },
});

// Sync the "Color by" selector with the persisted preference.
const colorBySel = document.getElementById('colorBySelect');
if (colorBySel) colorBySel.value = colorBy;

loadScheduleConfig().then(() => loadStaff().then(() => renderCalendar()));

/* ═══ Window exports ═══ */
window.changeWeek = changeWeek;

