  selectedSessionId = session.id;
  // Highlight selected card
  document.querySelectorAll('.ev.selected').forEach(el => el.classList.remove('selected'));
  document.querySelectorAll(`.ev-clients[data-sid="${session.id}"]`).forEach(el => {
    el.closest('.ev')?.classList.add('selected');
  });
  ClassDetailPanel.open(session.id);
}

