1	using Microsoft.Extensions.DependencyInjection;
2	using Microsoft.Extensions.Hosting;
3	using Microsoft.Extensions.Logging;
4	using Microsoft.Extensions.Options;
5	using MongoDB.Driver;
6	using SoulPilates.Core.Configuration;
7	using SoulPilates.Core.Entities;
8	using SoulPilates.Infrastructure.Data;
9	
10	namespace SoulPilates.Services;
11	
12	/// <summary>
13	/// Runs once at application startup to ensure the configured admin account
14	/// exists in the Users collection.  If the email is already present the
15	/// seeder is a complete no-op and never modifies any existing data.
16	///
17	/// Production override (Docker Compose stack environment group):
18	///   AdminSeed__Email     = admin@your-domain.com
19	///   AdminSeed__Password  = (strong password — operator changes after first login)
20	/// </summary>
21	public class AdminSeederHostedService : IHostedService
22	{
23	    private readonly IServiceProvider _services;
24	    private readonly ILogger<AdminSeederHostedService> _logger;
25	
26	    public AdminSeederHostedService(
27	        IServiceProvider services,
28	        ILogger<AdminSeederHostedService> logger)
29	    {
30	        _services = services;
31	        _logger = logger;
32	    }
33	
34	    public async Task StartAsync(CancellationToken cancellationToken)
35	    {
36	        using var scope = _services.CreateScope();
37	
38	        var settings = scope.ServiceProvider
39	            .GetRequiredService<IOptions<AdminSeedSettings>>().Value;
40	
41	        if (!settings.Enabled)
42	        {
43	            _logger.LogInformation("[AdminSeeder] Seeding disabled — skipping.");
44	            return;
45	        }
46	
47	        var email = settings.Email?.Trim().ToLowerInvariant() ?? string.Empty;
48	        var password = settings.Password?.Trim() ?? string.Empty;
49	
