using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using MongoDB.Driver;
using SoulPilates.Core.Configuration;
using SoulPilates.Core.Entities;
using SoulPilates.Infrastructure.Data;

namespace SoulPilates.Services;

/// <summary>
/// Runs once at application startup to ensure the configured admin account
/// exists in the Users collection.  If the email is already present the
/// seeder is a complete no-op and never modifies any existing data.
///
/// Production override (Docker Compose stack environment group):
///   AdminSeed__Email     = admin@your-domain.com
///   AdminSeed__Password  = (strong password — operator changes after first login)
/// </summary>
public class AdminSeederHostedService : IHostedService
{
    private readonly IServiceProvider _services;
    private readonly ILogger<AdminSeederHostedService> _logger;

    public AdminSeederHostedService(
        IServiceProvider services,
        ILogger<AdminSeederHostedService> logger)
    {
        _services = services;
        _logger = logger;
    }

    public async Task StartAsync(CancellationToken cancellationToken)
    {
        using var scope = _services.CreateScope();

        var settings = scope.ServiceProvider
            .GetRequiredService<IOptions<AdminSeedSettings>>().Value;

        if (!settings.Enabled)
        {
            _logger.LogInformation("[AdminSeeder] Seeding disabled — skipping.");
            return;
        }

        var email = settings.Email?.Trim().ToLowerInvariant() ?? string.Empty;
        var password = settings.Password?.Trim() ?? string.Empty;

        if (string.IsNullOrEmpty(email) || string.IsNullOrEmpty(password))
        {
            _logger.LogWarning(
                "[AdminSeeder] AdminSeed.Email or AdminSeed.Password is empty — skipping seed. " +
                "Set them in appsettings.json or via Docker Compose environment variables.");
            return;
        }

        var dbContext = scope.ServiceProvider.GetRequiredService<MongoDbContext>();
        var users = dbContext.GetCollection<User>("Users");

        var existing = await users
            .Find(u => u.Email == email)
            .FirstOrDefaultAsync(cancellationToken);

        if (existing is not null)
        {
            _logger.LogInformation(
                "[AdminSeeder] Admin '{Email}' already exists — skipping seed.",
                email);
            return;
        }

        var admin = new User
        {
            Name     = settings.Name?.Trim() is { Length: > 0 } n ? n : "Soul Pilates Admin",
            Email    = email,
            PasswordHash = PasswordHasher.Hash(password),
            Role     = "Admin"
        };

        await users.InsertOneAsync(admin, cancellationToken: cancellationToken);

        _logger.LogInformation(
            "[AdminSeeder] Admin '{Email}' seeded successfully. " +
            "Please change the default password after first login.",
            email);
    }

    public Task StopAsync(CancellationToken cancellationToken) => Task.CompletedTask;
}

