// Soul Pilates — service worker v2.0.0
//
// Intentionally minimal: push notifications only.
// All caching is delegated to the browser's native HTTP cache via
// Cache-Control headers set by nginx — no SW cache interception.
// This avoids the fetch-interception overhead that caused freezes on iOS.

const SW_VERSION = "v2.1.0";

// ── Install: take over immediately, no precache ──────────────────────────
self.addEventListener("install", (event) => {
  event.waitUntil(self.skipWaiting());
});

// ── Activate: clean up any old caches from v1.x, claim all clients ───────
self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.map((k) => caches.delete(k)));
      await self.clients.claim();
    })()
  );
});

// ── Push: show a notification ─────────────────────────────────────────────
self.addEventListener("push", (event) => {
  if (!event.data) return;

  let payload;
  try {
    payload = event.data.json();
  } catch {
    payload = { title: "Soul Pilates", body: event.data.text() };
  }

  const {
    title = "Soul Pilates",
    body = "",
    icon = "/icons/icon-192.png",
    badge = "/icons/icon-192.png",
    url = "/admin/",
    tag,
  } = payload;

  event.waitUntil(
    self.registration.showNotification(title, {
      body,
      icon,
      badge,
      tag,
      data: { url },
      requireInteraction: true,  // keep banner visible until user taps it
      vibrate: [200, 100, 200],  // short-pause-short pulse for visibility
    })
  );
});

// ── Notification click: focus existing window or open a new one ───────────
self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const targetUrl =
    (event.notification.data && event.notification.data.url) || "/admin/";

  event.waitUntil(
    (async () => {
      const all = await self.clients.matchAll({
        type: "window",
        includeUncontrolled: true,
      });
      for (const client of all) {
        if (client.url.includes(self.location.origin)) {
          await client.focus();
          if ("navigate" in client) await client.navigate(targetUrl);
          return;
        }
      }
      await self.clients.openWindow(targetUrl);
    })()
  );
});

// ── Message: allow pages to trigger skipWaiting ───────────────────────────
self.addEventListener("message", (event) => {
  if (event.data && event.data.type === "SKIP_WAITING") {
    self.skipWaiting();
  }
});

