using MongoDB.Bson;
using MongoDB.Bson.Serialization.Attributes;

namespace SoulPilates.Core.Entities;

/// <summary>
/// A single first-party web-analytics event captured from the public site
/// (booking portal, packages, checkout, etc). Two shapes share one collection,
/// discriminated by <see cref="Type"/>:
///   • "pageview"    — one row per page load.
///   • "funnel_step" — one row per booking-funnel milestone (see <see cref="FunnelStep"/>).
///
/// <para>
/// Rows are written by the anonymous <c>POST /api/track</c> beacon and read back
/// only by the admin analytics dashboard aggregations. Nothing here is PII-linked
/// to a Client — the <see cref="VisitorId"/> is an opaque first-party id minted in
/// the browser, not an account id.
/// </para>
/// </summary>
public class VisitorEvent : BaseEntity
{
    /// <summary>"pageview" | "funnel_step".</summary>
    public string Type { get; set; } = "pageview";

    /// <summary>Opaque, persistent per-browser id (localStorage). Drives new-vs-returning.</summary>
    public string VisitorId { get; set; } = null!;

    /// <summary>Per-tab/session id (sessionStorage). Drives live-visitor and funnel grouping.</summary>
    public string SessionId { get; set; } = null!;

    /// <summary>Path visited, e.g. "/booking".</summary>
    public string? Path { get; set; }

    /// <summary>Raw document.referrer as sent by the browser (may be empty).</summary>
    public string? Referrer { get; set; }

    /// <summary>Normalised acquisition channel: google, tiktok, instagram, facebook, direct, other.</summary>
    public string? ReferrerSource { get; set; }

    /// <summary>ISO country name resolved from <see cref="IpAddress"/> at collection time.</summary>
    public string? Country { get; set; }

    /// <summary>Two-letter country code (e.g. "VN"), when available.</summary>
    public string? CountryCode { get; set; }

    /// <summary>Raw client IP (X-Forwarded-For first hop). Retained per operator choice.</summary>
    public string? IpAddress { get; set; }

    /// <summary>Raw User-Agent string.</summary>
    public string? UserAgent { get; set; }

    /// <summary>True when this VisitorId had no prior events at capture time.</summary>
    public bool IsNewVisitor { get; set; }

    /// <summary>
    /// Booking-funnel milestone for Type == "funnel_step". Ordered enum below.
    /// Null for pageviews.
    /// </summary>
    [BsonRepresentation(BsonType.String)]
    public BookingFunnelStep? FunnelStep { get; set; }

    /// <summary>When the event occurred (client-reported, server-stamped fallback = CreatedAt).</summary>
    public DateTime OccurredAt { get; set; } = DateTime.UtcNow;
}

/// <summary>
/// Ordered stages of the public booking flow. The ordinal order is what the
/// dashboard uses to compute step-to-step drop-off, so only ever append.
/// </summary>
public enum BookingFunnelStep
{
    ScheduleViewed = 0,   // landed on /booking, schedule rendered
    DateSelected = 1,     // picked a day
    SessionSelected = 2,  // opened a class / tapped Book
    CheckoutStarted = 3,  // navigated to /checkout
    PaymentShown = 4,     // payment options / Stripe element shown
    PurchaseCompleted = 5 // booking confirmed
}

