{
    public string Type { get; set; } = "pageview";   // "pageview" | "funnel_step"
    public string VisitorId { get; set; } = null!;
    public string SessionId { get; set; } = null!;
    public string? Path { get; set; }
    public string? Referrer { get; set; }
    public string? FunnelStep { get; set; }           // enum name for funnel_step events
    public long? OccurredAtMs { get; set; }           // client epoch millis (optional)
}

/// <summary>Roll-up powering the Visitors tab headline stats + breakdowns.</summary>
public class VisitorSummaryDto
{
    public int TotalVisitors { get; set; }        // distinct VisitorId in range
    public int NewVisitors { get; set; }          // first-seen within range
    public int ReturningVisitors { get; set; }    // seen before AND in range
    public int TotalPageviews { get; set; }
    public List<VisitorBreakdownRow> Countries { get; set; } = new();
    public List<VisitorBreakdownRow> Referrers { get; set; } = new();
}

