using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Net.Http.Json;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using SoulPilates.Core.Interfaces;

namespace SoulPilates.Services;

/// <summary>
/// IP → country resolver backed by the free ip-api.com endpoint, with an
/// in-process cache keyed by IP so we make at most one lookup per distinct
/// address (ip-api allows ~45 req/min unauthenticated — the cache keeps us
/// comfortably under it even under load).
///
/// <para>Registered as a singleton so the cache is shared across requests.
/// Failures are swallowed and return an empty result: geo is a nice-to-have,
/// never a reason to drop a tracking beacon.</para>
/// </summary>
public class GeoIpResolver : IGeoIpResolver
{
    private readonly IHttpClientFactory _httpFactory;
    private readonly ILogger<GeoIpResolver> _logger;
    private readonly ConcurrentDictionary<string, GeoResult> _cache = new();

    public GeoIpResolver(IHttpClientFactory httpFactory, ILogger<GeoIpResolver> logger)
    {
        _httpFactory = httpFactory;
        _logger = logger;
    }

    public async Task<GeoResult> ResolveAsync(string? ip, CancellationToken ct = default)
    {
        if (string.IsNullOrWhiteSpace(ip)) return default;

        // Private / loopback ranges never resolve — short-circuit and cache.
