using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using SoulPilates.Core.Interfaces;

namespace SoulPilates.Services;

/// <summary>
/// IP → country resolver backed by the free ip-api.com endpoint, with an
/// in-process cache keyed by IP so we make at most one lookup per distinct
/// address (ip-api allows ~45 req/min unauthenticated — the cache keeps us
/// comfortably under it even under load).
