                $"http://ip-api.com/json/{ip}?fields=status,country,countryCode", ct);

            var result = (resp != null && resp.status == "success")
                ? new GeoResult(resp.country, resp.countryCode)
                : default;

            _cache[ip] = result;
            return result;
