using System;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using SoulPilates.Core.DTOs;
using SoulPilates.Core.Interfaces;

namespace SoulPilates.API.Controllers;

/// <summary>
/// First-party web-analytics surface.
///   • POST /api/track            — anonymous beacon from the public site.
///   • GET  /api/track/visitors/* — Admin-gated dashboard aggregations.
/// The write path is deliberately permissive and fire-and-forget; the read
/// paths are locked down like the rest of the analytics dashboard.
/// </summary>
[ApiController]
