<!-- ── First-party visitor + booking-funnel tracker ── -->
<script is:inline>
  // Self-hosted analytics beacon. Independent of GA4 so it works even when
  // no Measurement ID is configured. Sends pageviews + booking-funnel steps
  // to /api/track, which resolves country/referrer/new-vs-returning server-side.
  (function initSPTracker() {
    var metaApi = document.querySelector('meta[name="api-url"]');
    var API_URL = metaApi ? metaApi.content : '';

    // Persistent per-browser id (new/returning) + per-tab session id (live/funnel).
    function uid() {
      try {
        return (crypto.randomUUID && crypto.randomUUID()) ||
          (Date.now().toString(36) + Math.random().toString(36).slice(2));
      } catch (e) {
        return Date.now().toString(36) + Math.random().toString(36).slice(2);
      }
    }
    var visitorId, sessionId;
    try {
      visitorId = localStorage.getItem('sp_vid');
      if (!visitorId) { visitorId = uid(); localStorage.setItem('sp_vid', visitorId); }
    } catch (e) { visitorId = uid(); }
    try {
      sessionId = sessionStorage.getItem('sp_sid');
      if (!sessionId) { sessionId = uid(); sessionStorage.setItem('sp_sid', sessionId); }
    } catch (e) { sessionId = uid(); }

    function beacon(body) {
      if (!API_URL) return;
      try {
        fetch(API_URL + '/api/track', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(body),
          keepalive: true,   // survives page unload, like sendBeacon
          credentials: 'omit',
        }).catch(function () {});
      } catch (e) { /* analytics must never throw into the page */ }
    }

    // Pageview on load.
    beacon({
      type: 'pageview',
      visitorId: visitorId,
      sessionId: sessionId,
      path: location.pathname,
      referrer: document.referrer || '',
      occurredAtMs: Date.now(),
    });

    // Funnel-step helper for booking/checkout pages. Dedupes per session so
    // re-firing the same step (e.g. re-render) doesn't inflate the counts.
    var firedSteps = {};
    window.spTrackFunnel = function (stepName) {
      if (!stepName || firedSteps[stepName]) return;
      firedSteps[stepName] = true;
      beacon({
        type: 'funnel_step',
        visitorId: visitorId,
        sessionId: sessionId,
        path: location.pathname,
        referrer: document.referrer || '',
        funnelStep: stepName,
        occurredAtMs: Date.now(),
      });
    };
  })();
</script>

