const authHeaders = { Authorization: "Bearer " + token };

async function loadVisitorSummary() {
  const { start, end } = rangeFromState();
  const sub = document.getElementById("visitorsSubtitle");
  if (sub) sub.textContent = periodLabel() + " · loading…";
  try {
    const res = await fetch(
      `${API}/api/track/visitors/summary?start=${start}&end=${end}`,
      { headers: authHeaders },
    );
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const d = await res.json();

    const setTxt = (id, v) => {
      const el = document.getElementById(id);
      if (el) el.textContent = v;
    };
    setTxt("kpi-totalVisitors", (d.totalVisitors ?? 0).toLocaleString("en-US"));
    setTxt("kpi-totalPageviews", `${(d.totalPageviews ?? 0).toLocaleString("en-US")} pageviews`);
    setTxt("kpi-newVisitors", (d.newVisitors ?? 0).toLocaleString("en-US"));
    setTxt("kpi-returningVisitors", (d.returningVisitors ?? 0).toLocaleString("en-US"));
    const tv = d.totalVisitors || 0;
    setTxt("kpi-newVisitorsPct", tv ? `${Math.round((100 * (d.newVisitors || 0)) / tv)}% of total` : " ");
    setTxt("kpi-returningVisitorsPct", tv ? `${Math.round((100 * (d.returningVisitors || 0)) / tv)}% of total` : " ");
    if (sub) sub.textContent = `${periodLabel()} · ${tv.toLocaleString("en-US")} unique visitors`;

    renderBreakdown("visitorCountryTable", d.countries, "No visitor data yet");
    renderBreakdown("visitorReferrerTable", d.referrers, "No referrer data yet");
  } catch (e) {
    if (sub) sub.textContent = "Failed to load visitor data";
    renderBreakdown("visitorCountryTable", [], "Failed to load");
    renderBreakdown("visitorReferrerTable", [], "Failed to load");
  }
}

function renderBreakdown(tbodyId, rows, emptyMsg) {
  const tbody = document.getElementById(tbodyId);
  if (!tbody) return;
  if (!rows || !rows.length) {
    tbody.innerHTML = `<tr><td colspan="3" class="muted">${emptyMsg}</td></tr>`;
    return;
  }
  tbody.innerHTML = rows
    .map((r) => {
      const label = String(r.label ?? "")
        .replace(/[&<>"]/g, (m) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[m]));
      const pretty = label.charAt(0).toUpperCase() + label.slice(1);
      return `<tr><td>${pretty}</td><td class="num">${(r.visitors ?? 0).toLocaleString("en-US")}</td><td class="num">${r.percentage ?? 0}%</td></tr>`;
    })
    .join("");
}

async function loadVisitorFunnel() {
  const { start, end } = rangeFromState();
  const wrap = document.getElementById("visitorFunnel");
  if (!wrap) return;
  try {
    const res = await fetch(
      `${API}/api/track/visitors/funnel?start=${start}&end=${end}`,
      { headers: authHeaders },
    );
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const rows = await res.json();
    if (!rows || !rows.length || (rows[0] && rows[0].sessions === 0)) {
      wrap.innerHTML = `<div class="muted" style="padding:16px;">No booking-funnel activity in this period yet.</div>`;
      return;
    }
    wrap.innerHTML = rows
      .map((r) => {
        const conv = r.conversionFromStart ?? 0;
        const dropTxt =
          r.order === 0
            ? `<span class="drop none">entry point</span>`
            : `<span class="drop">−${r.dropoffFromPrevious ?? 0}% drop</span>`;
        return `
          <div class="sp-funnel-row">
            <div class="sp-funnel-label">${r.step}</div>
            <div class="sp-funnel-bar-wrap">
              <div class="sp-funnel-bar" style="width:${Math.max(conv, 2)}%">${(r.sessions ?? 0).toLocaleString("en-US")}</div>
            </div>
            <div class="sp-funnel-meta"><div class="conv">${conv}%</div>${dropTxt}</div>
          </div>`;
      })
      .join("");
  } catch (e) {
    wrap.innerHTML = `<div class="muted" style="padding:16px;">Failed to load funnel data.</div>`;
  }
}

