  async function completeOnboarding() {
    const dob = document.getElementById("dobInput")?.value || null;
    const medical =
      document.getElementById("medicalInput")?.value.trim() || null;
    const referralEl = document.querySelector(
      'input[name="referral"]:checked',
    );
    const referral = referralEl ? referralEl.value : null;

    const finishBtn = document.getElementById("finishBtn");
    if (finishBtn) finishBtn.disabled = true;

    try {
      await fetch(API + "/api/customer/onboarding", {
        method: "POST",
        headers: {
          Authorization: "Bearer " + token,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          dateOfBirth: dob ? new Date(dob).toISOString() : null,
          medicalHistory: medical,
          referralSource: referral,
        }),
      });
    } catch (e) {
      console.error("Onboarding submit failed", e);
    }
    // GA4: onboarding completed
    if (typeof window.spTrackEvent === 'function') {
      window.spTrackEvent('onboarding_complete', {
        referral: referral || 'skipped',
        filled_dob: !!dob,
        filled_medical: !!medical,
        page: 'onboarding',
      });
    }
    showStep(5);
  }
</script>

