public async Task<bool> CompleteOnboardingAsync(string accountId, DateTime? dateOfBirth, string? medicalHistory, string? referralSource)
{
    var update = Builders<CustomerAccount>.Update
        .Set(a => a.DateOfBirth, dateOfBirth)
        .Set(a => a.MedicalHistory, medicalHistory)
        .Set(a => a.ReferralSource, referralSource)
        .Set(a => a.OnboardingCompleted, true)
        .Set(a => a.UpdatedAt, DateTime.UtcNow);

    var result = await _accounts.UpdateOneAsync(a => a.Id == accountId, update);

    // Mirror DOB to linked CRM Client
    var account = await _accounts.Find(a => a.Id == accountId).FirstOrDefaultAsync();
    if (account?.ClientId != null && dateOfBirth.HasValue)
    {
        await _clients.UpdateOneAsync(c => c.Id == account.ClientId,
            Builders<Client>.Update.Set(c => c.DateOfBirth, dateOfBirth));
    }
    return result.ModifiedCount > 0;
}

