using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using MongoDB.Bson;
using MongoDB.Driver;
using SoulPilates.Core.DTOs;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Interfaces;
using SoulPilates.Infrastructure.Data;

namespace SoulPilates.Services;

/// <summary>
/// First-party web-analytics store + aggregations. See
/// <see cref="IVisitorAnalyticsService"/>. Writes come only from the public
/// tracking beacon; reads power the admin Visitors dashboard.
/// </summary>
public class VisitorAnalyticsService : IVisitorAnalyticsService
{
    private readonly IMongoCollection<VisitorEvent> _events;
    private readonly IGeoIpResolver _geo;

    public VisitorAnalyticsService(MongoDbContext dbContext, IGeoIpResolver geo)
    {
        _events = dbContext.GetCollection<VisitorEvent>("VisitorEvents");
        _geo = geo;
    }

    public async Task TrackAsync(TrackEventRequest req, string? ipAddress, string? userAgent, CancellationToken ct = default)
    {
        if (string.IsNullOrWhiteSpace(req.VisitorId) || string.IsNullOrWhiteSpace(req.SessionId))
            return; // malformed beacon — ignore silently

        // New vs returning: has this VisitorId ever been seen before now?
        var seenBefore = await _events
            .Find(e => e.VisitorId == req.VisitorId)
            .Limit(1)
            .AnyAsync(ct);

        var geo = await _geo.ResolveAsync(ipAddress, ct);

        BookingFunnelStep? step = null;
        if (req.Type == "funnel_step" &&
            Enum.TryParse<BookingFunnelStep>(req.FunnelStep, ignoreCase: true, out var parsed))
        {
            step = parsed;
        }

        var occurredAt = req.OccurredAtMs.HasValue
            ? DateTimeOffset.FromUnixTimeMilliseconds(req.OccurredAtMs.Value).UtcDateTime
            : DateTime.UtcNow;

        var evt = new VisitorEvent
        {
            Type = req.Type == "funnel_step" ? "funnel_step" : "pageview",
            VisitorId = req.VisitorId,
            SessionId = req.SessionId,
            Path = Trim(req.Path, 300),
            Referrer = Trim(req.Referrer, 500),
            ReferrerSource = ClassifyReferrer(req.Referrer, req.Path),
            Country = geo.Country,
            CountryCode = geo.CountryCode,
            IpAddress = ipAddress,
            UserAgent = Trim(userAgent, 500),
            IsNewVisitor = !seenBefore,
            FunnelStep = step,
            OccurredAt = occurredAt,
        };

        await _events.InsertOneAsync(evt, cancellationToken: ct);
    }

    public async Task<int> GetLiveVisitorCountAsync(int windowMinutes = 5, CancellationToken ct = default)
    {
        var since = DateTime.UtcNow.AddMinutes(-Math.Abs(windowMinutes));
        var recent = await _events
            .Distinct<string>("SessionId",
                Builders<VisitorEvent>.Filter.Gte(e => e.OccurredAt, since), cancellationToken: ct)
            .ToListAsync(ct);
        return recent.Count;
    }

    public async Task<VisitorSummaryDto> GetVisitorSummaryAsync(DateTime startUtc, DateTime endUtc, CancellationToken ct = default)
    {
        var inRange = Builders<VisitorEvent>.Filter.And(
            Builders<VisitorEvent>.Filter.Gte(e => e.OccurredAt, startUtc),
            Builders<VisitorEvent>.Filter.Lt(e => e.OccurredAt, endUtc),
            Builders<VisitorEvent>.Filter.Eq(e => e.Type, "pageview"));

        var events = await _events.Find(inRange).ToListAsync(ct);

        var byVisitor = events
            .GroupBy(e => e.VisitorId)
            .ToList();

        var total = byVisitor.Count;
        // A visitor counts as "new" when their first-ever pageview in range was
        // flagged new at capture time (no earlier events existed).
        var newCount = byVisitor.Count(g => g.Any(e => e.IsNewVisitor));
        var returning = total - newCount;

        var countries = BuildBreakdown(
            events.Select(e => (Label: string.IsNullOrWhiteSpace(e.Country) ? "Unknown" : e.Country!, e.VisitorId)),
            total);
        var referrers = BuildBreakdown(
            events.Select(e => (Label: string.IsNullOrWhiteSpace(e.ReferrerSource) ? "direct" : e.ReferrerSource!, e.VisitorId)),
            total);

        return new VisitorSummaryDto
        {
            TotalVisitors = total,
            NewVisitors = newCount,
            ReturningVisitors = returning,
            TotalPageviews = events.Count,
            Countries = countries,
            Referrers = referrers,
        };
    }

    public async Task<List<FunnelStepRow>> GetBookingFunnelAsync(DateTime startUtc, DateTime endUtc, CancellationToken ct = default)
    {
        var filter = Builders<VisitorEvent>.Filter.And(
            Builders<VisitorEvent>.Filter.Gte(e => e.OccurredAt, startUtc),
            Builders<VisitorEvent>.Filter.Lt(e => e.OccurredAt, endUtc),
            Builders<VisitorEvent>.Filter.Eq(e => e.Type, "funnel_step"));

        var events = await _events.Find(filter).ToListAsync(ct);

        // Distinct sessions that reached each step.
        var perStep = new Dictionary<BookingFunnelStep, HashSet<string>>();
        foreach (BookingFunnelStep s in Enum.GetValues(typeof(BookingFunnelStep)))
            perStep[s] = new HashSet<string>();

        foreach (var e in events)
        {
            if (e.FunnelStep is { } s && !string.IsNullOrWhiteSpace(e.SessionId))
                perStep[s].Add(e.SessionId);
        }

        var ordered = Enum.GetValues(typeof(BookingFunnelStep)).Cast<BookingFunnelStep>()
            .OrderBy(s => (int)s).ToList();

        var startCount = perStep[ordered[0]].Count;
        var rows = new List<FunnelStepRow>();
        int? prevCount = null;

        foreach (var s in ordered)
        {
            var count = perStep[s].Count;
            rows.Add(new FunnelStepRow
            {
                Step = ToLabel(s),
                Order = (int)s,
                Sessions = count,
                ConversionFromStart = startCount > 0 ? Math.Round(100.0 * count / startCount, 1) : 0,
                DropoffFromPrevious = (prevCount is > 0)
                    ? Math.Round(100.0 * (prevCount.Value - count) / prevCount.Value, 1)
                    : 0,
            });
            prevCount = count;
        }

        return rows;
    }

    // ── helpers ──────────────────────────────────────────────────────────

    private static List<VisitorBreakdownRow> BuildBreakdown(
        IEnumerable<(string Label, string VisitorId)> rows, int totalVisitors)
    {
        return rows
            .GroupBy(r => r.Label)
            .Select(g => new VisitorBreakdownRow
            {
                Label = g.Key,
                Visitors = g.Select(x => x.VisitorId).Distinct().Count(),
            })
            .OrderByDescending(r => r.Visitors)
            .Select(r =>
            {
                r.Percentage = totalVisitors > 0 ? Math.Round(100.0 * r.Visitors / totalVisitors, 1) : 0;
                return r;
            })
            .ToList();
    }

    /// <summary>
    /// Maps a referrer URL to a coarse acquisition channel. Order matters:
    /// social/search hosts are checked before falling back to "direct" (empty
    /// referrer) or "other" (a referrer we don't recognise).
    /// </summary>
    private static string ClassifyReferrer(string? referrer, string? path)
    {
        if (string.IsNullOrWhiteSpace(referrer)) return "direct";

        string host;
        try { host = new Uri(referrer).Host.ToLowerInvariant(); }
        catch { return "other"; }

        // Same-site referrers (internal navigation) don't represent acquisition.
        if (host.Contains("soulpilates")) return "internal";

        if (host.Contains("google.")) return "google";
        if (host.Contains("bing.")) return "bing";
        if (host.Contains("tiktok.")) return "tiktok";
        if (host.Contains("instagram.")) return "instagram";
        if (host is "l.facebook.com" or "lm.facebook.com" || host.Contains("facebook.") || host == "fb.me") return "facebook";
        if (host.Contains("youtube.") || host == "youtu.be") return "youtube";
        if (host.Contains("t.co") || host.Contains("twitter.") || host == "x.com") return "twitter";
        if (host.Contains("zalo.")) return "zalo";
        if (host.Contains("linkedin.")) return "linkedin";

        return "other";
    }

    private static string ToLabel(BookingFunnelStep s) => s switch
    {
        BookingFunnelStep.ScheduleViewed => "Schedule viewed",
        BookingFunnelStep.DateSelected => "Date selected",
        BookingFunnelStep.SessionSelected => "Class selected",
        BookingFunnelStep.CheckoutStarted => "Checkout started",
        BookingFunnelStep.PaymentShown => "Payment shown",
        BookingFunnelStep.PurchaseCompleted => "Purchase completed",
        _ => s.ToString(),
    };

    private static string? Trim(string? s, int max) =>
        string.IsNullOrEmpty(s) ? s : (s.Length <= max ? s : s.Substring(0, max));
}

