using System.Security.Claims;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using MongoDB.Driver;
using SoulPilates.Core.Entities;
using SoulPilates.Infrastructure.Data;

namespace SoulPilates.API.Controllers;

/// <summary>
/// Profile management for the currently-authenticated user.
/// Accessible from the topbar avatar profile modal on any admin page.
/// </summary>
[ApiController]
[Route("api/me")]
[Authorize]
public class MeController : ControllerBase
{
    private readonly MongoDbContext _db;

    public MeController(MongoDbContext db) => _db = db;

    // ── GET /api/me ────────────────────────────────────────────────
    /// <summary>Returns the current user's profile info.</summary>
    [HttpGet]
    public async Task<IActionResult> GetProfile()
    {
        var userId = CurrentUserId();
        if (userId is null) return Unauthorized();

        var users = _db.GetCollection<User>("Users");
        var user = await users.Find(u => u.Id == userId).FirstOrDefaultAsync();
        if (user is null) return NotFound();

        // Resolve photo from linked Staff record (if any)
        string? photoUrl = null;
        var effectiveRole = string.IsNullOrWhiteSpace(user.Role) ? "Instructor" : user.Role;
        var staff = await ResolveLinkedStaffAsync(user);
        if (staff is not null)
        {
            photoUrl = staff.PhotoUrl;
            effectiveRole = MapStaffRoleToUserRole(staff.Role) ?? effectiveRole;
        }

        return Ok(new
        {
            id      = user.Id,
            name    = user.Name,
            email   = user.Email,
            role    = effectiveRole,
            staffId = user.StaffId,
            photoUrl,
        });
    }

    // ── PUT /api/me/name ───────────────────────────────────────────
    /// <summary>Update the current user's display name.</summary>
    [HttpPut("name")]
    public async Task<IActionResult> UpdateName([FromBody] UpdateNameRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.Name))
            return BadRequest(new { error = "Name is required." });

        var userId = CurrentUserId();
        if (userId is null) return Unauthorized();

        var users = _db.GetCollection<User>("Users");
        var result = await users.UpdateOneAsync(
            u => u.Id == userId,
            Builders<User>.Update.Set(u => u.Name, request.Name.Trim()));

        if (result.MatchedCount == 0) return NotFound();
        return NoContent();
    }

    // ── PUT /api/me/password ───────────────────────────────────────
    /// <summary>Change the current user's password (requires current password).</summary>
    [HttpPut("password")]
    public async Task<IActionResult> ChangePassword([FromBody] ChangePasswordRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.CurrentPassword))
            return BadRequest(new { error = "Current password is required." });
        if (string.IsNullOrWhiteSpace(request.NewPassword) || request.NewPassword.Length < 8)
            return BadRequest(new { error = "New password must be at least 8 characters." });

        var userId = CurrentUserId();
        if (userId is null) return Unauthorized();

        var users = _db.GetCollection<User>("Users");
        var user = await users.Find(u => u.Id == userId).FirstOrDefaultAsync();
        if (user is null) return NotFound();

        // Verify current password
        if (!Services.PasswordHasher.Verify(request.CurrentPassword, user.PasswordHash))
            return BadRequest(new { error = "Current password is incorrect." });

        // Hash new password and persist
        var newHash = Services.PasswordHasher.Hash(request.NewPassword);
        await users.UpdateOneAsync(
            u => u.Id == userId,
            Builders<User>.Update.Set(u => u.PasswordHash, newHash));

        return NoContent();
    }

    // ── Helpers ─────────────────────────────────────────────────────

    private string? CurrentUserId()
    {
        var sub = User.FindFirst(ClaimTypes.NameIdentifier)?.Value
                  ?? User.FindFirst("sub")?.Value;
        return string.IsNullOrWhiteSpace(sub) ? null : sub;
    }

    private async Task<Staff?> ResolveLinkedStaffAsync(User user)
    {
        var staffCollection = _db.GetCollection<Staff>("Staff");
        Staff? staff = null;

        if (!string.IsNullOrWhiteSpace(user.StaffId))
        {
            staff = await staffCollection.Find(s => s.Id == user.StaffId).FirstOrDefaultAsync();
        }

        if (staff != null) return staff;

        var filters = new List<FilterDefinition<Staff>>();
        if (!string.IsNullOrWhiteSpace(user.Id))
            filters.Add(Builders<Staff>.Filter.Eq(s => s.UserId, user.Id));
        if (!string.IsNullOrWhiteSpace(user.Email))
            filters.Add(Builders<Staff>.Filter.Eq(s => s.Email, user.Email));
        if (filters.Count == 0) return null;

        staff = await staffCollection.Find(Builders<Staff>.Filter.Or(filters)).FirstOrDefaultAsync();
        if (staff == null || string.IsNullOrWhiteSpace(staff.Id)) return null;

        var mappedRole = MapStaffRoleToUserRole(staff.Role) ?? user.Role ?? "Instructor";
        await _db.GetCollection<User>("Users").UpdateOneAsync(
            u => u.Id == user.Id,
            Builders<User>.Update
                .Set(u => u.StaffId, staff.Id)
                .Set(u => u.Role, mappedRole));

        if (string.IsNullOrWhiteSpace(staff.UserId) && !string.IsNullOrWhiteSpace(user.Id))
        {
            await staffCollection.UpdateOneAsync(
                s => s.Id == staff.Id,
                Builders<Staff>.Update.Set(s => s.UserId, user.Id));
            staff.UserId = user.Id;
        }

        user.StaffId = staff.Id;
        user.Role = mappedRole;
        return staff;
    }

    private static string? MapStaffRoleToUserRole(string? staffRole)
    {
        return (staffRole ?? string.Empty).Trim().ToUpperInvariant() switch
        {
            "RECEPTIONIST" => "Receptionist",
            "INSTRUCTOR" => "Instructor",
            "MANAGER" => "Manager",
            "OWNER" => "Owner",
            "ACCOUNTANT" => "Accountant",
            "SUPERADMIN" => "SuperAdmin",
            "FREELANCE" => "Freelance",
            _ => null,
        };
    }
}

// ── DTOs ──────────────────────────────────────────────────────────────

public class UpdateNameRequest
{
    public string Name { get; set; } = null!;
}

public class ChangePasswordRequest
{
    public string CurrentPassword { get; set; } = null!;
    public string NewPassword { get; set; } = null!;
}

