/// </summary>
[HttpGet("dashboard")]
public async Task<IActionResult> GetDashboard()
{
    var userId = CurrentUserId();
    if (userId is null) return Unauthorized();

    var users = _db.GetCollection<User>("Users");
    var user = await users.Find(u => u.Id == userId).FirstOrDefaultAsync();
    if (user is null) return NotFound();

    var role = string.IsNullOrWhiteSpace(user.Role) ? "Instructor" : user.Role;
    var staff = await ResolveLinkedStaffAsync(user);
    if (staff is not null) role = MapStaffRoleToUserRole(staff.Role) ?? role;

    var catalog = Core.Dashboard.DashboardWidgetCatalog.ForRole(role)
        .Select(w => new
        {
            id = w.Id,
            title = w.Title,
            category = w.Category,
            description = w.Description,
            defaultW = w.DefaultW,
            defaultH = w.DefaultH,
            minW = w.MinW,
            minH = w.MinH,
        }).ToList();

    var layouts = _db.GetCollection<DashboardLayout>("DashboardLayouts");
    var saved = await layouts.Find(l => l.UserId == userId).FirstOrDefaultAsync();

    object widgets;
    if (saved is not null && saved.Widgets.Count > 0)
    {
        // Defence-in-depth: drop any placement the role is no longer allowed.
        widgets = saved.Widgets
            .Where(p => Core.Dashboard.DashboardWidgetCatalog.IsAllowed(p.WidgetId, role))
            .Select(p => new { widgetId = p.WidgetId, x = p.X, y = p.Y, w = p.W, h = p.H })
            .ToList();
    }
    else
    {
        widgets = Core.Dashboard.DashboardWidgetCatalog.DefaultLayoutFor(role)
            .Select(t => new { widgetId = t.WidgetId, x = t.X, y = t.Y, w = t.W, h = t.H })
            .ToList();
    }

    return Ok(new { role, catalog, widgets });
}

// ── PUT /api/me/dashboard ──────────────────────────────────────
/// <summary>Persist the caller's dashboard layout (role-filtered server-side).</summary>
[HttpPut("dashboard")]
public async Task<IActionResult> SaveDashboard([FromBody] SaveDashboardRequest request)
{
    var userId = CurrentUserId();
    if (userId is null) return Unauthorized();

    var users = _db.GetCollection<User>("Users");
    var user = await users.Find(u => u.Id == userId).FirstOrDefaultAsync();
    if (user is null) return NotFound();

    var role = string.IsNullOrWhiteSpace(user.Role) ? "Instructor" : user.Role;
    var staff = await ResolveLinkedStaffAsync(user);
    if (staff is not null) role = MapStaffRoleToUserRole(staff.Role) ?? role;

    // Only persist widgets the role is allowed to see — a tampered payload
    // can never grant access to a restricted metric.
    var placements = (request.Widgets ?? new())
        .Where(p => !string.IsNullOrWhiteSpace(p.WidgetId)
                    && Core.Dashboard.DashboardWidgetCatalog.IsAllowed(p.WidgetId, role))
        .Select(p => new DashboardWidgetPlacement
        {
            WidgetId = p.WidgetId,
            X = p.X, Y = p.Y,
            W = System.Math.Max(1, p.W),
            H = System.Math.Max(1, p.H),
        })
        .ToList();

    var layouts = _db.GetCollection<DashboardLayout>("DashboardLayouts");
    await layouts.UpdateOneAsync(
        l => l.UserId == userId,
        Builders<DashboardLayout>.Update
            .Set(l => l.Widgets, placements)
            .Set(l => l.UpdatedAt, System.DateTime.UtcNow)
            .SetOnInsert(l => l.UserId, userId)
            .SetOnInsert(l => l.CreatedAt, System.DateTime.UtcNow),
        new UpdateOptions { IsUpsert = true });

    return NoContent();
}

// ── Helpers ─────────────────────────────────────────────────────

private string? CurrentUserId()

