// Role visibility
const dashboardRole = (() => {
  try {
    const payload = JSON.parse(atob(token.split('.')[1]));
    return String(
      payload['http://schemas.microsoft.com/ws/2008/06/identity/claims/role'] ||
      payload.role || 'admin'
    ).toLowerCase();
  } catch { return 'admin'; }
})();
document.querySelectorAll('[data-dash-role]').forEach((el) => {
  const allowed = el.getAttribute('data-dash-role').toLowerCase().split(',');
  if (!allowed.includes(dashboardRole)) el.style.display = 'none';
});

const fmtVnd  = (n) => `${Math.round(Number(n) || 0).toLocaleString('en-US')} VND`;
const fmtInt  = (n) => `${Math.round(Number(n) || 0).toLocaleString('en-US')}`;
const fmtPct  = (n) => `${Math.round((Number(n) || 0) * 100)}%`;
const fmtM    = (n) => {
  const v = Math.round(Number(n) || 0);
  if (Math.abs(v) >= 1e9) return `${(v/1e9).toFixed(1)}B`;
  if (Math.abs(v) >= 1e6) return `${(v/1e6).toFixed(0)}M`;
  return v.toLocaleString('en-US');
};

function escapeHtml(v) {
  return String(v || '').replace(/[<>&"']/g, c =>
    ({ '<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&#39;' }[c]));
}

function css(name) {
  return getComputedStyle(document.documentElement).getPropertyValue(name).trim();
}

function currentMonthRange() {
  const now = new Date();
  const start = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-01`;
  const next  = new Date(now.getFullYear(), now.getMonth()+1, 1);
  const end   = `${next.getFullYear()}-${String(next.getMonth()+1).padStart(2,'0')}-01`;
  return { start, end };
}

let revenueChartInstance  = null;
let breakdownChartInstance = null;
let latestMonthSummary    = null;
let latestBreakdown       = null;

// ── KPIs ──────────────────────────────────────────────────────────────────
async function loadDashboardKpis() {
  try {
    const res = await fetch(`${API}/api/analytics/dashboard-kpis`, {
      headers: { Authorization: `Bearer ${token}` },
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const dto = await res.json();

    setText('kpi-revenue', fmtVnd(dto.monthlyRevenueVnd ?? 0));

    const deltaEl = document.getElementById('kpi-revenue-delta');
    if (deltaEl) {
      const delta = dto.monthlyRevenueDeltaPct;
      if (delta == null) {
        deltaEl.textContent = 'No prior month comparison yet';
        deltaEl.className = 'db-delta flat';
      } else if (Math.abs(delta) > 999) {
        // Suppress extreme deltas on new/sparse data — a 3000%+ swing is
        // meaningless when prior month has a single test payment.
        deltaEl.textContent = 'New month baseline';
        deltaEl.className = 'db-delta flat';
      } else if (delta >= 0) {
        deltaEl.textContent = `▲ ${delta.toFixed(1)}% vs last month`;
        deltaEl.className = 'db-delta up';
      } else {
        deltaEl.textContent = `▼ ${Math.abs(delta).toFixed(1)}% vs last month`;
        deltaEl.className = 'db-delta down';
      }
    }

    setText('kpi-clients', fmtInt(dto.activeClients30d ?? 0));
    setText('kpi-classes', fmtInt(dto.classesThisWeek ?? 0));
    setText('kpi-payroll', fmtVnd(dto.payrollEstimateVnd ?? 0));

    const pSubEl = document.getElementById('kpi-payroll-sub-label');
    if (pSubEl && dto.payrollEstimatePeriodLabel) {
      pSubEl.textContent = dto.payrollEstimatePeriodLabel;
    }
  } catch (e) {
    console.warn('KPI load failed:', e);
  }
}

// ── Month summary ─────────────────────────────────────────────────────────
async function loadMonthSummary() {
  const { start, end } = currentMonthRange();
  try {
    const res = await fetch(`${API}/api/analytics/month-summary?startDate=${start}&endDate=${end}`, {
      headers: { Authorization: `Bearer ${token}` },
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    latestMonthSummary = await res.json();

    setText('pulse-totalRevenue',  fmtVnd(latestMonthSummary.totalRevenueVnd ?? 0));
    setText('pulse-classRevenue',  fmtVnd(latestMonthSummary.singleClassRevenueVnd ?? 0));
    setText('pulse-packageRevenue',fmtVnd(latestMonthSummary.packageRevenueVnd ?? 0));
    setText('pulse-occupancy',     fmtPct(latestMonthSummary.averageOccupancyPct ?? 0));
    setText('pulse-packagesSold',  fmtInt(latestMonthSummary.packagesSoldCount ?? 0));
    setText('pulse-newClients',    fmtInt(latestMonthSummary.newClientsCount ?? 0));
    setText('pulse-dailyRevenue',  fmtVnd(latestMonthSummary.dailyAverageRevenueVnd ?? 0));
    setText('pulse-creditsOwed',   fmtInt(latestMonthSummary.outstandingPackageCredits ?? 0));
    setText('pulse-projection',    fmtVnd(latestMonthSummary.monthlyProjectionVnd ?? 0));
    setText('pulse-totalClasses',  fmtInt(latestMonthSummary.totalClassesHeld ?? 0));
    setText('pulse-dailyClasses',  `${(Number(latestMonthSummary.dailyAverageClasses)||0).toFixed(1)} / day`);
    setText('pulse-merchRevenue',  fmtVnd(latestMonthSummary.merchandiseRevenueVnd ?? 0));

    // Update doughnut center
    const centerVal = document.getElementById('doughnut-center-val');
    if (centerVal) centerVal.textContent = fmtM(latestMonthSummary.totalRevenueVnd ?? 0);

    renderInsights();
  } catch (e) {
    console.warn('Month summary failed:', e);
  }
}

function setText(id, val) {
  const el = document.getElementById(id);
  if (el) el.textContent = val;
}

// ── Recent invoices ───────────────────────────────────────────────────────
async function loadRecentInvoices() {
  const tbody = document.getElementById('recent-invoices');
  try {
    const res = await fetch(`${API}/api/invoice/recent?limit=6`, {
      headers: { Authorization: `Bearer ${token}` },
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const invoices = await res.json();

    if (!invoices?.length) {
      tbody.innerHTML = `<tr><td colspan="5" class="db-table-empty">No invoices yet.</td></tr>`;
      return;
    }
    tbody.innerHTML = invoices.map((inv) => {
      const date = new Date(inv.issueDate).toLocaleDateString('en-US', { month:'short', day:'numeric', year:'numeric' });
      const cls  = inv.status === 'PAID' ? 'badge-success' : inv.status === 'PARTIAL' ? 'badge-warning' : 'badge-default';
      const lbl  = inv.status === 'PARTIAL' ? 'Partial' : (inv.status || 'Unknown');
      return `<tr>
        <td>${escapeHtml(inv.clientName)}</td>
        <td>${date}</td>
        <td>${escapeHtml(inv.itemsSummary)}</td>
        <td>${fmtVnd(inv.totalNet)}</td>
        <td><span class="badge ${cls}">${escapeHtml(lbl)}</span></td>
      </tr>`;
    }).join('');
  } catch (e) {
    console.warn('Invoices failed:', e);
    tbody.innerHTML = `<tr><td colspan="5" class="db-table-empty">Unable to load recent invoices.</td></tr>`;
  }
}

// ── Revenue chart (line + area) ───────────────────────────────────────────
async function loadRevenueChart() {
  const ctx = document.getElementById('revenueChart').getContext('2d');
  try {
    const year = new Date().getFullYear();
    const res = await fetch(`${API}/api/analytics/yearly-revenue-expense?year=${year}`, {
      headers: { Authorization: `Bearer ${token}` },
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const rows = await res.json();

    if (revenueChartInstance) revenueChartInstance.destroy();

    const copper = css('--color-brand-accent') || '#db7d3c';
    const blue   = '#4ea5d9';

    // Gradient fill for revenue
    const gradRev = ctx.createLinearGradient(0, 0, 0, 280);
    gradRev.addColorStop(0,   'rgba(219,125,60,0.30)');

