import AdminLayout from '../../layouts/AdminLayout.astro';
---

<AdminLayout title="Dashboard" activePage="dashboard">
  <!-- Gridstack (drag/resize dashboard grid) -->
  <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/gridstack@10.3.1/dist/gridstack.min.css" />

  <style is:global>
    .dash-toolbar {
      display: flex; align-items: center; justify-content: space-between;
      gap: 12px; flex-wrap: wrap; margin-bottom: 14px;
    }
    .dash-toolbar-title { font-size: 22px; font-weight: 700; color: var(--color-text-primary); letter-spacing: -0.3px; }
    .dash-toolbar-actions { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
    .dash-btn {
      display: inline-flex; align-items: center; gap: 6px;
      padding: 8px 14px; font-size: 13px; font-weight: 600; cursor: pointer;
      border: 1px solid var(--color-border); border-radius: 8px;
      background: var(--color-surface); color: var(--color-text-primary);
      font-family: 'Inter', sans-serif; transition: all 0.12s;
    }
    .dash-btn:hover { border-color: var(--color-brand-accent); color: var(--color-brand-accent); }
    .dash-btn.primary { background: var(--color-brand-accent); color: #fff; border-color: var(--color-brand-accent); }
    .dash-btn svg { width: 15px; height: 15px; }
    .dash-editing-hint {
      font-size: 12px; color: var(--color-brand-accent); font-weight: 600;
      display: none;
    }
    body.dash-edit .dash-editing-hint { display: inline; }

    /* Gridstack container + items */
    .grid-stack { background: transparent; }
    .grid-stack-item-content {
      background: var(--color-surface);
      border: 1px solid var(--color-border-subtle);
      border-radius: 14px;
      overflow: auto;
      display: flex; flex-direction: column;
      padding: 16px 18px;
    }
    body.dash-edit .grid-stack-item-content {
      border-style: dashed; border-color: var(--color-brand-accent);
      cursor: move;
    }
    .wg-remove {
      position: absolute; top: 6px; right: 6px; z-index: 5;
      width: 24px; height: 24px; border-radius: 50%;
      border: none; background: rgba(239,68,68,0.9); color: #fff;
      font-size: 14px; line-height: 1; cursor: pointer; display: none;
      align-items: center; justify-content: center;
    }
    body.dash-edit .wg-remove { display: flex; }

    /* Widget internals */
    .wg-eyebrow { font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: .5px; color: var(--color-text-muted); }
    .wg-title { font-size: 13px; font-weight: 700; color: var(--color-text-primary); margin-top: 2px; }
    .wg-big { font-size: 30px; font-weight: 800; letter-spacing: -1px; color: var(--color-text-primary); margin-top: 6px; line-height: 1.05; }
    .wg-sub { font-size: 11px; color: var(--color-text-muted); margin-top: 4px; }
    .wg-delta { font-size: 12px; font-weight: 600; margin-top: 6px; }
    .wg-delta.up { color: #16a34a; } .wg-delta.down { color: #ef4444; } .wg-delta.flat { color: var(--color-text-muted); }
    .wg-body { flex: 1; min-height: 0; margin-top: 10px; }
    .wg-canvas-wrap { position: relative; height: 100%; min-height: 120px; }
    .wg-table { width: 100%; border-collapse: collapse; font-size: 12px; }
    .wg-table th { text-align: left; font-size: 10px; text-transform: uppercase; letter-spacing: .4px; color: var(--color-text-muted); padding: 6px 6px; border-bottom: 1px solid var(--color-border-subtle); }
    .wg-table td { padding: 7px 6px; border-bottom: 1px solid var(--color-border-subtle); color: var(--color-text-secondary); }
    .wg-table td.num, .wg-table th.num { text-align: right; }
    .wg-muted { color: var(--color-text-muted); font-size: 12px; padding: 8px 0; }
    .wg-live-dot { width: 8px; height: 8px; border-radius: 50%; background: #ef4444; display: inline-block; margin-right: 6px; animation: wgpulse 1.6s infinite; }
    @keyframes wgpulse { 0%{box-shadow:0 0 0 0 rgba(239,68,68,.5)} 70%{box-shadow:0 0 0 7px rgba(239,68,68,0)} 100%{box-shadow:0 0 0 0 rgba(239,68,68,0)} }
    .wg-pulse-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
    .wg-pulse-cell { background: var(--color-surface-raised, rgba(255,255,255,.03)); border-radius: 8px; padding: 8px 10px; }
    .wg-pulse-cell .l { font-size: 10px; color: var(--color-text-muted); text-transform: uppercase; letter-spacing: .3px; }
    .wg-pulse-cell .v { font-size: 16px; font-weight: 700; color: var(--color-text-primary); margin-top: 2px; }
    .wg-funnel-row { display: grid; grid-template-columns: 1fr auto; gap: 8px; align-items: center; margin-bottom: 6px; }
    .wg-funnel-bar-wrap { height: 22px; border-radius: 5px; background: rgba(128,128,128,.12); overflow: hidden; }
    .wg-funnel-bar { height: 100%; background: linear-gradient(90deg,#2BB7A3,#35c9b4); display: flex; align-items: center; padding-left: 8px; color: #fff; font-size: 11px; font-weight: 700; }
    .wg-funnel-label { font-size: 11px; color: var(--color-text-secondary); }

    /* Customize popup */
    .dash-modal-overlay {
      position: fixed; inset: 0; background: rgba(0,0,0,.5); z-index: 2000;
      display: none; align-items: center; justify-content: center; padding: 20px;
    }
    .dash-modal-overlay.open { display: flex; }
    .dash-modal {
      background: var(--color-surface); border: 1px solid var(--color-border);
      border-radius: 14px; width: 100%; max-width: 520px; max-height: 80vh;
      display: flex; flex-direction: column; overflow: hidden;
    }
    .dash-modal-head { padding: 16px 20px; border-bottom: 1px solid var(--color-border-subtle); display: flex; align-items: center; justify-content: space-between; }
    .dash-modal-title { font-size: 16px; font-weight: 700; color: var(--color-text-primary); }
    .dash-modal-body { padding: 8px 20px 16px; overflow-y: auto; }
    .dash-cat { font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: .5px; color: var(--color-text-muted); margin: 16px 0 6px; }
    .dash-wg-toggle { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 10px 0; border-bottom: 1px solid var(--color-border-subtle); }
    .dash-wg-toggle .info { min-width: 0; }
    .dash-wg-toggle .nm { font-size: 13px; font-weight: 600; color: var(--color-text-primary); }
    .dash-wg-toggle .ds { font-size: 11px; color: var(--color-text-muted); margin-top: 1px; }
    .dash-switch { position: relative; width: 40px; height: 22px; flex-shrink: 0; }
    .dash-switch input { opacity: 0; width: 0; height: 0; }
    .dash-switch .track { position: absolute; inset: 0; background: var(--color-border); border-radius: 22px; transition: .15s; cursor: pointer; }
    .dash-switch .track::before { content: ''; position: absolute; width: 16px; height: 16px; left: 3px; top: 3px; background: #fff; border-radius: 50%; transition: .15s; }
    .dash-switch input:checked + .track { background: var(--color-brand-accent); }
