    .dash-modal-foot { padding: 14px 20px; border-top: 1px solid var(--color-border-subtle); display: flex; justify-content: flex-end; gap: 8px; }
    .dash-empty { text-align: center; padding: 60px 20px; color: var(--color-text-muted); }
  </style>

