        Customize
      </button>
      <button class="dash-btn" id="btnEdit">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 20h9"/><path d="M16.5 3.5a2.12 2.12 0 0 1 3 3L7 19l-4 1 1-4Z"/></svg>
        Edit layout
      </button>
      <button class="dash-btn primary" id="btnSave" style="display:none;">Save</button>
    </div>
  </div>

  <div class="grid-stack" id="dashGrid"></div>
  <div class="dash-empty" id="dashEmpty" style="display:none;">
    No widgets to show. Click <strong>Customize</strong> to add metrics to your dashboard.
  </div>

  <!-- Customize popup -->
  <div class="dash-modal-overlay" id="customizeModal">
    <div class="dash-modal">
      <div class="dash-modal-head">
        <div class="dash-modal-title">Customize dashboard</div>
        <button class="dash-btn" id="btnCloseCustomize" style="padding:4px 8px;">✕</button>
      </div>
      <div class="dash-modal-body" id="customizeList"></div>
      <div class="dash-modal-foot">
        <button class="dash-btn primary" id="btnCloseCustomize2">Done</button>
      </div>
    </div>
  </div>

  <script src="https://cdn.jsdelivr.net/npm/chart.js" is:inline></script>
  <script src="https://cdn.jsdelivr.net/npm/gridstack@10.3.1/dist/gridstack-all.js" is:inline></script>
  <script>
    const token = localStorage.getItem('token');
    const API = import.meta.env.PUBLIC_API_URL;
    const authH = { Authorization: `Bearer ${token}` };

