      const start = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-01`;
      const nx = new Date(now.getFullYear(), now.getMonth()+1, 1);
      const end = `${nx.getFullYear()}-${String(nx.getMonth()+1).padStart(2,'0')}-01`;
      return { start, end };
    }

    // ── shared fetches (cached so multiple widgets reuse one request) ──
    let _kpis, _summary;
    const getKpis = () => (_kpis ||= fetch(`${API}/api/analytics/dashboard-kpis`, { headers: authH }).then(r => r.ok ? r.json() : null).catch(() => null));
    const getSummary = () => {
      const { start, end } = monthRange();
      return (_summary ||= fetch(`${API}/api/analytics/month-summary?startDate=${start}&endDate=${end}`, { headers: authH }).then(r => r.ok ? r.json() : null).catch(() => null));
    };

    // ── widget registry: id → { render(el), load(el) } ──
    const WIDGETS = {
      'revenue-kpi': {
        render: () => `<div class="wg-eyebrow">Finance</div><div class="wg-title">Monthly Revenue</div><div class="wg-big" data-f="v">--</div><div class="wg-delta flat" data-f="d">Loading…</div>`,
        load: async (el) => { const d = await getKpis(); if (!d) return; el.querySelector('[data-f=v]').textContent = fmtVnd(d.monthlyRevenueVnd ?? 0);
          const de = el.querySelector('[data-f=d]'); const p = d.monthlyRevenueDeltaPct;
          if (p == null || Math.abs(p) > 999) { de.textContent = 'New month baseline'; de.className = 'wg-delta flat'; }
          else if (p >= 0) { de.textContent = `▲ ${p.toFixed(1)}% vs last month`; de.className = 'wg-delta up'; }
          else { de.textContent = `▼ ${Math.abs(p).toFixed(1)}% vs last month`; de.className = 'wg-delta down'; } },
      },
      'payroll-estimate': {
        render: () => `<div class="wg-eyebrow">Finance</div><div class="wg-title">Payroll Estimate</div><div class="wg-big" data-f="v">--</div><div class="wg-sub" data-f="s">&nbsp;</div>`,
        load: async (el) => { const d = await getKpis(); if (!d) return; el.querySelector('[data-f=v]').textContent = fmtVnd(d.payrollEstimateVnd ?? 0); if (d.payrollEstimatePeriodLabel) el.querySelector('[data-f=s]').textContent = d.payrollEstimatePeriodLabel; },
      },
      'active-clients': {
        render: () => `<div class="wg-eyebrow">Clients</div><div class="wg-title">Active Clients (30d)</div><div class="wg-big" data-f="v">--</div><div class="wg-sub">Distinct clients active in the last 30 days</div>`,
        load: async (el) => { const d = await getKpis(); if (d) el.querySelector('[data-f=v]').textContent = fmtInt(d.activeClients30d ?? 0); },
      },
      'classes-week': {
        render: () => `<div class="wg-eyebrow">Schedule</div><div class="wg-title">Classes This Week</div><div class="wg-big" data-f="v">--</div><div class="wg-sub">Scheduled classes this week</div>`,
        load: async (el) => { const d = await getKpis(); if (d) el.querySelector('[data-f=v]').textContent = fmtInt(d.classesThisWeek ?? 0); },
      },
      'occupancy': {
        render: () => `<div class="wg-eyebrow">Operations</div><div class="wg-title">Class Occupancy</div><div class="wg-big" data-f="v">--</div><div class="wg-sub">Average fill rate this month</div>`,
        load: async (el) => { const d = await getSummary(); if (d) el.querySelector('[data-f=v]').textContent = fmtPct(d.averageOccupancyPct ?? 0); },
      },
      'live-visitors': {
        render: () => `<div class="wg-eyebrow">Web</div><div class="wg-title"><span class="wg-live-dot"></span>Live Visitors</div><div class="wg-big" data-f="v">--</div><div class="wg-sub">Active on the site in the last 5 min</div>`,
        load: async (el) => {
          const hit = async () => { try { const r = await fetch(`${API}/api/track/visitors/live`, { headers: authH }); if (r.ok) { const d = await r.json(); el.querySelector('[data-f=v]').textContent = fmtInt(d.live ?? 0); } } catch {} };
          hit(); const t = setInterval(() => { if (document.visibilityState === 'visible') hit(); }, 20000); el._timer = t;
        },
      },
      'studio-pulse': {
        render: () => `<div class="wg-eyebrow">Operating notes</div><div class="wg-title">Studio Pulse</div><div class="wg-body"><div class="wg-pulse-grid">
          ${['Month Revenue|r','Packages Sold|p','New Clients|n','Projection|j','Classes Held|c','Merch Revenue|m'].map(x=>{const[l,k]=x.split('|');return `<div class="wg-pulse-cell"><div class="l">${l}</div><div class="v" data-k="${k}">--</div></div>`}).join('')}
        </div></div>`,
        load: async (el) => { const d = await getSummary(); if (!d) return; const s=(k,v)=>{const e=el.querySelector(`[data-k=${k}]`); if(e)e.textContent=v;};
          s('r',fmtVnd(d.totalRevenueVnd??0)); s('p',fmtInt(d.packagesSoldCount??0)); s('n',fmtInt(d.newClientsCount??0)); s('j',fmtVnd(d.monthlyProjectionVnd??0)); s('c',fmtInt(d.totalClassesHeld??0)); s('m',fmtVnd(d.merchandiseRevenueVnd??0)); },
      },
      'recent-invoices': {
        render: () => `<div class="wg-eyebrow">Live activity</div><div class="wg-title">Recent Invoices</div><div class="wg-body"><table class="wg-table"><thead><tr><th>Client</th><th>Date</th><th class="num">Amount</th></tr></thead><tbody data-f="b"><tr><td colspan="3" class="wg-muted">Loading…</td></tr></tbody></table></div>`,
        load: async (el) => { try { const r = await fetch(`${API}/api/invoice/recent?limit=6`, { headers: authH }); const inv = r.ok ? await r.json() : []; const b = el.querySelector('[data-f=b]');
          if (!inv?.length) { b.innerHTML = `<tr><td colspan="3" class="wg-muted">No invoices yet.</td></tr>`; return; }
          b.innerHTML = inv.map(i => `<tr><td>${esc(i.clientName)}</td><td>${new Date(i.issueDate).toLocaleDateString('en-US',{month:'short',day:'numeric'})}</td><td class="num">${fmtVnd(i.totalNet)}</td></tr>`).join(''); } catch {} },
      },
      'top-clients': {
        render: () => `<div class="wg-eyebrow">Operations</div><div class="wg-title">Top Clients</div><div class="wg-body"><table class="wg-table"><thead><tr><th>Client</th><th class="num">Revenue</th></tr></thead><tbody data-f="b"><tr><td colspan="2" class="wg-muted">Loading…</td></tr></tbody></table></div>`,
        load: async (el) => { const { start, end } = monthRange(); try { const r = await fetch(`${API}/api/analytics/top-clients?startDate=${start}&endDate=${end}&top=6`, { headers: authH }); const rows = r.ok ? await r.json() : []; const b = el.querySelector('[data-f=b]');
          if (!rows?.length) { b.innerHTML = `<tr><td colspan="2" class="wg-muted">No data this month.</td></tr>`; return; }
          b.innerHTML = rows.map(c => `<tr><td>${esc(c.fullName)}</td><td class="num">${fmtVnd(c.revenueVnd)}</td></tr>`).join(''); } catch {} },
      },
      'signup-source': {
        render: () => `<div class="wg-eyebrow">Acquisition</div><div class="wg-title">Sign-up Source</div><div class="wg-body"><table class="wg-table"><thead><tr><th>Source</th><th class="num">Customers</th><th class="num">Share</th></tr></thead><tbody data-f="b"><tr><td colspan="3" class="wg-muted">Loading…</td></tr></tbody></table></div>`,
        load: async (el) => { const { start, end } = monthRange(); try { const r = await fetch(`${API}/api/track/visitors/signup-sources?start=${start}&end=${end}`, { headers: authH }); const rows = r.ok ? await r.json() : []; const b = el.querySelector('[data-f=b]');
          if (!rows?.length) { b.innerHTML = `<tr><td colspan="3" class="wg-muted">No sign-ups this month.</td></tr>`; return; }
          b.innerHTML = rows.map(x => { const l = String(x.label||''); return `<tr><td>${esc(l.charAt(0).toUpperCase()+l.slice(1))}</td><td class="num">${fmtInt(x.visitors)}</td><td class="num">${x.percentage}%</td></tr>`; }).join(''); } catch {} },
      },
      'booking-funnel': {
        render: () => `<div class="wg-eyebrow">Conversion</div><div class="wg-title">Booking Funnel</div><div class="wg-body" data-f="b"><div class="wg-muted">Loading…</div></div>`,
        load: async (el) => { const { start, end } = monthRange(); try { const r = await fetch(`${API}/api/track/visitors/funnel?start=${start}&end=${end}`, { headers: authH }); const rows = r.ok ? await r.json() : []; const b = el.querySelector('[data-f=b]');
          if (!rows?.length || rows[0]?.sessions === 0) { b.innerHTML = `<div class="wg-muted">No funnel activity this month.</div>`; return; }
          b.innerHTML = rows.map(s => `<div class="wg-funnel-row"><div class="wg-funnel-bar-wrap"><div class="wg-funnel-bar" style="width:${Math.max(s.conversionFromStart,3)}%">${fmtInt(s.sessions)}</div></div><div class="wg-funnel-label">${esc(s.step)} · ${s.conversionFromStart}%</div></div>`).join(''); } catch {} },
      },
      'revenue-vs-expenses': {
        render: () => `<div class="wg-eyebrow">Finance trend</div><div class="wg-title">Revenue vs Expenses</div><div class="wg-body"><div class="wg-canvas-wrap"><canvas data-f="c"></canvas></div></div>`,
        load: async (el) => { try { const year = new Date().getFullYear(); const r = await fetch(`${API}/api/analytics/yearly-revenue-expense?year=${year}`, { headers: authH }); const rows = r.ok ? await r.json() : []; const ctx = el.querySelector('[data-f=c]').getContext('2d');
          if (el._chart) el._chart.destroy();
          el._chart = new Chart(ctx, { type: 'line', data: { labels: rows.map(x => x.monthLabel || x.month || ''), datasets: [
            { label: 'Revenue', data: rows.map(x => x.revenueVnd ?? 0), borderColor: css('--color-brand-accent') || '#db7d3c', backgroundColor: 'rgba(219,125,60,0.15)', fill: true, tension: 0.35 },
            { label: 'Expenses', data: rows.map(x => x.expensesVnd ?? 0), borderColor: '#4ea5d9', backgroundColor: 'rgba(78,165,217,0.12)', fill: true, tension: 0.35 } ] },
            options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { labels: { boxWidth: 12, font: { size: 10 } } } }, scales: { y: { ticks: { callback: v => (v/1e6).toFixed(0)+'M', font: { size: 9 } } }, x: { ticks: { font: { size: 9 } } } } } }); } catch {} },
      },
      'revenue-breakdown': {
        render: () => `<div class="wg-eyebrow">Sales mix</div><div class="wg-title">What's Driving Revenue</div><div class="wg-body"><div class="wg-canvas-wrap"><canvas data-f="c"></canvas></div></div>`,
        load: async (el) => { const { start, end } = monthRange(); try { const r = await fetch(`${API}/api/analytics/revenue-breakdown?startDate=${start}&endDate=${end}`, { headers: authH }); const d = r.ok ? await r.json() : null; if (!d) return; const ctx = el.querySelector('[data-f=c]').getContext('2d');
          if (el._chart) el._chart.destroy();
          el._chart = new Chart(ctx, { type: 'doughnut', data: { labels: ['Classes','Packages','Merch','Rentals'], datasets: [{ data: [d.singleClassRevenueVnd??0, d.packageRevenueVnd??0, d.merchandiseRevenueVnd??0, d.rentalRevenueVnd??0], backgroundColor: ['#db7d3c','#4ea5d9','#44be82','#9b59b6'] }] }, options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { position: 'bottom', labels: { boxWidth: 10, font: { size: 10 } } } } } }); } catch {} },
      },
    };

    // ── state ──
    let grid = null;
    let catalog = [];       // [{id,title,category,description,defaultW,defaultH,minW,minH}]
    let placements = [];    // [{widgetId,x,y,w,h}]
    const gridEl = document.getElementById('dashGrid');

    function widgetInner(id) {
      const w = WIDGETS[id];
      return `<button class="wg-remove" data-remove="${id}" title="Remove">✕</button>${w ? w.render() : `<div class="wg-muted">${esc(id)}</div>`}`;
    }

    function addWidgetToGrid(p) {
      const meta = catalog.find(c => c.id === p.widgetId) || {};
      const el = grid.addWidget({
        x: p.x, y: p.y, w: p.w || meta.defaultW || 4, h: p.h || meta.defaultH || 2,
        minW: meta.minW || 2, minH: meta.minH || 2,
        content: widgetInner(p.widgetId),
      });
      el.setAttribute('gs-widget-id', p.widgetId);
      const contentEl = el.querySelector('.grid-stack-item-content');
      const w = WIDGETS[p.widgetId];
      if (w && w.load) { try { w.load(contentEl); } catch (e) { console.warn('widget load failed', p.widgetId, e); } }
      return el;
    }

    function refreshEmptyState() {
      const has = grid && grid.engine.nodes.length > 0;
      document.getElementById('dashEmpty').style.display = has ? 'none' : 'block';
    }

    async function boot() {
      let data;
      try {
        const r = await fetch(`${API}/api/me/dashboard`, { headers: authH });
        if (!r.ok) throw new Error(`HTTP ${r.status}`);
        data = await r.json();
      } catch (e) {
        document.getElementById('dashEmpty').textContent = 'Failed to load your dashboard. Please refresh.';
        document.getElementById('dashEmpty').style.display = 'block';
        return;
      }
      catalog = data.catalog || [];
      placements = data.widgets || [];

      grid = GridStack.init({ column: 12, cellHeight: 90, margin: 8, float: false, disableDrag: true, disableResize: true, animate: true }, gridEl);

      placements.forEach(addWidgetToGrid);
      refreshEmptyState();
      buildCustomizeList();
      wireRemove();
    }

    // ── remove (edit mode) ──
    function wireRemove() {
      gridEl.addEventListener('click', (e) => {
        const btn = e.target.closest('[data-remove]');
        if (!btn || !document.body.classList.contains('dash-edit')) return;
        const item = btn.closest('.grid-stack-item');
        const id = btn.getAttribute('data-remove');
        grid.removeWidget(item);
        const cb = document.querySelector(`.dash-wg-toggle input[data-id="${id}"]`);
        if (cb) cb.checked = false;
        refreshEmptyState();
      });
    }

    // ── customize popup ──
    function buildCustomizeList() {
      const list = document.getElementById('customizeList');
      const cats = [...new Set(catalog.map(c => c.category))];
      list.innerHTML = cats.map(cat => {
        const items = catalog.filter(c => c.category === cat);
        return `<div class="dash-cat">${esc(cat)}</div>` + items.map(c => {
          const on = placements.some(p => p.widgetId === c.id);
          return `<div class="dash-wg-toggle"><div class="info"><div class="nm">${esc(c.title)}</div><div class="ds">${esc(c.description)}</div></div>
            <label class="dash-switch"><input type="checkbox" data-id="${c.id}" ${on ? 'checked' : ''}/><span class="track"></span></label></div>`;
        }).join('');
      }).join('');

      list.querySelectorAll('input[data-id]').forEach(cb => {
        cb.addEventListener('change', () => {
          const id = cb.getAttribute('data-id');
          const existing = gridEl.querySelector(`[gs-widget-id="${id}"]`);
          if (cb.checked && !existing) {
            const meta = catalog.find(c => c.id === id) || {};
            addWidgetToGrid({ widgetId: id, x: 0, y: 1000, w: meta.defaultW, h: meta.defaultH });
          } else if (!cb.checked && existing) {
            grid.removeWidget(existing);
          }
          refreshEmptyState();
          persist();
        });
      });
    }

    // ── persist ──
    function collectLayout() {
      return grid.engine.nodes.map(n => ({
        widgetId: n.el.getAttribute('gs-widget-id'),
        x: n.x, y: n.y, w: n.w, h: n.h,
      })).filter(p => p.widgetId);
    }
    async function persist() {
      const widgets = collectLayout();
      placements = widgets;
      try {
        await fetch(`${API}/api/me/dashboard`, {
          method: 'PUT', headers: { ...authH, 'Content-Type': 'application/json' },
          body: JSON.stringify({ widgets }),
        });
      } catch (e) { console.warn('save failed', e); }
    }

    // ── edit mode ──
    let editing = false;
    function setEdit(on) {
      editing = on;
      document.body.classList.toggle('dash-edit', on);
      grid.enableMove(on); grid.enableResize(on);
      document.getElementById('btnEdit').style.display = on ? 'none' : '';
      document.getElementById('btnSave').style.display = on ? '' : 'none';
    }

    // ── wire toolbar ──
    document.getElementById('btnCustomize').addEventListener('click', () => document.getElementById('customizeModal').classList.add('open'));
    document.getElementById('btnCloseCustomize').addEventListener('click', () => document.getElementById('customizeModal').classList.remove('open'));
    document.getElementById('btnCloseCustomize2').addEventListener('click', () => document.getElementById('customizeModal').classList.remove('open'));
    document.getElementById('customizeModal').addEventListener('click', (e) => { if (e.target.id === 'customizeModal') e.currentTarget.classList.remove('open'); });
    document.getElementById('btnEdit').addEventListener('click', () => setEdit(true));
    document.getElementById('btnSave').addEventListener('click', async () => { await persist(); setEdit(false); });

    boot();
  </script>
</AdminLayout>

toolUseResult.content:
---
import AdminLayout from '../../layouts/AdminLayout.astro';
---

<AdminLayout title="Dashboard" activePage="dashboard">
  <!-- Gridstack (drag/resize dashboard grid) -->
  <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/gridstack@10.3.1/dist/gridstack.min.css" />

  <style is:global>
    .dash-toolbar {
      display: flex; align-items: center; justify-content: space-between;
      gap: 12px; flex-wrap: wrap; margin-bottom: 14px;
    }
    .dash-toolbar-title { font-size: 22px; font-weight: 700; color: var(--color-text-primary); letter-spacing: -0.3px; }
    .dash-toolbar-actions { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
    .dash-btn {
      display: inline-flex; align-items: center; gap: 6px;
      padding: 8px 14px; font-size: 13px; font-weight: 600; cursor: pointer;
      border: 1px solid var(--color-border); border-radius: 8px;
      background: var(--color-surface); color: var(--color-text-primary);
      font-family: 'Inter', sans-serif; transition: all 0.12s;
    }
    .dash-btn:hover { border-color: var(--color-brand-accent); color: var(--color-brand-accent); }
    .dash-btn.primary { background: var(--color-brand-accent); color: #fff; border-color: var(--color-brand-accent); }
    .dash-btn svg { width: 15px; height: 15px; }
    .dash-editing-hint {
      font-size: 12px; color: var(--color-brand-accent); font-weight: 600;
      display: none;
    }
    body.dash-edit .dash-editing-hint { display: inline; }

    /* Gridstack container + items */
    .grid-stack { background: transparent; }
    .grid-stack-item-content {
      background: var(--color-surface);
      border: 1px solid var(--color-border-subtle);
      border-radius: 14px;
      overflow: auto;
      display: flex; flex-direction: column;
      padding: 16px 18px;
    }
    body.dash-edit .grid-stack-item-content {
      border-style: dashed; border-color: var(--color-brand-accent);
      cursor: move;
    }
    .wg-remove {
      position: absolute; top: 6px; right: 6px; z-index: 5;
      width: 24px; height: 24px; border-radius: 50%;
      border: none; background: rgba(239,68,68,0.9); color: #fff;
      font-size: 14px; line-height: 1; cursor: pointer; display: none;
      align-items: center; justify-content: center;
    }
    body.dash-edit .wg-remove { display: flex; }

    /* Widget internals */
    .wg-eyebrow { font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: .5px; color: var(--color-text-muted); }
    .wg-title { font-size: 13px; font-weight: 700; color: var(--color-text-primary); margin-top: 2px; }
    .wg-big { font-size: 30px; font-weight: 800; letter-spacing: -1px; color: var(--color-text-primary); margin-top: 6px; line-height: 1.05; }
    .wg-sub { font-size: 11px; color: var(--color-text-muted); margin-top: 4px; }
    .wg-delta { font-size: 12px; font-weight: 600; margin-top: 6px; }
    .wg-delta.up { color: #16a34a; } .wg-delta.down { color: #ef4444; } .wg-delta.flat { color: var(--color-text-muted); }
    .wg-body { flex: 1; min-height: 0; margin-top: 10px; }
    .wg-canvas-wrap { position: relative; height: 100%; min-height: 120px; }
    .wg-table { width: 100%; border-collapse: collapse; font-size: 12px; }
    .wg-table th { text-align: left; font-size: 10px; text-transform: uppercase; letter-spacing: .4px; color: var(--color-text-muted); padding: 6px 6px; border-bottom: 1px solid var(--color-border-subtle); }
    .wg-table td { padding: 7px 6px; border-bottom: 1px solid var(--color-border-subtle); color: var(--color-text-secondary); }
    .wg-table td.num, .wg-table th.num { text-align: right; }
    .wg-muted { color: var(--color-text-muted); font-size: 12px; padding: 8px 0; }
    .wg-live-dot { width: 8px; height: 8px; border-radius: 50%; background: #ef4444; display: inline-block; margin-right: 6px; animation: wgpulse 1.6s infinite; }
    @keyframes wgpulse { 0%{box-shadow:0 0 0 0 rgba(239,68,68,.5)} 70%{box-shadow:0 0 0 7px rgba(239,68,68,0)} 100%{box-shadow:0 0 0 0 rgba(239,68,68,0)} }
    .wg-pulse-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
    .wg-pulse-cell { background: var(--color-surface-raised, rgba(255,255,255,.03)); border-radius: 8px; padding: 8px 10px; }
    .wg-pulse-cell .l { font-size: 10px; color: var(--color-text-muted); text-transform: uppercase; letter-spacing: .3px; }
    .wg-pulse-cell .v { font-size: 16px; font-weight: 700; color: var(--color-text-primary); margin-top: 2px; }
    .wg-funnel-row { display: grid; grid-template-columns: 1fr auto; gap: 8px; align-items: center; margin-bottom: 6px; }
    .wg-funnel-bar-wrap { height: 22px; border-radius: 5px; background: rgba(128,128,128,.12); overflow: hidden; }
    .wg-funnel-bar { height: 100%; background: linear-gradient(90deg,#2BB7A3,#35c9b4); display: flex; align-items: center; padding-left: 8px; color: #fff; font-size: 11px; font-weight: 700; }
    .wg-funnel-label { font-size: 11px; color: var(--color-text-secondary); }

    /* Customize popup */
    .dash-modal-overlay {
      position: fixed; inset: 0; background: rgba(0,0,0,.5); z-index: 2000;
      display: none; align-items: center; justify-content: center; padding: 20px;
    }
    .dash-modal-overlay.open { display: flex; }
    .dash-modal {
      background: var(--color-surface); border: 1px solid var(--color-border);
      border-radius: 14px; width: 100%; max-width: 520px; max-height: 80vh;
      display: flex; flex-direction: column; overflow: hidden;
    }
    .dash-modal-head { padding: 16px 20px; border-bottom: 1px solid var(--color-border-subtle); display: flex; align-items: center; justify-content: space-between; }
    .dash-modal-title { font-size: 16px; font-weight: 700; color: var(--color-text-primary); }
    .dash-modal-body { padding: 8px 20px 16px; overflow-y: auto; }
    .dash-cat { font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: .5px; color: var(--color-text-muted); margin: 16px 0 6px; }
    .dash-wg-toggle { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 10px 0; border-bottom: 1px solid var(--color-border-subtle); }
    .dash-wg-toggle .info { min-width: 0; }
    .dash-wg-toggle .nm { font-size: 13px; font-weight: 600; color: var(--color-text-primary); }
    .dash-wg-toggle .ds { font-size: 11px; color: var(--color-text-muted); margin-top: 1px; }
    .dash-switch { position: relative; width: 40px; height: 22px; flex-shrink: 0; }
    .dash-switch input { opacity: 0; width: 0; height: 0; }
    .dash-switch .track { position: absolute; inset: 0; background: var(--color-border); border-radius: 22px; transition: .15s; cursor: pointer; }
    .dash-switch .track::before { content: ''; position: absolute; width: 16px; height: 16px; left: 3px; top: 3px; background: #fff; border-radius: 50%; transition: .15s; }
    .dash-switch input:checked + .track { background: var(--color-brand-accent); }
    .dash-switch input:checked + .track::before { transform: translateX(18px); }
    .dash-modal-foot { padding: 14px 20px; border-top: 1px solid var(--color-border-subtle); display: flex; justify-content: flex-end; gap: 8px; }
    .dash-empty { text-align: center; padding: 60px 20px; color: var(--color-text-muted); }
  </style>

  <!-- Toolbar -->
  <div class="dash-toolbar">
    <div class="dash-toolbar-title">Dashboard <span class="dash-editing-hint">· editing — drag & resize, then Save</span></div>
    <div class="dash-toolbar-actions">
      <button class="dash-btn" id="btnCustomize">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z"/></svg>
        Customize
      </button>
      <button class="dash-btn" id="btnEdit">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 20h9"/><path d="M16.5 3.5a2.12 2.12 0 0 1 3 3L7 19l-4 1 1-4Z"/></svg>
        Edit layout
      </button>
      <button class="dash-btn primary" id="btnSave" style="display:none;">Save</button>
    </div>
  </div>

  <div class="grid-stack" id="dashGrid"></div>
  <div class="dash-empty" id="dashEmpty" style="display:none;">
    No widgets to show. Click <strong>Customize</strong> to add metrics to your dashboard.
  </div>

  <!-- Customize popup -->
  <div class="dash-modal-overlay" id="customizeModal">
    <div class="dash-modal">
      <div class="dash-modal-head">
        <div class="dash-modal-title">Customize dashboard</div>
        <button class="dash-btn" id="btnCloseCustomize" style="padding:4px 8px;">✕</button>
      </div>
      <div class="dash-modal-body" id="customizeList"></div>
      <div class="dash-modal-foot">
        <button class="dash-btn primary" id="btnCloseCustomize2">Done</button>
      </div>
    </div>
  </div>

  <script src="https://cdn.jsdelivr.net/npm/chart.js" is:inline></script>
  <script src="https://cdn.jsdelivr.net/npm/gridstack@10.3.1/dist/gridstack-all.js" is:inline></script>
  <script>
    const token = localStorage.getItem('token');
    const API = import.meta.env.PUBLIC_API_URL;
    const authH = { Authorization: `Bearer ${token}` };

    // ── formatters ──
    const fmtVnd = (n) => `${Math.round(Number(n) || 0).toLocaleString('en-US')} VND`;
    const fmtInt = (n) => `${Math.round(Number(n) || 0).toLocaleString('en-US')}`;
    const fmtPct = (n) => `${Math.round((Number(n) || 0) * 100)}%`;
    const esc = (v) => String(v ?? '').replace(/[<>&"']/g, c => ({ '<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&#39;' }[c]));
    const css = (n) => getComputedStyle(document.documentElement).getPropertyValue(n).trim();
    function monthRange() {
      const now = new Date();
      const start = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-01`;
      const nx = new Date(now.getFullYear(), now.getMonth()+1, 1);
      const end = `${nx.getFullYear()}-${String(nx.getMonth()+1).padStart(2,'0')}-01`;
      return { start, end };
    }

    // ── shared fetches (cached so multiple widgets reuse one request) ──
    let _kpis, _summary;
    const getKpis = () => (_kpis ||= fetch(`${API}/api/analytics/dashboard-kpis`, { headers: authH }).then(r => r.ok ? r.json() : null).catch(() => null));
    const getSummary = () => {
      const { start, end } = monthRange();
      return (_summary ||= fetch(`${API}/api/analytics/month-summary?startDate=${start}&endDate=${end}`, { headers: authH }).then(r => r.ok ? r.json() : null).catch(() => null));
    };

    // ── widget registry: id → { render(el), load(el) } ──
    const WIDGETS = {
      'revenue-kpi': {
        render: () => `<div class="wg-eyebrow">Finance</div><div class="wg-title">Monthly Revenue</div><div class="wg-big" data-f="v">--</div><div class="wg-delta flat" data-f="d">Loading…</div>`,
        load: async (el) => { const d = await getKpis(); if (!d) return; el.querySelector('[data-f=v]').textContent = fmtVnd(d.monthlyRevenueVnd ?? 0);
          const de = el.querySelector('[data-f=d]'); const p = d.monthlyRevenueDeltaPct;
          if (p == null || Math.abs(p) > 999) { de.textContent = 'New month baseline'; de.className = 'wg-delta flat'; }
          else if (p >= 0) { de.textContent = `▲ ${p.toFixed(1)}% vs last month`; de.className = 'wg-delta up'; }
          else { de.textContent = `▼ ${Math.abs(p).toFixed(1)}% vs last month`; de.className = 'wg-delta down'; } },
      },
      'payroll-estimate': {
        render: () => `<div class="wg-eyebrow">Finance</div><div class="wg-title">Payroll Estimate</div><div class="wg-big" data-f="v">--</div><div class="wg-sub" data-f="s">&nbsp;</div>`,
        load: async (el) => { const d = await getKpis(); if (!d) return; el.querySelector('[data-f=v]').textContent = fmtVnd(d.payrollEstimateVnd ?? 0); if (d.payrollEstimatePeriodLabel) el.querySelector('[data-f=s]').textContent = d.payrollEstimatePeriodLabel; },
      },
      'active-clients': {
        render: () => `<div class="wg-eyebrow">Clients</div><div class="wg-title">Active Clients (30d)</div><div class="wg-big" data-f="v">--</div><div class="wg-sub">Distinct clients active in the last 30 days</div>`,
        load: async (el) => { const d = await getKpis(); if (d) el.querySelector('[data-f=v]').textContent = fmtInt(d.activeClients30d ?? 0); },
      },
      'classes-week': {
        render: () => `<div class="wg-eyebrow">Schedule</div><div class="wg-title">Classes This Week</div><div class="wg-big" data-f="v">--</div><div class="wg-sub">Scheduled classes this week</div>`,
        load: async (el) => { const d = await getKpis(); if (d) el.querySelector('[data-f=v]').textContent = fmtInt(d.classesThisWeek ?? 0); },
      },
      'occupancy': {
        render: () => `<div class="wg-eyebrow">Operations</div><div class="wg-title">Class Occupancy</div><div class="wg-big" data-f="v">--</div><div class="wg-sub">Average fill rate this month</div>`,
        load: async (el) => { const d = await getSummary(); if (d) el.querySelector('[data-f=v]').textContent = fmtPct(d.averageOccupancyPct ?? 0); },
      },
      'live-visitors': {
        render: () => `<div class="wg-eyebrow">Web</div><div class="wg-title"><span class="wg-live-dot"></span>Live Visitors</div><div class="wg-big" data-f="v">--</div><div class="wg-sub">Active on the site in the last 5 min</div>`,
        load: async (el) => {
          const hit = async () => { try { const r = await fetch(`${API}/api/track/visitors/live`, { headers: authH }); if (r.ok) { const d = await r.json(); el.querySelector('[data-f=v]').textContent = fmtInt(d.live ?? 0); } } catch {} };
          hit(); const t = setInterval(() => { if (document.visibilityState === 'visible') hit(); }, 20000); el._timer = t;
        },
      },
      'studio-pulse': {
        render: () => `<div class="wg-eyebrow">Operating notes</div><div class="wg-title">Studio Pulse</div><div class="wg-body"><div class="wg-pulse-grid">
          ${['Month Revenue|r','Packages Sold|p','New Clients|n','Projection|j','Classes Held|c','Merch Revenue|m'].map(x=>{const[l,k]=x.split('|');return `<div class="wg-pulse-cell"><div class="l">${l}</div><div class="v" data-k="${k}">--</div></div>`}).join('')}
        </div></div>`,
        load: async (el) => { const d = await getSummary(); if (!d) return; const s=(k,v)=>{const e=el.querySelector(`[data-k=${k}]`); if(e)e.textContent=v;};
          s('r',fmtVnd(d.totalRevenueVnd??0)); s('p',fmtInt(d.packagesSoldCount??0)); s('n',fmtInt(d.newClientsCount??0)); s('j',fmtVnd(d.monthlyProjectionVnd??0)); s('c',fmtInt(d.totalClassesHeld??0)); s('m',fmtVnd(d.merchandiseRevenueVnd??0)); },
      },
      'recent-invoices': {
        render: () => `<div class="wg-eyebrow">Live activity</div><div class="wg-title">Recent Invoices</div><div class="wg-body"><table class="wg-table"><thead><tr><th>Client</th><th>Date</th><th class="num">Amount</th></tr></thead><tbody data-f="b"><tr><td colspan="3" class="wg-muted">Loading…</td></tr></tbody></table></div>`,
        load: async (el) => { try { const r = await fetch(`${API}/api/invoice/recent?limit=6`, { headers: authH }); const inv = r.ok ? await r.json() : []; const b = el.querySelector('[data-f=b]');
          if (!inv?.length) { b.innerHTML = `<tr><td colspan="3" class="wg-muted">No invoices yet.</td></tr>`; return; }
          b.innerHTML = inv.map(i => `<tr><td>${esc(i.clientName)}</td><td>${new Date(i.issueDate).toLocaleDateString('en-US',{month:'short',day:'numeric'})}</td><td class="num">${fmtVnd(i.totalNet)}</td></tr>`).join(''); } catch {} },
      },
      'top-clients': {
        render: () => `<div class="wg-eyebrow">Operations</div><div class="wg-title">Top Clients</div><div class="wg-body"><table class="wg-table"><thead><tr><th>Client</th><th class="num">Revenue</th></tr></thead><tbody data-f="b"><tr><td colspan="2" class="wg-muted">Loading…</td></tr></tbody></table></div>`,
        load: async (el) => { const { start, end } = monthRange(); try { const r = await fetch(`${API}/api/analytics/top-clients?startDate=${start}&endDate=${end}&top=6`, { headers: authH }); const rows = r.ok ? await r.json() : []; const b = el.querySelector('[data-f=b]');
          if (!rows?.length) { b.innerHTML = `<tr><td colspan="2" class="wg-muted">No data this month.</td></tr>`; return; }
          b.innerHTML = rows.map(c => `<tr><td>${esc(c.fullName)}</td><td class="num">${fmtVnd(c.revenueVnd)}</td></tr>`).join(''); } catch {} },
      },
      'signup-source': {
        render: () => `<div class="wg-eyebrow">Acquisition</div><div class="wg-title">Sign-up Source</div><div class="wg-body"><table class="wg-table"><thead><tr><th>Source</th><th class="num">Customers</th><th class="num">Share</th></tr></thead><tbody data-f="b"><tr><td colspan="3" class="wg-muted">Loading…</td></tr></tbody></table></div>`,
        load: async (el) => { const { start, end } = monthRange(); try { const r = await fetch(`${API}/api/track/visitors/signup-sources?start=${start}&end=${end}`, { headers: authH }); const rows = r.ok ? await r.json() : []; const b = el.querySelector('[data-f=b]');
          if (!rows?.length) { b.innerHTML = `<tr><td colspan="3" class="wg-muted">No sign-ups this month.</td></tr>`; return; }
          b.innerHTML = rows.map(x => { const l = String(x.label||''); return `<tr><td>${esc(l.charAt(0).toUpperCase()+l.slice(1))}</td><td class="num">${fmtInt(x.visitors)}</td><td class="num">${x.percentage}%</td></tr>`; }).join(''); } catch {} },
      },
      'booking-funnel': {
        render: () => `<div class="wg-eyebrow">Conversion</div><div class="wg-title">Booking Funnel</div><div class="wg-body" data-f="b"><div class="wg-muted">Loading…</div></div>`,
        load: async (el) => { const { start, end } = monthRange(); try { const r = await fetch(`${API}/api/track/visitors/funnel?start=${start}&end=${end}`, { headers: authH }); const rows = r.ok ? await r.json() : []; const b = el.querySelector('[data-f=b]');
          if (!rows?.length || rows[0]?.sessions === 0) { b.innerHTML = `<div class="wg-muted">No funnel activity this month.</div>`; return; }
          b.innerHTML = rows.map(s => `<div class="wg-funnel-row"><div class="wg-funnel-bar-wrap"><div class="wg-funnel-bar" style="width:${Math.max(s.conversionFromStart,3)}%">${fmtInt(s.sessions)}</div></div><div class="wg-funnel-label">${esc(s.step)} · ${s.conversionFromStart}%</div></div>`).join(''); } catch {} },
      },
      'revenue-vs-expenses': {
        render: () => `<div class="wg-eyebrow">Finance trend</div><div class="wg-title">Revenue vs Expenses</div><div class="wg-body"><div class="wg-canvas-wrap"><canvas data-f="c"></canvas></div></div>`,
        load: async (el) => { try { const year = new Date().getFullYear(); const r = await fetch(`${API}/api/analytics/yearly-revenue-expense?year=${year}`, { headers: authH }); const rows = r.ok ? await r.json() : []; const ctx = el.querySelector('[data-f=c]').getContext('2d');
          if (el._chart) el._chart.destroy();
          el._chart = new Chart(ctx, { type: 'line', data: { labels: rows.map(x => x.monthLabel || x.month || ''), datasets: [
            { label: 'Revenue', data: rows.map(x => x.revenueVnd ?? 0), borderColor: css('--color-brand-accent') || '#db7d3c', backgroundColor: 'rgba(219,125,60,0.15)', fill: true, tension: 0.35 },
            { label: 'Expenses', data: rows.map(x => x.expensesVnd ?? 0), borderColor: '#4ea5d9', backgroundColor: 'rgba(78,165,217,0.12)', fill: true, tension: 0.35 } ] },
            options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { labels: { boxWidth: 12, font: { size: 10 } } } }, scales: { y: { ticks: { callback: v => (v/1e6).toFixed(0)+'M', font: { size: 9 } } }, x: { ticks: { font: { size: 9 } } } } } }); } catch {} },
      },
      'revenue-breakdown': {
        render: () => `<div class="wg-eyebrow">Sales mix</div><div class="wg-title">What's Driving Revenue</div><div class="wg-body"><div class="wg-canvas-wrap"><canvas data-f="c"></canvas></div></div>`,
        load: async (el) => { const { start, end } = monthRange(); try { const r = await fetch(`${API}/api/analytics/revenue-breakdown?startDate=${start}&endDate=${end}`, { headers: authH }); const d = r.ok ? await r.json() : null; if (!d) return; const ctx = el.querySelector('[data-f=c]').getContext('2d');
          if (el._chart) el._chart.destroy();
          el._chart = new Chart(ctx, { type: 'doughnut', data: { labels: ['Classes','Packages','Merch','Rentals'], datasets: [{ data: [d.singleClassRevenueVnd??0, d.packageRevenueVnd??0, d.merchandiseRevenueVnd??0, d.rentalRevenueVnd??0], backgroundColor: ['#db7d3c','#4ea5d9','#44be82','#9b59b6'] }] }, options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { position: 'bottom', labels: { boxWidth: 10, font: { size: 10 } } } } } }); } catch {} },
      },
    };

    // ── state ──
    let grid = null;
    let catalog = [];       // [{id,title,category,description,defaultW,defaultH,minW,minH}]
    let placements = [];    // [{widgetId,x,y,w,h}]
    const gridEl = document.getElementById('dashGrid');

    function widgetInner(id) {
      const w = WIDGETS[id];
      return `<button class="wg-remove" data-remove="${id}" title="Remove">✕</button>${w ? w.render() : `<div class="wg-muted">${esc(id)}</div>`}`;
    }

    function addWidgetToGrid(p) {
      const meta = catalog.find(c => c.id === p.widgetId) || {};
      const el = grid.addWidget({
        x: p.x, y: p.y, w: p.w || meta.defaultW || 4, h: p.h || meta.defaultH || 2,
        minW: meta.minW || 2, minH: meta.minH || 2,
        content: widgetInner(p.widgetId),
      });
      el.setAttribute('gs-widget-id', p.widgetId);
      const contentEl = el.querySelector('.grid-stack-item-content');
      const w = WIDGETS[p.widgetId];
      if (w && w.load) { try { w.load(contentEl); } catch (e) { console.warn('widget load failed', p.widgetId, e); } }
      return el;
    }

    function refreshEmptyState() {
      const has = grid && grid.engine.nodes.length > 0;
      document.getElementById('dashEmpty').style.display = has ? 'none' : 'block';
    }

    async function boot() {
      let data;
      try {
        const r = await fetch(`${API}/api/me/dashboard`, { headers: authH });
        if (!r.ok) throw new Error(`HTTP ${r.status}`);
        data = await r.json();
      } catch (e) {
        document.getElementById('dashEmpty').textContent = 'Failed to load your dashboard. Please refresh.';
        document.getElementById('dashEmpty').style.display = 'block';
        return;
      }
      catalog = data.catalog || [];
      placements = data.widgets || [];

      grid = GridStack.init({ column: 12, cellHeight: 90, margin: 8, float: false, disableDrag: true, disableResize: true, animate: true }, gridEl);

      placements.forEach(addWidgetToGrid);
      refreshEmptyState();
      buildCustomizeList();
      wireRemove();
    }

    // ── remove (edit mode) ──
    function wireRemove() {
      gridEl.addEventListener('click', (e) => {
        const btn = e.target.closest('[data-remove]');
        if (!btn || !document.body.classList.contains('dash-edit')) return;
        const item = btn.closest('.grid-stack-item');
        const id = btn.getAttribute('data-remove');
        grid.removeWidget(item);
        const cb = document.querySelector(`.dash-wg-toggle input[data-id="${id}"]`);
        if (cb) cb.checked = false;
        refreshEmptyState();
      });
    }

    // ── customize popup ──
    function buildCustomizeList() {
      const list = document.getElementById('customizeList');
      const cats = [...new Set(catalog.map(c => c.category))];
      list.innerHTML = cats.map(cat => {
        const items = catalog.filter(c => c.category === cat);
        return `<div class="dash-cat">${esc(cat)}</div>` + items.map(c => {
          const on = placements.some(p => p.widgetId === c.id);
          return `<div class="dash-wg-toggle"><div class="info"><div class="nm">${esc(c.title)}</div><div class="ds">${esc(c.description)}</div></div>
            <label class="dash-switch"><input type="checkbox" data-id="${c.id}" ${on ? 'checked' : ''}/><span class="track"></span></label></div>`;
        }).join('');
      }).join('');

      list.querySelectorAll('input[data-id]').forEach(cb => {
        cb.addEventListener('change', () => {
          const id = cb.getAttribute('data-id');
          const existing = gridEl.querySelector(`[gs-widget-id="${id}"]`);
          if (cb.checked && !existing) {
            const meta = catalog.find(c => c.id === id) || {};
            addWidgetToGrid({ widgetId: id, x: 0, y: 1000, w: meta.defaultW, h: meta.defaultH });
          } else if (!cb.checked && existing) {
            grid.removeWidget(existing);
          }
          refreshEmptyState();
          persist();
        });
      });
    }

    // ── persist ──
    function collectLayout() {
      return grid.engine.nodes.map(n => ({
        widgetId: n.el.getAttribute('gs-widget-id'),
        x: n.x, y: n.y, w: n.w, h: n.h,
      })).filter(p => p.widgetId);
    }
    async function persist() {
      const widgets = collectLayout();
      placements = widgets;
      try {
        await fetch(`${API}/api/me/dashboard`, {
          method: 'PUT', headers: { ...authH, 'Content-Type': 'application/json' },
          body: JSON.stringify({ widgets }),
        });
      } catch (e) { console.warn('save failed', e); }
    }

    // ── edit mode ──
    let editing = false;
    function setEdit(on) {
      editing = on;
      document.body.classList.toggle('dash-edit', on);
      grid.enableMove(on); grid.enableResize(on);
      document.getElementById('btnEdit').style.display = on ? 'none' : '';
      document.getElementById('btnSave').style.display = on ? '' : 'none';
    }

    // ── wire toolbar ──
    document.getElementById('btnCustomize').addEventListener('click', () => document.getElementById('customizeModal').classList.add('open'));
    document.getElementById('btnCloseCustomize').addEventListener('click', () => document.getElementById('customizeModal').classList.remove('open'));
    document.getElementById('btnCloseCustomize2').addEventListener('click', () => document.getElementById('customizeModal').classList.remove('open'));
    document.getElementById('customizeModal').addEventListener('click', (e) => { if (e.target.id === 'customizeModal') e.currentTarget.classList.remove('open'); });
    document.getElementById('btnEdit').addEventListener('click', () => setEdit(true));
    document.getElementById('btnSave').addEventListener('click', async () => { await persist(); setEdit(false); });

    boot();
  </script>
</AdminLayout>

