    .analytics-tab-panel {
      --c-revenue: var(--color-brand-accent, #c97b4b);
      --c-revenue-soft: rgba(201, 123, 75, 0.12);
      --c-ops: #2f8f9d;
      --c-ops-soft: rgba(47, 143, 157, 0.12);
      --c-customer: #7c6bb3;
