const calPage = document.getElementById('calPage');
const pwaView = document.getElementById('pwaListView');
if (calPage) calPage.style.display = 'none';
if (pwaView) pwaView.style.display = 'flex';

// The shared ClassDetailPanel + its modals render INSIDE calPage, which is
// now display:none — a hidden ancestor also hides the panel even though it
// is position:fixed when open. Relocate them to <body> so tapping a class
// opens the same full detail panel the desktop uses (attendees, add people,
// change instructor, cancel, per-attendee edits, etc.).
['cdpOverlay', 'cdpPanel', 'cdpEditModal', 'cdpCollectModal', 'cdpQuickAddClientModal']
  .forEach(id => { const el = document.getElementById(id); if (el) document.body.appendChild(el); });

// Reveal the floating action button.
const fab = document.getElementById('pwaFab');
if (fab) fab.style.display = 'block';

// ── FAB speed-dial ──
let fabOpen = false;
const fabMenu = document.getElementById('pwaFabMenu');
const fabBackdrop = document.getElementById('pwaFabBackdrop');
const fabIcon = document.getElementById('pwaFabIcon');
function setFab(open) {
  fabOpen = open;
  if (fabMenu) fabMenu.style.display = open ? 'flex' : 'none';
  if (fabBackdrop) fabBackdrop.style.display = open ? 'block' : 'none';
  if (fabIcon) fabIcon.style.transform = open ? 'rotate(45deg)' : 'none';
}
document.getElementById('pwaFabBtn')?.addEventListener('click', () => setFab(!fabOpen));
fabBackdrop?.addEventListener('click', () => setFab(false));
window.pwaFabAction = function (kind) {
  setFab(false);
  if (kind === 'session' && typeof window.openNewSession === 'function') window.openNewSession();
  else if (kind === 'block' && typeof window.openBlockModal === 'function') window.openBlockModal();
};

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));

