  /* Original v1 sin: a hard `height:calc(100vh - 112px)` combined with
     `overflow:hidden` on the cart card hid the totals and the Complete
     Sale button at common zoom levels and on 720p laptops. We now use
     min-height as a floor and let inner scrollers do the work, plus two
     media queries for tablet/short viewports. */
  .pos-layout {
    display: grid;
    grid-template-columns: 1fr 380px;
    gap: 16px;
    min-height: calc(100vh - var(--topbar-height) - 56px);
    align-items: stretch;
  }
  .pos-col {
    display: flex;
    flex-direction: column;
    gap: 12px;
    min-height: 0;
  }
  .pos-col-right {
    /* Right column wants to be exactly as tall as the viewport on wide
       screens so the cart can scroll inside it, but allow it to grow on
