input.new_string:
  /* Lift the calendar FAB above the bottom nav. */
  #pwaFabBtn {
    bottom: calc(var(--bottom-nav-height) + env(safe-area-inset-bottom, 0px) + 16px) !important;
  }
  #pwaFabMenu {
    bottom: calc(var(--bottom-nav-height) + env(safe-area-inset-bottom, 0px) + 80px) !important;
  }
  /* The FAB must never sit on top of an open modal (it covered the
     Create button). Hide it whenever any modal/overlay is open. */
  body:has(.modal-overlay.open) #pwaFab,
  body:has(.cdp-panel.open) #pwaFab,
  body:has(.cdp-drawer.open) #pwaFab {
    display: none !important;
  }

  /* ── Modals / bottom-sheets ──
     On mobile these are bottom-anchored sheets (align-items:flex-end,
     padding:0), so their footer buttons (Cancel / Create / Complete) sat
     behind the fixed nav. Lift the sheet to rest ABOVE the nav and cap its
     height so the footer is always reachable. Applies to every modal in the
     app since they share these classes. */
  .modal-overlay {
    padding-bottom: calc(var(--bottom-nav-height) + env(safe-area-inset-bottom, 0px)) !important;
  }
  .modal {
    max-height: calc(92vh - var(--bottom-nav-height) - env(safe-area-inset-bottom, 0px)) !important;
  }

  /* ── POS ──
     The cart card and product grid scroll inside fixed-height columns, so
     their content (incl. the Complete Sale button) extended under the nav.
     Cap the column heights and pad the scrollers so nothing hides behind it. */
  .pos-col-right,
  .pos-cart-card {
    max-height: calc(100vh - var(--topbar-height) - 72px - var(--bottom-nav-height) - env(safe-area-inset-bottom, 0px)) !important;
  }
  .pos-cart-card {
    padding-bottom: calc(var(--bottom-nav-height) + env(safe-area-inset-bottom, 0px)) !important;
  }
  .pos-product-grid,
  .pos-cal-scroll {
    padding-bottom: calc(var(--bottom-nav-height) + env(safe-area-inset-bottom, 0px)) !important;
  }

  /* ── Shared class-detail panel (fullscreen on mobile) ──
     Covers the nav (higher z-index) but still needs clearance for the
     home-indicator safe area at the very bottom of its scroll. */
  .cdp-panel .cdp-inner,
  .cdp-drawer {
    padding-bottom: calc(env(safe-area-inset-bottom, 0px) + 16px) !important;
  }
}

