1	@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');
2	
3	/* ═══════════════════════════════════════════════════════════════════
4	   Soul Pilates · Admin Dashboard
5	   ───────────────────────────────────────────────────────────────────
6	   Design language: warm copper accents on cream surfaces (light) or
7	   warm-charcoal surfaces (dark). Inter throughout.
8	   Tokens are split between a base palette and a [data-theme="dark"]
9	   override so the entire app gracefully switches on a single attr.
10	   ═══════════════════════════════════════════════════════════════════ */
11	
12	/* ─── Base (Warm Light) Tokens ──────────────────────────────────── */
13	:root {
14	  /* Brand — constant across modes */
15	  --color-brand-primary: #1f1813;
16	  --color-brand-accent: #db7d3c;
17	  --color-brand-accent-hover: #c56a2d;
18	  --color-brand-accent-soft: rgba(219, 125, 60, 0.10);
19	  --color-brand-accent-glow: rgba(219, 125, 60, 0.18);
20	  --color-brand-accent-strong: rgba(219, 125, 60, 0.28);
21	
22	  /* Surface */
23	  --color-bg: #f4f2ee;
24	  --color-surface: rgba(255, 255, 255, 0.92);
25	  --color-surface-raised: #f8f6f2;
26	  --color-surface-sunken: #ede9e2;
27	  --color-border: rgba(121, 97, 72, 0.14);
28	  --color-border-subtle: rgba(121, 97, 72, 0.08);
29	  --color-border-strong: rgba(121, 97, 72, 0.22);
30	
31	  /* Sidebar — warm charcoal, not navy */
32	  --color-sidebar-bg: #120d09;
33	  --color-sidebar-text: #b8aea4;
34	  --color-sidebar-text-active: #fff8f1;
35	  --color-sidebar-item-active: rgba(219, 125, 60, 0.18);
36	  --color-sidebar-item-hover: rgba(255, 255, 255, 0.04);
37	  --color-sidebar-border: rgba(255, 255, 255, 0.07);
38	
39	  /* Text */
40	  --color-text-primary: #1b1714;
41	  --color-text-secondary: #605751;
42	  --color-text-muted: #8f8379;
43	  --color-text-inverse: #FFFFFF;
44	
