@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');

/* ═══════════════════════════════════════════════════════════════════
   Soul Pilates · Admin Dashboard
   ───────────────────────────────────────────────────────────────────
   Design language: warm copper accents on cream surfaces (light) or
   warm-charcoal surfaces (dark). Inter throughout.
   Tokens are split between a base palette and a [data-theme="dark"]
   override so the entire app gracefully switches on a single attr.
   ═══════════════════════════════════════════════════════════════════ */

/* ─── Base (Warm Light) Tokens ──────────────────────────────────── */
:root {
  /* Brand — constant across modes */
  --color-brand-primary: #1f1813;
  --color-brand-accent: #db7d3c;
  --color-brand-accent-hover: #c56a2d;
  --color-brand-accent-soft: rgba(219, 125, 60, 0.10);
  --color-brand-accent-glow: rgba(219, 125, 60, 0.18);
  --color-brand-accent-strong: rgba(219, 125, 60, 0.28);

  /* Surface */
  --color-bg: #f4f2ee;
  --color-surface: rgba(255, 255, 255, 0.92);
  --color-surface-raised: #f8f6f2;
  --color-surface-sunken: #ede9e2;
  --color-border: rgba(121, 97, 72, 0.14);
  --color-border-subtle: rgba(121, 97, 72, 0.08);
  --color-border-strong: rgba(121, 97, 72, 0.22);

  /* Sidebar — warm charcoal, not navy */
  --color-sidebar-bg: #120d09;
  --color-sidebar-text: #b8aea4;
  --color-sidebar-text-active: #fff8f1;
  --color-sidebar-item-active: rgba(219, 125, 60, 0.18);
  --color-sidebar-item-hover: rgba(255, 255, 255, 0.04);
  --color-sidebar-border: rgba(255, 255, 255, 0.07);

  /* Text */
  --color-text-primary: #1b1714;
  --color-text-secondary: #605751;
  --color-text-muted: #8f8379;
  --color-text-inverse: #FFFFFF;

  /* Status — warm palette aligned with customer */
  --color-success: #3D8C5C;
  --color-success-soft: rgba(61, 140, 92, 0.10);
  --color-warning: #D4930D;
  --color-warning-soft: rgba(212, 147, 13, 0.10);
  --color-danger: #C44B4B;
  --color-danger-soft: rgba(196, 75, 75, 0.10);
  --color-info: #5C5C5C;
  --color-info-soft: rgba(92, 92, 92, 0.08);

  /* Level palette (mirrors customer) */
  --color-level-beginner: #6B7B3A;
  --color-level-beginner-soft: rgba(107, 123, 58, 0.10);
  --color-level-intermediate: #C97B4B;
  --color-level-intermediate-soft: rgba(201, 123, 75, 0.10);
  --color-level-advanced: #C44B4B;
  --color-level-advanced-soft: rgba(196, 75, 75, 0.10);
  --color-level-all: #5C5C5C;
  --color-level-all-soft: rgba(92, 92, 92, 0.08);

  /* Spacing (mirrors customer) */
  --space-xs: 4px;
  --space-sm: 8px;
  --space-md: 12px;
  --space-lg: 16px;
  --space-xl: 20px;
  --space-2xl: 24px;
  --space-3xl: 32px;
  --space-4xl: 48px;

  /* Radius */
  --radius-xs: 4px;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;
  --radius-xl: 20px;
  --radius-full: 999px;

  /* Shadows — warm-tinted */
  --shadow-xs: 0 1px 2px rgba(26, 20, 16, 0.05);
  --shadow-sm: 0 10px 24px rgba(33, 24, 18, 0.05);
  --shadow-md: 0 18px 40px rgba(33, 24, 18, 0.08);
  --shadow-lg: 0 28px 64px rgba(33, 24, 18, 0.12);
  --shadow-xl: 0 40px 90px rgba(33, 24, 18, 0.16);
  --shadow-card: 0 16px 40px rgba(33, 24, 18, 0.06), 0 0 0 1px rgba(26, 20, 16, 0.02);
  --shadow-card-hover: 0 24px 50px rgba(33, 24, 18, 0.10), 0 0 0 1px rgba(219, 125, 60, 0.14);
  --shadow-brand: 0 10px 24px rgba(219, 125, 60, 0.24);
  --shadow-brand-strong: 0 18px 40px rgba(219, 125, 60, 0.32);

  /* Sizing */
  --sidebar-width: 248px;
  --sidebar-collapsed-width: 68px;
  --topbar-height: 56px;
  --bottom-nav-height: 60px;

  /* Transitions */
  --transition-fast: 0.12s ease;
  --transition-base: 0.2s ease;
  --transition-smooth: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

/* ─── Dark Mode Override ────────────────────────────────────────── */
[data-theme="dark"] {
  --color-bg: #0d0907;
  --color-surface: rgba(31, 22, 17, 0.96);
  --color-surface-raised: #281d17;
  --color-surface-sunken: #17100d;
  --color-border: rgba(255, 244, 236, 0.15);
  --color-border-subtle: rgba(255, 244, 236, 0.10);
  --color-border-strong: rgba(255, 244, 236, 0.24);

  --color-sidebar-bg: #120d09;
  --color-sidebar-text: #d4c4b7;
  --color-sidebar-text-active: #fff5ec;
  --color-sidebar-item-active: rgba(219, 125, 60, 0.34);
  --color-sidebar-item-hover: rgba(255, 248, 241, 0.12);
  --color-sidebar-border: rgba(255, 244, 236, 0.10);

  --color-text-primary: #fff7f0;
  --color-text-secondary: #e8dbd1;
  --color-text-muted: #c5b4a6;
  --color-text-inverse: #17110d;

  --color-success: #5BA876;
  --color-success-soft: rgba(91, 168, 118, 0.16);
  --color-warning: #E5A82E;

