input.command:
cat >> /opt/soulpilates/SoulPilates.Astro/src/styles/global.css <<'EOF'

/* ═══════════════════════════════════════════════════════════════════
   PREMIUM REDESIGN LAYER (visual only)
   Elevates shared admin components — cards, buttons, inputs, tables,
   sidebar, topbar, badges — to a modern SaaS finish. No layout, data,
   or behaviour is changed; only surface, depth, colour and motion.
   ═══════════════════════════════════════════════════════════════════ */

/* ── Cards: layered surface + soft depth + refined hover ── */
.card {
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  border: 1px solid var(--color-border-subtle);
  transition: transform var(--transition-smooth), box-shadow var(--transition-smooth), border-color var(--transition-smooth);
  position: relative;
}
.card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-card-hover);
  border-color: var(--color-border);
}
/* faint top sheen for dimensionality */
.card::after {
  content: '';
  position: absolute; inset: 0;
  border-radius: inherit;
  background: var(--gradient-sheen);
  opacity: 0.5;
  pointer-events: none;
  mix-blend-mode: normal;
}
[data-theme="dark"] .card::after { opacity: 0.7; }

/* Dashboard widget tiles + KPI/stat cards share the premium treatment */
.grid-stack-item-content,
.kpi-card,
.kpi-stat,
.db-card,
.db-hero,
.db-kpi,
.db-pulse,
.analytics-grid > .card {
  box-shadow: var(--shadow-card);
  border: 1px solid var(--color-border-subtle);
  transition: transform var(--transition-smooth), box-shadow var(--transition-smooth), border-color var(--transition-smooth);
}
.grid-stack-item-content:hover,
.db-kpi:hover,
.db-pulse:hover,
.kpi-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-card-hover);
}

/* Hero / primary KPI cards get a subtle brand wash */
.db-hero {
  background: linear-gradient(135deg, var(--color-surface), var(--color-surface)) padding-box,
              var(--gradient-brand) border-box;
  border: 1px solid transparent;
  position: relative;
  overflow: hidden;
}
.db-hero::before {
  content: '';
  position: absolute; inset: 0;
  background: var(--gradient-brand-soft);
  pointer-events: none;
}

/* ── Buttons: premium gradient primary, elevated hover, focus ring ── */
.btn {
  border-radius: var(--radius-md);
  font-weight: 600;
  transition: transform var(--transition-fast), box-shadow var(--transition-base), background var(--transition-base), border-color var(--transition-base), color var(--transition-base);
  letter-spacing: -0.01em;
}
.btn:active { transform: translateY(1px); }
.btn-primary,
.btn.btn-primary {
  background: var(--gradient-brand);
  border: 1px solid rgba(0,0,0,0.04);
  color: #fff;
  box-shadow: var(--shadow-brand);
}
.btn-primary:hover,
.btn.btn-primary:hover {
  filter: brightness(1.04);
  transform: translateY(-1px);
  box-shadow: var(--shadow-brand-strong);
}
.btn-secondary,
.btn.btn-secondary {
  border: 1px solid var(--color-border);
  background: var(--color-surface);
}
.btn-secondary:hover,
.btn.btn-secondary:hover {
  border-color: var(--color-brand-accent);
  color: var(--color-brand-accent);
  transform: translateY(-1px);
  box-shadow: var(--shadow-sm);
}
.btn:focus-visible {
  outline: none;
  box-shadow: var(--shadow-ring-brand);
}

/* ── Inputs / selects: refined borders + brand focus ring ── */
.form-control,
.cal-filter-select,
.cg-filter-select,
input[type="text"], input[type="email"], input[type="number"],
input[type="search"], input[type="date"], input[type="datetime-local"],
input[type="time"], input[type="password"], select, textarea {
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  background: var(--color-surface);
  transition: border-color var(--transition-base), box-shadow var(--transition-base), background var(--transition-base);
}
.form-control:hover,
select:hover { border-color: var(--color-border-strong); }
.form-control:focus,
.cal-filter-select:focus,
.cg-filter-select:focus,
input:focus, select:focus, textarea:focus {
  outline: none;
  border-color: var(--color-brand-accent);
  box-shadow: var(--shadow-ring-brand);
}

/* ── Tables: airy rows, elegant hover + header ── */
.data-table thead th {
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-size: 10.5px;
  color: var(--color-text-muted);
  border-bottom: 1px solid var(--color-border);
}
.data-table tbody tr {
  transition: background var(--transition-fast);
}
.data-table tbody tr:hover {
  background: var(--color-brand-accent-soft);
}
.data-table tbody td {
  border-bottom: 1px solid var(--color-border-subtle);
}

/* ── Sidebar: premium active rail + smooth hover ── */
.sidebar { border-right: 1px solid var(--color-sidebar-border); }
.nav-item {
  border-radius: var(--radius-md);
  transition: background var(--transition-base), color var(--transition-base), transform var(--transition-fast);
  position: relative;
}
.nav-item:hover { transform: translateX(2px); }
.nav-item.active {
  background: var(--color-sidebar-item-active);
  color: var(--color-sidebar-text-active);
  font-weight: 600;
}
.nav-item.active::before {
  content: '';
  position: absolute;
  left: 0; top: 50%; transform: translateY(-50%);
  width: 3px; height: 62%;
  border-radius: 0 3px 3px 0;
  background: var(--gradient-brand);
  box-shadow: 0 0 12px rgba(249, 115, 22, 0.5);
}

/* ── Topbar: crisp, subtly translucent ── */
.topbar {
  border-bottom: 1px solid var(--color-border-subtle);
  backdrop-filter: saturate(1.2) blur(8px);
  background: color-mix(in srgb, var(--color-surface) 88%, transparent);
}

/* ── Badges: refined pills ── */
.badge {
  border-radius: var(--radius-full);
  font-weight: 600;
  letter-spacing: 0.01em;
  border: 1px solid transparent;
}

/* ── Modals: rounder + deeper elevation ── */
.modal {
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-xl);
  border: 1px solid var(--color-border-subtle);
}

/* ── Slim modern scrollbars ── */
* {
  scrollbar-width: thin;
  scrollbar-color: var(--color-border-strong) transparent;
}
*::-webkit-scrollbar { width: 10px; height: 10px; }
*::-webkit-scrollbar-thumb {
  background: var(--color-border-strong);
  border-radius: 999px;
  border: 3px solid transparent;
  background-clip: padding-box;
}
*::-webkit-scrollbar-thumb:hover { background: var(--color-brand-accent); background-clip: padding-box; }
*::-webkit-scrollbar-track { background: transparent; }
EOF
