/* ═══════════════════════════════════════════════════════════════════
   PREMIUM SYSTEM PASS v2 — full-surface visual unification
   Targets every shared component family across the admin so all pages
   speak one design language (per the provided mockup): gradient icon
   tiles, pill trend badges, filled active tabs, layered tables, premium
   modals/drawers, branded skeletons + empty states. Visual only.
   ═══════════════════════════════════════════════════════════════════ */

/* ── Global polish ── */
::selection { background: rgba(249,115,22,0.25); }
:focus-visible { outline: none; box-shadow: var(--shadow-ring-brand); border-radius: 4px; }
input[type="checkbox"], input[type="radio"] { accent-color: var(--color-brand-accent); }

/* ── Page titles: consistent premium hierarchy everywhere ── */
.cal-topbar-title, .dash-toolbar-title, .cg-topbar-title,
.page-title, .content-area h1 {
  font-size: 24px !important;
  font-weight: 700 !important;
  letter-spacing: -0.03em !important;
  line-height: 1.15 !important;
}
.card-title, .db-card-title, .wg-title, .dash-modal-title {
  letter-spacing: -0.015em;
  font-weight: 700;
}
.card-eyebrow, .db-card-eyebrow, .wg-eyebrow, .section-head-sub {
  letter-spacing: 0.07em;
  font-size: 10px;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--color-text-muted);
}

/* ── Icon tiles: orange gradient squares w/ glow (mockup language) ── */
.section-head-icon,
.db-kpi-icon,
.cal-empty-icon,
.ins-empty-icon,
.db-pulse-badge {
  background: var(--gradient-brand) !important;
  color: #fff !important;
  border-radius: 12px !important;
  box-shadow: 0 4px 14px rgba(249,115,22,0.35), inset 0 1px 0 rgba(255,255,255,0.25) !important;
  display: inline-flex; align-items: center; justify-content: center;
}
.section-head-icon svg, .cal-empty-icon svg, .ins-empty-icon svg { color: #fff !important; stroke: #fff; }

/* ── KPI / stat cards: layered, hoverable, numeric emphasis ── */
.kpi-stat, .db-kpi, .db-pulse, .db-op-chip, .wg-pulse-cell {
  border-radius: var(--radius-lg) !important;
  border: 1px solid var(--color-border-subtle) !important;
  background:
    linear-gradient(180deg, rgba(255,255,255,0.03), rgba(255,255,255,0)) padding-box,
    var(--color-surface-raised);
  transition: transform var(--transition-smooth), box-shadow var(--transition-smooth), border-color var(--transition-smooth);
}
.kpi-stat:hover, .db-kpi:hover, .db-pulse:hover, .db-op-chip:hover {
  transform: translateY(-2px);
  border-color: rgba(249,115,22,0.3) !important;
  box-shadow: var(--shadow-card-hover);
}
.kpi-value, .db-kpi-value, .db-pulse-value, .wg-big, .db-hero-value {
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.03em !important;
}

/* ── Trend / delta pills (▲ +12.5% style from mockup) ── */
.db-delta, .wg-delta {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 3px 9px; border-radius: 999px;
  font-size: 11px; font-weight: 700;
  width: fit-content;
}
.db-delta.up, .wg-delta.up   { background: var(--color-success-soft); color: var(--color-success); }
.db-delta.down, .wg-delta.down { background: var(--color-danger-soft);  color: var(--color-danger); }
.db-delta.flat, .wg-delta.flat { background: var(--color-surface-sunken); color: var(--color-text-muted); }

/* ── Tabs & segmented controls: filled brand-gradient actives ── */
.analytics-tab {
  border-radius: 10px 10px 0 0;
  transition: color var(--transition-base), background var(--transition-base);
}
.analytics-tab.active {
  background: var(--color-brand-accent-soft);
  color: var(--color-brand-accent) !important;
  box-shadow: inset 0 -2px 0 var(--color-brand-accent);
}
.cal-seg-btn.active, .cal-view-btn.active, .cg-seg-btn.active, .ic-seg-btn.active {
  background: var(--gradient-brand) !important;
  color: #fff !important;
  box-shadow: 0 2px 8px rgba(249,115,22,0.35);
}
.cal-seg, .cal-view-seg, .cg-seg, .ic-seg {
  border-radius: 10px !important;
  overflow: hidden;
  background: var(--color-surface-sunken);
  border: 1px solid var(--color-border-subtle) !important;
}

/* ── Tables: rounded containers, sticky refined headers, soft hover ── */
.table-wrap, .table-responsive {
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--color-surface);
}
.table-wrap .data-table, .table-responsive .data-table { border: none; }
.data-table thead th {
  background: var(--color-surface-raised);
  position: sticky; top: 0; z-index: 1;
}
.data-table tbody tr:last-child td { border-bottom: none; }

/* ── Status badges: soft pills with dot (mockup) ── */
.badge { padding: 3px 10px; font-size: 11px; }
.badge-success { background: var(--color-success-soft); color: var(--color-success); border-color: transparent; }
.badge-warning { background: var(--color-warning-soft); color: var(--color-warning); border-color: transparent; }
.badge-danger  { background: var(--color-danger-soft);  color: var(--color-danger);  border-color: transparent; }
.badge-default { background: var(--color-surface-sunken); color: var(--color-text-muted); border-color: transparent; }

/* ── Modals & drawers: deeper, rounder, header sheen ── */
.modal { overflow: hidden; }
.modal-header {
  background: linear-gradient(180deg, var(--color-surface-raised), var(--color-surface));
  border-bottom: 1px solid var(--color-border-subtle);
}
.modal-footer { border-top: 1px solid var(--color-border-subtle); background: var(--color-surface-raised); }
.cdp-drawer, .detail-drawer, .ins-drawer {
  border-radius: var(--radius-xl) 0 0 var(--radius-xl);
  box-shadow: -12px 0 48px rgba(0,0,0,0.28), 0 0 0 1px var(--color-border-subtle);
}

/* ── Skeletons: branded shimmer ── */
.cal-skeleton-row, .ins-skeleton-row, .skeleton {
  background: linear-gradient(90deg,
    var(--color-surface-sunken) 25%,
    rgba(249,115,22,0.07) 50%,
    var(--color-surface-sunken) 75%) !important;
  background-size: 200% 100% !important;
  border-radius: var(--radius-lg) !important;
}

/* ── Empty states: dashed premium card ── */
.cal-empty, .ins-empty, .dash-empty {
  border: 1.5px dashed var(--color-border);
  border-radius: var(--radius-xl);
  background: var(--color-surface-raised);
}

/* ── Danger buttons: ember gradient ── */
.btn-danger, .btn.btn-danger {
  background: var(--gradient-ember) !important;
  color: #fff !important;
  border: none !important;
  box-shadow: 0 6px 16px rgba(220,38,38,0.3);
}

/* ── Calendar event cards + class list cards: depth + hover lift ── */
.ev, .cal-card, .ins-class-card, .cg-ev {
  border-radius: 10px !important;
  transition: transform var(--transition-fast), box-shadow var(--transition-base), border-color var(--transition-base), filter var(--transition-fast);
}
.cal-card:hover, .ins-class-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-card-hover);
}

/* ── POS product tiles + cart: same card language ── */
.pos-product-grid > * {
  border-radius: var(--radius-lg) !important;
  transition: transform var(--transition-fast), box-shadow var(--transition-base), border-color var(--transition-base);
}
.pos-product-grid > *:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-card-hover);
}

/* ── Content breathing room ── */
.content-area { padding-top: var(--space-2xl); }
.analytics-grid { gap: 18px; }

/* ── Reduced motion: respect user preference ── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; animation: none !important; }
}
EOF
