=== revenue breakdown classification logic ===
    public async Task<RevenueBreakdownDto> GetRevenueBreakdownAsync(AnalyticsRangeQuery range)
    {
        if (range == null) throw new ArgumentNullException(nameof(range));

        var paidInvoices = await _invoices
            .Find(Builders<Invoice>.Filter.And(
                Builders<Invoice>.Filter.Eq(i => i.Status, "PAID"),
                Builders<Invoice>.Filter.Gte(i => i.IssueDate, range.StartDate),
                Builders<Invoice>.Filter.Lt(i => i.IssueDate, range.EndDate)))
            .ToListAsync();

        var distinctProductIds = paidInvoices
            .SelectMany(i => i.Lines.Select(l => l.ProductId))
            .Where(pid => !string.IsNullOrEmpty(pid))
            .Distinct()
            .ToList();

        var productsById = distinctProductIds.Count == 0
            ? new Dictionary<string, Product>()
            : (await _products
                .Find(Builders<Product>.Filter.In(p => p.Id, distinctProductIds))
                .ToListAsync())
                .Where(p => p.Id != null)
                .ToDictionary(p => p.Id!, p => p);

        decimal total = 0m, singleClass = 0m, package = 0m, merch = 0m, rental = 0m;

        foreach (var inv in paidInvoices)
        {
            total += inv.TotalNet;
            foreach (var line in inv.Lines)
            {
                var pt = line.ProductTypeSnapshot;
                if (string.IsNullOrEmpty(pt) && !string.IsNullOrEmpty(line.ProductId) && productsById.TryGetValue(line.ProductId, out var prod))
                    pt = prod.Type;

                switch (pt)
                {
                    case "PACKAGE": package += line.LineTotal; break;
                    case "MERCHANDISE": merch += line.LineTotal; break;
                    case "FREELANCE_PACKAGE":
                    case "FREELANCE_SINGLE":
                        rental += line.LineTotal;
                        break;
                    default:
                        singleClass += line.LineTotal;
                        break;
                }
            }
        }
        if (rental <= 0m)
            rental = Math.Max(0m, total - singleClass - package - merch);

        return new RevenueBreakdownDto
        {
            TotalRevenueVnd = total,
            SingleClassRevenueVnd = singleClass,
            PackageRevenueVnd = package,
            MerchandiseRevenueVnd = merch,
            RentalRevenueVnd = rental,
        };
