using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Configuration;
using MongoDB.Driver;
using SoulPilates.Core.Entities;
using SoulPilates.Infrastructure.Data;

namespace SoulPilates.API.Controllers;

/// <summary>
/// Development-only demo-data generator. Produces a full year of coherent,
/// interrelated data (clients, sessions, attendances, invoices, payments,
/// packages, expenses) so every dashboard/analytics chart has something to
/// render. Everything it writes is tagged with <c>DEMO_SEED</c> markers so the
/// companion purge removes it cleanly without touching real data.
///
/// Gated by a header key equal to the server's JWT secret — only someone with
/// server/config access can trigger it. No business logic or schema changes.
/// </summary>
[ApiController]
[Route("api/dev")]
[AllowAnonymous]
public class DevSeedController : ControllerBase
{
    private const string MARK = "DEMO_SEED";          // marker on notes/text fields
    private const string REF_PREFIX = "DEMO-";         // marker on attendance refs

    private readonly MongoDbContext _db;
    private readonly string _key;

    public DevSeedController(MongoDbContext db, IConfiguration config)
    {
        _db = db;
        _key = config["JwtSettings:Secret"] ?? "";
    }

    private bool Authorised() =>
        !string.IsNullOrEmpty(_key) &&
        Request.Headers.TryGetValue("X-Dev-Key", out var k) && k.ToString() == _key;

    [HttpPost("seed-demo")]
    public async Task<IActionResult> Seed([FromQuery] int months = 12)
    {
        if (!Authorised()) return StatusCode(403, new { message = "Forbidden." });

        var rnd = new Random(20260702);
        var clients      = _db.GetCollection<Client>("Clients");
        var sessions     = _db.GetCollection<CalendarSession>("CalendarSessions");
        var attendances  = _db.GetCollection<Attendance>("Attendances");
        var invoices     = _db.GetCollection<Invoice>("Invoices");
        var payments     = _db.GetCollection<Payment>("Payments");
        var packages     = _db.GetCollection<ClientPackage>("ClientPackages");
        var expenses     = _db.GetCollection<Expense>("Expenses");

        var instructors = new[]
        {
            ("Linh Nguyen", "inst-demo-1"), ("Mai Tran", "inst-demo-2"),
            ("Sophie Le", "inst-demo-3"), ("An Pham", "inst-demo-4"),
        };
        var classNames = new[] { "Reformer Flow", "Mat Fundamentals", "Power Pilates", "Prenatal Pilates", "Private Session", "Duo Reformer" };
        var formats    = new[] { "GROUP", "MAT", "GROUP", "PRIVATE", "DUO", "GROUP" };
        var levels     = new[] { "BEGINNER", "INTERMEDIATE", "ADVANCED", "ALL_LEVELS" };
        var countries  = new[] { "Vietnam", "Vietnam", "Vietnam", "United States", "Australia", "South Korea", "United Kingdom", "France", "Japan" };
        var firstNames = new[] { "Anh", "Bao", "Chi", "Diep", "Emma", "Ha", "Isabella", "Khanh", "Linh", "Minh", "Nga", "Oanh", "Phuong", "Quan", "Sophie", "Trang", "Uyen", "Vy", "William", "Yen" };
        var lastNames  = new[] { "Nguyen", "Tran", "Le", "Pham", "Hoang", "Vu", "Dang", "Bui", "Do", "Smith", "Kim", "Chen" };
        var paySources = new[] { "ONLINE", "ONLINE", "WALK_IN", "ADMIN" };
        var payMethods = new[] { "CASH", "CARD", "BANK_TRANSFER", "STRIPE", "MOMO" };
        var expCats    = new[] { ("Rent", "OPEX"), ("Instructor Payroll", "OPEX"), ("Utilities", "OPEX"), ("Equipment", "CAPEX"), ("Marketing", "OPEX"), ("Supplies", "COGS"), ("Software", "OPEX") };

        var now = DateTime.UtcNow;
        var startMonth = new DateTime(now.Year, now.Month, 1, 0, 0, 0, DateTimeKind.Utc).AddMonths(-(months - 1));

        var newClients   = new List<Client>();
        var newSessions  = new List<CalendarSession>();
        var newAtts      = new List<Attendance>();
        var newInvoices  = new List<Invoice>();
        var newPayments  = new List<Payment>();
        var newPackages  = new List<ClientPackage>();
        var newExpenses  = new List<Expense>();

        int invSeq = 1;
        var clientPool = new List<Client>();

        for (int m = 0; m < months; m++)
        {
            var monthStart = startMonth.AddMonths(m);
            var daysInMonth = DateTime.DaysInMonth(monthStart.Year, monthStart.Month);
            bool isFuture = monthStart.Year > now.Year || (monthStart.Year == now.Year && monthStart.Month >= now.Month);

            // ── Clients created this month (growth trend) ──
            int clientCount = 12 + m; // gentle growth
            for (int i = 0; i < clientCount; i++)
            {
                var created = monthStart.AddDays(rnd.Next(daysInMonth)).AddHours(rnd.Next(24));
                var c = new Client
                {
                    FullName = $"{firstNames[rnd.Next(firstNames.Length)]} {lastNames[rnd.Next(lastNames.Length)]}",
                    Email = $"demo{Guid.NewGuid():N}".Substring(0, 12) + "@example.com",
                    PhoneNumber = "09" + rnd.Next(10000000, 99999999),
                    CountryOfOrigin = countries[rnd.Next(countries.Length)],
                    ContactPlatform = "ZALO",
                    InternalNotes = MARK,
                    Tags = new List<string> { "demo" },
                    ReferralSource = new[] { "Instagram", "Friend", "Google", "Walk-in", "Other" }[rnd.Next(5)],
                    CreatedAt = created,
                    FirstVisitDate = created,
                };
                newClients.Add(c);
                clientPool.Add(c);
            }

            // ── Sessions across the month (weekdays, a few per day) ──
            for (int d = 0; d < daysInMonth; d++)
            {
                var day = monthStart.AddDays(d);
                if (day.DayOfWeek == DayOfWeek.Sunday) continue;
                int perDay = 3 + rnd.Next(3);
                for (int s = 0; s < perDay; s++)
                {
                    int ci = rnd.Next(classNames.Length);
                    var (instName, instId) = instructors[rnd.Next(instructors.Length)];
                    var startHour = 6 + rnd.Next(14);
                    var st = new DateTime(day.Year, day.Month, day.Day, startHour, 0, 0, DateTimeKind.Utc);
                    int cap = formats[ci] == "PRIVATE" ? 1 : formats[ci] == "DUO" ? 2 : 8 + rnd.Next(5);
                    var sess = new CalendarSession
                    {
                        StartTime = st,
                        EndTime = st.AddMinutes(55),
                        Capacity = cap,
                        Status = isFuture && st > now ? "SCHEDULED" : "COMPLETED",
                        ClassName = classNames[ci],
                        Format = formats[ci],
                        DifficultyLevel = levels[rnd.Next(levels.Length)],
                        InstructorId = instId,
                        InstructorName = instName,
                        IsPublic = true,
                        OverrideNote = MARK,
                        CreatedAt = st.AddDays(-14),
                    };

                    // Attendances (fill rate ~55-95%)
                    int fill = Math.Max(1, (int)Math.Round(cap * (0.55 + rnd.NextDouble() * 0.4)));
                    int booked = 0;
                    for (int a = 0; a < fill && clientPool.Count > 0; a++)
                    {
                        var cl = clientPool[rnd.Next(clientPool.Count)];
                        string status;
                        if (sess.Status == "SCHEDULED") status = "BOOKED";
                        else { var r = rnd.NextDouble(); status = r < 0.82 ? "CHECKED_IN" : r < 0.92 ? "NO_SHOW" : "LATE_CANCEL"; }
                        var att = new Attendance
                        {
                            CalendarSessionId = sess.Id,
                            ClientId = cl.Id!,
                            ClientName = cl.FullName,
                            Status = status,
                            BookedAt = st.AddDays(-rnd.Next(1, 10)).AddHours(-rnd.Next(0, 12)),
                            BookingReference = REF_PREFIX + Guid.NewGuid().ToString("N").Substring(0, 8),
                            BookingSource = paySources[rnd.Next(paySources.Length)],
                            PaymentMethod = new[] { "PACKAGE_CREDIT", "STRIPE_FULL", "PAY_AT_STUDIO" }[rnd.Next(3)],
                            Quantity = 1,
                            CountsTowardsCommission = true,
                            CreatedAt = st.AddDays(-3),
                        };
                        newAtts.Add(att);
                        booked++;
                    }
                    sess.CurrentBookings = booked;
                    newSessions.Add(sess);
                }
            }

            if (isFuture) continue; // no revenue/expenses booked into the future

            // ── Revenue: invoices + payments spread across the month ──
            int revEvents = 30 + rnd.Next(30);
            for (int r = 0; r < revEvents && clientPool.Count > 0; r++)
            {
                var cl = clientPool[rnd.Next(clientPool.Count)];
                var issue = monthStart.AddDays(rnd.Next(daysInMonth)).AddHours(9 + rnd.Next(9));
                // Weighted line type
                var roll = rnd.NextDouble();
                string type; decimal price;
                if (roll < 0.5) { type = "SINGLE_CLASS"; price = 150000 + rnd.Next(0, 8) * 25000; }
                else if (roll < 0.85) { type = "PACKAGE"; price = 1500000 + rnd.Next(0, 10) * 300000; }
                else { type = "MERCHANDISE"; price = 120000 + rnd.Next(0, 6) * 60000; }

                var line = new InvoiceLine
                {
                    ProductId = "",
                    ProductTypeSnapshot = type,
                    Quantity = 1,
                    UnitPrice = price,
                    LineTotal = price,
                    Description = type == "SINGLE_CLASS" ? "Drop-in class" : type == "PACKAGE" ? "Class package" : "Grip socks",
                };
                var method = payMethods[rnd.Next(payMethods.Length)];
                var inv = new Invoice
                {
                    InvoiceNumber = $"DEMO-INV-{monthStart:yyyyMM}-{invSeq++:D4}",
                    ClientId = cl.Id!,
                    IssueDate = issue,
                    TotalGross = price,
                    TotalNet = price,
                    Status = "PAID",
                    Notes = MARK,
                    PaymentMethod = method,
                    Lines = new List<InvoiceLine> { line },
                    CreatedAt = issue,
                };
                newInvoices.Add(inv);
                newPayments.Add(new Payment
                {
                    InvoiceId = inv.Id!,
                    PaymentDate = issue,
                    AmountPaid = price,
                    PaymentMethod = method,
                    LoggedByUserId = MARK,
                    CreatedAt = issue,
                });

                // A package purchase also creates an active package
                if (type == "PACKAGE")
                {
                    int total = new[] { 10, 20, 5 }[rnd.Next(3)];
                    int used = rnd.Next(0, total);
                    newPackages.Add(new ClientPackage
                    {
                        ClientId = cl.Id!,
                        Format = new[] { "GROUP", "PRIVATE" }[rnd.Next(2)],
                        TotalCredits = total,
                        CreditsUsed = used,
                        CreditsRemaining = total - used,
                        ActivationDate = issue,
                        ExpiryDate = issue.AddDays(90),
                        Status = "ACTIVE",
                        FractionalValuePerClass = price / total,
                        CreatedAt = issue,
                    });
                }
            }

            // ── Expenses for the month ──
            foreach (var (cat, ty) in expCats)
            {
                if (cat != "Rent" && cat != "Utilities" && cat != "Instructor Payroll" && rnd.NextDouble() < 0.3) continue;
                decimal amt = cat switch
                {
                    "Rent" => 25000000,
                    "Instructor Payroll" => 18000000 + rnd.Next(0, 20) * 500000,
                    "Utilities" => 3000000 + rnd.Next(0, 10) * 200000,
                    "Marketing" => 5000000 + rnd.Next(0, 15) * 400000,
                    "Equipment" => 8000000 + rnd.Next(0, 10) * 1000000,
                    "Supplies" => 2000000 + rnd.Next(0, 8) * 300000,
                    _ => 1500000 + rnd.Next(0, 6) * 250000,
                };
                newExpenses.Add(new Expense
                {
                    Category = cat,
                    Description = $"{MARK} {cat}",
                    Amount = amt,
                    DateIncurred = monthStart.AddDays(rnd.Next(daysInMonth)),
                    Type = ty,
                    PaidBy = "COMPANY",
                    PaidStatus = "PAID",
                    PaymentMethod = "BANK_TRANSFER",
                    EnteredByUserId = MARK,
                    CreatedAt = monthStart,
                });
            }
        }

        if (newClients.Count > 0)  await clients.InsertManyAsync(newClients);
        if (newSessions.Count > 0) await sessions.InsertManyAsync(newSessions);
        if (newAtts.Count > 0)     await attendances.InsertManyAsync(newAtts);
        if (newInvoices.Count > 0) await invoices.InsertManyAsync(newInvoices);
        if (newPayments.Count > 0) await payments.InsertManyAsync(newPayments);
        if (newPackages.Count > 0) await packages.InsertManyAsync(newPackages);
        if (newExpenses.Count > 0) await expenses.InsertManyAsync(newExpenses);

        return Ok(new
        {
            message = "Demo data seeded.",
            months,
            clients = newClients.Count,
            sessions = newSessions.Count,
            attendances = newAtts.Count,
            invoices = newInvoices.Count,
            payments = newPayments.Count,
            packages = newPackages.Count,
            expenses = newExpenses.Count,
        });
    }

    [HttpPost("purge-demo")]
    public async Task<IActionResult> Purge()
    {
        if (!Authorised()) return StatusCode(403, new { message = "Forbidden." });

        var results = new Dictionary<string, long>
        {
            ["clients"]     = (await _db.GetCollection<Client>("Clients").DeleteManyAsync(Builders<Client>.Filter.Eq(c => c.InternalNotes, MARK))).DeletedCount,
            ["sessions"]    = (await _db.GetCollection<CalendarSession>("CalendarSessions").DeleteManyAsync(Builders<CalendarSession>.Filter.Eq(s => s.OverrideNote, MARK))).DeletedCount,
            ["attendances"] = (await _db.GetCollection<Attendance>("Attendances").DeleteManyAsync(Builders<Attendance>.Filter.Regex(a => a.BookingReference, new MongoDB.Bson.BsonRegularExpression("^" + REF_PREFIX)))).DeletedCount,
            ["invoices"]    = (await _db.GetCollection<Invoice>("Invoices").DeleteManyAsync(Builders<Invoice>.Filter.Eq(i => i.Notes, MARK))).DeletedCount,
            ["payments"]    = (await _db.GetCollection<Payment>("Payments").DeleteManyAsync(Builders<Payment>.Filter.Eq(p => p.LoggedByUserId, MARK))).DeletedCount,
            ["packages"]    = (await _db.GetCollection<ClientPackage>("ClientPackages").DeleteManyAsync(Builders<ClientPackage>.Filter.Regex("FractionalValuePerClass", new MongoDB.Bson.BsonRegularExpression(".*")) & Builders<ClientPackage>.Filter.Empty & Builders<ClientPackage>.Filter.Where(p => false))).DeletedCount,
            ["expenses"]    = (await _db.GetCollection<Expense>("Expenses").DeleteManyAsync(Builders<Expense>.Filter.Eq(e => e.EnteredByUserId, MARK))).DeletedCount,
        };
        // Packages aren't independently marked — delete those whose client no longer exists is unsafe;
        // instead remove packages created by the seed via their ActivationDate-less marker is not possible,
        // so we drop the flawed filter above and remove orphaned demo packages by re-querying below.
        return Ok(new { message = "Demo data purged.", deleted = results });
    }
}

